/* fr.hamidullah — نور القرآن */
window.TRANS_FR={"surahs":[{"n":1,"name":"سُورَةُ ٱلْفَاتِحَةِ","ename":"Al-Faatiha"},{"n":2,"name":"سُورَةُ البَقَرَةِ","ename":"Al-Baqara"},{"n":3,"name":"سُورَةُ آلِ عِمۡرَانَ","ename":"Aal-i-Imraan"},{"n":4,"name":"سُورَةُ النِّسَاءِ","ename":"An-Nisaa"},{"n":5,"name":"سُورَةُ المَائـِدَةِ","ename":"Al-Maaida"},{"n":6,"name":"سُورَةُ الأَنۡعَامِ","ename":"Al-An'aam"},{"n":7,"name":"سُورَةُ الأَعۡرَافِ","ename":"Al-A'raaf"},{"n":8,"name":"سُورَةُ الأَنفَالِ","ename":"Al-Anfaal"},{"n":9,"name":"سُورَةُ التَّوۡبَةِ","ename":"At-Tawba"},{"n":10,"name":"سُورَةُ يُونُسَ","ename":"Yunus"},{"n":11,"name":"سُورَةُ هُودٍ","ename":"Hud"},{"n":12,"name":"سُورَةُ يُوسُفَ","ename":"Yusuf"},{"n":13,"name":"سُورَةُ الرَّعۡدِ","ename":"Ar-Ra'd"},{"n":14,"name":"سُورَةُ إِبۡرَاهِيمَ","ename":"Ibrahim"},{"n":15,"name":"سُورَةُ الحِجۡرِ","ename":"Al-Hijr"},{"n":16,"name":"سُورَةُ النَّحۡلِ","ename":"An-Nahl"},{"n":17,"name":"سُورَةُ الإِسۡرَاءِ","ename":"Al-Israa"},{"n":18,"name":"سُورَةُ الكَهۡفِ","ename":"Al-Kahf"},{"n":19,"name":"سُورَةُ مَرۡيَمَ","ename":"Maryam"},{"n":20,"name":"سُورَةُ طه","ename":"Taa-Haa"},{"n":21,"name":"سُورَةُ الأَنبِيَاءِ","ename":"Al-Anbiyaa"},{"n":22,"name":"سُورَةُ الحَجِّ","ename":"Al-Hajj"},{"n":23,"name":"سُورَةُ المُؤۡمِنُونَ","ename":"Al-Muminoon"},{"n":24,"name":"سُورَةُ النُّورِ","ename":"An-Noor"},{"n":25,"name":"سُورَةُ الفُرۡقَانِ","ename":"Al-Furqaan"},{"n":26,"name":"سُورَةُ الشُّعَرَاءِ","ename":"Ash-Shu'araa"},{"n":27,"name":"سُورَةُ النَّمۡلِ","ename":"An-Naml"},{"n":28,"name":"سُورَةُ القَصَصِ","ename":"Al-Qasas"},{"n":29,"name":"سُورَةُ العَنكَبُوتِ","ename":"Al-Ankaboot"},{"n":30,"name":"سُورَةُ الرُّومِ","ename":"Ar-Room"},{"n":31,"name":"سُورَةُ لُقۡمَانَ","ename":"Luqman"},{"n":32,"name":"سُورَةُ السَّجۡدَةِ","ename":"As-Sajda"},{"n":33,"name":"سُورَةُ الأَحۡزَابِ","ename":"Al-Ahzaab"},{"n":34,"name":"سُورَةُ سَبَإٍ","ename":"Saba"},{"n":35,"name":"سُورَةُ فَاطِرٍ","ename":"Faatir"},{"n":36,"name":"سُورَةُ يسٓ","ename":"Yaseen"},{"n":37,"name":"سُورَةُ الصَّافَّاتِ","ename":"As-Saaffaat"},{"n":38,"name":"سُورَةُ صٓ","ename":"Saad"},{"n":39,"name":"سُورَةُ الزُّمَرِ","ename":"Az-Zumar"},{"n":40,"name":"سُورَةُ غَافِرٍ","ename":"Ghafir"},{"n":41,"name":"سُورَةُ فُصِّلَتۡ","ename":"Fussilat"},{"n":42,"name":"سُورَةُ الشُّورَىٰ","ename":"Ash-Shura"},{"n":43,"name":"سُورَةُ الزُّخۡرُفِ","ename":"Az-Zukhruf"},{"n":44,"name":"سُورَةُ الدُّخَانِ","ename":"Ad-Dukhaan"},{"n":45,"name":"سُورَةُ الجَاثِيَةِ","ename":"Al-Jaathiya"},{"n":46,"name":"سُورَةُ الأَحۡقَافِ","ename":"Al-Ahqaf"},{"n":47,"name":"سُورَةُ مُحَمَّدٍ","ename":"Muhammad"},{"n":48,"name":"سُورَةُ الفَتۡحِ","ename":"Al-Fath"},{"n":49,"name":"سُورَةُ الحُجُرَاتِ","ename":"Al-Hujuraat"},{"n":50,"name":"سُورَةُ قٓ","ename":"Qaaf"},{"n":51,"name":"سُورَةُ الذَّارِيَاتِ","ename":"Adh-Dhaariyat"},{"n":52,"name":"سُورَةُ الطُّورِ","ename":"At-Tur"},{"n":53,"name":"سُورَةُ النَّجۡمِ","ename":"An-Najm"},{"n":54,"name":"سُورَةُ القَمَرِ","ename":"Al-Qamar"},{"n":55,"name":"سُورَةُ الرَّحۡمَٰن","ename":"Ar-Rahmaan"},{"n":56,"name":"سُورَةُ الوَاقِعَةِ","ename":"Al-Waaqia"},{"n":57,"name":"سُورَةُ الحَدِيدِ","ename":"Al-Hadid"},{"n":58,"name":"سُورَةُ المُجَادلَةِ","ename":"Al-Mujaadila"},{"n":59,"name":"سُورَةُ الحَشۡرِ","ename":"Al-Hashr"},{"n":60,"name":"سُورَةُ المُمۡتَحنَةِ","ename":"Al-Mumtahana"},{"n":61,"name":"سُورَةُ الصَّفِّ","ename":"As-Saff"},{"n":62,"name":"سُورَةُ الجُمُعَةِ","ename":"Al-Jumu'a"},{"n":63,"name":"سُورَةُ المُنَافِقُونَ","ename":"Al-Munaafiqoon"},{"n":64,"name":"سُورَةُ التَّغَابُنِ","ename":"At-Taghaabun"},{"n":65,"name":"سُورَةُ الطَّلَاقِ","ename":"At-Talaaq"},{"n":66,"name":"سُورَةُ التَّحۡرِيمِ","ename":"At-Tahrim"},{"n":67,"name":"سُورَةُ المُلۡكِ","ename":"Al-Mulk"},{"n":68,"name":"سُورَةُ القَلَمِ","ename":"Al-Qalam"},{"n":69,"name":"سُورَةُ الحَاقَّةِ","ename":"Al-Haaqqa"},{"n":70,"name":"سُورَةُ المَعَارِجِ","ename":"Al-Ma'aarij"},{"n":71,"name":"سُورَةُ نُوحٍ","ename":"Nooh"},{"n":72,"name":"سُورَةُ الجِنِّ","ename":"Al-Jinn"},{"n":73,"name":"سُورَةُ المُزَّمِّلِ","ename":"Al-Muzzammil"},{"n":74,"name":"سُورَةُ المُدَّثِّرِ","ename":"Al-Muddaththir"},{"n":75,"name":"سُورَةُ القِيَامَةِ","ename":"Al-Qiyaama"},{"n":76,"name":"سُورَةُ الإِنسَانِ","ename":"Al-Insaan"},{"n":77,"name":"سُورَةُ المُرۡسَلَاتِ","ename":"Al-Mursalaat"},{"n":78,"name":"سُورَةُ النَّبَإِ","ename":"An-Naba"},{"n":79,"name":"سُورَةُ النَّازِعَاتِ","ename":"An-Naazi'aat"},{"n":80,"name":"سُورَةُ عَبَسَ","ename":"Abasa"},{"n":81,"name":"سُورَةُ التَّكۡوِيرِ","ename":"At-Takwir"},{"n":82,"name":"سُورَةُ الانفِطَارِ","ename":"Al-Infitaar"},{"n":83,"name":"سُورَةُ المُطَفِّفِينَ","ename":"Al-Mutaffifin"},{"n":84,"name":"سُورَةُ الانشِقَاقِ","ename":"Al-Inshiqaaq"},{"n":85,"name":"سُورَةُ البُرُوجِ","ename":"Al-Burooj"},{"n":86,"name":"سُورَةُ الطَّارِقِ","ename":"At-Taariq"},{"n":87,"name":"سُورَةُ الأَعۡلَىٰ","ename":"Al-A'laa"},{"n":88,"name":"سُورَةُ الغَاشِيَةِ","ename":"Al-Ghaashiya"},{"n":89,"name":"سُورَةُ الفَجۡرِ","ename":"Al-Fajr"},{"n":90,"name":"سُورَةُ البَلَدِ","ename":"Al-Balad"},{"n":91,"name":"سُورَةُ الشَّمۡسِ","ename":"Ash-Shams"},{"n":92,"name":"سُورَةُ اللَّيۡلِ","ename":"Al-Lail"},{"n":93,"name":"سُورَةُ الضُّحَىٰ","ename":"Ad-Dhuhaa"},{"n":94,"name":"سُورَةُ الشَّرۡحِ","ename":"Ash-Sharh"},{"n":95,"name":"سُورَةُ التِّينِ","ename":"At-Tin"},{"n":96,"name":"سُورَةُ العَلَقِ","ename":"Al-Alaq"},{"n":97,"name":"سُورَةُ القَدۡرِ","ename":"Al-Qadr"},{"n":98,"name":"سُورَةُ البَيِّنَةِ","ename":"Al-Bayyina"},{"n":99,"name":"سُورَةُ الزَّلۡزَلَةِ","ename":"Az-Zalzala"},{"n":100,"name":"سُورَةُ العَادِيَاتِ","ename":"Al-Aadiyaat"},{"n":101,"name":"سُورَةُ القَارِعَةِ","ename":"Al-Qaari'a"},{"n":102,"name":"سُورَةُ التَّكَاثُرِ","ename":"At-Takaathur"},{"n":103,"name":"سُورَةُ العَصۡرِ","ename":"Al-Asr"},{"n":104,"name":"سُورَةُ الهُمَزَةِ","ename":"Al-Humaza"},{"n":105,"name":"سُورَةُ الفِيلِ","ename":"Al-Fil"},{"n":106,"name":"سُورَةُ قُرَيۡشٍ","ename":"Quraish"},{"n":107,"name":"سُورَةُ المَاعُونِ","ename":"Al-Maa'un"},{"n":108,"name":"سُورَةُ الكَوۡثَرِ","ename":"Al-Kawthar"},{"n":109,"name":"سُورَةُ الكَافِرُونَ","ename":"Al-Kaafiroon"},{"n":110,"name":"سُورَةُ النَّصۡرِ","ename":"An-Nasr"},{"n":111,"name":"سُورَةُ المَسَدِ","ename":"Al-Masad"},{"n":112,"name":"سُورَةُ الإِخۡلَاصِ","ename":"Al-Ikhlaas"},{"n":113,"name":"سُورَةُ الفَلَقِ","ename":"Al-Falaq"},{"n":114,"name":"سُورَةُ النَّاسِ","ename":"An-Naas"}],"ayahs":[{"n":1,"s":1,"a":1,"t":"Au nom d'Allah, le Tout Miséricordieux, le Très Miséricordieux."},{"n":2,"s":1,"a":2,"t":"Louange à Allah, Seigneur de l'univers."},{"n":3,"s":1,"a":3,"t":"Le Tout Miséricordieux, le Très Miséricordieux,"},{"n":4,"s":1,"a":4,"t":"Maître du Jour de la rétribution."},{"n":5,"s":1,"a":5,"t":"C'est Toi [Seul] que nous adorons, et c'est Toi [Seul] dont nous implorons secours."},{"n":6,"s":1,"a":6,"t":"Guide-nous dans le droit chemin,"},{"n":7,"s":1,"a":7,"t":"le chemin de ceux que Tu as comblés de faveurs, non pas de ceux qui ont encouru Ta colère, ni des égarés."},{"n":8,"s":2,"a":1,"t":"Alif, Lâm, Mim."},{"n":9,"s":2,"a":2,"t":"C'est le Livre au sujet duquel il n'y a aucun doute, c'est un guide pour les pieux,"},{"n":10,"s":2,"a":3,"t":"qui croient à l'invisible et accomplissent la Salât et dépensent (dans l'obéissance à Allah), de ce que Nous leur avons attribué,"},{"n":11,"s":2,"a":4,"t":"Ceux qui croient à ce qui t'a été descendu (révélé) et à ce qui a été descendu avant toi et qui croient fermement à la vie future."},{"n":12,"s":2,"a":5,"t":"Ceux-là sont sur le bon chemin de leur Seigneur, et ce sont eux qui réussissent (dans cette vie et dans la vie future)."},{"n":13,"s":2,"a":6,"t":"[Mais] certes les infidèles que tu les avertisses ou que tu ne les avertisses pas, ils ne croient pas."},{"n":14,"s":2,"a":7,"t":"Allah a scellé leurs cœurs et leurs oreilles; et un voile épais leur couvre la vue; et pour eux il y aura un grand châtiment."},{"n":15,"s":2,"a":8,"t":"Parmi les gens, il y a ceux qui disent: «Nous croyons en Allah et au Jour dernier!» tandis qu'en fait, ils n'y croient pas."},{"n":16,"s":2,"a":9,"t":"Ils cherchent à tromper Allah et les croyants; mais ils ne trompent qu'eux-mêmes, et ils ne s'en rendent pas compte."},{"n":17,"s":2,"a":10,"t":"Il y a dans leurs cœurs une maladie (de doute et d'hypocrisie), et Allah laisse croître leur maladie. Ils auront un châtiment douloureux, pour avoir menti."},{"n":18,"s":2,"a":11,"t":"Et quand on leur dit: «Ne semez pas la corruption sur la terre», ils disent: «Au contraire nous ne sommes que des réformateurs!»"},{"n":19,"s":2,"a":12,"t":"Certes, ce sont eux les véritables corrupteurs, mais ils ne s'en rendent pas compte."},{"n":20,"s":2,"a":13,"t":"Et quand on leur dit: «Croyez comme les gens ont cru», ils disent: «Croirons-nous comme ont cru les faibles d'esprit?» Certes, ce sont eux les véritables faibles d'esprit, mais ils ne le savent pas."},{"n":21,"s":2,"a":14,"t":"Quand ils rencontrent ceux qui ont cru, ils disent: «Nous croyons» mais quand ils se trouvent seuls avec leurs diables, ils disent: «Nous sommes avec vous; en effet nous ne faisions que nous moquer (d'eux)»."},{"n":22,"s":2,"a":15,"t":"C'est Allah qui Se moque d'eux et les endurcira dans leur révolte et prolongera sans fin leur égarement."},{"n":23,"s":2,"a":16,"t":"Ce sont eux qui ont troqué le droit chemin contre l'égarement. Eh bien, leur négoce n'a point profité. Et ils ne sont pas sur la bonne voie."},{"n":24,"s":2,"a":17,"t":"Ils ressemblent à quelqu'un qui a allumé un feu; puis quand le feu a illuminé tout à l'entour, Allah a fait disparaître leur lumière et les a abandonnés dans les ténèbres où ils ne voient plus rien."},{"n":25,"s":2,"a":18,"t":"Sourds, muets, aveugles, ils ne peuvent donc pas revenir (de leur égarement)."},{"n":26,"s":2,"a":19,"t":"(On peut encore les comparer à ces gens qui,) au moment où les nuées éclatent en pluies, chargées de ténèbres, de tonnerre et éclairs, se mettent les doigts dans les oreilles, terrorisés par le fracas de la foudre et craignant la mort; et Allah encercle de tous côtés les infidèles."},{"n":27,"s":2,"a":20,"t":"L'éclair presque leur emporte la vue: chaque fois qu'il leur donne de la lumière, ils avancent; mais dès qu'il fait obscur, ils s'arrêtent. Si Allah le voulait Il leur enlèverait certes l'ouïe et la vue, car Allah a pouvoir sur toute chose."},{"n":28,"s":2,"a":21,"t":"O hommes! Adorez votre Seigneur, qui vous a créés vous et ceux qui vous ont précédés. Ainsi atteindriez-vous à la piété."},{"n":29,"s":2,"a":22,"t":"C'est Lui qui vous a fait la terre pour lit, et le ciel pour toit; qui précipite la pluie du ciel et par elle fait surgir toutes sortes de fruits pour vous nourrir, ne Lui cherchez donc pas des égaux, alors que vous savez (tout cela)."},{"n":30,"s":2,"a":23,"t":"Si vous avez un doute sur ce que Nous avons révélé à Notre Serviteur, tâchez donc de produire une sourate semblable et appelez vos témoins, (les idoles) que vous adorez en dehors d'Allah, si vous êtes véridiques."},{"n":31,"s":2,"a":24,"t":"Si vous n'y parvenez pas et, à coup sûr, vous n'y parviendrez jamais, parez-vous donc contre le feu qu'alimenteront les hommes et les pierres, lequel est réservé aux infidèles."},{"n":32,"s":2,"a":25,"t":"Annonce à ceux qui croient et pratiquent de bonnes œuvres qu'ils auront pour demeures des jardins sous lesquels coulent les ruisseaux; chaque fois qu'ils seront gratifiés d'un fruit des jardins ils diront: «C'est bien là ce qui nous avait été servi auparavant». Or c'est quelque chose de semblable (seulement dans la forme); ils auront là des épouses pures, et là ils demeureront éternellement."},{"n":33,"s":2,"a":26,"t":"Certes, Allah ne se gêne point de citer en exemple n'importe quoi: un moustique ou quoi que ce soit au-dessus; quant aux croyants, ils savent bien qu'il s'agit de la vérité venant de la part de leur Seigneur; quant aux infidèles, ils se demandent «Qu'a voulu dire Allah par un tel exemple?» Par cela, nombreux sont ceux qu'Il égare et nombreux sont ceux qu'Il guide; mais Il n'égare par cela que les pervers,"},{"n":34,"s":2,"a":27,"t":"qui rompent le pacte qu'ils avaient fermement conclu avec Allah, coupent ce qu'Allah a ordonné d'unir, et sèment la corruption sur la terre. Ceux-là sont les vrais perdants."},{"n":35,"s":2,"a":28,"t":"Comment pouvez-vous renier Allah alors qu'Il vous a donné la vie, quand vous en étiez privés? Puis Il vous fera mourir; puis Il vous fera revivre et enfin c'est à Lui que vous retournerez."},{"n":36,"s":2,"a":29,"t":"C'est Lui qui a créé pour vous tout ce qui est sur la terre, puis Il a orienté Sa volonté vers le ciel et en fit sept cieux. Et Il est Omniscient."},{"n":37,"s":2,"a":30,"t":"Lorsque Ton Seigneur confia aux Anges: «Je vais établir sur la terre un vicaire «Khalifa». Ils dirent: «Vas-Tu y désigner un qui y mettra le désordre et répandra le sang, quand nous sommes là à Te sanctifier et à Te glorifier?» - Il dit: «En vérité, Je sais ce que vous ne savez pas!»."},{"n":38,"s":2,"a":31,"t":"Et Il apprit à Adam tous les noms (de toutes choses), puis Il les présenta aux Anges et dit: «Informez-Moi des noms de ceux-là, si vous êtes véridiques!» (dans votre prétention que vous êtes plus méritants qu'Adam)."},{"n":39,"s":2,"a":32,"t":"- Ils dirent: «Gloire à Toi! Nous n'avons de savoir que ce que Tu nous a appris. Certes c'est Toi l'Omniscient, le Sage»."},{"n":40,"s":2,"a":33,"t":"Il dit: «O Adam, informe-les de ces noms ;» Puis quand celui-ci les eut informés de ces noms, Allah dit: «Ne vous ai-Je pas dit que Je connais les mystères des cieux et de la terre, et que Je sais ce que vous divulguez et ce que vous cachez?»"},{"n":41,"s":2,"a":34,"t":"Et lorsque Nous demandâmes aux Anges de se prosterner devant Adam, ils se prosternèrent à l'exception d'Iblis qui refusa, s'enfla d'orgueil et fut parmi les infidèles."},{"n":42,"s":2,"a":35,"t":"Et Nous dîmes: «O Adam, habite le Paradis toi et ton épouse, et nourrissez-vous-en de partout à votre guise; mais n'approchez pas de l'arbre que voici: sinon vous seriez du nombre des injustes»."},{"n":43,"s":2,"a":36,"t":"Peu de temps après, Satan les fit glisser de là et les fit sortir du lieu où ils étaient. Et Nous dîmes: «Descendez (du Paradis); ennemis les uns des autres. Et pour vous il y aura une demeure sur la terre, et un usufruit pour un temps."},{"n":44,"s":2,"a":37,"t":"Puis Adam reçut de son Seigneur des paroles, et Allah agréa son repentir car c'est Lui certes, le Repentant, le Miséricordieux."},{"n":45,"s":2,"a":38,"t":"- Nous dîmes: «Descendez d'ici, vous tous! Toutes les fois que Je vous enverrai un guide, ceux qui [le] suivront n'auront rien à craindre et ne seront point affligés»."},{"n":46,"s":2,"a":39,"t":"Et ceux qui ne croient pas (à nos messagers) et traitent de mensonge Nos révélations, ceux-là sont les gens du Feu où ils demeureront éternellement."},{"n":47,"s":2,"a":40,"t":"O enfants d'Israël, rappelez-vous Mon bienfait dont Je vous ai comblés. Si vous tenez vos engagements vis-à-vis de Moi, Je tiendrai les miens. Et c'est Moi que vous devez redouter."},{"n":48,"s":2,"a":41,"t":"Et croyez à ce que J'ai fait descendre, en confirmation de ce qui était déjà avec vous; et ne soyez pas les premiers à le rejeter. Et n'échangez pas Mes révélations contre un vil prix. Et c'est Moi que vous devez craindre."},{"n":49,"s":2,"a":42,"t":"Et ne mêlez pas le faux à la vérité. Ne cachez pas sciemment la vérité."},{"n":50,"s":2,"a":43,"t":"Et accomplissez la Salât, et acquittez la Zakât, et inclinez-vous avec ceux qui s'inclinent."},{"n":51,"s":2,"a":44,"t":"Commanderez-vous aux gens de faire le bien, et vous oubliez vous-mêmes de le faire, alors que vous récitez le Livre? Etes-vous donc dépourvus de raison?"},{"n":52,"s":2,"a":45,"t":"Et cherchez secours dans l'endurance et la salât: certes, la Salât est une lourde obligation, sauf pour les humbles,"},{"n":53,"s":2,"a":46,"t":"qui ont la certitude de rencontrer leur Seigneur (après leur résurrection) et retourner à Lui seul."},{"n":54,"s":2,"a":47,"t":"O Enfants d'Israël, rappelez-vous Mon bienfait dont Je vous ai comblés, (Rappelez-vous) que Je vous ai préférés à tous les peuples (de l'époque)."},{"n":55,"s":2,"a":48,"t":"Et redoutez le jour où nulle âme ne suffira en quoi que ce soit à une autre; où l'on n'acceptera d'elle aucune intercession; et où on ne recevra d'elle aucune compensation. Et ils ne seront point secourus."},{"n":56,"s":2,"a":49,"t":"Et [rappelez-vous] lorsque Nous vous avons délivrés des gens de Pharaon; qui vous infligeaient le pire châtiment: en égorgeant vos fils et épargnant vos femmes. C'était là une grande épreuve de la part de votre Seigneur."},{"n":57,"s":2,"a":50,"t":"Et [rappelez-vous] lorsque Nous avons fendu la mer pour vous donner passage!... Nous vous avons donc délivrés, et noyé les gens de Pharaon, tandis que vous regardiez."},{"n":58,"s":2,"a":51,"t":"Et [rappelez-vous] lorsque Nous donnâmes rendez-vous à Moïse pendant quarante nuits!... Puis en son absence vous avez pris le Veau pour idole alors que vous étiez injustes (à l'égard de vous-mêmes en adorant autre qu'Allah)."},{"n":59,"s":2,"a":52,"t":"Mais en dépit de cela Nous vous pardonnâmes, afin que vous reconnaissiez (Nos bienfaits à votre égard)."},{"n":60,"s":2,"a":53,"t":"Et [rappelez-vous] lorsque Nous avons donné à Moïse le Livre et le Discernement afin que vous soyez guidés."},{"n":61,"s":2,"a":54,"t":"Et [rappelez-vous] lorsque Moïse dit à son peuple: «O mon peuple, certes vous vous êtes fait du tort à vous-mêmes en prenant le Veau pour idole. Revenez donc à votre Créateur; puis, tuez donc les coupables vous-mêmes: ce serait mieux pour vous, auprès de votre Créateur!»... C'est ainsi qu'Il agréa votre repentir; car c'est Lui, certes, le Repentant et le Miséricordieux!"},{"n":62,"s":2,"a":55,"t":"Et [rappelez-vous] lorsque vous dites: «O Moïse, nous ne te croirons qu'après avoir vu Allah clairement»!... Alors la foudre vous saisit tandis que vous regardiez."},{"n":63,"s":2,"a":56,"t":"Puis Nous vous ressuscitâmes après votre mort afin que vous soyez reconnaissants."},{"n":64,"s":2,"a":57,"t":"Et Nous vous couvrîmes de l'ombre d'un nuage; et fîmes descendre sur vous la manne et les cailles: - «Mangez des délices que Nous vous avons attribués!» - Ce n'est pas à Nous qu'ils firent du tort, mais ils se firent tort à eux-mêmes."},{"n":65,"s":2,"a":58,"t":"Et [rappelez-vous] lorsque Nous dîmes: «Entrez dans cette ville, et mangez-y à l'envie où il vous plaira; mais entrez par la porte en vous prosternant et demandez la «rémission» (de vos péchés); Nous vous pardonnerons vos fautes si vous faites cela et donnerons davantage de récompense pour les bienfaisants."},{"n":66,"s":2,"a":59,"t":"Mais, à ces paroles, les pervers en substituèrent d'autres, et pour les punir de leur fourberie Nous leur envoyâmes du ciel un châtiment avilissant."},{"n":67,"s":2,"a":60,"t":"Et [rappelez-vous] quand Moïse demanda de l'eau pour désaltérer son peuple, c'est alors que Nous dîmes: «Frappe le rocher avec ton bâton». Et tout d'un coup, douze sources en jaillirent, et certes, chaque tribu sut où s'abreuver! - «Mangez et buvez de ce qu'Allah vous accorde; et ne semez pas de troubles sur la terre comme des fauteurs de désordre»."},{"n":68,"s":2,"a":61,"t":"Et [rappelez-vous] quand vous dîtes: «O Moïse, nous ne pouvons plus tolérer une seule nourriture. Prie donc ton Seigneur pour qu'Il nous fasse sortir de la terre ce qu'elle fait pousser, de ses légumes, ses concombres, son ail (ou blé), ses lentilles et ses oignons!» - Il vous répondit: «Voulez-vous échanger le meilleur pour le moins bon? Descendez donc à n'importe quelle ville; vous y trouverez certainement ce que vous demandez!». L'avilissement et la misère s'abattirent sur eux; ils encoururent la colère d'Allah. Cela est parce qu'ils reniaient les révélations d'Allah, et qu'ils tuaient sans droit les prophètes. Cela parce qu'ils désobéissaient et transgressaient."},{"n":69,"s":2,"a":62,"t":"Certes, ceux qui ont cru, ceux qui se sont judaïsés, les Nazaréens, et les sabéens, quiconque d'entre eux a cru en Allah au Jour dernier et accompli de bonnes œuvres, sera récompensé par son Seigneur; il n'éprouvera aucune crainte et il ne sera jamais affligé."},{"n":70,"s":2,"a":63,"t":"(Et rappelez-vous) quand Nous avons contracté un engagement avec vous et brandi sur vous le Mont -: «Tenez ferme ce que Nous vous avons donné et souvenez-vous de ce qui s'y trouve afin que vous soyez pieux!»"},{"n":71,"s":2,"a":64,"t":"Puis vous vous en détournâtes après vos engagements, n'eût été donc la grâce d'Allah et Sa miséricorde, vous seriez certes parmi les perdants."},{"n":72,"s":2,"a":65,"t":"Vous avez certainement connu ceux des vôtres qui transgressèrent le Sabbat. Et bien Nous leur dîmes: «Soyez des singes abjects!»"},{"n":73,"s":2,"a":66,"t":"Nous fîmes donc de cela un exemple pour les villes qui l'entouraient alors et une exhortation pour les pieux."},{"n":74,"s":2,"a":67,"t":"(Et rappelez-vous) lorsque Moïse dit à son peuple: «Certes Allah vous ordonne d'immoler une vache». Ils dirent: «Nous prends-tu en moquerie?» «Qu'Allah me garde d'être du nombre des ignorants» dit-il."},{"n":75,"s":2,"a":68,"t":"- Ils dirent: «Demande pour nous à ton Seigneur qu'Il nous précise ce qu'elle doit être». - Il dit: «Certes Allah dit que c'est bien une vache, ni vieille ni vierge, d'un âge moyen, entre les deux. Faites donc ce qu'on vous commande»."},{"n":76,"s":2,"a":69,"t":"- Ils dirent: «Demande donc pour nous à ton Seigneur qu'Il nous précise sa couleur». - Il dit: «Allah dit que c'est une vache jaune, de couleur vive et plaisante à voir»."},{"n":77,"s":2,"a":70,"t":"- Ils dirent: «Demande pour nous à ton Seigneur qu'Il nous précise ce qu'elle est car pour nous, les vaches se confondent. Mais, nous y serions certainement bien guidés, si Allah le veut»."},{"n":78,"s":2,"a":71,"t":"- Il dit: «Allah dit que c'est bien une vache qui n'a pas été asservie à labourer la terre ni à arroser le champ, indemne d'infirmité et dont la couleur est unie». - Ils dirent: «Te voilà enfin, tu nous as apporté la vérité!» Ils l'immolèrent alors mais il s'en fallut qu'ils ne l'eussent pas fait."},{"n":79,"s":2,"a":72,"t":"Et quand vous aviez tué un homme et que chacun de vous cherchait à se disculper!... Mais Allah démasque ce que vous dissimuliez."},{"n":80,"s":2,"a":73,"t":"Nous dîmes donc: «Frappez le tué avec une partie de la vache». - Ainsi Allah ressuscite les morts et vous montre les signes (de Sa puissance) afin que vous raisonniez"},{"n":81,"s":2,"a":74,"t":"Puis, et en dépit de tout cela, vos cœurs se sont endurcis; ils sont devenus comme des pierres ou même plus durs encore; car il y a des pierres d'où jaillissent les ruisseaux, d'autres se fendent pour qu'en surgisse l'eau, d'autres s'affaissent par crainte d'Allah. Et Allah n'est certainement jamais inattentif à ce que vous faites"},{"n":82,"s":2,"a":75,"t":"- Eh bien, espérez-vous [Musulmans] que des pareils gens (les Juifs) vous partageront la foi? alors qu'un groupe d'entre eux; après avoir entendu et compris la parole d'Allah, la falsifièrent sciemment."},{"n":83,"s":2,"a":76,"t":"Et quand ils rencontrent des croyants, ils disent: «Nous croyons» et, une fois seuls entre eux, ils disent: «Allez-vous confier aux musulmans ce qu'Allah vous a révélé pour leur fournir, ainsi, un argument contre vous devant votre Seigneur! Etes-vous donc dépourvus de raison?»."},{"n":84,"s":2,"a":77,"t":"- Ne savent-ils pas qu'en vérité Allah sait ce qu'ils cachent et ce qu'ils divulguent?"},{"n":85,"s":2,"a":78,"t":"Et il y a parmi eux des illettrés qui ne savent rien du Livre hormis des prétentions et ils ne font que des conjectures."},{"n":86,"s":2,"a":79,"t":"Malheur, donc, à ceux qui de leurs propres mains composent un livre puis le présentent comme venant d'Allah pour en tirer un vil profit! - Malheur à eux, donc, à cause de ce que leurs mains ont écrit, et malheur à eux à cause de ce qu'ils en profitent!"},{"n":87,"s":2,"a":80,"t":"Et ils ont dit: «Le Feu ne nous touchera que pour quelques jours comptés!». Dis: «Auriez-vous pris un engagement avec Allah - car Allah ne manque jamais à Son engagement; - non, mais vous dites sur Allah ce que vous ne savez pas»."},{"n":88,"s":2,"a":81,"t":"Bien au contraire! Ceux qui font le mal et qui se font cerner par leurs péchés, ceux-là sont les gens du Feu où ils demeureront éternellement."},{"n":89,"s":2,"a":82,"t":"Et ceux qui croient et pratiquent les bonnes œuvres, ceux-là sont les gens du Paradis où ils demeureront éternellement."},{"n":90,"s":2,"a":83,"t":"Et [rappelle-toi], lorsque Nous avons pris l'engagement des enfants d'Israël de n'adorer qu'Allah, de faire le bien envers les pères, les mères, les proches parents, les orphelins et les nécessiteux, d'avoir de bonnes paroles avec les gens; d'accomplir régulièrement la Salât et d'acquitter la Zakât! - Mais à l'exception d'un petit nombre de vous, vous manquiez à vos engagements en vous détournant de Nos commandements."},{"n":91,"s":2,"a":84,"t":"Et rappelez-vous, lorsque Nous obtînmes de vous l'engagement de ne pas vous verser le sang, [par le meurtre] de ne pas vous expulser les uns les autres de vos maisons. Puis vous y avez souscrit avec votre propre témoignage."},{"n":92,"s":2,"a":85,"t":"Quoique ainsi engagés, voilà que vous vous entretuez, que vous expulsez de leurs maisons une partie d'entre vous contre qui vous prêtez main forte par péché et agression. Mais quelle contradiction! Si vos coreligionnaires vous viennent captifs vous les rançonnez alors qu'il vous était interdit de les expulser (de chez eux). Croyez-vous donc en une partie du Livre et rejetez-vous le reste? Ceux d'entre vous qui agissent de la sorte ne méritent que l'ignominie dans cette vie, et au Jour de la Résurrection ils seront refoulés au plus dur châtiment, et Allah n'est pas inattentif à ce que vous faites."},{"n":93,"s":2,"a":86,"t":"Voilà ceux qui échangent la vie présente contre la vie future. Eh bien, leur châtiment ne sera pas diminué. Et ils ne seront point secourus."},{"n":94,"s":2,"a":87,"t":"Certes, Nous avons donné le Livre à Moïse; Nous avons envoyé après lui des prophètes successifs. Et Nous avons donné des preuves à Jésus fils de Marie, et Nous l'avons renforcé du Saint-Esprit. Est-ce qu'à chaque fois, qu'un Messager vous apportait des vérités contraires à vos souhaits vous vous enfliez d'orgueil? Vous traitiez les uns d'imposteurs et vous tuiez les autres."},{"n":95,"s":2,"a":88,"t":"Et ils dirent: «Nos cœurs sont enveloppés et impénétrables» - Non mais Allah les a maudits à cause de leur infidélité, leur foi est donc médiocre."},{"n":96,"s":2,"a":89,"t":"Et quand leur vint d'Allah un Livre confirmant celui qu'ils avaient déjà, - alors qu'auparavant ils cherchaient la suprématie sur les mécréants, - quand donc leur vint cela même qu'ils reconnaissaient, ils refusèrent d'y croire. Que la malédiction d'Allah soit sur les mécréants!"},{"n":97,"s":2,"a":90,"t":"Comme est vil ce contre quoi ils ont troqué leurs âmes! Ils ne croient pas en ce qu'Allah a fait descendre, révoltés à l'idée qu'Allah, de par Sa grâce, fasse descendre la révélation sur ceux de Ses serviteurs qu'Il veut. Ils ont donc acquis colère sur colère, car un châtiment avilissant attend les infidèles!"},{"n":98,"s":2,"a":91,"t":"Et quand on leur dit: «Croyez à ce qu'Allah a fait descendre», ils disent: «Nous croyons à ce qu'on a fait descendre à nous». Et ils rejettent le reste, alors qu'il est la vérité confirmant ce qu'il y avait déjà avec eux. - Dis: «Pourquoi donc avez-vous tué auparavant les prophètes d'Allah, si vous étiez croyants?»."},{"n":99,"s":2,"a":92,"t":"Et en effet Moïse vous est venu avec les preuves. Malgré cela, une fois absent, vous avez pris le Veau pour idole, alors que vous étiez injustes."},{"n":100,"s":2,"a":93,"t":"Et rappelez-vous, lorsque Nous avons pris l'engagement de vous, et brandi sur vous AT-Tûr (le Mont Sinaï) en vous disant: «Tenez ferme à ce que Nous vous avons donné, et écoutez!». Ils dirent: «Nous avons écouté et désobéi». Dans leur impiété, leurs cœurs étaient passionnément épris du Veau (objet de leur culte). Dis-[leur]: «Quelles mauvaises prescriptions ordonnées par votre foi, si vous êtes croyants»."},{"n":101,"s":2,"a":94,"t":"- Dis: «Si l'Ultime demeure auprès d'Allah est pour vous seuls, à l'exclusion des autres gens, souhaitez donc la mort [immédiate] si vous êtes véridiques!»"},{"n":102,"s":2,"a":95,"t":"Or, ils ne la souhaiteront jamais, sachant tout le mal qu'ils ont perpétré de leurs mains. Et Allah connait bien les injustes."},{"n":103,"s":2,"a":96,"t":"Et certes tu les trouveras les plus attachés à la vie [d'ici-bas], pire en cela que les Associateurs. Tel d'entre eux aimerait vivre mille ans. Mais une pareille longévité ne le sauvera pas du châtiment! Et Allah voit bien leurs actions."},{"n":104,"s":2,"a":97,"t":"Dis: «Quiconque est ennemi de Gabriel doit connaître que c'est lui qui, avec la permission d'Allah, a fait descendre sur ton cœur cette révélation qui déclare véridiques les messages antérieurs et qui sert aux croyants de guide et d'heureuse annonce»"},{"n":105,"s":2,"a":98,"t":"[Dis:] «Quiconque est ennemi d'Allah, de Ses anges, de Ses messagers, de Gabriel et de Michaël... [Allah sera son ennemi] car Allah est l'ennemi des infidèles»."},{"n":106,"s":2,"a":99,"t":"Et très certainement Nous avons fait descendre vers toi des signes évidents. Et seuls les pervers n'y croient pas."},{"n":107,"s":2,"a":100,"t":"Faudrait-il chaque fois qu'ils concluent un pacte, qu'une partie d'entre eux le dénonce? C'est que plutôt la plupart d'entre eux ne sont pas croyants."},{"n":108,"s":2,"a":101,"t":"Et quand leur vint d'Allah un messager confirmant ce qu'il y avait déjà avec eux, certains à qui le Livre avait été donné, jetèrent derrière leur dos le Livre d'Allah comme s'ils ne savaient pas!"},{"n":109,"s":2,"a":102,"t":"Et ils suivirent ce que les diables racontent contre le règne de Solayman. Alors que Solayman n'a jamais été mécréant mais bien les diables: ils enseignent aux gens la magie ainsi que ce qui est descendu aux deux anges Hârout et Mârout, à Babylone; mais ceux-ci n'enseignaient rien à personne, qu'ils n'aient dit d'abord: «Nous ne sommes rien qu'une tentation: ne sois pas mécréant» ils apprennent auprès d'eux ce qui sème la désunion entre l'homme et son épouse. Or ils ne sont capables de nuire à personne qu'avec la permission d'Allah. Et les gens apprennent ce qui leur nuit et ne leur est pas profitable. Et ils savent, très certainement, que celui qui acquiert [ce pouvoir] n'aura aucune part dans l'au-delà. Certes, quelle détestable marchandise pour laquelle ils ont vendu leurs âmes! Si seulement ils savaient!"},{"n":110,"s":2,"a":103,"t":"Et s'ils croyaient et vivaient en piété, une récompense de la part d'Allah serait certes meilleure. Si seulement ils savaient!"},{"n":111,"s":2,"a":104,"t":"O vous qui croyez! Ne dites pas: «Râ'inâ» (favorise-nous) mais dites: «Onzurnâ» (regarde-nous); et écoutez! Un châtiment douloureux sera pour les infidèles."},{"n":112,"s":2,"a":105,"t":"Ni les mécréants parmi les gens du Livre, ni les Associateurs n'aiment qu'on fasse descendre sur vous un bienfait de la part de votre Seigneur, alors qu'Allah réserve à qui Il veut sa Miséricorde. Et c'est Allah le Détenteur de l'abondante grâce."},{"n":113,"s":2,"a":106,"t":"Si Nous abrogeons un verset quelconque ou que Nous le fassions oublier, Nous en apportons un meilleur, ou un semblable. Ne sais-tu pas qu'Allah est Omnipotent?"},{"n":114,"s":2,"a":107,"t":"Ne sais-tu pas qu'à Allah, appartient le royaume des cieux et de la terre, et qu'en dehors d'Allah vous n'avez ni protecteur ni secoureur?"},{"n":115,"s":2,"a":108,"t":"Voudriez-vous interroger votre Messager comme auparavant on interrogea Moïse? Quiconque substitue la mécréance à la foi s'égare certes du droit chemin."},{"n":116,"s":2,"a":109,"t":"Nombre de gens du Livre aimeraient par jalousie de leur part, pouvoir vous rendre mécréants après que vous ayez cru. Et après que la vérité s'est manifestée à eux! Pardonnez et oubliez jusqu'à ce qu'Allah fasse venir Son commandement. Allah est très certainement Omnipotent!"},{"n":117,"s":2,"a":110,"t":"Et accomplissez la Salât et acquittez la Zakât. Et tout ce que vous avancez de bien pour vous-mêmes, vous le retrouverez auprès d'Allah, car Allah voit parfaitement ce que vous faites."},{"n":118,"s":2,"a":111,"t":"Et ils ont dit: «Nul n'entrera au Paradis que Juifs ou Chrétiens». Voilà leurs chimères. - Dis: «Donnez votre preuve, si vous êtes véridiques»."},{"n":119,"s":2,"a":112,"t":"Non, mais quiconque soumet à Allah son être tout en faisant le bien, aura sa rétribution auprès de son Seigneur. Pour eux, nulle crainte, et ils ne seront point attristés."},{"n":120,"s":2,"a":113,"t":"Et les Juifs disent: «Les Chrétiens ne tiennent sur rien» et les Chrétiens disent: «Les Juifs ne tiennent sur rien», alors qu'ils lisent le Livre! De même ceux qui ne savent rien tiennent un langage semblable au leur. Eh bien, Allah jugera sur ce quoi ils s'opposent, au Jour de la Résurrection."},{"n":121,"s":2,"a":114,"t":"Qui est plus injuste que celui qui empêche que dans les mosquées d'Allah, on mentionne Son Nom, et qui s'efforce à les détruire? De tels gens ne devraient y entrer qu'apeurés. Pour eux, ignominie ici-bas; et dans l'au-delà un énorme châtiment."},{"n":122,"s":2,"a":115,"t":"A Allah seul appartiennent l'Est et l'Ouest. Où que vous vous tourniez, la Face (direction) d'Allah est donc là, car Allah a la grâce immense; Il est Omniscient."},{"n":123,"s":2,"a":116,"t":"Et ils ont dit: «Allah s'est donné un fils»! Gloire à Lui! Non! mais c'est à Lui qu'appartient ce qui est dans les cieux et la terre et c'est à Lui que tous obéissent."},{"n":124,"s":2,"a":117,"t":"Il est le Créateur des cieux et de la terre à partir du néant. Lorsqu'Il décide une chose, Il dit seulement: «Sois», et elle est aussitôt."},{"n":125,"s":2,"a":118,"t":"Et ceux qui ne savent pas ont dit: «Pourquoi Allah ne nous parle-t-Il pas [directement], ou pourquoi un signe ne nous vient-il pas?» De même, ceux d'avant eux disaient une parole semblable. Leurs cœurs se ressemblent. Nous avons clairement exposé les signes pour des gens qui ont la foi ferme."},{"n":126,"s":2,"a":119,"t":"Certes, Nous t'avons envoyé avec la vérité, en annonciateur et avertisseur; et on ne te demande pas compte des gens de l'Enfer."},{"n":127,"s":2,"a":120,"t":"Ni les Juifs, ni les Chrétiens ne seront jamais satisfaits de toi, jusqu'à ce que tu suives leur religion. - Dis: «Certes, c'est la direction d'Allah qui est la vraie direction». Mais si tu suis leurs passions après ce que tu as reçu de science, tu n'auras contre Allah ni protecteur ni secoureur."},{"n":128,"s":2,"a":121,"t":"Ceux à qui Nous avons donné le Livre, qui le récitent comme il se doit, ceux-là y croient. Et ceux qui n'y croient pas sont les perdants."},{"n":129,"s":2,"a":122,"t":"O Enfants d'Israël, rappelez-vous Mon bienfait dont Je vous ai comblés et que Je vous ai favorisés par-dessus le reste du monde (de leur époque)."},{"n":130,"s":2,"a":123,"t":"Et redoutez le jour où nulle âme ne bénéficiera à une autre, où l'on n'acceptera d'elle aucune compensation, et où aucune intercession ne lui sera utile. Et ils ne seront point secourus."},{"n":131,"s":2,"a":124,"t":"[Et rappelle-toi] quand ton Seigneur eut éprouvé Abraham par certains commandements, et qu'il les eut accomplis, le Seigneur lui dit: «Je vais faire de toi un exemple à suivre pour les gens». - «Et parmi ma descendance?» demanda-t-il. - «Mon engagement, dit Allah, ne s'applique pas aux injustes»"},{"n":132,"s":2,"a":125,"t":"[Et rappelle-toi], quand nous fîmes de la Maison un lieu de visite et un asile pour les gens - Adoptez donc pour lieu de prière, ce lieu où Abraham se tint debout - Et Nous confiâmes à Abraham et à Ismaël ceci: «Purifiez Ma Maison pour ceux qui tournent autour, y font retraite pieuse, s'y inclinent et s'y prosternent."},{"n":133,"s":2,"a":126,"t":"Et quand Abraham supplia: «O mon Seigneur, fais de cette cité un lieu de sécurité, et fais attribution des fruits à ceux qui parmi ses habitants auront cru en Allah et au Jour dernier», le Seigneur dit: «Et quiconque n'y aura pas cru, alors Je lui concèderai une courte jouissance [ici-bas], puis Je le contraindrai au châtiment du Feu [dans l'au-delà]. Et quelle mauvaise destination!»"},{"n":134,"s":2,"a":127,"t":"Et quand Abraham et Ismaël élevaient les assises de la Maison: «O notre Seigneur, accepte ceci de notre part! Car c'est Toi l'Audient, l'Omniscient."},{"n":135,"s":2,"a":128,"t":"Notre Seigneur! Fais de nous Tes Soumis, et de notre descendance une communauté soumise à Toi. Et montre nous nos rites et accepte de nous le repentir. Car c'est Toi certes l'Accueillant au repentir, le Miséricordieux."},{"n":136,"s":2,"a":129,"t":"Notre Seigneur! Envoie l'un des leurs comme messager parmi eux, pour leur réciter Tes versets, leur enseigner le Livre et la Sagesse, et les purifier. Car c'est Toi certes le Puissant, le Sage!"},{"n":137,"s":2,"a":130,"t":"Qui donc aura en aversion la religion d'Abraham, sinon celui qui sème son âme dans la sottise? Car très certainement Nous l'avons choisi en ce monde; et, dans l'au-delà, il est certes du nombre des gens de bien."},{"n":138,"s":2,"a":131,"t":"Quand son Seigneur lui avait dit: «Soumets-toi», il dit: «Je me soumets au Seigneur de l'Univers»."},{"n":139,"s":2,"a":132,"t":"Et c'est ce qu'Abraham recommanda à ses fils, de même que Jacob: «O mes fils, certes Allah vous a choisi la religion: ne mourrez point, donc, autrement qu'en Soumis!» (à Allah)."},{"n":140,"s":2,"a":133,"t":"Etiez-vous témoins quand la mort se présenta à Jacob et qu'il dit à ses fils: «Qu'adorerez-vous après moi?» - Ils répondirent: «Nous adorerons ta divinité et la divinité de tes pères, Abraham, Ismaël et Isaac, Divinité Unique et à laquelle nous sommes Soumis»."},{"n":141,"s":2,"a":134,"t":"Voilà une génération bel et bien révolue. A elle ce qu'elle a acquis, et à vous ce que vous avez acquis. On ne vous demandera pas compte de ce qu'ils faisaient."},{"n":142,"s":2,"a":135,"t":"Ils ont dit : «Soyez Juifs ou Chrétiens, vous serez donc sur la bonne voie». - Dis: «Non, mais nous suivons la religion d'Abraham le modèle même de la droiture et qui ne fut point parmi les Associateurs»."},{"n":143,"s":2,"a":136,"t":"Dites: «Nous croyons en Allah et en ce qu'on nous a révélé, et en ce qu'on a fait descendre vers Abraham et Ismaël et Isaac et Jacob et les Tribus, et en ce qui a été donné à Moïse et à Jésus, et en ce qui a été donné aux prophètes, venant de leur Seigneur: nous ne faisons aucune distinction entre eux. Et à Lui nous sommes Soumis»."},{"n":144,"s":2,"a":137,"t":"Alors, s'ils croient à cela même à quoi vous croyez, ils seront certainement sur la bonne voie. Et s'ils s'en détournent, ils seront certes dans le schisme! Alors Allah te suffira contre eux. Il est l'Audient, l'Omniscient."},{"n":145,"s":2,"a":138,"t":"«Nous suivons la religion d'Allah! Et qui est meilleur qu'Allah en Sa religion? C'est Lui que nous adorons»."},{"n":146,"s":2,"a":139,"t":"Dis: «Discutez vous avec nous au sujet d'Allah, alors qu'Il est notre Seigneur et le vôtre? A nous nos actions et à vous les vôtres! C'est à Lui que nous sommes dévoués."},{"n":147,"s":2,"a":140,"t":"Ou dites-vous qu'Abraham, Ismaël, Isaac et Jacob et les tribus étaient Juifs ou Chrétiens?» - Dis: «Est-ce vous les plus savants ou Allah?» - Qui est plus injuste que celui qui cache un témoignage qu'il détient d'Allah? Et Allah n'est pas inattentif à ce que vous faites."},{"n":148,"s":2,"a":141,"t":"Voilà une génération bel et bien révolue. A elle ce qu'elle a acquis, et à vous ce que vous avez acquis. Et on ne vous demandera pas compte de ce qu'ils faisaient."},{"n":149,"s":2,"a":142,"t":"Les faibles d'esprit parmi les gens vont dire: «Qui les a détournés de la direction (Qibla) vers laquelle ils s'orientaient auparavant?» - Dis: «C'est à Allah qu'appartiennent le Levant et le Couchant. Il guide qui Il veut vers un droit chemin»."},{"n":150,"s":2,"a":143,"t":"Et aussi Nous avons fait de vous une communauté de justes pour que vous soyez témoins aux gens, comme le Messager sera témoin à vous. Et Nous n'avions établi la direction (Qibla) vers laquelle tu te tournais que pour savoir qui suit le Messager [Muhammad] et qui s'en retourne sur ses talons. C'était un changement difficile, mais pas pour ceux qu'Allah guide. Et ce n'est pas Allah qui vous fera perdre [la récompense de] votre foi, car Allah, certes est Compatissant et Miséricordieux pour les hommes."},{"n":151,"s":2,"a":144,"t":"Certes nous te voyons tourner le visage en tous sens dans le ciel. Nous te faisons donc orienter vers une direction qui te plaît. Tourne donc ton visage vers la Mosquée sacrée. Où que vous soyez, tournez-y vos visages. Certes, ceux à qui le Livre a été donné savent bien que c'est la vérité venue de leur Seigneur. Et Allah n'est pas inattentif à ce qu'ils font."},{"n":152,"s":2,"a":145,"t":"Certes si tu apportais toutes les preuves à ceux à qui le Livre a été donné, ils ne suivraient pas ta direction (Qibla)! Et tu ne suivras pas la leur; et entre eux, les uns ne suivent pas la direction des autres. Et si tu suivais leurs passions après ce que tu as reçu de science, tu serais, certes, du nombre des injustes."},{"n":153,"s":2,"a":146,"t":"Ceux à qui Nous avons donné le Livre, le reconnaissent comme ils reconnaissent leurs enfants. Or une partie d'entre eux cache la vérité, alors qu'ils la savent!"},{"n":154,"s":2,"a":147,"t":"La vérité vient de ton Seigneur. Ne sois donc pas de ceux qui doutent."},{"n":155,"s":2,"a":148,"t":"A chacun une orientation vers laquelle il se tourne. Rivalisez donc dans les bonnes œuvres. Où que vous soyez, Allah vous ramènera tous vers Lui, car Allah est, certes Omnipotent."},{"n":156,"s":2,"a":149,"t":"Et d'où que tu sortes, tourne ton visage vers la Mosquée sacrée. Oui voilà bien la vérité venant de ton Seigneur. Et Allah n'est pas inattentif à ce que vous faites."},{"n":157,"s":2,"a":150,"t":"Et d'où que tu sortes, tourne ton visage vers la Mosquée sacrée. Et où que vous soyez, tournez-y vos visages, afin que les gens n'aient pas d'argument contre vous, sauf ceux d'entre eux qui sont de vrais injustes. Ne les craignez donc pas; mais craignez-Moi pour que Je parachève Mon bienfait à votre égard, et que vous soyez bien guidés!"},{"n":158,"s":2,"a":151,"t":"Ainsi, Nous avons envoyé parmi vous un messager de chez vous qui vous récite Nos versets, vous purifie, vous enseigne le Livre et la Sagesse et vous enseigne ce que vous ne saviez pas."},{"n":159,"s":2,"a":152,"t":"Souvenez-vous de Moi donc. Je vous récompenserai. Remerciez-Moi et ne soyez pas ingrats envers Moi!"},{"n":160,"s":2,"a":153,"t":"O les croyants! Cherchez secours dans l'endurance et la Salât. Car Allah est avec ceux qui sont endurants."},{"n":161,"s":2,"a":154,"t":"Et ne dites pas de ceux qui sont tués dans le sentier d'Allah qu'ils sont morts. Au contraire ils sont vivants, mais vous en êtes inconscients."},{"n":162,"s":2,"a":155,"t":"Très certainement, Nous vous éprouverons par un peu de peur, de faim et de diminution de biens, de personnes et de fruits. Et fais la bonne annonce aux endurants,"},{"n":163,"s":2,"a":156,"t":"qui disent, quand un malheur les atteint: «Certes nous sommes à Allah, et c'est à Lui que nous retournerons."},{"n":164,"s":2,"a":157,"t":"Ceux-là reçoivent des bénédictions de leur Seigneur, ainsi que la miséricorde; et ceux-là sont les biens guidés."},{"n":165,"s":2,"a":158,"t":"AS-Safâ et Al-Marwah sont vraiment parmi les lieux sacrés d'Allah. Donc, quiconque fait pèlerinage à la Maison ou fait l'Umra ne commet pas de péché en faisant le va-et-vient entre ces deux monts. Et quiconque fait de son propre gré une bonne œuvre, alors Allah est Reconnaissant, Omniscient."},{"n":166,"s":2,"a":159,"t":"Certes ceux qui cachent ce que Nous avons fait descendre en fait de preuves et de guide après l'exposé que Nous en avons fait aux gens, dans le Livre, voilà ceux qu'Allah maudit et que les maudisseurs maudissent,"},{"n":167,"s":2,"a":160,"t":"sauf ceux qui se sont repentis, corrigés et déclarés: d'eux Je reçois le repentir. Car c'est Moi, l'Accueillant au repentir, le Miséricordieux."},{"n":168,"s":2,"a":161,"t":"Ceux qui ne croient pas et meurent mécréants, recevront la malédiction d'Allah, des Anges et de tous les hommes."},{"n":169,"s":2,"a":162,"t":"Ils y demeureront éternellement; le châtiment ne leur sera pas allégé, et on ne leur accordera pas de répit."},{"n":170,"s":2,"a":163,"t":"Et votre Divinité est une divinité unique. Pas de divinité à part Lui, le Tout Miséricordieux, le Très Miséricordieux."},{"n":171,"s":2,"a":164,"t":"Certes dans la création des cieux et de la terre, dans l'alternance de la nuit et du jour, dans le navire qui vogue en mer chargé de choses profitables aux gens, dans l'eau qu'Allah fait descendre du ciel, par laquelle Il rend la vie à la terre une fois morte et y répand des bêtes de toute espèce dans la variation des vents, et dans les nuages soumis entre le ciel et la terre, en tout cela il y a des signes, pour un peuple qui raisonne."},{"n":172,"s":2,"a":165,"t":"Parmi les hommes, il en est qui prennent, en dehors d'Allah, des égaux à Lui, en les aimant comme on aime Allah. Or les croyants sont les plus ardents en l'amour d'Allah. Quand les injustes verront le châtiment, ils sauront que la force tout entière est à Allah et qu'Allah est dur en châtiment!..."},{"n":173,"s":2,"a":166,"t":"Quand les meneurs désavoueront les suiveurs à la vue du châtiment, les liens entre eux seront bien brisés!"},{"n":174,"s":2,"a":167,"t":"Et les suiveurs diront: «Ah! Si un retour nous était possible! Alors nous les désavouerions comme ils nous ont désavoués!» - Ainsi Allah leur montra leurs actions; source de remords pour eux; mais ils ne pourront pas sortir du Feu."},{"n":175,"s":2,"a":168,"t":"O gens! De ce qui existe sur la terre; mangez le licite pur; ne suivez point les pas du Diable car il est vraiment pour vous, un ennemi déclaré."},{"n":176,"s":2,"a":169,"t":"Il ne vous commande que le mal et la turpitude et de dire contre Allah ce que vous ne savez pas."},{"n":177,"s":2,"a":170,"t":"Et quand on leur dit: «Suivez ce qu'Allah a fait descendre», ils disent: «Non, mais nous suivrons les coutumes de nos ancêtres.» - Quoi! et si leurs ancêtres n'avaient rien raisonné et s'ils n'avaient pas été dans la bonne direction?"},{"n":178,"s":2,"a":171,"t":"Les mécréants ressemblent à [du bétail] auquel on crie et qui entend seulement appel et voix confus. Sourds, muets, aveugles, ils ne raisonnent point."},{"n":179,"s":2,"a":172,"t":"O les croyants! Mangez des (nourritures) licites que Nous vous avons attribuées. Et remerciez Allah, si c'est Lui que vous adorez."},{"n":180,"s":2,"a":173,"t":"Certes, Il vous interdit la chair d'une bête morte, le sang, la viande de porc et ce sur quoi on a invoqué un autre qu'Allah. Il n'y a pas de péché sur celui qui est contraint sans toutefois abuser ni transgresser, car Allah est Pardonneur et Miséricordieux."},{"n":181,"s":2,"a":174,"t":"Ceux qui cachent ce qu'Allah a fait descendre du Livre et le vendent à vil prix, ceux-là ne s'emplissent le ventre que de Feu. Allah ne leur adressera pas la parole, au Jour de la Résurrection, et ne les purifiera pas. Et il y aura pour eux un douloureux châtiment."},{"n":182,"s":2,"a":175,"t":"Ceux-là ont échangé la bonne direction contre l'égarement et le pardon contre le châtiment. Qu'est-ce qui leur fera supporter le Feu?!"},{"n":183,"s":2,"a":176,"t":"C'est ainsi, car c'est avec la vérité qu'Allah a fait descendre le Livre; et ceux qui s'opposent au sujet du Livre sont dans une profonde divergence."},{"n":184,"s":2,"a":177,"t":"La bonté pieuse ne consiste pas à tourner vos visages vers le Levant ou le Couchant. Mais la bonté pieuse est de croire en Allah, au Jour dernier, aux Anges, au Livre et aux prophètes, de donner de son bien, quelqu'amour qu'on en ait, aux proches, aux orphelins, aux nécessiteux, aux voyageurs indigents et à ceux qui demandent l'aide et pour délier les jougs, d'accomplir la Salât et d'acquitter la Zakât. Et ceux qui remplissent leurs engagements lorsqu'ils se sont engagés, ceux qui sont endurants dans la misère, la maladie et quand les combats font rage, les voilà les véridiques et les voilà les vrais pieux!"},{"n":185,"s":2,"a":178,"t":"O les croyants! On vous a prescrit le talion au sujet des tués: homme libre pour homme libre, esclave pour esclave, femme pour femme. Mais celui à qui son frère aura pardonné en quelque façon doit faire face à une requête convenable et doit payer des dommages de bonne grâce. Ceci est un allègement de la part de votre Seigneur, et une miséricorde. Donc, quiconque après cela transgresse, aura un châtiment douloureux."},{"n":186,"s":2,"a":179,"t":"C'est dans le talion que vous aurez la préservation de la vie, ô vous doués d'intelligence, ainsi atteindrez-vous la piété."},{"n":187,"s":2,"a":180,"t":"On vous a prescrit, quand la mort est proche de l'un de vous et s'il laisse des biens, de faire un testament en règle en faveur de ses père et mère et de ses plus proches. C'est un devoir pour les pieux."},{"n":188,"s":2,"a":181,"t":"Quiconque l'altère après l'avoir entendu, le péché ne reposera que sur ceux qui l'ont altéré; certes, Allah est Audient et Omniscient."},{"n":189,"s":2,"a":182,"t":"Mais quiconque craint d'un testateur quelque partialité (volontaire ou involontaire), et les réconcilie, alors, pas de péché sur lui car Allah est certes Pardonneur et Miséricordieux!"},{"n":190,"s":2,"a":183,"t":"O les croyants! On vous a prescrit aS-Siyâm comme on l'a prescrit à ceux d'avant vous, ainsi atteindrez-vous la piété,"},{"n":191,"s":2,"a":184,"t":"pendant un nombre déterminé de jours. Quiconque d'entre vous est malade ou en voyage, devra jeûner un nombre égal d'autres jours. Mais pour ceux qui ne pourraient le supporter qu'(avec grande difficulté), il y a une compensation: nourrir un pauvre. Et si quelqu'un fait plus de son propre gré, c'est pour lui; mais il est mieux pour vous de jeûner; si vous saviez!"},{"n":192,"s":2,"a":185,"t":"(Ces jours sont) le mois de Ramadân au cours duquel le Coran a été descendu comme guide pour les gens, et preuves claires de la bonne direction et du discernement. Donc, quiconque d'entre vous est présent en ce mois, qu'il jeûne! Et quiconque est malade ou en voyage, alors qu'il jeûne un nombre égal d'autres jours. - Allah veut pour vous la facilité, Il ne veut pas la difficulté pour vous, afin que vous en complétiez le nombre et que vous proclamiez la grandeur d'Allah pour vous avoir guidés, et afin que vous soyez reconnaissants!"},{"n":193,"s":2,"a":186,"t":"Et quand Mes serviteurs t'interrogent sur Moi.. alors Je suis tout proche: Je réponds à l'appel de celui qui Me prie quand il Me prie. Qu'ils répondent à Mon appel, et qu'ils croient en Moi, afin qu'ils soient bien guidés."},{"n":194,"s":2,"a":187,"t":"On vous a permis, la nuit d'as-Siyâm, d'avoir des rapports avec vos femmes; elles sont un vêtement pour vous et vous êtes un vêtement pour elles. Allah sait que vous aviez clandestinement des rapports avec vos femmes. Il vous a pardonné et vous a graciés. Cohabitez donc avec elles, maintenant, et cherchez ce qu'Allah a prescrit en votre faveur; mangez et buvez jusqu'à ce que se distingue, pour vous, le fil blanc de l'aube du fil noir de la nuit. Puis accomplissez le jeûne jusqu'à la nuit. Mais ne cohabitez pas avec elles pendant que vous êtes en retraite rituelle dans les mosquées. Voilà les lois d'Allah: ne vous en approchez donc pas (pour les transgresser). C'est ainsi qu'Allah expose aux hommes Ses enseignements, afin qu'ils deviennent pieux!"},{"n":195,"s":2,"a":188,"t":"Et ne dévorez pas mutuellement et illicitement vos biens; et ne vous en servez pas pour corrompre des juges pour vous permettre de dévorer une partie des biens des gens, injustement et sciemment."},{"n":196,"s":2,"a":189,"t":"Ils t'interrogent sur les nouvelles lunes - Dis: «Elles servent aux gens pour compter le temps, et aussi pour le hajj [pèlerinage]. Et ce n'est pas un acte de bienfaisance que de rentrer chez vous par l'arrière des maisons. Mais la bonté pieuse consiste à craindre Allah. Entrez donc dans les maisons par leurs portes. Et craignez Allah, afin que vous réussissiez!"},{"n":197,"s":2,"a":190,"t":"Combattez dans le sentier d'Allah ceux qui vous combattent, et ne transgressez pas. Certes, Allah n'aime pas les transgresseurs!"},{"n":198,"s":2,"a":191,"t":"Et tuez-les, où que vous les rencontriez; et chassez-les d'où ils vous ont chassés: l'association est plus grave que le meurtre. Mais ne les combattez pas près de la Mosquée sacrée avant qu'ils ne vous y aient combattus. S'ils vous y combattent, tuez-les donc. Telle est la rétribution des mécréants."},{"n":199,"s":2,"a":192,"t":"S'ils cessent, Allah est, certes, Pardonneur et Miséricordieux."},{"n":200,"s":2,"a":193,"t":"Et combattez-les jusqu'à ce qu'il n'y ait plus d'association et que la religion soit entièrement à Allah seul. S'ils cessent, donc plus d'hostilités, sauf contre les injustes."},{"n":201,"s":2,"a":194,"t":"Le Mois sacré pour le mois sacré! - Le talion s'applique à toutes choses sacrées -. Donc, quiconque transgresse contre vous, transgressez contre lui, à transgression égale. Et craignez Allah. Et sachez qu'Allah est avec les pieux."},{"n":202,"s":2,"a":195,"t":"Et dépensez dans le sentier d'Allah. Et ne vous jetez pas par vos propres mains dans la destruction. Et faites le bien. Car Allah aime les bienfaisants."},{"n":203,"s":2,"a":196,"t":"Et accomplissez pour Allah le pèlerinage et l'Umra. Si vous en êtes empêchés, alors faites un sacrifice qui vous soit facile. Et ne rasez pas vos têtes avant que l'offrande [l'animal à sacrifier] n'ait atteint son lieu d'immolation. Si l'un d'entre vous est malade ou souffre d'une affection de la tête (et doit se raser), qu'il se rachète alors par un Siyâm ou par une aumône ou par un sacrifice. Quand vous retrouverez ensuite la paix, quiconque a joui d'une vie normale après avoir fait l'Umra en attendant le pèlerinage, doit faire un sacrifice qui lui soit facile. S'il n'a pas les moyens qu'il jeûne trois jours pendant le pèlerinage et sept jours une fois rentré chez lui, soit en tout dix jours. Cela est prescrit pour celui dont la famille n'habite pas auprès de la Mosquée sacrée. Et craignez Allah. Et sachez qu'Allah est dur en punition."},{"n":204,"s":2,"a":197,"t":"Le pèlerinage a lieu dans des mois connus. Si l'on se décide de l'accomplir, alors point de rapport sexuel, point de perversité, point de dispute pendant le pèlerinage. Et le bien que vous faites, Allah le sait. Et prenez vos provisions; mais vraiment la meilleure provision est la piété. Et redoutez-Moi, ô doués d'intelligence"},{"n":205,"s":2,"a":198,"t":"Ce n'est pas un péché que d'aller en quête de quelque grâce de votre Seigneur. Puis, quand vous déferlez depuis 'Arafât, invoquez Allah, à Al-Mach'ar-al-haram (Al-Muzdalifa). Et invoquez-Le comme Il vous a montré la bonne voie, quoiqu'auparavant vous étiez du nombre des égarés."},{"n":206,"s":2,"a":199,"t":"Ensuite déferlez par où les gens déferlèrent, et demandez pardon à Allah. Car Allah est Pardonneur et Miséricordieux."},{"n":207,"s":2,"a":200,"t":"Et quand vous aurez achevé vos rites, alors invoquez Allah comme vous invoquez vos pères, et plus ardemment encore. Mais il est des gens qui disent seulement: «Seigneur! Accorde nous [le bien] ici-bas!» - Pour ceux-là, nulle part dans l'au-delà."},{"n":208,"s":2,"a":201,"t":"Et il est des gens qui disent: «Seigneur! Accorde nous belle part ici-bas, et belle part aussi dans l'au-delà; et protège-nous du châtiment du Feu!»"},{"n":209,"s":2,"a":202,"t":"Ceux-là auront une part de ce qu'ils auront acquis. Et Allah est prompt à faire rendre compte."},{"n":210,"s":2,"a":203,"t":"Et invoquez Allah pendant un nombre de jours déterminés. Ensuite, il n'y a pas de péché, pour qui se comporte en piété, à partir au bout de deux jours, à s'attarder non plus. Et craignez Allah. Et sachez que c'est vers Lui que vous serez rassemblés."},{"n":211,"s":2,"a":204,"t":"Il y a parmi les gens celui dont la parole sur la vie présente te plaît, et qui prend Allah à témoin de ce qu'il a dans le cœur, tandis que c'est le plus acharné disputeur."},{"n":212,"s":2,"a":205,"t":"Dès qu'il tourne le dos, il parcourt la terre pour y semer le désordre et saccager culture et bétail. Et Allah n'aime pas le désordre!"},{"n":213,"s":2,"a":206,"t":"Et quand on lui dit: «Redoute Allah», l'orgueil criminel s'empare de lui. L'Enfer lui suffira, et quel mauvais lit, certes!"},{"n":214,"s":2,"a":207,"t":"Et il y a parmi les gens celui qui se sacrifie pour la recherche de l'agrément d'Allah. Et Allah est Compatissant envers Ses serviteurs."},{"n":215,"s":2,"a":208,"t":"O les croyants! Entrez en plein dans l'Islam, et ne suivez point les pas du diable, car il est certes pour vous un ennemi déclaré."},{"n":216,"s":2,"a":209,"t":"Puis, si vous bronchez, après que les preuves vous soient venues, sachez alors qu'Allah est Puissant et Sage."},{"n":217,"s":2,"a":210,"t":"Qu'attendent-ils sinon qu'Allah leur vienne à l'ombre des nuées de même que les Anges et que leur sort soit réglé? Et c'est à Allah que toute chose est ramenée."},{"n":218,"s":2,"a":211,"t":"Demande aux enfants d'Israël combien de miracles évidents Nous leur avons apportés! Or, quiconque altère le bienfait d'Allah après qu'il lui soit parvenu... alors, Allah vraiment est dur en punition."},{"n":219,"s":2,"a":212,"t":"On a enjolivé la vie présente à ceux qui ne croient pas, et ils se moquent de ceux qui croient. Mais les pieux seront au-dessus d'eux, au Jour de la Résurrection. Et Allah accorde Ses bienfaits à qui Il veut, sans compter."},{"n":220,"s":2,"a":213,"t":"Les gens formaient (à l'origine) une seule communauté (croyante). Puis, (après leurs divergences,) Allah envoya des prophètes comme annonciateurs et avertisseurs; et Il fit descendre avec eux le Livre contenant la vérité, pour régler parmi les gens leurs divergences. Mais, ce sont ceux-là mêmes à qui il avait été apporté, qui se mirent à en disputer, après que les preuves leur furent venues, par esprit de rivalité! Puis Allah, de par Sa Grâce, guida ceux qui crurent vers cette Vérité sur laquelle les autres disputaient. Et Allah guide qui Il veut vers le chemin droit."},{"n":221,"s":2,"a":214,"t":"Pensez-vous entrer au Paradis alors que vous n'avez pas encore subi des épreuves semblables à celles que subirent ceux qui vécurent avant vous? Misère et maladie les avaient touchés; et ils furent secoués jusqu'à ce que le Messager, et avec lui, ceux qui avaient cru, se fussent écriés: «Quand viendra le secours d'Allah?» - Quoi! le secours d'Allah est sûrement proche."},{"n":222,"s":2,"a":215,"t":"Ils t'interrogent: «Qu'est-ce qu'on doit dépenser?» Dis: «Ce que vous dépensez de bien devrait être pour les père et mère, les proches, les orphelins, les pauvres et les voyageurs indigents. Et tout ce que vous faites de bien, vraiment Allah le sait»."},{"n":223,"s":2,"a":216,"t":"Le combat vous a été prescrit alors qu'il vous est désagréable. Or, il se peut que vous ayez de l'aversion pour une chose alors qu'elle vous est un bien. Et il se peut que vous aimiez une chose alors qu'elle vous est mauvaise. C'est Allah qui sait, alors que vous ne savez pas."},{"n":224,"s":2,"a":217,"t":"Ils t'interrogent sur le fait de faire la guerre pendant les mois sacrés. - Dis: «Y combattre est un péché grave, mais plus grave encore auprès d'Allah est de faire obstacle au sentier d'Allah, d'être impie envers Celui-ci et la Mosquée sacrée, et d'expulser de là ses habitants. L'association est plus grave que le meurtre.» Or, ils ne cesseront de vous combattre jusqu'à, s'ils peuvent, vous détourner de votre religion. Et ceux qui parmi vous abjureront leur religion et mourront infidèles, vaines seront pour eux leurs actions dans la vie immédiate et la vie future. Voilà les gens du Feu: ils y demeureront éternellement."},{"n":225,"s":2,"a":218,"t":"Certes, ceux qui ont cru, émigré et lutté dans le sentier d'Allah, ceux-là espèrent la miséricorde d'Allah. Et Allah est Pardonneur et Miséricordieux."},{"n":226,"s":2,"a":219,"t":"Ils t'interrogent sur le vin et les jeux de hasard. Dis: «Dans les deux il y a un grand péché et quelques avantages pour les gens; mais dans les deux, le péché est plus grand que l'utilité». Et ils t'interrogent: «Que doit-on dépenser (en charité)?» Dis: «L'excédent de vos biens.» Ainsi, Allah vous explique Ses versets afin que vous méditiez"},{"n":227,"s":2,"a":220,"t":"sur ce monde et sur l'au-delà! Et ils t'interrogent au sujet des orphelins. Dis: «Leur faire du bien est la meilleure action. Si vous vous mêlez à eux, ce sont alors vos frères [en religion]. Allah distingue celui qui sème le désordre de celui qui fait le bien. Et si Allah avait voulu, Il vous aurait accablés. Certes Allah est Puissant et Sage."},{"n":228,"s":2,"a":221,"t":"Et n'épousez pas les femmes associatrices tant qu'elles n'auront pas la foi, et certes, une esclave croyante vaut mieux qu'une associatrice même si elle vous enchante. Et ne donnez pas d'épouses aux associateurs tant qu'ils n'auront pas la foi, et certes, un esclave croyant vaut mieux qu'un associateur même s'il vous enchante. Car ceux-là [les associateurs] invitent au Feu; tandis qu'Allah invite, de par Sa Grâce, au Paradis et au pardon Et Il expose aux gens Ses enseignements afin qu'ils se souviennent!"},{"n":229,"s":2,"a":222,"t":"- Et ils t'interrogent sur la menstruation des femmes. - Dis: «C'est un mal. Eloignez-vous donc des femmes pendant les menstrues, et ne les approchez que quand elles sont pures. Quand elles se sont purifiées, alors cohabitez avec elles suivant les prescriptions d'Allah car Allah aime ceux qui se repentent, et Il aime ceux qui se purifient»."},{"n":230,"s":2,"a":223,"t":"Vos épouses sont pour vous un champ de labour; allez à votre champ comme [et quand] vous le voulez et œuvrez pour vous-mêmes à l'avance. Craignez Allah et sachez que vous Le rencontrerez. Et fais gracieuse annonce aux croyants!"},{"n":231,"s":2,"a":224,"t":"Et n'usez pas du nom d'Allah, dans vos serments, pour vous dispenser de faire le bien, d'être pieux et de réconcilier les gens. Et Allah est Audient et Omniscient."},{"n":232,"s":2,"a":225,"t":"Ce n'est pas pour les expressions gratuites dans vos serments qu'Allah vous saisit: Il vous saisit pour ce que vos cœurs ont acquis. Et Allah est Pardonneur et Patient."},{"n":233,"s":2,"a":226,"t":"Pour ceux qui font le serment de se priver de leurs femmes, il y a un délai d'attente de quatre mois. Et s'ils reviennent (de leur serment) celui-ci sera annulé, car Allah est certes Pardonneur et Miséricordieux!"},{"n":234,"s":2,"a":227,"t":"Mais s'ils se décident au divorce, (celui-ci devient exécutoire) car Allah est certes Audient et Omniscient."},{"n":235,"s":2,"a":228,"t":"Et les femmes divorcées doivent observer un délai d'attente de trois menstrues; et il ne leur est pas permis de taire ce qu'Allah a créé dans leurs ventres, si elles croient en Allah et au Jour dernier. Et leurs époux seront plus en droit de les reprendre pendant cette période, s'ils veulent la réconciliation. Quant à elles, elles ont des droits équivalents à leurs obligations, conformément à la bienséance. Mais les hommes ont cependant une prédominance sur elles. Et Allah est Puissant et Sage."},{"n":236,"s":2,"a":229,"t":"Le divorce est permis pour seulement deux fois. Alors, c'est soit la reprise conformément à la bienséance, ou la libération avec gentillesse. Et il ne vous est pas permis de reprendre quoi que ce soit de ce que vous leur aviez donné, - à moins que tous deux ne craignent de ne point pouvoir se conformer aux ordres imposés par Allah. Si donc vous craignez que tous deux ne puissent se conformer aux ordres d'Allah, alors ils ne commettent aucun péché si la femme se rachète avec quelque bien. Voilà les ordres d'Allah. Ne les transgressez donc pas. Et ceux qui transgressent les ordres d'Allah ceux-là sont les injustes."},{"n":237,"s":2,"a":230,"t":"S'il divorce avec elle (la troisième fois) alors elle ne lui sera plus licite tant qu'elle n'aura pas épousé un autre. Et si ce (dernier) la répudie alors les deux ne commettent aucun péché en reprenant la vie commune, pourvu qu'ils pensent pouvoir tous deux se conformer aux ordres d'Allah. Voilà les ordres d'Allah, qu'Il expose aux gens qui comprennent."},{"n":238,"s":2,"a":231,"t":"Et quand vous divorcez d'avec vos épouses, et que leur délai expire, alors, reprenez-les conformément à la bienséance ou libérez-les conformément à la bienséance. Mais ne les retenez pas pour leur faire du tort: vous transgresseriez alors et quiconque agit ainsi se fait du tort à lui-même. Ne prenez pas en moquerie les versets d'Allah. Et rappelez-vous le bienfait d'Allah envers vous, ainsi que le Livre et la Sagesse qu'Il vous a fait descendre; par lesquels Il vous exhorte. Et craignez Allah, et sachez qu'Allah est Omniscient."},{"n":239,"s":2,"a":232,"t":"Et quand vous divorcez d'avec vos épouses, et que leur délai expire, alors ne les empêchez pas de renouer avec leurs époux, s'ils s'agréent l'un l'autre, et conformément à la bienséance. Voilà à quoi est exhorté celui d'entre vous qui croit en Allah et au Jour dernier. Ceci est plus décent et plus pur pour vous. Et Allah sait, alors que vous ne savez pas."},{"n":240,"s":2,"a":233,"t":"Et les mères, qui veulent donner un allaitement complet, allaiteront leurs bébés deux ans complets. Au père de l'enfant de les nourrir et vêtir de manière convenable. Nul ne doit supporter plus que ses moyens. La mère n'a pas à subir de dommage à cause de son enfant, ni le père, à cause de son enfant. Même obligation pour l'héritier. Et si, après s'être consultés, tous deux tombent d'accord pour décider le sevrage, nul grief à leur faire. Et si vous voulez mettre vos enfants en nourrice, nul grief à vous faire non plus, à condition que vous acquittiez la rétribution convenue, conformément à l'usage. Et craignez Allah, et sachez qu'Allah observe ce que vous faites."},{"n":241,"s":2,"a":234,"t":"Ceux des vôtres que la mort frappe et qui laissent des épouses: celles-ci doivent observer une période d'attente de quatre mois et dix jours. Passé ce délai, on ne vous reprochera pas la façon dont elles disposeront d'elles-mêmes d'une manière convenable. Allah est Parfaitement Connaisseur de ce que vous faites."},{"n":242,"s":2,"a":235,"t":"Et on ne vous reprochera pas de faire, aux femmes, allusion à une proposition de mariage, ou d'en garder secrète l'intention. Allah sait que vous allez songer à ces femmes. Mais ne leur promettez rien secrètement sauf à leur dire des paroles convenables. Et ne vous décidez au contrat de mariage qu'à l'expiration du délai prescrit. Et sachez qu'Allah sait ce qu'il y a dans vos âmes. Prenez donc garde à Lui, et sachez aussi qu'Allah est Pardonneur et Plein de mansuétude."},{"n":243,"s":2,"a":236,"t":"Vous ne faites point de péché en divorçant d'avec des épouses que vous n'avez pas touchées, et à qui vous n'avez pas fixé leur mahr. Donnez-leur toutefois - l'homme aisé selon sa capacité, l'indigent selon sa capacité - quelque bien convenable dont elles puissent jouir. C'est un devoir pour les bienfaisants.."},{"n":244,"s":2,"a":237,"t":"Et si vous divorcez d'avec elles sans les avoir touchées, mais après fixation de leur mahr versez-leur alors la moitié de ce que vous avez fixé, à moins qu'elles ne s'en désistent, ou que ne se désiste celui entre les mains de qui est la conclusion du mariage. Le désistement est plus proche de la piété. Et n'oubliez pas votre faveur mutuelle. Car Allah voit parfaitement ce que vous faites."},{"n":245,"s":2,"a":238,"t":"Soyez assidus aux Salâts et surtout la Salât médiane; et tenez-vous debout devant Allah, avec humilité."},{"n":246,"s":2,"a":239,"t":"Mais si vous craignez (un grand danger), alors priez en marchant ou sur vos montures. Puis quand vous êtes en sécurité, invoquez Allah comme Il vous a enseigné ce que vous ne saviez pas."},{"n":247,"s":2,"a":240,"t":"Ceux d'entre vous que la mort frappe et qui laissent des épouses, doivent laisser un testament en faveur de leurs épouses pourvoyant à un an d'entretien sans les expulser de chez elles. Si ce sont elles qui partent, alors on ne vous reprochera pas ce qu'elles font de convenable pour elles-mêmes. Allah est Puissant et Sage."},{"n":248,"s":2,"a":241,"t":"Les divorcées ont droit à la jouissance d'une allocation convenable, [constituant] un devoir pour les pieux."},{"n":249,"s":2,"a":242,"t":"C'est ainsi qu'Allah vous explique Ses versets, afin que vous raisonniez!"},{"n":250,"s":2,"a":243,"t":"N'as-tu pas vu ceux qui sortirent de leurs demeures, - il y en avait des milliers -, par crainte de la mort? Puis Allah leur dit: «Mourez». Après quoi Il les rendit à la vie. Certes, Allah est Détenteur de la Faveur, envers les gens; mais la plupart des gens ne sont pas reconnaissants."},{"n":251,"s":2,"a":244,"t":"Et combattez dans le sentier d'Allah. Et sachez qu'Allah est Audient et Omniscient."},{"n":252,"s":2,"a":245,"t":"Quiconque prête à Allah de bonne grâce, Il le lui rendra multiplié plusieurs fois. Allah restreint ou étend (Ses faveurs.) Et c'est à Lui que vous retournerez."},{"n":253,"s":2,"a":246,"t":"N'as-tu pas su l'histoire des notables, parmi les enfants d'Israël, lorsqu'après Moïse ils dirent à un prophète à eux: «Désigne-nous un roi, pour que nous combattions dans le sentier d'Allah». Il dit: «Et si vous ne combattez pas, quand le combat vous sera prescrit?» Ils dirent: «Et qu'aurions-nous à ne pas combattre dans le sentier d'Allah, alors qu'on nous a expulsés de nos maisons et qu'on a capturé nos enfants?» Et quand le combat leur fut prescrit, ils tournèrent le dos, sauf un petit nombre d'entre eux. Et Allah connaît bien les injustes."},{"n":254,"s":2,"a":247,"t":"Et leur prophète leur dit: «Voici qu'Allah vous a envoyé Tâlût pour roi.» Ils dirent: «Comment règnerait-il sur nous? Nous avons plus de droit que lui à la royauté. On ne lui a même pas prodigué beaucoup de richesses!» Il dit: «Allah, vraiment l'a élu sur vous, et a accru sa part quant au savoir et à la condition physique.» - Et Allah alloue Son pouvoir à qui Il veut. Allah a la grâce immense et Il est Omniscient."},{"n":255,"s":2,"a":248,"t":"Et leur prophète leur dit: «Le signe de son investiture sera que le Coffre va vous revenir; objet de quiétude inspiré par votre Seigneur, et contenant les reliques de ce que laissèrent la famille de Moïse et la famille d'Aaron. Les Anges le porteront. Voilà bien là un signe pour vous, si vous êtes croyants!»"},{"n":256,"s":2,"a":249,"t":"Puis, au moment de partir avec les troupes, Tâlût dit: «Voici: Allah va vous éprouver par une rivière: quiconque y boira ne sera plus des miens; et quiconque n'y goûtera pas sera des miens; - passe pour celui qui y puisera un coup dans le creux de sa main.» Ils en burent, sauf un petit nombre d'entre eux. Puis, lorsqu'ils l'eurent traversée, lui et ceux des croyants qui l'accompagnaient, ils dirent: «Nous voilà sans force aujourd'hui contre Goliath et ses troupes!» Ceux qui étaient convaincus qu'ils auront à rencontrer Allah dirent: «Combien de fois une troupe peu nombreuse a, par la grâce d'Allah, vaincu une troupe très nombreuse! Et Allah est avec les endurants»"},{"n":257,"s":2,"a":250,"t":"Et quand ils affrontèrent Goliath et ses troupes, ils dirent: «Seigneur! Déverse sur nous l'endurance, affermis nos pas et donne-nous la victoire sur ce peuple infidèle»."},{"n":258,"s":2,"a":251,"t":"Ils les mirent en déroute, par la grâce d'Allah. Et David tua Goliath; et Allah lui donna la royauté et la sagesse, et lui enseigna ce qu'Il voulut. Et si Allah ne neutralisait pas une partie des hommes par une autre, la terre serait certainement corrompue. Mais Allah est Détenteur de la Faveur pour les mondes."},{"n":259,"s":2,"a":252,"t":"Voilà les versets d'Allah, que Nous te (Muhammad) récitons avec la vérité. Et tu es, certes parmi les Envoyés."},{"n":260,"s":2,"a":253,"t":"Parmi ces messagers, Nous avons favorisé certains par rapport à d'autres. Il en est à qui Allah a parlé; et Il en a élevé d'autres en grade. A Jésus fils de Marie Nous avons apporté les preuves, et l'avons fortifié par le Saint-Esprit. Et si Allah avait voulu, les gens qui vinrent après eux ne se seraient pas entretués, après que les preuves leur furent venues; mais ils se sont opposés: les uns restèrent croyants, les autres furent infidèles. Si Allah avait voulu, ils ne se seraient pas entretués; mais Allah fait ce qu'Il veut."},{"n":261,"s":2,"a":254,"t":"O les croyants! Dépensez de ce que Nous vous avons attribué, avant que vienne le jour où il n'y aura ni rançon ni amitié ni intercession. Et ce sont les mécréants qui sont les injustes."},{"n":262,"s":2,"a":255,"t":"Allah! Point de divinité à part Lui, le Vivant, Celui qui subsiste par lui-même «Al-Qayyûm». Ni somnolence ni sommeil ne Le saisissent. A Lui appartient tout ce qui est dans les cieux et sur la terre. Qui peut intercéder auprès de Lui sans Sa permission? Il connaît leur passé et leur futur. Et, de Sa science, ils n'embrassent que ce qu'Il veut. Son Trône «Kursiy», déborde les cieux et la terre, dont la garde ne Lui coûte aucune peine. Et Il est le Très Haut, le Très Grand."},{"n":263,"s":2,"a":256,"t":"Nulle contrainte en religion! Car le bon chemin s'est distingué de l'égarement. Donc, quiconque mécroit au Rebelle tandis qu'il croit en Allah saisit l'anse la plus solide, qui ne peut se briser. Et Allah est Audient et Omniscient."},{"n":264,"s":2,"a":257,"t":"Allah est le défenseur de ceux qui ont la foi: Il les fait sortir des ténèbres à la lumière. Quant à ceux qui ne croient pas, ils ont pour défenseurs les Tâghût, qui les font sortir de la lumière aux ténèbres. Voilà les gens du Feu, où ils demeurent éternellement."},{"n":265,"s":2,"a":258,"t":"N'as-tu pas su (l'histoire de) celui qui, parce qu'Allah l'avait fait roi, argumenta contre Abraham au sujet de son Seigneur? Abraham ayant dit: «J'ai pour Seigneur Celui qui donne la vie et la mort», «Moi aussi, dit l'autre, je donne la vie et la mort.» Alors dit Abraham: «Puisqu'Allah fait venir le soleil du Levant, fais-le donc venir du Couchant.» Le mécréant resta alors confondu. Allah ne guide pas les gens injustes."},{"n":266,"s":2,"a":259,"t":"Ou comme celui qui passait par un village désert et dévasté: «Comment Allah va-t-Il redonner la vie à celui-ci après sa mort?» dit-il. Allah donc le fit mourir et le garda ainsi pendant cent ans. Puis Il le ressuscita en disant: «Combien de temps as-tu demeuré ainsi?» «Je suis resté un jour, dit l'autre, ou une partie d'une journée.» «Non! dit Allah, tu es resté cent ans. Regarde donc ta nourriture et ta boisson: rien ne s'est gâté; mais regarde ton âne... Et pour faire de toi un signe pour les gens, et regarde ces ossements, comment Nous les assemblons et les revêtons de chair». Et devant l'évidence, il dit: «Je sais qu'Allah est Omnipotent»."},{"n":267,"s":2,"a":260,"t":"Et quand Abraham dit: «Seigneur! Montre-moi comment Tu ressuscites les morts», Allah dit: «Ne crois-tu pas encore?» «Si! dit Abraham; mais que mon cœur soit rassuré». «Prends donc, dit Allah, quatre oiseaux, apprivoise-les (et coupe-les) puis, sur des monts séparés, mets-en un fragment ensuite appelle-les: ils viendront à toi en toute hâte. Et sache qu'Allah est Puissant et sage.»"},{"n":268,"s":2,"a":261,"t":"Ceux qui dépensent leurs biens dans le sentier d'Allah ressemblent à un grain d'où naissent sept épis, à cent grains l'épi. Car Allah multiplie la récompense à qui Il veut et la grâce d'Allah est immense, et Il est Omniscient."},{"n":269,"s":2,"a":262,"t":"Ceux qui dépensent leurs biens dans le sentier d'Allah sans faire suivre leurs largesses ni d'un rappel ni d'un tort, auront leur récompense auprès de leur Seigneur. Nulle crainte pour eux, et ils ne seront point affligés."},{"n":270,"s":2,"a":263,"t":"Une parole agréable et un pardon valent mieux qu'une aumône suivie d'un tort. Allah n'a besoin de rien, et Il est Indulgent."},{"n":271,"s":2,"a":264,"t":"O les croyants! N'annulez pas vos aumônes par un rappel ou un tort, comme celui qui dépense son bien par ostentation devant les gens sans croire en Allah et au Jour dernier. Il ressemble à un rocher recouvert de terre: qu'une averse l'atteigne, elle le laisse dénué. De pareils hommes ne tirent aucun profit de leurs actes. Et Allah ne guide pas les gens mécréants."},{"n":272,"s":2,"a":265,"t":"Et ceux qui dépensent leurs biens cherchant l'agrément d'Allah, et bien rassurés (de Sa récompense), ils ressemblent à un jardin sur une colline. Qu'une averse l'atteigne, il double ses fruits; à défaut d'une averse qui l'atteint, c'est la rosée. Et Allah voit parfaitement ce que vous faites."},{"n":273,"s":2,"a":266,"t":"L'un de vous aimerait-il avoir un jardin de dattiers et de vignes sous lequel coulent les ruisseaux, et qui lui donne toutes espèces de fruits, que la vieillesse le rattrape, tandis que ses enfants sont encore petits, et qu'un tourbillon contenant du feu s'abatte sur son jardin et le brûle? Ainsi Allah vous explique les signes afin que vous méditiez!"},{"n":274,"s":2,"a":267,"t":"O les croyants! Dépensez des meilleures choses que vous avez gagnées et des récoltes que Nous avons fait sortir de la terre pour vous. Et ne vous tournez pas vers ce qui est vil pour en faire dépense. Ne donnez pas ce que vous-mêmes n'accepteriez qu'en fermant les yeux! Et sachez qu'Allah n'a besoin de rien et qu'Il est digne de louange."},{"n":275,"s":2,"a":268,"t":"Le Diable vous fait craindre l'indigence et vous commande des actions honteuses; tandis qu'Allah vous promet pardon et faveur venant de Lui. La grâce d'Allah est immense et Il est Omniscient."},{"n":276,"s":2,"a":269,"t":"Il donne la sagesse à qui Il veut. Et celui à qui la sagesse est donnée, vraiment, c'est un bien immense qui lui est donné. Mais les doués d'intelligence seulement s'en souviennent."},{"n":277,"s":2,"a":270,"t":"Quelles que soient les dépenses que vœus avez faites, ou le vou que vous avez voué, Allah le sait. Et pour les injustes, pas de secoureurs!"},{"n":278,"s":2,"a":271,"t":"Si vous donnez ouvertement vos aumônes, c'est bien; c'est mieux encore, pour vous, si vous êtes discrets avec elles et vous les donniez aux indigents. Allah effacera une partie de vos méfaits. Allah est Parfaitement Connaisseur de ce que vous faites."},{"n":279,"s":2,"a":272,"t":"Ce n'est pas à toi de les guider (vers la bonne voie), mais c'est Allah qui guide qui Il veut. Et tout ce que vous dépensez de vos biens sera à votre avantage et vous ne dépensez que pour la recherche de la Face «Wajh» d'Allah. Et tout ce que vous dépensez de vos biens dans les bonnes œuvres vous sera récompensé pleinement. Et vous ne serez pas lésés."},{"n":280,"s":2,"a":273,"t":"Aux nécessiteux qui se sont confinés dans le sentier d'Allah, ne pouvant pas parcourir le monde, et que l'ignorant croit riches parce qu'ils ont honte de mendier - tu les reconnaîtras à leur aspect - Ils n'importunent personne en mendiant. Et tout ce que vous dépensez de vos biens, Allah le sait parfaitement."},{"n":281,"s":2,"a":274,"t":"Ceux qui, de nuit et de jour, en secret et ouvertement, dépensent leurs biens (dans les bonnes œuvres), ont leur salaire auprès de leur Seigneur. Ils n'ont rien à craindre et ils ne seront point affligés."},{"n":282,"s":2,"a":275,"t":"Ceux qui mangent [pratiquent] de l'intérêt usuraire ne se tiennent (au jour du Jugement dernier) que comme se tient celui que le toucher de Satan a bouleversé. Cela, parce qu'ils disent: «Le commerce est tout à fait comme l'intérêt». Alors qu'Allah a rendu licite le commerce, et illicite l'intérêt. Celui, donc, qui cesse dès que lui est venue une exhortation de son Seigneur, peut conserver ce qu'il a acquis auparavant; et son affaire dépend d'Allah. Mais quiconque récidive... alors les voilà, les gens du Feu! Ils y demeureront éternellement."},{"n":283,"s":2,"a":276,"t":"Allah anéantit l'intérêt usuraire et fait fructifier les aumônes. Et Allah n'aime pas le mécréant pécheur."},{"n":284,"s":2,"a":277,"t":"Ceux qui ont la foi, ont fait de bonnes œuvres, accompli la Salât et acquitté la Zakât auront certes leur récompense auprès de leur Seigneur. Pas de crainte pour eux, et ils ne seront point affligés."},{"n":285,"s":2,"a":278,"t":"O les croyants! Craignez Allah; et renoncez au reliquat de l'intérêt usuraire, si vous êtes croyants."},{"n":286,"s":2,"a":279,"t":"Et si vous ne le faites pas, alors recevez l'annonce d'une guerre de la part d'Allah et de Son messager. Et si vous vous repentez, vous aurez vos capitaux. Vous ne léserez personne, et vous ne serez point lésés."},{"n":287,"s":2,"a":280,"t":"A celui qui est dans la gêne, accordez un sursis jusqu'à ce qu'il soit dans l'aisance. Mais il est mieux pour vous de faire remise de la dette par charité! Si vous saviez!"},{"n":288,"s":2,"a":281,"t":"Et craignez le jour où vous serez ramenés vers Allah. Alors chaque âme sera pleinement rétribuée de ce qu'elle aura acquis. Et ils ne seront point lésés."},{"n":289,"s":2,"a":282,"t":"O les croyants! Quand vous contractez une dette à échéance déterminée, mettez-la en écrit; et qu'un scribe l'écrive, entre vous, en toute justice; un scribe n'a pas à refuser d'écrire selon ce qu'Allah lui a enseigné; qu'il écrive donc, et que dicte le débiteur: qu'il craigne Allah son Seigneur, et se garde d'en rien diminuer. Si le débiteur est gaspilleur ou faible, ou incapable de dicter lui-même, que son représentant dicte alors en toute justice. Faites-en témoigner par deux témoins d'entre vos hommes; et à défaut de deux hommes, un homme et deux femmes d'entre ceux que vous agréez comme témoins, en sorte que si l'une d'elles s'égare, l'autre puisse lui rappeler. Et que les témoins ne refusent pas quand ils sont appelés. Ne vous lassez pas d'écrire la dette, ainsi que son terme, qu'elle soit petite ou grande: c'est plus équitable auprès d'Allah, et plus droit pour le témoignage, et plus susceptible d'écarter les doutes. Mais s'il s'agit d'une marchandise présente que vous négociez entre vous: dans ce cas, il n'y a pas de péché à ne pas l'écrire. Mais prenez des témoins lorsque vous faites une transaction entre vous; et qu'on ne fasse aucun tort à aucun scribe ni à aucun témoin. Si vous le faisiez, cela serait une perversité en vous. Et craignez Allah. Alors Allah vous enseigne et Allah est Omniscient."},{"n":290,"s":2,"a":283,"t":"Mais si vous êtes en voyage et ne trouvez pas de scribe, un gage reçu suffit. S'il y a entre vous une confiance réciproque, que celui à qui on a confié quelque chose la restitue; et qu'il craigne Allah son Seigneur. Et ne cachez pas le témoignage: quiconque le cache a, certes, un cœur pécheur. Allah, de ce que vous faites, est Omniscient."},{"n":291,"s":2,"a":284,"t":"C'est à Allah qu'appartient tout ce qui est dans les cieux et sur la terre. Que vous manifestiez ce qui est en vous ou que vous le cachiez, Allah vous en demandera compte. Puis Il pardonnera à qui Il veut, et châtiera qui Il veut. Et Allah est Omnipotent."},{"n":292,"s":2,"a":285,"t":"Le Messager a cru en ce qu'on a fait descendre vers lui venant de son Seigneur, et aussi les croyants: tous ont cru en Allah, en Ses anges, à Ses livres et en Ses messagers; (en disant): «Nous ne faisons aucune distinction entre Ses messagers». Et ils ont dit: «Nous avons entendu et obéi. Seigneur, nous implorons Ton pardon. C'est à Toi que sera le retour»."},{"n":293,"s":2,"a":286,"t":"Allah n'impose à aucune âme une charge supérieure à sa capacité. Elle sera récompensée du bien qu'elle aura fait, punie du mal qu'elle aura fait. Seigneur, ne nous châtie pas s'il nous arrive d'oublier ou de commettre une erreur. Seigneur! Ne nous charge pas d'un fardeau lourd comme Tu as chargé ceux qui vécurent avant nous. Seigneur! Ne nous impose pas ce que nous ne pouvons supporter, efface nos fautes, pardonne-nous et fais nous miséricorde. Tu es Notre Maître, accorde-nous donc la victoire sur les peuples infidèles."},{"n":294,"s":3,"a":1,"t":"Alif, Lâm, Mîm."},{"n":295,"s":3,"a":2,"t":"Allah! Pas de divinité à part Lui, le Vivant, Celui qui subsiste par Lui-même «Al-Qayyum»."},{"n":296,"s":3,"a":3,"t":"Il a fait descendre sur toi le Livre avec la vérité, confirmant les Livres descendus avant lui. Et Il fit descendre la Thora et l'Evangile."},{"n":297,"s":3,"a":4,"t":"auparavant, en tant que guide pour les gens. Et Il a fait descendre le Discernement. Ceux qui ne croient pas aux Révélations d'Allah auront, certes, un dur châtiment! Et, Allah est Puissant, Détenteur du pouvoir de punir."},{"n":298,"s":3,"a":5,"t":"Rien, vraiment, ne se cache d'Allah de ce qui existe sur la terre ou dans le ciel."},{"n":299,"s":3,"a":6,"t":"C'est Lui qui vous donne forme dans les matrices comme Il veut. Point de divinité à part Lui, le Puissant, le Sage."},{"n":300,"s":3,"a":7,"t":"C'est Lui qui a fait descendre sur toi le Livre: il s'y trouve des versets sans équivoque, qui sont la base du Livre, et d'autres versets qui peuvent prêter à d'interprétations diverses. Les gens, donc, qui ont au cœur une inclination vers l'égarement, mettent l' accent sur les versets à équivoque cherchant la dissension en essayant de leur trouver une interprétation, alors que nul n'en connaît l'interprétation, à part Allah. Mais ceux qui sont bien enracinés dans la science disent: «Nous y croyons: tout est de la part de notre Seigneur!» Mais, seuls les doués d'intelligence s'en rappellent."},{"n":301,"s":3,"a":8,"t":"«Seigneur! Ne laisse pas dévier nos cœurs après que Tu nous aies guidés; et accorde-nous Ta miséricorde. C'est Toi, certes, le Grand Donateur!"},{"n":302,"s":3,"a":9,"t":"Seigneur! C'est Toi qui rassembleras les gens, un jour - en quoi il n'y a point de doute - Allah, vraiment, ne manque jamais à Sa promesse.»"},{"n":303,"s":3,"a":10,"t":"Ceux qui ne croient pas, ni leurs biens ni leurs enfants ne les mettront aucunement à l' abri de la punition d'Allah. Ils seront du combustible pour le Feu,"},{"n":304,"s":3,"a":11,"t":"comme les gens de Pharaon et ceux qui vécurent avant eux. Ils avaient traité de mensonges Nos preuves. Allah les saisit donc, pour leurs péchés. Et Allah est dur en punition."},{"n":305,"s":3,"a":12,"t":"Dis à ceux qui ne croient pas: «Vous serez vaincus bientôt; et vous serez rassemblés vers l'Enfer. Et quel mauvais endroit pour se reposer!»"},{"n":306,"s":3,"a":13,"t":"Il y eut déjà pour vous un signe dans ces deux troupes qui s'affrontèrent: l'une combattait dans le sentier d'Allah; et l'autre, était mécréante. Ces derniers voyaient (les croyants) de leurs propres yeux, deux fois plus nombreux qu'eux-mêmes. Or Allah secourt qui Il veut de Son aide. Voilà bien là un exemple pour les doués de clairvoyance!"},{"n":307,"s":3,"a":14,"t":"On a enjolivé aux gens l'amour des choses qu'ils désirent: femmes, enfants, trésors thésaurisés d'or et d'argent, chevaux marqués, bétail et champs; tout cela est l'objet de jouissance pour la vie présente, alors que c'est près d'Allah qu'il y a bon retour."},{"n":308,"s":3,"a":15,"t":"Dis: «Puis-je vous apprendre quelque chose de meilleur que tout cela? Pour les pieux, il y a, auprès de leur Seigneur, des jardins sous lesquels coulent les ruisseaux, pour y demeurer éternellement, et aussi, des épouses purifiées, et l'agrément d'Allah.» Et Allah est Clairvoyant sur [Ses] serviteurs,"},{"n":309,"s":3,"a":16,"t":"qui disent: «O notre Seigneur, nous avons la foi; pardonne-nous donc nos péchés, et protège-nous du châtiment du Feu»,"},{"n":310,"s":3,"a":17,"t":"ce sont les endurants, les véridiques, les obéissants, ceux qui dépensent [dans le sentier d'Allah] et ceux qui implorent pardon juste avant l'aube."},{"n":311,"s":3,"a":18,"t":"Allah atteste, et aussi les Anges et les doués de science, qu'il n'y a point de divinité à part Lui, le Mainteneur de la justice. Point de divinité à part Lui, le Puissant, le Sage!"},{"n":312,"s":3,"a":19,"t":"Certes, la religion acceptée d'Allah, c'est l'Islam. Ceux auxquels le Livre a été apporté ne se sont disputés, par agressivité entre eux, qu'après avoir reçu la science. Et quiconque ne croit pas aux signes d'Allah... alors Allah est prompt à demander compte!"},{"n":313,"s":3,"a":20,"t":"S'ils te contredisent, dis leur: «Je me suis entièrement soumis à Allah, moi et ceux qui m'ont suivi». Et dis à ceux à qui le Livre a été donné, ainsi qu'aux illettrés: «Avez-vous embrassé l'Islam?» S'ils embrassent l'Islam, ils seront bien guidés. Mais; s'ils tournent le dos... Ton devoir n'est que la transmission (du message). Allah, sur [Ses] serviteurs est Clairvoyant."},{"n":314,"s":3,"a":21,"t":"Ceux qui ne croient pas aux signes d'Allah, tuent sans droit les prophètes et tuent les gens qui commandent la justice, annonce-leur un châtiment douloureux."},{"n":315,"s":3,"a":22,"t":"Ce sont eux dont les œuvres sont devenues vaines, ici-bas comme dans l'au-delà. Et pour eux, pas de secoureurs!"},{"n":316,"s":3,"a":23,"t":"N'as-tu pas vu comment agissent ceux qui ont reçu une part du Livre, et qui sont maintenant invités au Livre d'Allah pour trancher leurs différends; comment un groupe des leurs tourne le dos et s'esquive?"},{"n":317,"s":3,"a":24,"t":"C'est parce qu'ils disent: «Le Feu ne nous touchera que pour un nombre de jours déterminés.» Et leurs mensonges les trompent en religion."},{"n":318,"s":3,"a":25,"t":"Eh bien comment seront-ils, quand Nous les aurons rassemblés, en un jour sur quoi il n'y a point de doute, et que chaque âme sera pleinement rétribuée selon ce qu'elle aura acquis? Et ils ne seront point lésés."},{"n":319,"s":3,"a":26,"t":"- Dis: «O Allah, Maître de l'autorité absolue. Tu donnes l'autorité à qui Tu veux, et Tu arraches l'autorité à qui Tu veux; et Tu donnes la puissance à qui Tu veux, et Tu humilies qui Tu veux. Le bien est en Ta main et Tu es Omnipotent."},{"n":320,"s":3,"a":27,"t":"Tu fais pénétrer la nuit dans le jour, et Tu fais pénétrer le jour dans la nuit, et Tu fais sortir le vivant du mort, et Tu fais sortir le mort du vivant. Et Tu accordes attribution à qui Tu veux, sans compter»."},{"n":321,"s":3,"a":28,"t":"Que les croyants ne prennent pas, pour alliés, des infidèles, au lieu de croyants. Quiconque le fait contredit la religion d'Allah, à moins que vous ne cherchiez à vous protéger d'eux. Allah vous met en garde à l'égard de Lui-même. Et c'est à Allah le retour."},{"n":322,"s":3,"a":29,"t":"Dis: «Que vous cachiez ce qui est dans vos poitrines ou bien vous le divulguiez, Allah le sait. Il connaît tout ce qui est dans les cieux et sur la terre. Et Allah est Omnipotent."},{"n":323,"s":3,"a":30,"t":"Le jour où chaque âme se trouvera confrontée avec ce qu'elle aura fait de bien et ce qu'elle aura fait de mal; elle souhaitera qu'il y ait entre elle et ce mal une longue distance! Allah vous met en garde à l'égard de Lui-même. Allah est Compatissant envers [Ses] serviteurs."},{"n":324,"s":3,"a":31,"t":"Dis: «Si vous aimez vraiment Allah, suivez-moi, Allah vous aimera alors et vous pardonnera vos péchés. Allah est Pardonneur et Miséricordieux."},{"n":325,"s":3,"a":32,"t":"Dis: «Obéissez à Allah et au Messager. Et si vous tournez le dos... alors Allah n'aime pas les infidèles!"},{"n":326,"s":3,"a":33,"t":"Certes, Allah a élu Adam, Noé, la famille d'Abraham et la famille d''Imran au-dessus de tout le monde."},{"n":327,"s":3,"a":34,"t":"En tant que descendants les uns des autres, et Allah est Audient et Omniscient."},{"n":328,"s":3,"a":35,"t":"(Rappelle-toi) quand la femme de 'Imran dit: «Seigneur, je T'ai voué en toute exclusivité ce qui est dans mon ventre. Accepte-le donc, de moi. C'est Toi certes l' Audient et l'Omniscient."},{"n":329,"s":3,"a":36,"t":"Puis, lorsqu'elle en eut accouché, elle dit: «Seigneur, voilà que j'ai accouché d'une fille» or Allah savait mieux ce dont elle avait accouché! Le garçon n'est pas comme la fille. «Je l'ai nommée Marie, et je la place, ainsi que sa descendance, sous Ta protection contre le Diable, le banni»."},{"n":330,"s":3,"a":37,"t":"Son Seigneur l'agréa alors du bon agrément, la fit croître en belle croissance. Et Il en confia la garde à Zacharie. Chaque fois que celui-ci entrait auprès d'elle dans le Sanctuaire, il trouvait près d'elle de la nourriture. Il dit: «O Marie, d'où te vient cette nourriture?» - Elle dit: «Cela me vient d'Allah». Il donne certes la nourriture à qui Il veut sans compter."},{"n":331,"s":3,"a":38,"t":"Alors, Zacharie pria son Seigneur, et dit: «O mon Seigneur, donne-moi, venant de Toi, une excellente descendance. Car Tu es Celui qui entend bien la prière»."},{"n":332,"s":3,"a":39,"t":"Alors, les Anges l'appelèrent pendant que, debout, il priait dans le Sanctuaire: «Voilà qu'Allah t'annonce la naissance de Yahya, confirmateur d'une parole d'Allah. Il sera un chef, un chaste, un prophète et du nombre des gens de bien»."},{"n":333,"s":3,"a":40,"t":"Il dit: «O mon Seigneur, comment aurais-je un garçon maintenant que la vieillesse m'a atteint et que ma femme est stérile?» Allah dit: «Comme cela!», Allah fait ce qu'Il veut."},{"n":334,"s":3,"a":41,"t":"- «Seigneur, dit Zacharie, donne-moi un signe.» - «Ton signe, dit Allah, c'est que pendant trois jours tu ne pourras parler aux gens que par geste. Invoque beaucoup Ton Seigneur; et, glorifie-Le, en fin et en début de journée.»"},{"n":335,"s":3,"a":42,"t":"(Rappelle-toi) quand les Anges dirent: «O Marie, certes Allah t'a élue et purifiée; et Il t'a élue au-dessus des femmes des mondes."},{"n":336,"s":3,"a":43,"t":"«O Marie, obéis à Ton Seigneur, prosterne-toi, et incline-toi avec ceux qui s'inclinent»."},{"n":337,"s":3,"a":44,"t":"- Ce sont là des nouvelles de l'Inconnaissable que Nous te révélons. Car tu n'étais pas là lorsqu'ils jetaient leurs calames pour décider qui se chargerait de Marie! Tu n'étais pas là non plus lorsqu'ils se disputaient!"},{"n":338,"s":3,"a":45,"t":"(Rappelle-toi) quand les Anges dirent: «O Marie, voilà qu'Allah t'annonce une parole de Sa part: son nom sera «Al-Masîh», «'Issâ», fils de Marie, illustre ici-bas comme dans l'au-delà, et l'un des rapprochés d'Allah»."},{"n":339,"s":3,"a":46,"t":"Il parlera aux gens, dans le berceau et en son âge mûr et il sera du nombre des gens de bien»."},{"n":340,"s":3,"a":47,"t":"- Elle dit: «Seigneur! Comment aurais-je un enfant, alors qu'aucun homme ne m'a touchée?» - «C'est ainsi!» dit-Il. Allah crée ce qu'Il veut. Quand Il décide d'une chose, Il lui dit seulement: «Sois» et elle est aussitôt."},{"n":341,"s":3,"a":48,"t":"Et (Allah) lui enseignera l'écriture, la sagesse, la Thora et l'Evangile,"},{"n":342,"s":3,"a":49,"t":"et Il sera le messager aux enfants d'Israël, [et leur dira]: «En vérité, je viens à vous avec un signe de la part de votre Seigneur. Pour vous, je forme de la glaise comme la figure d'un oiseau, puis je souffle dedans: et, par la permission d'Allah, cela devient un oiseau. Et je guéris l'aveugle-né et le lépreux, et je ressuscite les morts, par la permission d'Allah. Et je vous apprends ce que vous mangez et ce que vous amassez dans vos maisons. Voilà bien là un signe, pour vous, si vous êtes croyants!"},{"n":343,"s":3,"a":50,"t":"Et je confirme ce qu'il y a dans la Thora révélée avant moi, et je vous rends licite une partie de ce qui vous était interdit. Et j'ai certes apporté un signe de votre Seigneur. Craignez Allah donc, et obéissez-moi."},{"n":344,"s":3,"a":51,"t":"Allah est mon Seigneur et votre Seigneur. Adorez-Le donc: voilà le chemin droit.»"},{"n":345,"s":3,"a":52,"t":"Puis, quand Jésus ressentit de l'incrédulité, de leur part, il dit: «Qui sont mes alliés dans la voie d'Allah?» Les apôtres dirent: «Nous sommes les alliés d'Allah. Nous croyons en Allah. Et sois témoin que nous lui sommes soumis."},{"n":346,"s":3,"a":53,"t":"Seigneur! Nous avons cru à ce que Tu as fait descendre et suivi le messager. Inscris-nous donc parmi ceux qui témoignent»."},{"n":347,"s":3,"a":54,"t":"Et ils [les autres] se mirent à comploter. Allah a fait échouer leur complot. Et c'est Allah qui sait le mieux leur machination!"},{"n":348,"s":3,"a":55,"t":"(Rappelle-toi) quand Allah dit: «O Jésus, certes, Je vais mettre fin à ta vie terrestre t'élever vers Moi, te débarrasser de ceux qui n'ont pas cru et mettre jusqu'au Jour de la Résurrection, ceux qui te suivent au-dessus de ceux qui ne croient pas. Puis, c'est vers Moi que sera votre retour, et Je jugerai, entre vous, ce sur quoi vous vous opposiez."},{"n":349,"s":3,"a":56,"t":"Quant à ceux qui n'ont pas cru, Je les châtierai d'un dur châtiment, ici-bas tout comme dans l'au-delà; et pour eux, pas de secoureurs."},{"n":350,"s":3,"a":57,"t":"Et quant à ceux qui ont la foi et font de bonnes œuvres, Il leur donnera leurs récompenses. Et Allah n'aime pas les injustes."},{"n":351,"s":3,"a":58,"t":"Voilà ce que Nous te récitons des versets et de la révélation précise."},{"n":352,"s":3,"a":59,"t":"Pour Allah, Jésus est comme Adam qu'Il créa de poussière, puis Il lui dit: «Sois»: et il fut."},{"n":353,"s":3,"a":60,"t":"La vérité vient de ton Seigneur. Ne sois donc pas du nombre des sceptiques."},{"n":354,"s":3,"a":61,"t":"A ceux qui te contredisent à son propos, maintenant que tu en es bien informé, tu n'as qu'à dire: «Venez, appelons nos fils et les vôtres, nos femmes et les vôtres, nos propres personnes et les vôtres, puis proférons exécration réciproque en appelant la malédiction d'Allah sur les menteurs."},{"n":355,"s":3,"a":62,"t":"Voilà, certes, le récit véridique. Et il n'y a pas de divinité à part Allah. En vérité, c'est Allah qui est le Puissant, le Sage."},{"n":356,"s":3,"a":63,"t":"Si donc ils tournent le dos... alors Allah connaît bien les semeurs de corruption!"},{"n":357,"s":3,"a":64,"t":"- Dis: «O gens du Livre, venez à une parole commune entre nous et vous: que nous n'adorions qu'Allah, sans rien Lui associer, et que nous ne prenions point les uns les autres pour seigneurs en dehors d'Allah». Puis, s'ils tournent le dos, dites: «Soyez témoins que nous, nous sommes soumis»."},{"n":358,"s":3,"a":65,"t":"O gens du Livre, pourquoi disputez-vous au sujet d'Abraham, alors que la Thora et l'Evangile ne sont descendus qu'après lui? Ne raisonnez-vous donc pas?"},{"n":359,"s":3,"a":66,"t":"Vous avez bel et bien disputé à propos d'une chose dont vous avez connaissance. Mais pourquoi disputez-vous des choses dont vous n'avez pas connaissance? Or Allah sait, tandis que vous ne savez pas."},{"n":360,"s":3,"a":67,"t":"Abraham n'était ni Juif ni Chrétien. Il était entièrement soumis à Allah (Musulman). Et il n'était point du nombre des Associateurs."},{"n":361,"s":3,"a":68,"t":"Certes les hommes les plus dignes de se réclamer d'Abraham, sont ceux qui l'ont suivi, ainsi que ce Prophète-ci, et ceux qui ont la foi. Et Allah est l'allié des croyants."},{"n":362,"s":3,"a":69,"t":"Une partie des gens du Livre aurait bien voulu vous égarer. Or ils n'égarent qu'eux-mêmes; et ils n'en sont pas conscients."},{"n":363,"s":3,"a":70,"t":"O gens du Livre, pourquoi ne croyez vous pas aux versets d'Allah (le Coran), cependant que vous en êtes témoins?"},{"n":364,"s":3,"a":71,"t":"O gens du Livre, pourquoi mêlez-vous le faux au vrai et cachez-vous sciemment la vérité?"},{"n":365,"s":3,"a":72,"t":"Ainsi dit une partie des gens du Livre: «Au début du jour, croyez à ce qui a été révélé aux Musulmans, mais, à la fin du jour, rejetez-le, afin qu'ils retournent (à leur ancienne religion)."},{"n":366,"s":3,"a":73,"t":"[Et les gens du Livre disent à leurs coreligionnaires]: «Ne croyez que ceux qui suivent votre religion...» Dis: «La vraie direction est la direction d'Allah» - [et ils disent encore: Vous ne devez ni approuver ni reconnaître] que quelqu'un d'autre que vous puisse recevoir comme ce que vous avez reçu de sorte qu'ils (les musulmans) ne puissent argumenter contre vous auprès de votre Seigneur. Dis-[leur]: En vérité, la grâce est en la main d'Allah. Il la donne à qui Il veut. La grâce d'Allah est immense et Il est Omniscient."},{"n":367,"s":3,"a":74,"t":"Il réserve à qui Il veut sa miséricorde. Et Allah est Détenteur d'une grâce immense."},{"n":368,"s":3,"a":75,"t":"Et parmi les gens du Livre, il y en a qui, si tu lui confies un qintâr, te le rend. Mais il y en a aussi qui, si tu lui confies un dinâr, ne te le rendra que si tu l'y contrains sans relâche. Tout cela parce qu'ils disent: «Ces (arabes) qui n'ont pas de livre n'ont aucun chemin pour nous contraindre.» Ils profèrent des mensonges contre Allah alors qu'ils savent."},{"n":369,"s":3,"a":76,"t":"Au contraire, quiconque remplit sa promesse et craint Allah... Allah aime les pieux."},{"n":370,"s":3,"a":77,"t":"Ceux qui vendent à vil prix leur engagement avec Allah ainsi que leurs serments n'auront aucune part dans l'au-delà, et Allah ne leur parlera pas, ni les regardera, au Jour de la Résurrection, ni ne les purifiera; et ils auront un châtiment douloureux."},{"n":371,"s":3,"a":78,"t":"Et il y a parmi eux certains qui roulent leurs langues en lisant le Livre pour vous faire croire que cela provient du Livre, alors qu'il n'est point du Livre; et ils disent: «Ceci vient d'Allah, alors qu'il ne vient point d'Allah. Ils disent sciemment des mensonges contre Allah."},{"n":372,"s":3,"a":79,"t":"Il ne conviendrait pas à un être humain à qui Allah a donné le Livre, la Compréhension et la Prophétie, de dire ensuite aux gens: «Soyez mes adorateurs, à l'exclusion d'Allah; mais au contraire, [il devra dire]: «Devenez des savants, obéissant au Seigneur, puisque vous enseignez le Livre et vous l'étudiez»."},{"n":373,"s":3,"a":80,"t":"Et il ne va pas vous commander de prendre pour seigneurs anges et prophètes. Vous commanderait-il de rejeter la foi, vous qui êtes Musulmans?"},{"n":374,"s":3,"a":81,"t":"Et lorsqu'Allah prit cet engagement des prophètes: «Chaque fois que Je vous accorderai un Livre et de la Sagesse, et qu'ensuite un messager vous viendra confirmer ce qui est avec vous, vous devez croire en lui, et vous devrez lui porter secours.» Il leur dit: «Consentez-vous et acceptez-vous Mon pacte à cette condition?» - «Nous consentons», dirent-ils. «Soyez-en donc témoins, dit Allah. Et Me voici, avec vous, parmi les témoins."},{"n":375,"s":3,"a":82,"t":"Quiconque ensuite tournera le dos... alors ce sont eux qui seront les pervers»."},{"n":376,"s":3,"a":83,"t":"Désirent-ils une autre religion que celle d'Allah, alors que se soumet à Lui, bon gré, mal gré, tout ce qui existe dans les cieux et sur la terre, et que c'est vers Lui qu'ils seront ramenés?"},{"n":377,"s":3,"a":84,"t":"Dis: «Nous croyons en Allah, à ce qu'on a fait descendre sur nous, à ce qu'on a fait descendre sur Abraham, Ismaël, Isaac, Jacob et les Tribus, et à ce qui a été apporté à Moïse, à Jésus et aux prophètes, de la part de leur Seigneur: nous ne faisons aucune différence entre eux; et c'est à Lui que nous sommes Soumis»."},{"n":378,"s":3,"a":85,"t":"Et quiconque désire une religion autre que l'Islam, ne sera point agréé, et il sera, dans l'au-delà, parmi les perdants."},{"n":379,"s":3,"a":86,"t":"Comment Allah guiderait-Il des gens qui n'ont plus la foi après avoir cru et témoigné que le Messager est véridique, et après que les preuves leur sont venues? Allah ne guide pas les gens injustes."},{"n":380,"s":3,"a":87,"t":"Ceux là, leur rétribution sera qu'ils auront sur eux la malédiction d'Allah, des Anges et de tous les êtres humains."},{"n":381,"s":3,"a":88,"t":"Ils y demeureront éternellement. Le châtiment ne leur sera pas allégé, et ils n'auront aucun répit,"},{"n":382,"s":3,"a":89,"t":"excepté ceux qui par la suite se repentiront et se réformeront: car Allah est certes Pardonneur et Miséricordieux."},{"n":383,"s":3,"a":90,"t":"En vérité, ceux qui ne croient plus après avoir eu la foi, et laissent augmenter encore leur mécréance, leur repentir ne sera jamais accepté. Ceux-là sont vraiment les égarés."},{"n":384,"s":3,"a":91,"t":"Ceux qui ne croient pas et qui meurent mécréants, il ne sera jamais accepté, d'aucun d'eux de se racheter même si pour cela il (donnait) le contenu, en or, de la terre. Ils auront un châtiment douloureux, et ils n'auront point de secoureurs."},{"n":385,"s":3,"a":92,"t":"Vous n'atteindrez la (vraie) piété, que si vous faites largesses de ce que vous chérissez. Tout ce dont vous faites largesses, Allah le sait certainement bien."},{"n":386,"s":3,"a":93,"t":"Toute nourriture était licite aux enfants d'Israël, sauf celle qu'Israël lui-même s'interdit avant que ne descendît la Thora. Dis-[leur]: «Apportez la Thora et lisez-la, si ce que vous dites est vrai!»"},{"n":387,"s":3,"a":94,"t":"Donc, quiconque, après cela, invente des mensonges contre Allah... ceux-là sont, donc, les vrais injustes."},{"n":388,"s":3,"a":95,"t":"Dis: «C'est Allah qui dit la vérité. Suivez donc la religion d'Abraham, Musulman droit. Et il n'était point des associateurs»."},{"n":389,"s":3,"a":96,"t":"La première Maison qui ait été édifiée pour les gens, c'est bien celle de Bakka (la Mecque) bénie et une bonne direction pour l'univers."},{"n":390,"s":3,"a":97,"t":"Là sont des signes évidents, parmi lesquels l'endroit où Abraham s'est tenu debout; et quiconque y entre est en sécurité. Et c'est un devoir envers Allah pour les gens qui ont les moyens, d'aller faire le pèlerinage de la Maison. Et quiconque ne croit pas... Allah Se passe largement des mondes."},{"n":391,"s":3,"a":98,"t":"- Dis: «O gens du Livre, pourquoi ne croyez-vous pas aux versets d'Allah (al-Qur'ân), alors qu'Allah est témoin de ce que vous faites?»"},{"n":392,"s":3,"a":99,"t":"- Dis: «O gens du Livre, pourquoi obstruez-vous la voie d'Allah à celui qui a la foi, et pourquoi voulez-vous rendre cette voie tortueuse, alors que vous êtes témoins de la vérité!» Et Allah n'est pas inattentif à ce que vous faites."},{"n":393,"s":3,"a":100,"t":"O les croyants! Si vous obéissez à un groupe de ceux auxquels on a donné le Livre, il vous rendra mécréants après que vous ayez eu la foi."},{"n":394,"s":3,"a":101,"t":"Et comment pouvez-vous ne pas croire, alors que les versets d'Allah vous sont récités, et qu'au milieu de vous se tient Son messager? Quiconque s'attache fortement à Allah, il est certes guidé vers un droit chemin."},{"n":395,"s":3,"a":102,"t":"O les croyants! Craignez Allah comme Il doit être craint. Et ne mourez qu'en pleine soumission."},{"n":396,"s":3,"a":103,"t":"Et cramponnez-vous tous ensemble au «Habl» (câble) d'Allah et ne soyez pas divisés; et rappelez-vous le bienfait d'Allah sur vous: lorsque vous étiez ennemis, c'est Lui qui réconcilia vos cœurs. Puis, par Son bienfait, vous êtes devenus frères. Et alors que vous étiez au bord d'un abîme de Feu, c'est Lui qui vous en a sauvés. Ainsi Allah vous montre Ses signes afin que vous soyez bien guidés."},{"n":397,"s":3,"a":104,"t":"Que soit issue de vous une communauté qui appelle au bien, ordonne le convenable, et interdit le blâmable. Car ce seront eux qui réussiront."},{"n":398,"s":3,"a":105,"t":"Et ne soyez pas comme ceux qui se sont divisés et se sont mis à disputer, après que les preuves leur furent venues, et ceux-là auront un énorme châtiment."},{"n":399,"s":3,"a":106,"t":"Au jour où certains visages s'éclaireront, et que d'autres s'assombriront. A ceux dont les visages seront assombris (il sera dit): «avez-vous mécru après avoir eu la foi?» Eh bien, goûtez au châtiment, pour avoir renié la foi."},{"n":400,"s":3,"a":107,"t":"Et quant à ceux dont les visages s'éclaireront, ils seront dans la miséricorde d'Allah, où ils demeureront éternellement."},{"n":401,"s":3,"a":108,"t":"Tels sont les versets d'Allah; Nous te (Muhammad) les récitons avec vérité. Et Allah ne veut point léser les mondes."},{"n":402,"s":3,"a":109,"t":"A Allah appartient tout ce qui est dans les cieux et sur la terre. Et c'est vers Allah que toute chose sera ramenée."},{"n":403,"s":3,"a":110,"t":"Vous êtes la meilleure communauté, qu'on ait fait surgir pour les hommes. Vous ordonnez le convenable, interdisez le blâmable et croyez à Allah. Si les gens du Livre croyaient, ce serait meilleur pour eux, il y en a qui ont la foi, mais la plupart d'entre eux sont des pervers."},{"n":404,"s":3,"a":111,"t":"Ils ne sauront jamais vous causer de grand mal, seulement une nuisance (par la langue); et s'ils vous combattent, ils vous tourneront le dos, et ils n'auront alors point de secours."},{"n":405,"s":3,"a":112,"t":"Où qu'ils se trouvent, ils sont frappés d'avilissement, à moins d'un secours providentiel d'Allah ou d'un pacte conclu avec les hommes. Ils ont encouru la colère d'Allah, et les voilà frappés de malheur, pour n'avoir pas cru aux signes d'Allah, et assassiné injustement les prophètes, et aussi pour avoir désobéi et transgressé."},{"n":406,"s":3,"a":113,"t":"Mais ils ne sont pas tous pareils. Il est, parmi les gens du Livre, une communauté droite qui, aux heures de la nuit, récite les versets d'Allah en se prosternant."},{"n":407,"s":3,"a":114,"t":"Ils croient en Allah et au Jour dernier, ordonnent le convenable, interdisent le blâmable et concourent aux bonnes œuvres. Ceux-là sont parmi les gens de bien."},{"n":408,"s":3,"a":115,"t":"Et quelque bien qu'ils fassent, il ne leur sera pas dénié. Car Allah connaît bien les pieux."},{"n":409,"s":3,"a":116,"t":"Quant à ceux qui ne croient pas, ni leurs biens, ni leurs enfants ne pourront jamais leur servir contre la punition d'Allah. Et ce sont les gens du Feu: ils y demeureront éternellement."},{"n":410,"s":3,"a":117,"t":"Ce qu'ils dépensent dans la vie présente ressemble à un vent glacial qui s'abat sur un champ appartenant à des gens qui se sont lésés eux-mêmes, et le détruit. Car ce n'est pas Allah qui leur cause du mal, mais ils se font du mal à eux-mêmes."},{"n":411,"s":3,"a":118,"t":"O les croyants, ne prenez pas de confidents en dehors de vous-mêmes: ils ne failliront pas à vous bouleverser. Ils souhaiteraient que vous soyez en difficulté. La haine certes s'est manifestée dans leurs bouches, mais ce que leurs poitrines cachent est encore plus énorme. Voilà que Nous vous exposons les signes. Si vous pouviez raisonner!"},{"n":412,"s":3,"a":119,"t":"Vous, (Musulmans) vous les aimez, alors qu'ils ne vous aiment pas; et vous avez foi dans le Livre tout entier. Et lorsqu'ils vous rencontrent, ils disent: «Nous croyons» et une fois seuls, de rage contre vous, ils se mordent les bouts des doigts. Dis: «mourez de votre rage». En vérité, Allah connaît fort bien le contenu des cœurs."},{"n":413,"s":3,"a":120,"t":"Qu'un bien vous touche, ils s'en affligent. Qu'un mal vous atteigne, ils s'en réjouissent. Mais si vous êtes endurants et pieux, leur manigance ne vous causera aucun mal. Allah connaît parfaitement tout ce qu'ils font."},{"n":414,"s":3,"a":121,"t":"Lorsqu'un matin, tu (Muhammad) quittas ta famille, pour assigner aux croyants les postes de combat et Allah est Audient et Omniscient."},{"n":415,"s":3,"a":122,"t":"Quand deux de vos groupes songèrent à fléchir! Alors qu'Allah est leur allié à tous deux! Car, c'est en Allah que les croyants doivent placer leur confiance."},{"n":416,"s":3,"a":123,"t":"Allah vous a donné la victoire, à Badr, alors que vous étiez humiliés. Craignez Allah donc. Afin que vous soyez reconnaissants!"},{"n":417,"s":3,"a":124,"t":"(Allah vous a bien donné la victoire) lorsque tu disais aux croyants; «Ne vous suffit-il pas que votre Seigneur vous fasse descendre en aide trois milliers d'Anges?»"},{"n":418,"s":3,"a":125,"t":"Mais oui! Si vous êtes endurants et pieux, et qu'ils [les ennemis] vous assaillent immédiatement, votre Seigneur vous enverra en renfort cinq mille Anges marqués distinctement."},{"n":419,"s":3,"a":126,"t":"Et Allah ne le fit que (pour vous annoncer) une bonne nouvelle, et pour que vos cœurs s'en rassurent. La victoire ne peut venir que d'Allah, le Puissant, le Sage;"},{"n":420,"s":3,"a":127,"t":"pour anéantir une partie des mécréants ou pour les humilier (par la défaite) et qu'ils en retournent donc déçus."},{"n":421,"s":3,"a":128,"t":"- Tu n'as (Muhammad) aucune part dans l'ordre (divin) - qu'Il (Allah) accepte leur repentir (en embrassant l'Islam) ou qu'Il les châtie, car ils sont bien des injustes."},{"n":422,"s":3,"a":129,"t":"A Allah appartient tout ce qui est dans les cieux et sur la terre. Il pardonne à qui Il veut, et Il châtie qui Il veut... Et Allah est Pardonneur et Miséricordieux."},{"n":423,"s":3,"a":130,"t":"O les croyants! Ne pratiquez pas l'usure en multipliant démesurément votre capital. Et craignez Allah afin que vous réussissiez!"},{"n":424,"s":3,"a":131,"t":"Et craignez le Feu préparé pour les mécréants."},{"n":425,"s":3,"a":132,"t":"Et obéissez à Allah et au Messager afin qu'il vous soit fait miséricorde!"},{"n":426,"s":3,"a":133,"t":"Et concourez au pardon de votre Seigneur, et à un Jardin (paradis) large comme les cieux et la terre, préparé pour les pieux,"},{"n":427,"s":3,"a":134,"t":"qui dépensent dans l'aisance et dans l'adversité, qui dominent leur rage et pardonnent à autrui - car Allah aime les bienfaisants -"},{"n":428,"s":3,"a":135,"t":"et pour ceux qui, s'ils ont commis quelque turpitude ou causé quelque préjudice à leurs propres âmes (en désobéissant à Allah), se souviennent d'Allah et demandent pardon pour leurs péchés - et qui est-ce qui pardonne les péchés sinon Allah? - et qui ne persistent pas sciemment dans le mal qu'ils ont fait."},{"n":429,"s":3,"a":136,"t":"Ceux-là ont pour récompense le pardon de leur Seigneur, ainsi que les Jardins sous lesquels coulent les ruisseaux, pour y demeurer éternellement. Comme est beau le salaire de ceux qui font le bien!"},{"n":430,"s":3,"a":137,"t":"Avant vous, certes, beaucoup d'événements se sont passés. Or, parcourez la terre, et voyez ce qu'il est advenu de ceux qui traitaient (les prophètes) de menteurs."},{"n":431,"s":3,"a":138,"t":"Voilà un exposé pour les gens, un guide, et une exhortation pour les pieux."},{"n":432,"s":3,"a":139,"t":"Ne vous laissez pas battre, ne vous affligez pas alors que vous êtes les supérieurs, si vous êtes de vrais croyants."},{"n":433,"s":3,"a":140,"t":"Si une blessure vous atteint, pareille blessure atteint aussi l'ennemi. Ainsi faisons-Nous alterner les jours (bons et mauvais) parmi les gens, afin qu'Allah reconnaisse ceux qui ont cru, et qu'Il choisisse parmi vous des martyrs - et Allah n'aime pas les injustes,"},{"n":434,"s":3,"a":141,"t":"et afin qu'Allah purifie ceux qui ont cru, et anéantisse les mécréants."},{"n":435,"s":3,"a":142,"t":"Comptez-vous entrer au Paradis sans qu'Allah ne distingue parmi vous ceux qui luttent et qui sont endurants?"},{"n":436,"s":3,"a":143,"t":"Bien sûr, vous souhaitiez la mort avant de la rencontrer. Or vous l'avez vue, certes, tandis que vous regardiez!"},{"n":437,"s":3,"a":144,"t":"Muhammad n'est qu'un messager - des messagers avant lui sont passés -. S'il mourait, donc, ou s'il était tué, retourneriez-vous sur vos talons? Quiconque retourne sur ses talons ne nuira en rien à Allah; et Allah récompensera bientôt les reconnaissants."},{"n":438,"s":3,"a":145,"t":"Personne ne peut mourir que par la permission d'Allah, et au moment prédéterminé. Quiconque veut la récompense d'ici-bas, Nous lui en donnons. Quiconque veut la récompense de l'au-delà, Nous lui en donnons, et Nous récompenserons bientôt les reconnaissants."},{"n":439,"s":3,"a":146,"t":"Combien de prophètes ont combattu, en compagnie de beaucoup de disciples, ceux-ci ne fléchirent pas à cause de ce qui les atteignit dans le sentier d'Allah. Ils ne faiblirent pas et ils ne cédèrent point. Et Allah aime les endurants."},{"n":440,"s":3,"a":147,"t":"Et ils n'eurent que cette parole: «Seigneur, pardonne-nous nos péchés ainsi que nos excès dans nos comportements, affermis nos pas et donne-nous la victoire sur les gens mécréants»."},{"n":441,"s":3,"a":148,"t":"Allah, donc, leur donna la récompense d'ici-bas, ainsi que la belle récompense de l'au-delà. Et Allah aime les gens bienfaisants."},{"n":442,"s":3,"a":149,"t":"O les croyants! Si vous obéissez à ceux qui ne croient pas, ils vous feront retourner en arrière. Et vous reviendrez perdants."},{"n":443,"s":3,"a":150,"t":"Mais c'est Allah votre Maître. Il est le meilleur des secoureurs."},{"n":444,"s":3,"a":151,"t":"Nous allons jeter l'effroi dans les cœurs des mécréants. Car ils ont associé à Allah (des idoles) sans aucune preuve descendue de Sa part. Le Feu sera leur refuge. Quel mauvais séjour, que celui des injustes!"},{"n":445,"s":3,"a":152,"t":"Et certes, Allah a tenu Sa promesse envers vous, quand par Sa permission vous les tuiez sans relâche, jusqu'au moment où vous avez fléchi, où vous vous êtes disputés à propos de l'ordre donné, et vous avez désobéi après qu'Il vous eut montré (la victoire) que vous aimez! Il en était parmi vous qui désiraient la vie d'ici-bas et il en était parmi vous qui désiraient l'au-delà. Puis Il vous a fait reculer devant eux, afin de vous éprouver. Et certes Il vous a pardonné. Et Allah est Détenteur de la grâce envers les croyants."},{"n":446,"s":3,"a":153,"t":"(Rappelez-vous) quand vous fuyiez sans vous retourner vers personne, cependant que, derrière vous, le Messager vous appelait. Alors Il vous infligea angoisse sur angoisse, afin que vous n'ayez pas de chagrin pour ce qui vous a échappé ni pour les revers que vous avez subis. Et Allah est Parfaitement Connaisseur de ce que vous faites."},{"n":447,"s":3,"a":154,"t":"Puis Il fit descendre sur vous, après l'angoisse, la tranquillité, un sommeil qui enveloppa une partie d'entre vous, tandis qu'une autre partie était soucieuse pour elle-même et avait des pensées sur Allah non conformes à la vérité, des pensées dignes de l'époque de l'Ignorance. - Ils disaient: «Est-ce que nous avons une part dans cette affaire?» Dis: «L'affaire toute entière est à Allah.» Ce qu'ils ne te révèlent pas, ils le cachent en eux-mêmes: «Si nous avions eu un choix quelconque dans cette affaire, disent-ils, Nous n'aurions pas été tués ici.» Dis: «Eussiez-vous été dans vos maisons, ceux pour qui la mort était décrétée seraient sortis pour l'endroit où la mort les attendait. Ceci afin qu'Allah éprouve ce que vous avez dans vos poitrines, et qu'Il purifie ce que vous avez dans vos cœurs. Et Allah connaît ce qu'il y a dans les cœurs."},{"n":448,"s":3,"a":155,"t":"Ceux d'entre vous qui ont tourné le dos, le jour où les deux armées se rencontrèrent, c'est seulement le Diable qui les a fait broncher, à cause d'une partie de leurs (mauvaises) actions. Mais, certes, Allah leur a pardonné. Car vraiment Allah est Pardonneur et Indulgent!"},{"n":449,"s":3,"a":156,"t":"O les croyants! Ne soyez pas comme ces mécréants qui dirent à propos de leurs frères partis en voyage ou pour combattre: «S'ils étaient chez nous, ils ne seraient pas morts, et ils n'auraient pas été tués.» Allah en fit un sujet de regret dans leurs cœurs. C'est Allah qui donne la vie et la mort. Et Allah observe bien ce que vous faites."},{"n":450,"s":3,"a":157,"t":"Et si vous êtes tués dans le sentier d'Allah ou si vous mourez, un pardon de la part d'Allah et une miséricorde valent mieux que ce qu'ils amassent."},{"n":451,"s":3,"a":158,"t":"Que vous mouriez ou que vous soyez tués, c'est vers Allah que vous serez rassemblés."},{"n":452,"s":3,"a":159,"t":"C'est par quelque miséricorde de la part d'Allah que tu (Muhammad) as été si doux envers eux! Mais si tu étais rude, au cœur dur, ils se seraient enfuis de ton entourage. Pardonne-leur donc, et implore pour eux le pardon (d'Allah). Et consulte-les à propos des affaires; puis une fois que tu t'es décidé, confie-toi donc à Allah, Allah aime, en vérité, ceux qui Lui font confiance."},{"n":453,"s":3,"a":160,"t":"Si Allah vous donne Son secours, nul ne peut vous vaincre. S'Il vous abandonne, qui donc après Lui vous donnera secours? C'est à Allah que les croyants doivent faire confiance."},{"n":454,"s":3,"a":161,"t":"Un prophète n'est pas quelqu'un à s'approprier du butin. Quiconque s'en approprie, viendra avec ce qu'il se sera approprié le Jour de la Résurrection. Alors, à chaque individu on rétribuera pleinement ce qu'il aura acquis. Et ils ne seront point lésés."},{"n":455,"s":3,"a":162,"t":"Est-ce que celui qui se conforme à l'agrément d'Allah ressemble à celui qui encourt le courroux d'Allah? Son refuge sera l'Enfer; et quelle mauvaise destination!"},{"n":456,"s":3,"a":163,"t":"Ils ont des grades (différents) auprès d'Allah et Allah observe bien ce qu'ils font."},{"n":457,"s":3,"a":164,"t":"Allah a très certainement fait une faveur aux croyants lorsqu'Il a envoyé chez eux un messager de parmi eux-mêmes, qui leur récite Ses versets, les purifie et leur enseigne le Livre et la Sagesse, bien qu'ils fussent auparavant dans un égarement évident."},{"n":458,"s":3,"a":165,"t":"Quoi! Quand un malheur vous atteint - mais vous en avez jadis infligé le double - vous dites: «D'où vient cela?» Réponds-leur: «Il vient de vous-mêmes». Certes Allah est Omnipotent."},{"n":459,"s":3,"a":166,"t":"Et tout ce que vous avez subi, le jour où les deux troupes se rencontrèrent, c'est par permission d'Allah, et afin qu'Il distingue les croyants,"},{"n":460,"s":3,"a":167,"t":"et qu'Il distingue les hypocrites. On avait dit à ceux-ci: «Venez combattre dans le sentier d'Allah, ou repoussez [l'ennemi»], ils dirent: «Bien sûr que nous vous suivrions si nous étions sûrs qu'il y aurait une guerre.» Ils étaient, ce jour-là, plus près de la mécréance que de la foi. Ils disaient de leurs bouches ce qui n'était pas dans leurs cœurs. Et Allah sait fort bien ce qu'ils cachaient."},{"n":461,"s":3,"a":168,"t":"Ceux qui sont restés dans leurs foyers dirent à leurs frères: «S'ils nous avaient obéi, ils n'auraient pas été tués.» Dis: «Ecartez donc de vous la mort, si vous êtes véridiques»."},{"n":462,"s":3,"a":169,"t":"Ne pense pas que ceux qui ont été tués dans le sentier d'Allah, soient morts. Au contraire, ils sont vivants, auprès de leur Seigneur, bien pourvus"},{"n":463,"s":3,"a":170,"t":"et joyeux de la faveur qu'Allah leur a accordée, et ravis que ceux qui sont restés derrière eux et ne les ont pas encore rejoints, ne connaîtront aucune crainte et ne seront point affligés."},{"n":464,"s":3,"a":171,"t":"Ils sont ravis d'un bienfait d'Allah et d'une faveur, et du fait qu'Allah ne laisse pas perdre la récompense des croyants."},{"n":465,"s":3,"a":172,"t":"Ceux qui, quoiqu'atteints de blessure, répondirent à l'appel d'Allah et du Messager, il y aura une énorme récompense pour ceux d'entre eux qui ont agi en bien et pratiqué la piété."},{"n":466,"s":3,"a":173,"t":"Certes ceux auxquels l'on disait: «Les gens se sont rassemblés contre vous; craignez-les» - cela accrut leur foi - et ils dirent: «Allah nous suffit; Il est notre meilleur garant»."},{"n":467,"s":3,"a":174,"t":"Ils revinrent donc avec un bienfait de la part d'Allah et une grâce. Nul mal ne les toucha et ils suivirent ce qui satisfait Allah. Et Allah est Détenteur d'une grâce immense."},{"n":468,"s":3,"a":175,"t":"C'est le Diable qui vous fait peur de ses adhérents. N'ayez donc pas peur d'eux. Mais ayez peur de Moi, si vous êtes croyants."},{"n":469,"s":3,"a":176,"t":"N'aie (ô Muhammad) aucun chagrin pour ceux qui se jettent rapidement dans la mécréance. En vérité, ils ne nuiront en rien à Allah. Allah tient à ne leur assigner aucune part de biens dans l'au-delà. Et pour eux il y aura un énorme châtiment."},{"n":470,"s":3,"a":177,"t":"Ceux qui auront troqué la croyance contre la mécréance ne nuiront en rien à Allah. Et pour eux un châtiment douloureux."},{"n":471,"s":3,"a":178,"t":"Que ceux qui n'ont pas cru ne comptent pas que ce délai que Nous leur accordons soit à leur avantage. Si Nous leur accordons un délai, c'est seulement pour qu'ils augmentent leurs péchés. Et pour eux un châtiment avilissant."},{"n":472,"s":3,"a":179,"t":"Allah n'est point tel qu'Il laisse les croyants dans l'état où vous êtes jusqu'à ce qu'Il distingue le mauvais du bon. Et Allah n'est point tel qu'Il vous dévoile l'Inconnaissable. Mais Allah choisit parmi Ses messagers qui Il veut. Croyez donc en Allah et en Ses messagers. Et si vous avez la foi et la piété, vous aurez alors une récompense énorme."},{"n":473,"s":3,"a":180,"t":"Que ceux qui gardent avec avarice ce qu'Allah leur donne par Sa grâce, ne comptent point cela comme bon pour eux. Au contraire, c'est mauvais pour eux: au Jour de la Résurrection, on leur attachera autour du cou ce qu'ils ont gardé avec avarice. C'est Allah qui a l'héritage des cieux et de la terre. Et Allah est Parfaitement Connaisseur de ce que vous faites."},{"n":474,"s":3,"a":181,"t":"Allah a certainement entendu la parole de ceux qui ont dit: «Allah est pauvre et nous sommes riches.» Nous enregistrons leur parole, ainsi que leur meurtre, sans droit, des prophètes. Et Nous leur dirons: «Goûtez au châtiment de la fournaise."},{"n":475,"s":3,"a":182,"t":"Cela, à cause de ce que vos mains ont accompli (antérieurement)!» Car Allah ne fait point de tort aux serviteurs."},{"n":476,"s":3,"a":183,"t":"Ceux-là mêmes qui ont dit: «Vraiment Allah nous a enjoint de ne pas croire en un messager tant qu'Il ne nous a pas apporté une offrande que le feu consume». - Dis: «Des messagers avant moi vous sont, certes, venus avec des preuves, et avec ce que vous avez dit [demandé]. Pourquoi donc les avez-vous tués, si vous êtes véridiques?»"},{"n":477,"s":3,"a":184,"t":"S'ils te (Muhammad) traitent de menteur, des prophètes avant toi, ont certes été traités de menteurs. Ils étaient venus avec les preuves claires, les Psaumes et le Livre lumineux."},{"n":478,"s":3,"a":185,"t":"Toute âme goûtera la mort. Mais c'est seulement au Jour de la Résurrection que vous recevrez votre entière rétribution. Quiconque donc est écarté du Feu et introduit au Paradis, a certes réussi. Et la vie présente n'est qu'un objet de jouissance trompeuse."},{"n":479,"s":3,"a":186,"t":"Certes vous serez éprouvés dans vos biens et vos personnes; et certes vous entendrez de la part de ceux à qui le Livre a été donné avant vous, et de la part des Associateurs, beaucoup de propos désagréables. Mais si vous êtes endurants et pieux... voilà bien la meilleure résolution à prendre."},{"n":480,"s":3,"a":187,"t":"Allah prit, de ceux auxquels le Livre était donné, cet engagement: «Exposez-le, certes, aux gens et ne le cachez pas». Mais ils l'ont jeté derrière leur dos et l'ont vendu à vil prix. Quel mauvais commerce ils ont fait!"},{"n":481,"s":3,"a":188,"t":"Ne pense point que ceux-là qui exultent de ce qu'ils ont fait, et qui aiment qu'on les loue pour ce qu'ils n'ont pas fait, ne pense point donc, qu'ils trouvent une échappatoire au châtiment. Pour eux, il y aura un châtiment douloureux!"},{"n":482,"s":3,"a":189,"t":"A Allah appartient le royaume des cieux et de la terre. Et Allah est Omnipotent."},{"n":483,"s":3,"a":190,"t":"En vérité, dans la création des cieux et de la terre, et dans l'alternance de la nuit et du jour, il y a certes des signes pour les doués d'intelligence,"},{"n":484,"s":3,"a":191,"t":"qui, debout, assis, couchés sur leurs côtés, invoquent Allah et méditent sur la création des cieux et de la terre (disant): «Notre Seigneur! Tu n'as pas créé cela en vain. Gloire à Toi! Garde-nous du châtiment du Feu."},{"n":485,"s":3,"a":192,"t":"Seigneur! Quiconque Tu fais entrer dans le Feu, Tu le couvres vraiment d'ignominie. Et pour les injustes, il n'y a pas de secoureurs!"},{"n":486,"s":3,"a":193,"t":"Seigneur! Nous avons entendu l'appel de celui qui a appelé ainsi à la foi: «Croyez en votre Seigneur» et dès lors nous avons cru. Seigneur, pardonne-nous nos péchés, efface de nous nos méfaits, et place nous, à notre mort, avec les gens de bien."},{"n":487,"s":3,"a":194,"t":"Seigneur! Donne-nous ce que Tu nous as promis par Tes messagers. Et ne nous couvre pas d'ignominie au Jour de la Résurrection. Car Toi, Tu ne manques pas à Ta promesse»."},{"n":488,"s":3,"a":195,"t":"Leur Seigneur les a alors exaucés (disant): «En vérité, Je ne laisse pas perdre le bien que quiconque parmi vous a fait, homme ou femme, car vous êtes les uns des autres. Ceux donc qui ont émigré, qui ont été expulsés de leurs demeures, qui ont été persécutés dans Mon chemin, qui ont combattu, qui ont été tués, Je tiendrai certes pour expiées leurs mauvaises actions, et les ferai entrer dans les Jardins sous lesquels coulent les ruisseaux, comme récompense de la part d'Allah.» Quant à Allah, c'est auprès de Lui qu'est la plus belle récompense."},{"n":489,"s":3,"a":196,"t":"Que ne t'abuse point la versatilité [pour la prospérité] dans le pays, de ceux qui sont infidèles."},{"n":490,"s":3,"a":197,"t":"Piètre jouissance! Puis leur refuge sera l'Enfer. Et quelle détestable couche!"},{"n":491,"s":3,"a":198,"t":"Mais quant à ceux qui craignent leur Seigneur, ils auront des Jardins sous lesquels coulent les ruisseaux, pour y demeurer éternellement, un lieu d'accueil de la part d'Allah. Et ce qu'il y a auprès d'Allah est meilleur, pour les pieux."},{"n":492,"s":3,"a":199,"t":"Il y a certes, parmi les gens du Livre ceux qui croient en Allah et en ce qu'on a fait descendre vers vous et en ce qu'on a fait descendre vers eux. Ils sont humbles envers Allah, et ne vendent point les versets d'Allah à vil prix. Voilà ceux dont la récompense est auprès de leur Seigneur. En vérité, Allah est prompt à faire les comptes."},{"n":493,"s":3,"a":200,"t":"O les croyants! Soyez endurants. Incitez-vous à l'endurance. Luttez constamment (contre l'ennemi) et craignez Allah, afin que vous réussissiez!"},{"n":494,"s":4,"a":1,"t":"O hommes! Craignez votre Seigneur qui vous a créés d'un seul être, et a créé de celui-ci son épouse, et qui de ces deux là a fait répandre (sur la terre) beaucoup d'hommes et de femmes. Craignez Allah au nom duquel vous vous implorez les uns les autres, et craignez de rompre les liens du sang. Certes Allah vous observe parfaitement."},{"n":495,"s":4,"a":2,"t":"Et donnez aux orphelins leurs biens; n'y substituez pas le mauvais au bon. Ne mangez pas leurs biens avec les vôtres: c'est vraiment un grand péché."},{"n":496,"s":4,"a":3,"t":"Et si vous craignez de n'être pas justes envers les orphelins,... Il est permis d'épouser deux, trois ou quatre, parmi les femmes qui vous plaisent, mais, si vous craignez de n'être pas justes avec celles-ci, alors une seule, ou des esclaves que vous possédez. Cela, afin de ne pas faire d'injustice (ou afin de ne pas aggraver votre charge de famille)."},{"n":497,"s":4,"a":4,"t":"Et donnez aux épouses leur mahr, de bonne grâce. Si de bon gré, elles vous en abandonnent quelque chose, disposez-en alors à votre aise et de bon cœur."},{"n":498,"s":4,"a":5,"t":"Et ne confiez pas aux incapables vos biens dont Allah a fait votre subsistance. Mais prélevez-en, pour eux, nourriture et vêtement; et parlez-leur convenablement."},{"n":499,"s":4,"a":6,"t":"Et éprouvez (la capacité) des orphelins jusqu'à ce qu'ils atteignent (l'aptitude) au mariage; et si vous ressentez en eux une bonne conduite, remettez-leur leurs biens. Ne les utilisez pas (dans votre intérêt) avec gaspillage et dissipation, avant qu'ils ne grandissent. Quiconque est aisé, qu'il s'abstienne d'en prendre lui-même. S'il est pauvre, alors qu'il en utilise raisonnablement: et lorsque vous leur remettez leurs biens, prenez des témoins à leur encontre. Mais Allah suffit pour observer et compter."},{"n":500,"s":4,"a":7,"t":"Aux hommes revient une part de ce qu'ont laissé les père et mère ainsi que les proches; et aux femmes une part de ce qu'ont laissé les père et mère ainsi que les proches, que ce soit peu ou beaucoup: une part fixée."},{"n":501,"s":4,"a":8,"t":"Et lorsque les proches parents, les orphelins, les nécessiteux assistent au partage, offrez-leur quelque chose de l'héritage, et parlez-leur convenablement."},{"n":502,"s":4,"a":9,"t":"Que la crainte saisisse ceux qui laisseraient après eux une descendance faible, et qui seraient inquiets à leur sujet; qu'ils redoutent donc Allah et qu'ils prononcent des paroles justes."},{"n":503,"s":4,"a":10,"t":"Ceux qui mangent [disposent] injustement des biens des orphelins ne font que manger du feu dans leurs ventres. Ils brûleront bientôt dans les flammes de l'Enfer."},{"n":504,"s":4,"a":11,"t":"Voici ce qu'Allah vous enjoint au sujet de vos enfants: au fils, une part équivalente à celle de deux filles. S'il n'y a que des filles, même plus de deux, à elles alors deux tiers de ce que le défunt laisse. Et s'il n'y en a qu'une, à elle alors la moitié. Quant aux père et mère du défunt, à chacun d'eux le sixième de ce qu'il laisse, s'il a un enfant. S'il n'a pas d'enfant et que ses père et mère héritent de lui, à sa mère alors le tiers. Mais s'il a des frères, à la mère alors le sixième, après exécution du testament qu'il aurait fait ou paiement d'une dette. De vos ascendants ou descendants, vous ne savez pas qui est plus près de vous en utilité. Ceci est un ordre obligatoire de la part d'Allah, car Allah est, certes, Omniscient et Sage."},{"n":505,"s":4,"a":12,"t":"Et à vous la moitié de ce que laissent vos épouses, si elles n'ont pas d'enfants. Si elles ont un enfant, alors à vous le quart de ce qu'elles laissent, après exécution du testament qu'elles auraient fait ou paiement d'une dette. Et à elles un quart de ce que vous laissez, si vous n'avez pas d'enfant. Mais si vous avez un enfant, à elles alors le huitième de ce que vous laissez après exécution du testament que vous auriez fait ou paiement d'une dette. Et si un homme, ou une femme meurt sans héritier direct, cependant qu'il laisse un frère ou une sœur, à chacun de ceux-ci alors, un sixième. S'ils sont plus de deux, tous alors participeront au tiers, après exécution du testament ou paiement d'une dette, sans préjudice à quiconque. (Telle est l') Injonction d'Allah! Et Allah est Omniscient et Indulgent."},{"n":506,"s":4,"a":13,"t":"Tels sont les ordres d'Allah. Et quiconque obéit à Allah et à Son messager, Il le fera entrer dans les Jardins sous lesquels coulent les ruisseaux, pour y demeurer éternellement. Et voilà la grande réussite."},{"n":507,"s":4,"a":14,"t":"Et quiconque désobéit à Allah et à Son messager, et transgresse Ses ordres, Il le fera entrer au Feu pour y demeurer éternellement. Et celui-là aura un châtiment avilissant."},{"n":508,"s":4,"a":15,"t":"Celles de vos femmes qui forniquent, faites témoigner à leur encontre quatre d'entre vous. S'ils témoignent, alors confinez ces femmes dans vos maisons jusqu'à ce que la mort les rappelle ou qu'Allah décrète un autre ordre à leur égard."},{"n":509,"s":4,"a":16,"t":"Les deux d'entre vous qui l'ont commise [la fornication], sévissez contre eux. S'ils se repentent ensuite et se réforment, alors laissez-les en paix. Allah demeure Accueillant au repentir et Miséricordieux."},{"n":510,"s":4,"a":17,"t":"Allah accueille seulement le repentir de ceux qui font le mal par ignorance et qui aussitôt se repentent. Voilà ceux de qui Allah accueille le repentir. Et Allah est Omniscient et Sage."},{"n":511,"s":4,"a":18,"t":"Mais l'absolution n'est point destinée à ceux qui font de mauvaises actions jusqu'au moment où la mort se présente à l'un d'eux, et qui s'écrie: «Certes, je me repens maintenant» - non plus pour ceux qui meurent mécréants. Et c'est pour eux que Nous avons préparé un châtiment douloureux."},{"n":512,"s":4,"a":19,"t":"O les croyants! Il ne vous est pas licite d'hériter des femmes contre leur gré. Ne les empêchez pas de se remarier dans le but de leur ravir une partie de ce que vous aviez donné, à moins qu'elles ne viennent à commettre un péché prouvé. Et comportez-vous convenablement envers elles. Si vous avez de l'aversion envers elles durant la vie commune, il se peut que vous ayez de l'aversion pour une chose où Allah a déposé un grand bien."},{"n":513,"s":4,"a":20,"t":"Si vous voulez substituer une épouse à une autre, et que vous ayez donné à l'une un qintâr, n'en reprenez rien. Quoi! Le reprendriez-vous par injustice et péché manifeste?"},{"n":514,"s":4,"a":21,"t":"Comment oseriez-vous le reprendre, après que l'union la plus intime vous ait associés l'un à l'autre et qu'elles aient obtenu de vous un engagement solennel?"},{"n":515,"s":4,"a":22,"t":"Et n'épousez pas les femmes que vos pères ont épousées, exception faite pour le passé. C'est une turpitude, une abomination, et quelle mauvaise conduite!"},{"n":516,"s":4,"a":23,"t":"Vous sont interdites vos mères, filles, sœurs, tantes paternelles et tantes maternelles, filles d'un frère et filles d'une sœur, mères qui vous ont allaités, sœurs de lait, mères de vos femmes, belles-filles sous votre tutelle et issues des femmes avec qui vous avez consommé le mariage; si le mariage n'a pas été consommé, ceci n'est pas un péché de votre part; les femmes de vos fils nés de vos reins; de même que deux sœurs réunies - exception faite pour le passé. Car vraiment Allah est Pardonneur et Miséricordieux;"},{"n":517,"s":4,"a":24,"t":"et, parmi les femmes, les dames (qui ont un mari), sauf si elles sont vos esclaves en toute propriété. Prescription d'Allah sur vous! A part cela, il vous est permis de les rechercher, en vous servant de vos biens et en concluant mariage, non en débauchés. Puis, de même que vous jouissez d'elles, donnez-leur leur mahr comme une chose due. Il n'y a aucun péché contre vous à ce que vous concluez un accord quelconque entre vous après la fixation du mahr Car Allah est, certes, Omniscient et Sage."},{"n":518,"s":4,"a":25,"t":"Et quiconque parmi vous n'a pas les moyens pour épouser des femmes libres (non esclaves) croyantes, eh bien (il peut épouser) une femme parmi celles de vos esclaves croyantes. Allah connaît mieux votre foi, car vous êtes les uns des autres (de la même religion). Et épousez-les avec l'autorisation de leurs maîtres (Waliy) et donnez-leur un mahr convenable; (épousez-les) étant vertueuses et non pas livrées à la débauche ni ayant des amants clandestins. Si, une fois engagées dans le mariage, elles commettent l'adultère, elles reçoivent la moitié du châtiment qui revient aux femmes libres (non esclaves) mariées. Ceci est autorisé à celui d'entre vous qui craint la débauche; mais ce serait mieux pour vous d'être endurant. Et Allah est Pardonneur et Miséricordieux."},{"n":519,"s":4,"a":26,"t":"Allah veut vous éclairer, vous montrer les voies des hommes d'avant vous, et aussi accueillir votre repentir. Et Allah est Omniscient et Sage."},{"n":520,"s":4,"a":27,"t":"Et Allah veut accueillir votre repentir. Mais ceux qui suivent les passions veulent que vous vous incliniez grandement (vers l'erreur comme ils le font)."},{"n":521,"s":4,"a":28,"t":"Allah veut vous alléger (les obligations,) car l'homme a été créé faible."},{"n":522,"s":4,"a":29,"t":"O les croyants! Que les uns d'entre vous ne mangent pas les biens des autres illégalement. Mais qu'il y ait du négoce (légal), entre vous, par consentement mutuel. Et ne vous tuez pas vous-mêmes. Allah, en vérité, est Miséricordieux envers vous."},{"n":523,"s":4,"a":30,"t":"Et quiconque commet cela, par excès et par iniquité, Nous le jetterons au Feu, voilà qui est facile pour Allah."},{"n":524,"s":4,"a":31,"t":"Si vous évitez les grands péchés qui vous sont interdits, Nous effacerons vos méfaits de votre compte, et Nous vous ferons entrer dans un endroit honorable (le Paradis)."},{"n":525,"s":4,"a":32,"t":"Ne convoitez pas ce qu'Allah a attribué aux uns d'entre vous plus qu'aux autres; aux hommes la part qu'ils ont acquise, et aux femmes la part qu'elles ont acquise. Demandez à Allah de Sa grâce. Car Allah, certes, est Omniscient."},{"n":526,"s":4,"a":33,"t":"A tous Nous avons désigné des héritiers pour ce que leur laissent leurs père et mère, leurs proches parents, et ceux envers qui, de vos propres mains, vous vous êtes engagés, donnez leur donc leur part, car Allah, en vérité, est témoin de tout."},{"n":527,"s":4,"a":34,"t":"Les hommes ont autorité sur les femmes, en raison des faveurs qu'Allah accorde à ceux-là sur celles-ci, et aussi à cause des dépenses qu'ils font de leurs biens. Les femmes vertueuses sont obéissantes (à leurs maris), et protègent ce qui doit être protégé, pendant l'absence de leurs époux, avec la protection d'Allah. Et quant à celles dont vous craignez la désobéissance, exhortez-les, éloignez-vous d'elles dans leurs lits et frappez-les. Si elles arrivent à vous obéir, alors ne cherchez plus de voie contre elles, car Allah est certes, Haut et Grand!"},{"n":528,"s":4,"a":35,"t":"Si vous craignez le désaccord entre les deux [époux], envoyez alors un arbitre de sa famille à lui, et un arbitre de sa famille à elle. Si les deux veulent la réconciliation, Allah rétablira l'entente entre eux. Allah est certes, Omniscient et Parfaitement Connaisseur."},{"n":529,"s":4,"a":36,"t":"Adorez Allah et ne Lui donnez aucun associé. Agissez avec bonté envers (vos) père et mère, les proches, les orphelins, les pauvres, le proche voisin, le voisin lointain, le collègue et le voyageur, et les esclaves en votre possession, car Allah n'aime pas, en vérité, le présomptueux, l'arrogant,"},{"n":530,"s":4,"a":37,"t":"Ceux qui sont avares et ordonnent l'avarice aux autres, et cachent ce qu'Allah leur a donné de par Sa grâce. Nous avons préparé un châtiment avilissant pour les mécréants."},{"n":531,"s":4,"a":38,"t":"Et ceux qui dépensent leurs biens avec ostentation devant les gens, et ne croient ni en Allah ni au Jour dernier. Quiconque a le Diable pour camarade inséparable, quel mauvais camarade!"},{"n":532,"s":4,"a":39,"t":"Qu'auraient-ils à se reprocher s'ils avaient cru en Allah et au Jour dernier et dépensé (dans l'obéissance) de ce qu'Allah leur a attribué? Allah, d'eux, est Omniscient."},{"n":533,"s":4,"a":40,"t":"Certes, Allah ne lèse (personne), fût-ce du poids d'un atome. S'il est une bonne action, Il la double, et accorde une grosse récompense de Sa part."},{"n":534,"s":4,"a":41,"t":"Comment seront-ils quand Nous ferons venir de chaque communauté un témoin, et que Nous te (Muhammad) ferons venir comme témoin contre ces gens-ci?"},{"n":535,"s":4,"a":42,"t":"Ce jour-là, ceux qui n'ont pas cru et ont désobéi au Messager, préfèreraient que la terre fût nivelée sur eux et ils ne sauront cacher à Allah aucune parole."},{"n":536,"s":4,"a":43,"t":"O les croyants! N'approchez pas de la Salât alors que vous êtes ivres jusqu'à ce que vous compreniez ce que vous dites, et aussi quand vous êtes en état d'impureté [pollués] - à moins que vous ne soyez en voyage - jusqu'à ce que vous ayez pris un bain rituel. Si vous êtes malades ou en voyage, ou si l'un de vous revient du lieu où il a fait ses besoins, ou si vous avez touché à des femmes et que vous ne trouviez pas d'eau, alors recourez à une terre pure, et passez-vous-en sur vos visages et sur vos mains. Allah, en vérité, est Indulgent et Pardonneur."},{"n":537,"s":4,"a":44,"t":"N'as-tu (Muhammad) pas vu ceux qui ont reçu une partie du Livre acheter l'égarement et chercher à ce que vous vous égariez du [droit] chemin?"},{"n":538,"s":4,"a":45,"t":"Allah connaît mieux vos ennemis. Et Allah suffit comme protecteur. Et Allah suffit comme secoureur."},{"n":539,"s":4,"a":46,"t":"Il en est parmi les Juifs qui détournent les mots de leur sens, et disent: «Nous avions entendu, mais nous avons désobéi», «Ecoute sans qu'il te soit donné d'entendre», et favorise nous «Ra'inâ», tordant la langue et attaquant la religion. Si au contraire ils disaient: «Nous avons entendu et nous avons obéi», «Ecoute», et «Regarde-nous», ce serait meilleur pour eux, et plus droit. Mais Allah les a maudits à cause de leur mécréance; leur foi est donc bien médiocre."},{"n":540,"s":4,"a":47,"t":"O vous à qui on a donné le Livre, croyez à ce que Nous avons fait descendre, en confirmation de ce que vous aviez déjà, avant que Nous effacions des visages et les retournions sens devant derrière, ou que Nous les maudissions comme Nous avons maudit les gens du Sabbat. Car le commandement d'Allah est toujours exécuté."},{"n":541,"s":4,"a":48,"t":"Certes Allah ne pardonne pas qu'on Lui donne quelqu'associé. A part cela, Il pardonne à qui Il veut. Mais quiconque donne à Allah quelqu'associé commet un énorme péché."},{"n":542,"s":4,"a":49,"t":"N'as-tu pas vu ceux-là qui se déclarent purs? Mais c'est Allah qui purifie qui Il veut; et ils ne seront point lésés, fût-ce d'un brin de noyau de datte."},{"n":543,"s":4,"a":50,"t":"Regarde comme ils inventent le mensonge à l'encontre d'Allah. Et çà, c'est assez comme péché manifeste!"},{"n":544,"s":4,"a":51,"t":"N'as-tu pas vu ceux-là, à qui une partie du Livre a été donnée, avoir foi à la magie (gibt) et au Tâghhoût, et dire en faveur de ceux qui ne croient pas: «Ceux-là sont mieux guidés (sur le chemin) que ceux qui ont cru»?"},{"n":545,"s":4,"a":52,"t":"Voilà ceux qu'Allah a maudits; et quiconque Allah maudit, jamais tu ne trouveras pour lui de secoureur."},{"n":546,"s":4,"a":53,"t":"Possèdent-ils une partie du pouvoir? Ils ne donneraient donc rien aux gens, fût-ce le creux d'un noyau de datte."},{"n":547,"s":4,"a":54,"t":"Envient-ils aux gens ce qu'Allah leur a donné de par Sa grâce? Or, Nous avons donné à la famille d'Abraham le Livre et la Sagesse; et Nous leur avons donné un immense royaume."},{"n":548,"s":4,"a":55,"t":"Certains d'entre eux ont cru en lui, d'autres d'entre eux s'en sont écartés. L'Enfer leur suffira comme flamme (pour y brûler)."},{"n":549,"s":4,"a":56,"t":"Certes, ceux qui ne croient pas à Nos Versets, (le Coran) Nous les brûlerons bientôt dans le Feu. Chaque fois que leurs peaux auront été consumées, Nous leur donnerons d'autres peaux en échange afin qu'ils goûtent au châtiment. Allah est certes, Puissant et Sage!"},{"n":550,"s":4,"a":57,"t":"Et quant à ceux qui ont cru et fait de bonnes œuvres, bientôt Nous les ferons entrer aux Jardins sous lesquels coulent des ruisseaux. Ils y demeureront éternellement. Il y aura là pour eux des épouses purifiées. Et Nous les ferons entrer sous un ombrage épais."},{"n":551,"s":4,"a":58,"t":"Certes, Allah vous commande de rendre les dépôts à leurs ayants-droit, et quand vous jugez entre des gens, de juger avec équité. Quelle bonne exhortation qu'Allah vous fait! Allah est, en vérité, Celui qui entend et qui voit tout."},{"n":552,"s":4,"a":59,"t":"O les croyants! Obéissez à Allah, et obéissez au Messager et à ceux d'entre vous qui détiennent le commandement. Puis, si vous vous disputez en quoi que ce soit, renvoyez-le à Allah et au Messager, si vous croyez en Allah et au Jour dernier. Ce sera bien mieux et de meilleure interprétation (et aboutissement)."},{"n":553,"s":4,"a":60,"t":"N'as-tu pas vu ceux qui prétendent croire à ce qu'on a fait descendre vers toi [prophète] et à ce qu'on a fait descendre avant toi? Ils veulent prendre pour juge le Tâghût, alors que c'est en lui qu'on leur a commandé de ne pas croire. Mais le Diable veut les égarer très loin, dans l'égarement."},{"n":554,"s":4,"a":61,"t":"Et lorsqu'on leur dit: «Venez vers ce qu'Allah a fait descendre et vers le Messager», tu vois les hypocrites s'écarter loin de toi."},{"n":555,"s":4,"a":62,"t":"Comment (agiront-ils) quand un malheur les atteindra, à cause de ce qu'ils ont préparé de leurs propres mains? Puis ils viendront alors près de toi, jurant par Allah: «Nous n'avons voulu que le bien et la réconciliation»."},{"n":556,"s":4,"a":63,"t":"Voilà ceux dont Allah sait ce qu'ils ont dans leurs cœurs. Ne leur tiens donc pas rigueur, exhorte-les, et dis-leur sur eux-mêmes des paroles convaincantes."},{"n":557,"s":4,"a":64,"t":"Nous n'avons envoyé de Messager que pour qu'il soit obéi par la permission d'Allah. Si, lorsqu'ils ont fait du tort à leurs propres personnes ils venaient à toi en implorant le pardon d'Allah et si le Messager demandait le pardon pour eux, ils trouveraient, certes, Allah, Très Accueillant au repentir, Miséricordieux."},{"n":558,"s":4,"a":65,"t":"Non!... Par ton Seigneur! Ils ne seront pas croyants aussi longtemps qu'ils ne t'auront demandé de juger de leurs disputes et qu'ils n'auront éprouvé nulle angoisse pour ce que tu auras décidé, et qu'ils se soumettent complètement [à ta sentence]."},{"n":559,"s":4,"a":66,"t":"Si Nous leur avions prescrit ceci: «Tuez-vous vous-mêmes», ou «Sortez de vos demeures», ils ne l'auraient pas fait, sauf un petit nombre d'entre eux. S'ils avaient fait ce à quoi on les exhortait, cela aurait été certainement meilleur pour eux, et (leur foi) aurait été plus affermie."},{"n":560,"s":4,"a":67,"t":"Alors Nous leur aurions donné certainement, de Notre part, une grande récompense,"},{"n":561,"s":4,"a":68,"t":"et Nous les aurions guidé certes, vers un droit chemin."},{"n":562,"s":4,"a":69,"t":"Quiconque obéit à Allah et au Messager... ceux-là seront avec ceux qu'Allah a comblés de Ses bienfaits: les prophètes, les véridiques, les martyrs, et les vertueux. Et quels bons compagnons que ceux-là!"},{"n":563,"s":4,"a":70,"t":"Cette grâce vient d'Allah. Et Allah suffit comme Parfait Connaisseur."},{"n":564,"s":4,"a":71,"t":"O les croyants! Prenez vos précautions et partez en expédition par détachements ou en masse."},{"n":565,"s":4,"a":72,"t":"Parmi vous, il y aura certes, quelqu'un qui tardera [à aller au combat] et qui, si un malheur vous atteint, dira: «Certes, Allah m'a fait une faveur en ce que je ne me suis pas trouvé en leur compagnie»"},{"n":566,"s":4,"a":73,"t":"et si c'est une grâce qui vous atteint de la part d'Allah, il se mettra, certes, à dire, comme s'il n'y avait aucune affection entre vous et lui: «Quel dommage! Si j'avais été avec eux, j'aurais alors acquis un gain énorme»."},{"n":567,"s":4,"a":74,"t":"Qu'ils combattent donc dans le sentier d'Allah, ceux qui troquent la vie présente contre la vie future. Et quiconque combat dans le sentier d'Allah, tué ou vainqueur, Nous lui donnerons bientôt une énorme récompense."},{"n":568,"s":4,"a":75,"t":"Et qu'avez-vous à ne pas combattre dans le sentier d'Allah, et pour la cause des faibles: hommes, femmes et enfants qui disent: «Seigneur! Fais-nous sortir de cette cité dont les gens sont injustes, et assigne-nous de Ta part un allié, et assigne-nous de Ta part un secoureur»."},{"n":569,"s":4,"a":76,"t":"Les croyants combattent dans le sentier d'Allah, et ceux qui ne croient pas combattent dans le sentier du Tâghût. Eh bien, combattez les alliés du Diable, car la ruse du Diable est, certes, faible."},{"n":570,"s":4,"a":77,"t":"N'as-tu pas vu ceux auxquels on avait dit: «Abstenez-vous de combattre, accomplissez la Salât et acquittez la Zakât!» Puis lorsque le combat leur fut prescrit, voilà qu'une partie d'entre eux se mit à craindre les gens comme on craint Allah, ou même d'une crainte plus forte encore, et à dire: «O notre Seigneur! Pourquoi nous as-Tu prescrit le combat? Pourquoi n'as-Tu pas reporté cela à un peu plus tard?» Dis: «La jouissance d'ici-bas est éphémère, mais la vie future est meilleure pour quiconque est pieux. Et on ne vous lésera pas, fût-ce d'un brin de noyau de datte."},{"n":571,"s":4,"a":78,"t":"Où que vous soyez, la mort vous atteindra, fussiez-vous dans des tours imprenables. Qu'un bien les atteigne, ils disent: «C'est de la part d'Allah.» Qu'un mal les atteigne, ils disent: «C'est dû à toi (Muhammad).» Dis: «Tout est d'Allah.» Mais qu'ont-ils ces gens, à ne comprendre presque aucune parole?"},{"n":572,"s":4,"a":79,"t":"Tout bien qui t'atteint vient d'Allah, et tout mal qui t'atteint vient de toi-même. Et nous t'avons envoyé aux gens comme Messager. Et Allah suffit comme témoin."},{"n":573,"s":4,"a":80,"t":"Quiconque obéit au Messager obéit certainement à Allah. Et quiconque tourne le dos... Nous ne t'avons pas envoyé à eux comme gardien."},{"n":574,"s":4,"a":81,"t":"Ils disent: «Obéissance!» Puis, sitôt sortis de chez toi, une partie d'entre eux délibère au cours de la nuit de tout autre chose que ce qu'elle t'a dit. [Cependant] Allah enregistre ce qu'ils font la nuit. Pardonne-leur donc et place ta confiance en Allah. Et Allah suffit comme Protecteur."},{"n":575,"s":4,"a":82,"t":"Ne méditent-ils donc pas sur le Coran? S'il provenait d'un autre qu'Allah, ils y trouveraient certes maintes contradictions!"},{"n":576,"s":4,"a":83,"t":"Quand leur parvient une nouvelle rassurante ou alarmante, ils la diffusent. S'ils la rapportaient au Messager et aux détenteurs du commandement parmi eux, ceux d'entre eux qui cherchent à être éclairés, auraient appris (la vérité de la bouche du Prophète et des détenteurs du commandement). Et n'eussent été la grâce d'Allah sur vous et Sa miséricorde, vous auriez suivi le Diable, à part quelques-uns."},{"n":577,"s":4,"a":84,"t":"Combats donc dans le sentier d'Allah, tu n'es responsable que de toi même, et incite les croyants (au combat) Allah arrêtera certes la violence des mécréants. Allah est plus redoutable en force et plus sévère en punition."},{"n":578,"s":4,"a":85,"t":"Quiconque intercède d'une bonne intercession, en aura une part; et quiconque intercède d'une mauvaise intercession en portera une part de responsabilité. Et Allah est Puissant sur toute chose."},{"n":579,"s":4,"a":86,"t":"Si on vous fait une salutation, saluez d'une façon meilleure; ou bien rendez-la (simplement). Certes, Allah tient compte de tout."},{"n":580,"s":4,"a":87,"t":"Allah! Pas de divinité à part Lui! Très certainement Il vous rassemblera au Jour de la Résurrection, point de doute là-dessus. Et qui est plus véridique qu'Allah en parole?"},{"n":581,"s":4,"a":88,"t":"Qu'avez-vous à vous diviser en deux factions au sujet des hypocrites? Alors qu'Allah les a refoulés (dans leur infidélité) pour ce qu'ils ont acquis. Voulez-vous guider ceux qu'Allah égare? Et quiconque Allah égare, tu ne lui trouveras pas de chemin (pour le ramener)."},{"n":582,"s":4,"a":89,"t":"Ils aimeraient vous voir mécréants comme ils ont mécru: alors vous seriez tous égaux! Ne prenez donc pas d'alliés parmi eux, jusqu'à ce qu'ils émigrent dans le sentier d'Allah. Mais s'ils tournent le dos, saisissez-les alors, et tuez-les où que vous les trouviez; et ne prenez parmi eux ni allié ni secoureur,"},{"n":583,"s":4,"a":90,"t":"excepté ceux qui se joignent à un groupe avec lequel vous avez conclu une alliance, ou ceux qui viennent chez vous, le cœur serré d'avoir à vous combattre ou à combattre leur propre tribu. Si Allah avait voulu, Il leur aurait donné l'audace (et la force) contre vous, et ils vous auraient certainement combattu. (Par conséquent,) s'ils restent neutres à votre égard et ne vous combattent point, et qu'ils vous offrent la paix, alors, Allah ne vous donne pas de chemin contre eux."},{"n":584,"s":4,"a":91,"t":"Vous en trouverez d'autres qui cherchent à avoir votre confiance, et en même temps la confiance de leur propre tribu. Toutes les fois qu'on les pousse vers l'Association, (l'idolâtrie) ils y retombent en masse. (Par conséquent,) s'ils ne restent pas neutres à votre égard, ne vous offrent pas la paix et ne retiennent pas leurs mains (de vous combattre), alors, saisissez-les et tuez les où que vous les trouviez. Contre ceux-ci, Nous vous avons donné une autorité manifeste."},{"n":585,"s":4,"a":92,"t":"Il n'appartient pas à un croyant de tuer un autre croyant, si ce n'est par erreur. Quiconque tue par erreur un croyant, qu'il affranchisse alors un esclave croyant et remette à sa famille le prix du sang, à moins que celle-ci n'y renonce par charité. Mais si [le tué] appartenait à un peuple ennemi à vous et qu'il soit croyant, qu'on affranchisse alors un esclave croyant. S'il appartenait à un peuple auquel vous êtes liés par un pacte, qu'on verse alors à sa famille le prix du sang et qu'on affranchisse un esclave croyant. Celui qui n'en trouve pas les moyens, qu'il jeûne deux mois d'affilée pour être pardonné par Allah. Allah est Omniscient et Sage."},{"n":586,"s":4,"a":93,"t":"Quiconque tue intentionnellement un croyant, Sa rétribution alors sera l'Enfer, pour y demeurer éternellement. Allah l'a frappé de Sa colère, l'a maudit et lui a préparé un énorme châtiment."},{"n":587,"s":4,"a":94,"t":"O les croyants! Lorsque vous sortez pour lutter dans le sentier d'Allah, voyez bien clair (ne vous hâtez pas) et ne dites pas à quiconque vous adresse le salut (de l'Islam): «Tu n'es pas croyant», convoitant les biens de la vie d'ici-bas. Or c'est auprès d'Allah qu'il y a beaucoup de butin. C'est ainsi que vous étiez auparavant; puis Allah vous a accordé Sa grâce. Voyez donc bien clair. Allah est, certes, Parfaitement Connaisseur de ce que vous faites."},{"n":588,"s":4,"a":95,"t":"Ne sont pas égaux ceux des croyants qui restent chez eux - sauf ceux qui ont quelque infirmité - et ceux qui luttent corps et biens dans le sentier d'Allah. Allah donne à ceux qui luttent corps et biens un grade d'excellence sur ceux qui restent chez eux. Et à chacun Allah a promis la meilleure récompense; et Allah a mis les combattants au-dessus des non combattants en leur accordant une rétribution immense;"},{"n":589,"s":4,"a":96,"t":"des grades de supériorité de Sa part ainsi qu'un pardon et une miséricorde. Allah est Pardonneur et Miséricordieux."},{"n":590,"s":4,"a":97,"t":"Ceux qui ont fait du tort à eux-mêmes, les Anges enlèveront leurs âmes en disant: «Où en étiez-vous?» (à propos de votre religion) - «Nous étions impuissants sur terre», dirent-ils. Alors les Anges diront: «La terre d'Allah n'était-elle pas assez vaste pour vous permettre d'émigrer?» Voilà bien ceux dont le refuge est l'Enfer. Et quelle mauvaise destination!"},{"n":591,"s":4,"a":98,"t":"A l'exception des impuissants: hommes, femmes et enfants, incapables de se débrouiller, et qui ne trouvent aucune voie:"},{"n":592,"s":4,"a":99,"t":"A ceux-là, il se peut qu'Allah donne le pardon. Allah est Clément et Pardonneur."},{"n":593,"s":4,"a":100,"t":"Et quiconque émigre dans le sentier d'Allah trouvera sur terre maints refuges et abondance. Et quiconque sort de sa maison, émigrant vers Allah et Son messager, et que la mort atteint, sa récompense incombe à Allah. Et Allah est Pardonneur et Miséricordieux."},{"n":594,"s":4,"a":101,"t":"Et quand vous parcourez la terre, ce n'est pas un péché pour vous de raccourcir la Salât, si vous craignez que les mécréants ne vous mettent à l'épreuve, car les mécréants demeurent pour vous un ennemi déclaré."},{"n":595,"s":4,"a":102,"t":"Et lorsque tu (Muhammad) te trouves parmi eux, et que tu les diriges dans la Salât, qu'un groupe d'entre eux se mette debout en ta compagnie, en gardant leurs armes. Puis lorsqu'ils ont terminé la prosternation, qu'ils passent derrière vous et que vienne l'autre groupe, ceux qui n'ont pas encore célébré la Salât. A ceux-ci alors d'accomplir la Salât avec toi, prenant leurs précautions et leurs armes. Les mécréants aimeraient vous voir négliger vos armes et vos bagages, afin de tomber sur vous en une seule masse. Vous ne commettez aucun péché si, incommodés par la pluie ou malades, vous déposez vos armes; cependant prenez garde. Certes, Allah a préparé pour les mécréants un châtiment avilissant."},{"n":596,"s":4,"a":103,"t":"Quand vous avez accompli la Salât, invoquez le nom d'Allah, debout, assis ou couchés sur vos côtés. Puis lorsque vous êtes en sécurité, accomplissez la Salât (normalement), car la Salât demeure, pour les croyants, une prescription, à des temps déterminés."},{"n":597,"s":4,"a":104,"t":"Ne faiblissez pas dans la poursuite du peuple [ennemi]. Si vous souffrez, lui aussi souffre comme vous souffrez, tandis que vous espérez d'Allah ce qu'il n'espère pas. Allah est Omniscient et Sage."},{"n":598,"s":4,"a":105,"t":"Nous avons fait descendre vers toi le Livre avec la vérité, pour que tu juges entre les gens, selon ce qu'Allah t'a appris. Et ne te fais pas l'avocat des traîtres."},{"n":599,"s":4,"a":106,"t":"Et implore d'Allah le pardon car Allah est certes Pardonneur et Miséricordieux."},{"n":600,"s":4,"a":107,"t":"Et ne dispute pas en faveur de ceux qui se trahissent eux-mêmes. Allah, vraiment, n'aime pas le traître et le pécheur."},{"n":601,"s":4,"a":108,"t":"Ils cherchent à se cacher des gens, mais ils ne cherchent pas à se cacher d'Allah. Or, Il est avec eux quand ils tiennent la nuit des paroles qu'Il (Allah) n'agrée pas. Et Allah ne cesse de cerner (par Sa science) ce qu'ils font."},{"n":602,"s":4,"a":109,"t":"Voilà les gens en faveur desquels vous disputez dans la vie présente. Mais qui va disputer pour eux devant Allah au Jour de la Résurrection? Ou bien qui sera leur protecteur?"},{"n":603,"s":4,"a":110,"t":"Quiconque agit mal ou fait du tort à lui-même, puis aussitôt implore d'Allah le pardon, trouvera Allah Pardonneur et Miséricordieux."},{"n":604,"s":4,"a":111,"t":"Quiconque acquiert un péché, ne l'acquiert que contre lui-même. Et Allah est Omniscient et Sage."},{"n":605,"s":4,"a":112,"t":"Et quiconque acquiert une faute ou un péché puis en accuse un innocent, se rend coupable alors d'une injustice et d'un péché manifeste."},{"n":606,"s":4,"a":113,"t":"Et n'eût été la grâce d'Allah sur toi (Muhammad) et Sa miséricorde, une partie d'entre eux t'aurait bien volontiers égaré. Mais ils n'égarent qu'eux-mêmes, et ne peuvent en rien te nuire. Allah a fait descendre sur toi le Livre et la Sagesse, et t'a enseigné ce que tu ne savais pas. Et la grâce d'Allah sur toi est immense."},{"n":607,"s":4,"a":114,"t":"Il n'y a rien de bon dans la plus grande partie de leurs conversations secrètes, sauf si l'un d'eux ordonne une charité, une bonne action, ou une conciliation entre les gens. Et quiconque le fait, cherchant l'agrément d'Allah, à celui-là Nous donnerons bientôt une récompense énorme."},{"n":608,"s":4,"a":115,"t":"Et quiconque fait scission d'avec le Messager, après que le droit chemin lui est apparu et suit un sentier autre que celui des croyants, alors Nous le laisserons comme il s'est détourné, et le brûlerons dans l'Enfer. Et quelle mauvaise destination!"},{"n":609,"s":4,"a":116,"t":"Certes, Allah ne pardonne pas qu'on Lui donne des associés. A part cela, Il pardonne à qui Il veut. Quiconque donne des associés à Allah s'égare, très loin dans l'égarement."},{"n":610,"s":4,"a":117,"t":"Ce ne sont que des femelles qu'ils invoquent, en dehors de Lui. Et ce n'est qu'un diable rebelle qu'ils invoquent."},{"n":611,"s":4,"a":118,"t":"Allah l'a (le Diable) maudit et celui-ci a dit: «Certainement, je saisirai parmi Tes serviteurs, une partie déterminée."},{"n":612,"s":4,"a":119,"t":"Certes, je ne manquerai pas de les égarer, je leur donnerai de faux espoirs, je leur commanderai, et ils fendront les oreilles aux bestiaux; je leur commanderai, et ils altèreront la création d'Allah. Et quiconque prend le Diable pour allié au lieu d'Allah, sera, certes, voué à une perte évidente."},{"n":613,"s":4,"a":120,"t":"Il leur fait des promesses et leur donne de faux espoirs. Et le Diable ne leur fait que des promesses trompeuses."},{"n":614,"s":4,"a":121,"t":"Voilà ceux dont le refuge est l'Enfer. Et ils ne trouveront aucun moyen d'y échapper!"},{"n":615,"s":4,"a":122,"t":"Et quant à ceux qui ont cru et fait de bonnes œuvres, Nous les ferons entrer bientôt aux Jardins sous lesquels coulent les ruisseaux, pour y demeurer éternellement. Promesse d'Allah en vérité. Et qui est plus véridique qu'Allah en parole?"},{"n":616,"s":4,"a":123,"t":"Ceci ne dépend ni de vos désirs ni des désirs des gens du Livre. Quiconque fait un mal sera rétribué pour cela, et ne trouvera en sa faveur, hors d'Allah, ni allié ni secoureur."},{"n":617,"s":4,"a":124,"t":"Et quiconque, homme ou femme, fait de bonnes œuvres, tout en étant croyant... les voilà ceux qui entreront au Paradis; et on ne leur fera aucune injustice, fût-ce d'un creux de noyau de datte."},{"n":618,"s":4,"a":125,"t":"Qui est meilleur en religion que celui qui soumet à Allah son être, tout en se conformant à la Loi révélée et suivant la religion d'Abraham, homme de droiture? Et Allah avait pris Abraham pour ami privilégié."},{"n":619,"s":4,"a":126,"t":"C'est à Allah qu'appartient tout ce qui est dans les cieux et sur la terre. Et Allah embrasse toute chose (de Sa science et de Sa puissance)."},{"n":620,"s":4,"a":127,"t":"Et ils te consultent à propos de ce qui a été décrété au sujet des femmes. Dis: «Allah vous donne Son décret là-dessus, en plus de ce qui vous est récité dans le Livre, au sujet des orphelines auxquelles vous ne donnez pas ce qui leur a été prescrit, et que vous désirez épouser, et au sujet des mineurs encore d'âge faible». Vous devez agir avec équité envers les orphelins. Et de tout ce que vous faites de bien, Allah en est, certes, Omniscient."},{"n":621,"s":4,"a":128,"t":"Et si une femme craint de son mari abandon ou indifférence, alors ce n'est pas un péché pour les deux s'ils se réconcilient par un compromis quelconque, et la réconciliation est meilleure, puisque les âmes sont portées à la ladrerie. Mais si vous agissez en bien et vous êtes pieux... Allah est, certes, Parfaitement Connaisseur de ce que vous faites."},{"n":622,"s":4,"a":129,"t":"Vous ne pourrez jamais être équitables entre vos femmes, même si vous en êtes soucieux. Ne vous penchez pas tout à fait vers l'une d'elles, au point de laisser l'autre comme en suspens. Mais si vous vous réconciliez et vous êtes pieux... donc Allah est, certes, Pardonneur et Miséricordieux."},{"n":623,"s":4,"a":130,"t":"Si les deux se séparent, Allah de par Sa largesse, accordera à chacun d'eux un autre destin. Et Allah est plein de largesses et parfaitement Sage."},{"n":624,"s":4,"a":131,"t":"A Allah seul appartient tout ce qui est dans les cieux et sur la terre. «Craignez Allah!» Voilà ce que Nous avons enjoint à ceux auxquels avant vous le Livre fut donné, tout comme à vous-mêmes. Et si vous ne croyez pas (cela ne nuit pas à Allah, car) très certainement à Allah seul appartient tout ce qui est dans les cieux et sur la terre. Et Allah se suffit à Lui-même et Il est digne de louange."},{"n":625,"s":4,"a":132,"t":"A Allah seul appartient tout ce qui est dans les cieux et sur la terre. Et Allah suffit pour s'occuper de tout."},{"n":626,"s":4,"a":133,"t":"S'Il voulait, il vous ferait disparaître, ô gens, et en ferait venir d'autres. Car Allah en est très capable."},{"n":627,"s":4,"a":134,"t":"Quiconque désire la récompense d'ici-bas, c'est auprès d'Allah qu'est la récompense d'ici-bas tout comme celle de l'au-delà. Et Allah entend et observe tout."},{"n":628,"s":4,"a":135,"t":"O les croyants! Observez strictement la justice et soyez des témoins (véridiques) comme Allah l'ordonne, fût-ce contre vous-mêmes, contre vos père et mère ou proches parents. Qu'il s'agisse d'un riche ou d'un besogneux, Allah a priorité sur eux deux (et Il est plus connaisseur de leur intérêt que vous). Ne suivez donc pas les passions, afin de ne pas dévier de la justice. Si vous portez un faux témoignage ou si vous le refusez, [sachez qu'] Allah est Parfaitement Connaisseur de ce que vous faites."},{"n":629,"s":4,"a":136,"t":"O les croyants! Soyez fermes en votre foi en Allah, en Son messager, au Livre qu'Il a fait descendre sur Son messager, et au Livre qu'Il a fait descendre avant. Quiconque ne croit pas en Allah, en Ses anges, en Ses Livres, en Ses messagers et au Jour dernier, s'égare, loin dans l'égarement."},{"n":630,"s":4,"a":137,"t":"Ceux qui ont cru, puis sont devenus mécréants, puis ont cru de nouveau, ensuite sont redevenus mécréants, et n'ont fait que croître en mécréance, Allah ne leur pardonnera pas, ni les guidera vers un chemin (droit)."},{"n":631,"s":4,"a":138,"t":"Annonce aux hypocrites qu'il y a pour eux un châtiment douloureux,"},{"n":632,"s":4,"a":139,"t":"ceux qui prennent pour alliés des mécréants au lieu des croyants, est-ce la puissance qu'ils recherchent auprès d'eux? (En vérité) la puissance appartient entièrement à Allah."},{"n":633,"s":4,"a":140,"t":"Dans le Livre, Il vous a déjà révélé ceci: lorsque vous entendez qu'on renie les versets (le Coran) d'Allah et qu'on s'en raille, ne vous asseyez point avec ceux-là jusqu'à ce qu'ils entreprennent une autre conversation. Sinon, vous serez comme eux. Allah rassemblera, certes, les hypocrites et les mécréants, tous, dans l'Enfer."},{"n":634,"s":4,"a":141,"t":"Ils restent dans l'expectative à votre égard; si une victoire vous vient de la part d'Allah, ils disent: «N'étions-nous pas avec vous?» et s'il en revient un avantage aux mécréants, ils leur disent: «Est-ce que nous n'avons pas mis la main sur vous pour vous soustraire aux croyants?» Eh bien, Allah jugera entre vous au Jour de la Résurrection. Et jamais Allah ne donnera une voie aux mécréants contre les croyants."},{"n":635,"s":4,"a":142,"t":"Les hypocrites cherchent à tromper Allah, mais Allah retourne leur tromperie (contre eux-mêmes). Et lorsqu'ils se lèvent pour la Salât, ils se lèvent avec paresse et par ostentation envers les gens. A peine invoquent-ils Allah."},{"n":636,"s":4,"a":143,"t":"Ils sont indécis (entre les croyants et les mécréants,) n'appartenant ni aux uns ni aux autres. Or, quiconque Allah égare, jamais tu ne trouveras de chemin pour lui."},{"n":637,"s":4,"a":144,"t":"O les croyants! Ne prenez pas pour alliés les mécréants au lieu des croyants. Voudriez-vous donner à Allah une preuve évidente contre vous?"},{"n":638,"s":4,"a":145,"t":"Les hypocrites seront, certes, au plus bas fond du Feu, et tu ne leur trouveras jamais de secoureur,"},{"n":639,"s":4,"a":146,"t":"sauf ceux qui se repentent, s'amendent, s'attachent fermement à Allah, et Lui vouent une foi exclusive. Ceux-là seront avec les croyants. Et Allah donnera aux croyants une énorme récompense."},{"n":640,"s":4,"a":147,"t":"Pourquoi Allah vous infligerait-Il un châtiment si vous êtes reconnaissants et croyants? Allah est Reconnaissant et Omniscient."},{"n":641,"s":4,"a":148,"t":"Allah n'aime pas qu'on profère de mauvaises paroles sauf quand on a été injustement provoqué. Et Allah est Audient et Omniscient."},{"n":642,"s":4,"a":149,"t":"Que vous fassiez du bien, ouvertement ou en cachette, ou bien que vous pardonniez un mal... Alors Allah est Pardonneur et Omnipotent."},{"n":643,"s":4,"a":150,"t":"Ceux qui ne croient pas en Allah et en Ses messagers, et qui veulent faire distinction entre Allah et Ses messagers et qui disent: «Nous croyons en certains d'entre eux mais ne croyons pas en d'autres», et qui veulent prendre un chemin intermédiaire (entre la foi et la mécréance),"},{"n":644,"s":4,"a":151,"t":"les voilà les vrais mécréants! Et Nous avons préparé pour les mécréants un châtiment avilissant."},{"n":645,"s":4,"a":152,"t":"Et ceux qui croient en Allah et en Ses messagers et qui ne font point de différence entre ces derniers, voilà ceux à qui Il donnera leurs récompenses. Et Allah est Pardonneur et Miséricordieux."},{"n":646,"s":4,"a":153,"t":"Les gens du Livre te demandent de leur faire descendre du ciel un Livre. Ils ont déjà demandé à Moïse quelque chose de bien plus grave quand ils dirent: «Fais-nous voir Allah à découvert!» Alors la foudre les frappa pour leur tort. Puis ils adoptèrent le Veau (comme idole) même après que les preuves leur furent venues. Nous leur pardonnâmes cela et donnâmes à Moïse une autorité déclarée."},{"n":647,"s":4,"a":154,"t":"Et pour (obtenir) leur engagement, Nous avons brandi au-dessus d'eux le Mont Tor, Nous leur avons dit: «Entrez par la porte en vous prosternant» Nous leur avons dit: «Ne transgressez pas le Sabbat» et Nous avons pris d'eux un engagement ferme."},{"n":648,"s":4,"a":155,"t":"(Nous les avons maudits) à cause de leur rupture de l'engagement, leur mécréance aux révélations d'Allah, leur meurtre injustifié des prophètes, et leur parole: «Nos cœurs sont (enveloppés) et imperméables». En réalité, c'est Allah qui a scellé leurs cœurs à cause de leur mécréance, car ils ne croyaient que très peu."},{"n":649,"s":4,"a":156,"t":"Et à cause de leur mécréance et de l'énorme calomnie qu'ils prononcent contre Marie,"},{"n":650,"s":4,"a":157,"t":"et à cause de leur parole: «Nous avons vraiment tué le Christ, Jésus, fils de Marie, le Messager d'Allah»... Or, ils ne l'ont ni tué ni crucifié; mais ce n'était qu'un faux semblant! Et ceux qui ont discuté sur son sujet sont vraiment dans l'incertitude: ils n'en ont aucune connaissance certaine, ils ne font que suivre des conjectures et ils ne l'ont certainement pas tué,"},{"n":651,"s":4,"a":158,"t":"mais Allah l'a élevé vers Lui. Et Allah est Puissant et Sage."},{"n":652,"s":4,"a":159,"t":"Il n'y aura personne, parmi les gens du Livre, qui n'aura pas foi en lui avant sa mort. Et au Jour de la Résurrection, il sera témoin contre eux."},{"n":653,"s":4,"a":160,"t":"C'est à cause des iniquités des Juifs que Nous leur avons rendu illicites les bonnes nourritures qui leur étaient licites, et aussi à cause de ce qu'ils obstruent le sentier d'Allah, (à eux-mêmes et) à beaucoup de monde,"},{"n":654,"s":4,"a":161,"t":"et à cause de ce qu'ils prennent des intérêts usuraires- qui leur étaient pourtant interdits - et parce qu'ils mangent illégalement les biens des gens. A ceux d'entre eux qui sont mécréants Nous avons préparé un châtiment douloureux."},{"n":655,"s":4,"a":162,"t":"Mais ceux d'entre eux qui sont enracinés dans la connaissance, ainsi que les croyants, (tous) ont foi à ce qu'on a fait descendre sur toi et à ce qu'on a fait descendre avant toi. Et quant à ceux qui accomplissent la Salât, paient la Zakât et croient en Allah et au Jour dernier, ceux-là Nous leur donnerons une énorme récompense."},{"n":656,"s":4,"a":163,"t":"Nous t'avons fait une révélation comme Nous fîmes à Noé et aux prophètes après lui. Et Nous avons fait révélation à Abraham, à Ismaël, à Isaac, à Jacob aux Tribus, à Jésus, à Job, à Jonas, à Aaron et à Salomon, et Nous avons donné le Zabour à David."},{"n":657,"s":4,"a":164,"t":"Et il y a des messagers dont Nous t'avons raconté l'histoire précédemment, et des messagers dont Nous ne t'avons point raconté l'histoire - et Allah a parlé à Moïse de vive voix -"},{"n":658,"s":4,"a":165,"t":"en tant que messagers, annonciateurs et avertisseurs, afin qu'après la venue des messagers il n'y eût pour les gens point d'argument devant Allah. Allah est Puissant et Sage."},{"n":659,"s":4,"a":166,"t":"Mais Allah témoigne de ce qu'Il a fait descendre vers toi, Il l'a fait descendre en toute connaissance. Et les Anges en témoignent. Et Allah suffit comme témoin."},{"n":660,"s":4,"a":167,"t":"Ceux qui ne croient pas et qui obstruent le sentier d'Allah, s'égarent certes loin dans l'égarement."},{"n":661,"s":4,"a":168,"t":"Ceux qui ne croient pas et qui pratiquent l'injustice, Allah n'est nullement disposé à leur pardonner, ni à les guider dans un chemin"},{"n":662,"s":4,"a":169,"t":"(autre) que le chemin de l'Enfer où ils demeureront éternellement. Et cela est facile à Allah."},{"n":663,"s":4,"a":170,"t":"O gens! Le Messager vous a apporté la vérité de la part de votre Seigneur. Ayez la foi, donc, cela vous sera meilleur. Et si vous ne croyez pas (qu'importe!), c'est à Allah qu'appartient tout ce qui est dans les cieux et sur la terre. Et Allah est Omniscient et Sage."},{"n":664,"s":4,"a":171,"t":"O gens du Livre (Chrétiens), n'exagérez pas dans votre religion, et ne dites d'Allah que la vérité. Le Messie Jésus, fils de Marie, n'est qu'un Messager d'Allah, Sa parole qu'Il envoya à Marie, et un souffle (de vie) venant de Lui. Croyez donc en Allah et en Ses messagers. Et ne dites pas «Trois». Cessez! Ce sera meilleur pour vous. Allah n'est qu'un Dieu unique. Il est trop glorieux pour avoir un enfant. C'est à Lui qu'appartient tout ce qui est dans les cieux et sur la terre et Allah suffit comme protecteur."},{"n":665,"s":4,"a":172,"t":"Jamais le Messie ne trouve indigne d'être un serviteur d'Allah, ni les Anges rapprochés [de Lui]. Et ceux qui trouvent indigne de L'adorer et s'enflent d'orgueil... Il les rassemblera tous vers Lui."},{"n":666,"s":4,"a":173,"t":"Quant à ceux qui ont cru et fait de bonnes œuvres, Il leur accordera leurs pleines récompenses et y ajoutera le surcroît de Sa grâce. Et quant à ceux qui ont eu la morgue et se sont enflés d'orgueil, Il les châtiera d'un châtiment douloureux. Et ils ne trouveront, pour eux, en dehors d'Allah, ni allié ni secoureur,"},{"n":667,"s":4,"a":174,"t":"O gens! Certes, une preuve évidente vous est venue de la part de votre Seigneur. Et Nous avons fait descendre vers vous une lumière éclatante."},{"n":668,"s":4,"a":175,"t":"Alors ceux qui croient en Allah et qui s'attachent à Lui, Il les fera entrer dans une miséricorde venue de Lui, et dans une grâce aussi. Et Il les guidera vers Lui dans un chemin droit."},{"n":669,"s":4,"a":176,"t":"Ils te demandent ce qui a été décrété. Dis: «Au sujet du défunt qui n'a pas de père ni de mère ni d'enfant, Allah vous donne Son décret: si quelqu'un meurt sans enfant, mais a une sœur, à celle-ci revient la moitié de ce qu'il laisse. Et lui, il héritera d'elle en totalité si elle n'a pas d'enfant. Mais s'il a deux sœurs (ou plus), à elles alors les deux tiers de ce qu'il laisse; et s'il a des frères et des sœurs, à un frère alors revient une portion égale à celle de deux sœurs. Allah vous donne des explications pour que vous ne vous égariez pas. Et Allah est Omniscient."},{"n":670,"s":5,"a":1,"t":"O les croyants! Remplissez fidèlement vos engagements. Vous est permise la bête du cheptel, sauf ce qui sera énoncé [comme étant interdit]. Ne vous permettez point la chasse alors que vous êtes en état d'ihrâm. Allah en vérité, décide ce qu'Il veut."},{"n":671,"s":5,"a":2,"t":"O les croyants! Ne profanez ni les rites du pèlerinage (dans les endroits sacrés) d'Allah, ni le mois sacré, ni les animaux de sacrifice, ni les guirlandes, ni ceux qui se dirigent vers la Maison sacrée cherchant de leur Seigneur grâce et agrément. Une fois désacralisés, vous êtes libres de chasser. Et ne laissez pas la haine pour un peuple qui vous a obstrué la route vers la Mosquée sacrée vous inciter à transgresser. Entraidez-vous dans l'accomplissement des bonnes œuvres et de la piété et ne vous entraidez pas dans le péché et la transgression. Et craignez Allah, car Allah est, certes, dur en punition!"},{"n":672,"s":5,"a":3,"t":"Vous sont interdits la bête trouvée morte, le sang, la chair de porc, ce sur quoi on a invoqué un autre nom que celui d'Allah, la bête étouffée, la bête assommée ou morte d'une chute ou morte d'un coup de corne, et celle qu'une bête féroce a dévorée - sauf celle que vous égorgez avant qu'elle ne soit morte -. (Vous sont interdits aussi la bête) qu'on a immolée sur les pierres dressées, ainsi que de procéder au partage par tirage au sort au moyen de flèches. Car cela est perversité. Aujourd'hui, les mécréants désespèrent (de vous détourner) de votre religion: ne les craignez donc pas et craignez-Moi. Aujourd'hui, J'ai parachevé pour vous votre religion, et accompli sur vous Mon bienfait. Et J'agrée l'Islam comme religion pour vous. Si quelqu'un est contraint par la faim, sans inclination vers le péché... alors, Allah est Pardonneur et Miséricordieux."},{"n":673,"s":5,"a":4,"t":"Ils t'interrogent sur ce qui leur est permis. Dis: «Vous sont permises les bonnes nourritures, ainsi que ce que capturent les carnassiers que vous avez dressés, en leur apprenant ce qu'Allah vous a appris. Mangez donc de ce qu'elles capturent pour vous et prononcez dessus le nom d'Allah. Et craignez Allah. Car Allah est, certes, prompt dans les comptes."},{"n":674,"s":5,"a":5,"t":"«Vous sont permises, aujourd'hui, les bonnes nourritures. Vous est permise la nourriture des gens du Livre, et votre propre nourriture leur est permise. (Vous sont permises) les femmes vertueuses d'entre les croyantes, et les femmes vertueuses d'entre les gens qui ont reçu le Livre avant vous, si vous leur donnez leur mahr avec contrat de mariage, non en débauchés ni en preneurs d'amantes. Et quiconque abjure la foi, alors vaine devient son action, et il sera dans l'au-delà, du nombre des perdants"},{"n":675,"s":5,"a":6,"t":"O les croyants! Lorsque vous vous levez pour la Salât, lavez vos visages et vos mains jusqu'aux coudes; passez les mains mouillées sur vos têtes; et lavez-vous les pieds jusqu'aux chevilles. Et si vous êtes pollués «junub», alors purifiez-vous (par un bain); mais si vous êtes malades, ou en voyage, ou si l'un de vous revient du lieu où il a fait ses besoins ou si vous avez touché aux femmes et que vous ne trouviez pas d'eau, alors recourez à la terre pure, passez-en sur vos visages et vos mains. Allah ne veut pas vous imposer quelque gêne, mais Il veut vous purifier et parfaire sur vous Son bienfait. Peut-être serez-vous reconnaissants."},{"n":676,"s":5,"a":7,"t":"Et rappelez-vous le bienfait d'Allah sur vous, ainsi que l'alliance qu'Il a conclue avec vous, quand vous avez dit: «Nous avons entendu et nous avons obéi». Et craignez Allah. Car Allah connaît parfaitement le contenu des cœurs."},{"n":677,"s":5,"a":8,"t":"O les croyants! Soyez stricts (dans vos devoirs) envers Allah et (soyez) des témoins équitables. Et que la haine pour un peuple ne vous incite pas à être injustes. Pratiquez l'équité: cela est plus proche de la piété. Et craignez Allah. Car Allah est certes Parfaitement Connaisseur de ce que vous faites."},{"n":678,"s":5,"a":9,"t":"Allah a promis à ceux qui croient et font de bonnes œuvres qu'il y aura pour eux un pardon et une énorme récompense."},{"n":679,"s":5,"a":10,"t":"Quant à ceux qui ne croient pas et traitent de mensonge Nos preuves, ceux-là sont des gens de l'Enfer."},{"n":680,"s":5,"a":11,"t":"O les croyants! Rappelez-vous le bienfait d'Allah à votre égard, le jour où un groupe d'ennemis s'apprêtait à porter la main sur vous (en vue de vous attaquer) et qu'Il repoussa leur tentative. Et craignez Allah. C'est en Allah que les croyants doivent mettre leur confiance."},{"n":681,"s":5,"a":12,"t":"Et Allah certes prit l'engagement des enfants d'Israël. Nous nommâmes douze chefs d'entre eux. Et Allah dit: «Je suis avec vous, pourvu que vous accomplissiez la Salât, acquittiez la Zakât, croyiez en Mes messagers, les aidiez et fassiez à Allah un bon prêt. Alors, certes, j'effacerai vos méfaits, et vous ferai entrer aux Jardins sous lesquels coulent les ruisseaux. Et quiconque parmi vous, après cela, mécroit, s'égare certes du droit chemin»!"},{"n":682,"s":5,"a":13,"t":"Et puis, à cause de leur violation de l'engagement, Nous les avons maudits et endurci leurs cœurs: ils détournent les paroles de leur sens et oublient une partie de ce qui leur a été rappelé. Tu ne cesseras de découvrir leur trahison, sauf d'un petit nombre d'entre eux. Pardonne-leur donc et oublie [leurs fautes]. Car Allah aime, certes, les bienfaisants."},{"n":683,"s":5,"a":14,"t":"Et de ceux qui disent: «Nous sommes chrétiens», Nous avons pris leur engagement. Mais ils ont oublié une partie de ce qui leur a été rappelé. Nous avons donc suscité entre eux l'inimitié et la haine jusqu'au Jour de la Résurrection. Et Allah les informera de ce qu'ils faisaient."},{"n":684,"s":5,"a":15,"t":"O gens du Livre! Notre Messager (Muhammad) vous est certes venu, vous exposant beaucoup de ce que vous cachiez du Livre, et passant sur bien d'autres choses! Une lumière et un Livre explicite vous sont certes venus d'Allah!"},{"n":685,"s":5,"a":16,"t":"Par ceci (le Coran), Allah guide aux chemins du salut ceux qui cherchent Son agrément. Et Il les fait sortir des ténèbres à la lumière par Sa grâce. Et Il les guide vers un chemin droit."},{"n":686,"s":5,"a":17,"t":"Certes sont mécréants ceux qui disent: «Allah, c'est le Messie, fils de Marie!» - Dis: «Qui donc détient quelque chose d'Allah (pour L'empêcher), s'Il voulait faire périr le Messie, fils de Marie, ainsi que sa mère et tous ceux qui sont sur la terre?... A Allah seul appartient la royauté des cieux et de la terre et de ce qui se trouve entre les deux». Il crée ce qu'Il veut. Et Allah est Omnipotent."},{"n":687,"s":5,"a":18,"t":"Les Juifs et les Chrétiens ont dit: «Nous sommes les fils d'Allah et Ses préférés.» Dis: «Pourquoi donc vous châtie-t-Il pour vos péchés?» En fait, vous êtes des êtres humains d'entre ceux qu'Il a créés. Il pardonne à qui Il veut et Il châtie qui Il veut. Et à Allah seul appartient la royauté des cieux et de la terre et de ce qui se trouve entre les deux. Et c'est vers Lui que sera la destination finale."},{"n":688,"s":5,"a":19,"t":"O gens du Livre! Notre Messager (Muhammad) est venu pour vous éclairer après une interruption des messagers afin que vous ne disiez pas: «Il ne nous est venu ni annonciateur ni avertisseur». Voilà, certes, que vous est venu un annonciateur et un avertisseur. Et Allah est Omnipotent."},{"n":689,"s":5,"a":20,"t":"(Souvenez-vous) Lorsque Moïse dit à son peuple: «O, mon peuple! Rappelez-vous le bienfait d'Allah sur vous, lorsqu'Il a désigné parmi vous des prophètes. Et Il a fait de vous des rois. Et Il vous a donné ce qu'Il n'avait donné à nul autre aux mondes."},{"n":690,"s":5,"a":21,"t":"O mon peuple! Entrez dans la terre sainte qu'Allah vous a prescrite. Et ne revenez point sur vos pas [en refusant de combattre] car vous retourneriez perdants."},{"n":691,"s":5,"a":22,"t":"Ils dirent: «O Moïse, il y a là un peuple de géants. Jamais nous n'y entrerons jusqu'à ce qu'ils en sortent. S'ils en sortent, alors nous y entrerons»."},{"n":692,"s":5,"a":23,"t":"Deux hommes d'entre ceux qui craignaient Allah et qui étaient comblés par Lui de bienfaits dirent: «Entrez chez eux par la porte; puis quand vous y serez entrés, vous serez sans doute les dominants. Et c'est en Allah qu'il faut avoir confiance, si vous êtes croyants»."},{"n":693,"s":5,"a":24,"t":"Ils dirent: «Moïse! Nous n'y entrerons jamais, aussi longtemps qu'ils y seront. Va donc, toi et ton Seigneur, et combattez tous deux. Nous restons là où nous sommes»."},{"n":694,"s":5,"a":25,"t":"Il dit: «Seigneur! Je n'ai de pouvoir, vraiment, que sur moi-même et sur mon frère: sépare-nous donc de ce peuple pervers»."},{"n":695,"s":5,"a":26,"t":"Il (Allah) dit: «Eh bien, ce pays leur sera interdit pendant quarante ans, durant lesquels ils erreront sur la terre. Ne te tourmente donc pas pour ce peuple pervers»."},{"n":696,"s":5,"a":27,"t":"Et raconte-leur en toute vérité l'histoire des deux fils d'Adam. Les deux offrirent des sacrifices; celui de l'un fut accepté et celui de l'autre ne le fut pas. Celui-ci dit: «Je te tuerai sûrement». «Allah n'accepte, dit l'autre, que de la part des pieux»."},{"n":697,"s":5,"a":28,"t":"Si tu étends vers moi ta main pour me tuer, moi, je n'étendrai pas vers toi ma main pour te tuer: car je crains Allah, le Seigneur de l'Univers."},{"n":698,"s":5,"a":29,"t":"Je veux que tu partes avec le péché de m'avoir tué et avec ton propre péché: alors tu seras du nombre des gens du Feu. Telle est la récompense des injustes."},{"n":699,"s":5,"a":30,"t":"Son âme l'incita à tuer son frère. Il le tua donc et devint ainsi du nombre des perdants."},{"n":700,"s":5,"a":31,"t":"Puis Allah envoya un corbeau qui se mit à gratter la terre pour lui montrer comment ensevelir le cadavre de son frère. Il dit: «Malheur à moi! Suis-je incapable d'être, comme ce corbeau, à même d'ensevelir le cadavre de mon frère?» Il devint alors du nombre de ceux que ronge le remords."},{"n":701,"s":5,"a":32,"t":"C'est pourquoi Nous avons prescrit pour les Enfants d'Israël que quiconque tuerait une personne non coupable d'un meurtre ou d'une corruption sur la terre, c'est comme s'il avait tué tous les hommes. Et quiconque lui fait don de la vie, c'est comme s'il faisait don de la vie à tous les hommes. En effet Nos messagers sont venus à eux avec les preuves. Et puis voilà, qu'en dépit de cela, beaucoup d'entre eux se mettent à commettre des excès sur la terre."},{"n":702,"s":5,"a":33,"t":"La récompense de ceux qui font la guerre contre Allah et Son messager, et qui s'efforcent de semer la corruption sur la terre, c'est qu'ils soient tués, ou crucifiés, ou que soient coupées leur main et leur jambe opposées, ou qu'ils soient expulsés du pays. Ce sera pour eux l'ignominie ici-bas; et dans l'au-delà, il y aura pour eux un énorme châtiment,"},{"n":703,"s":5,"a":34,"t":"excepté ceux qui se sont repentis avant de tomber en votre pouvoir: sachez qu'alors, Allah est Pardonneur et Miséricordieux."},{"n":704,"s":5,"a":35,"t":"O les croyants! Craignez Allah, cherchez le moyen de vous rapprocher de Lui et luttez pour Sa cause. Peut-être serez-vous de ceux qui réussissent!"},{"n":705,"s":5,"a":36,"t":"Si les mécréants possédaient tout ce qui est sur la terre et autant encore, pour se racheter du châtiment du Jour de la Résurrection, on ne l'accepterait pas d'eux. Et pour eux il y aura un châtiment douloureux."},{"n":706,"s":5,"a":37,"t":"Ils voudront sortir du Feu, mais ils n'en sortiront point. Et ils auront un châtiment permanent."},{"n":707,"s":5,"a":38,"t":"Le voleur et la voleuse, à tous deux coupez la main, en punition de ce qu'ils se sont acquis, et comme châtiment de la part d'Allah. Allah est Puissant et Sage."},{"n":708,"s":5,"a":39,"t":"Mais quiconque se repent après son tort et se réforme, Allah accepte son repentir. Car, Allah est, certes, Pardonneur et Miséricordieux."},{"n":709,"s":5,"a":40,"t":"Ne sais-tu pas qu'à Allah appartient la royauté des cieux et de la terre? Il châtie qui Il veut et pardonne à qui Il veut. Et Allah est Omnipotent."},{"n":710,"s":5,"a":41,"t":"O Messager! Que ne t'affligent point ceux qui concourent en mécréance; parmi ceux qui ont dit: «Nous avons cru» avec leurs bouches sans que leurs cœurs aient jamais cru et parmi les Juifs qui aiment bien écouter le mensonge et écouter d'autres gens qui ne sont jamais venus à toi et qui déforment le sens des mots une fois bien établi. Ils disent: «Si vous avez reçu ceci, acceptez-le et si vous ne l'avez pas reçu, soyez méfiants». Celui qu'Allah veut éprouver, tu n'as pour lui aucune protection contre Allah. Voilà ceux dont Allah n'a point voulu purifier les cœurs. A eux, seront réservés, une ignominie ici-bas et un énorme châtiment dans l'au-delà."},{"n":711,"s":5,"a":42,"t":"Ils sont attentifs au mensonge et voraces de gains illicites. S'ils viennent à toi, sois juge entre eux ou détourne toi d'eux. Et si tu te détournes d'eux, jamais ils ne pourront te faire aucun mal. Et si tu juges, alors juge entre eux en équité. Car Allah aime ceux qui jugent équitablement."},{"n":712,"s":5,"a":43,"t":"Mais comment te demanderaient-ils d'être leur juge quand ils ont avec eux la Thora dans laquelle se trouve le jugement d'Allah? Et puis, après cela, ils rejettent ton jugement. Ces gens-là ne sont nullement les croyants."},{"n":713,"s":5,"a":44,"t":"Nous avons fait descendre la Thora dans laquelle il y a guide et lumière. C'est sur sa base que les prophètes qui se sont soumis à Allah, ainsi que les rabbins et les docteurs jugent les affaires des Juifs. Car on leur a confié la garde du Livre d'Allah, et ils en sont les témoins. Ne craignez donc pas les gens, mais craignez Moi. Et ne vendez pas Mes enseignements à vil prix. Et ceux qui ne jugent pas d'après ce qu'Allah a fait descendre, les voilà les mécréants."},{"n":714,"s":5,"a":45,"t":"Et Nous y avons prescrit pour eux vie pour vie, œil pour œil, nez pour nez, oreille pour oreille, dent pour dent. Les blessures tombent sous la loi du talion. Après, quiconque y renonce par charité, cela lui vaudra une expiation. Et ceux qui ne jugent pas d'après ce qu'Allah a fait descendre, ceux-là sont des injustes."},{"n":715,"s":5,"a":46,"t":"Et Nous avons envoyé après eux Jésus, fils de Marie, pour confirmer ce qu'il y avait dans la Thora avant lui. Et Nous lui avons donné l'Evangile, où il y a guide et lumière, pour confirmer ce qu'il y avait dans la Thora avant lui, et un guide et une exhortation pour les pieux."},{"n":716,"s":5,"a":47,"t":"Que les gens de l'Evangile jugent d'après ce qu'Allah y a fait descendre. Ceux qui ne jugent pas d'après ce qu'Allah a fait descendre, ceux-là sont les pervers."},{"n":717,"s":5,"a":48,"t":"Et sur toi (Muhammad) Nous avons fait descendre le Livre avec la vérité, pour confirmer le Livre qui était là avant lui et pour prévaloir sur lui. Juge donc parmi eux d'après ce qu'Allah a fait descendre. Ne suis pas leurs passions, loin de la vérité qui t'est venue. A chacun de vous Nous avons assigné une législation et un plan à suivre. Si Allah avait voulu, certes Il aurait fait de vous tous une seule communauté. Mais Il veut vous éprouver en ce qu'Il vous donne. Concurrencez donc dans les bonnes cœvres. C'est vers Allah qu'est votre retour à tous; alors Il vous informera de ce en quoi vous divergiez."},{"n":718,"s":5,"a":49,"t":"Juge alors parmi eux d'après ce qu'Allah a fait descendre. Ne suis pas leurs passions, et prends garde qu'ils ne tentent de t'éloigner d'une partie de ce qu'Allah t'a révélé. Et puis, s'ils refusent (le jugement révélé) sache qu'Allah veut les affliger [ici-bas] pour une partie de leurs péchés. Beaucoup de gens, certes, sont des pervers."},{"n":719,"s":5,"a":50,"t":"Est-ce donc le jugement du temps de l'Ignorance qu'ils cherchent? Qu'y a-t-il de meilleur qu'Allah, en matière de jugement pour des gens qui ont une foi ferme?"},{"n":720,"s":5,"a":51,"t":"O les croyants! Ne prenez pas pour alliés les Juifs et les Chrétiens; ils sont alliés les uns des autres. Et celui d'entre vous qui les prend pour alliés, devient un des leurs. Allah ne guide certes pas les gens injustes."},{"n":721,"s":5,"a":52,"t":"Tu verras, d'ailleurs, que ceux qui ont la maladie au cœur se précipitent vers eux et disent: «Nous craignons qu'un revers de fortune ne nous frappe.» Mais peut-être qu'Allah fera venir la victoire ou un ordre émanant de Lui. Alors ceux-là regretteront leurs pensées secrètes."},{"n":722,"s":5,"a":53,"t":"Et les croyants diront: «Est-ce là ceux qui juraient par Allah de toute leur force qu'ils étaient avec vous?» Mais leurs actions sont devenues vaines et ils sont devenus perdants."},{"n":723,"s":5,"a":54,"t":"O les croyants! Quiconque parmi vous apostasie de sa religion... Allah va faire venir un peuple qu'Il aime et qui L'aime, modeste envers les croyants et fier et puissant envers les mécréants, qui lutte dans le sentier d'Allah, ne craignant le blâme d'aucun blâmeur. Telle est la grâce d'Allah. Il la donne à qui Il veut. Allah est Immense et Omniscient."},{"n":724,"s":5,"a":55,"t":"Vous n'avez d'autres alliés qu'Allah, Son messager, et les croyants qui accomplissent la Salât, s'acquittent de la Zakât, et s'inclinent (devant Allah)."},{"n":725,"s":5,"a":56,"t":"Et quiconque prend pour alliés Allah, Son messager et les croyants, [réussira] car c'est le parti d'Allah qui sera victorieux."},{"n":726,"s":5,"a":57,"t":"O les croyants! N'adoptez pas pour alliés ceux qui prennent en raillerie et jeu votre religion, parmi ceux à qui le Livre fut donné avant vous et parmi les mécréants. Et craignez Allah si vous êtes croyants."},{"n":727,"s":5,"a":58,"t":"Et lorsque vous faites l'appel à la Salât, ils la prennent en raillerie et jeu. C'est qu'ils sont des gens qui ne raisonnent point."},{"n":728,"s":5,"a":59,"t":"Dis: «O gens du Livre! Est-ce que vous nous reprochez autre chose que de croire en Allah, à ce qu'on a fait descendre vers nous et à ce qu'on a fait descendre auparavant? Mais la plupart d'entre vous sont des pervers."},{"n":729,"s":5,"a":60,"t":"Dis: «Puis-je vous informer de ce qu'il y a de pire, en fait de rétribution auprès d'Allah? Celui qu'Allah a maudit, celui qui a encouru Sa colère, et ceux dont Il a fait des singes, des porcs, et de même, celui qui a adoré le Tâghût, ceux-là ont la pire des places et sont les plus égarés du chemin droit»."},{"n":730,"s":5,"a":61,"t":"Lorsqu'ils viennent chez vous, ils disent: «Nous croyons.» Alors qu'ils sont entrés avec la mécréance et qu'ils sont sortis avec. Et Allah sait parfaitement ce qu'ils cachent."},{"n":731,"s":5,"a":62,"t":"Et tu verras beaucoup d'entre eux se précipiter vers le péché et l'iniquité, et manger des gains illicites. Comme est donc mauvais ce qu'ils œuvrent!"},{"n":732,"s":5,"a":63,"t":"Pourquoi les rabbins et les docteurs (de la Loi religieuse) ne les empêchent-ils pas de tenir des propos mensongers et de manger des gains illicites? Que leurs actions sont donc mauvaises!"},{"n":733,"s":5,"a":64,"t":"Et les Juifs disent: «La main d'Allah est fermée!» Que leurs propres mains soient fermées, et maudits soient-ils pour l'avoir dit. Au contraire, Ses deux mains sont largement ouvertes: Il distribue Ses dons comme Il veut. Et certes, ce qui a été descendu vers toi de la part de ton Seigneur va faire beaucoup croître parmi eux la rébellion et la mécréance. Nous avons jeté parmi eux l'inimitié et la haine jusqu'au Jour de la Résurrection. Toutes les fois qu'ils allument un feu pour la guerre, Allah l'éteint. Et ils s'efforcent de semer le désordre sur la terre, alors qu'Allah n'aime pas les semeurs de désordre."},{"n":734,"s":5,"a":65,"t":"Si les gens du Livre avaient la foi et la piété, Nous leur aurions certainement effacé leurs méfaits et les aurions certainement introduits dans les Jardins du délice."},{"n":735,"s":5,"a":66,"t":"S'ils avaient appliqué la Thora et l'Evangile et ce qui est descendu sur eux de la part de leur Seigneur, ils auraient certainement joui de ce qui est au-dessus d'eux et de ce qui est sous leurs pieds. Il y a parmi eux un groupe qui agit avec droiture; mais pour beaucoup d'entre eux, comme est mauvais ce qu'ils font!"},{"n":736,"s":5,"a":67,"t":"O Messager, transmets ce qui t'a été descendu de la part de ton Seigneur. Si tu ne le faisais pas, alors tu n'aurais pas communiqué Son message. Et Allah te protègera des gens. Certes, Allah ne guide pas les gens mécréants."},{"n":737,"s":5,"a":68,"t":"Dis: «O gens du Livre, vous ne tenez sur rien, tant que vous ne vous conformez pas à la Thora et à l'Evangile et à ce qui vous a été descendu de la part de votre Seigneur.» Et certes, ce qui t'a été descendu de la part de ton Seigneur va accroître beaucoup d'entre eux en rébellion et en mécréance. Ne te tourmente donc pas pour les gens mécréants."},{"n":738,"s":5,"a":69,"t":"Ceux qui ont cru, ceux qui se sont judaïsés, les Sabéens, et les Chrétiens, ceux parmi eux qui croient en Allah, au Jour dernier et qui accomplissent les bonnes œuvres, pas de crainte sur eux, et ils ne seront point affligés."},{"n":739,"s":5,"a":70,"t":"Certes, Nous avions déjà pris l'engagement des Enfants d'Israël, et Nous leur avions envoyé des messagers. Mais chaque fois qu'un Messager leur vient avec ce qu'ils ne désirent pas, ils en traitent certains de menteurs et ils en tuent d'autres."},{"n":740,"s":5,"a":71,"t":"Comptant qu'il n'y aurait pas de tentation contre eux, ils étaient devenus aveugles et sourds. Puis Allah accueillit leur repentir. Ensuite, beaucoup d'entre eux redevinrent aveugles et sourds. Et Allah voit parfaitement ce qu'ils font."},{"n":741,"s":5,"a":72,"t":"Ce sont, certes, des mécréants ceux qui disent: «En vérité, Allah c'est le Messie, fils de Marie.» Alors que le Messie a dit: «O enfants d'Israël, adorez Allah, mon Seigneur et votre Seigneur». Quiconque associe à Allah (d'autres divinités,) Allah lui interdit le Paradis; et son refuge sera le Feu. Et pour les injustes, pas de secoureurs!"},{"n":742,"s":5,"a":73,"t":"Ce sont certes des mécréants, ceux qui disent: «En vérité, Allah est le troisième de trois.» Alors qu'il n'y a de divinité qu'Une Divinité Unique! Et s'ils ne cessent de le dire, certes, un châtiment douloureux touchera les mécréants d'entre eux."},{"n":743,"s":5,"a":74,"t":"Ne vont-ils donc pas se repentir à Allah et implorer Son pardon? Car Allah est Pardonneur et Miséricordieux."},{"n":744,"s":5,"a":75,"t":"Le Messie, fils de Marie, n'était qu'un Messager. Des messagers sont passés avant lui. Et sa mère était une véridique. Et tous deux consommaient de la nourriture. Vois comme Nous leur expliquons les preuves et puis vois comme ils se détournent."},{"n":745,"s":5,"a":76,"t":"Dis: «Adorez-vous, au lieu d'Allah, ce qui n'a le pouvoir de vous faire ni le mal ni le bien?» Or c'est Allah qui est l'Audient et l'Omniscient."},{"n":746,"s":5,"a":77,"t":"Dis: «O gens du Livre, n'exagérez pas en votre religion, s'opposant à la vérité. Ne suivez pas les passions des gens qui se sont égarés avant cela, qui ont égaré beaucoup de monde et qui se sont égarés du chemin droit."},{"n":747,"s":5,"a":78,"t":"Ceux des Enfants d'Israël qui n'avaient pas cru ont été maudits par la bouche de David et de Jésus fils de Marie, parce qu'ils désobéissaient et transgressaient."},{"n":748,"s":5,"a":79,"t":"Ils ne s'interdisaient pas les uns aux autres ce qu'ils faisaient de blâmable. Comme est mauvais, certes, ce qu'ils faisaient!"},{"n":749,"s":5,"a":80,"t":"Tu vois beaucoup d'entre eux s'allier aux mécréants. Comme est mauvais, certes, ce que leurs âmes ont préparé, pour eux-mêmes, de sorte qu'ils ont encouru le courroux d'Allah, et c'est dans le supplice qu'ils éterniseront."},{"n":750,"s":5,"a":81,"t":"S'ils croyaient en Allah, au Prophète et à ce qui lui a été descendu, ils ne prendraient pas ces mécréants pour alliés. Mais beaucoup d'entre eux sont pervers."},{"n":751,"s":5,"a":82,"t":"Tu trouveras certainement que les Juifs et les associateurs sont les ennemis les plus acharnés des croyants. Et tu trouveras certes que les plus disposés à aimer les croyants sont ceux qui disent: «Nous sommes chrétiens». C'est qu'il y a parmi eux des prêtres et des moines, et qu'ils ne s'enflent pas d'orgueil."},{"n":752,"s":5,"a":83,"t":"Et quand ils entendent ce qui a été descendu sur le Messager [Muhammad], tu vois leurs yeux déborder de larmes, parce qu'ils ont reconnu la vérité. Ils disent: «O notre Seigneur! Nous croyons: inscris-nous donc parmi ceux qui témoignent (de la véracité du Coran)."},{"n":753,"s":5,"a":84,"t":"Pourquoi ne croirions-nous pas en Allah et à ce qui nous est parvenu de la vérité. Pourquoi ne convoitions-nous pas que notre Seigneur nous fasse entrer en la compagnie des gens vertueux?»"},{"n":754,"s":5,"a":85,"t":"Allah donc les récompense pour ce qu'ils disent par des Jardins sous lesquels coulent les ruisseaux, où ils demeureront éternellement. Telle est la récompense des bienfaisants."},{"n":755,"s":5,"a":86,"t":"Et quant à ceux qui ne croient pas et qui traitent de mensonges Nos versets, ce sont les gens de la Fournaise."},{"n":756,"s":5,"a":87,"t":"O les croyants: ne déclarez pas illicites les bonnes choses qu'Allah vous a rendues licites. Et ne transgressez pas. Allah, (en vérité,) n'aime pas les transgresseurs."},{"n":757,"s":5,"a":88,"t":"Et mangez de ce qu'Allah vous a attribué de licite et de bon. Craignez Allah, en qui vous avez foi."},{"n":758,"s":5,"a":89,"t":"Allah ne vous sanctionne pas pour la frivolité dans vos serments, mais Il vous sanctionne pour les serments que vous avez l'intention d'exécuter. L'expiation en sera de nourrir dix pauvres, de ce dont vous nourrissez normalement vos familles, ou de les habiller, ou de libérer un esclave. Quiconque n'en trouve pas les moyens devra jeûner trois jours. Voilà l'expiation pour vos serments, lorsque vous avez juré. Et tenez à vos serments. Ainsi Allah vous explique Ses versets, afin que vous soyez reconnaissants!"},{"n":759,"s":5,"a":90,"t":"O les croyants! Le vin, le jeu de hasard, les pierres dressées, les flèches de divination ne sont qu'une abomination, œuvre du Diable. Ecartez-vous en, afin que vous réussissiez."},{"n":760,"s":5,"a":91,"t":"Le Diable ne veut que jeter parmi vous, à travers le vin et le jeu de hasard, l'inimitié et la haine, et vous détourner d'invoquer Allah et de la Salât. Allez-vous donc y mettre fin?"},{"n":761,"s":5,"a":92,"t":"Obéissez à Allah, obéissez au Messager, et prenez garde! Si ensuite vous vous détournez... alors sachez qu'il n'incombe à Notre messager que de transmettre le message clairement."},{"n":762,"s":5,"a":93,"t":"Ce n'est pas un péché pour ceux qui ont la foi et font de bonnes œuvres en ce qu'ils ont consommé (du vin et des gains des jeux de hasard avant leur prohibition) pourvu qu'ils soient pieux (en évitant les choses interdites après en avoir eu connaissance) et qu'ils croient (en acceptant leur prohibition) et qu'ils fassent de bonnes œuvres; puis qui (continuent) d'être pieux et de croire et qui (demeurent) pieux et bienfaisants. Car Allah aime les bienfaisants."},{"n":763,"s":5,"a":94,"t":"O les croyants! Allah va certainement vous éprouver par quelque gibier à la portée de vos mains et de vos lances. C'est pour qu'Allah sache celui qui Le craint en secret. Quiconque après cela transgresse aura un châtiment douloureux."},{"n":764,"s":5,"a":95,"t":"O les croyants! Ne tuez pas de gibier pendant que vous êtes en état d'Ihram. Quiconque parmi vous en tue délibérément, qu'il compense alors, soit par quelque bête de troupeau, semblable à ce qu'il a tué, d'après le jugement de deux personnes intègres parmi vous, et cela en offrande qu'il fera parvenir à (destination des pauvres de) la Ka'aba, ou bien par une expiation, en nourrissant des pauvres, ou par l'équivalent en jeûne. Cela afin qu'il goûte à la mauvaise conséquence de son acte. Allah a pardonné ce qui est passé; mais quiconque récidive, Allah le punira. Allah est Puissant et Détenteur du pouvoir de punir."},{"n":765,"s":5,"a":96,"t":"La chasse en mer vous est permise, et aussi d'en manger, pour votre jouissance et celle des voyageurs. Et vous est illicite la chasse à terre tant que vous êtes en état d'Ihram. Et craignez Allah vers qui vous serez rassemblés."},{"n":766,"s":5,"a":97,"t":"Allah a institué la Ka'aba, la Maison sacrée, comme un lieu de rassemblement pour les gens. (Il a institué) le mois sacré, l'offrande (d'animaux,) et les guirlandes, afin que vous sachiez que vraiment Allah sait tout ce qui est dans les cieux et sur la terre; et que vraiment Allah est Omniscient."},{"n":767,"s":5,"a":98,"t":"Sachez qu'Allah est sévère en punition, mais aussi qu'Allah est Pardonneur et Miséricordieux."},{"n":768,"s":5,"a":99,"t":"Il n'incombe au Messager que de transmettre (le message). Et Allah sait ce que vous divulguez tout comme ce que vous cachez."},{"n":769,"s":5,"a":100,"t":"Dis: «Le mauvais et le bon ne sont pas semblables, même si l'abondance du mal te séduit. Craignez Allah, donc, ô gens intelligents, afin que vous réussissiez."},{"n":770,"s":5,"a":101,"t":"O les croyants! Ne posez pas de questions sur des choses qui, si elles vous étaient divulguées, vous mécontenteraient. Et si vous posez des questions à leur sujet, pendant que le Coran est révélé, elles vous seront divulguées. Allah vous a pardonné cela. Et Allah est Pardonneur et Indulgent."},{"n":771,"s":5,"a":102,"t":"Un peuple avant vous avait posé des questions (pareilles) puis, devinrent de leur fait mécréants."},{"n":772,"s":5,"a":103,"t":"Allah n'a pas institué la Bahira, la Sâïba, la Wasîlani le Hâm. Mais ceux qui ont mécru ont inventé ce mensonge contre Allah, et la plupart d'entre eux ne raisonnent pas."},{"n":773,"s":5,"a":104,"t":"Et quand on leur dit: «Venez vers ce qu'Allah a fait descendre (la Révélation), et vers le Messager», ils disent: «Il nous suffit de ce sur quoi nous avons trouvé nos ancêtres.» Quoi! Même si leurs ancêtres ne savaient rien et n'étaient pas sur le bon chemin...?"},{"n":774,"s":5,"a":105,"t":"O les croyants! Vous êtes responsables de vous-mêmes! Celui qui s'égare ne vous nuira point si vous vous avez pris la bonne voie. C'est Vers Allah que vous retournerez tous; alors Il vous informera de ce que vous faisiez."},{"n":775,"s":5,"a":106,"t":"O les croyants! Quand la mort se présente à l'un de vous, le testament sera attesté par deux hommes intègres d'entre vous, ou deux autres, non des vôtres, si vous êtes en voyage dans le monde et que la mort vous frappe. Vous les retiendrez (les deux témoins), après la Sal?t, puis, si vous avez des doutes, vous les ferez jurer par Allah: «Nous ne faisons aucun commerce ou profit avec cela, même s'il s'agit d'un proche, et nous ne cacherons point le témoignage d'Allah. Sinon, nous serions du nombre des pécheurs»."},{"n":776,"s":5,"a":107,"t":"Si l'on découvre que ces deux témoins sont coupables de péché, deux autres plus intègres, parmi ceux auxquels le tort a été fait, prendront leur place et tous deux jureront par Allah: «En vérité, notre témoignage est plus juste que le témoignage de ces deux-là; et nous ne transgressons point. Sinon, nous serions certainement du nombre des injustes»."},{"n":777,"s":5,"a":108,"t":"C'est le moyen le plus sûr pour les inciter à fournir le témoignage dans sa forme réelle; ou leur faire craindre de voir d'autres serments se substituer aux leurs. Et craignez Allah et écoutez. Allah ne guide pas les gens pervers."},{"n":778,"s":5,"a":109,"t":"(Rappelle-toi) le jour où Allah rassemblera (tous) les messagers, et qu'Il dira: «Que vous a-t-on donné comme réponse?» Ils diront: «Nous n'avons aucun savoir: c'est Toi, vraiment, le grand connaisseur de tout ce qui est inconnu»."},{"n":779,"s":5,"a":110,"t":"Et quand Allah dira: «O Jésus, fils de Marie, rappelle-toi Mon bienfait sur toi et sur ta mère quand Je te fortifiais du Saint-Esprit. Au berceau tu parlais aux gens, tout comme en ton âge mûr. Je t'enseignais le Livre, la Sagesse, la Thora et l'Evangile! Tu fabriquais de l'argile comme une forme d'oiseau par Ma permission; puis tu soufflais dedans. Alors par Ma permission, elle devenait oiseau. Et tu guérissais par Ma permission, l'aveugle-né et le lépreux. Et par Ma permission, tu faisais revivre les morts. Je te protégeais contre les Enfants d'Israël pendant que tu leur apportais les preuves. Mais ceux d'entre eux qui ne croyaient pas dirent: «Ceci n'est que de la magie évidente»."},{"n":780,"s":5,"a":111,"t":"Et quand J'ai révélé aux Apôtres ceci: «Croyez en Moi et en Mon messager (Jésus)». Ils dirent: «Nous croyons; et atteste que nous sommes entièrement soumis»."},{"n":781,"s":5,"a":112,"t":"Rappelle-toi le moment) où les Apôtres dirent: «O Jésus, fils de Marie, se peut-il que ton Seigneur fasse descendre sur nous du ciel une table servie?» Il leur dit: «Craignez plutôt Allah, si vous êtes croyants»."},{"n":782,"s":5,"a":113,"t":"Ils dirent: «Nous voulons en manger, rassurer ainsi nos cœurs, savoir que tu nous as réellement dit la vérité et en être parmi les témoins»."},{"n":783,"s":5,"a":114,"t":"«O Allah, notre Seigneur, dit Jésus, fils de Marie, fais descendre du ciel sur nous une table servie qui soit une fête pour nous, pour le premier d'entre nous, comme pour le dernier, ainsi qu'un signe de Ta part. Nourris-nous: Tu es le meilleur des nourrisseurs.»"},{"n":784,"s":5,"a":115,"t":"«Oui, dit Allah, Je la ferai descendre sur vous. Mais ensuite, quiconque d'entre vous refuse de croire, Je le châtierai d'un châtiment dont Je ne châtierai personne d'autre dans l'univers.»"},{"n":785,"s":5,"a":116,"t":"(Rappelle-leur) le moment où Allah dira: «O Jésus, fils de Marie, est-ce toi qui as dit aux gens: «Prenez-moi, ainsi que ma mère, pour deux divinités en dehors d'Allah?» Il dira: «Gloire et pureté à Toi! Il ne m'appartient pas de déclarer ce que je n'ai pas le droit de dire! Si je l'avais dit, Tu l'aurais su, certes. Tu sais ce qu'il y a en moi, et je ne sais pas ce qu'il y a en Toi. Tu es, en vérité, le grand connaisseur de tout ce qui est inconnu."},{"n":786,"s":5,"a":117,"t":"Je ne leur ai dit que ce que Tu m'avais commandé, (à savoir): «Adorez Allah, mon Seigneur et votre Seigneur». Et je fus témoin contre eux aussi longtemps que je fus parmi eux. Puis quand Tu m'as rappelé, c'est Toi qui fus leur observateur attentif. Et Tu es témoin de toute chose."},{"n":787,"s":5,"a":118,"t":"Si Tu les châties, ils sont Tes serviteurs. Et si Tu leur pardonnes, c'est Toi le Puissant, le Sage»."},{"n":788,"s":5,"a":119,"t":"Allah dira: «Voilà le jour où leur véracité va profiter aux véridiques: ils auront des Jardins sous lesquels coulent les ruisseaux pour y demeurer éternellement.» Allah les a agréés et eux L'ont agréé. Voilà l'énorme succès."},{"n":789,"s":5,"a":120,"t":"A Allah seul appartient le royaume des cieux, de la terre et de ce qu'ils renferment. Et Il est Omnipotent."},{"n":790,"s":6,"a":1,"t":"Louange à Allah qui a créé les cieux et la terre, et établi les ténèbres et la lumière. Pourtant, les mécréants donnent des égaux à leur Seigneur."},{"n":791,"s":6,"a":2,"t":"C'est Lui qui vous a créés d'argile; puis il vous a décrété un terme, et il y a un terme fixé auprès de Lui. Pourtant, vous doutez encore!"},{"n":792,"s":6,"a":3,"t":"Et Lui, Il est Allah dans les cieux et sur la terre. Il connaît ce que vous cachez en vous et ce que vous divulguez et Il sait ce que vous acquérez."},{"n":793,"s":6,"a":4,"t":"Et il ne leur vient aucun des signes d'entre les signes de leur Seigneur, sans qu'ils ne s'en détournent."},{"n":794,"s":6,"a":5,"t":"Ils traitent de mensonge la vérité quand celle-ci leur vient. Mais ils vont avoir des nouvelles de ce dont ils se moquent."},{"n":795,"s":6,"a":6,"t":"N'ont-ils pas vu combien de générations, avant eux, Nous avons détruites, auxquelles Nous avions donné pouvoir sur terre, bien plus que ce que Nous vous avons donnés? Nous avions envoyé, sur eux, du ciel, la pluie en abondance, et Nous avions fait couler des rivières à leurs pieds. Puis Nous les avons détruites, pour leurs péchés; et Nous avons créé après eux, une nouvelle génération."},{"n":796,"s":6,"a":7,"t":"Même si Nous avions fait descendre sur toi (Muhammad) un Livre en papier qu'ils pouvaient toucher de leurs mains, ceux qui ne croient pas auraient certainement dit: «Ce n'est que de la magie évidente!»"},{"n":797,"s":6,"a":8,"t":"Et ils disent: «Pourquoi n'a-t-on pas fait descendre sur lui (Muhammad) un Ange?» Si Nous avions fait descendre un Ange, c'eût été, sûrement, affaire faite; puis on ne leur eût point donné de délai."},{"n":798,"s":6,"a":9,"t":"Si Nous avions désigné un Ange [comme prophète], Nous aurions fait de lui un homme et Nous leur aurions causé la même confusion que celle dans laquelle ils sont."},{"n":799,"s":6,"a":10,"t":"Certes, on s'est moqué de messagers avant toi, mais ceux qui se sont raillés d'eux, leur propre raillerie les enveloppa."},{"n":800,"s":6,"a":11,"t":"Dis: «Parcourez la terre et regardez ce qu'il est advenu de ceux qui traitaient la vérité de mensonge»."},{"n":801,"s":6,"a":12,"t":"Dis: «A qui appartient ce qui est dans les cieux et la terre?» Dis: «A Allah!» Il S'est à Lui-même prescrit la miséricorde. Il vous rassemblera, certainement, au Jour de la Résurrection: il n'y a pas de doute là-dessus. Ceux qui font leur propre perte sont ceux qui ne croient pas."},{"n":802,"s":6,"a":13,"t":"Et à Lui tout ce qui réside dans la nuit et le jour. C'est Lui qui est l'Audient, l'Omniscient."},{"n":803,"s":6,"a":14,"t":"Dis: «Devais-je prendre pour allié autre qu'Allah, le Créateur des cieux et de la terre? C'est Lui qui nourrit et personne ne Le nourrit. Dis: «On m'a commandé d'être le premier à me soumettre». Et ne sois jamais du nombre des associateurs."},{"n":804,"s":6,"a":15,"t":"Dis: «Je crains, si je désobéis à mon Seigneur, le châtiment d'un jour redoutable»."},{"n":805,"s":6,"a":16,"t":"En ce jour, quiconque est épargné, c'est qu'[Allah] lui a fait miséricorde. Et voilà le succès éclatant."},{"n":806,"s":6,"a":17,"t":"Et si Allah fait qu'un malheur te touche, nul autre que Lui ne peut l'enlever. Et s'Il fait qu'un bonheur te touche... c'est qu'Il est Omnipotent."},{"n":807,"s":6,"a":18,"t":"C'est Lui le Dominateur Suprême sur Ses serviteurs; c'est Lui le Sage, le Parfaitement Connaisseur."},{"n":808,"s":6,"a":19,"t":"Dis: «Qu'y a-t-il de plus grand en fait de témoignage?» Dis: «Allah est témoin entre moi et vous; et ce Coran m'a été révélé pour que je vous avertisse, par sa voie, vous et tous ceux qu'il atteindra. «Est-ce vous vraiment qui attestez qu'il y ait avec Allah d'autres divinités? Dis: «Je n'atteste pas». Dis [aussi]: «Il n'y a qu'une Divinité Unique. Et moi, je désavoue ce que vous (Lui) associez»."},{"n":809,"s":6,"a":20,"t":"Ceux à qui Nous avons donné le Livre reconnaissent (le Messager Muhammad) comme ils reconnaissent leurs propres enfants. Ceux qui font leur propre perte sont ceux qui ne croient pas."},{"n":810,"s":6,"a":21,"t":"Qui donc est plus injuste que celui qui invente un mensonge contre Allah, ou qui traite de mensonge Ses versets? Les injustes ne réussiront pas."},{"n":811,"s":6,"a":22,"t":"Et le Jour où Nous les rassemblerons tous puis dirons à ceux qui auront donné des associés: «Où sont donc vos associés que vous prétendiez?»"},{"n":812,"s":6,"a":23,"t":"Alors il ne leur restera comme excuse que de dire: «Par Allah notre Seigneur! Nous n'étions jamais des associateurs»."},{"n":813,"s":6,"a":24,"t":"Vois comment ils mentent à eux-mêmes! Et comment les abandonnent (les associés) qu'ils inventaient!"},{"n":814,"s":6,"a":25,"t":"Il en est parmi eux qui viennent t'écouter, cependant que Nous avons entouré de voiles leurs cœurs, qui les empêchent de comprendre (le Coran), et dans leurs oreilles est une lourdeur. Quand même ils verraient toutes sortes de preuves, ils n'y croiraient pas. Et quand ils viennent disputer avec toi, ceux qui ne croient pas disent alors: «Ce ne sont que des légendes des anciens»."},{"n":815,"s":6,"a":26,"t":"Ils empêchent [les gens] de s'approcher de lui et s'en écartent eux-mêmes. Ils ne feront périr qu'eux-mêmes sans s'en rendre compte."},{"n":816,"s":6,"a":27,"t":"Si tu les voyais, quand ils seront placés devant le Feu. Ils diront alors: «Hélas! Si nous pouvions être renvoyés (sur la terre), nous ne traiterions plus de mensonges les versets de notre Seigneur et nous serions du nombre des croyants»."},{"n":817,"s":6,"a":28,"t":"Mais non! Voilà que leur apparaîtra ce qu'auparavant ils cachaient. Or, s'ils étaient rendus [à la vie terrestre], ils reviendraient sûrement à ce qui leur était interdit. Ce sont vraiment des menteurs."},{"n":818,"s":6,"a":29,"t":"Et ils disent: «Il n'y a pour nous [d'autre vie] que celle d'ici-bas; et nous ne serons pas ressuscités»."},{"n":819,"s":6,"a":30,"t":"Si tu les voyais, quand ils comparaîtront devant leur Seigneur. Il leur dira: «Cela n'est-il pas la vérité?» Ils diront: «Mais si! Par notre Seigneur!» Et, il dira: «Goûtez alors au châtiment pour n'avoir pas cru»."},{"n":820,"s":6,"a":31,"t":"Sont perdants certes ceux qui traitent de mensonge la rencontre d'Allah. Et quand soudain l'Heure leur viendra, ils diront: «Malheur à nous pour notre négligence à son égard, Et ils porteront leurs fardeaux sur leurs dos, et quels mauvais fardeaux!"},{"n":821,"s":6,"a":32,"t":"La présente vie n'est que jeu et amusement. La demeure dans l'au-delà sera meilleure pour ceux qui sont pieux. Eh bien, ne comprenez-vous pas?"},{"n":822,"s":6,"a":33,"t":"Nous savons qu'en vérité ce qu'ils disent te chagrine. Or, vraiment ils ne croient pas que tu es menteur, mais ce sont les versets (le Coran) d'Allah, que les injustes renient."},{"n":823,"s":6,"a":34,"t":"Certes, des messagers avant toi (Muhammad) ont été traités de menteurs. Ils endurèrent alors avec constance d'être traités de menteurs et d'être persécutés, jusqu'à ce que Notre secours leur vînt. Et nul ne peut changer les paroles d'Allah, et il t'est déjà parvenu une partie de l'histoire des Envoyés."},{"n":824,"s":6,"a":35,"t":"Et si leur indifférence t'afflige énormément, et qu'il est dans ton pouvoir de chercher un tunnel à travers la terre, ou une échelle pour aller au ciel pour leur apporter un miracle, [fais-le donc]. Et si Allah voulait, Il pourrait les mettre tous sur le chemin droit. Ne sois pas du nombre des ignorants."},{"n":825,"s":6,"a":36,"t":"Seuls ceux qui entendent répondent à l'appel [de la foi]. Et quant aux morts, Allah les ressuscitera; puis ils Lui seront ramenés."},{"n":826,"s":6,"a":37,"t":"Et ils disent: «Pourquoi n'a-t-on pas fait descendre sur lui (Muhammad) un miracle de la part de son Seigneur?» Dis: «Certes Allah est capable de faire descendre un miracle. Mais la plupart d'entre eux ne savent pas»."},{"n":827,"s":6,"a":38,"t":"Nulle bête marchant sur terre, nul oiseau volant de ses ailes, qui ne soit comme vous en communauté. Nous n'avons rien omis d'écrire dans le Livre. Puis, c'est vers leur Seigneur qu'ils seront ramenés."},{"n":828,"s":6,"a":39,"t":"Et ceux qui traitent de mensonges Nos versets sont sourds et muets, dans les ténèbres. Allah égare qui Il veut; et Il place qui Il veut sur un chemin droit."},{"n":829,"s":6,"a":40,"t":"Dis: «Informez-moi: si le châtiment d'Allah vous vient, ou que vous vient l'Heure, ferez-vous appel à autre qu'Allah, si vous êtes véridiques?»"},{"n":830,"s":6,"a":41,"t":"C'est plutôt à Lui que vous ferez appel. Puis, Il dissipera, s'Il veut, l'objet de votre appel et vous oublierez ce que vous [Lui] associez."},{"n":831,"s":6,"a":42,"t":"Nous avons, certes, envoyé (des messagers) aux communautés avant toi. Ensuite Nous les avons saisies par l'adversité et la détresse - peut-être imploreront-ils (la miséricorde)! -"},{"n":832,"s":6,"a":43,"t":"Pourquoi donc, lorsque Notre rigueur leur vînt, n'ont-ils pas imploré (la miséricorde)? Mais leurs cœurs s'étaient endurcis et le Diable enjolivait à leurs yeux ce qu'ils faisaient."},{"n":833,"s":6,"a":44,"t":"Puis, lorsqu'ils eurent oublié ce qu'on leur avait rappelé, Nous leur ouvrîmes les portes donnant sur toute chose (l'abondance); et lorsqu'ils eurent exulté de joie en raison de ce qui leur avait été donné, Nous les saisîmes soudain, et les voilà désespérés."},{"n":834,"s":6,"a":45,"t":"Ainsi fut exterminé le dernier reste de ces injustes. Et louange à Allah, Seigneur de l'Univers!"},{"n":835,"s":6,"a":46,"t":"Dis: «Voyez-vous? Si Allah prenait votre ouïe et votre vue, et scellait vos cœurs, quelle divinité autre qu'Allah vous les rendrait? Regarde comment, à leur intention, Nous clarifions les preuves! Pourtant ils s'en détournent."},{"n":836,"s":6,"a":47,"t":"Dis: «Que vous en semble? Si le châtiment d'Allah vous venait à l'improviste ou au grand jour, qui seront détruits sinon les gens injustes?»"},{"n":837,"s":6,"a":48,"t":"Nous n'envoyons des messagers qu'en annonciateurs et avertisseurs: ceux qui croient donc et se réforment, nulle crainte sur eux et ils ne seront point affligés."},{"n":838,"s":6,"a":49,"t":"Et ceux qui traitent de mensonges Nos preuves, le châtiment les touchera, à cause de leur perversité."},{"n":839,"s":6,"a":50,"t":"Dis-[leur]: «Je ne vous dis pas que je détiens les trésors d'Allah, ni que je connais l'Inconnaissable, et je ne vous dis pas que je suis un ange. Je ne fais que suivre ce qui m'est révélé.» Dis: «Est-ce que sont égaux l'aveugle et celui qui voit? Ne réfléchissez-vous donc pas?»"},{"n":840,"s":6,"a":51,"t":"Et avertis par ceci (le Coran), ceux qui craignent d'être rassemblés devant leur Seigneur, qu'ils n'auront hors d'Allah ni allié ni intercesseur. Peut-être deviendraient-ils pieux!"},{"n":841,"s":6,"a":52,"t":"Et ne repousse pas ceux qui, matin et soir, implorent leur Seigneur, cherchant sa Face «Wajh». Leur demander compte ne t'incombe en rien, et te demander compte ne leur incombe en rien. En les repoussant donc, tu serais du nombre des injustes."},{"n":842,"s":6,"a":53,"t":"Ainsi, éprouvons-Nous (les gens) les uns par les autres, pour qu'ils disent: «Est-ce là ceux qu'Allah a favorisés parmi nous?» N'est-ce pas Allah qui sait le mieux lesquels sont reconnaissants?"},{"n":843,"s":6,"a":54,"t":"Et lorsque viennent vers toi ceux qui croient à nos versets (le Coran), dis: «Que la paix soit sur vous! Votre Seigneur S'est prescrit à Lui-même la miséricorde. Et quiconque d'entre vous a fait un mal par ignorance, et ensuite s'est repenti et s'est réformé... Il est, alors, Pardonneur et Miséricordieux»."},{"n":844,"s":6,"a":55,"t":"C'est ainsi que Nous détaillons les versets, afin qu'apparaisse clairement le chemin des criminels."},{"n":845,"s":6,"a":56,"t":"Dis: «il m'a été interdit d'adorer ceux que vous priez en dehors d'Allah». Dis: «Je ne suivrai pas vos passions: car ce serait m'égarer, et je ne serais plus parmi les bien-guidés»."},{"n":846,"s":6,"a":57,"t":"Dis: «Je m'appuie sur une preuve évidente de la part de mon Seigneur, et vous avez traité cela de mensonge. Ce (le châtiment) que vous voulez hâter ne dépend pas de moi. Le jugement n'appartient qu'à Allah: Il tranche en toute vérité et Il est le meilleur des juges."},{"n":847,"s":6,"a":58,"t":"Dis: «Si ce que vous voulez hâter dépendait de moi, ce serait affaire faite entre vous et moi.» C'est Allah qui connaît le mieux les injustes."},{"n":848,"s":6,"a":59,"t":"C'est Lui qui détient les clefs de l'Inconnaissable. Nul autre que Lui ne les connaît. Et Il connaît ce qui est dans la terre ferme, comme dans la mer. Et pas une feuille ne tombe qu'Il ne le sache. Et pas une graine dans les ténèbres de la terre, rien de frais ou de sec, qui ne soit consigné dans un livre explicite."},{"n":849,"s":6,"a":60,"t":"Et, la nuit, c'est Lui qui prend vos âmes, et Il sait ce que vous avez acquis pendant le jour. Puis Il vous ressuscite le jour afin que s'accomplisse le terme fixé. Ensuite, c'est vers Lui que sera votre retour, et Il vous informera de ce que vous faisiez."},{"n":850,"s":6,"a":61,"t":"Et Il est le Dominateur Suprême sur Ses serviteurs. Et Il envoie sur vous des gardiens. Et lorsque la mort atteint l'un de vous, Nos messagers (les Anges) enlèvent son âme sans aucune négligence."},{"n":851,"s":6,"a":62,"t":"Ils sont ensuite ramenés vers Allah, leur vrai Maître. C'est à Lui qu'appartient le jugement et Il est le plus prompt des juges."},{"n":852,"s":6,"a":63,"t":"Dis: «Qui vous délivre des ténèbres de la terre et de la mer?» Vous l'invoquez humblement et en secret: «S'Il nous délivre de ceci, nous serons du nombre des reconnaissants."},{"n":853,"s":6,"a":64,"t":"Dis: «C'est Allah qui vous en délivre ainsi que de toute angoisse. Pourtant, vous Lui donnez des associés»."},{"n":854,"s":6,"a":65,"t":"Dis: «Il est capable, Lui, de susciter contre vous, d'en haut, ou de dessous vos pieds, un châtiment, ou de vous confondre dans le sectarisme. Et Il vous fait goûter l'ardeur [au combat] les uns aux autres.» Regarde comment Nous exposons Nos versets. Peut-être comprendront-ils?"},{"n":855,"s":6,"a":66,"t":"Et ton peuple traite cela (le Coran) de mensonge, alors que c'est la vérité. Dis: «Je ne suis pas votre garant."},{"n":856,"s":6,"a":67,"t":"Chaque annonce arrive en son temps et en son lieu. Et bientôt vous le saurez.»"},{"n":857,"s":6,"a":68,"t":"Quand tu vois ceux qui pataugent dans des discussions à propos de Nos versets, éloigne-toi d'eux jusqu'à ce qu'ils entament une autre discussion. Et si le Diable te fait oublier, alors, dès que tu te rappelles, ne reste pas avec les injustes."},{"n":858,"s":6,"a":69,"t":"Il n'incombe nullement à ceux qui sont pieux de rendre compte pour ces gens là. Mais c'est à titre de rappel. Peut-être craindront-ils [Allah]."},{"n":859,"s":6,"a":70,"t":"Laisse ceux qui prennent leur religion pour jeu et amusement, et qui sont séduits par la vie sur terre. Et rappelle par ceci (le Coran) pour qu'une âme ne s'expose pas à sa perte selon ce qu'elle aura acquis, elle n'aura en dehors d'Allah, ni allié ni intercesseur. Et quelle que soit la compensation qu'elle offrirait, elle ne sera pas acceptée d'elle. Ceux-là se sont abandonnés à leur perdition à cause de ce qu'ils ont acquis. Leur breuvage sera l'eau bouillante et ils auront un châtiment douloureux, pour avoir mécru."},{"n":860,"s":6,"a":71,"t":"Dis: «Invoquerons-nous, au lieu d'Allah, ce qui ne peut nous profiter ni nous nuire? Et reviendrons-nous sur nos talons après qu'Allah nous a guidés, comme quelqu'un que les diables ont séduit et qui erre perplexe sur la terre, bien que des amis l'appellent vers le droit chemin (lui disant): - «Viens à nous». Dis: «Le vrai chemin, c'est le chemin d'Allah. Et il nous a été commandé de nous soumettre au Seigneur de l'Univers,"},{"n":861,"s":6,"a":72,"t":"Et d'accomplir la Salât et de Le craindre. C'est vers Lui que vous serez rassemblés»."},{"n":862,"s":6,"a":73,"t":"Et c'est Lui qui a créé les cieux et la terre, en toute vérité. Et le jour où Il dit: «Sois!» Cela est, Sa parole est la vérité. A Lui, [seul,] la royauté, le jour où l'on soufflera dans la Trompe. C'est Lui le Connaisseur de ce qui est voilé et de ce qui est manifeste. Et c'est Lui le Sage et le Parfaitement Connaisseur."},{"n":863,"s":6,"a":74,"t":"(Rappelle le moment) où Abraham dit à `Azar, son père: «Prends-tu des idoles comme divinités? Je te vois, toi et ton peuple, dans un égarement évident!»"},{"n":864,"s":6,"a":75,"t":"Ainsi avons-Nous montré à Abraham le royaume des cieux et de la terre, afin qu'il fût de ceux qui croient avec conviction."},{"n":865,"s":6,"a":76,"t":"Quand la nuit l'enveloppa, il observa une étoile, et dit: «Voilà mon Seigneur!» Puis, lorsqu'elle disparut, il dit: «Je n'aime pas les choses qui disparaissent»."},{"n":866,"s":6,"a":77,"t":"Lorsqu'ensuite il observa la lune se levant, il dit: «Voilà mon Seigneur!» Puis, lorsqu'elle disparut, il dit: «Si mon Seigneur ne me guide pas, je serai certes du nombre des gens égarés»."},{"n":867,"s":6,"a":78,"t":"Lorsqu'ensuite il observa le soleil levant, il dit: «Voilà mon Seigneur! Celui-ci est plus grand» Puis lorsque le soleil disparut, il dit: «O mon peuple, je désavoue tout ce que vous associez à Allah."},{"n":868,"s":6,"a":79,"t":"Je tourne mon visage exclusivement vers Celui qui a créé (à partir du néant) les cieux et la terre; et je ne suis point de ceux qui Lui donnent des associés.»"},{"n":869,"s":6,"a":80,"t":"Son peuple disputa avec lui; mais il dit: «Allez-vous disputer avec moi au sujet d'Allah, alors qu'Il m'a guidé? Je n'ai pas peur des associés que vous Lui donnez. Je ne crains que ce que veut mon Seigneur. Mon Seigneur embrasse tout dans Sa science. Ne vous rappelez-vous donc pas?"},{"n":870,"s":6,"a":81,"t":"Et comment aurais-je peur des associés que vous Lui donnez, alors que vous n'avez pas eu peur d'associer à Allah des choses pour lesquelles Il ne vous a fait descendre aucune preuve? Lequel donc des deux partis a le plus droit à la sécurité? (Dites-le) si vous savez."},{"n":871,"s":6,"a":82,"t":"Ceux qui ont cru et n'ont point troublé la pureté de leur foi par quelqu'inéquité (association), ceux-là ont la sécurité; et ce sont eux les bien-guidés»."},{"n":872,"s":6,"a":83,"t":"Tel est l'argument que Nous inspirâmes à Abraham contre son peuple. Nous élevons en haut rang qui Nous voulons. Ton Seigneur est Sage et Omniscient."},{"n":873,"s":6,"a":84,"t":"Et Nous lui avons donné Isaac et Jacob et Nous les avons guidés tous les deux. Et Noé, Nous l'avons guidé auparavant, et parmi la descendance (d'Abraham) (ou de Noé), David, Salomon, Job, Joseph, Moïse et Aaron. Et c'est ainsi que Nous récompensons les bienfaisants."},{"n":874,"s":6,"a":85,"t":"De même, Zacharie, Jean-Baptiste, Jésus et Elie, tous étant du nombre des gens de bien."},{"n":875,"s":6,"a":86,"t":"De même, Ismaël, Elisée, Jonas et Lot. Chacun d'eux Nous l'avons favorisé par dessus le reste du monde."},{"n":876,"s":6,"a":87,"t":"De même une partie de leurs ancêtres, de leurs descendants et de leurs frères et Nous les avons choisis et guidés vers un chemin droit."},{"n":877,"s":6,"a":88,"t":"Telle est la direction par laquelle Allah guide qui Il veut parmi Ses serviteurs. Mais s'ils avaient donné à Allah des associés, alors, tout ce qu'ils auraient fait eût certainement été vain."},{"n":878,"s":6,"a":89,"t":"C'est à eux que Nous avons apporté le Livre, la sagesse et la prophétie. Si ces autres-là n'y croient pas, du moins Nous avons confié ces choses à des gens qui ne les nient pas."},{"n":879,"s":6,"a":90,"t":"Voilà ceux qu'Allah a guidés: suis donc leur direction. Dis: «Je ne vous demande pas pour cela de salaire». Ce n'est qu'un rappel à l'intention de tout l'univers."},{"n":880,"s":6,"a":91,"t":"Ils n'apprécient pas Allah comme Il le mérite quand ils disent: «Allah n'a rien fait descendre sur un humain.» Dis: «Qui a fait descendre le Livre que Moïse a apporté comme lumière et guide, pour les gens? Vous le mettez en feuillets, pour en montrer une partie, tout en cachant beaucoup. Vous avez été instruits de ce que vous ne saviez pas, ni vous ni vos ancêtres. Dis: «C'est Allah». Et puis, laisse-les s'amuser dans leur égarement."},{"n":881,"s":6,"a":92,"t":"Voici un Livre (le Coran) béni que Nous avons fait descendre, confirmant ce qui existait déjà avant lui, afin que tu avertisses la Mère des Cités (la Mecque) et les gens tout autour. Ceux qui croient au Jour dernier, y croient et demeurent assidus dans leur Salât."},{"n":882,"s":6,"a":93,"t":"Et quel pire injuste que celui qui fabrique un mensonge contre Allah ou qui dit: «Révélation m'a été faite», quand rien ne lui a été révélé. De même celui qui dit: «Je vais faire descendre quelque chose de semblable à ce qu'Allah a fait descendre.» Si tu voyais les injustes lorsqu'ils seront dans les affres de la mort, et que les Anges leur tendront les mains (disant): «Laissez sortir vos âmes. Aujourd'hui vous allez être récompensés par le châtiment de l'humiliation pour ce que vous disiez sur Allah d'autre que la vérité et parce que vous vous détourniez orgueilleusement de Ses enseignements»."},{"n":883,"s":6,"a":94,"t":"Et vous voici venus à Nous, seuls, tout comme Nous vous avions créés la première fois, abandonnant derrière vos dos tout ce que Nous vous avions accordé. Nous ne vous voyons point accompagnés des intercesseurs que vous prétendiez être des associés. Il y a certainement eu rupture entre vous: ils vous ont abandonnés, ceux que vous prétendiez (être vos intercesseurs)."},{"n":884,"s":6,"a":95,"t":"C'est Allah qui fait fendre la graine et le noyau: du mort il fait sortir le vivant, et du vivant, il fait sortir le mort. Tel est Allah. Comment donc vous laissez-vous détourner?"},{"n":885,"s":6,"a":96,"t":"Fendeur de l'aube, Il a fait de la nuit une phase de repos; le soleil et la lune pour mesurer le temps. Voilà l'ordre conçu par le Puissant, l'Omniscient."},{"n":886,"s":6,"a":97,"t":"Et c'est Lui qui vous a assigné les étoiles, pour que, par elles, vous vous guidiez dans les ténèbres de la terre et de la mer. Certes, Nous exposons les preuves pour ceux qui savent!"},{"n":887,"s":6,"a":98,"t":"Et c'est Lui qui vous a créés à partir d'une personne unique (Adam). Et il y a une demeure et un lieu de dépôt (pour vous.) Nous avons exposé les preuves pour ceux qui comprennent."},{"n":888,"s":6,"a":99,"t":"Et c'est Lui qui, du ciel, a fait descendre l'eau. Puis par elle, Nous fîmes germer toute plante, de quoi Nous fîmes sortir une verdure, d'où Nous produisîmes des grains, superposés les uns sur les autres; et du palmier, de sa spathe, des régimes de dattes qui se tendent. Et aussi les jardins de raisins, l'olive et la grenade, semblables ou différents les uns des autres. Regardez leurs fruits au moment de leur production et de leur mûrissement. Voilà bien là des signes pour ceux qui ont la foi."},{"n":889,"s":6,"a":100,"t":"Et ils ont désigné des associés à Allah: les djinns, alors que c'est Lui qui les a créés. Et ils Lui ont inventé, dans leur ignorance, des fils et des filles, Gloire à Lui! Il transcende tout ce qu'ils lui attribuent."},{"n":890,"s":6,"a":101,"t":"Créateur des cieux et de la terre. Comment aurait-Il un enfant, quand Il n'a pas de compagne? C'est Lui qui a tout créé, et Il est Omniscient."},{"n":891,"s":6,"a":102,"t":"Voilà Allah, votre Seigneur! Il n'y a de divinité que Lui, Créateur de tout. Adorez-Le donc. C'est Lui qui a charge de tout."},{"n":892,"s":6,"a":103,"t":"Les regards ne peuvent l'atteindre, cependant qu'Il saisit tous les regards. Et Il est le Doux, le Parfaitement Connaisseur."},{"n":893,"s":6,"a":104,"t":"Certes, il vous est parvenu des preuves évidentes, de la part de votre Seigneur. Donc, quiconque voit clair, c'est en sa faveur; et quiconque reste aveugle, c'est à son détriment, car je ne suis nullement chargé de votre sauvegarde."},{"n":894,"s":6,"a":105,"t":"C'est ainsi que Nous expliquons les versets. Et afin qu'ils disent: «Tu as étudié». Et afin de l'exposer clairement à des gens qui savent."},{"n":895,"s":6,"a":106,"t":"Suis ce qui t'est révélé de la part de ton Seigneur. Point de divinité autre que Lui. Et écarte-toi des associateurs."},{"n":896,"s":6,"a":107,"t":"Si Allah voulait, ils ne seraient point associateurs! Mais Nous ne t'avons pas désigné comme gardien sur eux; et tu n'es pas leur garant."},{"n":897,"s":6,"a":108,"t":"N'injuriez pas ceux qu'ils invoquent, en dehors d'Allah, car par agressivité, ils injurieraient Allah, dans leur ignorance. De même, Nous avons enjolivé (aux yeux) de chaque communauté sa propre action. Ensuite, c'est vers leur Seigneur que sera leur retour; et Il les informera de ce qu'ils œuvraient."},{"n":898,"s":6,"a":109,"t":"Et ils jurent par Allah de toute la force de leurs serments, que s'il leur venait un miracle, ils y croiraient (sans hésiter,) Dis: «En vérité, les miracles ne dépendent que d'Allah.» Mais qu'est ce qui vous fait penser que quand cela (le signe) arrivera, ils n'y croiront pas?"},{"n":899,"s":6,"a":110,"t":"Parce qu'ils n'ont pas cru la première fois, nous détournerons leurs cœurs et leurs yeux; nous les laisserons marcher aveuglement dans leur rébellion."},{"n":900,"s":6,"a":111,"t":"Et si Nous faisions descendre les Anges vers eux, [comme ils l'avaient proposé] si les morts leur parlaient, et si Nous rassemblions toute chose devant eux, ils ne croiraient que si Allah veut. Mais la plupart d'entre eux ignorent."},{"n":901,"s":6,"a":112,"t":"Ainsi, à chaque prophète avons-Nous assigné un ennemi: des diables d'entre les hommes et les djinns, qui s'inspirent trompeusement les uns aux autres des paroles enjolivées. Si ton Seigneur avait voulu, ils ne l'auraient pas fait; laisse-les donc avec ce qu'ils inventent."},{"n":902,"s":6,"a":113,"t":"Et pour que les cœurs de ceux qui ne croient pas à l'au-delà se penchent vers elles, qu'ils les agréent, et qu'ils perpètrent ce qu'ils perpètrent."},{"n":903,"s":6,"a":114,"t":"Chercherai-je un autre juge qu'Allah, alors que c'est Lui qui a fait descendre vers vous ce Livre bien exposé? Ceux auxquels Nous avons donné le Livre savent qu'il est descendu avec la vérité venant de ton Seigneur. Ne sois donc point du nombre de ceux qui doutent."},{"n":904,"s":6,"a":115,"t":"Et la parole de ton Seigneur s'est accomplie en toute vérité et équité. Nul ne peut modifier Ses paroles. Il est l'Audient, l'Omniscient."},{"n":905,"s":6,"a":116,"t":"Et si tu obéis à la majorité de ceux qui sont sur la terre, ils t'égareront du sentier d'Allah: ils ne suivent que la conjecture et ne font que fabriquer des mensonges."},{"n":906,"s":6,"a":117,"t":"Certes ton Seigneur connaît le mieux ceux qui s'égarent de Son sentier, et c'est Lui qui connaît le mieux les bien-guidés."},{"n":907,"s":6,"a":118,"t":"Mangez donc de ce sur quoi on a prononcé le nom d'Allah si vous êtes croyants en Ses versets (le Coran)."},{"n":908,"s":6,"a":119,"t":"Qu'avez-vous à ne pas manger de ce sur quoi le nom d'Allah a été prononcé? Alors qu'Il vous a détaillé ce qu'Il vous a interdit, à moins que vous ne soyez contraints d'y recourir. Beaucoup de gens égarent, sans savoir, par leurs passions. C'est ton Seigneur qui connaît le mieux les transgresseurs."},{"n":909,"s":6,"a":120,"t":"Evitez le péché apparent ou caché, (car) ceux qui acquièrent le péché seront rétribués selon ce qu'ils auront commis."},{"n":910,"s":6,"a":121,"t":"Et ne mangez pas de ce sur quoi le nom d'Allah n'a pas été prononcé, car ce serait (assurément) une perversité. Les diables inspirent à leurs alliés de disputer avec vous. Si vous leur obéissez, vous deviendrez certes des associateurs."},{"n":911,"s":6,"a":122,"t":"Est-ce que celui qui était mort et que Nous avons ramené à la vie et à qui Nous avons assigné une lumière grâce à laquelle il marche parmi les gens, est pareil à celui qui est dans les ténèbres sans pouvoir en sortir? Ainsi on a enjolivé aux mécréants ce qu'ils œuvrent."},{"n":912,"s":6,"a":123,"t":"Ainsi, Nous avons placé dans chaque cité de grands criminels qui y ourdissent des complots. Mais ils ne complotent que contre eux-mêmes et ils n'en sont pas conscients."},{"n":913,"s":6,"a":124,"t":"Et lorsqu'une preuve leur vient, ils disent: «Jamais nous ne croirons tant que nous n'aurons pas reçu un don semblable à celui qui a été donné aux messagers d'Allah». Allah sait mieux où placer Son message. Ceux qui ont commis le crime seront atteints d'un rapetissement auprès d'Allah ainsi que d'un supplice sévère pour les ruses qu'ils tramaient."},{"n":914,"s":6,"a":125,"t":"Et puis, quiconque Allah veut guider, Il lui ouvre la poitrine à l'Islam. Et quiconque Il veut égarer, Il rend sa poitrine étroite et gênée, comme s'il s'efforçait de monter au ciel. Ainsi Allah inflige Sa punition à ceux qui ne croient pas."},{"n":915,"s":6,"a":126,"t":"Telle est la voie de ton Seigneur dans toute sa rectitude. Nous avons [effectivement] bien détaillé les signes (ou versets) à des gens qui se rappellent."},{"n":916,"s":6,"a":127,"t":"Pour eux la maison du Salut auprès de leur Seigneur. Et c'est Lui qui est leur protecteur, pour ce qu'ils faisaient (sur terre)."},{"n":917,"s":6,"a":128,"t":"Et le jour où Il les rassemblera tous: «O communauté des djinns, vous avez trop abusé des humains». Et leurs alliés parmi les humains diront: «O notre Seigneur, nous avons profité les uns des autres, et nous avons atteint le terme que Tu avais fixé pour nous.» Il leur dira: «l'Enfer est votre demeure, pour y rester éternellement, sauf si Allah en décide autrement.» Vraiment ton Seigneur est Sage et Omniscient."},{"n":918,"s":6,"a":129,"t":"Et ainsi accordons-Nous, à certains injustes l'autorité sur d'autres, (injustes) à cause de ce qu'ils ont acquis."},{"n":919,"s":6,"a":130,"t":"O communauté des djinns et des humains, ne vous est-il pas venu des messagers, choisis parmi vous, qui vous ont raconté Mes signes et averti de la rencontre de ce jour? Ils diront: «Nous témoignons contre nous-mêmes.» La vie présente les a trompés; et ils ont témoigné contre eux-mêmes qu'en (vérité) ils étaient mécréants."},{"n":920,"s":6,"a":131,"t":"C'est que ton Seigneur n'anéantit point injustement des cités dont les gens ne sont pas encore avertis."},{"n":921,"s":6,"a":132,"t":"A chacun des rangs (des récompenses) selon ses œuvres. Or ton Seigneur n'est pas inattentif à ce qu'ils font."},{"n":922,"s":6,"a":133,"t":"Ton Seigneur est le Suffisant à Soi-même, le Détenteur de la miséricorde. S'Il voulait, Il vous ferait périr et mettrait à votre place qui Il veut, de même qu'Il vous a créés d'une descendance d'un autre peuple."},{"n":923,"s":6,"a":134,"t":"Ce qui vous a été promis arrivera (certainement.) Et vous n'êtes pas à même de [Nous] réduire à l'impuissance."},{"n":924,"s":6,"a":135,"t":"Dis: «O mon peuple! Continuez à agir selon votre méthode; moi aussi j'agirai selon la mienne. Ensuite, vous saurez qui aura un meilleur (sort) dans l'au-delà.» Certes, les injustes ne réussiront jamais."},{"n":925,"s":6,"a":136,"t":"Et ils assignent à Allah une part de ce qu'Il a Lui-même créé, en fait de récoltes et de bestiaux, et ils disent: «Ceci est à Allah - selon leur prétention! - et ceci à nos divinités.» Mais ce qui est pour leurs divinités ne parvient pas à Allah, tandis que ce qui est pour Allah parvient à leurs divinités. Comme leur jugement est mauvais!"},{"n":926,"s":6,"a":137,"t":"Et c'est ainsi que leurs divinités ont enjolivé à beaucoup d'associateurs le meurtre de leurs enfants, afin de les ruiner et de travestir à leurs yeux leur religion. Or si Allah voulait, ils ne le feraient pas. Laisse-les donc, ainsi que ce qu'ils inventent."},{"n":927,"s":6,"a":138,"t":"Et ils dirent: «Voilà des bestiaux et des champs frappés d'interdiction: n'en mangeront que ceux que nous voudrons.» - selon leur prétention! - Et voilà des bêtes dont le dos est tabou, et des bêtes sur lesquelles ils ne mentionnent pas le nom d'Allah. Des inventions contre Lui! Il les rétribuera pour ce qu'ils inventaient comme mensonges."},{"n":928,"s":6,"a":139,"t":"Et ils dirent: «Ce qui est dans le ventre de ces bêtes est réservé aux mâles d'entre nous, et interdit à nos femmes.» Et si c'est un mort-né, ils y participent tous. Bientôt Il les rétribuera pour leur prescription, car Il est Sage et Omniscient."},{"n":929,"s":6,"a":140,"t":"Ils sont certes perdants, ceux qui ont, par sottise et ignorance tué leurs enfants, et ceux qui ont interdit ce qu'Allah leur a attribué de nourriture, inventant des mensonges contre Allah. Ils se sont égarés et ne sont point guidés."},{"n":930,"s":6,"a":141,"t":"C'est Lui qui a créé les jardins, treillagés et non treillagés; ainsi que les palmiers et la culture aux récoltes diverses; [de même que] l'olive et la grenade, d'espèces semblables et différentes. Mangez de leurs fruits, quand ils en produisent; et acquittez-en les droits le jour de la récolte. Et ne gaspillez point car Il n'aime pas les gaspilleurs."},{"n":931,"s":6,"a":142,"t":"Et (Il a créé) parmi les bestiaux, certains pour le transport, et d'autres pour diverses utilités; mangez de ce qu'Allah vous a attribué, et ne suivez pas les pas du Diable, car il est pour vous un ennemi déclaré."},{"n":932,"s":6,"a":143,"t":"(Il en a créé) huit, en couples: deux pour les ovins, deux pour les caprins... dis: «Est-ce les deux mâles qu'Il a interdits ou les deux femelles, ou ce qui est dans les matrices des deux femelles? Informez-moi de toute connaissance, si vous êtes véridiques»"},{"n":933,"s":6,"a":144,"t":"...deux pour les camélidés, deux pour les bovins... Dis: «Est-ce les deux mâles qu'Il a interdits ou les deux femelles, ou ce qui est dans les matrices des deux femelles? Ou bien étiez-vous témoins quand Allah vous l'enjoignit?» Qui est donc plus injuste que celui qui invente un mensonge contre Allah pour égarer les gens sans se baser sur aucun savoir? Allah ne guide pas les gens injustes."},{"n":934,"s":6,"a":145,"t":"Dis: «Dans ce qui m'a été révélé, je ne trouve d'interdit, à aucun mangeur d'en manger, que la bête (trouvée) morte, ou le sang qu'on a fait couler, ou la chair de porc - car c'est une souillure - ou ce qui, par perversité, a été sacrifié à autre qu'Allah». Quiconque est contraint, sans toutefois abuser ou transgresser, ton Seigneur est certes Pardonneur et Miséricordieux."},{"n":935,"s":6,"a":146,"t":"Aux Juifs, Nous avons interdit toute bête à ongle unique. Des bovins et des ovins, Nous leurs avons interdit les graisses, sauf ce que portent leur dos, leurs entrailles, ou ce qui est mêlé à l'os. Ainsi les avons-Nous punis pour leur rébellion. Et Nous sommes bien véridiques."},{"n":936,"s":6,"a":147,"t":"Puis, s'ils te traitent de menteur, alors dis: «Votre Seigneur est Détenteur d'une immense miséricorde cependant que Sa rigueur ne saura être détournée des gens criminels»."},{"n":937,"s":6,"a":148,"t":"Ceux qui ont associé diront: «Si Allah avait voulu, nous ne Lui aurions pas donné des associés, nos ancêtres non plus et nous n'aurions rien déclaré interdit.» Ainsi leurs prédécesseurs traitaient de menteurs (les messagers) jusqu'à ce qu'ils eurent goûté Notre rigueur. Dis: «Avez-vous quelque science à nous produire? Vous ne suivez que la conjecture et ne faites que mentir»."},{"n":938,"s":6,"a":149,"t":"Dis: «L'argument décisif appartient à Allah. S'Il avait voulu certainement Il vous aurait tous guidés. (sur le droit chemin)"},{"n":939,"s":6,"a":150,"t":"Dis: «Amenez vos témoins qui attesteraient qu'Allah a interdit cela.» Si ensuite ils témoignent, alors toi, ne témoigne pas avec eux et ne suis pas les passions de ceux qui traitent de mensonges Nos signes et qui ne croient pas à l'au-delà, tandis qu'ils donnent des égaux à leur Seigneur."},{"n":940,"s":6,"a":151,"t":"Dis: «Venez, je vais réciter ce que votre Seigneur vous a interdit: ne Lui associez rien; et soyez bienfaisants envers vos père et mère. Ne tuez pas vos enfants pour cause de pauvreté. Nous vous nourrissons tout comme eux. N'approchez pas des turpitudes ouvertement, ou en cachette. Ne tuez qu'en toute justice la vie qu'Allah a fait sacrée. Voilà ce qu'[Allah] vous a recommandé de faire; peut-être comprendrez-vous."},{"n":941,"s":6,"a":152,"t":"Et ne vous approchez des biens de l'orphelin que de la plus belle manière, jusqu'à ce qu'il ait atteint sa majorité. Et donnez la juste mesure et le bon poids, en toute justice. Nous n'imposons à une âme que selon sa capacité. Et quand vous parlez, soyez équitables même s'il s'agit d'un proche parent. Et remplissez votre engagement envers Allah. Voilà ce qu'Il vous enjoint. Peut-être vous rappellerez-vous."},{"n":942,"s":6,"a":153,"t":"«Et voilà Mon chemin dans toute sa rectitude, suivez-le donc; et ne suivez pas les sentiers qui vous écartent de Sa voie.» Voilà ce qu'Il vous enjoint. Ainsi atteindrez-vous la piété."},{"n":943,"s":6,"a":154,"t":"Puis Nous avons donné à Moïse le Livre complet en récompense pour le bien qu'il avait fait, et comme un exposé détaillé de toute chose, un guide et une miséricorde. Peut-être croiraient-ils en leur rencontre avec leur Seigneur (au jour du Jugement dernier)."},{"n":944,"s":6,"a":155,"t":"Et voici un Livre (le Coran) béni que Nous avons fait descendre - suivez-le donc et soyez pieux, afin de recevoir la miséricorde -"},{"n":945,"s":6,"a":156,"t":"afin que vous ne disiez point: «On n'a fait descendre le Livre que sur deux peuples avant nous, et nous avons été inattentifs à les étudier."},{"n":946,"s":6,"a":157,"t":"Ou que vous disiez: «Si c'était à nous qu'on avait fait descendre le Livre, nous aurions certainement été mieux guidés qu'eux.» Voilà certes que vous sont venus, de votre Seigneur, preuve, guidée et miséricorde. Qui est plus injuste que celui qui traite de mensonges les versets d'Allah et qui s'en détourne? Nous punirons ceux qui se détournent de Nos versets, par un mauvais châtiment, pour s'en être détournés."},{"n":947,"s":6,"a":158,"t":"Qu'attendent-ils? Que les Anges leur viennent? Que vienne ton Seigneur? Ou que viennent certains signes de ton Seigneur? Le jour où certains signes de ton Seigneur viendront, la foi en Lui ne profitera à aucune âme qui n'avait pas cru auparavant ou qui n'avait acquis aucun mérite de sa croyance. Dis: «Attendez!» Nous attendons, Nous aussi."},{"n":948,"s":6,"a":159,"t":"Ceux qui émiettent leur religion et se divisent en sectes, de ceux-là tu n'es responsable en rien: leur sort ne dépend que d'Allah. Puis Il les informera de ce qu'ils faisaient."},{"n":949,"s":6,"a":160,"t":"Quiconque viendra avec le bien aura dix fois autant; et quiconque viendra avec le mal ne sera rétribué que par son équivalent. Et on ne leur fera aucune injustice."},{"n":950,"s":6,"a":161,"t":"Dis: «Moi, mon Seigneur m'a guidé vers un chemin droit, une religion droite, la religion d'Abraham, le soumis exclusivement à Allah et qui n'était point parmi les associateurs."},{"n":951,"s":6,"a":162,"t":"Dis: «En vérité, ma Salât, mes actes de dévotion, ma vie et ma mort appartiennent à Allah, Seigneur de l'Univers."},{"n":952,"s":6,"a":163,"t":"A Lui nul associé! Et voilà ce qu'il m'a été ordonné, et je suis le premier à me soumettre.»"},{"n":953,"s":6,"a":164,"t":"Dis: «Chercherais-je un autre Seigneur qu'Allah, alors qu'Il est le Seigneur de toute chose? Chacun n'acquiert [le mal] qu'à son détriment: personne ne portera le fardeau (responsabilité) d'autrui. Puis vers votre Seigneur sera votre retour et Il vous informera de ce en quoi vous divergez."},{"n":954,"s":6,"a":165,"t":"C'est Lui qui a fait de vous les successeurs sur terre et qui vous a élevés, en rangs, les uns au-dessus des autres, afin de vous éprouver en ce qu'Il vous a donné. (Vraiment) ton Seigneur est prompt en punition, Il est aussi Pardonneur et Miséricordieux."},{"n":955,"s":7,"a":1,"t":"Alif, Lâm, Mîm, Sâd."},{"n":956,"s":7,"a":2,"t":"C'est un Livre qui t'a été descendu; qu'il n'y ait, à son sujet, nulle gêne dans ton cœur; afin que par cela tu avertisses, et (qu'il soit) un Rappel aux croyants."},{"n":957,"s":7,"a":3,"t":"Suivez ce qui vous a été descendu venant de votre Seigneur et ne suivez pas d'autres alliés que Lui. Mais vous vous souvenez peu."},{"n":958,"s":7,"a":4,"t":"Que de cités Nous avons détruites! Or, Notre rigueur les atteignit au cours du repos nocturne ou durant leur sieste."},{"n":959,"s":7,"a":5,"t":"Leur invocation, lorsque leur survint notre rigueur, se limita à ces paroles: «Certes nous étions injustes»."},{"n":960,"s":7,"a":6,"t":"Nous interrogerons ceux vers qui furent envoyés des messagers et Nous interrogerons aussi les envoyés."},{"n":961,"s":7,"a":7,"t":"Nous leur raconterons en toute connaissance (ce qu'ils faisaient) car Nous n'étions pas absent!"},{"n":962,"s":7,"a":8,"t":"Et la pesée, ce jour-là, sera équitable. Donc, celui dont les bonnes actions pèseront lourd... voilà ceux qui réussiront!"},{"n":963,"s":7,"a":9,"t":"Et quant à celui dont les bonnes actions pèseront léger... voilà ceux qui auront causé la perte de leurs âmes parce qu'ils étaient injustes envers Nos enseignements."},{"n":964,"s":7,"a":10,"t":"Certes, Nous vous avons donné du pouvoir sur terre et Nous vous y avons assigné subsistance. (Mais) vous êtes très peu reconnaissants!"},{"n":965,"s":7,"a":11,"t":"Nous vous avons créés, puis Nous vous avons donné une forme, ensuite Nous avons dit aux Anges: «Prosternez-vous devant Adam.» Ils se prosternèrent, à l'exception de Iblis qui ne fut point de ceux qui se prosternèrent."},{"n":966,"s":7,"a":12,"t":"[Allah] dit: «Qu'est-ce qui t'empêche de te prosterner quand Je te l'ai commandé?» Il répondit: «Je suis meilleur que lui: Tu m'as créé de feu, alors que Tu l'as créé d'argile»."},{"n":967,"s":7,"a":13,"t":"[Allah] dit: «Descends d'ici, Tu n'as pas à t'enfler d'orgueil ici. Sors, te voilà parmi les méprisés.»"},{"n":968,"s":7,"a":14,"t":"«Accorde-moi un délai, dit (Satan,) jusqu'au jour où ils seront ressuscités.»"},{"n":969,"s":7,"a":15,"t":"[Allah] dit: «Tu es de ceux à qui délai est accordé.»"},{"n":970,"s":7,"a":16,"t":"«Puisque Tu m'as mis en erreur, dit [Satan], je m'assoirai pour eux sur Ton droit chemin,"},{"n":971,"s":7,"a":17,"t":"puis je les assaillerai de devant, de derrière, de leur droite et de leur gauche. Et, pour la plupart, Tu ne les trouveras pas reconnaissants.»"},{"n":972,"s":7,"a":18,"t":"«Sors de là», dit (Allah,) banni et rejeté. Quiconque te suit parmi eux... de vous tous, J'emplirai l'Enfer»."},{"n":973,"s":7,"a":19,"t":"«O Adam, habite le Paradis, toi et ton épouse; et mangez en vous deux, à votre guise; et n'approchez pas l'arbre que voici; sinon, vous seriez du nombre des injustes.»"},{"n":974,"s":7,"a":20,"t":"Puis le Diable, afin de leur rendre visible ce qui leur était caché - leurs nudités - leur chuchota, disant: «Votre Seigneur ne vous a interdit cet arbre que pour vous empêcher de devenir des Anges ou d'être immortels»."},{"n":975,"s":7,"a":21,"t":"Et il leur jura: «Vraiment, je suis pour vous deux un bon conseiller»."},{"n":976,"s":7,"a":22,"t":"Alors il les fit tomber par tromperie. Puis, lorsqu'ils eurent goûté de l'arbre, leurs nudités leur devinrent visibles; et ils commencèrent tous deux à y attacher des feuilles du Paradis. Et leur Seigneur les appela: «Ne vous avais-Je pas interdit cet arbre? Et ne vous avais-Je pas dit que le Diable était pour vous un ennemi déclaré?»"},{"n":977,"s":7,"a":23,"t":"Tous deux dirent: «O notre Seigneur, nous avons fait du tort à nous-mêmes. Et si Tu ne nous pardonnes pas et ne nous fais pas miséricorde, nous serons très certainement du nombre des perdants»."},{"n":978,"s":7,"a":24,"t":"«Descendez, dit [Allah], vous serez ennemis les uns des autres. Et il y aura pour vous sur terre séjour et jouissance, pour un temps.»"},{"n":979,"s":7,"a":25,"t":"«Là, dit (Allah), vous vivrez, là vous mourrez, et de là on vous fera sortir.»"},{"n":980,"s":7,"a":26,"t":"O enfants d'Adam! Nous avons fait descendre sur vous un vêtement pour cacher vos nudités, ainsi que des parures. - Mais le vêtement de la piété voilà qui est meilleur - C'est un des signes (de la puissance) d'Allah. Afin qu'ils se rappellent."},{"n":981,"s":7,"a":27,"t":"O enfants d'Adam! Que le Diable ne vous tente point, comme il a fait sortir du Paradis vos père et mère, leur arrachant leur vêtement pour leur rendre visibles leurs nudités. Il vous voit, lui et ses suppôts, d'où vous ne les voyez pas. Nous avons désigné les diables pour alliés à ceux qui ne croient point,"},{"n":982,"s":7,"a":28,"t":"et quand ceux-ci commettent une turpitude, ils disent: «C'est une coutume léguée par nos ancêtres et prescrite par Allah.» Dis: «[Non,] Allah ne commande point la turpitude. Direz-vous contre Allah ce que vous ne savez pas?»"},{"n":983,"s":7,"a":29,"t":"Dis: «Mon Seigneur a commandé l'équité. Que votre prosternation soit exclusivement pour Lui. Et invoquez-Le, sincères dans votre culte. De même qu'Il vous a créés, vous retournerez à Lui»."},{"n":984,"s":7,"a":30,"t":"Il guide une partie, tandis qu'une autre partie a mérité l'égarement parce qu'ils ont pris, au lieu d'Allah, les diables pour alliés, et ils pensent qu'ils sont bien-guidés!"},{"n":985,"s":7,"a":31,"t":"O enfants d'Adam, dans chaque lieu de Salât portez votre parure (vos habits). Et mangez et buvez; et ne commettez pas d'excès, car Il [Allah] n'aime pas ceux qui commettent des excès."},{"n":986,"s":7,"a":32,"t":"Dis: «Qui a interdit la parure d'Allah, qu'Il a produite pour Ses serviteurs, ainsi que les bonnes nourritures?» Dis: «Elles sont destinées à ceux qui ont la foi, dans cette vie, et exclusivement à eux au Jour de la Résurrection.» Ainsi exposons-Nous clairement les versets pour les gens qui savent."},{"n":987,"s":7,"a":33,"t":"Dis: «Mon Seigneur n'a interdit que les turpitudes (les grands péchés), tant apparentes que secrètes, de même que le péché, l'agression sans droit et d'associer à Allah ce dont Il n'a fait descendre aucune preuve, et de dire sur Allah ce que vous ne savez pas»."},{"n":988,"s":7,"a":34,"t":"Pour chaque communauté il y a un terme. Quand leur terme vient, ils ne peuvent le retarder d'une heure et ils ne peuvent le hâter non plus."},{"n":989,"s":7,"a":35,"t":"O enfants d'Adam! Si des messagers [choisis] parmi vous viennent pour vous exposer Mes signes, alors ceux qui acquièrent la piété et se réforment, n'auront aucune crainte et ne seront point affligés."},{"n":990,"s":7,"a":36,"t":"Et ceux qui traitent de mensonges Nos signes et s'en écartent avec orgueil, sont les gens du Feu et ils y demeureront éternellement."},{"n":991,"s":7,"a":37,"t":"Quel pire injuste, que celui qui invente un mensonge contre Allah, ou qui traite de mensonges Ses signes? Ceux là auront la part qui leur a été prescrite; jusqu'au moment où Nos Envoyés [Nos Anges] viennent à eux pour leur enlever l'âme, en leur disant: «Où sont ceux que vous invoquiez en dehors d'Allah?» - Ils répondront: «Nous ne les trouvons plus». Et ils témoigneront contre eux-mêmes qu'ils étaient mécréants."},{"n":992,"s":7,"a":38,"t":"«Entrez dans le Feu», dira [Allah,] «parmi les djinns et les hommes des communautés qui vous ont précédés.» Chaque fois qu'une communauté entrera, elle maudira celle qui l'aura précédée. Puis, lorsque tous s'y retrouveront, la dernière fournée dira de la première: «O notre Seigneur! Voilà ceux qui nous ont égarés: donne-leur donc double châtiment du feu.» Il dira: «A chacun le double, mais vous ne savez pas»."},{"n":993,"s":7,"a":39,"t":"Et la première fournée dira à la dernière: «Mais vous n'avez sur nous aucun avantage. Goûtez donc au châtiment, pour ce que vous avez acquis»."},{"n":994,"s":7,"a":40,"t":"Pour ceux qui traitent de mensonges Nos enseignements et qui s'en écartent par orgueil, les portes du ciel ne leur seront pas ouvertes, et ils n'entreront au Paradis que quand le chameau pénètre dans le chas de l'aiguille. Ainsi rétribuons-Nous les criminels."},{"n":995,"s":7,"a":41,"t":"L'Enfer leur servira de lit et, comme couverture, ils auront des voiles de ténèbres. Ainsi rétribuons-Nous les injustes."},{"n":996,"s":7,"a":42,"t":"Et ceux qui croient et font de bonnes œuvres - Nous n'imposons aucune charge à personne que selon sa capacité - ceux-là seront les gens du Paradis: ils y demeureront éternellement."},{"n":997,"s":7,"a":43,"t":"Et Nous enlèverons toute la rancune de leurs poitrines, sous eux couleront les ruisseaux, et ils diront: «Louange à Allah qui nous a guidés à ceci. Nous n'aurions pas été guidés, si Allah ne nous avait pas guidés. Les messagers de notre Seigneur sont venus avec la vérité.» Et on leur proclamera: «Voilà le Paradis qui vous a été donné en héritage pour ce que vous faisiez»."},{"n":998,"s":7,"a":44,"t":"Les gens du Paradis crieront aux gens du Feu: «Certes, nous avons trouvé vrai ce que notre Seigneur nous avait promis. Avez-vous aussi trouvé vrai ce que votre Seigneur avait promis?» «Oui», diront-ils. Un héraut annoncera alors au milieu d'eux: Que la malédiction d'Allah soit sur les injustes,"},{"n":999,"s":7,"a":45,"t":"qui obstruaient le sentier d'Allah, qui voulaient le rendre tortueux, et qui ne croyaient pas à l'au-delà.»"},{"n":1000,"s":7,"a":46,"t":"Et entre les deux, il y aura un mur, et, sur al-A'râf seront des gens qui reconnaîtront tout le monde par leurs traits caractéristiques. Et ils crieront aux gens du Paradis: «Paix sur vous!» Ils n'y sont pas entrés bien qu'ils le souhaitent."},{"n":1001,"s":7,"a":47,"t":"Et quand leurs regards seront tournés vers les gens du Feu, ils diront; «O notre Seigneur! Ne nous mets pas avec le peuple injuste»."},{"n":1002,"s":7,"a":48,"t":"Et les gens d'al-A'râf, appelant certains hommes qu'ils reconnaîtront par leurs traits caractéristiques, diront: «Vous n'avez tiré aucun profit de tout ce que vous aviez amassé et de l'orgueil dont vous étiez enflés!"},{"n":1003,"s":7,"a":49,"t":"Est-ce donc ceux-là au sujet desquels vous juriez qu'ils n'obtiendront de la part d'Allah aucune miséricorde...? - Entrez au Paradis! Vous serez à l'abri de toute crainte et vous ne serez point affligés."},{"n":1004,"s":7,"a":50,"t":"Et les gens du Feu crieront aux gens du Paradis: «Déversez sur nous de l'eau, ou de ce qu'Allah vous a attribué.» «Ils répondront: Allah les a interdits aux mécréants»."},{"n":1005,"s":7,"a":51,"t":"Ceux-ci prenaient leur religion comme distraction et jeu, et la vie d'ici-bas les trompait. Aujourd'hui, Nous les oublierons comme ils ont oublié la rencontre de leur jour que voici, et parce qu'ils reniaient Nos enseignements."},{"n":1006,"s":7,"a":52,"t":"Nous leur avons, certes, apporté un Livre que Nous avons détaillé, en toute connaissance, à titre de guide et de miséricorde pour les gens qui croient."},{"n":1007,"s":7,"a":53,"t":"Attendent-ils uniquement la réalisation (de Sa menace et de Ses promesses?). Le jour où sa (véritable) réalisation viendra, ceux qui auparavant l'oubliaient diront: «Les messagers de notre Seigneur sont venus avec la vérité. Y a-t-il pour nous des intercesseurs qui puissent intercéder en notre faveur? Ou pourrons-nous être renvoyés [sur terre], afin que nous œuvrions autrement que ce que nous faisions auparavant?» Ils ont certes créé leur propre perte; et ce qu'ils inventaient les a délaissés."},{"n":1008,"s":7,"a":54,"t":"Votre Seigneur, c'est Allah, qui a créé les cieux et la terre en six jours, puis S'est établi «'istawâ» sur le Trône. Il couvre le jour de la nuit qui poursuit celui-ci sans arrêt. (Il a créé) le soleil, la lune et les étoiles, soumis à Son commandement. La création et le commandement n'appartiennent qu'à Lui. Toute gloire à Allah, Seigneur de l'Univers!"},{"n":1009,"s":7,"a":55,"t":"Invoquez votre Seigneur en toute humilité et recueillement et avec discrétion. Certes, Il n'aime pas les transgresseurs."},{"n":1010,"s":7,"a":56,"t":"Et ne semez pas la corruption sur la terre après qu'elle ait été réformée. Et invoquez-Le avec crainte et espoir, car la miséricorde d'Allah est proche des bienfaisants."},{"n":1011,"s":7,"a":57,"t":"C'est Lui qui envoie les vents comme une annonce de Sa Miséricorde. Puis, lorsqu'ils transportent une nuée lourde, Nous la dirigeons vers un pays mort [de sécheresse], puis Nous en faisons descendre l'eau, ensuite Nous en faisons sortir toutes espèces de fruits. Ainsi ferons-Nous sortir les morts. Peut-être vous rappellerez-vous."},{"n":1012,"s":7,"a":58,"t":"Le bon pays, sa végétation pousse avec la grâce de son Seigneur; quant au mauvais pays, (sa végétation) ne sort qu'insuffisamment et difficilement. Ainsi déployons-Nous les enseignements pour des gens reconnaissants."},{"n":1013,"s":7,"a":59,"t":"Nous avons envoyé Noé vers son peuple. Il dit: «O mon peuple, adorez Allah. Pour vous, pas d'autre divinité que Lui. Je crains pour vous le châtiment d'un jour terrible»."},{"n":1014,"s":7,"a":60,"t":"Les notables de son peuple dirent: «Nous te voyons dans un égarement manifeste»."},{"n":1015,"s":7,"a":61,"t":"Il dit: «O mon peuple, il n'y a pas d'égarement en moi; mais je suis un Messager de la part du Seigneur de l'Univers."},{"n":1016,"s":7,"a":62,"t":"Je vous communique les messages de mon Seigneur, et je vous donne conseil sincère, et je sais d'Allah ce que vous ne savez pas."},{"n":1017,"s":7,"a":63,"t":"Est-ce que vous vous étonnez qu'un rappel vous vienne de votre Seigneur à travers un homme issu de vous, pour qu'il vous avertisse et que vous deveniez pieux et que la miséricorde vous soit accordée?»"},{"n":1018,"s":7,"a":64,"t":"Et ils le traitèrent de menteur. Or, Nous le sauvâmes, lui et ceux qui étaient avec lui dans l'arche, et noyâmes ceux qui traitaient de mensonges Nos miracles. C'étaient des gens aveugles, vraiment."},{"n":1019,"s":7,"a":65,"t":"Et aux 'Aad, leur frère Hûd: «O mon peuple, dit-il, adorez Allah. Pour vous, pas d'autre divinité que Lui. Ne [Le] craignez-vous donc pas?»"},{"n":1020,"s":7,"a":66,"t":"Les notables de son peuple qui ne croyaient pas dirent: «Certes, nous te voyons en pleine sottise, et nous pensons que tu es du nombre des menteurs»."},{"n":1021,"s":7,"a":67,"t":"Il dit: «O mon peuple, il n'y a point de sottise en moi; mais je suis un Messager de la part du Seigneur de l'Univers."},{"n":1022,"s":7,"a":68,"t":"Je vous communique les messages de mon Seigneur, et je suis pour vous un conseiller digne de confiance."},{"n":1023,"s":7,"a":69,"t":"Quoi! Vous vous étonnez qu'un rappel vous vienne de votre Seigneur à travers un homme issu de vous, pour qu'il vous avertisse? Et rappelez-vous quand Il vous a fait succéder au peuple de Noé, et qu'Il accrut votre corps en hauteur (et puissance). Eh bien, rappelez-vous les bienfaits d'Allah afin que vous réussissiez."},{"n":1024,"s":7,"a":70,"t":"Ils dirent: «Es-tu venu à nous pour que nous adorions Allah seul, et que nous délaissions ce que nos ancêtres adoraient? Fais donc venir ce dont tu nous menaces, si tu es du nombre des véridiques»."},{"n":1025,"s":7,"a":71,"t":"Il dit: «Vous voilà, frappés de la part de votre Seigneur d'un supplice et d'une colère. Allez vous vous disputer avec moi au sujet de noms que vous et vos ancêtres avez donnés, sans qu'Allah n'y fasse descendre la moindre preuve? Attendez donc! Moi aussi j'attends avec vous."},{"n":1026,"s":7,"a":72,"t":"Or, Nous l'avons sauvé, (lui) et ceux qui étaient avec lui par miséricorde, de Notre part, et Nous avons exterminé ceux qui traitaient de mensonges Nos enseignements et qui n'étaient pas croyants."},{"n":1027,"s":7,"a":73,"t":"Et aux Thamûd, leur frère Sâlih: «O mon peuple, dit-il, adorez Allah. Pour vous, pas d'autre divinité que Lui. Certes, une preuve vous est venue de votre Seigneur: voici la chamelle d'Allah, un signe pour vous. Laissez-la donc manger sur la terre d'Allah et ne lui faites aucun mal; sinon un châtiment douloureux vous saisira."},{"n":1028,"s":7,"a":74,"t":"Et rappelez-vous quand Il vous fit succéder aux Aad et vous installa sur la terre. Vous avez édifié des palais dans ses plaines, et taillé en maisons les montagnes. Rappelez-vous donc les bienfaits d'Allah et ne répandez pas la corruption sur la terre «comme des fauteurs de trouble»."},{"n":1029,"s":7,"a":75,"t":"Les notables de son peuple qui s'enflaient d'orgueil dirent aux opprimés, à ceux d'entre eux qui avaient la foi: «Savez-vous si Sâlih est envoyé de la part de son Seigneur?» Ils dirent: «Oui, nous sommes croyants à son message»."},{"n":1030,"s":7,"a":76,"t":"Ceux qui s'enflaient d'orgueil dirent: «Nous, nous ne croyons certainement pas en ce que vous avez cru»."},{"n":1031,"s":7,"a":77,"t":"Ils tuèrent la chamelle, désobéirent au commandement de leur Seigneur et dirent: «O Sâlih, fais nous venir ce dont tu nous menaces, si tu es du nombre des Envoyés»."},{"n":1032,"s":7,"a":78,"t":"Le cataclysme les saisit; et les voilà étendus gisant dans leurs demeures."},{"n":1033,"s":7,"a":79,"t":"Alors il se détourna d'eux et dit: «O mon peuple, je vous avais communiqué le message de mon Seigneur et vous avais conseillé sincèrement. Mais vous n'aimez pas les conseillers sincères!»"},{"n":1034,"s":7,"a":80,"t":"Et Lot, quand il dit à son peuple: «Vous livrez vous à cette turpitude que nul, parmi les mondes, n'a commise avant vous?"},{"n":1035,"s":7,"a":81,"t":"Certes, vous assouvissez vos désirs charnels avec les hommes au lieu des femmes! Vous êtes bien un peuple outrancier.»"},{"n":1036,"s":7,"a":82,"t":"Et pour toute réponse, son peuple ne fit que dire: «Expulsez-les de votre cité. Ce sont des gens qui veulent se garder purs!»"},{"n":1037,"s":7,"a":83,"t":"Or, Nous l'avons sauvé, lui et sa famille, sauf sa femme qui fut parmi les exterminés."},{"n":1038,"s":7,"a":84,"t":"Et Nous avons fait pleuvoir sur eux une pluie. Regarde donc ce que fut la fin des criminels!"},{"n":1039,"s":7,"a":85,"t":"Et aux Madyan, leur frère Chu'aïb: «O mon peuple, dit-il, adorez Allah. Pour vous, pas d'autre divinité que Lui. Une preuve vous est venue de votre Seigneur. Donnez donc la pleine mesure et le poids et ne donnez pas aux gens moins que ce qui leur est dû. Et ne commettez pas de la corruption sur la terre après sa réforme. Ce sera mieux pour vous si vous êtes croyants."},{"n":1040,"s":7,"a":86,"t":"Et ne vous placez pas sur tout chemin, menaçant, empêchant du sentier d'Allah celui qui croit en Lui et cherchant à rendre ce sentier tortueux. Rappelez-vous quand vous étiez peu nombreux et qu'Il vous a multipliés en grand nombre. Et regardez ce qui est advenu aux fauteurs de désordre."},{"n":1041,"s":7,"a":87,"t":"Si une partie d'entre vous a cru au message avec lequel j'ai été envoyé, et qu'une partie n'a pas cru, patientez donc jusqu'à ce qu'Allah juge parmi nous car Il est le Meilleur des juges.»"},{"n":1042,"s":7,"a":88,"t":"Les notables de son peuple qui s'enflaient d'orgueil, dirent: «Nous t'expulserons certes de notre cité, ô Chu'aïb, toi et ceux qui ont cru avec toi. Ou que vous reveniez à notre religion.» - Il dit: «Est-ce même quand cela nous répugne?»"},{"n":1043,"s":7,"a":89,"t":"Certes, nous aurions forgé un mensonge contre Allah si nous revenions à votre religion après qu'Allah nous en a sauvés. Il ne nous appartient pas d'y retourner à moins qu'Allah notre Seigneur ne le veuille. Notre Seigneur embrasse toute chose de Sa science. C'est en Allah que nous plaçons notre confiance. O notre Seigneur, tranche par la vérité, entre nous et notre peuple car Tu es le meilleur des juges.»"},{"n":1044,"s":7,"a":90,"t":"Et les notables de son peuple qui ne croyaient pas, dirent: «Si vous suivez Chu'aïb, vous serez assurément perdants»."},{"n":1045,"s":7,"a":91,"t":"Alors le tremblement (de terre) les saisit; et les voilà étendus, gisant dans leurs demeures."},{"n":1046,"s":7,"a":92,"t":"Ceux qui traitaient Chu'aïb de menteur (disparurent) comme s'ils n'y avaient jamais vécu. Ceux qui traitaient Chu'aïb de menteur furent eux les perdants."},{"n":1047,"s":7,"a":93,"t":"Il se détourna d'eux et dit: «O mon peuple, je vous ai bien communiqué les messages de mon Seigneur et donné des conseils. Comment donc m'attristerais-je sur des gens mécréants?»"},{"n":1048,"s":7,"a":94,"t":"Nous n'avons envoyé aucun prophète dans une cité, sans que Nous n'ayons pris ses habitants ensuite par l'adversité et la détresse afin qu'ils implorent (le pardon)."},{"n":1049,"s":7,"a":95,"t":"Puis Nous avons changé leur mauvaise condition en y substituant le bien, au point qu'ayant grandi en nombre et en richesse, ils dirent: «La détresse et l'aisance ont touché nos ancêtres aussi.» Eh bien, Nous les avons saisis soudain, sans qu'ils s'en rendent compte."},{"n":1050,"s":7,"a":96,"t":"Si les habitants des cités avaient cru et avaient été pieux, Nous leur aurions certainement accordé des bénédictions du ciel et de la terre. Mais ils ont démenti et Nous les avons donc saisis, pour ce qu'ils avaient acquis."},{"n":1051,"s":7,"a":97,"t":"Les gens des cités sont-ils sûrs que Notre châtiment rigoureux ne les atteindra pas la nuit, pendant qu'ils sont endormis?"},{"n":1052,"s":7,"a":98,"t":"Les gens des cités sont-ils sûrs que Notre châtiment rigoureux ne les atteindra pas le jour, pendant qu'ils s'amusent?"},{"n":1053,"s":7,"a":99,"t":"Sont-ils à l'abri du stratagème d'Allah? Seuls les gens perdus se sentent à l'abri du stratagème d'Allah."},{"n":1054,"s":7,"a":100,"t":"N'est-il pas prouvé à ceux qui reçoivent la terre en héritage des peuples précédents que, si Nous voulions, Nous les frapperions pour leurs péchés et scellerions leurs cœurs, et ils n'entendraient plus rien?"},{"n":1055,"s":7,"a":101,"t":"Voilà les cités dont Nous te racontons certaines de leurs nouvelles. [A ceux-là,] en vérité, leurs messagers leur avaient apporté les preuves, mais ils n'étaient pas prêts à accepter ce qu'auparavant ils avaient traité de mensonge. C'est ainsi qu'Allah scelle les cœurs des mécréants."},{"n":1056,"s":7,"a":102,"t":"Et Nous n'avons trouvé chez la plupart d'entre eux aucun respect de l'engagement; mais Nous avons trouvé la plupart d'entre eux pervers."},{"n":1057,"s":7,"a":103,"t":"Puis, après [ces messagers,] Nous avons envoyé Moïse avec Nos miracles vers Pharaon et ses notables. Mais ils se montrèrent injustes envers Nos signes. Considère donc quelle fut la fin des corrupteurs."},{"n":1058,"s":7,"a":104,"t":"Et Moïse dit: «O Pharaon, je suis un Messager de la part du Seigneur de l'Univers,"},{"n":1059,"s":7,"a":105,"t":"je ne dois dire sur Allah que la vérité. Je suis venu à vous avec une preuve de la part de votre Seigneur. Laisse donc partir avec moi les Enfants d'Israël.»"},{"n":1060,"s":7,"a":106,"t":"«Si tu es venu avec un miracle, dit (Pharaon,) apporte-le donc, si tu es du nombre des véridiques.»"},{"n":1061,"s":7,"a":107,"t":"Il jeta son bâton et voilà que c'était un serpent évident."},{"n":1062,"s":7,"a":108,"t":"Et il sortit sa main et voilà qu'elle était blanche (éclatante), pour ceux qui regardaient."},{"n":1063,"s":7,"a":109,"t":"Les notables du peuple de Pharaon dirent: «Voilà, certes, un magicien chevronné."},{"n":1064,"s":7,"a":110,"t":"Il veut vous expulser de votre pays.» - «Alors, que commandez-vous?»"},{"n":1065,"s":7,"a":111,"t":"Ils dirent: «Fais-le attendre, lui et son frère, et envoie des rassembleurs dans les villes,"},{"n":1066,"s":7,"a":112,"t":"qui t'amèneront tout magicien averti."},{"n":1067,"s":7,"a":113,"t":"Et les magiciens vinrent à Pharaon en disant: «Y aura-t-il vraiment une récompense pour nous, si nous sommes les vainqueurs?»"},{"n":1068,"s":7,"a":114,"t":"Il dit: «Oui, et vous serez certainement du nombre de mes rapprochés»."},{"n":1069,"s":7,"a":115,"t":"Ils dirent: «O Moïse, ou bien tu jetteras (le premier), ou bien nous serons les premiers à jeter»."},{"n":1070,"s":7,"a":116,"t":"«Jetez» dit-il. Puis lorsqu'ils eurent jeté, ils ensorcelèrent les yeux des gens et les épouvantèrent, et vinrent avec une puissante magie."},{"n":1071,"s":7,"a":117,"t":"Et Nous révélâmes à Moïse: «Jette ton bâton». Et voilà que celui-ci se mit à engloutir ce qu'ils avaient fabriqué."},{"n":1072,"s":7,"a":118,"t":"Ainsi la vérité se manifesta et ce qu'ils firent fût vain."},{"n":1073,"s":7,"a":119,"t":"Ainsi ils furent battus et se trouvèrent humiliés."},{"n":1074,"s":7,"a":120,"t":"Et les magiciens se jetèrent prosternés."},{"n":1075,"s":7,"a":121,"t":"Ils dirent: «Nous croyons au Seigneur de l'Univers,"},{"n":1076,"s":7,"a":122,"t":"au Seigneur de Moïse et d'Aaron.»"},{"n":1077,"s":7,"a":123,"t":"«Y avez-vous cru avant que je ne vous (le) permette? dit Pharaon. C'est bien un stratagème que vous avez manigancé dans la ville, afin d'en faire partir ses habitants. Vous saurez bientôt..."},{"n":1078,"s":7,"a":124,"t":"Je vais vous couper la main et la jambe opposées, et puis, je vous crucifierai tous.»"},{"n":1079,"s":7,"a":125,"t":"Ils dirent: «En vérité, c'est vers notre Seigneur que nous retournerons."},{"n":1080,"s":7,"a":126,"t":"Tu ne te venges de nous que parce que nous avons cru aux preuves de notre Seigneur, lorsqu'elles nous sont venues. O notre Seigneur! Déverse sur nous l'endurance et fais nous mourir entièrement soumis.»"},{"n":1081,"s":7,"a":127,"t":"Et les notables du peuple de Pharaon dirent: «Laisseras-tu Moïse et son peuple commettre du désordre sur la terre, et lui-même te délaisser, toi et tes divinités?» Il dit: «Nous allons massacrer leurs fils et laisser vivre leurs femmes. Nous aurons le dessus sur eux et les dominerons.»"},{"n":1082,"s":7,"a":128,"t":"Moïse dit à son peuple: «Demandez aide auprès d'Allah et soyez patients, car la terre appartient à Allah. Il en fait héritier qui Il veut parmi Ses serviteurs. Et la fin (heureuse) sera aux pieux»."},{"n":1083,"s":7,"a":129,"t":"Ils dirent: «Nous avons été persécutés avant que tu ne viennes à nous, et après ton arrivée.» Il dit: «Il se peut que votre Seigneur détruise votre ennemi et vous donne la lieutenance sur terre, et Il verra ensuite comment vous agirez»."},{"n":1084,"s":7,"a":130,"t":"Nous avons éprouvé les gens de Pharaon par des années de disette et par une diminution des fruits afin qu'ils se rappellent."},{"n":1085,"s":7,"a":131,"t":"Et quand le bien-être leur vint, ils dirent: «Cela nous est dû» et si un mal les atteignait, ils voyaient en Moïse et ceux qui étaient avec lui un mauvais augure. En vérité leur sort dépend uniquement d'Allah? Mais la plupart d'entre eux ne savent pas."},{"n":1086,"s":7,"a":132,"t":"Et ils dirent: «Quel que soit le miracle que tu nous apportes pour nous fasciner, nous ne croirons pas en toi»."},{"n":1087,"s":7,"a":133,"t":"Et Nous avons alors envoyé sur eux l'inondation, les sauterelles, les poux (ou la calandre), les grenouilles et le sang, comme signes explicites. Mais ils s'enflèrent d'orgueil et demeurèrent un peuple criminel."},{"n":1088,"s":7,"a":134,"t":"Et quand le châtiment les frappa, ils dirent: «O Moïse, invoque pour nous ton Seigneur en vertu de l'engagement qu'Il t'a donné. Si tu éloignes de nous le châtiment, nous croirons certes en toi et laisserons partir avec toi les enfants d'Israël»."},{"n":1089,"s":7,"a":135,"t":"Et quand Nous eûmes éloigné d'eux le châtiment jusqu'au terme fixé qu'ils devaient atteindre, voilà qu'ils violèrent l'engagement."},{"n":1090,"s":7,"a":136,"t":"Alors Nous Nous sommes vengés d'eux; Nous les avons noyés dans les flots, parce qu'ils traitaient de mensonges Nos signes et n'y prêtaient aucune attention."},{"n":1091,"s":7,"a":137,"t":"Et les gens qui étaient opprimés, Nous les avons fait hériter les contrées orientales et occidentales de la terre que Nous avons bénies. Et la très belle promesse de ton Seigneur sur les enfants d'Israël s'accomplit pour prix de leur endurance. Et Nous avons détruit ce que faisaient Pharaon et son peuple, ainsi que ce qu'ils construisaient."},{"n":1092,"s":7,"a":138,"t":"Et Nous avons fait traverser la Mer aux Enfants d'Israël. Ils passèrent auprès d'un peuple attaché à ses idoles et dirent: «O Moïse, désigne-nous une divinité semblable à leurs dieux.» Il dit: «Vous êtes certes des gens ignorants."},{"n":1093,"s":7,"a":139,"t":"Le culte, auquel ceux-là s'adonnent, est caduc; et tout ce qu'ils font est nul et sans valeur.»"},{"n":1094,"s":7,"a":140,"t":"Il dit: «Chercherai-je pour vous une autre divinité qu'Allah, alors que c'est Lui qui vous a préférés à toutes les créatures [de leur époque]?»"},{"n":1095,"s":7,"a":141,"t":"(Rappelez-vous) le moment où Nous vous sauvâmes des gens de Pharaon qui vous infligeaient le pire châtiment. Ils massacraient vos fils et laissaient vivre vos femmes. C'était là une terrible épreuve de la part de votre Seigneur."},{"n":1096,"s":7,"a":142,"t":"Et Nous donnâmes à Moïse rendez-vous pendant trente nuits, et Nous les complétâmes par dix, de sorte que le temps fixé par son Seigneur se termina au bout de quarante nuits. Et Moïse dit à Aaron son frère: «Remplace-moi auprès de mon peuple, et agis en bien, et ne suis pas le sentier des corrupteurs»."},{"n":1097,"s":7,"a":143,"t":"Et lorsque Moïse vint à Notre rendez-vous et que son Seigneur lui eut parlé, il dit: «O mon Seigneur, montre Toi à moi pour que je Te voie!» Il dit: «Tu ne Me verras pas; mais regarde le Mont: s'il tient en sa place, alors tu Me verras.» Mais lorsque son Seigneur Se manifesta au Mont, Il le pulvérisa, et Moïse s'effondra foudroyé. Lorsqu'il se fut remis, il dit: «Gloire à Toi! A Toi je me repens; et je suis le premier des croyants»."},{"n":1098,"s":7,"a":144,"t":"Et (Allah) dit: «O Moïse, Je t'ai préféré à tous les hommes, par Mes messages et par Ma parole. Prends donc ce que Je te donne, et sois du nombre des reconnaissants»."},{"n":1099,"s":7,"a":145,"t":"Et Nous écrivîmes pour lui, sur les tablettes, une exhortation concernant toute chose, et un exposé détaillé de toute chose. «Prends-les donc fermement et commande à ton peuple d'en adopter le meilleur. Bientôt Je vous ferai voir la demeure des pervers."},{"n":1100,"s":7,"a":146,"t":"J'écarterai de Mes signes ceux qui, sans raison, s'enflent d'orgueil sur terre. Même s'ils voyaient tous les miracles, ils n'y croiraient pas. Et s'ils voient le bon sentier, ils ne le prennent pas comme sentier. Mais s'ils voient le sentier de l'erreur, ils le prennent comme sentier. C'est qu'en vérité ils traitent de mensonges Nos preuves et ils ne leur accordaient aucune attention."},{"n":1101,"s":7,"a":147,"t":"Et ceux qui traitent de mensonges Nos preuves ainsi que la rencontre de l'au-delà, leurs œuvres sont vaines. Seraient-ils rétribués autrement que selon leurs œuvres?»"},{"n":1102,"s":7,"a":148,"t":"Et le peuple de Moïse adopta après lui un veau, fait de leurs parures: un corps qui semblait mugir. N'ont-ils pas vu qu'il ne leur parlait point et qu'il ne les guidait sur aucun chemin? Ils l'adoptèrent [comme divinité], et ils étaient des injustes."},{"n":1103,"s":7,"a":149,"t":"Et quand ils éprouvèrent des regrets, et qu'ils virent qu'ils étaient bel et bien égarés, ils dirent: «Si notre Seigneur ne nous fait pas miséricorde et ne nous pardonne pas, nous serons très certainement du nombre des perdants»."},{"n":1104,"s":7,"a":150,"t":"Et lorsque Moïse retourna à son peuple, fâché, attristé, il dit: «Vous avez très mal agi pendant mon absence! Avez-vous voulu hâter le commandement de votre Seigneur?» Il jeta les tablettes et prit la tête de son frère, en la tirant à lui: «O fils de ma mère, dit (Aaron), le peuple m'a traité en faible, et peu s'en est fallu qu'ils ne me tuent. Ne fais donc pas que les ennemis se réjouissent à mes dépens, et ne m'assigne pas la compagnie des gens injustes»."},{"n":1105,"s":7,"a":151,"t":"Et (Moïse) dit: «O mon Seigneur, pardonne à moi et à mon frère et fais-nous entrer en Ta miséricorde, car Tu es Le plus Miséricordieux des miséricordieux»."},{"n":1106,"s":7,"a":152,"t":"Ceux qui prenaient le veau (comme divinité), bientôt tombera sur eux de la part de leur Seigneur, une colère, et un avilissement dans la vie présente. Ainsi, Nous rétribuons les inventeurs (d'idoles)."},{"n":1107,"s":7,"a":153,"t":"Ceux qui ont fait de mauvaises actions et qui ensuite se sont repentis et ont cru... ton Seigneur, après cela est sûrement Pardonneur et Miséricordieux."},{"n":1108,"s":7,"a":154,"t":"Et quand la colère de Moïse se fut calmée, il prit les tablettes. Il y avait dans leur texte guide et miséricorde à l'intention de ceux qui craignent leur Seigneur."},{"n":1109,"s":7,"a":155,"t":"Et Moïse choisit de son peuple soixante-dix hommes pour un rendez-vous avec Nous. Puis lorsqu'ils furent saisis par le tremblement (de terre), il dit: «Mon Seigneur, si Tu avais voulu, Tu les aurais détruits avant, et moi avec. Vas-Tu nous détruire pour ce que des sots d'entre nous ont fait? Ce n'est là qu'une épreuve de Toi, par laquelle Tu égares qui Tu veux, et guides qui Tu veux. Tu es notre Maître. Pardonne-nous et fais-nous miséricorde, car Tu es le Meilleur des pardonneurs."},{"n":1110,"s":7,"a":156,"t":"Et prescris pour nous le bien ici-bas ainsi que dans l'au-delà. Nous voilà revenus vers Toi, repentis.» Et (Allah) dit: «Je ferai que Mon châtiment atteigne qui Je veux. Et Ma miséricorde embrasse toute chose. Je la prescrirai à ceux qui (Me) craignent, acquittent la Zakât, et ont foi en Nos signes,"},{"n":1111,"s":7,"a":157,"t":"Ceux qui suivent le Messager, le Prophète illettré qu'ils trouvent écrit (mentionné) chez eux dans la Thora et l'Evangile. Il leur ordonne le convenable, leur défend le blâmable, leur rend licites les bonnes choses, leur interdit les mauvaises, et leur ôte le fardeau et les jougs qui étaient sur eux. Ceux qui croiront en lui, le soutiendront, lui porteront secours et suivront la lumière descendue avec lui; ceux-là seront les gagnants."},{"n":1112,"s":7,"a":158,"t":"Dis: «O hommes! Je suis pour vous tous le Messager d'Allah, à Qui appartient la royauté des cieux et de la terre. Pas de divinité à part Lui. Il donne la vie et Il donne la mort. Croyez donc en Allah, en Son messager, le Prophète illettré qui croit en Allah et en Ses paroles. Et suivez-le afin que vous soyez bien guidés»."},{"n":1113,"s":7,"a":159,"t":"Parmi le peuple de Moïse, il est une communauté qui guide (les autres) avec la vérité, et qui, par là, exerce la justice."},{"n":1114,"s":7,"a":160,"t":"Nous les répartîmes en douze tribus, (en douze) communautés. Et Nous révélâmes à Moïse, lorsque son peuple lui demanda de l'eau: «Frappe le rocher avec ton bâton.» Et voilà qu'en jaillirent douze sources. Chaque tribu sut son abreuvoir. Nous les couvrîmes de l'ombre du nuage, et fîmes descendre sur eux la manne et les cailles: «Mangez des bonnes choses que Nous vous avons attribuées.» Et ce n'est pas à Nous qu'ils ont fait du tort, mais c'est à eux-mêmes qu'ils en faisaient."},{"n":1115,"s":7,"a":161,"t":"Et lorsqu'il leur fut dit: «Habitez cette cité et mangez [de ses produits] à votre guise, mais dites: rémission [à nos péchés] et entrez par la porte en vous prosternant. Nous vous pardonnerons vos fautes; et aux bienfaisants (d'entre vous,) Nous accorderons davantage»."},{"n":1116,"s":7,"a":162,"t":"Puis, les injustes parmi eux changèrent en une autre, la parole qui leur était dite. Alors, Nous envoyâmes du ciel un châtiment sur eux, pour le méfait qu'ils avaient commis."},{"n":1117,"s":7,"a":163,"t":"Et interroge-les au sujet de la cité qui donnait sur la mer, lorsqu'on y transgressait le Sabbat! Que leurs poissons venaient à eux faisant surface, au jour de leur Sabbat, et ne venaient pas à eux le jour où ce n'était pas Sabbat! Ainsi les éprouvions-Nous pour la perversité qu'ils commettaient."},{"n":1118,"s":7,"a":164,"t":"Et quand parmi eux une communauté dit: «Pourquoi exhortez-vous un peuple qu'Allah va anéantir ou châtier d'un châtiment sévère?» Ils répondirent: «Pour dégager notre responsabilité vis-à-vis de votre Seigneur; et que peut-être ils deviendront pieux!»"},{"n":1119,"s":7,"a":165,"t":"Puis, lorsqu'ils oublièrent ce qu'on leur avait rappelé, Nous sauvâmes ceux qui (leur) avaient interdit le mal et saisîmes par un châtiment rigoureux les injustes pour leurs actes pervers."},{"n":1120,"s":7,"a":166,"t":"Puis, lorsqu'ils refusèrent (par orgueil) d'abandonner ce qui leur avait été interdit, Nous leur dîmes: «Soyez des singes abjects»."},{"n":1121,"s":7,"a":167,"t":"Et lorsque ton Seigneur annonça qu'Il enverra certes contre eux quelqu'un qui leur imposera le pire châtiment jusqu'au Jour de la Résurrection. En vérité ton Seigneur est prompt à punir mais Il est aussi Pardonneur et Miséricordieux."},{"n":1122,"s":7,"a":168,"t":"Et Nous les avons répartis en communautés sur la terre. Il y a parmi eux des gens de bien, mais il y en a qui le sont moins. Nous les avons éprouvés par des biens et par des maux, peut-être reviendraient-ils (au droit chemin)."},{"n":1123,"s":7,"a":169,"t":"Puis les suivirent des successeurs qui héritèrent le Livre, mais qui préférèrent ce qu'offre la vie d'ici-bas en disant: «Nous aurons le pardon.» Et si des choses semblables s'offrent à eux, ils les acceptent. N'avait-on pas pris d'eux l'engagement du Livre, qu'ils ne diraient sur Allah que la vérité? Ils avaient pourtant étudié ce qui s'y trouve. Et l'ultime demeure est meilleure pour ceux qui pratiquent la piété, - Ne comprendrez-vous donc pas? -"},{"n":1124,"s":7,"a":170,"t":"Et ceux qui se conforment au Livre et accomplissent laSalât, [en vérité], Nous ne laissons pas perdre la récompense de ceux qui s'amendent."},{"n":1125,"s":7,"a":171,"t":"Et lorsque Nous avons brandi au-dessus d'eux le Mont, comme si c'eût été une ombrelle. Ils pensaient qu'il allait tomber sur eux. «Tenez fermement à ce que Nous vous donnons et rappelez-vous son contenu. Peut-être craindrez vous Allah»."},{"n":1126,"s":7,"a":172,"t":"Et quand ton Seigneur tira une descendance des reins des fils d'Adam et les fit témoigner sur eux-mêmes: «Ne suis-Je pas votre Seigneur?» Ils répondirent: «Mais si, nous en témoignons...» - afin que vous ne disiez point, au Jour de la Résurrection: «Vraiment, nous n'y avons pas fait attention»,"},{"n":1127,"s":7,"a":173,"t":"ou que vous auriez dit (tout simplement): «Nos ancêtres autrefois donnaient des associés à Allah, et nous sommes leurs descendants, après eux. Vas-Tu nous détruire pour ce qu'ont fait les imposteurs?»"},{"n":1128,"s":7,"a":174,"t":"Et c'est ainsi que Nous expliquons intelligemment les signes. Peut-être reviendront-ils!"},{"n":1129,"s":7,"a":175,"t":"Et raconte-leur l'histoire de celui à qui Nous avions donné Nos signes et qui s'en écarta. Le Diable, donc, l'entraîna dans sa suite et il devint ainsi du nombre des égarés."},{"n":1130,"s":7,"a":176,"t":"Et si Nous avions voulu, Nous l'aurions élevé par ces mêmes enseignements, mais il s'inclina vers la terre et suivit sa propre passion. Il est semblable à un chien qui halète si tu l'attaques, et qui halète aussi si tu le laisses. Tel est l'exemple des gens qui traitent de mensonges Nos signes. Eh bien, raconte le récit. Peut-être réfléchiront-ils!"},{"n":1131,"s":7,"a":177,"t":"Quel mauvais exemple que ces gens qui traitent de mensonges Nos signes, cependant que c'est à eux-mêmes qu'ils font du tort."},{"n":1132,"s":7,"a":178,"t":"Quiconque Allah guide, voilà le bien guidé. Et quiconque Il égare, voilà les perdants."},{"n":1133,"s":7,"a":179,"t":"Nous avons destiné beaucoup de djinns et d'hommes pour l'Enfer. Ils ont des cœurs, mais ne comprennent pas. Ils ont des yeux, mais ne voient pas. Ils ont des oreilles, mais n'entendent pas. Ceux-là sont comme les bestiaux, même plus égarés encore. Tels sont les insouciants."},{"n":1134,"s":7,"a":180,"t":"C'est à Allah qu'appartiennent les noms les plus beaux. Invoquez-Le par ces noms et laissez ceux qui profanent Ses noms: ils seront rétribués pour ce qu'ils ont fait."},{"n":1135,"s":7,"a":181,"t":"Parmi ceux que Nous avons créés, il y a une communauté qui guide (les autres) selon la vérité et par celle-ci exerce la justice."},{"n":1136,"s":7,"a":182,"t":"Ceux qui traitent de mensonges Nos enseignements, Nous allons les conduire graduellement vers leur perte par des voies qu'ils ignorent."},{"n":1137,"s":7,"a":183,"t":"Et Je leur accorderai un délai, car Mon stratagème est solide!"},{"n":1138,"s":7,"a":184,"t":"Est-ce qu'ils n'ont pas réfléchi? Il n'y a point de folie en leur compagnon (Muhammad): il n'est qu'un avertisseur explicite!"},{"n":1139,"s":7,"a":185,"t":"N'ont-ils pas médité sur le royaume des cieux et de la terre, et toute chose qu'Allah a créée, et que leur terme est peut-être déjà proche? En quelle parole croiront-ils après cela?"},{"n":1140,"s":7,"a":186,"t":"Quiconque Allah égare, pas de guide pour lui. Et Il les laisse dans leur transgression confus et hésitants."},{"n":1141,"s":7,"a":187,"t":"Ils t'interrogent sur l'Heure: «Quand arrivera-t-elle?» Dis: «Seul mon Seigneur en a connaissance. Lui seul la manifestera en son temps. Lourde elle sera dans les cieux et (sur) la terre et elle ne viendra à vous que soudainement.» Ils t'interrogent comme si tu en étais averti. Dis: «Seul Allah en a connaissance.» Mais beaucoup de gens ne savent pas."},{"n":1142,"s":7,"a":188,"t":"Dis: «Je ne détiens pour moi-même ni profit ni dommage, sauf ce qu'Allah veut. Et si je connaissais l'Inconnaissable, j'aurais eu des biens en abondance et aucun mal ne m'aurait touché. Je ne suis, pour les gens qui croient, qu'un avertisseur et un annonciateur»."},{"n":1143,"s":7,"a":189,"t":"C'est Lui qui vous a créés d'un seul être dont il a tiré son épouse, pour qu'il trouve de la tranquillité auprès d'elle; et lorsque celui-ci eut cohabité avec elle, elle conçut une légère grossesse, avec quoi elle se déplaçait (facilement). Puis lorsqu'elle se trouva alourdie, tous deux invoquèrent leur Seigneur: «Si Tu nous donnes un (enfant) sain, nous serons certainement du nombre des reconnaissants»."},{"n":1144,"s":7,"a":190,"t":"Puis, lorsqu'Il leur eût donné un (enfant) sain, tous deux assignèrent à Allah des associés en ce qu'Il leur avait donné. Mais Allah est bien au-dessus des associés qu'on Lui assigne."},{"n":1145,"s":7,"a":191,"t":"Est-ce qu'ils assignent comme associés ce qui ne crée rien et qui eux-mêmes sont créés,"},{"n":1146,"s":7,"a":192,"t":"et qui ne peuvent ni les secourir ni se secourir eux-mêmes?"},{"n":1147,"s":7,"a":193,"t":"Si vous les appelez vers le chemin droit, ils ne vous suivront pas. Le résultat pour vous est le même, que vous les appeliez ou que vous gardiez le silence."},{"n":1148,"s":7,"a":194,"t":"Ceux que vous invoquez en dehors d'Allah sont des serviteurs comme vous. Invoquez-les donc et qu'ils vous répondent, si vous êtes véridiques."},{"n":1149,"s":7,"a":195,"t":"Ont-ils des jambes pour marcher? Ont-ils de mains pour frapper? Ont-ils des yeux pour observer? Ont-ils des oreilles pour entendre? Dis: «Invoquez vos associés, et puis, rusez contre moi; et ne me donnez pas de répit."},{"n":1150,"s":7,"a":196,"t":"Certes mon Maître, c'est Allah qui a fait descendre le Livre (le Coran). C'est Lui qui se charge (de la protection) des vertueux."},{"n":1151,"s":7,"a":197,"t":"Et ceux que vous invoquez en dehors de Lui ne sont capables ni de vous secourir, ni de se secourir eux-mêmes.»"},{"n":1152,"s":7,"a":198,"t":"Et si tu les appelles vers le chemin droit, ils n'entendent pas. Tu les vois qui te regardent, (mais) ils ne voient pas."},{"n":1153,"s":7,"a":199,"t":"Accepte ce qu'on t'offre de raisonnable, commande ce qui est convenable et éloigne-toi des ignorants."},{"n":1154,"s":7,"a":200,"t":"Et si jamais le Diable t'incite à faire le mal, cherche refuge auprès d'Allah. Car Il entend, et sait tout."},{"n":1155,"s":7,"a":201,"t":"Ceux qui pratiquent la piété, lorsqu'une suggestion du Diable les touche se rappellent [du châtiment d'Allah]: et les voilà devenus clairvoyants."},{"n":1156,"s":7,"a":202,"t":"(Quant aux méchants), leurs partenaires diaboliques les enfoncent dans l'aberration, puis ils ne cessent (de s'enfoncer)."},{"n":1157,"s":7,"a":203,"t":"Quand tu ne leur apportes pas de miracle, ils disent: «Pourquoi ne l'inventes-tu pas?» Dis: «Je ne fais que suivre ce qui m'est révélé de mon Seigneur. Ces [versets coraniques] sont des preuves illuminantes venant de votre Seigneur, un guide et une grâce pour des gens qui croient."},{"n":1158,"s":7,"a":204,"t":"Et quand on récite le Coran, prêtez-lui l'oreille attentivement et observez le silence, afin que vous obteniez la miséricorde (d'Allah)."},{"n":1159,"s":7,"a":205,"t":"Et invoque ton Seigneur en toi-même, en humilité et crainte, à mi-voix, le matin et le soir, et ne sois pas du nombre des insouciants."},{"n":1160,"s":7,"a":206,"t":"Ceux qui sont auprès de ton Seigneur [les anges] ne dédaignent pas de L'adorer. Ils Le glorifient et se prosternent devant Lui."},{"n":1161,"s":8,"a":1,"t":"Ils t'interrogent au sujet du butin. Dis: «Le butin est à Allah et à Son messager.» Craignez Allah, maintenez la concorde entre vous et obéissez à Allah et à Son messager, si vous êtes croyants."},{"n":1162,"s":8,"a":2,"t":"Les vrais croyants sont ceux dont les cœurs frémissent quand on mentionne Allah. Et quand Ses versets leur sont récités, cela fait augmenter leur foi. Et ils placent leur confiance en leur Seigneur."},{"n":1163,"s":8,"a":3,"t":"Ceux qui accomplissent la Salât et qui dépensent [dans le sentier d'Allah] de ce que Nous leur avons attribué."},{"n":1164,"s":8,"a":4,"t":"Ceux-là sont, en toute vérité les croyants: à eux des degrés (élevés) auprès de leur Seigneur, ainsi qu'un pardon et une dotation généreuse."},{"n":1165,"s":8,"a":5,"t":"De même, c'est au nom de la vérité que ton Seigneur t'a fait sortir de ta demeure, malgré la répulsion d'une partie des croyants."},{"n":1166,"s":8,"a":6,"t":"Ils discutent avec toi au sujet de la vérité après qu'elle fut clairement apparue; comme si on les poussait vers la mort et qu'ils (la) voyaient."},{"n":1167,"s":8,"a":7,"t":"(Rappelez-vous), quand Allah vous promettait qu'une des deux bandes sera à vous. Vous désiriez vous emparer de celle qui était sans armes, alors qu'Allah voulait par Ses paroles faire triompher la vérité et anéantir les mécréants jusqu'au dernier."},{"n":1168,"s":8,"a":8,"t":"afin qu'Il fasse triompher la vérité et anéantir le faux, en dépit de la répulsion qu'en avaient les criminels."},{"n":1169,"s":8,"a":9,"t":"(Et rappelez-vous) le moment où vous imploriez le secours de votre Seigneur et qu'Il vous exauça aussitôt: «Je vais vous aider d'un millier d'Anges déferlant les uns à la suite des autres.»"},{"n":1170,"s":8,"a":10,"t":"Allah ne fit cela que pour (vous) apporter une bonne nouvelle et pour qu'avec cela vos cœurs se tranquillisent. Il n'y a de victoire que de la part d'Allah. Allah est Puissant et Sage."},{"n":1171,"s":8,"a":11,"t":"Et quand Il vous enveloppa de sommeil comme d'une sécurité de Sa part, et du ciel Il fit descendre de l'eau sur vous afin de vous en purifier, d'écarter de vous la souillure du Diable, de renforcer les cœurs et d'en raffermir les pas! [vos pas]."},{"n":1172,"s":8,"a":12,"t":"Et ton Seigneur révéla aux Anges: «Je suis avec vous: affermissez donc les croyants. Je vais jeter l'effroi dans les cœurs des mécréants. Frappez donc au-dessus des cous et frappez-les sur tous les bouts des doigts."},{"n":1173,"s":8,"a":13,"t":"Ce, parce qu'ils ont désobéi à Allah et à Son messager.» Et quiconque désobéit à Allah et à Son messager... Allah est certainement dur en punition!"},{"n":1174,"s":8,"a":14,"t":"Voilà (votre sort); goûtez-le donc! Et aux mécréants le châtiment du Feu (sera réservé)."},{"n":1175,"s":8,"a":15,"t":"O vous qui croyez quand vous rencontrez (l'armée) des mécréants en marche, ne leur tournez point le dos."},{"n":1176,"s":8,"a":16,"t":"Quiconque, ce jour-là, leur tourne le dos, - à moins que ce soit par tactique de combat, ou pour rallier un autre groupe, - celui-là encourt la colère d'Allah et son refuge sera l'Enfer. Et quelle mauvaise destination!"},{"n":1177,"s":8,"a":17,"t":"Ce n'est pas vous qui les avez tués: mais c'est Allah qui les a tués. Et lorsque tu lançais (une poignée de terre), ce n'est pas toi qui lançais: mais c'est Allah qui lançait, et ce pour éprouver les croyants d'une belle épreuve de Sa part! Allah est Audient et Omniscient."},{"n":1178,"s":8,"a":18,"t":"Voilà! Allah réduit à rien la ruse des mécréants."},{"n":1179,"s":8,"a":19,"t":"Si vous avez imploré l'arbitrage d'Allah vous connaissez maintenant la sentence [d'Allah] Et si vous cessez [la mécréance et l'hostilité contre le Prophète..], c'est mieux pour vous. Mais si vous revenez, Nous reviendrons, et votre masse, même nombreuse, ne vous sera d'aucune utilité. Car Allah est vraiment avec les croyants."},{"n":1180,"s":8,"a":20,"t":"O vous qui croyez! Obéissez à Allah et à Son messager et ne vous détournez pas de lui quand vous l'entendez (parler)."},{"n":1181,"s":8,"a":21,"t":"Et ne soyez pas comme ceux qui disent: «Nous avons entendu», alors qu'ils n'entendent pas."},{"n":1182,"s":8,"a":22,"t":"Les pires des bêtes auprès d'Allah, sont, [en vérité], les sourds-muets qui ne raisonnent pas."},{"n":1183,"s":8,"a":23,"t":"Et si Allah avait reconnu en eux quelque bien, Il aurait fait qu'ils entendent. Mais, même s'Il les faisait entendre, ils tourneraient [sûrement] le dos en s'éloignant."},{"n":1184,"s":8,"a":24,"t":"O vous qui croyez! Répondez à Allah et au Messager lorsqu'il vous appelle à ce qui vous donne la (vraie) vie, et sachez qu'Allah s'interpose entre l'homme et son cœur, et que c'est vers Lui que vous serez rassemblés."},{"n":1185,"s":8,"a":25,"t":"Et craignez une calamité qui n'affligera pas exclusivement les injustes d'entre vous. Et sachez qu'Allah est dur en punition."},{"n":1186,"s":8,"a":26,"t":"Et rappelez-vous quand vous étiez peu nombreux, opprimés sur terre, craignant de vous faire enlever par des gens. Il vous donna asile, vous renforça de Son secours et vous attribua de bonnes choses afin que vous soyez reconnaissants."},{"n":1187,"s":8,"a":27,"t":"O vous qui croyez! Ne trahissez pas Allah et le Messager. Ne trahissez pas sciemment la confiance qu'on a placée en vous?"},{"n":1188,"s":8,"a":28,"t":"Et sachez que vos biens et vos enfants ne sont qu'une épreuve et qu'auprès d'Allah il y a une énorme récompense."},{"n":1189,"s":8,"a":29,"t":"O vous qui croyez! Si vous craignez Allah, Il vous accordera la faculté de discerner (entre le bien et le mal), vous effacera vos méfaits et vous pardonnera. Et Allah est le Détenteur de l'énorme grâce."},{"n":1190,"s":8,"a":30,"t":"(Et rappelle-toi) le moment où les mécréants complotaient contre toi pour t'emprisonner ou t'assassiner ou te bannir. Ils complotèrent. mais Allah a fait échouer leur complot, et Allah est le meilleur en stratagèmes."},{"n":1191,"s":8,"a":31,"t":"Et lorsque Nos versets leur sont récités, ils disent: «Nous avons écouté, certes! Si nous voulions, nous dirions pareil à cela, ce ne sont que des légendes d'anciens.»"},{"n":1192,"s":8,"a":32,"t":"Et quand ils dirent: «O Allah, si cela est la vérité de Ta part, alors, fais pleuvoir du ciel des pierres sur nous, ou fais venir sur nous un châtiment douloureux»."},{"n":1193,"s":8,"a":33,"t":"Allah n'est point tel qu'Il les châtie, alors que tu es au milieu d'eux. Et Allah n'est point tel qu'il les châtie alors qu'Ils demandent pardon."},{"n":1194,"s":8,"a":34,"t":"Qu'ont-ils donc pour qu'Allah ne les châtie pas, alors qu'ils repoussent (les croyants) de la Mosquée sacrée, quoiqu'ils n'en soient pas les gardiens, car ses gardiens ne sont que les pieux. Mais la plupart d'entre eux ne le savent pas."},{"n":1195,"s":8,"a":35,"t":"Et leur prière, auprès de la Maison, n'est que sifflement et battements de mains: «Goûtez donc au châtiment, à cause de votre mécréance!»"},{"n":1196,"s":8,"a":36,"t":"Ceux qui ne croient pas dépensent leurs biens pour éloigner (les gens) du sentier d'Allah. Or, après les avoir dépensés, ils seront pour eux un sujet de regret. Puis ils seront vaincus, et tous ceux qui ne croient pas seront rassemblés vers l'Enfer,"},{"n":1197,"s":8,"a":37,"t":"afin qu'Allah distingue le mauvais du bon, et qu'Il place les mauvais les uns sur les autres, pour en faire un amoncellement qu'Il jettera dans l'Enfer. Ceux-là sont les perdants."},{"n":1198,"s":8,"a":38,"t":"Dis à ceux qui ne croient pas que, s'ils cessent, on leur pardonnera ce qui s'est passé. Et s'ils récidivent, (ils seront châtiés); à l'exemple de (leurs) devanciers."},{"n":1199,"s":8,"a":39,"t":"Et combattez-les jusqu'à ce qu'il ne subsiste plus d'association, et que la religion soit entièrement à Allah. Puis, s'ils cessent (ils seront pardonnés car) Allah observe bien ce qu'ils œuvrent."},{"n":1200,"s":8,"a":40,"t":"Et s'ils tournent le dos, sachez alors qu'Allah est votre Maître. Quel excellent Maître et quel excellent Protecteur!"},{"n":1201,"s":8,"a":41,"t":"Et sachez que, de tout butin que vous avez ramassé, le cinquième appartient à Allah, au messager, à ses proches parents, aux orphelins, aux pauvres, et aux voyageurs (en détresse), si vous croyez en Allah et en ce que Nous avons fait descendre sur Notre serviteur, le jour du Discernement: le jour où les deux groupes s'étaient rencontrés, et Allah est Omnipotent."},{"n":1202,"s":8,"a":42,"t":"Vous étiez sur le versant le plus proche, et eux (les ennemis) sur le versant le plus éloigné, tandis que la caravane était plus bas que vous. Si vous vous étiez donné rendez-vous, vous l'auriez manqué (effrayés par le nombre de l'ennemi). Mais il fallait qu'Allah accomplît un ordre qui devait être exécuté, pour que, sur preuve, pérît celui qui (devait) périr, et vécût, sur preuve, celui qui (devait) vivre. Et certes Allah est Audient et Omniscient."},{"n":1203,"s":8,"a":43,"t":"En songe, Allah te les avait montrés peu nombreux! Car s'Il te les avait montrés nombreux, vous auriez certainement fléchi, et vous vous seriez certainement disputés à propos de l'affaire. Mais Allah vous en a préservés. Il connait le contenu des cœurs."},{"n":1204,"s":8,"a":44,"t":"Et aussi, au moment de la rencontre, Il vous les montrait peu nombreux à Vos yeux, de même qu'Il vous faisant paraître à leurs yeux peu nombreux afin qu'Allah parachève un ordre qui devait être exécuté. C'est à Allah que sont ramenées les choses."},{"n":1205,"s":8,"a":45,"t":"O vous qui croyez! Lorsque vous rencontrez une troupe (ennemie), soyez fermes, et invoquez beaucoup Allah afin de réussir."},{"n":1206,"s":8,"a":46,"t":"Et obéissez à Allah et à Son messager; et ne vous disputez pas, sinon vous fléchirez et perdrez votre force. Et soyez endurants, car Allah est avec les endurants."},{"n":1207,"s":8,"a":47,"t":"Et ne soyez pas comme ceux qui sortirent de leurs demeures pour repousser la vérité et avec ostentation publique, obstruant le chemin d'Allah. Et Allah cerne ce qu'ils font."},{"n":1208,"s":8,"a":48,"t":"Et quand le Diable leur eut embelli leurs actions et dit: «Nul parmi les humains ne peut vous dominer aujourd'hui, et je suis votre soutien.» Mais, lorsque les deux groupes furent en vue l'un de l'autre, il tourna les deux talons et dit: «Je vous désavoue. Je vois ce que vous ne voyez pas; je crains Allah, et Allah est dur en punition»."},{"n":1209,"s":8,"a":49,"t":"(Et rappelez-vous), quand les hypocrites et ceux qui ont une maladie au cœur [dont la foi est douteuse] disaient: «Ces gens-là, leur religion les trompe.» Mais quiconque place sa confiance en Allah (sera victorieux)... car Allah est Puissant et Sage."},{"n":1210,"s":8,"a":50,"t":"Si tu voyais, lorsque les Anges arrachaient les âmes aux mécréants! Ils les frappaient sur leurs visages et leurs derrières, (en disant): «Goûtez au châtiment du Feu."},{"n":1211,"s":8,"a":51,"t":"Cela (le châtiment), pour ce que vos mains ont accompli.» Et Allah n'est point injuste envers les esclaves."},{"n":1212,"s":8,"a":52,"t":"Il en fut de même des gens de Pharaon et ceux qui avant eux n'avaient pas cru aux signes (enseignements) d'Allah. Allah les saisit pour leurs péchés. Allah est certes Fort et sévère en punition."},{"n":1213,"s":8,"a":53,"t":"C'est qu'en effet Allah ne modifie pas un bienfait dont Il a gratifié un peuple avant que celui-ci change ce qui est en lui-même. Et Allah est, Audient et Omniscient."},{"n":1214,"s":8,"a":54,"t":"Il en fut de même des gens de Pharaon et ceux qui avant eux avaient traité de mensonges les signes (enseignements) de leur Seigneur. Nous les avons fait périr pour leurs péchés. Et Nous avons noyé les gens de Pharaon. Car ils étaient tous des injustes."},{"n":1215,"s":8,"a":55,"t":"Les pires bêtes, auprès d'Allah, sont ceux qui ont été infidèles (dans le passé) et qui ne croient donc point (actuellement),"},{"n":1216,"s":8,"a":56,"t":"ceux-là mêmes avec lesquels tu as fait un pacte et qui chaque fois le rompent, sans aucune crainte [d'Allah]."},{"n":1217,"s":8,"a":57,"t":"Donc, si tu les maîtrises à la guerre, inflige-leur un châtiment exemplaire de telle sorte que ceux qui sont derrière eux soient effarouchés. Afin qu'ils se souviennent."},{"n":1218,"s":8,"a":58,"t":"Et si jamais tu crains vraiment une trahison de la part d'un peuple, dénonce alors le pacte (que tu as conclu avec), d'une façon franche et loyale car Allah n'aime pas les traîtres."},{"n":1219,"s":8,"a":59,"t":"Que les mécréants ne pensent pas qu'ils Nous ont échappé. Non, ils ne pourront jamais Nous empêcher (de les rattraper à n'importe quel moment)."},{"n":1220,"s":8,"a":60,"t":"Et préparez [pour lutter] contre eux tout ce que vous pouvez comme force et comme cavalerie équipée, afin d'effrayer l'ennemi d'Allah et le vôtre, et d'autres encore que vous ne connaissez pas en dehors de ceux-ci mais qu'Allah connaît. Et tout ce que vous dépensez dans le sentier d'Allah vous sera remboursé pleinement et vous ne serez point lésés."},{"n":1221,"s":8,"a":61,"t":"Et s'ils inclinent à la paix, incline vers celle-ci (toi aussi) et place ta confiance en Allah, car c'est Lui l'Audient, l'Omniscient."},{"n":1222,"s":8,"a":62,"t":"Et s'ils veulent te tromper, alors Allah te suffira. C'est Lui qui t'a soutenu par Son secours, ainsi que par (l'assistance) des croyants."},{"n":1223,"s":8,"a":63,"t":"Il a uni leurs cœurs (par la foi). Aurais-tu dépensé tout ce qui est sur terre, tu n'aurais pu unir leurs cœurs; mais c'est Allah qui les a unis, car Il est Puissant et Sage."},{"n":1224,"s":8,"a":64,"t":"O Prophète, Allah et ceux des croyants qui te suivent te suffisent."},{"n":1225,"s":8,"a":65,"t":"O Prophète, incite les croyants au combat. S'il se trouve parmi vous vingt endurants, ils vaincront deux cents; et s'il s'en trouve cent, ils vaincront mille mécréants, car ce sont vraiment des gens qui ne comprennent pas."},{"n":1226,"s":8,"a":66,"t":"Maintenant, Allah a allégé votre tâche, sachant qu'il y a de la faiblesse en vous. S'il y a cent endurants parmi vous, ils vaincront deux cents; et s'il y en a mille, ils vaincront deux mille, par la grâce d'Allah. Et Allah est avec les endurants."},{"n":1227,"s":8,"a":67,"t":"Un prophète ne devrait pas faire de prisonniers avant d'avoir prévalu [mis les mécréants hors de combat] sur la terre. Vous voulez les biens d'ici-bas, tandis qu'Allah veut l'au-delà. Allah est Puissant et Sage."},{"n":1228,"s":8,"a":68,"t":"N'eût-été une prescription préalable d'Allah, un énorme châtiment vous aurait touché pour ce que vous avez pris. [de la rançon]"},{"n":1229,"s":8,"a":69,"t":"Mangez donc de ce qui vous est échu en butin, tant qu'il est licite et pur. Et craignez Allah, car Allah est Pardonneur et Miséricordieux."},{"n":1230,"s":8,"a":70,"t":"O Prophète, dis aux captifs qui sont entre vos mains: «Si Allah sait qu'il y a quelque bien dans vos cœurs, Il vous donnera mieux que ce qui vous a été pris et vous pardonnera. Allah est Pardonneur et Miséricordieux."},{"n":1231,"s":8,"a":71,"t":"Et s'ils veulent te trahir..., c'est qu'ils ont déjà trahi Allah [par la mécréance]; mais Il a donné prise sur eux [le jour de Badr]. Et Allah est Omniscient et Sage."},{"n":1232,"s":8,"a":72,"t":"Ceux qui ont cru, émigré et lutté de leurs biens et de leurs personnes dans le sentier d'Allah, ainsi que ceux qui leur ont donné refuge et secours, ceux-là sont alliés les uns des autres. Quant à ceux qui ont cru et n'ont pas émigré, vous ne serez pas liés à eux, jusqu'à ce qu'ils émigrent. Et s'ils vous demandent secours au nom de la religion, à vous alors de leur porter secours, mais pas contre un peuple auquel vous êtes liés par un pacte. Et Allah observe bien ce que vous œuvrez."},{"n":1233,"s":8,"a":73,"t":"Et ceux qui n'ont pas cru sont alliés les uns des autres. Si vous n'agissez pas ainsi [en rompant les liens avec les infidèles], il y aura discorde sur terre et grand désordre."},{"n":1234,"s":8,"a":74,"t":"Et ceux qui ont cru, émigré et lutté dans le sentier d'Allah, ainsi que ceux qui leur ont donné refuge et porté secours, ceux-là sont les vrais croyants: à eux, le pardon et une récompense généreuse."},{"n":1235,"s":8,"a":75,"t":"Et ceux qui après cela ont cru et émigré et lutté en votre compagnie, ceux-là sont des vôtres. Cependant ceux qui sont liés par la parenté ont priorité les uns envers les autres, d'après le Livre d'Allah. Certes, Allah est Omniscient."},{"n":1236,"s":9,"a":1,"t":"Désaveu de la part d'Allah et de Son messager à l'égard des associateurs avec qui vous avez conclu un pacte:"},{"n":1237,"s":9,"a":2,"t":"Parcourez la terre durant quatre mois; et sachez que vous ne réduirez pas Allah à l'impuissance et qu'Allah couvre d'ignominie les mécréants.»"},{"n":1238,"s":9,"a":3,"t":"Et proclamation aux gens, de la part d'Allah et de Son messager, au jour du Grand Pèlerinage, qu'Allah et Son messager, désavouent les associateurs. Si vous vous repentez, ce sera mieux pour vous. Mais si vous vous détournez, sachez que vous ne réduirez pas Allah à l'impuissance. Et annonce un châtiment douloureux à ceux qui ne croient pas."},{"n":1239,"s":9,"a":4,"t":"A l'exception des associateurs avec lesquels vous avez conclu un pacte, puis ils ne vous ont manqué en rien, et n'ont soutenu personne [à lutter] contre vous: respectez pleinement le pacte conclu avec eux jusqu'au terme convenu. Allah aime les pieux."},{"n":1240,"s":9,"a":5,"t":"Après que les mois sacrés expirent, tuez les associateurs où que vous les trouviez. Capturez-les, assiégez-les et guettez-les dans toute embuscade. Si ensuite ils se repentent, accomplissent la Salât et acquittent la Zakât, alors laissez-leur la voie libre, car Allah est Pardonneur et Miséricordieux."},{"n":1241,"s":9,"a":6,"t":"Et si l'un des associateurs te demande asile, accorde-le lui, afin qu'il entende la parole d'Allah, puis fais-le parvenir à son lieu de sécurité. Car ce sont des gens qui ne savent pas."},{"n":1242,"s":9,"a":7,"t":"Comment y aurait-il pour les associateurs un pacte admis par Allah et par Son messager? A l'exception de ceux avec lesquels vous avez conclu un pacte près de la Mosquée sacrée. Tant qu'ils sont droits envers vous, soyez droits envers eux. Car Allah aime les pieux."},{"n":1243,"s":9,"a":8,"t":"Comment donc! Quand ils triomphent de vous, ils ne respectent à votre égard, ni parenté ni pacte conclu. Ils vous satisfont de leurs bouches, tandis que leurs cœurs se refusent; et la plupart d'entre eux sont des pervers."},{"n":1244,"s":9,"a":9,"t":"Ils troquent à vil prix les versets d'Allah (le Coran) et obstruent Son chemin. Ce qu'ils font est très mauvais!"},{"n":1245,"s":9,"a":10,"t":"Ils ne respectent, à l'égard d'un croyant, ni parenté ni pacte conclu. Et ceux-là sont les transgresseurs."},{"n":1246,"s":9,"a":11,"t":"Mais s'ils se repentent, accomplissent la Salât et acquittent la Zakat, ils deviendront vos frères en religion. Nous exposons intelligiblement les versets pour des gens qui savent."},{"n":1247,"s":9,"a":12,"t":"Et si, après le pacte, ils violent leurs serments et attaquent votre religion, combattez alors les chefs de la mécréance - car, ils ne tiennent aucun serment - peut-être cesseront-ils?"},{"n":1248,"s":9,"a":13,"t":"Ne combattrez-vous pas des gens qui ont violé leurs serments, qui ont voulu bannir le Messager et alors que ce sont eux qui vous ont attaqués les premiers? Les redoutiez-vous? C'est Allah qui est plus digne de votre crainte si vous êtes croyants!"},{"n":1249,"s":9,"a":14,"t":"Combattez-les. Allah, par vos mains, les châtiera, les couvrira d'ignominie, vous donnera la victoire sur eux et guérira les poitrines d'un peuple croyant."},{"n":1250,"s":9,"a":15,"t":"Et il fera partir la colère de leurs cœurs. Allah accueille le repentir de qui Il veut. Allah est Omniscient et Sage."},{"n":1251,"s":9,"a":16,"t":"Pensez-vous que vous serez délaissés, cependant qu'Allah n'a pas encore distingué ceux d'entre vous qui ont lutté et qui n'ont pas cherché des alliés en dehors d'Allah, de Son messager et des croyants? Et Allah est Parfaitement Connaisseur de ce que vous faites."},{"n":1252,"s":9,"a":17,"t":"Il n'appartient pas aux associateurs de peupler les mosquées d'Allah, vu qu'ils témoignent contre eux-mêmes de leur mécréance. Voilà ceux dont les œuvres sont vaines; et dans le Feu ils demeureront éternellement."},{"n":1253,"s":9,"a":18,"t":"Ne peupleront les mosquées d'Allah que ceux qui croient en Allah et au Jour dernier, accomplissent la Salât, acquittent la Zakât et ne craignent qu'Allah. Il se peut que ceux-là soient du nombre des bien-guidés."},{"n":1254,"s":9,"a":19,"t":"Ferez-vous de la charge de donner à boire aux pèlerins et d'entretenir la Mosquée sacrée (des devoirs) comparables [au mérite] de celui qui croit en Allah et au Jour dernier et lutte dans le sentier d'Allah? Ils ne sont pas égaux auprès d'Allah et Allah ne guide pas les gens injustes."},{"n":1255,"s":9,"a":20,"t":"Ceux qui ont cru, qui ont émigré et qui ont lutté par leurs biens et leurs personnes dans le sentier d'Allah, ont les plus hauts rangs auprès d'Allah... et ce sont eux les victorieux."},{"n":1256,"s":9,"a":21,"t":"Leur Seigneur leur annonce de Sa part, miséricorde et agrément, et des Jardins où il y aura pour eux un délice permanent"},{"n":1257,"s":9,"a":22,"t":"où ils demeureront éternellement. Certes il y a auprès d'Allah une énorme récompense."},{"n":1258,"s":9,"a":23,"t":"O vous qui croyez! Ne prenez pas pour alliés, vos pères et vos frères s'ils préfèrent la mécréance à la foi. Et quiconque parmi vous les prend pour alliés... ceux-là sont les injustes."},{"n":1259,"s":9,"a":24,"t":"Dis: «Si vos pères, vos enfants, vos frères, vos épouses, vos clans, les biens que vous gagnez, le négoce dont vous craignez le déclin et les demeures qui vous sont agréables, vous sont plus chers qu'Allah, Son messager et la lutte dans le sentier d'Allah, alors attendez qu'Allah fasse venir Son ordre. Et Allah ne guide pas les gens pervers»."},{"n":1260,"s":9,"a":25,"t":"Allah vous a déjà secourus en maints endroits. Et [rappelez-vous] le jour de Hunayn, quand vous étiez fiers de votre grand nombre et que cela ne vous a servi à rien. La terre, malgré son étendue vous devint bien étroite; puis vous avez tourné le dos en fuyards."},{"n":1261,"s":9,"a":26,"t":"Puis, Allah fit descendre Sa quiétude [Sa «sakîna»] sur Son messager et sur les croyants. Il fit descendre des troupes (Anges) que vous ne voyiez pas, et châtia ceux qui ont mécru. Telle est la rétribution des mécréants."},{"n":1262,"s":9,"a":27,"t":"Après cela Allah, accueillera le repentir de qui Il veut, car Allah est Pardonneur et Miséricordieux."},{"n":1263,"s":9,"a":28,"t":"O vous qui croyez! Les associateurs ne sont qu'impureté: qu'ils ne s'approchent plus de la Mosquée sacrée, après cette année-ci. Et si vous redoutez une pénurie, Allah vous enrichira, s'Il veut, de par Sa grâce. Car Allah est Omniscient et Sage."},{"n":1264,"s":9,"a":29,"t":"Combattez ceux qui ne croient ni en Allah ni au Jour dernier, qui n'interdisent pas ce qu'Allah et Son messager ont interdit et qui ne professent pas la religion de la vérité, parmi ceux qui ont reçu le Livre, jusqu'à ce qu'ils versent la capitation par leurs propres mains, après s'être humiliés."},{"n":1265,"s":9,"a":30,"t":"Les Juifs disent: «'Uzayr est fils d'Allah» et les Chrétiens disent: «Le Christ est fils d'Allah». Telle est leur parole provenant de leurs bouches. Ils imitent le dire des mécréants avant eux. Qu'Allah les anéantisse! Comment s'écartent-ils (de la vérité)?"},{"n":1266,"s":9,"a":31,"t":"Ils ont pris leurs rabbins et leurs moines, ainsi que le Christ fils de Marie, comme Seigneurs en dehors d'Allah, alors qu'on ne leur a commandé que d'adorer un Dieu unique. Pas de divinité à part Lui! Gloire à Lui! Il est au-dessus de ce qu'ils [Lui] associent."},{"n":1267,"s":9,"a":32,"t":"Ils veulent éteindre avec leurs bouches la lumière d'Allah, alors qu'Allah ne veut que parachever Sa lumière, quelque répulsion qu'en aient les mécréants."},{"n":1268,"s":9,"a":33,"t":"C'est Lui qui a envoyé Son messager avec la bonne direction et la religion de la vérité, afin qu'elle triomphe sur toute autre religion, quelque répulsion qu'en aient les associateurs."},{"n":1269,"s":9,"a":34,"t":"O vous qui croyez! Beaucoup de rabbins et de moines dévorent, les biens des gens illégalement et [leur] obstruent le sentier d'Allah. A ceux qui thésaurisent l'or et l'argent et ne les dépensent pas dans le sentier d'Allah, annonce un châtiment douloureux,"},{"n":1270,"s":9,"a":35,"t":"le jour où (ces trésors) seront portés à l'incandescence dans le feu de l'Enfer et qu'ils en seront cautérisés, front, flancs et dos: voici ce que vous avez thésaurisé pour vous-mêmes. Goûtez de ce que vous thésaurisiez.»"},{"n":1271,"s":9,"a":36,"t":"Le nombre de mois, auprès d'Allah, est de douze [mois], dans la prescription d'Allah, le jour où Il créa les cieux et la terre. Quatre d'entre eux sont sacrés: telle est la religion droite. [Durant ces mois], ne faites pas de tort à vous-mêmes. Combattez les associateurs sans exception, comme ils vous combattent sans exception. Et sachez qu'Allah est avec les pieux."},{"n":1272,"s":9,"a":37,"t":"Le report d'un mois sacré à un autre est un surcroît de mécréance. Par là, les mécréants sont égarés: une année, ils le font profane, et une année, ils le font sacré, afin d'ajuster le nombre de mois qu'Allah a fait sacrés. Ainsi rendent-ils profane ce qu'Allah a fait sacré. Leurs méfaits leurs sont enjolivés. Et Allah ne guide pas les gens mécréants."},{"n":1273,"s":9,"a":38,"t":"O vous qui croyez! Qu'avez-vous? Lorsque l'on vous a dit: «Elancez-vous dans le sentier d'Allah» vous vous êtes appesantis sur la terre. La vie présente vous agrée-t-elle plus que l'au-delà? - Or, la jouissance de la vie présente ne sera que peu de chose, comparée à l'au-delà!"},{"n":1274,"s":9,"a":39,"t":"Si vous ne vous lancez pas au combat, Il vous châtiera d'un châtiment douloureux et vous remplacera par un autre peuple. Vous ne Lui nuirez en rien. Et Allah est Omnipotent."},{"n":1275,"s":9,"a":40,"t":"Si vous ne lui portez pas secours... Allah l'a déjà secouru, lorsque ceux qui avaient mécru l'avaient banni, deuxième de deux. Quand ils étaient dans la grotte et qu'il disait à son compagnon: «Ne t'afflige pas, car Allah est avec nous.» Allah fit alors descendre sur Lui Sa sérénité «Sa sakîna» et le soutint de soldats (Anges) que vous ne voyiez pas, et Il abaissa ainsi la parole des mécréants, tandis que la parole d'Allah eut le dessus. Et Allah est Puissant et Sage."},{"n":1276,"s":9,"a":41,"t":"Légers ou lourds, lancez-vous au combat, et luttez avec vos biens et vos personnes dans le sentier d'Allah. Cela est meilleur pour vous, si vous saviez."},{"n":1277,"s":9,"a":42,"t":"S'il s'était agi d'un profit facile ou d'un court voyage, ils t'auraient suivi; mais la distance leur parut longue. Et ils jureront par Allah: «Si nous avions pu, nous serions sortis en votre compagnie.» Ils se perdent eux-mêmes. Et Allah sait bien qu'ils mentent."},{"n":1278,"s":9,"a":43,"t":"Qu'Allah te pardonne! Pourquoi leur as-tu donné permission avant que tu ne puisses distinguer ceux qui disaient vrai et reconnaître les menteurs?"},{"n":1279,"s":9,"a":44,"t":"Ceux qui croient en Allah et au Jour dernier ne te demandent pas permission quand il s'agit de mener combat avec leurs biens et leurs personnes. Et Allah connaît bien les pieux."},{"n":1280,"s":9,"a":45,"t":"Ne te demandent permission que ceux qui ne croient pas en Allah et au Jour dernier, et dont les cœurs sont emplis de doute. Ils ne font qu'hésiter dans leur incertitude."},{"n":1281,"s":9,"a":46,"t":"Et s'ils avaient voulu partir (au combat), ils lui auraient fait des préparatifs. Mais leur départ répugna à Allah; Il les a rendus paresseux. Et il leur fut dit: «Restez avec ceux qui restent»."},{"n":1282,"s":9,"a":47,"t":"S'ils étaient sortis avec vous, ils n'auraient fait qu'accroître votre trouble et jeter la dissension dans vos rangs, cherchant à créer la discorde entre vous. Et il y en a parmi vous qui les écoutent. Et Allah connaît bien les injustes."},{"n":1283,"s":9,"a":48,"t":"Ils ont, auparavant, cherché à semer la discorde (dans vos rangs) et à embrouiller tes affaires jusqu'à ce que vînt la vérité et triomphât le commandement d'Allah, en dépit de leur hostilité."},{"n":1284,"s":9,"a":49,"t":"Parmi eux il en est qui dit: «Donne-moi la permission (de rester) et ne me mets pas en tentation.» Or, c'est bien dans la tentation qu'ils sont tombés; l'Enfer est tout autour des mécréants."},{"n":1285,"s":9,"a":50,"t":"Qu'un bonheur t'atteigne, ça les afflige. Et que t'atteigne un malheur, ils disent: «Heureusement que nous avions pris d'avance nos précautions.» Et ils se détournent tout en exultant."},{"n":1286,"s":9,"a":51,"t":"Dis: «Rien ne nous atteindra, en dehors de ce qu'Allah a prescrit pour nous. Il est notre Protecteur. C'est en Allah que les croyants doivent mettre leur confiance»."},{"n":1287,"s":9,"a":52,"t":"Dis: «Qu'attendez-vous pour nous, sinon l'une des deux meilleures choses? Tandis que ce que nous attendons pour vous, c'est qu'Allah vous inflige un châtiment de Sa part ou par nos mains. Attendez donc! Nous attendons aussi, avec vous»."},{"n":1288,"s":9,"a":53,"t":"Dis: «Dépensez bon gré, mal gré: jamais cela ne sera accepté de vous, car vous êtes des gens pervers»."},{"n":1289,"s":9,"a":54,"t":"Ce qui empêche leurs dons d'être agréés, c'est le fait qu'ils n'ont pas cru en Allah et Son messager, qu'ils ne se rendent à la Salât que paresseusement, et qu'ils ne dépensent (dans les bonnes œuvres) qu'à contrecœur."},{"n":1290,"s":9,"a":55,"t":"Que leurs biens et leurs enfants ne t'émerveillent point! Allah ne veut par là que les châtier dans la vie présente, et que (les voir) rendre péniblement l'âme en état de mécréance."},{"n":1291,"s":9,"a":56,"t":"Et ils (les hypocrites) jurent par Allah qu'ils sont vraiment des vôtres; alors qu'ils ne le sont pas. Mais ce sont des gens peureux."},{"n":1292,"s":9,"a":57,"t":"S'ils trouvaient un refuge, des cavernes ou un souterrain, ils s'y tourneraient donc et s'y précipiteraient à bride abattue."},{"n":1293,"s":9,"a":58,"t":"Il en est parmi eux qui te critiquent au sujet des Sadaqats: s'il leur en est donné, les voilà contents; mais s'il ne leur en est pas donné, les voilà pleins de rancœur."},{"n":1294,"s":9,"a":59,"t":"S'ils s'étaient contentés de ce qu'Allah leur avait donné ainsi que Son messager et avaient dit: «Allah nous suffit. Bientôt Allah nous accordera Sa faveur de même que Son messager!... C'est vers Allah que va tout notre désir»."},{"n":1295,"s":9,"a":60,"t":"Les ?adaqâts ne sont destinés que pour les pauvres, les indigents, ceux qui y travaillent, ceux dont les cœurs sont à gagner (à l'Islam), l'affranchissement des jougs, ceux qui sont lourdement endettés, dans le sentier d'Allah, et pour le voyageur (en détresse). C'est un décret d'Allah! Et Allah est Omniscient et Sage."},{"n":1296,"s":9,"a":61,"t":"Et il en est parmi eux ceux qui font du tort au Prophète et disent: «Il est tout oreille». - Dis: «Une oreille pour votre bien. Il croit en Allah et fait confiance aux croyants, et il est une miséricorde pour ceux d'entre vous qui croient. Et ceux qui font du tort au Messager d'Allah auront un châtiment douloureux»."},{"n":1297,"s":9,"a":62,"t":"Ils vous jurent par Allah pour vous satisfaire. Alors qu'Allah - ainsi que Son messager - est plus en droit qu'ils Le satisfassent, s'ils sont vraiment croyants."},{"n":1298,"s":9,"a":63,"t":"Ne savent-ils pas qu'en vérité quiconque s'oppose à Allah et à Son messager, aura le feu de l'Enfer pour y demeurer éternellement? Et voilà l'immense opprobre."},{"n":1299,"s":9,"a":64,"t":"Les hypocrites craignent que l'on fasse descendre sur eux une Sourate leur dévoilant ce qu'il y a dans leurs cœurs. Dis: «Moquez-vous! Allah fera surgir ce que vous prenez la précaution (de cacher)»."},{"n":1300,"s":9,"a":65,"t":"Et si tu les interrogeais, ils diraient très certainement: «Vraiment, nous ne faisions que bavarder et jouer.» Dis: «Est-ce d'Allah, de Ses versets (le Coran) et de Son messager que vous vous moquiez?»"},{"n":1301,"s":9,"a":66,"t":"Ne vous excusez pas: vous avez bel et bien rejeté la foi après avoir cru. Si Nous pardonnons à une partie des vôtres, Nous en châtierons une autre pour avoir été des criminels."},{"n":1302,"s":9,"a":67,"t":"Les hypocrites, hommes et femmes, appartiennent les uns aux autres. Ils commandent le blâmable, interdisent le convenable, et replient leurs mains (d'avarice). Ils ont oublié Allah et Il les a alors oubliés. En vérité, les hypocrites sont les pervers."},{"n":1303,"s":9,"a":68,"t":"Aux hypocrites, hommes et femmes, et aux mécréants, Allah a promis le feu de l'Enfer pour qu'ils y demeurent éternellement. C'est suffisant pour eux. Allah les a maudits. Et pour eux, il y aura un châtiment permanent."},{"n":1304,"s":9,"a":69,"t":"[Il en fut] de même de ceux qui vous ont précédés: ils étaient plus forts que vous, plus riches et avaient plus d'enfants. Ils jouirent de leur lot [en ce monde] et vous avez joui de votre lot comme ont joui vos prédécesseurs de leur lot. Et vous avez discuté à tort et à travers comme ce qu'ils avaient discuté. Ceux-là verront leurs œuvres anéanties dans ce monde et dans l'autre et ceux-là sont les perdants."},{"n":1305,"s":9,"a":70,"t":"Est-ce que ne leur est pas parvenue l'histoire de ceux qui les ont précédés: le peuple de Noé, des 'Aad, des Tamûd, d'Abraham, des gens de Madyan, et des Villes renversées? Leurs messagers leur avaient apporté des preuves évidentes. Ce ne fut pas Allah qui leur fit du tort, mais ils se firent du tort à eux-mêmes."},{"n":1306,"s":9,"a":71,"t":"Les croyants et les croyantes sont alliés les uns des autres. Ils commandent le convenable, interdisent le blâmable accomplissent la ?alât, acquittent la Zakât et obéissent à Allah et à Son messager. Voilà ceux auxquels Allah fera miséricorde, car Allah est Puissant et Sage."},{"n":1307,"s":9,"a":72,"t":"Aux croyants et aux croyantes, Allah a promis des Jardins sous lesquels coulent les ruisseaux, pour qu'ils y demeurent éternellement, et des demeures excellentes, aux jardins d'Eden [du séjour permanent]. Et la satisfaction d'Allah est plus grande encore, et c'est là l'énorme succès."},{"n":1308,"s":9,"a":73,"t":"O Prophète, lutte contre les mécréants et les hypocrites, et sois rude avec eux; l'Enfer sera leur refuge, et quelle mauvaise destination!"},{"n":1309,"s":9,"a":74,"t":"Ils jurent par Allah qu'ils n'ont pas dit (ce qu'ils ont proféré), alors qu'en vérité ils ont dit la parole de la mécréance et ils ont rejeté la foi après avoir été musulmans. Ils ont projeté ce qu'ils n'ont pu accomplir. Mais ils n'ont pas de reproche à faire si ce n'est qu'Allah - ainsi que Son messager - les a enrichis par Sa grâce. S'ils se repentaient, ce serait mieux pour eux. Et s'ils tournent le dos, Allah les châtiera d'un douloureux châtiment, ici-bas et dans l'au-delà; et ils n'auront sur terre ni allié ni secoureur."},{"n":1310,"s":9,"a":75,"t":"Et parmi eux il en est qui avaient pris l'engagement envers Allah: «S'Il nous donne de Sa grâce, nous payerons, certes, la Zakât, et serons du nombre des gens de bien»."},{"n":1311,"s":9,"a":76,"t":"Mais, lorsqu'Il leur donna de Sa grâce, ils s'en montrèrent avares et tournèrent le dos en faisant volte-face."},{"n":1312,"s":9,"a":77,"t":"Il a donc suscité l'hypocrisie dans leurs cœurs, et cela jusqu'au jour où ils Le rencontreront, pour avoir violé ce qu'ils avaient promis à Allah et pour avoir menti."},{"n":1313,"s":9,"a":78,"t":"Ne savent-ils pas qu'Allah connaît leur secret et leurs conversations confidentielles et qu'Allah connaît parfaitement les (choses) inconnaissables."},{"n":1314,"s":9,"a":79,"t":"Ceux-là qui dirigent leurs calomnies contre les croyants qui font des aumônes volontaires et contre ceux qui ne trouvent que leurs faibles moyens (à offrir), et ils se moquent alors d'eux. Qu'Allah les raille. Et ils auront un châtiment douloureux."},{"n":1315,"s":9,"a":80,"t":"Que tu demandes pardon pour eux, ou que tu ne le demandes pas - et si tu demandes pardon pour eux soixante dix fois - Allah ne leur pardonnera point. Et ce parce qu'ils n'ont pas cru en Allah et en Son messager et Allah ne guide pas les gens pervers."},{"n":1316,"s":9,"a":81,"t":"Ceux qui ont été laissés à l'arrière se sont réjouis de pouvoir rester chez eux à l'arrière du Messager d'Allah, ils ont répugné à lutter par leurs biens et leurs personnes dans le sentier d'Allah, et ont dit: «Ne partez pas au combat pendant cette chaleur!» Dis: «Le feu de l'Enfer est plus intense en chaleur.» - S'ils comprenaient!"},{"n":1317,"s":9,"a":82,"t":"Qu'ils rient un peu et qu'ils pleurent beaucoup en récompense de ce qu'ils se sont acquis."},{"n":1318,"s":9,"a":83,"t":"Si Allah te ramène vers un groupe de ces (gens-là), et qu'ils te demandent permission de partir au combat, alors dis: «Vous ne sortirez plus jamais en ma compagnie, et vous ne combattrez plus jamais d'ennemis avec moi. Vous avez été plus contents de rester chez vous la première fois; demeurez donc chez vous en compagnie de ceux qui se tiennent à l'arrière»."},{"n":1319,"s":9,"a":84,"t":"Et ne fais jamais la Salât sur l'un d'entre eux qui meurt, et ne te tiens pas debout auprès de sa tombe, parce qu'ils n'ont pas cru en Allah et en Son messager, et ils sont morts tout en étant pervers."},{"n":1320,"s":9,"a":85,"t":"Et que ni leurs biens ni leurs enfants ne t'émerveillent! Allah ne veut par là, que les châtier ici-bas, et qu'ils rendent péniblement l'âme en mécréants."},{"n":1321,"s":9,"a":86,"t":"Et lorsqu'une Sourate est révélée: «Croyez en Allah et luttez en compagnie de Son messager», les gens qui ont tous les moyens (de combattre) parmi eux te demandent de les dispenser (du combat), et disent: «Laisse-nous avec ceux qui restent»."},{"n":1322,"s":9,"a":87,"t":"Il leur plaît, (après le départ des combattants) de demeurer avec celles qui sont restées à l'arrière. Leurs cœurs ont été scellés et ils ne comprennent rien."},{"n":1323,"s":9,"a":88,"t":"Mais le Messager et ceux qui ont cru avec lui ont lutté avec leurs biens et leurs personnes. Ceux-là auront les bonnes choses et ce sont eux qui réussiront."},{"n":1324,"s":9,"a":89,"t":"Allah a préparé pour eux des Jardins sous lesquels coulent les ruisseaux, pour qu'ils y demeurent éternellement. Voilà l'énorme succès!"},{"n":1325,"s":9,"a":90,"t":"Et parmi les Bédouins, certains sont venus demander d'être dispensés (du combat). Et ceux qui ont menti à Allah et à Son messager sont restés chez eux. Un châtiment douloureux affligera les mécréants d'entre eux."},{"n":1326,"s":9,"a":91,"t":"Nul grief sur les faibles, ni sur les malades, ni sur ceux qui ne trouvent pas de quoi dépenser (pour la cause d'Allah), s'ils sont sincères envers Allah et Son messager. Pas de reproche contre les bienfaiteurs. Allah est Pardonneur et Miséricordieux."},{"n":1327,"s":9,"a":92,"t":"(Pas de reproche) non plus à ceux qui vinrent te trouver pour que tu leur fournisses une monture et à qui tu dis: «Je ne trouve pas de monture pour vous.» Ils retournèrent les yeux débordant de larmes, tristes de ne pas trouver de quoi dépenser."},{"n":1328,"s":9,"a":93,"t":"Il n'y a de voie (de reproche à), vraiment, que contre ceux qui demandent d'être dispensés, alors qu'ils sont riches. Il leur plaît de demeurer avec celles qui sont restées à l'arrière. Et Allah a scellé leurs cœurs et ils ne savent pas."},{"n":1329,"s":9,"a":94,"t":"Ils vous présentent des excuses quand vous revenez à eux. Dis: «Ne présentez pas d'excuses: nous ne vous croyons pas. Allah nous a déjà informés de vos nouvelles. Et Allah verra votre œuvre, ainsi que Son messager. Puis vous serez ramenés vers Celui qui connaît bien l'invisible et le visible, et alors, Il vous informera de ce que vous faisiez."},{"n":1330,"s":9,"a":95,"t":"Ils vous feront des serments par Allah, quand vous êtes de retour vers eux, afin que vous passiez (sur leur tort). Détournez-vous d'eux. Ils sont une souillure et leur refuge est l'Enfer, en rétribution de ce qu'ils acquéraient."},{"n":1331,"s":9,"a":96,"t":"Ils vous font des serments pour se faire agréer de vous, même si vous les agréez, Allah n'agrée pas les gens pervers."},{"n":1332,"s":9,"a":97,"t":"Les Bédouins sont plus endurcis dans leur impiété et dans leur hypocrisie, et les plus enclins à méconnaître les préceptes qu'Allah a révélés à Son messager. Et Allah est Omniscient et Sage."},{"n":1333,"s":9,"a":98,"t":"Parmi les Bédouins, certains prennent leur dépense (en aumône ou à la guerre) comme une charge onéreuse, et attendent pour vous un revers de fortune. Que le malheur retombe sur eux! Allah est Audient et Omniscient."},{"n":1334,"s":9,"a":99,"t":"(Tel autre,) parmi les Bédouins, croit en Allah et au Jour dernier et prend ce qu'il dépense comme moyen de se rapprocher d'Allah et afin de bénéficier des invocations du Messager. C'est vraiment pour eux (un moyen) de se rapprocher (d'Allah) et Allah les admettra en Sa miséricorde. Car Allah est Pardonneur et Miséricordieux."},{"n":1335,"s":9,"a":100,"t":"Les tout premiers [croyants] parmi les Emigrés et les Auxiliaires et ceux qui les ont suivis dans un beau comportement, Allah les agrée, et ils L'agréent. Il a préparé pour eux des Jardins sous lesquels coulent les ruisseaux, et ils y demeureront éternellement. Voilà l'énorme succès!"},{"n":1336,"s":9,"a":101,"t":"Et parmi les Bédouins qui vous entourent, il y a des hypocrites, tout comme une partie des habitants de Médine. Ils s'obstinent dans l'hypocrisie. Tu ne les connais pas mais Nous les connaissons. Nous les châtierons deux fois puis ils seront ramenés vers un énorme châtiment."},{"n":1337,"s":9,"a":102,"t":"D'autres ont reconnu leurs péchés, ils ont mêlé de bonnes actions à d'autres mauvaises. Il se peut qu'Allah accueille leur repentir. Car Allah est Pardonneur et Miséricordieux."},{"n":1338,"s":9,"a":103,"t":"Prélève de leurs biens une Sadaqa par laquelle tu les purifies et les bénis, et prie pour eux. Ta prière est une quiétude pour eux. Et Allah est Audient et Omniscient."},{"n":1339,"s":9,"a":104,"t":"Ne savent-ils pas que c'est Allah qui accueille le repentir de Ses serviteurs, et qui reçoit les Sadaqât, et qu'Allah est L'Accueillant au repentir et le Miséricordieux."},{"n":1340,"s":9,"a":105,"t":"Et dis: «Oeuvrez, car Allah va voir votre œuvre, de même que Son messager et les croyants, et vous serez ramenés vers Celui qui connaît bien l'invisible et le visible. Alors Il vous informera de ce que vous faisiez»."},{"n":1341,"s":9,"a":106,"t":"Et d'autres sont laissés dans l'attente de la décision d'Allah, soit qu'Il les punisse, soit qu'Il leur pardonne. Et Allah est Omniscient et Sage."},{"n":1342,"s":9,"a":107,"t":"Ceux qui ont édifié une mosquée pour en faire [un mobile] de rivalité, d'impiété et de division entre les croyants, qui la préparent pour celui qui auparavant avait combattu Allah et son Envoyé et jurent en disant: «Nous ne voulions que le bien!» [Ceux-là], Allah atteste qu'ils mentent."},{"n":1343,"s":9,"a":108,"t":"Ne te tiens jamais dans (cette mosquée). Car une Mosquée fondée dès le premier jour, sur la piété, est plus digne que tu t'y tiennes debout [pour y prier]. On y trouve des gens qui aiment bien se purifier, et Allah aime ceux qui se purifient."},{"n":1344,"s":9,"a":109,"t":"Lequel est plus méritant? Est-ce celui qui a fondé son édifice sur la piété et l'agrément d'Allah, ou bien celui qui a placé les assises de sa construction sur le bord d'une falaise croulante et qui croula avec lui dans le feu de l'Enfer? Et Allah ne guide pas les gens injustes."},{"n":1345,"s":9,"a":110,"t":"La construction qu'ils ont édifiée sera toujours une source de doute dans leurs cœurs, jusqu'à ce que leurs cœurs se déchirent. Et Allah est Omniscient et Sage."},{"n":1346,"s":9,"a":111,"t":"Certes, Allah a acheté des croyants, leurs personnes et leurs biens en échange du Paradis. Ils combattent dans le sentier d'Allah: ils tuent, et ils se font tuer. C'est une promesse authentique qu'Il a prise sur Lui-même dans la Thora, l'Evangile et le Coran. Et qui est plus fidèle qu'Allah à son engagement? Réjouissez-vous donc de l'échange que vous avez fait: Et c'est là le très grand succès."},{"n":1347,"s":9,"a":112,"t":"Ils sont ceux qui se repentent, qui adorent, qui louent, qui parcourent la terre (ou qui jeûnent), qui s'inclinent, qui se prosternent, qui commandent le convenable et interdisent le blâmable et qui observent les lois d'Allah... et fais bonne annonce aux croyants."},{"n":1348,"s":9,"a":113,"t":"Il n'appartient pas au Prophète et aux croyants d'implorer le pardon en faveur des associateurs, fussent-ils des parents alors qu'il leur est apparu clairement que ce sont les gens de l'Enfer."},{"n":1349,"s":9,"a":114,"t":"Abraham ne demanda pardon en faveur de son père qu'à cause d'une promesse qu'il lui avait faite. Mais, dès qu'il lui apparut clairement qu'il était un ennemi d'Allah, il le désavoua. Abraham était certes plein de sollicitude et indulgent."},{"n":1350,"s":9,"a":115,"t":"Allah n'est point tel à égarer un peuple après qu'Il les a guidés, jusqu'à ce qu'Il leur ait montré clairement ce qu'ils doivent éviter. Certes, Allah est Omniscient."},{"n":1351,"s":9,"a":116,"t":"A Allah appartient la royauté des cieux et de la terre. Il donne la vie et Il donne la mort. Et il n'y a pour vous, en dehors d'Allah, ni allié ni protecteur."},{"n":1352,"s":9,"a":117,"t":"Allah a accueilli le repentir du Prophète, celui des Emigrés et des Auxiliaires qui l'ont suivi à un moment difficile, après que les cœurs d'un groupe d'entre eux étaient sur le point de dévier. Puis Il accueillit leur repentir car Il est Compatissant et Miséricordieux à leur égard."},{"n":1353,"s":9,"a":118,"t":"Et [Il accueillit le repentir] des trois qui étaient restés à l'arrière si bien que, toute vaste qu'elle fût, la terre leur paraissait exiguë; ils se sentaient à l'étroit, dans leur propre personne et ils pensaient qu'il n'y avait d'autre refuge d'Allah qu'auprès de Lui. Puis Il agréa leur repentir pour qu'ils reviennent [à Lui], car Allah est l'accueillant au repentir, le Miséricordieux."},{"n":1354,"s":9,"a":119,"t":"O vous qui croyez! Craignez Allah et soyez avec les véridiques."},{"n":1355,"s":9,"a":120,"t":"Il n'appartient pas aux habitants de Médine, ni aux Bédouins qui sont autour d'eux, de traîner loin derrière le Messager d'Allah, ni de préférer leur propre vie à la sienne. Car ils n'éprouveront ni soif, ni fatigue, ni faim dans le sentier d'Allah, ils ne fouleront aucune terre en provoquant la colère des infidèles, et n'obtiendront aucun avantage sur un ennemi, sans qu'il ne leur soit écrit pour cela une bonne action. En vérité Allah ne laisse pas perdre la récompense des bienfaiteurs."},{"n":1356,"s":9,"a":121,"t":"Ils ne supporteront aucune dépense, minime ou importante, ne traverseront aucune vallée, sans que (cela) ne soit inscrit à leur actif, en sorte qu'Allah les récompense pour le meilleur de ce qu'ils faisaient."},{"n":1357,"s":9,"a":122,"t":"Les croyants n'ont pas à quitter tous leurs foyers. Pourquoi de chaque clan quelques hommes ne viendraient-ils pas s'instruire dans la religion, pour pouvoir à leur retour, avertir leur peuple afin qu'ils soient sur leur garde."},{"n":1358,"s":9,"a":123,"t":"O vous qui croyez! Combattez ceux des mécréants qui sont près de vous; et qu'ils trouvent de la dureté en vous. Et sachez qu'Allah est avec les pieux."},{"n":1359,"s":9,"a":124,"t":"Et quand une Sourate est révélée, il en est parmi eux qui dit: «Quel est celui d'entre vous dont elle fait croître la foi?» Quant aux croyants, elle fait certes croître leur foi, et ils s'en réjouissent."},{"n":1360,"s":9,"a":125,"t":"Mais quant à ceux dont les cœurs sont malades, elle ajoute une souillure à leur souillure, et ils meurent dans la mécréance."},{"n":1361,"s":9,"a":126,"t":"Ne voient-ils pas que chaque année on les éprouve une ou deux fois? Malgré cela, ils ne se repentent, ni ne se souviennent."},{"n":1362,"s":9,"a":127,"t":"Et quand une Sourate est révélée, ils se regardent les uns les autres [et se disent]: «Quelqu'un vous voit-il?» Puis ils se détournent. Qu'Allah détourne leurs cœurs, puisque ce sont des gens qui ne comprennent rien."},{"n":1363,"s":9,"a":128,"t":"Certes, un Messager pris parmi vous, est venu à vous, auquel pèsent lourd les difficultés que vous subissez, qui est plein de sollicitude pour vous, qui est compatissant et miséricordieux envers les croyants."},{"n":1364,"s":9,"a":129,"t":"Alors, s'ils se détournent dis: «Allah me suffit. Il n'y a de divinité que Lui. En Lui je place ma confiance; et Il est le Seigneur du Trône immense»."},{"n":1365,"s":10,"a":1,"t":"Alif, Lâm, Râ. Voici les versets du Livre plein de sagesse."},{"n":1366,"s":10,"a":2,"t":"Est-il étonnant pour les gens, que Nous ayons révélé à un homme d'entre eux: «Avertis les gens, et annonce la bonne nouvelle aux croyants qu'ils ont auprès de leur Seigneur une présence méritée [pour leur loyauté antérieure]? Les mécréants dirent alors: «Celui-ci est certainement un magicien évident»."},{"n":1367,"s":10,"a":3,"t":"Votre Seigneur est, Allah qui créa les cieux et la terre en six jours, puis S'est établi «Istawâ» sur le Trône, administrant toute chose. Il n'y a d'intercesseur qu'avec Sa permission. Tel est Allah votre Seigneur. Adorez-Le donc. Ne réfléchissez-vous pas?"},{"n":1368,"s":10,"a":4,"t":"C'est vers Lui que vous retournerez tous, c'est là, la promesse d'Allah en toute vérité! C'est Lui qui fait la création une première fois puis la refait (en la ressuscitant) afin de rétribuer en toute équité ceux qui ont cru et fait de bonnes œuvres. Quant à ceux qui n'ont pas cru, ils auront un breuvage d'eau bouillante et un châtiment douloureux à cause de leur mécréance!"},{"n":1369,"s":10,"a":5,"t":"C'est Lui qui a fait du soleil une clarté et de la lune une lumière, et Il en a déterminé les phases afin que vous sachiez le nombre des années et le calcul (du temps). Allah n'a créé cela qu'en toute vérité. Il expose les signes pour les gens doués de savoir."},{"n":1370,"s":10,"a":6,"t":"Dans l'alternance de la nuit et du jour, et aussi dans tout ce qu'Allah a créé dans les cieux et la terre, il y a des signes, certes, pour des gens qui craignent (Allah)."},{"n":1371,"s":10,"a":7,"t":"Ceux qui n'espèrent pas Notre rencontre, qui sont satisfaits de la vie présente et s'y sentent en sécurité, et ceux qui sont inattentifs à Nos signes [ou versets],"},{"n":1372,"s":10,"a":8,"t":"leur refuge sera le Feu, pour ce qu'ils acquéraient."},{"n":1373,"s":10,"a":9,"t":"Ceux qui croient et font de bonnes œuvres, leur Seigneur les guidera à cause de leur foi. A leurs pieds les ruisseaux couleront dans les Jardins des délices."},{"n":1374,"s":10,"a":10,"t":"Là, leur invocation sera «Gloire à Toi, O Allah», et leur salutation: «Salâm», [Paix!] et la fin de leur invocation: «Louange à Allah, Seigneur de l'Univers»."},{"n":1375,"s":10,"a":11,"t":"Et si Allah hâtait le malheur des gens avec autant de hâte qu'ils cherchent le bonheur, le terme de leur vie aurait été décrété. Mais Nous laissons ceux qui n'espèrent pas Notre rencontre confus et hésitants dans leur transgression."},{"n":1376,"s":10,"a":12,"t":"Et quand le malheur touche l'homme, il fait appel à Nous, couché sur le côté, assis, ou debout. Puis quand Nous le délivrons de son malheur, il s'en va comme s'il ne Nous avait point imploré pour un mal qui l'a touché. C'est ainsi que furent embellies aux outranciers leurs actions."},{"n":1377,"s":10,"a":13,"t":"Nous avons fait périr les générations d'avant vous lorsqu'elles eurent été injustes alors que leurs messagers leur avaient apporté des preuves. Cependant, elles n'étaient pas disposées à croire. C'est ainsi que Nous rétribuons les gens criminels."},{"n":1378,"s":10,"a":14,"t":"Puis nous fîmes de vous des successeurs sur terre après eux, pour voir comment vous agiriez."},{"n":1379,"s":10,"a":15,"t":"Et quand leur sont récités Nos versets en toute clarté, ceux qui n'espèrent pas notre rencontre disent: «Apporte un Coran autre que celui-ci» ou bien «Change-le». Dis: «Il ne m'appartient pas de le changer de mon propre chef. Je ne fais que suivre ce qui m'est révélé. Je crains, si je désobéis à mon Seigneur, le châtiment d'un jour terrible»."},{"n":1380,"s":10,"a":16,"t":"Dis: «Si Allah avait voulu, je ne vous l'aurais pas récité et Il ne vous l'aurait pas non plus fait connaître. Je suis bien resté, avant cela, tout un âge parmi vous. Ne raisonnez-vous donc pas?»"},{"n":1381,"s":10,"a":17,"t":"Qui est plus injuste que celui qui invente un mensonge contre Allah, ou qui traite de mensonges Ses versets (le Coran)? Vraiment, les criminels ne réussissent pas."},{"n":1382,"s":10,"a":18,"t":"Ils adorent au lieu d'Allah ce qui ne peut ni leur nuire ni leur profiter et disent: «Ceux-ci sont nos intercesseurs auprès d'Allah». Dis: «Informerez-vous Allah de ce qu'Il ne connaît pas dans les cieux et sur la terre?» Pureté à Lui, Il est Très élevé au-dessus de ce qu'Ils Lui associent!"},{"n":1383,"s":10,"a":19,"t":"Les gens ne formaient (à l'origine) qu'une seule communauté. Puis ils divergèrent. Et si ce n'était une décision préalable de ton Seigneur, les litiges qui les opposaient auraient été tranchés."},{"n":1384,"s":10,"a":20,"t":"Et ils disent: «Que ne fait-on descendre sur lui (Muhammad) un miracle de son Seigneur?» Alors, dis: «L'inconnaissable relève seulement d'Allah. Attendez donc; je serai avec vous parmi ceux qui attendent."},{"n":1385,"s":10,"a":21,"t":"Et quand Nous faisons goûter aux gens une miséricorde après qu'un malheur les a touchés, voilà qu'ils dénigrent Nos versets. Dis: «Allah est plus prompt à réprimer (ceux qui dénigrent Ses versets)». Car Nos anges enregistrent vos dénigrements."},{"n":1386,"s":10,"a":22,"t":"C'est Lui qui vous fait aller sur terre et sur mer, quand vous êtes en bateau. [Ces bateaux] les emportèrent, grâce à un bon vent. Ils s'en réjouirent jusqu'au moment où, assaillis par un vent impétueux, assaillis de tous côtés par les vagues, se jugeant enveloppés [par la mort], ils prièrent Allah, Lui vouant le culte [et disant]: «Certes, si Tu nous sauves de ceci, nous serons parmi les reconnaissants!»"},{"n":1387,"s":10,"a":23,"t":"Lorsqu'Il les a sauvés, les voilà qui, sur terre, transgressent injustement. O gens! Votre transgression ne retombera que sur vous-mêmes. C'est une jouissance temporaire de la vie présente. Ensuite, c'est vers Nous que sera votre retour, et Nous vous rappellerons alors ce que vous faisiez."},{"n":1388,"s":10,"a":24,"t":"La vie présente est comparable à une eau que Nous faisons descendre du ciel et qui se mélange à la végétation de la terre dont se nourrissent les hommes et les bêtes. Puis, lorsque la terre prend sa parure et s'embellit, et que ses habitants pensent qu'elle est à leur entière disposition, Notre Ordre lui vient, de nuit ou de jour, c'est alors que Nous la rendrons toute moissonnée, comme si elle n'avait pas été florissante la veille. Ainsi exposons-Nous les preuves pour des gens qui réfléchissent."},{"n":1389,"s":10,"a":25,"t":"Allah appelle à la demeure de la paix et guide qui Il veut vers un droit chemin."},{"n":1390,"s":10,"a":26,"t":"A ceux qui agissent en bien est réservée la meilleure (récompense) et même davantage. Nulle fumée noircissante, nul avilissement ne couvriront leurs visages. Ceux-là sont les gens du Paradis, où ils demeureront éternellement."},{"n":1391,"s":10,"a":27,"t":"Et ceux qui ont commis de mauvaises actions, la rétribution d'une mauvaise action sera l'équivalent. Un avilissement les couvrira, - pas de protecteur pour eux contre Allah -, comme si leurs visages se couvraient de lambeaux de ténèbres nocturnes. Ceux-là sont là les gens du Feu où ils demeureront éternellement."},{"n":1392,"s":10,"a":28,"t":"(Et rappelle-toi) le jour où Nous les rassemblerons tous. Puis, Nous dirons à ceux qui ont donné [à Allah] des associés: «A votre place, vous et vos associés.» Nous les séparerons les uns des autres et leurs associés diront: «Ce n'est pas nous que vous adoriez»."},{"n":1393,"s":10,"a":29,"t":"Allah suffit comme témoin entre nous et vous. En vérité, nous étions indifférents à votre adoration»."},{"n":1394,"s":10,"a":30,"t":"Là, chaque âme éprouvera (les conséquences de) ce qu'elle a précédemment accompli. Et ils seront ramenés vers Allah leur vrai Maître; et leurs inventions (idoles) s'éloigneront d'eux."},{"n":1395,"s":10,"a":31,"t":"Dis: «Qui vous attribue de la nourriture du ciel et de la terre? Qui détient l'ouïe et la vue, et qui fait sortir le vivant du mort et fait sortir le mort du vivant, et qui administre tout?» Ils diront: «Allah». Dis alors: «Ne Le craignez-vous donc pas?»"},{"n":1396,"s":10,"a":32,"t":"Tel est Allah, votre vrai Seigneur. Au delà de la vérité qu'y a-t-il donc sinon l'égarement? Comment alors pouvez-vous, vous détourner?»"},{"n":1397,"s":10,"a":33,"t":"C'est ainsi que s'est réalisée la parole de ton Seigneur contre ceux qui sont pervers: «Ils ne croiront pas»."},{"n":1398,"s":10,"a":34,"t":"Dis: «Parmi vos associés, qui donne la vie par une première création et la redonne [après la mort]?» Dis: «Allah [seul] donne la vie par une première création et la redonne. Comment pouvez-vous vous écarter [de l'adoration d'Allah]?"},{"n":1399,"s":10,"a":35,"t":"Dis: «Est-ce qu'il y a parmi vos associés un qui guide vers la vérité?» Dis: «C'est Allah qui guide vers la vérité. Celui qui guide vers la vérité est-il plus digne d'être suivi, ou bien celui qui ne se dirige qu'autant qu'il est lui-même dirigé? Qu'avez-vous donc? Comment jugez-vous ainsi?»"},{"n":1400,"s":10,"a":36,"t":"Et la plupart d'entre eux ne suivent que conjecture. Mais, la conjecture ne sert à rien contre la vérité! Allah sait parfaitement ce qu'ils font."},{"n":1401,"s":10,"a":37,"t":"Ce Coran n'est nullement à être forgé en dehors d'Allah mais c'est la confirmation de ce qui existait déjà avant lui, et l'exposé détaillé du Livre en quoi il n'y a pas de doute, venu du Seigneur de l'Univers."},{"n":1402,"s":10,"a":38,"t":"Ou bien ils disent: «Il (Muhammad) l'a inventé?» Dis: «Composez donc une sourate semblable à ceci, et appelez à votre aide n'importe qui vous pourrez, en dehors d'Allah, si vous êtes véridiques»."},{"n":1403,"s":10,"a":39,"t":"Bien au contraire: ils ont traité de mensonge ce qu'ils ne peuvent embrasser de leur savoir, et dont l'interprétation ne leur est pas encore parvenue. Ainsi ceux qui vivaient avant eux traitaient d'imposteurs (leurs messagers). Regarde comment a été la fin des injustes!"},{"n":1404,"s":10,"a":40,"t":"Certains d'entre eux y croient, et d'autres n'y croient pas. Et ton Seigneur connaît le mieux les fauteurs de désordre."},{"n":1405,"s":10,"a":41,"t":"Et s'ils te traitent de menteur, dis alors: «A moi mon œuvre, et à vous la vôtre. Vous êtes irresponsables de ce que je fais et je suis irresponsable de ce que vous faites»."},{"n":1406,"s":10,"a":42,"t":"Et il en est parmi eux qui te prêtent l'oreille. Est-ce toi qui fait entendre les sourds, même s'ils sont incapables de comprendre."},{"n":1407,"s":10,"a":43,"t":"Et il en est parmi eux qui te regardent. Est-ce toi qui peux guider les aveugles, même s'ils ne voient pas?"},{"n":1408,"s":10,"a":44,"t":"En vérité, Allah n'est point injuste à l'égard des gens, mais ce sont les gens qui font du tort à eux-mêmes."},{"n":1409,"s":10,"a":45,"t":"Et le jour où Il les rassemblera, ce sera comme s'ils n'étaient restés [dans leur tombeau] qu'une heure du jour et ils se reconnaîtront mutuellement. Perdants seront alors ceux qui auront traité de mensonge la rencontre d'Allah, et ils n'auront pas été bien guidés."},{"n":1410,"s":10,"a":46,"t":"Que Nous te fassions voir une partie de ce dont Nous les menaçons, ou que Nous te fassions mourir, (en tout cas), c'est vers Nous que sera leur retour. Allah est en outre, témoin de ce qu'ils font."},{"n":1411,"s":10,"a":47,"t":"A chaque communauté un Messager. Et lorsque leur messager vint, tout se décida en équité entre eux et ils ne furent point lésés."},{"n":1412,"s":10,"a":48,"t":"Et ils disent «A quand cette promesse, si vous êtes véridiques»?"},{"n":1413,"s":10,"a":49,"t":"Dis: «Je ne détiens pour moi rien qui peut me nuire ou me profiter, excepté ce qu'Allah veut. A chaque communauté un terme. Quand leur terme arrive, ils ne peuvent ni le retarder d'une heure ni l'avancer»."},{"n":1414,"s":10,"a":50,"t":"Dis: «Voyez-vous! Si Son châtiment vous arrivait de nuit ou de jour, les criminels pourraient-ils en hâter quelque chose?"},{"n":1415,"s":10,"a":51,"t":"«Est-ce au moment où le châtiment se produira que vous croirez? [Il vous sera dit: «Inutile».] Maintenant! Autrefois, vous en réclamiez [ironiquement] la prompte arrivée!»"},{"n":1416,"s":10,"a":52,"t":"Puis il sera dit aux injustes: «Goûtez au châtiment éternel! Etes-vous rétribués autrement qu'en rapport de ce que vous acquériez?»"},{"n":1417,"s":10,"a":53,"t":"Et ils s'informent auprès de toi: «Est-ce vrai?» - Dis: «Oui! Par mon Seigneur! C'est bien vrai. Et vous ne pouvez vous soustraire à la puissance d'Allah."},{"n":1418,"s":10,"a":54,"t":"Si chaque âme injuste possédait tout ce qu'il y a sur terre, elle le donnerait pour sa rançon. Ils dissimuleront leur regret quand ils verront le châtiment. Et il sera décidé entre eux en toute équité, et ils ne seront point lésés."},{"n":1419,"s":10,"a":55,"t":"C'est à Allah qu'appartient, certes, tout ce qui est dans les cieux et sur la terre. Certes, la promesse d'Allah est vérité. Mais la plupart d'entre eux ne (le) savent pas."},{"n":1420,"s":10,"a":56,"t":"C'est Lui qui donne la vie et qui donne la mort; et c'est vers Lui que vous serez ramenés."},{"n":1421,"s":10,"a":57,"t":"O gens! Une exhortation vous est venue, de votre Seigneur, une guérison de ce qui est dans les poitrines, un guide et une miséricorde pour les croyants."},{"n":1422,"s":10,"a":58,"t":"Dis: «[Ceci provient] de la grâce d'Allah et de Sa miséricorde; Voilà de quoi ils devraient se réjouir. C'est bien mieux que tout ce qu'ils amassent»."},{"n":1423,"s":10,"a":59,"t":"Que dites-vous de ce qu'Allah a fait descendre pour vous comme subsistance et dont vous avez alors fait des choses licites et des choses interdites? - Dis: «Est-ce Allah qui vous l'a permis? Ou bien forgez vous (des mensonges) contre Allah?»"},{"n":1424,"s":10,"a":60,"t":"Et que penseront, au Jour de la Résurrection, ceux qui forgent le mensonge contre Allah? - Certes, Allah est Détenteur de grâce pour les gens, mais la plupart d'entre eux ne sont pas reconnaissants."},{"n":1425,"s":10,"a":61,"t":"Tu ne te trouveras dans aucune situation, tu ne réciteras aucun passage du Coran, vous n'accomplirez aucun acte sans que Nous soyons témoin au moment où vous l'entreprendrez. Il n'échappe à ton Seigneur ni le poids d'un atome sur terre ou dans le ciel, ni un poids plus petit ou plus grand qui ne soit déjà inscrit dans un livre évident."},{"n":1426,"s":10,"a":62,"t":"En vérité, les bien-aimés d'Allah seront à l'abri de toute crainte, et ils ne seront point affligés,"},{"n":1427,"s":10,"a":63,"t":"ceux qui croient et qui craignent [Allah]."},{"n":1428,"s":10,"a":64,"t":"Il y a pour eux une bonne annonce dans la vie d'ici-bas tout comme dans la vie ultime. - Il n'y aura pas de changement aux paroles d'Allah -. Voilà l'énorme succès!"},{"n":1429,"s":10,"a":65,"t":"Que ce qu'ils disent ne t'afflige pas. La puissance toute entière appartient à Allah. C'est Lui qui est l'Audient, l'Omniscient."},{"n":1430,"s":10,"a":66,"t":"C'est à Allah qu'appartient, ce qui est dans les cieux et ce qui est sur la terre. Que suivent donc ceux qui invoquent, en dehors d'Allah, [des divinités] qu'ils Lui associent? Ils ne suivent que la conjecture et ne font que mentir."},{"n":1431,"s":10,"a":67,"t":"C'est Lui qui vous a désigné la nuit pour que vous vous y reposiez, et le jour pour vous permettre de voir. Ce sont en vérité des signes pour les gens qui entendent!"},{"n":1432,"s":10,"a":68,"t":"Ils disent: «Allah S'est donné un enfant» Gloire et Pureté à Lui! Il est Le Riche par excellence. A Lui appartient tout ce qui est aux cieux et sur la terre; - vous n'avez pour cela aucune preuve. Allez-vous dire contre Allah ce que vous ne savez pas?"},{"n":1433,"s":10,"a":69,"t":"Dis: «En vérité, ceux qui forgent le mensonge contre Allah ne réussiront pas»."},{"n":1434,"s":10,"a":70,"t":"C'est une jouissance (temporaire) dans la vie d'ici-bas; puis ils retourneront vers Nous et Nous leur ferons goûter au dur châtiment, à titre de sanction pour leur mécréance."},{"n":1435,"s":10,"a":71,"t":"Raconte-leur l'histoire de Noé, quand il dit à son peuple: «O mon peuple, si mon séjour (parmi vous), et mon rappel des signes d'Allah vous pèsent trop, alors c'est en Allah que je place (entièrement) ma confiance. Concertez-vous avec vos associés, et ne cachez pas vos desseins. Puis, décidez de moi et ne me donnez pas de répit."},{"n":1436,"s":10,"a":72,"t":"Si vous vous détournez, alors je ne vous ai pas demandé de salaire... Mon salaire n'incombe qu'à Allah. Et il m'a été commandé d'être du nombre des soumis»."},{"n":1437,"s":10,"a":73,"t":"Ils le traitèrent de menteur. Nous le sauvâmes, lui et ceux qui étaient avec lui dans l'arche, desquels Nous fîmes les successeurs (sur la terre). Nous noyâmes ceux qui traitaient de mensonge Nos preuves. Regarde comment a été la fin de ceux qui avaient été avertis!"},{"n":1438,"s":10,"a":74,"t":"Puis Nous envoyâmes après lui des messagers à leurs peuples. Ils leur vinrent avec les preuves. Mais (les gens) étaient tels qu'ils ne pouvaient croire à ce qu'auparavant ils avaient traité de mensonge. Ainsi scellons-Nous les cœurs des transgresseurs."},{"n":1439,"s":10,"a":75,"t":"Ensuite, Nous envoyâmes après eux Moïse et Aaron, munis de Nos preuves à Pharaon et ses notables. Mais (ces gens) s'enflèrent d'orgueil et ils étaient un peuple criminel."},{"n":1440,"s":10,"a":76,"t":"Et lorsque la vérité leur vint de Notre part, ils dirent: «Voilà certes, une magie manifeste!»"},{"n":1441,"s":10,"a":77,"t":"Moïse dit: «Dites-vous à la Vérité quand elle vous est venue: Est-ce que cela est de la magie? Alors que les magiciens ne réussissent pas...»."},{"n":1442,"s":10,"a":78,"t":"Ils dirent: «Est-ce pour nous écarter de ce sur quoi nous avons trouvé nos ancêtres que tu es venu à nous, et pour que la grandeur appartienne à vous deux sur la terre? Et nous ne croyons pas en vous!»"},{"n":1443,"s":10,"a":79,"t":"Et Pharaon dit: «Amenez-moi tout magicien savant!»"},{"n":1444,"s":10,"a":80,"t":"Puis, lorsque vinrent les magiciens, Moïse leur dit: «Jetez ce que vous avez à jeter»."},{"n":1445,"s":10,"a":81,"t":"Lorsqu'ils jetèrent, Moïse dit: «Ce que vous avez produit est magie! Allah l'annulera. Car Allah ne fait pas prospérer ce que font les fauteurs de désordre."},{"n":1446,"s":10,"a":82,"t":"Et par Ses paroles, Allah fera triompher la Vérité, quelque répulsion qu'en aient les criminels»."},{"n":1447,"s":10,"a":83,"t":"Personne ne crut (au message) de Moïse, sauf un groupe de jeunes gens de son peuple, par crainte de représailles de Pharaon et de leurs notables. En vérité, Pharaon fut certes superbe sur terre et il fut du nombre des extravagants."},{"n":1448,"s":10,"a":84,"t":"Et Moïse dit: «O mon peuple, si vous croyez en Allah, placez votre confiance en Lui si vous (Lui) êtes soumis»."},{"n":1449,"s":10,"a":85,"t":"Ils dirent: «En Allah nous plaçons notre confiance. O notre Seigneur, ne fais pas de nous une cible pour les persécutions des injustes."},{"n":1450,"s":10,"a":86,"t":"Et délivre-nous, par Ta miséricorde, des gens mécréants»."},{"n":1451,"s":10,"a":87,"t":"Et Nous révélâmes à Moïse et à son frère: «Prenez pour votre peuple des maisons en Egypte, faites de vos maisons un lieu de prière et soyez assidus dans la prière. Et fais la bonne annonce aux croyants»."},{"n":1452,"s":10,"a":88,"t":"Et Moïse dit: «O notre Seigneur, Tu as accordé à Pharaon et ses notables des parures et des biens dans la vie présente, et voilà, O notre Seigneur, qu'avec cela ils égarent (les gens loin) de Ton sentier. O notre Seigneur, anéantis leurs biens et endurcis leurs cœurs, afin qu'ils ne croient pas, jusqu'à ce qu'ils aient vu le châtiment douloureux»."},{"n":1453,"s":10,"a":89,"t":"Il dit: «Votre prière est exaucée. Restez tous deux sur le chemin droit, et ne suivez point le sentier de ceux qui ne savent pas»."},{"n":1454,"s":10,"a":90,"t":"Et Nous fîmes traverser la mer aux Enfants d'Israël. Pharaon et ses armées les poursuivirent avec acharnement et inimitié. Puis, quand la noyade l'eut atteint, il dit: «Je crois qu'il n'y a d'autre divinité que Celui en qui ont cru les enfants d'Israël. Et je suis du nombre des soumis»."},{"n":1455,"s":10,"a":91,"t":"[Allah dit]: Maintenant? Alors qu'auparavant tu as désobéi et que tu as été du nombre des corrupteurs!"},{"n":1456,"s":10,"a":92,"t":"Nous allons aujourd'hui épargner ton corps, afin que tu deviennes un signe à tes successeurs. Cependant beaucoup de gens ne prêtent aucune attention à Nos signes (d'avertissement)."},{"n":1457,"s":10,"a":93,"t":"Certes, Nous avons établi les Enfants d'Israël dans un endroit honorable, et leur avons attribué comme nourriture de bons aliments. Par la suite, ils n'ont divergé qu'au moment où leur vint la science. Ton Seigneur décidera entre eux, au Jour de la Résurrection sur ce qui les divisait."},{"n":1458,"s":10,"a":94,"t":"Et si tu es en doute sur ce que Nous avons fait descendre vers toi, interroge alors ceux qui lisent le Livre révélé avant toi. La vérité certes, t'est venue de ton Seigneur: ne sois donc point de ceux qui doutent."},{"n":1459,"s":10,"a":95,"t":"Et ne sois point de ceux qui traitent de mensonge les versets d'Allah. Tu serais alors du nombre des perdants."},{"n":1460,"s":10,"a":96,"t":"Ceux contre qui la parole (la menace) de ton Seigneur se réalisera ne croiront pas,"},{"n":1461,"s":10,"a":97,"t":"même si tous les signes leur parvenaient, jusqu'à ce qu'ils voient le châtiment douloureux."},{"n":1462,"s":10,"a":98,"t":"Si seulement il y avait, à part le peuple de Yûnus (Jonas), une cité qui ait cru et à qui sa croyance eut ensuite profité! Lorsqu'ils eurent cru, Nous leur enlevâmes le châtiment d'ignominie dans la vie présente et leur donnâmes jouissance pour un certain temps."},{"n":1463,"s":10,"a":99,"t":"Si ton Seigneur l'avait voulu, tous ceux qui sont sur la terre auraient cru. Est-ce à toi de contraindre les gens à devenir croyants?"},{"n":1464,"s":10,"a":100,"t":"Il n'appartient nullement à une âme de croire si ce n'est avec la permission d'Allah. Et Il voue au châtiment ceux qui ne raisonnent pas."},{"n":1465,"s":10,"a":101,"t":"Dis: «Regardez ce qui est dans les cieux et sur la terre». Mais ni les preuves ni les avertisseurs (prophètes) ne suffisent à des gens qui ne croient pas."},{"n":1466,"s":10,"a":102,"t":"Est-ce qu'ils attendent autre chose que des châtiments semblables à ceux des peuples antérieurs? Dis: «Attendez! Moi aussi, j'attends avec vous»."},{"n":1467,"s":10,"a":103,"t":"Ensuite, Nous délivrerons Nos messagers et les croyants. C'est ainsi qu'il Nous incombe [en toute justice] de délivrer les croyants."},{"n":1468,"s":10,"a":104,"t":"Dis: «O gens! Si vous êtes en doute sur ma religion, moi, je n'adore point ceux que vous adorez en dehors d'Allah; mais j'adore Allah qui vous fera mourir. Et il m'a été commandé d'être du nombre des croyants»."},{"n":1469,"s":10,"a":105,"t":"Et (il m'a été dit): «Oriente-toi exclusivement sur la religion en pur monothéiste! Et ne sois pas du nombre des Associateurs;"},{"n":1470,"s":10,"a":106,"t":"et n'invoque pas, en dehors d'Allah, ce qui ne peut te profiter ni te nuire. Et si tu le fais, tu seras alors du nombre des injustes»."},{"n":1471,"s":10,"a":107,"t":"Et si Allah fait qu'un mal te touche, nul ne peut l'écarter en dehors de Lui. Et s'Il te veut un bien, nul ne peut repousser Sa grâce. Il en gratifie qui Il veut parmi Ses serviteurs. Et c'est Lui le Pardonneur, le Miséricordieux."},{"n":1472,"s":10,"a":108,"t":"Dis: «O gens! Certes la vérité vous est venue de votre Seigneur. Donc, quiconque est dans le bon chemin ne l'est que pour lui-même; et quiconque s'égare, ne s'égare qu'à son propre détriment. Je ne suis nullement un protecteur pour vous."},{"n":1473,"s":10,"a":109,"t":"Et suis ce qui t'est révélé, et sois constant jusqu'à ce qu'Allah rende Son jugement car Il est le meilleur des juges."},{"n":1474,"s":11,"a":1,"t":"Alif, Lâm, Râ. C'est un Livre dont les versets sont parfaits en style et en sens, émanant d'un Sage, Parfaitement Connaisseur."},{"n":1475,"s":11,"a":2,"t":"N'adorez qu'Allah. Moi, je suis pour vous, de Sa part, un avertisseur et un annonciateur."},{"n":1476,"s":11,"a":3,"t":"Demandez pardon à votre Seigneur; ensuite, revenez à Lui. Il vous accordera une belle jouissance jusqu'à un terme fixé, et Il accordera à chaque méritant l'honneur qu'il mérite. Mais si vous tournez le dos, je crains alors pour vous le châtiment d'un grand jour."},{"n":1477,"s":11,"a":4,"t":"C'est à Allah que sera votre retour; et Il est Omnipotent."},{"n":1478,"s":11,"a":5,"t":"Eh quoi! Ils replient leurs poitrines afin de se cacher de Lui. Même lorsqu'ils se couvrent de leurs vêtements, Il sait ce qu'ils cachent et ce qu'ils divulguent car Il connaît certes le contenu des poitrines."},{"n":1479,"s":11,"a":6,"t":"Il n'y a point de bête sur terre dont la subsistance n'incombe à Allah qui connaît son gîte et son dépôt; tout est dans un Livre explicite."},{"n":1480,"s":11,"a":7,"t":"Et c'est Lui qui a créé les cieux et la terre en six jours, - alors que Son Trône était sur l'eau, - afin d'éprouver lequel de vous agirait le mieux. Et si tu dis: «Vous serez ressuscités après la mort», ceux qui ne croient pas diront: «Ce n'est là qu'une magie évidente»."},{"n":1481,"s":11,"a":8,"t":"Et si Nous retardons pour eux le châtiment jusqu'à une période fixée, ils diront: «Qu'est-ce qui le retient?» - Mais le jour où cela leur viendra, il ne sera pas détourné; d'eux et ce dont ils se moquaient les enveloppera."},{"n":1482,"s":11,"a":9,"t":"Et si Nous faisons goûter à l'homme une grâce de Notre part, et qu'ensuite Nous la lui arrachons, le voilà désespéré et ingrat."},{"n":1483,"s":11,"a":10,"t":"Et si Nous lui faisons goûter le bonheur, après qu'un malheur l'ait touché, il dira: «Les maux se sont éloignés de moi», et le voilà qui exulte, plein de gloriole."},{"n":1484,"s":11,"a":11,"t":"sauf ceux qui sont endurants et font de bonnes œuvres. Ceux-là obtiendront pardon et une grosse récompense."},{"n":1485,"s":11,"a":12,"t":"Il se peut que tu négliges une partie de ce qui t'est révélé, et que ta poitrine s'en sente compressée; parce qu'ils disent: «Que n'a-t-on fait descendre sur lui un trésor?» Ou bien: «Que n'est-il venu un Ange en sa compagnie?» - Tu n'es qu'un avertisseur. Et Allah est Le protecteur de toute chose."},{"n":1486,"s":11,"a":13,"t":"Ou bien ils disent: «Il l'a forgé [le Coran]» - Dis: «Apportez donc dix Sourates semblables à ceci, forgées (par vous). Et appelez qui vous pourrez (pour vous aider), hormis Allah, si vous êtes véridiques»."},{"n":1487,"s":11,"a":14,"t":"S'ils ne vous répondent pas, sachez alors que c'est par la science d'Allah qu'il est descendu, et qu'il n'y a de divinité que Lui. Etes-vous soumis (à Lui)?"},{"n":1488,"s":11,"a":15,"t":"Ceux qui veulent la vie présente avec sa parure, Nous les rétribuerons exactement selon leurs actions sur terre, sans que rien leur en soit diminué."},{"n":1489,"s":11,"a":16,"t":"Ceux-là qui n'ont rien, dans l'au-delà, que le Feu. Ce qu'ils auront fait ici-bas sera un échec, et sera vain ce qu'ils auront œuvré."},{"n":1490,"s":11,"a":17,"t":"Est-ce que celui qui se fonde sur une preuve évidente (le Coran) venant de son Seigneur et récitée par un témoin [l'archange Gabriel] de Sa part, cependant qu'avant lui [Muhammad] il y a le livre de Moïse tenant lieu de guide et de miséricorde... [est meilleur ou bien celui qui ne se fonde sur aucune preuve valable?]. Ceux-là y croient; mais quiconque d'entre les factions n'y croit pas, aura le Feu comme rendez-vous. Ne sois donc pas en doute au sujet de ceci (le Coran). Oui, c'est la vérité venant de ton Seigneur; mais la plupart des gens n'y croient pas."},{"n":1491,"s":11,"a":18,"t":"Et quel pire injuste que celui qui forge un mensonge contre Allah? Ceux-là seront présentés à leur Seigneur, et les témoins (les anges) diront: «Voilà ceux qui ont menti contre leur Seigneur». Que la malédiction d'Allah (frappe) les injustes,"},{"n":1492,"s":11,"a":19,"t":"qui obstruent le sentier d'Allah (aux gens), cherchent à le rendre tortueux et ne croient pas en l'au-delà."},{"n":1493,"s":11,"a":20,"t":"Ceux-là ne peuvent réduire (Allah) à l'impuissance sur terre! Pas d'alliés pour eux en dehors d'Allah et leur châtiment sera doublé. Ils étaient incapables d'entendre; ils ne voyaient pas non plus."},{"n":1494,"s":11,"a":21,"t":"Ce sont ceux-là qui ont causé la perte de leurs propres âmes. Et leurs inventions (idoles) se sont éloignées d'eux."},{"n":1495,"s":11,"a":22,"t":"Ce sont eux, infailliblement, qui dans l'au-delà seront les plus grands perdants."},{"n":1496,"s":11,"a":23,"t":"Certes ceux qui croient, font de bonnes œuvres et s'humilient devant leur Seigneur, voilà les gens du Paradis où ils demeureront éternellement."},{"n":1497,"s":11,"a":24,"t":"Les deux groupes ressemblent, l'un à l'aveugle et au sourd, l'autre à celui qui voit et qui entend. Les deux sont-ils comparativement égaux? Ne vous souvenez-vous pas?"},{"n":1498,"s":11,"a":25,"t":"Nous avons déjà envoyé Noé à son peuple: «Je suis pour vous un avertisseur explicite"},{"n":1499,"s":11,"a":26,"t":"afin que vous n'adoriez qu'Allah. Je crains pour vous le châtiment d'un jour douloureux»."},{"n":1500,"s":11,"a":27,"t":"Les notables de son peuple qui avaient mécru, dirent alors: «Nous ne voyons en toi qu'un homme comme nous; et nous voyons que ce sont seulement les vils parmi nous qui te suivent sans réfléchir; et nous ne voyons en vous aucune supériorité sur nous. Plutôt, nous pensons que vous êtes des menteurs»."},{"n":1501,"s":11,"a":28,"t":"Il dit: «O mon peuple! Que vous en semble? Si je me conforme à une preuve de mon Seigneur, si une Miséricorde, (prophétie) échappant à vos yeux, est venue à moi de Sa part, devrons-nous vous l'imposer alors que vous la répugnez?"},{"n":1502,"s":11,"a":29,"t":"O mon peuple, je ne vous demande pas de richesse en retour. Mon salaire n'incombe qu'à Allah. Je ne repousserai point ceux qui ont cru, ils auront à rencontrer leur Seigneur. Mais je vous trouve des gens ignorants."},{"n":1503,"s":11,"a":30,"t":"O mon peuple, qui me secourra contre (la punition d') Allah si je les repousse? Ne vous souvenez-vous pas?"},{"n":1504,"s":11,"a":31,"t":"Et je ne vous dis pas que je détiens les trésors d'Allah, je ne connais pas l'Inconnaissable, et je ne dis pas que je suis un Ange; et je ne dis pas non plus aux gens, que vos yeux méprisent, qu'Allah ne leur accordera aucune faveur; Allah connaît mieux ce qu'il y a dans leurs âmes. [Si je le leur disais], je serais du nombre des injustes."},{"n":1505,"s":11,"a":32,"t":"Ils dirent: «O Noé, tu as disputé avec nous et multiplié les discussions. Apporte-nous donc ce dont tu nous menaces, si tu es du nombre des véridiques»."},{"n":1506,"s":11,"a":33,"t":"Il dit: «C'est Allah seul qui vous l'apportera - s'Il veut - et vous ne saurez y échapper."},{"n":1507,"s":11,"a":34,"t":"Et mon conseil ne vous profiterait pas, au cas où je voulais vous conseiller, et qu'Allah veuille vous égarer. Il est votre Seigneur, et c'est vers Lui que vous serez ramenés»."},{"n":1508,"s":11,"a":35,"t":"Ou bien ils disent: il l'a inventé? Dis: «Si je l'ai inventé, que mon crime retombe sur moi! Et je suis innocent de vos criminelles accusations»."},{"n":1509,"s":11,"a":36,"t":"Et il fut révélé à Noé: «De ton peuple, il n'y aura plus de croyants que ceux qui ont déjà cru. Ne t'afflige pas de ce qu'ils faisaient."},{"n":1510,"s":11,"a":37,"t":"Et construis l'arche sous Nos yeux et d'après Notre révélation. Et ne M'interpelle plus au sujet des injustes, car ils vont être noyés»."},{"n":1511,"s":11,"a":38,"t":"Et il construisait l'arche. Et chaque fois que des notables de son peuple passaient près de lui, ils se moquaient de lui. Il dit: «Si vous vous moquez de nous, eh bien, nous nous moquerons de vous, comme vous vous moquez [de nous]."},{"n":1512,"s":11,"a":39,"t":"Et vous saurez bientôt à qui viendra un châtiment qui l'humiliera, et sur qui s'abattra un châtiment durable!»"},{"n":1513,"s":11,"a":40,"t":"Puis, lorsque Notre commandement vint et que le four se mit à bouillonner [d'eau], Nous dîmes: «Charge [dans l'arche] un couple de chaque espèce ainsi que ta famille - sauf ceux contre qui le décret est déjà prononcé - et ceux qui croient». Or, ceux qui avaient cru avec lui étaient peu nombreux."},{"n":1514,"s":11,"a":41,"t":"Et il dit: «Montez dedans. Que sa course et son mouillage soient au nom d'Allah. Certes mon Seigneur est Pardonneur et Miséricordieux»."},{"n":1515,"s":11,"a":42,"t":"Et elle vogua en les emportant au milieu des vagues comme des montagnes. Et Noé appela son fils, qui restait en un lieu écarté (non loin de l'arche): «O mon enfant, monte avec nous et ne reste pas avec les mécréants»."},{"n":1516,"s":11,"a":43,"t":"Il répondit: «Je vais me réfugier vers un mont qui me protègera de l'eau». Et Noé lui dit: «Il n'y a aujourd'hui aucun protecteur contre l'ordre d'Allah. (Tous périront) sauf celui à qui Il fait miséricorde». Et les vagues s'interposèrent entre les deux, et le fils fut alors du nombre des noyés."},{"n":1517,"s":11,"a":44,"t":"Et il fut dit: «O terre, absorbe ton eau! Et toi, ciel, cesse [de pleuvoir]!» L'eau baissa, l'ordre fut exécuté et l'arche s'installa sur le Jûdi, et il fut dit: «Que disparaissent les gens pervers»!"},{"n":1518,"s":11,"a":45,"t":"Et Noé invoqua son Seigneur et dit: «O mon Seigneur, certes mon fils est de ma famille et Ta promesse est vérité. Tu es le plus juste des juges»."},{"n":1519,"s":11,"a":46,"t":"Il dit: «O Noé, il n'est pas de ta famille car il a commis un acte infâme. Ne me demande pas ce dont tu n'as aucune connaissance. Je t'exhorte afin que tu ne sois pas du nombre des ignorants»."},{"n":1520,"s":11,"a":47,"t":"Alors Noé dit: «Seigneur, je cherche Ta protection contre toute demande de ce dont je n'ai aucune connaissance. Et si Tu ne me pardonnes pas et ne me fais pas miséricorde, je serai au nombre des perdants»."},{"n":1521,"s":11,"a":48,"t":"Il fut dit: «O Noé, débarque avec Notre sécurité et Nos bénédictions sur toi et sur des communautés [issues] de ceux qui sont avec toi. Et il y (en) aura des communautés auxquelles Nous accorderons une jouissance temporaire; puis un châtiment douloureux venant de Nous les touchera»."},{"n":1522,"s":11,"a":49,"t":"Voilà quelques nouvelles de l'Inconnaissable que Nous te révélons. Tu ne les savais pas, ni toi ni ton peuple, avant cela. Sois patient. La fin heureuse sera aux pieux."},{"n":1523,"s":11,"a":50,"t":"Et (Nous avons envoyé) aux 'Aad, leur frère Hûd, qui leur dit: «O mon peuple, adorez Allah. Vous n'avez point de divinité à part Lui. Vous n'êtes que des forgeurs (de mensonges)."},{"n":1524,"s":11,"a":51,"t":"O mon peuple, je ne vous demande pas de salaire pour cela. Mon salaire n'incombe qu'à Celui qui m'a créé. Ne raisonnez-vous pas?"},{"n":1525,"s":11,"a":52,"t":"O mon peuple, implorez le pardon de votre Seigneur et repentez-vous à Lui pour qu'Il envoie sur vous du ciel des pluies abondantes et qu'Il ajoute force à votre force. Et ne vous détournez pas [de Lui] en devenant coupables»."},{"n":1526,"s":11,"a":53,"t":"Ils dirent: «O Hûd, tu n'es pas venu à nous avec une preuve, et nous ne sommes pas disposés à abandonner nos divinités sur ta parole, et nous n'avons pas foi en toi."},{"n":1527,"s":11,"a":54,"t":"Nous dirons plutôt qu'une de nos divinités t'a affligé d'un mal». Il dit: «Je prends Allah à témoin - et vous aussi soyez témoins - qu'en vérité, je désavoue ce que vous associez,"},{"n":1528,"s":11,"a":55,"t":"en dehors de Lui. Rusez donc tous contre moi et ne me donnez pas de répit."},{"n":1529,"s":11,"a":56,"t":"Je place ma confiance en Allah, mon Seigneur et le vôtre. Il n'y a pas d'être vivant qu'Il ne tienne par son toupet. Mon Seigneur, certes, est sur un droit chemin."},{"n":1530,"s":11,"a":57,"t":"Si vous vous détournez... voilà que je vous ai transmis [le message] que j'étais chargé de vous faire parvenir. Et mon Seigneur vous remplacera par un autre peuple, sans que vous ne Lui nuisiez en rien, car mon Seigneur, est gardien par excellence sur toute chose»."},{"n":1531,"s":11,"a":58,"t":"Et quand vint Notre Ordre, Nous sauvâmes par une miséricorde de Notre part, Hûd et ceux qui avec lui avaient cru. Et Nous les sauvâmes d'un terrible châtiment."},{"n":1532,"s":11,"a":59,"t":"Voilà les 'Aad. Ils avaient nié les signes (enseignements) de leur Seigneur, désobéi à Ses messagers et suivi le commandement de tout tyran entêté."},{"n":1533,"s":11,"a":60,"t":"Et ils furent poursuivis, ici-bas, d'une malédiction, ainsi qu'au Jour de la Résurrection. En vérité, les 'Aad n'ont pas cru en leur Seigneur. Que s'éloignent (périssent) les 'Aad, peuple de Hûd!"},{"n":1534,"s":11,"a":61,"t":"Et (Nous avons envoyé) aux Thamûd, leur frère Sâlih qui dit: «O mon peuple, adorez Allah. Vous n'avez point de divinité en dehors de Lui. De la terre Il vous a créés, et Il vous l'a fait peupler (et exploiter). Implorez donc Son pardon, puis repentez-vous à Lui. Mon Seigneur est bien proche et Il répond toujours (aux appels)»."},{"n":1535,"s":11,"a":62,"t":"Ils dirent: «O Sâlih, tu étais auparavant un espoir pour nous. Nous interdirais-tu d'adorer ce qu'adoraient nos ancêtres? Cependant, nous voilà bien dans un doute troublant au sujet de ce vers quoi tu nous invites»."},{"n":1536,"s":11,"a":63,"t":"Il dit: «O mon peuple! Que vous en semble, si je m'appuie sur une preuve évidente émanant de mon Seigneur et s'Il m'a accordé, de Sa part, une miséricorde, qui donc me protègera contre Allah si je Lui désobéis? Vous ne ferez qu'accroître ma perte."},{"n":1537,"s":11,"a":64,"t":"O mon peuple, voici la chamelle d'Allah qu'Il vous a envoyée comme signe. Laissez-la donc paître sur la terre d'Allah, et ne lui faites aucun mal sinon, un châtiment proche vous saisira!»"},{"n":1538,"s":11,"a":65,"t":"Ils la tuèrent. Alors, il leur dit: «Jouissez (de vos biens) dans vos demeures pendant trois jours (encore)! Voilà une promesse qui ne sera pas démentie»."},{"n":1539,"s":11,"a":66,"t":"Puis, lorsque Notre ordre vint, Nous sauvâmes Sâlih et ceux qui avaient cru avec lui, - par une miséricorde venant de Nous - de l'ignominie de ce jour-là. En vérité, c'est ton Seigneur qui est le Fort, le Puissant."},{"n":1540,"s":11,"a":67,"t":"Et le Cri saisit les injustes. Et les voilà foudroyés dans leurs demeures,"},{"n":1541,"s":11,"a":68,"t":"comme s'ils n'y avaient jamais prospéré. En vérité, les Thamûd n'ont pas cru en leur Seigneur. Que périssent les Thamûd!"},{"n":1542,"s":11,"a":69,"t":"Et Nos émissaires sont, certes, venus à Abraham avec la bonne nouvelle, en disant: «Salâm!». Il dit: «Salâm!», et il ne tarda pas à apporter un veau rôti."},{"n":1543,"s":11,"a":70,"t":"Puis, lorsqu'il vit que leurs mains ne l'approchaient pas, il fut pris de suspicion à leur égard et ressentit de la peur vis-à-vis d'eux. Ils dirent: «N'aie pas peur, nous sommes envoyés au peuple de Lot»."},{"n":1544,"s":11,"a":71,"t":"Sa femme était debout, et elle rit alors; Nous lui annonçâmes donc (la naissance d') Isaac, et après Isaac, Jacob."},{"n":1545,"s":11,"a":72,"t":"Elle dit: «Malheur à moi! Vais-je enfanter alors que je suis vieille et que mon mari, que voici, est un vieillard? C'est là vraiment une chose étrange!»"},{"n":1546,"s":11,"a":73,"t":"Ils dirent: «T'étonnes-tu de l'ordre d'Allah? Que la miséricorde d'Allah et Ses bénédictions soient sur vous, gens de cette maison! Il est vraiment, digne de louange et de glorification!»"},{"n":1547,"s":11,"a":74,"t":"Lorsque l'effroi eut quitté Abraham et que la bonne nouvelle l'eut atteint, voilà qu'il discuta avec Nous (en faveur) du peuple de Lot."},{"n":1548,"s":11,"a":75,"t":"Abraham était, certes, longanime, très implorant et repentant."},{"n":1549,"s":11,"a":76,"t":"O Abraham, renonce à cela; car l'ordre de Ton Seigneur est déjà venu, et un châtiment irrévocable va leur arriver»."},{"n":1550,"s":11,"a":77,"t":"Et quand Nos émissaires (Anges) vinrent à Lot, il fut chagriné pour eux, et en éprouva une grande gêne. Et il dit: «Voici un jour terrible»."},{"n":1551,"s":11,"a":78,"t":"Quant à son peuple, ils vinrent à lui, accourant. Auparavant ils commettaient des mauvaises actions. Il dit: «O mon peuple, voici mes filles: elles sont plus pures pour vous. Craignez Allah donc, et ne me déshonorez pas dans mes hôtes. N'y a-t-il pas parmi vous un homme raisonnable?»"},{"n":1552,"s":11,"a":79,"t":"Ils dirent: Tu sais très bien que nous n'avons pas de droit sur tes filles. Et en vérité, tu sais bien ce que nous voulons»."},{"n":1553,"s":11,"a":80,"t":"Il dit: «[Ah!] si j'avais de la force pour vous résister! ou bien si je trouvais un appui solide!»"},{"n":1554,"s":11,"a":81,"t":"Alors [les hôtes] dirent: «O Lot, nous sommes vraiment les émissaires de ton Seigneur. Ils ne pourront jamais t'atteindre. Pars avec ta famille à un moment de la nuit. Et que nul d'entre vous ne se retourne en arrière. Exception faite de ta femme qui sera atteinte par ce qui frappera les autres. Ce qui les menace s'accomplira à l'aube. L'aube n'est-elle pas proche?»"},{"n":1555,"s":11,"a":82,"t":"Et, lorsque vint Notre ordre, Nous renversâmes [la cité] de fond en comble, et fîmes pleuvoir sur elle en masse, des pierres d'argile succédant les unes aux autres,"},{"n":1556,"s":11,"a":83,"t":"portant une marque connue de ton Seigneur. Et elles (ces pierres) ne sont pas loin des injustes."},{"n":1557,"s":11,"a":84,"t":"Et (Nous avons envoyé) aux Madyan, leur frère Chuayb qui leur dit: «O mon peuple, adorez Allah; vous n'avez point de divinité en dehors Lui. Et ne diminuez pas les mesures et le poids. Je vous vois dans l'aisance, et je crains pour vous [si vous ne croyez pas] le châtiment d'un jour qui enveloppera tout."},{"n":1558,"s":11,"a":85,"t":"O mon peuple, faites équitablement pleine mesure et plein poids, ne dépréciez pas aux gens leurs valeurs et ne semez pas la corruption sur terre."},{"n":1559,"s":11,"a":86,"t":"Ce qui demeure auprès d'Allah est meilleur pour vous si vous êtes croyants! Et je ne suis pas un gardien pour vous»."},{"n":1560,"s":11,"a":87,"t":"Ils dirent: «O Chuayb! Est-ce que ta prière te demande de nous faire abandonner ce qu'adoraient nos ancêtres, ou de ne plus faire de nos biens ce que nous voulons? Est-ce toi l'indulgent, le droit?»"},{"n":1561,"s":11,"a":88,"t":"Il dit: «O mon peuple, voyez-vous si je me base sur une preuve évidente émanant de mon Seigneur, et s'Il m'attribue de Sa part une excellente donation?... Je ne veux nullement faire ce que je vous interdis. Je ne veux que la réforme, autant que je le puis. Et ma réussite ne dépend que d'Allah. En Lui je place ma confiance, et c'est vers Lui que je reviens repentant."},{"n":1562,"s":11,"a":89,"t":"O mon peuple, que votre répugnance et votre hostilité à mon égard ne vous entraînent pas à encourir les mêmes châtiments qui atteignirent le peuple de Noé, le peuple de Hûd, ou le peuple de Sâlih et (l'exemple du) peuple de Lot n'est pas éloigné de vous."},{"n":1563,"s":11,"a":90,"t":"Et implorez le pardon de votre Seigneur et repentez-vous à Lui. Mon Seigneur est vraiment Miséricordieux et plein d'amour»."},{"n":1564,"s":11,"a":91,"t":"Ils dirent: «O Chuayb, nous ne comprenons pas grand chose à ce que tu dis; et vraiment nous te considérons comme un faible parmi nous. Si ce n'est ton clan, nous t'aurions certainement lapidé. Et rien ne nous empêche de t'atteindre»."},{"n":1565,"s":11,"a":92,"t":"Il dit: «O mon peuple, mon clan est-il à vos yeux plus puissant qu'Allah à qui vous tournez ouvertement le dos? Mon Seigneur embrasse (en Sa science) tout ce que vous œuvrez."},{"n":1566,"s":11,"a":93,"t":"O mon peuple, agissez autant que vous voulez. Moi aussi j'agis. Bientôt, vous saurez sur qui tombera un châtiment qui le déshonorera, et qui de nous est l'imposteur. Et attendez (la conséquence de vos actes)! Moi aussi j'attends avec vous»."},{"n":1567,"s":11,"a":94,"t":"Lorsque vint Notre ordre, Nous sauvâmes, par une miséricorde de Notre part, Chuayb et ceux qui avaient cru avec lui. Et le Cri terrible saisit les injustes, et ils gisèrent dans leurs demeures,"},{"n":1568,"s":11,"a":95,"t":"comme s'ils n'y avaient jamais prospéré. Que les Madyan s'éloignent comme les Thamûd se sont éloignés."},{"n":1569,"s":11,"a":96,"t":"Et Nous avions envoyé Moïse, avec Nos miracles et une autorité incontestable,"},{"n":1570,"s":11,"a":97,"t":"à Pharaon et ses notables. Mais ils suivirent l'ordre de Pharaon, bien que l'ordre de Pharaon n'avait rien de sensé."},{"n":1571,"s":11,"a":98,"t":"Il précédera son peuple, au Jour de la Résurrection. Il les mènera à l'aiguade du Feu. Et quelle détestable aiguade!"},{"n":1572,"s":11,"a":99,"t":"Et ils sont poursuivis par une malédiction ici-bas et au Jour de la Résurrection. Quel détestable don leur sera donné!"},{"n":1573,"s":11,"a":100,"t":"Cela fait partie des récits que Nous te [Muhammad] racontons concernant des cités: les unes sont encore debout, tandis que d'autres (sont complètement) rasées."},{"n":1574,"s":11,"a":101,"t":"Nous ne leur avons fait aucun tort. Mais ils se sont fait du tort à eux-mêmes. Leurs divinités, qu'ils invoquaient en dehors d'Allah, ne leur ont servi à rien, quand l'Ordre (le châtiment) de ton Seigneur fut venu; elles n'ont fait qu'accroître leur perte."},{"n":1575,"s":11,"a":102,"t":"Telle est la rigueur de la prise de ton Seigneur quand Il frappe les cités lorsqu'elles sont injustes. Son châtiment est bien douloureux et bien dur."},{"n":1576,"s":11,"a":103,"t":"Il y a bien là un signe pour celui qui craint le châtiment de l'au-delà. C'est un jour où les gens seront rassemblés; et c'est un jour solennel (attesté par tous)."},{"n":1577,"s":11,"a":104,"t":"Et Nous ne le retardons que pour un terme bien déterminé."},{"n":1578,"s":11,"a":105,"t":"Le jour où cela arrivera, nulle âme ne parlera qu'avec Sa permission (celle d'Allah). Il y aura des damnés et des heureux."},{"n":1579,"s":11,"a":106,"t":"Ceux qui sont damnés seront dans le Feu où ils ont des soupirs et des sanglots."},{"n":1580,"s":11,"a":107,"t":"Pour y demeurer éternellement tant que dureront les cieux et la terre - à moins que ton Seigneur en décide autrement - car ton Seigneur fait absolument tout ce qu'Il veut."},{"n":1581,"s":11,"a":108,"t":"Et quant aux bienheureux, ils seront au Paradis, pour y demeurer éternellement tant que dureront les cieux et la terre - à moins que ton Seigneur n'en décide autrement - c'est là un don qui n'est jamais interrompu."},{"n":1582,"s":11,"a":109,"t":"Ne sois donc pas en doute au sujet de ce que ceux-là adorent. Ils n'adorent que comme leurs ancêtres adoraient auparavant. Et Nous leur donnerons la totalité de leur part, sans en rien retrancher."},{"n":1583,"s":11,"a":110,"t":"Et Nous avons déjà donné à Moïse le Livre. Il y eut des divergences à son sujet. S'il n'y avait pas un décret préalable de la part de ton Seigneur, tout aurait été décidé entre eux. Et ils sont, à son sujet pleins d'un doute troublant."},{"n":1584,"s":11,"a":111,"t":"Très certainement, ton Seigneur fera leur pleine rétribution à tous pour leurs œuvres... Il est Parfaitement Connaisseur de ce qu'ils font."},{"n":1585,"s":11,"a":112,"t":"Demeure sur le droit chemin comme il t'est commandé, ainsi que ceux qui sont revenus [à Allah] avec toi. Et ne commettez pas d'excès. Car vraiment Il observe ce que vous faites."},{"n":1586,"s":11,"a":113,"t":"Et ne vous penchez pas vers les injustes: sinon le Feu vous atteindrait. Vous n'avez pas d'alliés en dehors d'Allah. Et vous ne serez pas secourus."},{"n":1587,"s":11,"a":114,"t":"Et accomplis la Salât aux deux extrémités du jour et à certaines heures de la nuit. Les bonnes œuvres dissipent les mauvaises. Cela est une exhortation pour ceux qui réfléchissent."},{"n":1588,"s":11,"a":115,"t":"Et sois patient. Car Allah ne laisse pas perdre la récompense des gens bienfaisants."},{"n":1589,"s":11,"a":116,"t":"Si seulement il existait, dans les générations d'avant vous, des gens vertueux qui interdisent la corruption sur terre! (Hélas) Il n'y en avait qu'un petit nombre que Nous sauvâmes, alors que les injustes persistaient dans le luxe (exagéré) dans lequel ils vivaient, et ils étaient des criminels."},{"n":1590,"s":11,"a":117,"t":"Et ton Seigneur n'est point tel à détruire injustement des cités dont les habitants sont des réformateurs."},{"n":1591,"s":11,"a":118,"t":"Et si ton Seigneur avait voulu, Il aurait fait des gens une seule communauté. Or, ils ne cessent d'être en désaccord (entre eux,)"},{"n":1592,"s":11,"a":119,"t":"sauf ceux à qui ton Seigneur a accordé miséricorde. C'est pour cela qu'Il les a créés. Et la parole de ton Seigneur s'accomplit: «Très certainement, Je remplirai l'Enfer de djinns et d'hommes, tous ensemble»."},{"n":1593,"s":11,"a":120,"t":"Et tout ce que Nous te racontons des récits des messagers, c'est pour en raffermir ton cœur. Et de ceux-ci t'est venue la vérité ainsi qu'une exhortation et un rappel aux croyants."},{"n":1594,"s":11,"a":121,"t":"Et dis à ceux qui ne croient pas: «Oeuvrez autant que vous pouvez. Nous aussi, nous œuvrons."},{"n":1595,"s":11,"a":122,"t":"Et attendez. Nous aussi nous attendons!»"},{"n":1596,"s":11,"a":123,"t":"A Allah appartient l'Inconnaissable des cieux et de la terre, et c'est à Lui que revient l'ordre tout entier. Adore-Le donc et place ta confiance en Lui. Ton Seigneur n'est pas inattentif à ce que vous faites."},{"n":1597,"s":12,"a":1,"t":"Alif, Lâm, Râ. Tels sont les versets du Livre explicite."},{"n":1598,"s":12,"a":2,"t":"Nous l'avons fait descendre, un Coran en [langue] arabe, afin que vous raisonniez."},{"n":1599,"s":12,"a":3,"t":"Nous te racontons le meilleur récit, grâce à la révélation que Nous te faisons dans ce Coran même si tu étais auparavant du nombre des inattentifs (à ces récits)."},{"n":1600,"s":12,"a":4,"t":"Quand Joseph dit à son père: «O mon père, j'ai vu [en songe], onze étoiles, et aussi le soleil et la lune; je les ai vus prosternés devant moi»."},{"n":1601,"s":12,"a":5,"t":"«O mon fils, dit-il, ne raconte pas ta vision à tes frères car ils monteraient un complot contre toi; le Diable est certainement pour l'homme un ennemi déclaré."},{"n":1602,"s":12,"a":6,"t":"Ainsi ton Seigneur te choisira et t'enseignera l'interprétation des rêves, et Il parfera Son bienfait sur toi et sur la famille de Jacob, tout comme Il l'a parfait auparavant sur tes deux ancêtres, Abraham et Isaac, car ton Seigneur est Omniscient et Sage."},{"n":1603,"s":12,"a":7,"t":"Il y avait certainement, en Joseph et ses frères, des exhortations pour ceux qui interrogent,"},{"n":1604,"s":12,"a":8,"t":"quand ceux-ci dirent: «Joseph et son frère sont plus aimés de notre père que nous, alors que nous sommes un groupe bien fort. Notre père est vraiment dans un tort évident."},{"n":1605,"s":12,"a":9,"t":"Tuez Joseph ou bien éloignez-le dans n'importe quel pays, afin que le visage de votre père se tourne exclusivement vers vous, et que vous soyez après cela des gens de bien»."},{"n":1606,"s":12,"a":10,"t":"L'un d'eux dit: «Ne tuez pas Joseph, mais jetez-le si vous êtes disposés à agir, au fond du puits afin que quelque caravane le recueille»."},{"n":1607,"s":12,"a":11,"t":"Ils dirent: «O notre père, qu'as-tu à ne pas te fier à nous au sujet de Joseph? Nous sommes cependant bien intentionnés à son égard."},{"n":1608,"s":12,"a":12,"t":"Envoie-le demain avec nous faire une promenade et jouer. Et nous veillerons sur lui»."},{"n":1609,"s":12,"a":13,"t":"Il dit: «Certes, je m'attristerai que vous l'emmeniez; et je crains que le loup ne le dévore dans un moment où vous ne ferez pas attention à lui»."},{"n":1610,"s":12,"a":14,"t":"Ils dirent: «Si le loup le dévore alors que nous sommes nombreux, nous serons vraiment les perdants»."},{"n":1611,"s":12,"a":15,"t":"Et lorsqu'ils l'eurent emmené, et se furent mis d'accord pour le jeter dans les profondeurs invisibles du puits, Nous lui révélâmes: «Tu les informeras sûrement de cette affaire sans qu'ils s'en rendent compte»."},{"n":1612,"s":12,"a":16,"t":"Et ils vinrent à leur père, le soir, en pleurant."},{"n":1613,"s":12,"a":17,"t":"Ils dirent: «O notre père, nous sommes allés faire une course, et nous avons laissé Joseph auprès de nos effets; et le loup l'a dévoré. Tu ne nous croiras pas, même si nous disons la vérité»."},{"n":1614,"s":12,"a":18,"t":"Ils apportèrent sa tunique tachée d'un faux sang. Il dit: «Vos âmes, plutôt, vous ont suggéré quelque chose... [Il ne me reste plus donc] qu'une belle patience! C'est Allah qu'il faut appeler au secours contre ce que vous racontez!»"},{"n":1615,"s":12,"a":19,"t":"Or, vint une caravane. Ils envoyèrent leur chercheur d'eau, qui fit descendre son seau. Il dit: «Bonne nouvelle! Voilà un garçon!» Et ils le dissimulèrent [pour le vendre] telle une marchandise. Allah cependant savait fort bien ce qu'ils faisaient."},{"n":1616,"s":12,"a":20,"t":"Et ils le vendirent à vil prix: pour quelques dirhams comptés. Ils le considéraient comme indésirable."},{"n":1617,"s":12,"a":21,"t":"Et celui qui l'acheta était de l'Egypte. Il dit à sa femme: «Accorde lui une généreuse hospitalité. Il se peut qu'il nous soit utile ou que nous l'adoptions comme notre enfant.» Ainsi avons-nous raffermi Joseph dans le pays et nous lui avons appris l'interprétation des rêves. Et Allah est souverain en Son Commandement: mais la plupart des gens ne savent pas."},{"n":1618,"s":12,"a":22,"t":"Et quand il eut atteint sa maturité Nous lui accordâmes sagesse et savoir. C'est ainsi que nous récompensons les bienfaisants."},{"n":1619,"s":12,"a":23,"t":"Or celle [Zulikha] qui l'avait reçu dans sa maison essaya de le séduire. Et elle ferma bien les portes et dit: «Viens, (je suis prête pour toi!)» - Il dit: «Qu'Allah me protège! C'est mon maître qui m'a accordé un bon asile. Vraiment les injustes ne réussissent pas»."},{"n":1620,"s":12,"a":24,"t":"Et, elle le désira. Et il l'aurait désirée n'eût été ce qu'il vit comme preuve évidente de son Seigneur. Ainsi [Nous avons agi] pour écarter de lui le mal et la turpitude. Il était certes un de Nos serviteurs élus."},{"n":1621,"s":12,"a":25,"t":"Et tous deux coururent vers la porte, et elle lui déchira sa tunique par derrière. Ils trouvèrent le mari [de cette femme] à la porte. Elle dit: «Quelle serait la punition de quiconque a voulu faire du mal à ta famille, sinon la prison, ou un châtiment douloureux?»"},{"n":1622,"s":12,"a":26,"t":"[Joseph] dit: «C'est elle qui a voulu me séduire». Et un témoin, de la famille de celle-ci témoigna: «Si sa tunique [à lui] est déchirée par devant, alors c'est elle qui dit la vérité, tandis qu'il est du nombre des menteurs."},{"n":1623,"s":12,"a":27,"t":"Mais si sa tunique est déchirée par derrière, alors c'est elle qui mentit, tandis qu'il est du nombre des véridiques»."},{"n":1624,"s":12,"a":28,"t":"Puis, quand il (le mari) vit la tunique déchirée par derrière, il dit: «C'est bien de votre ruse de femmes! Vos ruses sont vraiment énormes!"},{"n":1625,"s":12,"a":29,"t":"Joseph, ne pense plus à cela! Et toi, (femme), implore le pardon pour ton péché car tu es fautive»."},{"n":1626,"s":12,"a":30,"t":"Et dans la ville, des femmes dirent: «la femme d'Al-'Azize essaye de séduire son valet! Il l'a vraiment rendue folle d'amour. Nous la trouvons certes dans un égarement évident."},{"n":1627,"s":12,"a":31,"t":"Lorsqu'elle eut entendu leur fourberie, elle leur envoya [des invitations,] et prépara pour elles une collation; et elle remit à chacune d'elles un couteau. Puis elle dit: «Sors devant elles, (Joseph!)» - Lorsqu'elles le virent, elles l'admirèrent, se coupèrent les mains et dirent: «A Allah ne plaise! Ce n'est pas un être humain, ce n'est qu'un ange noble!»"},{"n":1628,"s":12,"a":32,"t":"Elle dit: «Voilà donc celui à propos duquel vous me blâmiez. J'ai essayé de le séduire mais il s'en défendit fermement. Or, s'il ne fait pas ce que je lui commande, il sera très certainement emprisonné et sera certes parmi les humiliés»."},{"n":1629,"s":12,"a":33,"t":"Il dit: «O mon Seigneur, la prison m'est préférable à ce à quoi elles m'invitent. Et si Tu n'écartes pas de moi leur ruse, je pencherai vers elles et serai du nombre des ignorants» [des pécheurs]."},{"n":1630,"s":12,"a":34,"t":"Son Seigneur l'exauça donc, et éloigna de lui leur ruse. C'est Lui, vraiment, qui est l'Audient et l'Omniscient."},{"n":1631,"s":12,"a":35,"t":"Puis, après qu'ils eurent vu les preuves (de son innocence), il leur sembla qu'ils devaient l'emprisonner pour un temps."},{"n":1632,"s":12,"a":36,"t":"Deux valets entrèrent avec lui en prison. L'un d'eux dit: «Je me voyais [en rêve] pressant du raisin...» Et l'autre dit: «Et moi, je me voyais portant sur ma tête du pain dont les oiseaux mangeaient. Apprends-nous l'interprétation (de nos rêves), nous te voyons au nombre des bienfaisants»."},{"n":1633,"s":12,"a":37,"t":"«La nourriture qui vous est attribuée ne vous parviendra point, dit-il, que je ne vous aie avisés de son interprétation [de votre nourriture] avant qu'elle ne vous arrive. Cela fait partie de ce que mon Seigneur m'a enseigné. Certes, j'ai abandonné la religion d'un peuple qui ne croit pas en Allah et qui nie la vie future»."},{"n":1634,"s":12,"a":38,"t":"Et j'ai suivi la religion de mes ancêtres, Abraham, Isaac et Jacob. Il ne nous convient pas d'associer à Allah quoi que ce soit. Ceci est une grâce d'Allah sur nous et sur tout le monde; mais la plupart des gens ne sont pas reconnaissants."},{"n":1635,"s":12,"a":39,"t":"O mes deux compagnons de prison! Qui est le meilleur: des Seigneurs éparpillés ou Allah, l'Unique, le Dominateur suprême?"},{"n":1636,"s":12,"a":40,"t":"Vous n'adorez, en dehors de Lui, que des noms que vous avez inventés, vous et vos ancêtres, et à l'appui desquels Allah n'a fait descendre aucune preuve. Le pouvoir n'appartient qu'à Allah. Il vous a commandé de n'adorer que Lui. Telle est la religion droite; mais la plupart des gens ne savent pas."},{"n":1637,"s":12,"a":41,"t":"O mes deux compagnons de prison! L'un de vous donnera du vin à boire à son maître; quant à l'autre, il sera crucifié, et les oiseaux mangeront de sa tête. L'affaire sur laquelle vous me consultez est déjà décidée.»"},{"n":1638,"s":12,"a":42,"t":"Et il dit à celui des deux dont il pensait qu'il serait délivré: «Parle de moi auprès de ton maître». Mais le Diable fit qu'il oublia de rappeler (le cas de Joseph) à son maître. Joseph resta donc en prison quelques années."},{"n":1639,"s":12,"a":43,"t":"Et le roi dit: «En vérité, je voyais (en rêve) sept vaches grasses mangées par sept maigres; et sept épis verts, et autant d'autres, secs. O conseil de notables, donnez-moi une explication de ma vision, si vous savez interpréter le rêve»."},{"n":1640,"s":12,"a":44,"t":"Ils dirent: «C'est un amas de rêves! Et nous ne savons pas interpréter les rêves!»"},{"n":1641,"s":12,"a":45,"t":"Or, celui des deux qui avait été délivré et qui, après quelque temps se rappela, dit: «Je vous en donnerai l'interprétation. Envoyez-moi donc»."},{"n":1642,"s":12,"a":46,"t":"«O toi, Joseph, le véridique! Eclaire-nous au sujet de sept vaches grasses que mangent sept très maigres, et sept épis verts et autant d'autres, secs, afin que je retourne aux gens et qu'ils sachent [l'interprétation exacte du rêve]»."},{"n":1643,"s":12,"a":47,"t":"Alors [Joseph dit]: «Vous sèmerez pendant sept années consécutives. Tout ce que vous aurez moissonné, laissez-le en épi, sauf le peu que vous consommerez."},{"n":1644,"s":12,"a":48,"t":"Viendront ensuite sept années de disette qui consommeront tout ce que vous aurez amassé pour elles sauf le peu que vous aurez réservé [comme semence]."},{"n":1645,"s":12,"a":49,"t":"Puis, viendra après cela une année où les gens seront secourus [par la pluie] et iront au pressoir.»"},{"n":1646,"s":12,"a":50,"t":"Et le roi dit: «Amenez-le moi». Puis, lorsque l'émissaire arriva auprès de lui, [Joseph] dit: «Retourne auprès de ton maître et demande-lui: «Quelle était la raison qui poussa les femmes à se couper les mains? Mon Seigneur connaît bien leur ruse»."},{"n":1647,"s":12,"a":51,"t":"Alors, [le roi leur] dit: «Qu'est-ce donc qui vous a poussées à essayer de séduire Joseph?» Elles dirent: «A Allah ne plaise! Nous ne connaissons rien de mauvais contre lui». Et la femme d'Al-'Azize dit: «Maintenant la vérité s'est manifestée. C'est moi qui ai voulu le séduire. Et c'est lui, vraiment, qui est du nombre des véridiques!»"},{"n":1648,"s":12,"a":52,"t":"«Cela afin qu'il sache que je ne l'ai pas trahi en son absence, et qu'en vérité Allah ne guide pas la ruse des traîtres."},{"n":1649,"s":12,"a":53,"t":"Je ne m'innocente cependant pas, car l'âme est très incitatrice au mal, à moins que mon Seigneur, par miséricorde, [ne la préserve du péché]. Mon Seigneur est certes Pardonneur et très Miséricordieux»."},{"n":1650,"s":12,"a":54,"t":"Et le roi dit: «Amenez-le moi: je me le réserve pour moi-même». Et lorsqu'il lui eut parlé, il dit: «Tu es dès aujourd'hui près de nous, en une position d'autorité et de confiance»."},{"n":1651,"s":12,"a":55,"t":"Et [Joseph] dit: «Assigne-moi les dépôts du territoire: je suis bon gardien et connaisseur»."},{"n":1652,"s":12,"a":56,"t":"Ainsi avons-nous affermi (l'autorité de) Joseph dans ce territoire et il s'y installait là où il le voulait. Nous touchons de Notre miséricorde qui Nous voulons et ne faisons pas perdre aux hommes de bien le mérite [de leurs œuvres]."},{"n":1653,"s":12,"a":57,"t":"Et la récompense de l'au-delà est meilleure pour ceux qui ont cru et ont pratiqué la piété."},{"n":1654,"s":12,"a":58,"t":"Et les frères de Joseph vinrent et entrèrent auprès de lui. Il les reconnut, mais eux ne le reconnurent pas."},{"n":1655,"s":12,"a":59,"t":"Et quand il leur eut fourni leur provision, il dit: «Amenez-moi un frère que vous avez de votre père. Ne voyez-vous pas que je donne la pleine mesure et que je suis le meilleur des hôtes?"},{"n":1656,"s":12,"a":60,"t":"Et si vous ne me l'amenez pas, alors il n'y aura plus de provision pour vous, chez moi; et vous ne m'approcherez plus»."},{"n":1657,"s":12,"a":61,"t":"Ils dirent: «Nous essayerons de persuader son père. Certes, nous le ferons»."},{"n":1658,"s":12,"a":62,"t":"Et il dit à ses serviteurs: «Remettez leurs marchandises dans leurs sacs: peut-être les reconnaîtront-ils quand ils seront de retour vers leur famille et peut-être qu'ils reviendront»."},{"n":1659,"s":12,"a":63,"t":"Et lorsqu'ils revinrent à leur père, ils dirent: «O notre père, il nous sera refusé [à l'avenir] de nous ravitailler [en grain]. Envoie donc avec nous notre frère, afin que nous obtenions des provisions. Nous le surveillerons bien»."},{"n":1660,"s":12,"a":64,"t":"Il dit: «Vais-je vous le confier comme, auparavant, je vous ai confié son frère? Mais Allah est le meilleur gardien, et Il est Le plus Miséricordieux des miséricordieux!»"},{"n":1661,"s":12,"a":65,"t":"Et lorsqu'ils ouvrirent leurs bagages, ils trouvèrent qu'on leur avait rendu leurs marchandises. Ils dirent: «O notre père. Que désirons-nous [de plus]? Voici que nos marchandises nous ont été rendues. Et ainsi nous approvisionnerons notre famille, nous veillerons à la sécurité de notre frère et nous nous ajouterons la charge d'un chameau et c'est une charge facile»."},{"n":1662,"s":12,"a":66,"t":"- Il dit: «Jamais je ne l'enverrai avec vous, jusqu'à ce que vous m'apportiez l'engagement formel au nom d'Allah que vous me le ramènerez à moins que vous ne soyez cernés». Lorsqu'ils lui eurent apporté l'engagement, il dit: «Allah est garant de ce que nous disons»."},{"n":1663,"s":12,"a":67,"t":"Et il dit: «O mes fils, n'entrez pas par une seule porte, mais entrez par portes séparées. Je ne peux cependant vous être d'aucune utilité contre les desseins d'Allah. La décision n'appartient qu'à Allah: en Lui je place ma confiance. Et que ceux qui placent leur confiance la placent en Lui»."},{"n":1664,"s":12,"a":68,"t":"Etant entrés comme leur père le leur avait commandé [cela] ne leur servit à rien contre (les décrets d') Allah. Ce n'était [au reste] qu'une précaution que Jacob avait jugé [de leur recommander]. Il avait pleine connaissance de ce que Nous lui avions enseigné. Mais la plupart des gens ne savent pas."},{"n":1665,"s":12,"a":69,"t":"Et quand ils furent entrés auprès de Joseph, [celui-ci] retint son frère auprès de lui en disant: «Je suis ton frère. Ne te chagrine donc pas pour ce qu'ils faisaient»."},{"n":1666,"s":12,"a":70,"t":"Puis, quand il leur eut fourni leurs provisions, il mit la coupe dans le sac de son frère. Ensuite un crieur annonça: «Caravaniers! vous êtes des voleurs»."},{"n":1667,"s":12,"a":71,"t":"Ils se retournèrent en disant: «Qu'avez-vous perdu?»"},{"n":1668,"s":12,"a":72,"t":"Ils répondirent: «Nous cherchons la grande coupe du roi. La charge d'un chameau à qui l'apportera et j'en suis garant»."},{"n":1669,"s":12,"a":73,"t":"«Par Allah, dirent-ils, vous savez certes que nous ne sommes pas venus pour semer la corruption sur le territoire et que nous ne sommes pas des voleurs»."},{"n":1670,"s":12,"a":74,"t":"- Quelle sera donc la sanction si vous êtes des menteurs? (dirent-ils)."},{"n":1671,"s":12,"a":75,"t":"Ils dirent: «La sanction infligée à celui dont les bagages de qui la coupe sera retrouvée est: [qu'il soit livré] lui-même [à titre d'esclave à la victime du vol]. C'est ainsi que nous punissons les malfaiteurs»."},{"n":1672,"s":12,"a":76,"t":"[Joseph] commença par les sacs des autres avant celui de son frère; puis il la fit sortir du sac de son frère. Ainsi suggérâmes-Nous cet artifice à Joseph. Car il ne pouvait pas se saisir de son frère, selon la justice du roi, à moins qu'Allah ne l'eût voulu. Nous élevons en rang qui Nous voulons. Et au-dessus de tout homme détenant la science il y a un savant [plus docte que lui]."},{"n":1673,"s":12,"a":77,"t":"Ils dirent: «S'il a commis un vol, un frère à lui auparavant a volé aussi.» Mais Joseph tint sa pensée secrète, et ne la leur dévoila pas. Il dit [en lui même]: «Votre position est bien pire encore! Et Allah connaît mieux ce que vous décrivez.»"},{"n":1674,"s":12,"a":78,"t":"- Ils dirent. «O Al-'Azize, il a un père très vieux; saisis-toi donc de l'un de nous, à sa place. Nous voyons que tu es vraiment du nombre des gens bienfaisants»."},{"n":1675,"s":12,"a":79,"t":"- Il dit: «Qu'Allah nous garde de prendre un autre que celui chez qui nous avons trouvé notre bien! Nous serions alors vraiment injustes.»"},{"n":1676,"s":12,"a":80,"t":"Puis, lorsqu'ils eurent perdu tout espoir [de ramener Benyamin] ils se concertèrent en secret. Leur aîné dit: «Ne savez-vous pas que votre père a pris de vous un engagement formel au nom d'Allah, et que déjà vous y avez manqué autrefois à propos de Joseph? Je ne quitterai point le territoire, jusqu'à ce que mon père me le permette ou qu'Allah juge en ma faveur, et Il est le meilleur des juges."},{"n":1677,"s":12,"a":81,"t":"Retournez à votre père et dites: «O notre père, ton fils a volé. Et nous n'attestons que ce que nous savons. Et nous n'étions nullement au courant de l'inconnu."},{"n":1678,"s":12,"a":82,"t":"Et interroge la ville où nous étions, ainsi que la caravane dans laquelle nous sommes arrivés. Nous disons réellement la vérité.»"},{"n":1679,"s":12,"a":83,"t":"Alors [Jacob] dit: Vos âmes plutôt vous ont inspiré [d'entreprendre] quelque chose!... Oh! belle patience. Il se peut qu'Allah me les ramènera tous les deux. Car c'est Lui l'Omniscient, le Sage»."},{"n":1680,"s":12,"a":84,"t":"Et il se détourna d'eux et dit: «Que mon chagrin est grand pour Joseph!» Et ses yeux blanchirent d'affliction. Et il était accablé."},{"n":1681,"s":12,"a":85,"t":"- Ils dirent: «Par Allah! Tu ne cesseras pas d'évoquer Joseph, jusqu'à ce que tu t'épuises ou que tu sois parmi les morts»."},{"n":1682,"s":12,"a":86,"t":"- Il dit: «Je ne me plains qu'à Allah de mon déchirement et de mon chagrin. Et, je sais de la part d'Allah, ce que vous ne savez pas."},{"n":1683,"s":12,"a":87,"t":"O mes fils! Partez et enquérez-vous de Joseph et de son frère. Et ne désespérez pas de la miséricorde d'Allah. Ce sont seulement les gens mécréants qui désespèrent de la miséricorde d'Allah»."},{"n":1684,"s":12,"a":88,"t":"Et lorsqu'ils s'introduisirent auprès de [Joseph,] ils dirent: «O al-'Azize, la famine nous a touchés, nous et notre famille; et nous venons avec une marchandise sans grande valeur. Donne-nous une pleine mesure, et fais-nous la charité. Certes, Allah récompense les charitables!»"},{"n":1685,"s":12,"a":89,"t":"- Il dit: «Savez-vous ce que vous avez fait de Joseph et de son frère alors que vous étiez ignorants? [injustes]»."},{"n":1686,"s":12,"a":90,"t":"- Ils dirent: «Est-ce que tu es... Certes, tu es Joseph!» - Il dit: «Je suis Joseph, et voici mon frère. Certes, Allah nous a favorisés. Quiconque craint et patiente... Et très certainement, Allah ne fait pas perdre la récompense des bienfaisants»."},{"n":1687,"s":12,"a":91,"t":"- Ils dirent: «Par Allah! Vraiment Allah t'a préféré à nous et nous avons été fautifs»."},{"n":1688,"s":12,"a":92,"t":"- Il dit: «Pas de récrimination contre vous aujourd'hui! Qu'Allah vous pardonne. C'est Lui Le plus Miséricordieux des miséricordieux."},{"n":1689,"s":12,"a":93,"t":"Emportez ma tunique que voici, et appliquez-la sur le visage de mon père: il recouvrera [aussitôt] la vue. Et amenez-moi toute votre famille»."},{"n":1690,"s":12,"a":94,"t":"- Et dès que la caravane franchit la frontière [de Canâan], leur père dit: «Je décèle, certes, l'odeur de Joseph, même si vous dites que je radote»."},{"n":1691,"s":12,"a":95,"t":"Ils Lui dirent: «Par Allah te voilà bien dans ton ancien égarement»."},{"n":1692,"s":12,"a":96,"t":"Puis quand arriva le porteur de bonne annonce, il l'appliqua [la tunique] sur le visage de Jacob. Celui-ci recouvra [aussitôt] la vue, et dit: «Ne vous ai-je pas dit que je sais, par Allah, ce que vous ne savez pas?»"},{"n":1693,"s":12,"a":97,"t":"- Ils dirent: «O notre père, implore pour nous la rémission de nos péchés. Nous étions vraiment fautifs»."},{"n":1694,"s":12,"a":98,"t":"- Il dit: «J'implorerai pour vous le pardon de mon Seigneur. Car c'est Lui le Pardonneur, le Très Miséricordieux»."},{"n":1695,"s":12,"a":99,"t":"Lorsqu'ils s'introduisirent auprès de Joseph, celui-ci accueillit ses père et mère, et leur dit: «Entrez en Egypte, en toute sécurité, si Allah le veut!»"},{"n":1696,"s":12,"a":100,"t":"Et il éleva ses parents sur le trône, et tous tombèrent devant lui, prosternés. Et il dit: «O mon père, voilà l'interprétation de mon rêve de jadis. Allah l'a bel et bien réalisé... Et Il m'a certainement fait du bien quand Il m'a fait sortir de prison et qu'Il vous a fait venir de la campagne, [du désert], après que le Diable ait suscité la discorde entre mes frères et moi. Mon Seigneur est plein de douceur pour ce qu'Il veut. Et c'est Lui l'Omniscient, le Sage."},{"n":1697,"s":12,"a":101,"t":"O mon Seigneur, Tu m'as donné du pouvoir et m'as enseigné l'interprétation des rêves. [C'est Toi Le] Créateur des cieux et de la terre, Tu es mon patron, ici-bas et dans l'au-delà. Fais-moi mourir en parfaite soumission et fais moi rejoindre les vertueux."},{"n":1698,"s":12,"a":102,"t":"Ce sont là des récits inconnus que Nous te révélons. Et tu n'étais pas auprès d'eux quand ils se mirent d'accord pour comploter."},{"n":1699,"s":12,"a":103,"t":"Et la plupart des gens ne sont pas croyants malgré ton désir ardent."},{"n":1700,"s":12,"a":104,"t":"Et tu ne leur demandes aucun salaire pour cela. Ce n'est là qu'un rappel adressé à l'univers."},{"n":1701,"s":12,"a":105,"t":"Et dans les cieux et sur la terre, que de signes auprès desquels les gens passent, en s'en détournant!"},{"n":1702,"s":12,"a":106,"t":"Et la plupart d'entre eux ne croient en Allah, qu'en lui donnant des associés."},{"n":1703,"s":12,"a":107,"t":"Est-ce qu'ils sont sûrs que le châtiment d'Allah ne viendra pas les couvrir ou que l'Heure ne leur viendra pas soudainement, sans qu'ils s'en rendent compte?"},{"n":1704,"s":12,"a":108,"t":"Dis: «Voici ma voie, j'appelle les gens à [la religion] d'Allah, moi et ceux qui me suivent, nous basant sur une preuve évidente. Gloire à Allah! Et je ne suis point du nombre des associateurs."},{"n":1705,"s":12,"a":109,"t":"Nous n'avons envoyé avant toi que des hommes originaires des cités, à qui Nous avons fait des révélations. [Ces gens là] n'ont-ils pas parcouru la terre et considéré quelle fut la fin de ceux qui ont vécu avant eux? La demeure de l'au-delà est assurément meilleure pour ceux qui craignent [Allah]. Ne raisonnerez-vous donc pas?"},{"n":1706,"s":12,"a":110,"t":"Quand les messagers faillirent perdre espoir (et que leurs adeptes) eurent pensé qu'ils étaient dupés voilà que vint à eux Notre secours. Et furent sauvés ceux que Nous voulûmes. Mais Notre rigueur ne saurait être détournée des gens criminels."},{"n":1707,"s":12,"a":111,"t":"Dans leurs récits il y a certes une leçon pour les gens doués d'intelligence. Ce n'est point là un récit fabriqué. C'est au contraire la confirmation de ce qui existait déjà avant lui, un exposé détaillé de toute chose, un guide et une miséricorde pour des gens qui croient."},{"n":1708,"s":13,"a":1,"t":"Alif, Lâm, Mîm, Râ. Voici les versets du Livre; et ce qui t'a été révélé par ton Seigneur est la vérité; mais la plupart des gens ne croient pas."},{"n":1709,"s":13,"a":2,"t":"Allah est Celui qui a élevé [bien haut] les cieux sans piliers visibles. Il S'est établi [istawâ] sur le Trône et a soumis le soleil et la lune, chacun poursuivant sa course vers un terme fixé. Il règle l'Ordre [de tout] et expose en détail les signes afin que vous ayez la certitude de la rencontre de votre Seigneur."},{"n":1710,"s":13,"a":3,"t":"Et c'est Lui qui a étendu la terre et y a placé montagnes et fleuves. Et de chaque espèce de fruits Il y établit deux éléments de couple. Il fait que la nuit couvre le jour. Voilà bien là des preuves pour des gens qui réfléchissent."},{"n":1711,"s":13,"a":4,"t":"Et sur la terre il y a des parcelles voisines les unes des autres, des jardins [plantés] de vignes, et des céréales et des palmiers, en touffes ou espacés, arrosés de la même eau, cependant Nous rendons supérieurs les uns aux autres quant au goût. Voilà bien là des preuves pour des gens qui raisonnent."},{"n":1712,"s":13,"a":5,"t":"Et si tu dois t'étonner, rien de plus étonnant que leurs dires: «Quand nous seront poussière, reviendrons-nous vraiment à une nouvelle création?» Ceux-là sont ceux qui ne croient pas en leur Seigneur. Et ce sont eux qui auront des jougs à leur cou. Et ce sont eux les gens du Feu, où ils demeureront éternellement."},{"n":1713,"s":13,"a":6,"t":"Et ils te demandent de hâter [la venue] du malheur plutôt que celle du bonheur. Certes, il s'est produit avant eux des châtiments exemplaires. Ton Seigneur est Détenteur du pardon pour les gens, malgré leurs méfaits. Et ton Seigneur est assurément dur en punition."},{"n":1714,"s":13,"a":7,"t":"Et ceux qui ont mécru disent: «Pourquoi n'a-t-on pas fait descendre sur celui-ci (Muhammad) un miracle venant de son Seigneur?» Tu n'es qu'un avertisseur, et à chaque peuple un guide."},{"n":1715,"s":13,"a":8,"t":"Allah sait ce que porte chaque femelle, et de combien la période de gestation dans la matrice est écourtée ou prolongée. Et toute chose a auprès de Lui sa mesure."},{"n":1716,"s":13,"a":9,"t":"Le Connaisseur de ce qui est caché et de ce qui est apparent, Le Grand, Le Sublime."},{"n":1717,"s":13,"a":10,"t":"Sont égaux pour lui, celui parmi vous qui tient secrète sa parole, et celui qui la divulgue, celui qui se cache la nuit comme celui qui se montre au grand jour."},{"n":1718,"s":13,"a":11,"t":"Il [l'homme] a par devant lui et derrière lui des Anges qui se relaient et qui veillent sur lui par ordre d'Allah. En vérité, Allah ne modifie point l'état d'un peuple, tant que les [individus qui le composent] ne modifient pas ce qui est en eux-mêmes. Et lorsqu'Allah veut [infliger] un mal à un peuple, nul ne peut le repousser: ils n'ont en dehors de Lui aucun protecteur."},{"n":1719,"s":13,"a":12,"t":"C'est lui qui vous fait voir l'éclair [qui vous inspire] crainte et espoir; et Il crée les nuages lourds."},{"n":1720,"s":13,"a":13,"t":"Le tonnerre Le glorifie par Sa louange, et aussi les Anges, sous l'effet de Sa crainte. Et Il lance les foudres dont Il atteint qui Il veut. Or ils disputent au sujet d'Allah alors qu'Il est redoutable en Sa force."},{"n":1721,"s":13,"a":14,"t":"A Lui l'appel de la Vérité! Ceux qu'ils invoquent en dehors de Lui ne leur répondent d'aucune façon; semblables à celui qui étend ses deux mains vers l'eau pour la porter à sa bouche, mais qui ne parvient jamais à l'atteindre. L'invocation des mécréants n'est que vanité."},{"n":1722,"s":13,"a":15,"t":"Et c'est à Allah que se prosternent, bon gré mal gré, tous ceux qui sont dans les cieux et sur la terre, ainsi que leurs ombres, au début et à la fin de la journée."},{"n":1723,"s":13,"a":16,"t":"Dis: «Qui est le Seigneur des cieux et de la terre?» Dis: «Allah». Dis: «Et prendrez-vous en dehors de Lui, des maîtres qui ne détiennent pour eux-mêmes ni bien ni mal?» Dis: «Sont-ils égaux, l'aveugle et celui qui voit? Ou sont-elles égales, les ténèbres et la lumière? Ou donnent-ils à Allah des associés qui créent comme Sa création au point que les deux créations se soient confondues à eux? Dis: «Allah est le Créateur de toute chose, et c'est Lui l'Unique, le Dominateur suprême»."},{"n":1724,"s":13,"a":17,"t":"Il a fait descendre une eau du ciel à laquelle des vallées servent de lit, selon leur grandeur. Le flot débordé a charrié une écume flottante; et semblable à celle-ci est [l'] écume provenant de ce qu'on porte à fusion, dans le feu pour [fabriquer] des bijoux et des ustensiles. Ainsi Allah représente en parabole la Vérité et le Faux: l'écume [du torrent et du métal fondu] s'en va, au rebut, tandis que [l'eau et les objets] utiles aux Hommes demeurent sur la terre. Ainsi Allah propose des paraboles."},{"n":1725,"s":13,"a":18,"t":"La meilleure [fin] est pour ceux qui répondent à [l'appel] de leur Seigneur. Et quant à ceux qui ne Lui répondent pas, s'ils avaient tout ce qui est sur la terre, et autant encore, ils l'offriraient en rançon. Ceux-là auront le détestable rendement de compte et l'Enfer sera leur refuge. Quel détestable lit de repos!"},{"n":1726,"s":13,"a":19,"t":"Celui qui sait que ce qui t'est révélé de la part de ton Seigneur est la vérité, est-il semblable à l'aveugle? Seuls les gens doués d'intelligence réfléchissent bien,"},{"n":1727,"s":13,"a":20,"t":"ceux qui remplissent leur engagement envers Allah et ne violent pas le pacte,"},{"n":1728,"s":13,"a":21,"t":"qui unissent ce qu'Allah a commandé d'unir, redoutent leur Seigneur et craignent une malheureuse reddition de compte,"},{"n":1729,"s":13,"a":22,"t":"et qui endurent dans la recherche de l'agrément d'Allah, accomplissent la Salât et dépensent (dans le bien), en secret et en public, de ce que Nous leur avons attribué, et repoussent le mal par le bien. A ceux-là, la bonne demeure finale,"},{"n":1730,"s":13,"a":23,"t":"les jardins d'Eden, où ils entreront, ainsi que tous ceux de leurs ascendants, conjoints et descendants, qui ont été de bons croyants. De chaque porte, les Anges entreront auprès d'eux:"},{"n":1731,"s":13,"a":24,"t":"- «Paix sur vous, pour ce que vous avez enduré!» - Comme est bonne votre demeure finale!»"},{"n":1732,"s":13,"a":25,"t":"[Mais] ceux qui violent leur pacte avec Allah après l'avoir engagé, et rompent ce qu'Allah a commandé d'unir et commettent le désordre sur terre, auront la malédiction et la mauvaise demeure."},{"n":1733,"s":13,"a":26,"t":"Allah étend largement Ses dons ou [les] restreint à qui Il veut. Ils se réjouissent de la vie sur terre, mais la vie d'ici-bas ne paraîtra que comme une jouissance éphémère en comparaison de l'au-delà."},{"n":1734,"s":13,"a":27,"t":"Ceux qui ont mécru disent: «Pourquoi n'a-t-on pas descendu sur lui (Muhammad) un miracle venant de son Seigneur?» Dis: «En vérité, Allah égare qui Il veut; et Il guide vers Lui celui qui se repent,"},{"n":1735,"s":13,"a":28,"t":"ceux qui ont cru, et dont les cœurs se tranquillisent à l'évocation d'Allah». Certes, c'est par l'évocation d'Allah que les cœurs se tranquillisent."},{"n":1736,"s":13,"a":29,"t":"Ceux qui croient et font de bonnes œuvres, auront le plus grand bien et aussi le plus bon retour."},{"n":1737,"s":13,"a":30,"t":"Ainsi Nous t'envoyons dans une communauté - que d'autres communautés ont précédée - pour que tu leur récites ce que Nous te révélons [le Coran], cependant qu'ils ne croient pas au Tout Miséricordieux. Dis: «C'est Lui mon Seigneur. Pas d'autre divinité à part Lui. En Lui je place ma confiance. Et à Lui je me repens»."},{"n":1738,"s":13,"a":31,"t":"S'il y avait un Coran à mettre les montagnes en marche, à fendre la terre ou à faire parler les morts (ce serait celui-ci). C'est plutôt à Allah le commandement tout entier. Les croyants ne savent-ils pas que, si Allah voulait, Il aurait dirigé tous les hommes vers le droit chemin. Cependant, ceux qui ne croient pas ne manqueront pas, pour prix de ce qu'ils font, d'être frappés par un cataclysme, ou [qu'un cataclysme] s'abattra près de leurs demeures jusqu'à ce que vienne la promesse d'Allah. Car Allah, ne manque pas à Sa promesse."},{"n":1739,"s":13,"a":32,"t":"On s'est certes moqué des messagers avant toi. Alors, J'ai donné un répit aux mécréants. Ensuite, Je les ai saisis. Et quel fut Mon châtiment!"},{"n":1740,"s":13,"a":33,"t":"Est-ce que Celui qui observe ce que chaque âme acquiert [est semblable aux associés?...] Et pourtant ils donnent des associés à Allah. Dis [leur:] «Nommez-les. Ou essayez-vous de Lui apprendre ce qu'Il ne connaît pas sur la terre? Ou avez-vous été simplement séduits par de faux noms?» En fait, on a embelli aux mécréants leur stratagème et on les a empêchés de prendre le droit chemin. Et quiconque Allah laisse égarer, n'a plus personne pour le guider."},{"n":1741,"s":13,"a":34,"t":"Un châtiment les atteindra dans la vie présente. Le châtiment de l'au-delà sera cependant plus écrasant et ils n'auront nul protecteur contre Allah."},{"n":1742,"s":13,"a":35,"t":"Tel est le paradis qui a été promis aux pieux: sous lequel coulent les ruisseaux; ses fruits sont perpétuels, ainsi que son ombrage. Voilà la fin de ceux qui pratiquent la piété, tandis que la fin des mécréants sera le Feu."},{"n":1743,"s":13,"a":36,"t":"Et ceux à qui Nous avons déjà donné le Livre se réjouissent de ce qu'on a fait descendre vers toi. Tandis que certaines factions en rejettent une partie. Dis: «Il m'a seulement été commandé d'adorer Allah et de ne rien Lui associer. C'est à Lui que j'appelle [les gens], Et c'est vers Lui que sera mon retour»."},{"n":1744,"s":13,"a":37,"t":"Ainsi l'avons-Nous fait descendre (le Coran) [sous forme] de loi en arabe. Et si tu suis leurs passions après ce que tu as reçu comme savoir, il n'y aura pour toi, contre Allah, ni allié ni protecteur."},{"n":1745,"s":13,"a":38,"t":"Et Nous avons certes envoyé avant toi des messagers, et leur avons donné des épouses et des descendants. Et il n'appartient pas à un Messager d'apporter un miracle, si ce n'est qu'avec la permission d'Allah. Chaque échéance a son terme prescrit."},{"n":1746,"s":13,"a":39,"t":"Allah efface ou confirme ce qu'Il veut et l'Ecriture primordiale est auprès de Lui."},{"n":1747,"s":13,"a":40,"t":"Que Nous te fassions voir une partie de ce dont Nous les menaçons, ou que Nous te fassions mourir (avant cela), ton devoir est seulement la communication du message, et le règlement de compte sera à Nous."},{"n":1748,"s":13,"a":41,"t":"Ne voient-ils pas que Nous frappons la terre et que Nous la réduisons de tous côtés? C'est Allah qui juge et personne ne peut s'opposer à Son jugement, et Il est prompt à régler les comptes."},{"n":1749,"s":13,"a":42,"t":"Certes ceux d'avant eux ont manigancé (contre leur Messager); le stratagème tout entier appartient à Allah. Il sait ce que chaque âme acquiert. Et les mécréants sauront bientôt à qui appartient la bonne demeure finale."},{"n":1750,"s":13,"a":43,"t":"Et ceux qui ne croient pas disent: «Tu n'es pas un Messager». Dis: «Allah suffit, comme témoin entre vous et moi, et ceux qui ont la connaissance du Livre (sont aussi témoins)»."},{"n":1751,"s":14,"a":1,"t":"Alif, Lâm, Râ. (Voici) un livre que nous avons fait descendre sur toi, afin que - par la permission de leur Seigneur - tu fasses sortir les gens des ténèbres vers la lumière, sur la voie du Tout Puissant, du Digne de louange."},{"n":1752,"s":14,"a":2,"t":"Allah, à qui appartient tout ce qui est dans les cieux et sur la terre. Et malheur aux mécréants, pour un dur châtiment [qu'ils subiront]."},{"n":1753,"s":14,"a":3,"t":"Ceux qui préfèrent la vie d'ici-bas à l'au-delà, obstruent [aux gens] le chemin d'Allah et cherchent à le rendre tortueux, ceux-là sont loin dans l'égarement."},{"n":1754,"s":14,"a":4,"t":"Et Nous n'avons envoyé de Messager qu'avec la langue de son peuple, afin de les éclairer. Allah égare qui Il veut et guide qui Il veut. Et, c'est Lui le Tout Puissant, le Sage."},{"n":1755,"s":14,"a":5,"t":"Nous avons certes, envoyé Moïse avec Nos miracles [en lui disant]: «Fais sortir ton peuple des ténèbres vers la lumière, et rappelle-leur les jours d'Allah». [Ses bienfaits]. Dans tout cela il y a des signes pour tout homme plein d'endurance et de reconnaissance."},{"n":1756,"s":14,"a":6,"t":"(Rappelle-toi) quand Moïse dit à son peuple: «Rappelez-vous le bienfait d'Allah sur vous quand Il vous sauva des gens de Pharaon qui vous infligeaient le pire châtiment. Ils massacraient vos fils et laissaient en vie vos filles. Il y avait là une dure épreuve de la part de votre Seigneur»,"},{"n":1757,"s":14,"a":7,"t":"Et lorsque votre Seigneur proclama: «Si vous êtes reconnaissants, très certainement J'augmenterai [Mes bienfaits] pour vous. Mais si vous êtes ingrats, Mon châtiment sera terrible»."},{"n":1758,"s":14,"a":8,"t":"Et Moïse dit: «Si vous êtes ingrats, vous ainsi que tous ceux qui sont sur terre, [sachez] qu'Allah Se suffit à Lui-même et qu'Il est digne de louange."},{"n":1759,"s":14,"a":9,"t":"Ne vous est-il pas parvenu le récit de ceux d'avant vous, du peuple de Noé, des `Aad, des Thamud et de ceux qui vécurent après eux, et que seul Allah connaît? Leurs messagers vinrent à eux avec des preuves, mais ils dirent, ramenant leurs mains à leurs bouches: «Nous ne croyons pas [au message] avec lequel vous avez été envoyés et nous sommes, au sujet de ce à quoi vous nous appelez, dans un doute vraiment troublant»."},{"n":1760,"s":14,"a":10,"t":"Leurs messagers dirent: «Y a-t-il un doute au sujet d'Allah, Créateur des cieux et de la terre, qui vous appelle pour vous pardonner une partie de vos péchés et vous donner un délai jusqu'à un terme fixé?» [Les mécréants] répondirent: «Vous n'êtes que des hommes comme nous. Vous voulez nous empêcher de ce que nos ancêtres adoraient. Apportez-nous donc une preuve évidente»."},{"n":1761,"s":14,"a":11,"t":"Leurs messagers leur dirent: «Certes, nous ne sommes que des humains comme vous. Mais Allah favorise qui Il veut parmi Ses serviteurs. Il ne nous appartient de vous apporter quelque preuve, que par la permission d'Allah. Et c'est en Allah que les croyants doivent placer leur confiance."},{"n":1762,"s":14,"a":12,"t":"Et qu'aurions-nous à ne pas placer notre confiance en Allah, alors qu'Il nous a guidés sur les sentiers [que nous devions suivre]? Nous endurerons sûrement la persécution que vous nous infligez. Et ceux qui ont confiance en Allah s'en remettent entièrement à Lui.»"},{"n":1763,"s":14,"a":13,"t":"Et ceux qui ont mécru dirent à leurs messagers: «Nous vous expulserons certainement de notre territoire, à moins que vous ne réintégriez notre religion!» Alors, leur Seigneur leur révéla: «Assurément Nous anéantirons les injustes,"},{"n":1764,"s":14,"a":14,"t":"et vous établirons dans le pays après eux. Cela est pour celui qui craint Ma présence et craint Ma menace»."},{"n":1765,"s":14,"a":15,"t":"Et ils demandèrent [à Allah] la victoire. Et tout tyran insolent fut déçu."},{"n":1766,"s":14,"a":16,"t":"L'Enfer est sa destination et il sera abreuvé d'une eau purulente"},{"n":1767,"s":14,"a":17,"t":"qu'il tentera d'avaler à petites gorgées. Mais c'est à peine s'il peut l'avaler. La mort lui viendra de toutes parts, mais il ne mourra pas; et il aura un châtiment terrible."},{"n":1768,"s":14,"a":18,"t":"Les œuvres de ceux qui ont mécru en leur Seigneur sont comparables à de la cendre violemment frappée par le vent, dans un jour de tempête. Ils ne tireront aucun profit de ce qu'ils ont acquis. C'est cela l'égarement profond."},{"n":1769,"s":14,"a":19,"t":"Ne vois-tu pas qu'Allah a créé les cieux et la terre pour une juste raison? S'Il voulait, Il vous ferait disparaître et ferait venir de nouvelles créatures,"},{"n":1770,"s":14,"a":20,"t":"et cela n'est nullement difficile pour Allah."},{"n":1771,"s":14,"a":21,"t":"Et tous comparaîtront devant Allah. Puis, les faibles diront à ceux qui s'enflaient d'orgueil: «Nous étions bien vos suiveurs. Pouvez-vous nous être de quelque utilité contre le châtiment d'Allah?» - Alors, les autres diront: «Si Allah nous avait guidés nous vous aurions certainement guidés. Il est indifférent pour nous de nous plaindre ou d'endurer; nous n'avons pas d'échappatoire»."},{"n":1772,"s":14,"a":22,"t":"Et quand tout sera accompli, le Diable dira: «Certes, Allah vous avait fait une promesse de vérité; tandis que moi, je vous ai fait une promesse que je n'ai pas tenue. Je n'avais aucune autorité sur vous si ce n'est que je vous ai appelés, et que vous m'avez répondu. Ne me faites donc pas de reproches; mais faites-en à vous-mêmes. Je ne vous suis d'aucun secours et vous ne m'êtes d'aucun secours. Je vous renie de m'avoir jadis associé [à Allah]». Certes, un châtiment douloureux attend les injustes [les associateurs]."},{"n":1773,"s":14,"a":23,"t":"Et on fera entrer ceux qui croient et font de bonnes œuvres, dans les jardins sous lesquels coulent les ruisseaux, pour y demeurer éternellement, par permission de leur Seigneur. Et là, leur salutation sera: «Salâm» (Paix)."},{"n":1774,"s":14,"a":24,"t":"N'as-tu pas vu comment Allah propose en parabole une bonne parole pareille à un bel arbre dont la racine est ferme et la ramure s'élançant dans le ciel?"},{"n":1775,"s":14,"a":25,"t":"Il donne à tout instant ses fruits, par la grâce de son Seigneur. Allah propose des paraboles à l'intention des gens afin qu'ils s'exhortent."},{"n":1776,"s":14,"a":26,"t":"Et une mauvaise parole est pareille à un mauvais arbre, déraciné de la surface de la terre et qui n'a point de stabilité."},{"n":1777,"s":14,"a":27,"t":"Allah affermit les croyants par une parole ferme, dans la vie présente et dans l'au-delà. Tandis qu'Il égare les injustes. Et Allah fait ce qu'Il veut."},{"n":1778,"s":14,"a":28,"t":"Ne vois-tu point ceux qui troquent les bienfaits d'Allah contre l'ingratitude et établissent leur peuple dans la demeure de la perdition"},{"n":1779,"s":14,"a":29,"t":"...l'Enfer, où ils brûleront? Et quel mauvais gîte!"},{"n":1780,"s":14,"a":30,"t":"Et ils ont donné à Allah des égaux afin d'égarer (les gens) de Son sentier. - Dis: «Jouissez [de cette vie] car votre destination sera le feu»."},{"n":1781,"s":14,"a":31,"t":"Dis à Mes serviteurs qui ont cru, qu'ils accomplissent la Salât et qu'ils dépensent [dans le bien] en secret et en public de ce que Nous leur avons attribué, avant que vienne le jour où il n'y a ni rachat ni amitié."},{"n":1782,"s":14,"a":32,"t":"Allah, c'est Lui qui a crée les cieux et la terre et qui, du ciel, a fait descendre l'eau; grâce à laquelle Il a produit des fruits pour vous nourrir. Il a soumis à votre service les vaisseaux qui, par Son ordre, voguent sur la mer. Et Il a soumis à votre service les rivières."},{"n":1783,"s":14,"a":33,"t":"Et pour vous, Il a assujetti le soleil et la lune à une perpétuelle révolution. Et Il vous a assujetti la nuit et le jour."},{"n":1784,"s":14,"a":34,"t":"Il vous a accordé de tout ce que vous Lui avez demandé. Et si vous comptiez les bienfaits d'Allah, vous ne sauriez les dénombrer. L'homme est vraiment très injuste, très ingrat."},{"n":1785,"s":14,"a":35,"t":"Et (rappelle-toi) quand Abraham dit: «O mon Seigneur, fais de cette cité un lieu sûr, et préserve-moi ainsi que mes enfants de l'adoration des idoles."},{"n":1786,"s":14,"a":36,"t":"O mon Seigneur, elles (les idoles) ont égaré beaucoup de gens. Quiconque me suit est des miens. Quant à celui qui me désobéit... c'est Toi, le Pardonneur, le Très Miséricordieux!"},{"n":1787,"s":14,"a":37,"t":"O notre Seigneur, j'ai établi une partie de ma descendance dans une vallée sans agriculture, près de Ta Maison sacrée [la Ka'ba], - ô notre Seigneur - afin qu'ils accomplissent la Salât. Fais donc que se penchent vers eux les cœurs d'une partie des gens. Et nourris-les de fruits. Peut-être seront-ils reconnaissants?"},{"n":1788,"s":14,"a":38,"t":"O notre Seigneur, Tu sais, vraiment, ce que nous cachons et ce que nous divulguons: - et rien n'échappe à Allah, ni sur terre, ni au ciel! -"},{"n":1789,"s":14,"a":39,"t":"Louange à Allah, qui en dépit de ma vieillesse, m'a donné Ismaël et Isaac. Certes, mon Seigneur entend bien les prières."},{"n":1790,"s":14,"a":40,"t":"O mon Seigneur! Fais que j'accomplisse assidûment la Salât ainsi qu'une partie de ma descendance; exauce ma prière, ô notre Seigneur!"},{"n":1791,"s":14,"a":41,"t":"O notre Seigneur! pardonne-moi, ainsi qu'à mes père et mère et aux croyants, le jour de la reddition des comptes»."},{"n":1792,"s":14,"a":42,"t":"Et ne pense point qu'Allah soit inattentif à ce que font les injustes. Ils leur accordera un délai jusqu'au jour ou leurs regards se figeront."},{"n":1793,"s":14,"a":43,"t":"Ils courront [suppliant], levant la tête, les yeux hagards et les cœurs vides."},{"n":1794,"s":14,"a":44,"t":"Et avertis les gens du jour où le châtiment les atteindra et ceux qui auront été injustes diront: «O notre Seigneur accorde-nous un court délai, nous répondrons à Ton appel et suivrons les messagers». - N'avez-vous pas juré auparavant que vous ne deviez jamais disparaître?"},{"n":1795,"s":14,"a":45,"t":"Et vous avez habité, les demeures de ceux qui s'étaient fait du tort à eux-mêmes. Il vous est apparu en toute évidence comment Nous les avions traité et Nous vous avons cité les exemples."},{"n":1796,"s":14,"a":46,"t":"Ils ont certes comploté. Or leur complot est (inscrit) auprès d'Allah même si leur complot était assez puissant pour faire disparaître les montagnes..."},{"n":1797,"s":14,"a":47,"t":"Ne pense point qu'Allah manque à Sa promesse envers Ses messagers. Certes Allah est Tout Puissant et Détenteur du pouvoir de punir,"},{"n":1798,"s":14,"a":48,"t":"au jour où la terre sera remplacée par une autre, de même que les cieux et où (les hommes) comparaîtront devant Allah, l'Unique, le Dominateur Suprême."},{"n":1799,"s":14,"a":49,"t":"Et ce jour-là, tu verras les coupables, enchaînés les uns aux autres,"},{"n":1800,"s":14,"a":50,"t":"leurs tuniques seront de goudron et le feu couvrira leurs visages."},{"n":1801,"s":14,"a":51,"t":"(Tout cela) afin qu'Allah rétribue chaque âme de ce qu'elle aura acquis. Certes Allah est prompt dans Ses comptes."},{"n":1802,"s":14,"a":52,"t":"Ceci est un message (le Coran) pour les gens afin qu'ils soient avertis, qu'ils sachent qu'Il n'est qu'un Dieu unique, et pour que les doués d'intelligence s'exhortent."},{"n":1803,"s":15,"a":1,"t":"Alif, Lâm, Râ. Voici les versets du Livre et d'une Lecture explicite."},{"n":1804,"s":15,"a":2,"t":"[Le Jour du Jugement Dernier] les mécréants voudraient avoir été Musulmans [soumis]."},{"n":1805,"s":15,"a":3,"t":"Laisse-les manger, jouir (un temps), et être distraits par l'espoir; car bientôt ils sauront!"},{"n":1806,"s":15,"a":4,"t":"Or Nous ne détruisons aucune cité sans qu'elle n'ait eu [un terme fixé en] une Ecriture connue."},{"n":1807,"s":15,"a":5,"t":"Nulle communauté ne devance son terme, ni ne le retarde."},{"n":1808,"s":15,"a":6,"t":"Et ils (les mecquois) disent: «O toi sur qui on a fait descendre le Coran, tu es certainement fou!"},{"n":1809,"s":15,"a":7,"t":"Pourquoi ne nous es-tu pas venu avec les Anges, si tu es du nombre des véridiques?»"},{"n":1810,"s":15,"a":8,"t":"Nous ne faisons descendre les Anges qu'avec la vérité; et alors, il ne leur sera pas accordé de répit [à ces impies]."},{"n":1811,"s":15,"a":9,"t":"En vérité c'est Nous qui avons fait descendre le Coran, et c'est Nous qui en sommes gardien."},{"n":1812,"s":15,"a":10,"t":"Et nous avons certes envoyé, avant toi, [des Messagers] parmi les peuples des Anciens."},{"n":1813,"s":15,"a":11,"t":"Et pas un Messager ne leur est venu sans qu'ils s'en soient moqués."},{"n":1814,"s":15,"a":12,"t":"C'est ainsi que Nous faisons pénétrer (la mécréance) dans les cœurs des coupables."},{"n":1815,"s":15,"a":13,"t":"Ils ne croiront pas en lui [le Messager ou le Coran] bien que se soit accompli le sort traditionnel des anciens."},{"n":1816,"s":15,"a":14,"t":"Et même si Nous ouvrions pour eux une porte du ciel, et qu'ils pussent y monter,"},{"n":1817,"s":15,"a":15,"t":"ils diraient: «Vraiment nos yeux sont voilés. Mais plutôt, nous sommes des gens ensorcelés»."},{"n":1818,"s":15,"a":16,"t":"Certes Nous avons placé dans le ciel des constellations et Nous l'avons embelli pour ceux qui regardent."},{"n":1819,"s":15,"a":17,"t":"Et Nous l'avons protégé contre tout diable banni."},{"n":1820,"s":15,"a":18,"t":"A moins que l'un d'eux parvienne subrepticement à écouter, une flamme brillante alors le poursuit."},{"n":1821,"s":15,"a":19,"t":"Et quant à la terre, Nous l'avons étalée et y avons placé des montagnes (immobiles) et y avons fait pousser toute chose harmonieusement proportionnée."},{"n":1822,"s":15,"a":20,"t":"Et Nous y avons placé des vivres pour vous, et (placé aussi pour vous) des êtres que vous ne nourrissez pas."},{"n":1823,"s":15,"a":21,"t":"Et il n'est rien dont Nous n'ayons les réserves et Nous ne le faisons descendre que dans une mesure déterminée."},{"n":1824,"s":15,"a":22,"t":"Et Nous envoyons les vents fécondants; et Nous faisons alors descendre du ciel une eau dont Nous vous abreuvons et que vous n'êtes pas en mesure de conserver."},{"n":1825,"s":15,"a":23,"t":"Et c'est bien Nous qui donnons la vie et donnons la mort, et c'est Nous qui sommes l'héritier [de tout]."},{"n":1826,"s":15,"a":24,"t":"Et Nous connaissons certes ceux qui parmi vous ont avancé et Nous connaissons ceux qui tardent encore."},{"n":1827,"s":15,"a":25,"t":"Certes, c'est ton Seigneur qui les rassemblera. Car c'est Lui le Sage, l'Omniscient."},{"n":1828,"s":15,"a":26,"t":"Nous créâmes l'homme d'une argile crissante, extraite d'une boue malléable."},{"n":1829,"s":15,"a":27,"t":"Et quant au djinn, Nous l'avions auparavant créé d'un feu d'une chaleur ardente."},{"n":1830,"s":15,"a":28,"t":"Et lorsque ton Seigneur dit aux Anges: «Je vais créer un homme d'argile crissante, extraite d'une boue malléable,"},{"n":1831,"s":15,"a":29,"t":"et dès que Je l'aurai harmonieusement formé et lui aurai insufflé Mon souffle de vie, jetez-vous alors, prosternés devant lui»."},{"n":1832,"s":15,"a":30,"t":"Alors, les Anges se prosternèrent tous ensemble,"},{"n":1833,"s":15,"a":31,"t":"excepté Iblis qui refusa d'être avec les prosternés."},{"n":1834,"s":15,"a":32,"t":"Alors [Allah] dit: «O Iblis, pourquoi n'es-tu pas au nombre des prosternés?»"},{"n":1835,"s":15,"a":33,"t":"Il dit: «Je ne puis me prosterner devant un homme que Tu as créé d'argile crissante, extraite d'une boue malléable»."},{"n":1836,"s":15,"a":34,"t":"- Et [Allah] dit: «Sors de là [du Paradis], car te voilà banni!"},{"n":1837,"s":15,"a":35,"t":"Et malédiction sur toi, jusqu'au Jour de la rétribution!»"},{"n":1838,"s":15,"a":36,"t":"- Il dit: «O mon Seigneur, donne-moi donc un délai jusqu'au jour où ils (les gens) seront ressuscités»."},{"n":1839,"s":15,"a":37,"t":"[Allah] dit: «tu es de ceux à qui ce délai est accordé,"},{"n":1840,"s":15,"a":38,"t":"jusqu'au jour de l'instant connu» [d'Allah]."},{"n":1841,"s":15,"a":39,"t":"- Il dit: «O mon Seigneur, parce que Tu m'as induit en erreur, eh bien je leur enjoliverai la vie sur terre et les égarerai tous,"},{"n":1842,"s":15,"a":40,"t":"à l'exception, parmi eux, de Tes serviteurs élus.»"},{"n":1843,"s":15,"a":41,"t":"- «[Allah] dit: voici une voie droite [qui mène] vers Moi."},{"n":1844,"s":15,"a":42,"t":"Sur Mes serviteurs tu n'auras aucune autorité, excepté sur celui qui te suivra parmi les dévoyés."},{"n":1845,"s":15,"a":43,"t":"Et l'Enfer sera sûrement leur lieu de rendez-vous à tous."},{"n":1846,"s":15,"a":44,"t":"Il a sept portes; et chaque porte en a sa part déterminée»."},{"n":1847,"s":15,"a":45,"t":"Certes, les pieux seront dans des jardins avec des sources."},{"n":1848,"s":15,"a":46,"t":"«Entrez-y en paix et en sécurité»."},{"n":1849,"s":15,"a":47,"t":"Et Nous aurons arraché toute rancune de leurs poitrines: et ils se sentiront frères, faisant face les uns aux autres sur des lits."},{"n":1850,"s":15,"a":48,"t":"Nulle fatigue ne les y touchera. Et on ne les en fera pas sortir."},{"n":1851,"s":15,"a":49,"t":"Informe Mes serviteurs que c'est Moi le Pardonneur, le Très Miséricordieux."},{"n":1852,"s":15,"a":50,"t":"et que Mon châtiment est certes le châtiment douloureux."},{"n":1853,"s":15,"a":51,"t":"Et informe-les au sujet des hôtes d'Abraham"},{"n":1854,"s":15,"a":52,"t":"Quand ils entrèrent chez lui et dirent: «Salâm» - Il dit: «Nous avons peur de vous»."},{"n":1855,"s":15,"a":53,"t":"Ils dirent: «N'aie pas peur! Nous t'annonçons une bonne nouvelle, [la naissance] d'un garçon plein de savoir»."},{"n":1856,"s":15,"a":54,"t":"Il dit: «M'annoncez-vous [cette nouvelle] alors que la vieillesse m'a touché? Que m'annoncez-vous donc?»"},{"n":1857,"s":15,"a":55,"t":"- Ils dirent: «Nous t'annonçons la vérité. Ne sois donc pas de ceux qui désespèrent»."},{"n":1858,"s":15,"a":56,"t":"- Il dit: «Et qui désespère de la miséricorde de son Seigneur, sinon les égarés?»"},{"n":1859,"s":15,"a":57,"t":"Et il [leur] dit: «Que voulez-vous, ô envoyés d'Allah?»"},{"n":1860,"s":15,"a":58,"t":"- Ils dirent: «En vérité, nous sommes envoyés à des gens criminels,"},{"n":1861,"s":15,"a":59,"t":"à l'exception de la famille de Lot que nous sauverons tous"},{"n":1862,"s":15,"a":60,"t":"sauf sa femme.«Nous (Allah) avions déterminé qu'elle sera du nombre des exterminés."},{"n":1863,"s":15,"a":61,"t":"Puis lorsque les envoyés vinrent auprès de la famille de Lot"},{"n":1864,"s":15,"a":62,"t":"celui-ci dit: «Vous êtes [pour moi] des gens inconnus»."},{"n":1865,"s":15,"a":63,"t":"- Ils dirent: «Nous sommes plutôt venus à toi en apportant (le châtiment) à propos duquel ils doutaient."},{"n":1866,"s":15,"a":64,"t":"Et nous venons à toi avec la vérité. Et nous sommes véridiques."},{"n":1867,"s":15,"a":65,"t":"Pars donc avec ta famille en parie de nuit et suis leurs arrières; et que nul d'entre vous ne se retourne. Et allez là où on vous le commande»."},{"n":1868,"s":15,"a":66,"t":"Et Nous lui annonçâmes cet ordre: que ces gens-là, au matin, seront anéantis jusqu'au dernier."},{"n":1869,"s":15,"a":67,"t":"Et les habitants de la ville (Sodome) vinrent [à lui] dans la joie."},{"n":1870,"s":15,"a":68,"t":"- Il dit: «Ceux-ci sont mes hôtes, ne me déshonorez donc pas."},{"n":1871,"s":15,"a":69,"t":"Et craignez Allah. Et ne me couvrez pas d'ignominie.»"},{"n":1872,"s":15,"a":70,"t":"Ils dirent: «Ne t'avions-nous pas interdit de [recevoir] du monde?»"},{"n":1873,"s":15,"a":71,"t":"Il dit: «Voici mes filles, si vous voulez faire [quelque chose]!»"},{"n":1874,"s":15,"a":72,"t":"Par ta vie! ils se confondaient dans leur délire."},{"n":1875,"s":15,"a":73,"t":"Alors, au lever du soleil le Cri (la catastrophe) les saisit."},{"n":1876,"s":15,"a":74,"t":"Et Nous renversâmes [la ville] de fond en comble et fîmes pleuvoir sur eux des pierres d'argile dure."},{"n":1877,"s":15,"a":75,"t":"Voilà vraiment des preuves, pour ceux qui savent observer!"},{"n":1878,"s":15,"a":76,"t":"Elle [cette ville] se trouvait sur un chemin connu de tous."},{"n":1879,"s":15,"a":77,"t":"Voilà vraiment une exhortation pour les croyants!"},{"n":1880,"s":15,"a":78,"t":"Et les habitants d'al-Aïka étaient [aussi] des injustes."},{"n":1881,"s":15,"a":79,"t":"Nous Nous sommes donc vengés d'eux. Et ces deux [cités], vraiment, sont sur une route bien évidente [que vous connaissez]."},{"n":1882,"s":15,"a":80,"t":"Certes, les gens d'al-Hijr ont traité de menteurs les messagers."},{"n":1883,"s":15,"a":81,"t":"Nous leur avons montré Nos miracles, mais ils s'en étaient détournés."},{"n":1884,"s":15,"a":82,"t":"Et ils taillaient des maisons dans les montagnes, vivant en sécurité."},{"n":1885,"s":15,"a":83,"t":"Puis, au matin, le Cri les saisit."},{"n":1886,"s":15,"a":84,"t":"Ce qu'ils avaient acquis ne leur a donc point profité."},{"n":1887,"s":15,"a":85,"t":"Et Nous n'avons créé les cieux et la terre, et ce qui est entre eux, que pour une juste raison. Et l'Heure [sans aucun doute] arrivera! Pardonne-[leur] donc d'un beau pardon."},{"n":1888,"s":15,"a":86,"t":"Ton Seigneur, c'est Lui vraiment le grand Créateur, l'Omniscient."},{"n":1889,"s":15,"a":87,"t":"Nous t'avons certes donné «les sept versets que l'on répète», ainsi que le Coran sublime."},{"n":1890,"s":15,"a":88,"t":"Ne regarde surtout pas avec envie les choses dont Nous avons donné jouissance temporaire à certains couples d'entre eux, ne t'afflige pas à leur sujet et abaisse ton aile pour les croyants."},{"n":1891,"s":15,"a":89,"t":"Et dis: «Je suis l'avertisseur évident» (d'un châtiment),"},{"n":1892,"s":15,"a":90,"t":"De même que Nous avons fait descendre [le châtiment] sur ceux qui ont juré (entre eux),"},{"n":1893,"s":15,"a":91,"t":"ceux qui ont fait du Coran des fractions diverses, (pour créer des doutes)."},{"n":1894,"s":15,"a":92,"t":"Par ton Seigneur! Nous les interrogerons tous"},{"n":1895,"s":15,"a":93,"t":"sur ce qu'ils œuvraient."},{"n":1896,"s":15,"a":94,"t":"Expose donc clairement ce qu'on t'a commandé et détourne-toi des associateurs."},{"n":1897,"s":15,"a":95,"t":"Nous t'avons effectivement défendu vis-à-vis des railleurs."},{"n":1898,"s":15,"a":96,"t":"Ceux qui associent à Allah une autre divinité. Mais ils sauront bientôt."},{"n":1899,"s":15,"a":97,"t":"Et Nous savons certes que ta poitrine se serre, à cause de ce qu'ils disent."},{"n":1900,"s":15,"a":98,"t":"Glorifie donc Ton Seigneur par Sa louange et sois de ceux qui se prosternent;"},{"n":1901,"s":15,"a":99,"t":"et adore ton Seigneur jusqu'à ce que te vienne la certitude (la mort)."},{"n":1902,"s":16,"a":1,"t":"L'ordre d'Allah arrive. Ne le hâtez donc pas. Gloire à Lui! Il est au-dessus de ce qu'on Lui associe."},{"n":1903,"s":16,"a":2,"t":"Il fait descendre, par Son ordre, les Anges, avec la révélation sur qui Il veut parmi Ses serviteurs: «Avertissez qu'il n'est d'autre divinité que Moi. Craignez-Moi donc»."},{"n":1904,"s":16,"a":3,"t":"Il a créé les cieux et la terre avec juste raison. Il transcende ce qu'on [Lui] associe."},{"n":1905,"s":16,"a":4,"t":"Il a créé l'homme d'une goutte de sperme; et voilà que l'homme devient un disputeur déclaré."},{"n":1906,"s":16,"a":5,"t":"Et les bestiaux, Il les a créés pour vous; vous en retirez des [vêtements] chauds ainsi que d'autres profits. Et vous en mangez aussi."},{"n":1907,"s":16,"a":6,"t":"Ils vous paraissent beaux quand vous les ramenez, le soir, et aussi le matin quand vous les lâchez pour le pâturage."},{"n":1908,"s":16,"a":7,"t":"Et ils portent vos fardeaux vers un pays que vous n'atteindriez qu'avec peine. Vraiment, votre Seigneur est Compatissant et Miséricordieux."},{"n":1909,"s":16,"a":8,"t":"Et les chevaux, les mulets et les ânes, pour que vous les montiez, et pour l'apparat. Et Il crée ce que vous ne savez pas."},{"n":1910,"s":16,"a":9,"t":"Il appartient à Allah [par Sa grâce, de montrer] le droit chemin car il en est qui s'en détachent. Or, s'Il voulait, Il vous guiderait tous."},{"n":1911,"s":16,"a":10,"t":"C'est Lui qui, du ciel, a fait descendre de l'eau qui vous sert de boisson et grâce à laquelle poussent des plantes dont vous nourrissez vos troupeaux."},{"n":1912,"s":16,"a":11,"t":"D'elle, Il fait pousser pour vous, les cultures, les oliviers, les palmiers, les vignes et aussi toutes sortes de fruits. Voilà bien là une preuve pour des gens qui réfléchissent."},{"n":1913,"s":16,"a":12,"t":"Pour vous, Il a assujetti la nuit et le jour; le soleil et la lune. Et à Son ordre sont assujetties les étoiles. Voilà bien là des preuves pour des gens qui raisonnent."},{"n":1914,"s":16,"a":13,"t":"Ce qu'Il a créé pour vous sur la terre a des couleurs diverses. Voilà bien là une preuve pour des gens qui se rappellent."},{"n":1915,"s":16,"a":14,"t":"Et c'est Lui qui a assujetti la mer afin que vous en mangiez une chair fraîche, et que vous en retiriez des parures que vous portez. Et tu vois les bateaux fendre la mer avec bruit, pour que vous partiez en quête de Sa grâce et afin que vous soyez reconnaissants."},{"n":1916,"s":16,"a":15,"t":"Et Il a implanté des montagnes immobiles dans la terre afin qu'elle ne branle pas en vous emportant avec elle de même que des rivières et des sentiers, pour que vous vous guidiez,"},{"n":1917,"s":16,"a":16,"t":"ainsi que des points de repère. Et au moyen des étoiles [les gens] se guident."},{"n":1918,"s":16,"a":17,"t":"Celui qui crée est-il semblable à celui qui ne crée rien? Ne vous souvenez-vous pas?"},{"n":1919,"s":16,"a":18,"t":"Et si vous comptez les bienfaits d'Allah, vous ne saurez pas les dénombrer. Car Allah est Pardonneur, et Miséricordieux."},{"n":1920,"s":16,"a":19,"t":"Et Allah sait ce que vous cachez et ce que vous divulguez."},{"n":1921,"s":16,"a":20,"t":"Et ceux qu'ils invoquent en dehors d'Allah ne créent rien, et ils sont eux-mêmes créés."},{"n":1922,"s":16,"a":21,"t":"Ils sont morts, et non pas vivants, et ils ne savent pas quand ils seront ressuscités."},{"n":1923,"s":16,"a":22,"t":"Votre Dieu est un Dieu unique. Ceux qui ne croient pas en l'au-delà leurs cœurs nient (l'unicité d'Allah) et ils sont remplis d'orgueil."},{"n":1924,"s":16,"a":23,"t":"Nul doute qu'Allah sait ce qu'ils cachent et ce qu'ils divulguent. Et assurément Il n'aime pas les orgueilleux."},{"n":1925,"s":16,"a":24,"t":"Et lorsqu'on leur dit: «Qu'est-ce que votre Seigneur a fait descendre?» Ils disent: «Des légendes anciennes!»"},{"n":1926,"s":16,"a":25,"t":"Qu'ils portent donc, au Jour de la Résurrection, tous les fardeaux de leurs propres œuvres ainsi qu'une partie des fardeaux de ceux qu'ils égarent, sans le savoir; combien est mauvais [le fardeau] qu'ils portent!"},{"n":1927,"s":16,"a":26,"t":"Ceux qui ont vécu avant eux, certes, ont comploté, mais Allah attaqua les bases mêmes de leur bâtisse. Le toit s'écroula au-dessus d'eux et le châtiment les surprit d'où ils ne l'avaient pas pressenti."},{"n":1928,"s":16,"a":27,"t":"Puis, le Jour de la Résurrection, Il les couvrira d'ignominie, et [leur] dira: «Où sont Mes associés pour lesquels vous combattiez?» - Ceux qui ont le savoir diront: «L'ignominie et le malheur tombent aujourd'hui sur les mécréants»."},{"n":1929,"s":16,"a":28,"t":"Ceux à qui les Anges ôtent la vie, alors qu'ils sont injustes envers eux-mêmes, se soumettront humiliés, (et diront): «Nous ne faisions pas de mal!» - «Mais, en fait, Allah sait bien ce que vous faisiez»."},{"n":1930,"s":16,"a":29,"t":"Entrez donc par les portes de l'Enfer pour y demeurer éternellement. Combien est mauvaise la demeure des orgueilleux!"},{"n":1931,"s":16,"a":30,"t":"Et on dira à ceux qui étaient pieux: «Qu'a fait descendre votre Seigneur?» Ils diront: «Un bien». Ceux qui font les bonnes œuvres auront un bien ici-bas; mais la demeure de l'au-delà est certes meilleure. Combien agréable sera la demeure des pieux!"},{"n":1932,"s":16,"a":31,"t":"Les jardins du séjour (éternel), où ils entreront et sous lesquels coulent les ruisseaux. Ils auront là ce qu'ils voudront; c'est ainsi qu'Allah récompense les pieux."},{"n":1933,"s":16,"a":32,"t":"Ceux dont les Anges reprennent l'âme - alors qu'ils sont bons - [les Anges leur] disent: «Paix sur vous! Entrez au Paradis, pour ce que vous faisiez»."},{"n":1934,"s":16,"a":33,"t":"[Les infidèles] attendent-ils que les Anges leur viennent, ou que survienne l'ordre de ton Seigneur? Ainsi agissaient les gens avant eux. Allah ne les a pas lésés; mais ils faisaient du tort à eux-mêmes."},{"n":1935,"s":16,"a":34,"t":"Les méfaits qu'ils accomplissaient les atteindront, et ce dont ils se moquaient les cernera de toutes parts."},{"n":1936,"s":16,"a":35,"t":"Et les associateurs dirent: «Si Allah avait voulu, nous n'aurions pas adoré quoi que ce soit en dehors de Lui, ni nous ni nos ancêtres; et nous n'aurions rien interdit qu'Il n'ait interdit Lui-même». Ainsi agissaient les gens avant eux. N'incombe-t-il aux messagers sinon de transmettre le message en toute clarté?"},{"n":1937,"s":16,"a":36,"t":"Nous avons envoyé dans chaque communauté un Messager, [pour leur dire]: «Adorez Allah et écartez-vous du Tâgût». Alors Allah en guida certains, mais il y en eut qui ont été destinés à l'égarement. Parcourez donc la terre, et regardez quelle fut la fin de ceux qui traitaient [Nos messagers] de menteurs."},{"n":1938,"s":16,"a":37,"t":"Même si tu désirais ardemment qu'ils soient guidés... [Sache] qu'Allah ne guide pas ceux qui s'égarent. Et ils n'auront pas de secoureurs."},{"n":1939,"s":16,"a":38,"t":"Et ils jurent par Allah en prononçant leurs serments les plus solennels: «Allah ne ressuscitera pas celui qui meurt». Bien au contraire! C'est une promesse véritable [de Sa part], mais la plupart des gens ne le savent pas."},{"n":1940,"s":16,"a":39,"t":"(Il les ressuscitera) afin qu'Il leur expose clairement ce en quoi ils divergeaient, et pour que ceux qui ont mécru sachent qu'ils ont été des menteurs."},{"n":1941,"s":16,"a":40,"t":"Quand Nous voulons une chose, Notre seule parole est: «Sois». Et, elle est."},{"n":1942,"s":16,"a":41,"t":"Et ceux qui, pour (la cause d') Allah, ont émigré après avoir subi des injustices, Nous les installerons dans une situation agréable dans la vie d'ici-bas. Et le salaire de la vie dernière sera plus grand encore s'ils savaient."},{"n":1943,"s":16,"a":42,"t":"Eux qui ont enduré et placé leur confiance en leur Seigneur."},{"n":1944,"s":16,"a":43,"t":"Nous n'avons envoyé, avant toi, que des hommes auxquels Nous avons fait des révélations. Demandez donc aux gens du rappel si vous ne savez pas."},{"n":1945,"s":16,"a":44,"t":"(Nous les avons envoyés) avec des preuves évidentes et des livres saints. Et vers toi, Nous avons fait descendre le Coran, pour que tu exposes clairement aux gens ce qu'on a fait descendre pour eux et afin qu'ils réfléchissent."},{"n":1946,"s":16,"a":45,"t":"Ceux qui complotaient des méfaits sont-ils à l'abri de ce qu'Allah les engloutisse en terre ou que leur vienne le châtiment d'où ils ne s'attendaient point?"},{"n":1947,"s":16,"a":46,"t":"Ou bien qu'Il les saisisse en pleine activité sans qu'ils puissent échapper (au châtiment d'Allah)."},{"n":1948,"s":16,"a":47,"t":"Ou bien qu'Il les saisisse en plein effroi? Mais vraiment, votre Seigneur est Compatissant et Miséricordieux."},{"n":1949,"s":16,"a":48,"t":"N'ont-ils point vu que les ombres de toute chose qu'Allah a créée s'allongent à droite et à gauche, en se prosternant devant Allah, en toute humilité?"},{"n":1950,"s":16,"a":49,"t":"Et c'est devant Allah que se prosterne tout être vivant dans les cieux, et sur la terre; ainsi que les Anges qui ne s'enflent pas d'orgueil."},{"n":1951,"s":16,"a":50,"t":"Ils craignent leur Seigneur, au-dessus d'eux, et font ce qui leur est commandé."},{"n":1952,"s":16,"a":51,"t":"Allah dit: «Ne prenez pas deux divinités. Il n'est qu'un Dieu unique. Donc, ne craignez que Moi»."},{"n":1953,"s":16,"a":52,"t":"C'est à Lui qu'appartient ce qui est dans les cieux et sur la terre; c'est à Lui que l'obéissance perpétuelle est due. Craindriez-vous donc, d'autres qu'Allah?"},{"n":1954,"s":16,"a":53,"t":"Et tout ce que vous avez comme bienfait provient d'Allah. Puis quand le malheur vous touche, c'est Lui que vous implorez à haute voix."},{"n":1955,"s":16,"a":54,"t":"Et une fois qu'Il a dissipé votre malheur, voilà qu'une partie d'entre vous se mettent à donner des associés à leur Seigneur,"},{"n":1956,"s":16,"a":55,"t":"méconnaissant ainsi ce que Nous leur avons donné. Jouissez donc [pour un temps!] Bientôt vous saurez!"},{"n":1957,"s":16,"a":56,"t":"Et ils assignent une partie [des biens] que Nous leur avons attribués à [des idoles] qu'ils ne connaissent pas. Par Allah! Vous serez certes interrogés sur ce que vous inventiez."},{"n":1958,"s":16,"a":57,"t":"Et ils assignent à Allah des filles. Gloire et pureté à Lui! Et à eux-mêmes, cependant, (ils assignent) ce qu'ils désirent (des fils)."},{"n":1959,"s":16,"a":58,"t":"Et lorsqu'on annonce à l'un d'eux une fille, son visage s'assombrit et une rage profonde [l'envahit]."},{"n":1960,"s":16,"a":59,"t":"Il se cache des gens, à cause du malheur qu'on lui a annoncé. Doit-il la garder malgré la honte ou l'enfouira-t-il dans la terre? Combien est mauvais leur jugement!"},{"n":1961,"s":16,"a":60,"t":"C'est à ceux qui ne croient pas en l'au-delà que revient le mauvais qualificatif (qu'ils ont attribué à Allah). Tandis qu'à Allah [Seul] est le qualificatif suprême. Et c'est Lui le Tout Puissant, le Sage."},{"n":1962,"s":16,"a":61,"t":"Si Allah s'en prenait aux gens pour leurs méfaits, Il ne laisserait sur cette terre aucun être vivant. Mais Il les renvoie jusqu'à un terme fixé. Puis, quand leur terme vient, ils ne peuvent ni le retarder d'une heure ni l'avancer."},{"n":1963,"s":16,"a":62,"t":"Et ils assignent à Allah ce qu'ils détestent [pour eux-mêmes]. Et leurs langues profèrent un mensonge quand ils disent que la plus belle récompense leur sera réservée. C'est le Feu, sans nul doute, qui leur sera réservé et ils y seront envoyés, les premiers."},{"n":1964,"s":16,"a":63,"t":"Par Allah! Nous avons effectivement envoyé (des messagers) à des communautés avant toi. Mais le Diable leur enjoliva ce qu'ils faisaient. C'est lui qui est, leur allié, aujourd'hui [dans ce monde]. Et ils auront un châtiment douloureux [dans l'au-delà]."},{"n":1965,"s":16,"a":64,"t":"Et Nous n'avons fait descendre sur toi le Livre qu'afin que tu leur montres clairement le motif de leur dissension, de même qu'un guide et une miséricorde pour des gens croyants."},{"n":1966,"s":16,"a":65,"t":"Allah a fait descendre du ciel une eau avec laquelle Il revivifie la terre après sa mort. Il y a vraiment là une preuve pour des gens qui entendent."},{"n":1967,"s":16,"a":66,"t":"Il y a certes un enseignement pour vous dans les bestiaux: Nous vous abreuvons de ce qui est dans leurs ventres, - [un produit] extrait du [mélange] des excréments [intestinaux] et du sang - un lait pur, délicieux pour les buveurs."},{"n":1968,"s":16,"a":67,"t":"Des fruits des palmiers et des vignes, vous retirez une boisson enivrante et un aliment excellent. Il y a vraiment là un signe pour des gens qui raisonnent."},{"n":1969,"s":16,"a":68,"t":"[Et voilà] ce que ton Seigneur révéla aux abeilles: «Prenez des demeures dans les montagnes, les arbres, et les treillages que [les hommes] font."},{"n":1970,"s":16,"a":69,"t":"Puis mangez de toute espèce de fruits, et suivez les sentiers de votre Seigneur, rendus faciles pour vous. De leur ventre, sort une liqueur, aux couleurs variées, dans laquelle il y a une guérison pour les gens. Il y a vraiment là une preuve pour des gens qui réfléchissent."},{"n":1971,"s":16,"a":70,"t":"Allah vous a créés! Puis Il vous fera mourir. Tel parmi vous sera reconduit jusqu'à l'âge le plus vil, de sorte qu'après avoir su, il arrive à ne plus rien savoir. Allah est, certes, Omniscient et Omnipotent."},{"n":1972,"s":16,"a":71,"t":"Allah a favorisé les uns d'entre vous par rapport aux autres dans [la répartition] de Ses dons. Ceux qui ont été favorisés ne sont nullement disposés à donner leur portion à ceux qu'ils possèdent de plein droit [esclaves] au point qu'ils y deviennent associés à part égale. Nieront-ils les bienfaits d'Allah?"},{"n":1973,"s":16,"a":72,"t":"Allah vous a fait à partir de vous-mêmes des épouses, et de vos épouses Il vous a donné des enfants et des petits-enfants. Et Il vous a attribué de bonnes choses. Croient-ils donc au faux et nient-ils le bienfait d'Allah?"},{"n":1974,"s":16,"a":73,"t":"Et ils adorent, en dehors d'Allah, ce qui ne peut leur procurer aucune nourriture des cieux et de la terre et qui n'est capable de rien."},{"n":1975,"s":16,"a":74,"t":"N'attribuez donc pas à Allah des semblables. Car Allah sait, tandis que vous ne savez pas."},{"n":1976,"s":16,"a":75,"t":"Allah propose en parabole un esclave appartenant [à son maître], dépourvu de tout pouvoir, et un homme à qui Nous avons accordé de Notre part une bonne attribution dont il dépense en secret et en public. [Ces deux hommes] sont-ils égaux? Louange à Allah! Mais la plupart d'entre eux ne savent pas."},{"n":1977,"s":16,"a":76,"t":"Et Allah propose en parabole deux hommes: l'un d'eux est muet, dépourvu de tout pouvoir et totalement à la charge de son maître; Quelque lieu où celui-ci l'envoie, il ne rapporte rien de bon; serait-il l'égal de celui qui ordonne la justice et qui est sur le droit chemin?"},{"n":1978,"s":16,"a":77,"t":"C'est à Allah qu'appartient l'inconnaissable des cieux et de la terre. Et l'ordre [concernant] l'Heure ne sera que comme un clin d'œil ou plus bref encore! Car Allah est, certes, Omnipotent."},{"n":1979,"s":16,"a":78,"t":"Et Allah vous a fait sortir des ventres de vos mères, dénués de tout savoir, et vous a donné l'ouïe, les yeux et les cœurs (l'intelligence), afin que vous; soyez reconnaissants."},{"n":1980,"s":16,"a":79,"t":"N'ont-ils pas vu les oiseaux assujettis [au vol] dans l'atmosphère du ciel sans que rien ne les retienne en dehors d'Allah? Il y a vraiment là des preuves pour des gens qui croient."},{"n":1981,"s":16,"a":80,"t":"Et Allah vous a fait de vos maisons une habitation, tout comme Il vous a procuré des maisons faites de peaux de bêtes que vous trouvez légères, le jour où vous vous déplacez et le jour où vous vous campez. De leur laine, de leur poil et de leur crin (Il vous a procuré) des effets et des objets dont vous jouissez pour un certain délai."},{"n":1982,"s":16,"a":81,"t":"Et de ce qu'Il a créé, Allah vous a procuré des ombres. Et Il vous a procuré des abris dans les montagnes. Et Il vous a procuré des vêtements qui vous protègent de la chaleur, ainsi que des vêtements [cuirasses, armures] qui vous protègent de votre propre violence. C'est ainsi qu'Allah parachève sur vous Son bienfait, peut-être que vous vous soumettez."},{"n":1983,"s":16,"a":82,"t":"S'ils se détournent... il ne t'incombe que la communication claire."},{"n":1984,"s":16,"a":83,"t":"Ils reconnaissent le bienfait d'Allah; puis, ils le renient. Et la plupart d'entre eux sont des ingrats."},{"n":1985,"s":16,"a":84,"t":"(Et rappelle-toi) le jour où de chaque communauté Nous susciterons un témoin, on ne permettra pas aux infidèles (de s'excuser), et on ne leur demandera pas de revenir [sur ce qui a provoqué la colère d'Allah]."},{"n":1986,"s":16,"a":85,"t":"Et quand les injustes verront le châtiment, on ne leur accordera ni allégement ni répit."},{"n":1987,"s":16,"a":86,"t":"Quand les associateurs verront ceux qu'ils associaient à Allah, ils diront: «O notre Seigneur, voilà nos divinités que nous invoquions en dehors de Toi». Mais [leurs associés] leur adresseront la parole: «Vous êtes assurément des menteurs»."},{"n":1988,"s":16,"a":87,"t":"Ils offriront ce jour-là à Allah la soumission, et ce qu'ils avaient inventé sera perdu pour eux."},{"n":1989,"s":16,"a":88,"t":"Ceux qui ne croyaient pas et obstruaient le sentier d'Allah, Nous leur ajouterons châtiment sur châtiment, pour la corruption qu'ils semaient (sur terre)."},{"n":1990,"s":16,"a":89,"t":"Et le jour où dans chaque communauté, Nous susciterons parmi eux-mêmes un témoin contre eux, Et Nous t'emmenerons [Muhammad] comme témoin contre ceux-ci. Et Nous avons fait descendre sur toi le Livre, comme un exposé explicite de toute chose, ainsi qu'un guide, une grâce et une bonne annonce aux Musulmans."},{"n":1991,"s":16,"a":90,"t":"Certes, Allah commande l'équité, la bienfaisance et l'assistance aux proches. Et Il interdit la turpitude, l'acte répréhensible et la rébellion. Il vous exhorte afin que vous vous souveniez."},{"n":1992,"s":16,"a":91,"t":"Soyez fidèles au pacte d'Allah après l'avoir contracté et ne violez pas vos serments après les avoir solennellement prêtés et avoir pris Allah comme garant [de votre bonne foi]. Vraiment Allah sait ce que vous faites!"},{"n":1993,"s":16,"a":92,"t":"Et ne faites pas comme celle qui défaisait brin par brin sa quenouille après l'avoir solidement filée, en prenant vos serments comme un moyen pour vous tromper les uns les autres, du fait que (vous avez trouvé) une communauté plus forte et plus nombreuse que l'autre. Allah ne fait, par là, que vous éprouver. Et, certes, Il vous montrera clairement, au Jour de la Résurrection ce sur quoi vous vous opposiez."},{"n":1994,"s":16,"a":93,"t":"Si Allah avait voulu, Il aurait certes fait de vous une seule communauté. Mais Il laisse s'égarer qui Il veut et guide qui Il veut. Et vous serez certes, interrogés sur ce que vous faisiez."},{"n":1995,"s":16,"a":94,"t":"Et ne prenez pas vos serments comme un moyen pour vous tromper les uns les autres, sinon [vos] pas glisseront après avoir été fermes, et vous goûterez le malheur pour avoir barré le sentier d'Allah. Et vous subirez un châtiment terrible."},{"n":1996,"s":16,"a":95,"t":"Et ne vendez pas à vil prix le pacte d'Allah. Ce qui se trouve auprès d'Allah est meilleur pour vous, si vous saviez!"},{"n":1997,"s":16,"a":96,"t":"Tout ce que vous possédez s'épuisera, tandis que ce qui est auprès d'Allah durera. Et Nous récompenserons ceux qui ont été constants en fonction du meilleur de ce qu'ils faisaient."},{"n":1998,"s":16,"a":97,"t":"Quiconque, mâle ou femelle, fait une bonne œuvre tout en étant croyant, Nous lui ferons vivre une bonne vie. Et Nous les récompenserons, certes, en fonction des meilleures de leurs actions."},{"n":1999,"s":16,"a":98,"t":"Lorsque tu lis le Coran, demande la protection d'Allah contre le Diable banni."},{"n":2000,"s":16,"a":99,"t":"Il n'a aucun pouvoir sur ceux qui croient et qui placent leur confiance en leur Seigneur."},{"n":2001,"s":16,"a":100,"t":"Il n'a de pouvoir que sur ceux qui le prennent pour allié et qui deviennent associateurs à cause de lui."},{"n":2002,"s":16,"a":101,"t":"Quand Nous remplaçons un verset par un autre - et Allah sait mieux ce qu'Il fait descendre - ils disent: «Tu n'es qu'un menteur». Mais la plupart d'entre eux ne savent pas."},{"n":2003,"s":16,"a":102,"t":"Dis: «C'est le Saint Esprit [Gabriel] qui l'a fait descendre de la part de ton Seigneur en toute vérité, afin de raffermir [la foi] de ceux qui croient, ainsi qu'un guide et une bonne annonce pour les Musulmans.»"},{"n":2004,"s":16,"a":103,"t":"Et Nous savons parfaitement qu'ils disent: «Ce n'est qu'un être humain qui lui enseigne (le Coran)». Or, la langue de celui auquel ils font allusion est étrangère [non arabe], et celle-ci est une langue arabe bien claire."},{"n":2005,"s":16,"a":104,"t":"Ceux qui ne croient pas aux versets d'Allah, Allah ne les guide pas. Et ils ont un châtiment douloureux."},{"n":2006,"s":16,"a":105,"t":"Seuls forgent le mensonge ceux qui ne croient pas aux versets d'Allah; et tels sont les menteurs."},{"n":2007,"s":16,"a":106,"t":"Quiconque a renié Allah après avoir cru... - sauf celui qui y a été contraint alors que son cœur demeure plein de la sérénité de la foi - mais ceux qui ouvrent délibérément leur cœur à la mécréance, ceux-là ont sur eux une colère d'Allah et ils ont un châtiment terrible."},{"n":2008,"s":16,"a":107,"t":"Il en est ainsi, parce qu'ils ont aimé la vie présente plus que l'au-delà. Et Allah, vraiment, ne guide pas les gens mécréants."},{"n":2009,"s":16,"a":108,"t":"Voilà ceux dont Allah a scellé les cœurs, l'ouïe, et les yeux. Ce sont eux les insouciants."},{"n":2010,"s":16,"a":109,"t":"Et nul doute que dans l'au-delà, ils seront les perdants."},{"n":2011,"s":16,"a":110,"t":"Quant à ceux qui ont émigré après avoir subi des épreuves, puis ont lutté et ont enduré, ton Seigneur après cela, est certes Pardonneur et Miséricordieux."},{"n":2012,"s":16,"a":111,"t":"(Rappelle-toi) le jour où chaque âme viendra, plaidant pour elle-même, et chaque âme sera pleinement rétribuée pour ce qu'elle aura œuvré sans qu'ils subissent la moindre injustice."},{"n":2013,"s":16,"a":112,"t":"Et Allah propose en parabole une ville: elle était en sécurité, tranquille; sa part de nourriture lui venait de partout en abondance. Puis elle se montra ingrate aux bienfaits d'Allah. Allah lui fit alors goûter la violence de la faim et de la peur [en punition] de ce qu'ils faisaient."},{"n":2014,"s":16,"a":113,"t":"En effet, un Messager des leurs est venu à eux, mais ils l'ont traité de menteur. Le châtiment, donc, les saisit parce qu'ils étaient injustes."},{"n":2015,"s":16,"a":114,"t":"Mangez donc de ce qu'Allah vous a attribué de licite et de bon. Et soyez reconnaissants pour les bienfaits d'Allah, si c'est Lui que vous adorez."},{"n":2016,"s":16,"a":115,"t":"Il vous a, en effet, interdit (la chair) de la bête morte, le sang, la chair de porc, et la bête sur laquelle un autre nom que celui d'Allah a été invoqué. Mais quiconque en mange sous contrainte, et n'est ni rebelle ni transgresseur, alors Allah est Pardonneur et Miséricordieux."},{"n":2017,"s":16,"a":116,"t":"Et ne dites pas, conformément aux mensonges proférés par vos langues: «Ceci est licite, et cela est illicite», pour forger le mensonge contre Allah. Certes, ceux qui forgent le mensonge contre Allah ne réussiront pas."},{"n":2018,"s":16,"a":117,"t":"Ce sera pour eux une piètre jouissance, mais un douloureux châtiment les attend."},{"n":2019,"s":16,"a":118,"t":"Aux Juifs, Nous avions interdit ce que Nous t'avons déjà relaté. Nous ne leur avons fait aucun tort; mais ils se faisaient du tort à eux-mêmes."},{"n":2020,"s":16,"a":119,"t":"Puis ton Seigneur envers ceux qui ont commis le mal par ignorance, et se sont par la suite repentis et ont amélioré leur conduite, ton Seigneur, après cela est certes Pardonneur et Miséricordieux."},{"n":2021,"s":16,"a":120,"t":"Abraham était un guide ('Umma) parfait. Il était soumis à Allah, voué exclusivement à Lui et il n'était point du nombre des associateurs."},{"n":2022,"s":16,"a":121,"t":"Il était reconnaissant pour Ses bienfaits et Allah l'avait élu et guidé vers un droit chemin."},{"n":2023,"s":16,"a":122,"t":"Nous lui avons donné une belle part ici-bas. Et il sera certes dans l'au-delà du nombre des gens de bien."},{"n":2024,"s":16,"a":123,"t":"Puis Nous t'avons révélé: «Suis la religion d'Abraham qui était voué exclusivement à Allah et n'était point du nombre des associateurs»."},{"n":2025,"s":16,"a":124,"t":"Le Sabbat n'a été imposé qu'à ceux qui divergeaient à son sujet. Au Jour de la Résurrection, ton Seigneur jugera certainement au sujet de ce dont ils divergeaient."},{"n":2026,"s":16,"a":125,"t":"Par la sagesse et la bonne exhortation appelle (les gens) au sentier de ton Seigneur. Et discute avec eux de la meilleure façon. Car c'est ton Seigneur qui connaît le mieux celui qui s'égare de Son sentier et c'est Lui qui connaît le mieux ceux qui sont bien guidés."},{"n":2027,"s":16,"a":126,"t":"Et si vous punissez, infligez [à l'agresseur] une punition égale au tort qu'il vous a fait. Et si vous endurez... cela est certes meilleur pour les endurants."},{"n":2028,"s":16,"a":127,"t":"Endure! Ton endurance [ne viendra] qu'avec (l'aide) d'Allah. Ne t'afflige pas pour eux. Et ne sois pas angoissé à cause de leurs complots."},{"n":2029,"s":16,"a":128,"t":"Certes, Allah est avec ceux qui [L'] ont craint avec piété et ceux qui sont bienfaisants."},{"n":2030,"s":17,"a":1,"t":"Gloire et Pureté à Celui qui de nuit, fit voyager Son serviteur [Muhammad], de la Mosquée Al-Harâm à la Mosquée Al-Aqsâ dont Nous avons béni l'alentour, afin de lui faire voir certaines de Nos merveilles. C'est Lui, vraiment, qui est l'Audient, le Clairvoyant."},{"n":2031,"s":17,"a":2,"t":"Et Nous avions donné à Moïse le Livre dont Nous avions fait un guide pour les Enfants d'Israël: «Ne prenez pas de protecteur en dehors de Moi»."},{"n":2032,"s":17,"a":3,"t":"[O vous], les descendants de ceux que Nous avons transportés dans l'arche avec Noé. Celui-ci était vraiment un serviteur fort reconnaissant."},{"n":2033,"s":17,"a":4,"t":"Nous avions décrété pour les Enfants d'Israël, (et annoncé) dans le Livre: «Par deux fois vous sèmerez la corruption sur terre et vous allez transgresser d'une façon excessive»."},{"n":2034,"s":17,"a":5,"t":"Lorsque vint l'accomplissement de la première de ces deux [prédictions,] Nous envoyâmes contre vous certains de Nos serviteurs doués d'une force terrible, qui pénétrèrent à l'intérieur des demeures. Et la prédiction fut accomplie."},{"n":2035,"s":17,"a":6,"t":"Ensuite, Nous vous donnâmes la revanche sur eux; et Nous vous renforçâmes en biens et en enfants. Et Nous vous fîmes [un peuple] plus nombreux:"},{"n":2036,"s":17,"a":7,"t":"«Si vous faites le bien; vous le faites à vous-mêmes; et si vous faites le mal, vous le faites à vous [aussi]». Puis, quand vint la dernière [prédiction,] ce fut pour qu'ils affligent vos visages et entrent dans la Mosquée comme ils y étaient entrés la première fois, et pour qu'ils détruisent complètement ce dont ils se sont emparés."},{"n":2037,"s":17,"a":8,"t":"Il se peut que votre Seigneur vous fasse miséricorde. Mais si vous récidivez, Nous récidiverons. Et Nous avons assigné l'Enfer comme camp de détention aux infidèles."},{"n":2038,"s":17,"a":9,"t":"Certes, ce Coran guide vers ce qu'il y a de plus droit, et il annonce aux croyants qui font de bonnes œuvres qu'ils auront une grande récompense,"},{"n":2039,"s":17,"a":10,"t":"et à ceux qui ne croient pas en l'au-delà, que Nous leur avons préparé un châtiment douloureux."},{"n":2040,"s":17,"a":11,"t":"L'homme appelle le mal comme il appelle le bien, car l'homme est très hâtif."},{"n":2041,"s":17,"a":12,"t":"Nous avons fait de la nuit et du jour deux signes, et Nous avons effacé le signe de la nuit, tandis que Nous avons rendu visible le signe du jour, pour que vous recherchiez des grâces de votre Seigneur, et que vous sachiez le nombre des années et le calcul du temps. Et Nous avons expliqué toute chose d'une manière détaillée."},{"n":2042,"s":17,"a":13,"t":"Et au cou de chaque homme, Nous avons attaché son œuvre. Et au Jour de la Résurrection, Nous lui sortirons un écrit qu'il trouvera déroulé:"},{"n":2043,"s":17,"a":14,"t":"«Lis ton écrit. Aujourd'hui, tu te suffis d'être ton propre comptable»."},{"n":2044,"s":17,"a":15,"t":"Quiconque prend le droit chemin ne le prend que pour lui-même; et quiconque s'égare, ne s'égare qu'à son propre détriment. Et nul ne portera le fardeau d'autrui. Et Nous n'avons jamais puni [un peuple] avant de [lui] avoir envoyé un Messager."},{"n":2045,"s":17,"a":16,"t":"Et quand Nous voulons détruire une cité, Nous ordonnons à ses gens opulents [d'obéir à Nos prescriptions], mais (au contraire) ils se livrent à la perversité. Alors la Parole prononcée contre elle se réalise, et Nous la détruisons entièrement."},{"n":2046,"s":17,"a":17,"t":"Que de générations avons-nous exterminées, après Noé! Et ton Seigneur suffit qu'Il soit Parfaitement Connaisseur et Clairvoyant sur les péchés de Ses serviteurs."},{"n":2047,"s":17,"a":18,"t":"Quiconque désire [la vie] immédiate, Nous nous hâtons de donner ce que Nous voulons, à qui Nous voulons. Puis, Nous lui assignons l'Enfer où il brûlera méprisé et repoussé."},{"n":2048,"s":17,"a":19,"t":"Et ceux qui recherchent l'au-delà et fournissent les efforts qui y mènent, tout en étant croyants... alors l'effort de ceux-là sera reconnu."},{"n":2049,"s":17,"a":20,"t":"Nous accordons abondamment à tous, ceux-ci comme ceux-là, des dons de ton Seigneur. Et les dons de ton Seigneur ne sont refusés [à personne]."},{"n":2050,"s":17,"a":21,"t":"Regarde comment Nous favorisons certains sur d'autres. Et dans l'au-delà, il y a des rangs plus élevés et plus privilégiés."},{"n":2051,"s":17,"a":22,"t":"N'assigne point à Allah d'autre divinité; sinon tu te trouveras méprisé et abandonné."},{"n":2052,"s":17,"a":23,"t":"Et ton Seigneur a décrété: «N'adorez que Lui; et (marquez) de la bonté envers les père et mère: si l'un d'eux ou tous deux doivent atteindre la vieillesse auprès de toi, alors ne leur dis point: «Fi!» et ne les brusque pas, mais adresse-leur des paroles respectueuses."},{"n":2053,"s":17,"a":24,"t":"et par miséricorde, abaisse pour eux l'aile de l'humilité, et dis: «O mon Seigneur, fais-leur, à tous deux, miséricorde comme ils m'ont élevé tout petit»."},{"n":2054,"s":17,"a":25,"t":"Votre Seigneur connaît mieux ce qu'il y a dans vos âmes. Si vous êtes bons, Il est certes Pardonneur pour ceux qui Lui reviennent se repentant."},{"n":2055,"s":17,"a":26,"t":"«Et donne au proche parent ce qui lui est dû ainsi qu'au pauvre et au voyageur (en détresse). Et ne gaspille pas indûment,"},{"n":2056,"s":17,"a":27,"t":"car les gaspilleurs sont les frères des diables; et le Diable est très ingrat envers son Seigneur."},{"n":2057,"s":17,"a":28,"t":"Si tu t'écartes d'eux à la recherche d'une miséricorde de Ton Seigneur, que tu espères, adresse-leur une parole bienveillante."},{"n":2058,"s":17,"a":29,"t":"Ne porte pas ta main enchaînée à ton cou [par avarice], et ne l'étend pas non plus trop largement, sinon tu te trouveras blâmé et chagriné."},{"n":2059,"s":17,"a":30,"t":"En vérité ton Seigneur étend Ses dons largement à qu'Il veut ou les accorde avec parcimonie. Il est, sur Ses serviteurs, Parfaitement Connaisseur et Clairvoyant."},{"n":2060,"s":17,"a":31,"t":"Et ne tuez pas vos enfants par crainte de pauvreté; c'est Nous qui attribuons leur subsistance, tout comme à vous. Les tuer, c'est vraiment, un énorme péché."},{"n":2061,"s":17,"a":32,"t":"Et n'approchez point la fornication. En vérité, c'est une turpitude et quel mauvais chemin!"},{"n":2062,"s":17,"a":33,"t":"Et, sauf en droit, ne tuez point la vie qu'Allah a rendu sacrée. Quiconque est tué injustement, alors Nous avons donné pouvoir à son proche [parent]. Que celui-ci ne commette pas d'excès dans le meurtre, car il est déjà assisté (par la loi)."},{"n":2063,"s":17,"a":34,"t":"Et n'approchez les biens de l'orphelin que de la façon la meilleure, jusqu'à ce qu'il atteigne sa majorité. Et remplissez l'engagement, car on sera interrogé au sujet des engagements."},{"n":2064,"s":17,"a":35,"t":"Et donnez la pleine mesure quand vous mesurez, et pesez avec une balance exacte. C'est mieux [pour vous] et le résultat en sera meilleur."},{"n":2065,"s":17,"a":36,"t":"Et ne poursuis pas ce dont tu n'as aucune connaissance. L'ouïe, la vue et le cœur: sur tout cela, en vérité, on sera interrogé."},{"n":2066,"s":17,"a":37,"t":"Et ne foule pas la terre avec orgueil: tu ne sauras jamais fendre la terre et tu ne pourras jamais atteindre la hauteur des montagnes!"},{"n":2067,"s":17,"a":38,"t":"Ce qui est mauvais en tout cela est détesté de ton Seigneur."},{"n":2068,"s":17,"a":39,"t":"Tout cela fait partie de ce que ton Seigneur t'a révélé de la Sagesse. N'assigne donc pas à Allah d'autre divinité, sinon tu seras jeté dans l'Enfer, blâmé et repoussé."},{"n":2069,"s":17,"a":40,"t":"Votre Seigneur, aurait-Il réservé exclusivement pour vous des fils, et Lui, aurait-Il pris pour Lui des filles parmi les Anges? Vous prononcez là une parole monstrueuse."},{"n":2070,"s":17,"a":41,"t":"Très certainement Nous avons exposé [tout ceci] dans ce Coran afin que [les gens] réfléchissent. Mais cela ne fait qu'augmenter leur répulsion."},{"n":2071,"s":17,"a":42,"t":"Dis: «S'il y avait des divinités avec Lui, comme ils le disent, elles auraient alors cherché un chemin [pour atteindre] le Détenteur du Trône»."},{"n":2072,"s":17,"a":43,"t":"Pureté à Lui! Il est plus haut et infiniment au-dessus de ce qu'ils disent!"},{"n":2073,"s":17,"a":44,"t":"Les sept cieux et la terre et ceux qui s'y trouvent, célèbrent Sa gloire. Et il n'existe rien qui ne célèbre Sa gloire et Ses louanges. Mais vous ne comprenez pas leur façon de Le glorifier. Certes c'est Lui qui est Indulgent et Pardonneur."},{"n":2074,"s":17,"a":45,"t":"Et quand tu lis le Coran, Nous plaçons, entre toi et ceux qui ne croient pas en l'au-delà, un voile invisible,"},{"n":2075,"s":17,"a":46,"t":"Nous avons mis des voiles sur leurs cœurs, de sorte qu'ils ne le comprennent pas: et dans leurs oreilles, une lourdeur. Et quand, dans le Coran, tu évoques Ton Seigneur l'Unique, ils tournent le dos par répulsion."},{"n":2076,"s":17,"a":47,"t":"Nous savons très bien ce qu'ils écoutent. Quand ils t'écoutent et qu'ils chuchotent entre eux, les injustes disent: «Vous ne suivez qu'un homme ensorcelé»."},{"n":2077,"s":17,"a":48,"t":"Vois ce à quoi ils te comparent! Ils s'égarent donc et sont incapables de trouver un chemin (vers la vérité)."},{"n":2078,"s":17,"a":49,"t":"Et ils disent: «Quand nous serons ossements et poussière, serons-nous ressuscités en une nouvelle création?»"},{"n":2079,"s":17,"a":50,"t":"Dis: «Soyez pierre ou fer."},{"n":2080,"s":17,"a":51,"t":"ou toute autre créature que vous puissiez concevoir.» Ils diront alors: «Qui donc nous fera revenir?» - Dis: «Celui qui vous a créés la première fois». Ils secoueront vers toi leurs têtes et diront: «Quand cela?» Dis: «Il se peut que ce soit proche."},{"n":2081,"s":17,"a":52,"t":"Le jour où Il vous appellera, vous Lui répondrez en Le glorifiant. Vous penserez cependant que vous n'êtes restés [sur terre] que peu de temps!»"},{"n":2082,"s":17,"a":53,"t":"Et dis à Mes serviteurs d'exprimer les meilleures paroles, car le Diable sème la discorde parmi eux. Le Diable est certes, pour l'homme, un ennemi déclaré."},{"n":2083,"s":17,"a":54,"t":"Votre Seigneur vous connaît mieux. S'Il veut, Il vous fera miséricorde, et s'Il veut, Il vous châtiera. Et Nous ne t'avons pas envoyé pour que tu sois leur protecteur."},{"n":2084,"s":17,"a":55,"t":"Et ton Seigneur est plus Connaisseur de ceux qui sont dans les cieux et sur la terre. Et parmi les prophètes, Nous avons donné à certains plus de faveurs qu'à d'autres. Et à David Nous avons donné le «Zabûr»."},{"n":2085,"s":17,"a":56,"t":"Dis: «Invoquez ceux que vous prétendez, (être des divinités) en dehors de Lui. Ils ne possèdent ni le moyen de dissiper votre malheur ni de le détourner."},{"n":2086,"s":17,"a":57,"t":"Ceux qu'ils invoquent, cherchent [eux-mêmes], à qui mieux, le moyen de se rapprocher le plus de leur Seigneur. Ils espèrent Sa miséricorde et craignent Son châtiment. Le châtiment de ton Seigneur est vraiment redouté."},{"n":2087,"s":17,"a":58,"t":"Il n'est point de cité [injuste] que Nous ne fassions périr avant le Jour de la Résurrection, ou que Nous ne punissions d'un dur châtiment. Cela est bien tracé dans le Livre [des décrets immuables]."},{"n":2088,"s":17,"a":59,"t":"Rien ne Nous empêche d'envoyer les miracles, si ce n'est que les Anciens les avaient traités de mensonges. Nous avions apporté aux Thamûd la chamelle qui était un [miracle] visible: mais ils lui firent du tort. En outre, Nous n'envoyons de miracles qu'à titre de menace."},{"n":2089,"s":17,"a":60,"t":"Et lorsque Nous te disions que ton Seigneur cerne tous les gens (par Sa puissance et Son savoir). Quant à la vision que Nous t'avons montrée, Nous ne l'avons faite que pour éprouver les gens, tout comme l'arbre maudit mentionné dans le Coran. Nous les menaçons, mais cela ne fait qu'augmenter leur grande transgression."},{"n":2090,"s":17,"a":61,"t":"Et lorsque Nous avons dit aux Anges: «Prosternez-vous devant Adam», ils se prosternèrent, à l'exception d'Iblis, qui dit: «Me prosternerai-je devant quelqu'un que Tu as créé d'argile?»"},{"n":2091,"s":17,"a":62,"t":"Il dit encore: «Vois-Tu? Celui que Tu as honoré au-dessus de moi, si Tu me donnais du répit jusqu'au Jour de la Résurrection, j'éprouverai, certes, sa descendance excepté un petit nombre [parmi eux]»."},{"n":2092,"s":17,"a":63,"t":"Et [Allah] dit: «Va-t-en! Quiconque d'entre eux te suivra... votre sanction sera l'Enfer, une ample rétribution."},{"n":2093,"s":17,"a":64,"t":"Excite, par ta voix, ceux d'entre eux que tu pourras, rassemble contre eux ta cavalerie et ton infanterie, associe-toi à eux dans leur biens et leurs enfants et fais-leur des promesses». Or, le Diable ne leur fait des promesses qu'en tromperie."},{"n":2094,"s":17,"a":65,"t":"Quant à Mes serviteurs, tu n'as aucun pouvoir sur eux». Et ton Seigneur suffit pour les protéger!"},{"n":2095,"s":17,"a":66,"t":"Votre Seigneur est Celui qui fait voguer le vaisseau pour vous en mer, afin que vous alliez à la recherche de quelque grâce de Sa part; Certes Il est Miséricordieux envers vous,"},{"n":2096,"s":17,"a":67,"t":"Et quand le mal vous touche en mer, ceux que vous invoquiez en dehors de Lui se perdent. Puis, quand Il vous sauve et vous ramène à terre, vous vous détournez. L'homme reste très ingrat!"},{"n":2097,"s":17,"a":68,"t":"Etes-vous à l'abri de ce qu'Il vous fasse engloutir par un pan de terre, ou qu'Il envoie contre vous un ouragan (avec pluie en pierres) et que vous ne trouverez alors aucun protecteur."},{"n":2098,"s":17,"a":69,"t":"Ou êtes-vous à l'abri de ce qu'Il vous y ramène (en mer) une autre fois, qu'Il déchaîne contre vous un de ces vents à tout casser, puis qu'Il vous fasse noyer à cause de votre mécréance? Et alors vous ne trouverez personne pour vous défendre contre Nous!"},{"n":2099,"s":17,"a":70,"t":"Certes, Nous avons honoré les fils d'Adam. Nous les avons transportés sur terre et sur mer, leur avons attribué de bonnes choses comme nourriture, et Nous les avons nettement préférés à plusieurs de Nos créatures."},{"n":2100,"s":17,"a":71,"t":"Le jour où Nous appellerons chaque groupement d'hommes par leur chef, ceux à qui on remettra leur livre dans la main droite liront leur livre (avec plaisir) et ne subiront pas la moindre injustice."},{"n":2101,"s":17,"a":72,"t":"Et quiconque aura été aveugle ici-bas, sera aveugle dans l'au-delà, et sera plus égaré [encore] par rapport à la bonne voie."},{"n":2102,"s":17,"a":73,"t":"Ils ont failli te détourner de ce que Nous t'avions révélé, [dans l'espoir] qu'à la place de ceci, tu inventes quelque chose d'autre et (l'imputes) à Nous. Et alors, ils t'auraient pris pour ami intime."},{"n":2103,"s":17,"a":74,"t":"Et si Nous ne t'avions pas raffermi, tu aurais bien failli t'incliner quelque peu vers eux."},{"n":2104,"s":17,"a":75,"t":"Alors, Nous t'aurions certes fait goûter le double [supplice] de la vie et le double [supplice] de la mort; et ensuite tu n'aurais pas trouvé de secoureur contre Nous."},{"n":2105,"s":17,"a":76,"t":"En vérité, ils ont failli t'inciter à fuir du pays pour t'en bannir. Mais dans ce cas, ils n'y seraient pas restés longtemps après toi."},{"n":2106,"s":17,"a":77,"t":"Telle fut la règle appliquée par Nous à Nos messagers que Nous avons envoyés avant toi. Et tu ne trouveras pas de changement en Notre règle."},{"n":2107,"s":17,"a":78,"t":"Accomplis la Salât au déclin du soleil jusqu'à l'obscurité de la nuit, et [fais] aussi la Lecture à l'aube, car la Lecture à l'aube a des témoins."},{"n":2108,"s":17,"a":79,"t":"Et de la nuit consacre une partie [avant l'aube] pour des Salât surérogatoires: afin que ton Seigneur te ressuscite en une position de gloire."},{"n":2109,"s":17,"a":80,"t":"Et dis: «O mon Seigneur, fais que j'entre par une entrée de vérité et que je sorte par une sortie de vérité; et accorde-moi de Ta part, un pouvoir bénéficiant de Ton secours»."},{"n":2110,"s":17,"a":81,"t":"Et dis: «La Vérité (l'Islam) est venue et l'Erreur a disparu. Car l'Erreur est destinée à disparaître»."},{"n":2111,"s":17,"a":82,"t":"Nous faisons descendre du Coran, ce qui est une guérison et une miséricorde pour les croyants. Cependant, cela ne fait qu'accroître la perdition des injustes."},{"n":2112,"s":17,"a":83,"t":"Et quand Nous comblons l'homme de bienfaits, il se détourne et se replie sur lui-même; et quand un mal le touche, le voilà profondément désespéré."},{"n":2113,"s":17,"a":84,"t":"Dis: «Chacun agit selon sa méthode, alors que votre Seigneur connaît mieux qui suit la meilleure voie»."},{"n":2114,"s":17,"a":85,"t":"Et ils t'interrogent au sujet de l'âme, - Dis: «L'âme relève de l'Ordre de mon Seigneur». Et on ne vous a donné que peu de connaissance."},{"n":2115,"s":17,"a":86,"t":"Si Nous voulons, Nous pouvons certes faire disparaître ce que Nous t'avons révélé; et tu n'y trouverais par la suite aucun défenseur contre Nous."},{"n":2116,"s":17,"a":87,"t":"Si ce n'est par une miséricorde de ton Seigneur, car en vérité Sa grâce sur toi est grande."},{"n":2117,"s":17,"a":88,"t":"Dis: «Même si les hommes et les djinns s'unissaient pour produire quelque chose de semblable à ce Coran, ils ne sauraient produire rien de semblable, même s'ils se soutenaient les uns les autres»."},{"n":2118,"s":17,"a":89,"t":"Et certes, Nous avons déployé pour les gens, dans ce Coran, toutes sortes d'exemples. Mais la plupart des gens s'obstinent à être mécréants."},{"n":2119,"s":17,"a":90,"t":"Et ils dirent: «Nous ne croirons pas en toi, jusqu'à ce que tu aies fait jaillir de terre, pour nous, une source;"},{"n":2120,"s":17,"a":91,"t":"ou que tu aies un jardin de palmiers et de vignes, entre lesquels tu feras jaillir des ruisseaux en abondance;"},{"n":2121,"s":17,"a":92,"t":"ou que tu fasses tomber sur nous, comme tu le prétends, le ciel en morceaux; ou que tu fasses venir Allah et les Anges en face de nous;"},{"n":2122,"s":17,"a":93,"t":"ou que tu aies une maison [garnie] d'ornements; ou que tu sois monté au ciel. Encore ne croirons-nous pas à ta montée au ciel, jusqu'à ce que tu fasses descendre sur nous un Livre que nous puissions lire». Dis-[leur]: «Gloire à mon Seigneur! Ne suis-je qu'un être humain-Messager?»"},{"n":2123,"s":17,"a":94,"t":"Et rien n'empêcha les gens de croire, quand le guide leur est parvenu, si ce n'est qu'ils disaient: «Allah envoie-t-Il un être humain-Messager?»"},{"n":2124,"s":17,"a":95,"t":"Dis: «S'il y avait sur terre des Anges marchant tranquillement, Nous aurions certes fait descendre sur eux du ciel un Ange-Messager»."},{"n":2125,"s":17,"a":96,"t":"Dis: «Allah suffit comme témoin entre vous et moi». Il est, sur Ses serviteurs, Parfaitement Connaisseur et Clairvoyant."},{"n":2126,"s":17,"a":97,"t":"Celui qu'Allah guide, c'est lui le bien-guidé et ceux qu'Il égare... tu ne leur trouveras jamais d'alliés en dehors de Lui et au Jour de la Résurrection, Nous les rassemblerons traînés sur leurs visages, aveugles, muets et sourds. L'Enfer sera leur demeure: chaque fois que son feu s'affaiblit, Nous leur accroîtrons la flamme ardente."},{"n":2127,"s":17,"a":98,"t":"Telle sera leur sanction parce qu'ils ne croient pas en Nos preuves et disent: «Quand nous serons ossements et poussière, serons-nous ressuscités en une nouvelle création?»"},{"n":2128,"s":17,"a":99,"t":"N'ont-ils pas vu qu'Allah qui a créé les cieux et la terre est capable de créer leurs pareils? Il leur a fixé un terme, sur lequel il n'y a aucun doute, mais les injustes s'obstinent dans leur mécréance."},{"n":2129,"s":17,"a":100,"t":"Dis: «Si c'était vous qui possédiez les trésors de la miséricorde de mon Seigneur, vous lésineriez, certes, de peur de les dépenser. Et l'homme est très avare!"},{"n":2130,"s":17,"a":101,"t":"Et certes, Nous donnâmes à Moïse neuf miracles évidents. Demande donc aux Enfants d'Israël, lorsqu'il leur vint et que Pharaon lui dit: «O Moïse, je pense que tu es ensorcelé»."},{"n":2131,"s":17,"a":102,"t":"Il dit: «Tu sais fort bien que ces choses [les miracles], seul le Seigneur des cieux et de la terre les a fait descendre comme autant de preuves illuminantes; et certes, O Pharaon, je te crois perdu»."},{"n":2132,"s":17,"a":103,"t":"[Pharaon] voulut donc les expulser du pays. Alors Nous les noyâmes tous, lui et ceux qui étaient avec lui."},{"n":2133,"s":17,"a":104,"t":"Et après lui, Nous dîmes aux Enfants d'Israël: «Habitez la terre». Puis, lorsque viendra la promesse de la (vie) dernière, Nous vous ferons venir en foule."},{"n":2134,"s":17,"a":105,"t":"Et c'est en toute vérité que Nous l'avons fait descendre (le Coran), et avec la vérité il est descendu, et Nous ne t'avons envoyé qu'en annonciateur et avertisseur."},{"n":2135,"s":17,"a":106,"t":"(Nous avons fait descendre) un Coran que Nous avons fragmenté, pour que tu le lises lentement aux gens. Et Nous l'avons fait descendre graduellement."},{"n":2136,"s":17,"a":107,"t":"Dis: «Croyez-y ou n'y croyez pas. Ceux à qui la connaissance a été donnée avant cela, lorsqu'on le leur récite, tombent, prosternés, le menton contre terre"},{"n":2137,"s":17,"a":108,"t":"et disent: «Gloire à notre Seigneur! La promesse de notre Seigneur est assurément accomplie»."},{"n":2138,"s":17,"a":109,"t":"Et ils tombent sur leur menton, pleurant, et cela augmente leur humilité."},{"n":2139,"s":17,"a":110,"t":"Dis: «Invoquez Allah, ou invoquez le Tout Miséricordieux. Quel que soit le nom par lequel vous l'appelez, Il a les plus beaux noms. Et dans ta Salât, ne récite pas à voix haute; et ne l'y abaisse pas trop, mais cherche le juste milieu entre les deux»."},{"n":2140,"s":17,"a":111,"t":"Et dis: «Louange à Allah qui ne S'est jamais attribué d'enfant, qui n'a point d'associé en la royauté et qui n'a jamais eu de protecteur de l'humiliation». Et proclame hautement Sa grandeur."},{"n":2141,"s":18,"a":1,"t":"Louange à Allah qui a fait descendre sur Son serviteur (Muhammad), le Livre, et n'y a point introduit de tortuosité (ambiguité)!"},{"n":2142,"s":18,"a":2,"t":"[Un Livre] d'une parfaite droiture pour avertir d'une sévère punition venant de Sa part et pour annoncer aux croyants qui font de bonnes œuvres qu'il y aura pour eux une belle récompense."},{"n":2143,"s":18,"a":3,"t":"où ils demeureront éternellement,"},{"n":2144,"s":18,"a":4,"t":"et pour avertir ceux qui disent: «Allah S'est attribué un enfant.»"},{"n":2145,"s":18,"a":5,"t":"Ni eux ni leurs ancêtres n'en savent rien. Quelle monstrueuse parole que celle qui sort de leurs bouches! Ce qu'ils disent n'est que mensonge."},{"n":2146,"s":18,"a":6,"t":"Tu vas peut-être te consumer de chagrin parce qu'ils se détournent de toi et ne croient pas en ce discours!"},{"n":2147,"s":18,"a":7,"t":"Nous avons placé ce qu'il y a sur la terre pour l'embellir, afin d'éprouver (les hommes et afin de savoir) qui d'entre eux sont les meilleurs dans leurs actions."},{"n":2148,"s":18,"a":8,"t":"Puis, Nous allons sûrement transformer sa surface en un sol aride."},{"n":2149,"s":18,"a":9,"t":"Penses-tu que les gens de la Caverne et d'ar-Raquîm ont constitué une chose extraordinaire d'entre Nos prodiges?"},{"n":2150,"s":18,"a":10,"t":"Quand les jeunes gens se furent réfugiés dans la caverne, ils dirent: «O notre Seigneur, donne-nous de Ta part une miséricorde; et assure nous la droiture dans tout ce qui nous concerne»."},{"n":2151,"s":18,"a":11,"t":"Alors, Nous avons assourdi leurs oreilles, dans la caverne pendant de nombreuses années."},{"n":2152,"s":18,"a":12,"t":"Ensuite, Nous les avons ressuscités, afin de savoir lequel des deux groupes saurait le mieux calculer la durée exacte de leur séjour."},{"n":2153,"s":18,"a":13,"t":"Nous allons te raconter leur récit en toute vérité. Ce sont des jeunes gens qui croyaient en leur Seigneur; et Nous leur avons accordé les plus grands moyens de se diriger [dans la bonne voie]."},{"n":2154,"s":18,"a":14,"t":"Nous avons fortifié leurs cœurs lorsqu'ils s'étaient levés pour dire: «Notre Seigneur est le Seigneur des cieux et de la terre: jamais nous n'invoquerons de divinité en dehors de Lui, sans quoi, nous transgresserions dans nos paroles."},{"n":2155,"s":18,"a":15,"t":"Voilà que nos concitoyens ont adopté en dehors de Lui des divinités. Que n'apportent-ils sur elles une preuve évidente? Quel pire injuste, donc que celui qui invente un mensonge contre Allah?"},{"n":2156,"s":18,"a":16,"t":"Et quand vous vous serez séparés d'eux et de ce qu'ils adorent en dehors d'Allah, réfugiez-vous donc dans la caverne: votre Seigneur répandra de Sa miséricorde sur vous et disposera pour vous un adoucissement à votre sort."},{"n":2157,"s":18,"a":17,"t":"Tu aurais vu le soleil, quand il se lève, s'écarter de leur caverne vers la droite, et quand il se couche, passer à leur gauche, tandis qu'eux-mêmes sont là dans une partie spacieuse (de la caverne)... Cela est une des merveilles d'Allah. Celui qu'Allah guide, c'est lui le bien-guidé. Et quiconque Il égare, tu ne trouveras alors pour lui aucun allié pour le mettre sur la bonne voie."},{"n":2158,"s":18,"a":18,"t":"Et tu les aurais cru éveillés, alors qu'ils dorment. Et Nous les tournons sur le côté droit et sur le côté gauche, tandis que leur chien est à l'entrée, pattes étendues. Si tu les avais aperçus, certes tu leur aurais tourné le dos en fuyant; et tu aurais été assurément rempli d'effroi devant eux."},{"n":2159,"s":18,"a":19,"t":"Et c'est ainsi que Nous les ressuscitâmes, afin qu'ils s'interrogent entre eux. L'un parmi eux dit: «Combien de temps avez-vous demeuré là?» Ils dirent: «Nous avons demeuré un jour ou une partie d'un jour». D'autres dirent: «Votre Seigneur sait mieux combien [de temps] vous y avez demeuré. Envoyez donc l'un de vous à la ville avec votre argent que voici, pour qu'il voie quel aliment est le plus pur et qu'il vous en apporte de quoi vous nourrir. Qu'il agisse avec tact; et qu'il ne donne l'éveil à personne sur vous."},{"n":2160,"s":18,"a":20,"t":"Si jamais ils vous attrapent, ils vous lapideront ou vous feront retourner à leur religion, et vous ne réussirez alors plus jamais»."},{"n":2161,"s":18,"a":21,"t":"Et c'est ainsi que Nous fîmes qu'ils furent découverts, afin qu'ils [les gens de la cité] sachent que la promesse d'Allah est vérité et qu'il n'y ait point de doute au sujet de l'Heure. Aussi se disputèrent-ils à leur sujet et déclarèrent-ils: «Construisez sur eux un édifice. Leur Seigneur les connaît mieux». Mais ceux qui l'emportèrent [dans la discussion] dirent: «Elevons sur eux un sanctuaire»."},{"n":2162,"s":18,"a":22,"t":"Ils diront: «ils étaient trois et le quatrième était leur chien». Et ils diront en conjecturant sur leur mystère qu'ils étaient cinq, le sixième étant leur chien et ils diront: «sept, le huitième étant leur chien». Dis: «Mon Seigneur connaît mieux leur nombre. Il n'en est que peu qui le savent». Ne discute à leur sujet que d'une façon apparente et ne consulte personne en ce qui les concerne."},{"n":2163,"s":18,"a":23,"t":"Et ne dis jamais, à propos d'une chose: «Je la ferai sûrement demain»,"},{"n":2164,"s":18,"a":24,"t":"sans ajouter: «Si Allah le veut», et invoque ton Seigneur quand tu oublies et dis: «Je souhaite que mon Seigneur me guide et me mène plus près de ce qui est correct»."},{"n":2165,"s":18,"a":25,"t":"Or, ils demeurèrent dans leur caverne trois cents ans et en ajoutèrent neuf (années)."},{"n":2166,"s":18,"a":26,"t":"Dis: «Allah sait mieux combien de temps ils demeurèrent là. A Lui appartient l'Inconnaissable des cieux et de la terre. Comme Il est Voyant et Audient! Ils n'ont aucun allié en dehors de Lui et Il n'associe personne à Son commandement."},{"n":2167,"s":18,"a":27,"t":"Et récite ce qui t'a été révélé du Livre de ton Seigneur. Nul ne peut changer Ses paroles. Et tu ne trouveras, en dehors de Lui, aucun refuge."},{"n":2168,"s":18,"a":28,"t":"Fais preuve de patience [en restant] avec ceux qui invoquent leur Seigneur matin et soir, désirant Sa Face. Et que tes yeux ne se détachent point d'eux, en cherchant (le faux) brillant de la vie sur terre. Et n'obéis pas à celui dont Nous avons rendu le cœur inattentif à Notre Rappel, qui poursuit sa passion et dont le comportement est outrancier."},{"n":2169,"s":18,"a":29,"t":"Et dis: «La vérité émane de votre Seigneur». Quiconque le veut, qu'il croie, quiconque le veut qu'il mécroie». Nous avons préparé pour les injustes un Feu dont les flammes les cernent. Et s'ils implorent à boire on les abreuvera d'une eau comme du métal fondu brûlant les visages. Quelle mauvaise boisson et quelle détestable demeure!"},{"n":2170,"s":18,"a":30,"t":"Ceux qui croient et font de bonnes œuvres... vraiment Nous ne laissons pas perdre la récompense de celui qui fait le bien."},{"n":2171,"s":18,"a":31,"t":"Voilà ceux qui auront les jardins du séjour (éternel) sous lesquels coulent les ruisseaux. Ils y seront parés de bracelets d'or et se vêtiront d'habits verts de soie fine et de brocart, accoudés sur des divans (bien ornés). Quelle bonne récompense et quelle belle demeure!"},{"n":2172,"s":18,"a":32,"t":"Donne-leur l'exemple de deux hommes: à l'un d'eux Nous avons assigné deux jardins de vignes que Nous avons entourés de palmiers et Nous avons mis entre les deux jardins des champs cultivés."},{"n":2173,"s":18,"a":33,"t":"Les deux jardins produisaient leur récolte sans jamais manquer. Et Nous avons fait jaillir entre eux un ruisseau."},{"n":2174,"s":18,"a":34,"t":"Et il avait des fruits et dit alors à son compagnon avec qui il conversait: «Je possède plus de biens que toi, et je suis plus puissant que toi grâce à mon clan»."},{"n":2175,"s":18,"a":35,"t":"Il entra dans son jardin coupable envers lui-même [par sa mécréance]; il dit: «Je ne pense pas que ceci puisse jamais périr,"},{"n":2176,"s":18,"a":36,"t":"et je ne pense pas que l'Heure viendra. Et si on me ramène vers mon Seigneur, je trouverai certes meilleur lieu de retour que ce jardin."},{"n":2177,"s":18,"a":37,"t":"Son compagnon lui dit, tout en conversant avec lui: «Serais-tu mécréant envers Celui qui t'a créé de terre, puis de sperme et enfin t'a façonné en homme?"},{"n":2178,"s":18,"a":38,"t":"Quant à moi, c'est Allah qui est mon Seigneur; et je n'associe personne à mon Seigneur."},{"n":2179,"s":18,"a":39,"t":"En entrant dans ton jardin, que ne dis-tu: «Telle est la volonté (et la grâce) d'Allah! Il n'y a de puissance que par Allah». Si tu me vois moins pourvu que toi en biens et en enfants,"},{"n":2180,"s":18,"a":40,"t":"il se peut que mon Seigneur, bientôt, me donne quelque chose de meilleur que ton jardin, qu'Il envoie sur [ce dernier], du ciel, quelque calamité, et que son sol devienne glissant,"},{"n":2181,"s":18,"a":41,"t":"ou que son eau tarisse de sorte que tu ne puisses plus la retrouver»."},{"n":2182,"s":18,"a":42,"t":"Et sa récolte fut détruite et il se mit alors à se tordre les deux mains à cause de ce qu'il y avait dépensé, cependant que ses treilles étaient complètement ravagées. Et il disait: «Que je souhaite n'avoir associé personne à mon Seigneur!»"},{"n":2183,"s":18,"a":43,"t":"Il n'eut aucun groupe de gens pour le secourir contre (la punition) d'Allah. Et il ne put se secourir lui-même."},{"n":2184,"s":18,"a":44,"t":"En l'occurrence, la souveraine protection appartient à Allah, le Vrai. Il accorde la meilleure récompense et le meilleur résultat."},{"n":2185,"s":18,"a":45,"t":"Et propose-leur l'exemple de la vie ici-bas. Elle est semblable à une eau que Nous faisons descendre du ciel; la végétation de la terre se mélange à elle. Puis elle devient de l'herbe desséchée que les vents dispersent. Allah est certes Puissant en toutes choses!"},{"n":2186,"s":18,"a":46,"t":"Les biens et les enfants sont l'ornement de la vie de ce monde. Cependant, les bonnes œuvres qui persistent ont auprès de ton Seigneur une meilleure récompense et [suscitent] une belle espérance."},{"n":2187,"s":18,"a":47,"t":"Le jour où Nous ferons marcher les montagnes et où tu verras la terre nivelée (comme une plaine) et Nous les rassemblerons sans en omettre un seul."},{"n":2188,"s":18,"a":48,"t":"Et ils seront présentés en rangs devant ton Seigneur. «Vous voilà venus à Nous comme Nous vous avons créés la première fois. Pourtant vous prétendiez que Nous ne remplirions pas Nos promesses»."},{"n":2189,"s":18,"a":49,"t":"Et on déposera le livre (de chacun). Alors tu verras les criminels, effrayés à cause de ce qu'il y a dedans, dire: «Malheur à nous, qu'a donc ce livre à n'omettre de mentionner ni péché véniel ni péché capital?» Et ils trouveront devant eux tout ce qu'ils ont œuvré. Et ton Seigneur ne fait du tort à personne."},{"n":2190,"s":18,"a":50,"t":"Et lorsque nous dîmes aux Anges: «Prosternez-vous devant Adam», ils se prosternèrent, excepté Iblis [Satan] qui était du nombre des djinns et qui se révolta contre le commandement de son Seigneur. Allez-vous cependant le prendre, ainsi que sa descendance, pour alliés en dehors de Moi, alors qu'ils vous sont ennemis? Quel mauvais échange pour les injustes!"},{"n":2191,"s":18,"a":51,"t":"Je ne les ai pas pris comme témoins de la création des cieux et de la terre, ni de la création de leurs propres personnes. Et Je n'ai pas pris comme aides ceux qui égarent."},{"n":2192,"s":18,"a":52,"t":"Et le jour où Il dira: «Appelez ceux que vous prétendiez être Mes associés». Ils les invoqueront; mais eux ne leur répondront pas, Nous aurons placé entre eux une vallée de perdition."},{"n":2193,"s":18,"a":53,"t":"Et les criminels verront le Feu. Ils seront alors convaincus qu'ils y tomberont et n'en trouveront pas d'échappatoire."},{"n":2194,"s":18,"a":54,"t":"Et assurément, Nous avons déployé pour les gens, dans ce Coran, toutes sortes d'exemples. L'homme cependant, est de tous les êtres le plus grand disputeur."},{"n":2195,"s":18,"a":55,"t":"Qu'est-ce qui a donc empêché les gens de croire, lorsque le guide leur est venu, ainsi que de demander pardon à leur Seigneur, si ce n'est qu'ils veulent subir le sort des Anciens, ou se trouver face à face avec le châtiment."},{"n":2196,"s":18,"a":56,"t":"Et Nous n'envoyons des messagers que pour annoncer la bonne nouvelle et avertir. Et ceux qui ont mécru disputent avec de faux arguments, afin d'infirmer la vérité et prennent en raillerie Mes versets (le Coran) ainsi que ce (châtiment) dont on les a avertis."},{"n":2197,"s":18,"a":57,"t":"Quel pire injuste que celui à qui on a rappelé les versets de son Seigneur et qui en détourna le dos en oubliant ce que ses deux mains ont commis? Nous avons placé des voiles sur leurs cœurs, de sorte qu'ils ne comprennent pas (le Coran), et mis une lourdeur dans leurs oreilles. Même si tu les appelles vers la bonne voie, jamais ils ne pourront donc se guider."},{"n":2198,"s":18,"a":58,"t":"Et ton Seigneur est le Pardonneur, le Détenteur de la miséricorde. S'Il s'en prenait à eux pour ce qu'ils ont acquis, Il leur hâterait certes le châtiment. Mais il y a pour eux un terme fixé (pour l'accomplissement des menaces) contre lequel ils ne trouveront aucun refuge."},{"n":2199,"s":18,"a":59,"t":"Et voilà les villes que Nous avons fait périr quand leurs peuples commirent des injustices et Nous avons fixé un rendez-vous pour leur destruction."},{"n":2200,"s":18,"a":60,"t":"(Rappelle-toi) quand Moïse dit à son valet: «Je n'arrêterai pas avant d'avoir atteint le confluent des deux mers, dussé-je marcher de longues années»."},{"n":2201,"s":18,"a":61,"t":"Puis, lorsque tous deux eurent atteint le confluent, Ils oublièrent leur poisson qui prit alors librement son chemin dans la mer."},{"n":2202,"s":18,"a":62,"t":"Puis, lorsque tous deux eurent dépassé [cet endroit,] il dit à son valet: «Apporte-nous notre déjeuner: nous avons rencontré de la fatigue dans notre présent voyage»."},{"n":2203,"s":18,"a":63,"t":"[Le valet lui] dit: «Quand nous avons pris refuge près du rocher, vois-tu, j'ai oublié le poisson - le Diable seul m'a fait oublier de (te) le rappeler - et il a curieusement pris son chemin dans la mer»."},{"n":2204,"s":18,"a":64,"t":"[Moïse] dit: «Voilà ce que nous cherchions». Puis, ils retournèrent sur leurs pas, suivant leurs traces."},{"n":2205,"s":18,"a":65,"t":"Ils trouvèrent l'un de Nos serviteurs à qui Nous avions donné une grâce, de Notre part, et à qui Nous avions enseigné une science émanant de Nous."},{"n":2206,"s":18,"a":66,"t":"Moïse lui dit: «Puis-je te suivre, à la condition que tu m'apprennes de ce qu'on t'a appris concernant une bonne direction?»"},{"n":2207,"s":18,"a":67,"t":"[L'autre] dit: «Vraiment, tu ne pourras jamais être patient avec moi."},{"n":2208,"s":18,"a":68,"t":"Comment endurerais-tu sur des choses que tu n'embrasses pas par ta connaissance?»"},{"n":2209,"s":18,"a":69,"t":"[Moïse] lui dit: «Si Allah veut, tu me trouveras patient; et je ne désobéirai à aucun de tes ordres»."},{"n":2210,"s":18,"a":70,"t":"«Si tu me suis, dit [l'autre,] ne m'interroge sur rien tant que je ne t'en aurai pas fait mention»."},{"n":2211,"s":18,"a":71,"t":"Alors les deux partirent. Et après qu'ils furent montés sur un bateau, l'homme y fit une brèche. [Moïse] lui dit: «Est-ce pour noyer ses occupants que tu l'as ébréché? Tu as commis, certes, une chose monstrueuse!»"},{"n":2212,"s":18,"a":72,"t":"[L'autre] répondit: «N'ai-je pas dit que tu ne pourrais pas garder patience en ma compagnie?»"},{"n":2213,"s":18,"a":73,"t":"«Ne t'en prends pas à moi, dit [Moïse,] pour un oubli de ma part; et ne m'impose pas de grande difficulté dans mon affaire»."},{"n":2214,"s":18,"a":74,"t":"Puis ils partirent tous deux; et quand ils eurent rencontré un enfant, [l'homme] le tua. Alors [Moïse] lui dit: «As-tu tué un être innocent, qui n'a tué personne? Tu as commis certes, une chose affreuse!»"},{"n":2215,"s":18,"a":75,"t":"[L'autre] lui dit: «Ne t'ai je pas dit que tu ne pourrais pas garder patience en ma compagnie?»"},{"n":2216,"s":18,"a":76,"t":"«Si, après cela, je t'interroge sur quoi que ce soit, dit [Moïse], alors ne m'accompagne plus. Tu seras alors excusé de te séparer de moi»."},{"n":2217,"s":18,"a":77,"t":"Ils partirent donc tous deux; et quand ils furent arrivés à un village habité, ils demandèrent à manger à ses habitants; mais ceux-ci refusèrent de leur donner l'hospitalité. Ensuite, ils y trouvèrent un mur sur le point de s'écrouler. L'homme le redressa. Alors [Moïse] lui dit: «Si tu voulais, tu aurais bien pu réclamer pour cela un salaire»."},{"n":2218,"s":18,"a":78,"t":"«Ceci [marque] la séparation entre toi et moi, dit [l'homme,] Je vais t'apprendre l'interprétation de ce que tu n'as pu supporter avec patience."},{"n":2219,"s":18,"a":79,"t":"Pour ce qui est du bateau, il appartenait à des pauvres gens qui travaillaient en mer. Je voulais donc le rendre défectueux, car il y avait derrière eux un roi qui saisissait de force tout bateau."},{"n":2220,"s":18,"a":80,"t":"Quant au garçon, ses père et mère étaient des croyants; nous avons craint qu'il ne leur imposât la rébellion et la mécréance."},{"n":2221,"s":18,"a":81,"t":"Nous avons donc voulu que leur Seigneur leur accordât en échange un autre plus pur et plus affectueux."},{"n":2222,"s":18,"a":82,"t":"Et quant au mur, il appartenait à deux garçons orphelins de la ville, et il y avait dessous un trésor à eux; et leur père était un homme vertueux. Ton Seigneur a donc voulu que tous deux atteignent leur maturité et qu'ils extraient, [eux-mêmes] leur trésor, par une miséricorde de ton Seigneur. Je ne l'ai d'ailleurs pas fait de mon propre chef. Voilà l'interprétation de ce que tu n'as pas pu endurer avec patience»."},{"n":2223,"s":18,"a":83,"t":"Et ils t'interrogent sur Dûl-Qarnayn. Dis: «Je vais vous en citer quelque fait mémorable»."},{"n":2224,"s":18,"a":84,"t":"Vraiment, Nous avons affermi sa puissance sur terre, et Nous lui avons donné libre voie à toute chose."},{"n":2225,"s":18,"a":85,"t":"Il suivit donc une voie."},{"n":2226,"s":18,"a":86,"t":"Et quand il eut atteint le Couchant, il trouva que le soleil se couchait dans une source boueuse, et, auprès d'elle il trouva une peuplade [impie]. Nous dîmes: «O Dûl-Qarnayn! ou tu les châties, ou tu uses de bienveillance à leur égard»."},{"n":2227,"s":18,"a":87,"t":"Il dit: «Quant à celui qui est injuste, nous le châtierons; ensuite il sera ramené vers son Seigneur qui le punira d'un châtiment terrible."},{"n":2228,"s":18,"a":88,"t":"Et quant à celui qui croit et fait bonne œuvre, il aura, en retour, la plus belle récompense. Et nous lui donnerons des ordres faciles à exécuter»."},{"n":2229,"s":18,"a":89,"t":"Puis, il suivit (une autre) voie."},{"n":2230,"s":18,"a":90,"t":"Et quand il eut atteint le Levant, il trouva que le soleil se levait sur une peuplade à laquelle Nous n'avions pas donné de voile pour s'en protéger."},{"n":2231,"s":18,"a":91,"t":"Il en fut ainsi et Nous embrassons de Notre Science ce qu'il détenait."},{"n":2232,"s":18,"a":92,"t":"Puis, il suivit (une autre) voie."},{"n":2233,"s":18,"a":93,"t":"Et quand il eut atteint un endroit situé entre les Deux Barrières (montagnes), il trouva derrière elles une peuplade qui ne comprenait presque aucun langage."},{"n":2234,"s":18,"a":94,"t":"Ils dirent: «O Dûl-Qarnayn, les Yâ jûj et les Mâ jûj commettent du désordre sur terre. Est-ce que nous pourrons t'accorder un tribut pour construire une barrière entre eux et nous?»"},{"n":2235,"s":18,"a":95,"t":"Il dit: «Ce que Mon Seigneur m'a conféré vaut mieux (que vos dons). Aidez-moi donc avec votre force et je construirai un remblai entre vous et eux."},{"n":2236,"s":18,"a":96,"t":"Apportez-moi des blocs de fer». Puis, lorsqu'il en eut comblé l'espace entre les deux montagnes, il dit: «Soufflez!» Puis, lorsqu'il l'eut rendu une fournaise, il dit: «Apportez-moi du cuivre fondu, que je le déverse dessus»."},{"n":2237,"s":18,"a":97,"t":"Ainsi, ils ne purent guère l'escalader ni l'ébrécher non plus."},{"n":2238,"s":18,"a":98,"t":"Il dit: «C'est une miséricorde de la part de mon Seigneur. Mais, lorsque la promesse de mon Seigneur viendra, Il le nivellera. Et la promesse de mon Seigneur est vérité»."},{"n":2239,"s":18,"a":99,"t":"Nous les laisserons, ce jour-là, déferler comme les flots les uns sur les autres, et on soufflera dans la Trompe et Nous les rassemblerons tous."},{"n":2240,"s":18,"a":100,"t":"Et ce jour-là Nous présenterons de près l'Enfer aux mécréants,"},{"n":2241,"s":18,"a":101,"t":"dont les yeux étaient couverts d'un voile qui les empêchait de penser à Moi, et ils ne pouvaient rien entendre non plus."},{"n":2242,"s":18,"a":102,"t":"Ceux qui ont mécru, comptent-ils donc pouvoir prendre, pour alliés, Mes serviteurs en dehors de Moi? Nous avons préparé l'Enfer comme résidence pour les mécréants."},{"n":2243,"s":18,"a":103,"t":"Dis: «Voulez-vous que Nous vous apprenions lesquels sont les plus grands perdants, en œuvres?"},{"n":2244,"s":18,"a":104,"t":"Ceux dont l'effort, dans la vie présente, s'est égaré, alors qu'ils s'imaginent faire le bien."},{"n":2245,"s":18,"a":105,"t":"Ceux-là qui ont nié les signes de leur Seigneur, ainsi que Sa rencontre. Leurs actions sont donc vaines». Nous ne leur assignerons pas de poids au Jour de la Résurrection."},{"n":2246,"s":18,"a":106,"t":"C'est que leur rétribution sera l'Enfer, pour avoir mécru et pris en raillerie Mes signes (enseignements) et Mes messagers."},{"n":2247,"s":18,"a":107,"t":"Ceux qui croient et font de bonnes œuvres auront pour résidence les Jardins du «Firdaws,» (Paradis),"},{"n":2248,"s":18,"a":108,"t":"où ils demeureront éternellement, sans désirer aucun changement."},{"n":2249,"s":18,"a":109,"t":"Dis: «Si la mer était une encre [pour écrire] les paroles de mon Seigneur, certes la mer s'épuiserait avant que ne soient épuisées les paroles de mon Seigneur, quand même Nous lui apporterions son équivalent comme renfort.»"},{"n":2250,"s":18,"a":110,"t":"Dis: «Je suis en fait un être humain comme vous. Il m'a été révélé que votre Dieu est un Dieu unique! Quiconque, donc, espère rencontrer son Seigneur, qu'il fasse de bonnes actions et qu'il n'associe dans son adoration aucun autre à son Seigneur»."},{"n":2251,"s":19,"a":1,"t":"Kâf, Hâ', Yâ', 'Aîn, Sâd."},{"n":2252,"s":19,"a":2,"t":"C'est un récit de la miséricorde de ton Seigneur envers Son serviteur Zacharie."},{"n":2253,"s":19,"a":3,"t":"Lorsqu'il invoqua son Seigneur d'une invocation secrète,"},{"n":2254,"s":19,"a":4,"t":"et dit: «O mon Seigneur, mes os sont affaiblis et ma tête s'est enflammée de cheveux blancs. [Cependant], je n'ai jamais été malheureux [déçu] en te priant, ô mon Seigneur."},{"n":2255,"s":19,"a":5,"t":"Je crains [le comportement] de mes héritiers, après moi. Et ma propre femme est stérile. Accorde-moi, de Ta part, un descendant"},{"n":2256,"s":19,"a":6,"t":"qui hérite de moi et hérite de la famille de Jacob. Et fais qu'il te soit agréable, ô mon Seigneur»."},{"n":2257,"s":19,"a":7,"t":"«O Zacharie, Nous t'annonçons la bonne nouvelle d'un fils. Son nom sera Yahya [Jean]. Nous ne lui avons pas donné auparavant d'homonyme»."},{"n":2258,"s":19,"a":8,"t":"Et [Zacharie dit]: «O mon Seigneur, comment aurai-je un fils, quand ma femme est stérile et que je suis très avancé en vieillesse?»"},{"n":2259,"s":19,"a":9,"t":"[Allah] lui dit: «Ainsi sera-t-il! Ton Seigneur a dit: «Ceci m'est facile. Et avant cela, Je t'ai créé alors que tu n'étais rien»."},{"n":2260,"s":19,"a":10,"t":"«O mon Seigneur, dit [Zacharie], accorde-moi un signe». «Ton signe, dit [Allah,] sera que tu ne pourras pas parler aux gens pendant trois nuits tout en étant bien portant."},{"n":2261,"s":19,"a":11,"t":"Il sortit donc du sanctuaire vers son peuple; puis il leur fit signe de prier matin et soir."},{"n":2262,"s":19,"a":12,"t":"... «O Yahya, tiens fermement au Livre (la Thora)!» Nous lui donnâmes la sagesse alors qu'il était enfant,"},{"n":2263,"s":19,"a":13,"t":"ainsi que la tendresse de Notre part et la pureté. Il était pieux,"},{"n":2264,"s":19,"a":14,"t":"et dévoué envers ses père et mère; et ne fut ni violent ni désobéissant."},{"n":2265,"s":19,"a":15,"t":"Que la paix soit sur lui le jour où il naquit, le jour où il mourra, et le jour où il sera ressuscité vivant!"},{"n":2266,"s":19,"a":16,"t":"Mentionne, dans le Livre (le Coran), Marie, quand elle se retira de sa famille en un lieu vers l'Orient."},{"n":2267,"s":19,"a":17,"t":"Elle mit entre elle et eux un voile. Nous lui envoyâmes Notre Esprit (Gabriel), qui se présenta à elle sous la forme d'un homme parfait."},{"n":2268,"s":19,"a":18,"t":"Elle dit: «Je me réfugie contre toi auprès du Tout Miséricordieux. Si tu es pieux, [ne m'approche point].»"},{"n":2269,"s":19,"a":19,"t":"Il dit: «Je suis en fait un Messager de ton Seigneur pour te faire don d'un fils pur»."},{"n":2270,"s":19,"a":20,"t":"Elle dit: «Comment aurais-je un fils, quand aucun homme ne m'a touchée, et que je ne suis pas prostituée?»"},{"n":2271,"s":19,"a":21,"t":"Il dit: «Ainsi sera-t-il! Cela M'est facile, a dit ton Seigneur! Et Nous ferons de lui un signe pour les gens, et une miséricorde de Notre part. C'est une affaire déjà décidée»."},{"n":2272,"s":19,"a":22,"t":"Elle devint donc enceinte [de l'enfant], et elle se retira avec lui en un lieu éloigné."},{"n":2273,"s":19,"a":23,"t":"Puis les douleurs de l'enfantement l'amenèrent au tronc du palmier, et elle dit: «Malheur à moi! Que je fusse morte avant cet instant! Et que je fusse totalement oubliée!»"},{"n":2274,"s":19,"a":24,"t":"Alors, il l'appela d'au-dessous d'elle, [lui disant:] «Ne t'afflige pas. Ton Seigneur a placé à tes pieds une source."},{"n":2275,"s":19,"a":25,"t":"Secoue vers toi le tronc du palmier: il fera tomber sur toi des dattes fraîches et mûres."},{"n":2276,"s":19,"a":26,"t":"Mange donc et bois et que ton œil se réjouisse! Si tu vois quelqu'un d'entre les humains, dis [lui:] «Assurément, j'ai voué un jeûne au Tout Miséricordieux: je ne parlerai donc aujourd'hui à aucun être humain»."},{"n":2277,"s":19,"a":27,"t":"Puis elle vint auprès des siens en le portant [le bébé]. Ils dirent: «O Marie, tu as fait une chose monstrueuse!"},{"n":2278,"s":19,"a":28,"t":"«Sœur de Hârûn, ton père n'était pas un homme de mal et ta mère n'était pas une prostituée»."},{"n":2279,"s":19,"a":29,"t":"Elle fit alors un signe vers lui [le bébé]. Ils dirent: «Comment parlerions-nous à un bébé au berceau?»"},{"n":2280,"s":19,"a":30,"t":"Mais (le bébé) dit: «Je suis vraiment le serviteur d'Allah. Il m'a donné le Livre et m'a désigné Prophète."},{"n":2281,"s":19,"a":31,"t":"Où que je sois, Il m'a rendu béni; et Il m'a recommandé, tant que je vivrai, la prière et la Zakât;"},{"n":2282,"s":19,"a":32,"t":"et la bonté envers ma mère. Il ne m'a fait ni violent ni malheureux."},{"n":2283,"s":19,"a":33,"t":"Et que la paix soit sur moi le jour où je naquis, le jour où je mourrai, et le jour où je serai ressuscité vivant.»"},{"n":2284,"s":19,"a":34,"t":"Tel est Issa (Jésus), fils de Marie: parole de vérité, dont ils doutent."},{"n":2285,"s":19,"a":35,"t":"Il ne convient pas à Allah de S'attribuer un fils. Gloire et Pureté à Lui! Quand Il décide d'une chose, Il dit seulement: «Sois!» et elle est."},{"n":2286,"s":19,"a":36,"t":"Certes, Allah est mon Seigneur tout comme votre Seigneur. Adorez-le donc. Voilà un droit chemin»."},{"n":2287,"s":19,"a":37,"t":"[par la suite,] les sectes divergèrent entre elles. Alors, malheur aux mécréants lors de la vue d'un jour terrible!"},{"n":2288,"s":19,"a":38,"t":"Comme ils entendront et verront bien le jour où ils viendront à Nous! Mais aujourd'hui, les injustes sont dans un égarement évident."},{"n":2289,"s":19,"a":39,"t":"Et avertis-les du jour du Regret, quand tout sera réglé; alors qu'ils sont [dans ce monde] inattentifs et qu'ils ne croient pas."},{"n":2290,"s":19,"a":40,"t":"C'est Nous, en vérité, qui hériterons la terre et tout ce qui s'y trouve, et c'est à Nous qu'ils seront ramenés."},{"n":2291,"s":19,"a":41,"t":"Et mentionne dans le Livre, Abraham. C'était un très véridique et un Prophète."},{"n":2292,"s":19,"a":42,"t":"Lorsqu'il dit à son père: «O mon père, pourquoi adores-tu ce qui n'entend ni ne voit, et ne te profite en rien?"},{"n":2293,"s":19,"a":43,"t":"O mon père, il m'est venu de la science ce que tu n'as pas reçu; suis-moi, donc, je te guiderai sur une voie droite."},{"n":2294,"s":19,"a":44,"t":"O mon père, n'adore pas le Diable, car le Diable désobéit au Tout Miséricordieux."},{"n":2295,"s":19,"a":45,"t":"O mon père, je crains qu'un châtiment venant du Tout Miséricordieux ne te touche et que tu ne deviennes un allié du Diable»."},{"n":2296,"s":19,"a":46,"t":"Il dit: «O Abraham, aurais-tu du dédain pour mes divinités? Si tu ne cesses pas, certes je te lapiderai, éloigne-toi de moi pour bien longtemps»."},{"n":2297,"s":19,"a":47,"t":"«Paix sur toi», dit Abraham. «J'implorerai mon Seigneur de te pardonner car Il m'a toujours comblé de Ses bienfaits."},{"n":2298,"s":19,"a":48,"t":"Je me sépare de vous, ainsi que de ce que vous invoquez, en dehors d'Allah, et j'invoquerai mon Seigneur. J'espère ne pas être malheureux dans mon appel à mon Seigneur»."},{"n":2299,"s":19,"a":49,"t":"Puis, lorsqu'il se fut séparé d'eux et de ce qu'ils adoraient en dehors d'Allah, Nous lui fîmes don d'Isaac et de Jacob; et de chacun Nous fîmes un prophète."},{"n":2300,"s":19,"a":50,"t":"Et Nous leur donnâmes de par Notre miséricorde, et Nous leur accordâmes un langage sublime de vérité."},{"n":2301,"s":19,"a":51,"t":"Et mentionne dans le Livre Moïse. C'était vraiment un élu, et c'était un Messager et un prophète."},{"n":2302,"s":19,"a":52,"t":"Du côté droit du Mont (Sinaï) Nous l'appelâmes et Nous le fîmes approcher tel un confident."},{"n":2303,"s":19,"a":53,"t":"Et par Notre miséricorde, Nous lui donnâmes Aaron son frère comme prophète."},{"n":2304,"s":19,"a":54,"t":"Et mentionne Ismaël, dans le Livre. Il était fidèle à ses promesses; et c'était un Messager et un prophète."},{"n":2305,"s":19,"a":55,"t":"Et il commandait à sa famille la prière et la Zakât; et il était agréé auprès de son Seigneur."},{"n":2306,"s":19,"a":56,"t":"Et mentionne Idris, dans le Livre. C'était un véridique et un prophète."},{"n":2307,"s":19,"a":57,"t":"Et Nous l'élevâmes à un haut rang."},{"n":2308,"s":19,"a":58,"t":"Voilà ceux qu'Allah a comblés de faveurs, parmi les prophètes, parmi les descendants d'Adam, et aussi parmi ceux que Nous avons transportés en compagnie de Noé, et parmi la descendance d'Abraham et d'Israël, et parmi ceux que Nous avons guidés et choisis. Quand les versets du Tout Miséricordieux leur étaient récités, ils tombaient prosternés en pleurant."},{"n":2309,"s":19,"a":59,"t":"Puis leur succédèrent des générations qui délaissèrent la prière et suivirent leurs passions. Ils se trouveront en perdition,"},{"n":2310,"s":19,"a":60,"t":"sauf celui qui se repent, croit et fait le bien: ceux-là entreront dans le Paradis et ne seront point lésés,"},{"n":2311,"s":19,"a":61,"t":"aux jardins du séjour (éternel) que le Tout Miséricordieux a promis à Ses serviteurs, [qui ont cru] au mystère. Car Sa promesse arrivera sans nul doute."},{"n":2312,"s":19,"a":62,"t":"On n'y entend nulle parole insignifiante; seulement: «Salâm»; et ils auront là leur nourriture, matin et soir."},{"n":2313,"s":19,"a":63,"t":"Voilà le Paradis dont Nous ferons hériter ceux de Nos serviteurs qui auront été pieux."},{"n":2314,"s":19,"a":64,"t":"«Nous ne descendons que sur ordre de ton Seigneur. A Lui tout ce qui est devant nous, tout ce qui est derrière nous et tout ce qui est entre les deux. Ton Seigneur n'oublie rien."},{"n":2315,"s":19,"a":65,"t":"Il est le Seigneur des cieux et de la terre et de tout ce qui est entre eux. Adore-Le donc, et sois constant dans Son adoration. Lui connais-tu un homonyme?»"},{"n":2316,"s":19,"a":66,"t":"Et l'homme dit: «Une fois mort, me sortira-t-on vivant?»"},{"n":2317,"s":19,"a":67,"t":"L'homme ne se rappelle-t-il pas qu'avant cela, c'est Nous qui l'avons créé, alors qu'il n'était rien?"},{"n":2318,"s":19,"a":68,"t":"Par ton Seigneur! Assurément, Nous les rassemblerons, eux et les diables. Puis, Nous les placerons autour de l'Enfer, agenouillés."},{"n":2319,"s":19,"a":69,"t":"Ensuite, Nous arracherons de chaque groupe ceux d'entre eux qui étaient les plus obstinés contre le Tout Miséricordieux."},{"n":2320,"s":19,"a":70,"t":"Puis nous sommes Le meilleur à savoir ceux qui méritent le plus d'y être brûlés."},{"n":2321,"s":19,"a":71,"t":"Il n'y a personne parmi vous qui ne passera pas par [L'Enfer]: Car [il s'agit là] pour ton Seigneur d'une sentence irrévocable."},{"n":2322,"s":19,"a":72,"t":"Ensuite, Nous délivrerons ceux qui étaient pieux et Nous y laisserons les injustes agenouillés."},{"n":2323,"s":19,"a":73,"t":"Et lorsque Nos versets évidents leur sont récités les mécréants disent à ceux qui croient: «Lequel des deux groupes a la situation la plus confortable et la meilleure compagnie?»"},{"n":2324,"s":19,"a":74,"t":"Combien de générations, avant eux, avons-Nous fait périr, qui les surpassaient en biens et en apparence?"},{"n":2325,"s":19,"a":75,"t":"Dis: «Celui qui est dans l'égarement, que le Tout Miséricordieux prolonge sa vie pour un certain temps, jusqu'à ce qu'ils voient soit le châtiment, soit l'Heure dont ils sont menacés. Alors, ils sauront qui a la pire situation et la troupe la plus faible»."},{"n":2326,"s":19,"a":76,"t":"Allah accroît la rectitude de ceux qui suivent le bon chemin, et les bonnes œuvres durables méritent auprès de ton Seigneur une meilleure récompense et une meilleure destination."},{"n":2327,"s":19,"a":77,"t":"As-tu vu celui qui ne croit pas à Nos versets et dit: «On me donnera certes des biens et des enfants»?"},{"n":2328,"s":19,"a":78,"t":"Est-il au courant de l'Inconnaissable ou a-t-il pris un engagement avec le Tout Miséricordieux?"},{"n":2329,"s":19,"a":79,"t":"Bien au contraire! Nous enregistrerons ce qu'il dit et accroîtrons son châtiment."},{"n":2330,"s":19,"a":80,"t":"C'est Nous qui hériterons ce dont il parle, tandis qu'il viendra à Nous, tout seul."},{"n":2331,"s":19,"a":81,"t":"Ils ont adopté des divinités en dehors d'Allah pour qu'ils leur soient des protecteurs (contre le châtiment)."},{"n":2332,"s":19,"a":82,"t":"Bien au contraire! [ces divinités] renieront leur adoration et seront pour eux des adversaires."},{"n":2333,"s":19,"a":83,"t":"N'as-tu pas vu que Nous avons envoyé contre les mécréants des diables qui les excitent furieusement [à désobéir]?"},{"n":2334,"s":19,"a":84,"t":"Ne te hâte donc pas contre eux: Nous tenons un compte précis de [tous leurs actes]."},{"n":2335,"s":19,"a":85,"t":"(Rappelle-toi) le jour où Nous rassemblerons les pieux sur des montures et en grande pompe, auprès du Tout Miséricordieux,"},{"n":2336,"s":19,"a":86,"t":"et pousserons les criminels à l'Enfer comme (un troupeau) à l'abreuvoir,"},{"n":2337,"s":19,"a":87,"t":"ils ne disposeront d'aucune intercession, sauf celui qui aura pris un engagement avec le Tout Miséricordieux."},{"n":2338,"s":19,"a":88,"t":"Et ils ont dit: «Le Tout Miséricordieux S'est attribué un enfant!»"},{"n":2339,"s":19,"a":89,"t":"Vous avancez certes là une chose abominable!"},{"n":2340,"s":19,"a":90,"t":"Peu s'en faut que les cieux ne s'entrouvrent à ces mots, que la terre ne se fende et que les montagnes ne s'écroulent,"},{"n":2341,"s":19,"a":91,"t":"du fait qu'ils ont attribué un enfant au Tout Miséricordieux,"},{"n":2342,"s":19,"a":92,"t":"alors qu'il ne convient nullement au Tout Miséricordieux d'avoir un enfant!"},{"n":2343,"s":19,"a":93,"t":"Tous ceux qui sont dans les cieux et sur la terre se rendront auprès du Tout Miséricordieux, [sans exception], en serviteurs."},{"n":2344,"s":19,"a":94,"t":"Il les a certes dénombrés et bien comptés."},{"n":2345,"s":19,"a":95,"t":"Et au Jour de la Résurrection, chacun d'eux se rendra seul auprès de Lui."},{"n":2346,"s":19,"a":96,"t":"A ceux qui croient et font de bonnes œuvres, le Tout Miséricordieux accordera Son amour."},{"n":2347,"s":19,"a":97,"t":"Nous l'avons rendu (le Coran) facile [à comprendre] en ta langue, afin que tu annonces par lui la bonne nouvelle aux gens pieux, et que, tu avertisses un peuple irréductible."},{"n":2348,"s":19,"a":98,"t":"Que de générations avant eux avons-Nous fait périr! En retrouves-tu un seul individu? ou en entends-tu le moindre murmure?"},{"n":2349,"s":20,"a":1,"t":"Tâ-Hâ."},{"n":2350,"s":20,"a":2,"t":"Nous n'avons point fait descendre sur toi le Coran pour que tu sois malheureux,"},{"n":2351,"s":20,"a":3,"t":"si ce n'est qu'un Rappel pour celui qui redoute (Allah),"},{"n":2352,"s":20,"a":4,"t":"(et comme) une révélation émanant de Celui qui a créé la terre et les cieux sublimes."},{"n":2353,"s":20,"a":5,"t":"Le Tout Miséricordieux S'est établi «Istawâ» sur le Trône."},{"n":2354,"s":20,"a":6,"t":"A Lui appartient ce qui est dans les cieux, sur la terre, ce qui est entre eux et ce qui est sous le sol humide."},{"n":2355,"s":20,"a":7,"t":"Et si tu élèves la voix, Il connaît certes les secrets, même les plus cachés."},{"n":2356,"s":20,"a":8,"t":"Allah! Point de divinité que Lui! Il possède les noms les plus beaux."},{"n":2357,"s":20,"a":9,"t":"Le récit de Moïse t'est-il parvenu?"},{"n":2358,"s":20,"a":10,"t":"Lorsqu'il vit du feu, il dit à sa famille: «Restez ici! Je vois du feu de loin; peut-être vous en apporterai-je un tison, ou trouverai-je auprès du feu de quoi me guider»."},{"n":2359,"s":20,"a":11,"t":"Puis, lorsqu'il y arriva, il fut interpellé: «Moïse!"},{"n":2360,"s":20,"a":12,"t":"Je suis ton Seigneur. Enlève tes sandales: car tu es dans la vallée sacrée, Tuwâ."},{"n":2361,"s":20,"a":13,"t":"Moi, Je t'ai choisi. Ecoute donc ce qui va être révélé."},{"n":2362,"s":20,"a":14,"t":"Certes, c'est Moi Allah: point de divinité que Moi. Adore-Moi donc et accomplis la Salât pour te souvenir de Moi."},{"n":2363,"s":20,"a":15,"t":"L'Heure va certes arriver. Je la cache à peine, pour que chaque âme soit rétribuée selon ses efforts."},{"n":2364,"s":20,"a":16,"t":"Que celui qui n'y croit pas et qui suit sa propre passion ne t'en détourne pas. Sinon tu périras."},{"n":2365,"s":20,"a":17,"t":"Et qu'est-ce qu'il y a dans ta main droite, ô Moïse?»"},{"n":2366,"s":20,"a":18,"t":"Il dit: «C'est mon bâton sur lequel je m'appuie, qui me sert à effeuiller (les arbres) pour mes moutons et j'en fais d'autres usages»."},{"n":2367,"s":20,"a":19,"t":"[Allah lui] dit: «Jette-le, O Moïse»."},{"n":2368,"s":20,"a":20,"t":"Il le jeta: et le voici un serpent qui rampait."},{"n":2369,"s":20,"a":21,"t":"[Allah] dit: «Saisis-le et ne crains rien: Nous le ramènerons à son premier état."},{"n":2370,"s":20,"a":22,"t":"Et serre ta main sous ton aisselle: elle en sortira blanche sans aucun mal, et ce sera là un autre prodige,"},{"n":2371,"s":20,"a":23,"t":"afin que Nous te fassions voir de Nos prodiges les plus importants."},{"n":2372,"s":20,"a":24,"t":"Rends-toi auprès de Pharaon car il a outrepassé toute limite."},{"n":2373,"s":20,"a":25,"t":"[Moïse] dit: «Seigneur, ouvre-moi ma poitrine,"},{"n":2374,"s":20,"a":26,"t":"et facilite ma mission,"},{"n":2375,"s":20,"a":27,"t":"et dénoue un nœud en ma langue,"},{"n":2376,"s":20,"a":28,"t":"afin qu'ils comprennent mes paroles,"},{"n":2377,"s":20,"a":29,"t":"et assigne-moi un assistant de ma famille:"},{"n":2378,"s":20,"a":30,"t":"Aaron, mon frère,"},{"n":2379,"s":20,"a":31,"t":"accrois par lui ma force!"},{"n":2380,"s":20,"a":32,"t":"et associe-le à ma mission,"},{"n":2381,"s":20,"a":33,"t":"afin que nous Te glorifions beaucoup,"},{"n":2382,"s":20,"a":34,"t":"et que nous T'invoquions beaucoup."},{"n":2383,"s":20,"a":35,"t":"Et Toi, certes, Tu es Très Clairvoyant sur nous»."},{"n":2384,"s":20,"a":36,"t":"[Allah] dit: «Ta demande est exaucée, ô Moïse."},{"n":2385,"s":20,"a":37,"t":"Et Nous t'avons déjà favorisé une première fois"},{"n":2386,"s":20,"a":38,"t":"lorsque Nous révélâmes à ta mère ce qui fut révélé:"},{"n":2387,"s":20,"a":39,"t":"«Mets-le dans le coffret, puis jette celui-ci dans les flots pour qu'ensuite le fleuve le lance sur la rive; un ennemi à Moi et à lui le prendra». Et J'ai répandu sur toi une affection de Ma part, afin que tu sois élevé sous Mon œil."},{"n":2388,"s":20,"a":40,"t":"Et vœilà que ta sœur (te suivait en) marchant et disait: «Puis-je vous indiquer quelqu'un qui se chargera de lui?» Ainsi, Nous te rapportâmes à ta mère afin que son oil se réjouisse et qu'elle ne s'afflige plus. Tu tuas ensuite un individu; Nous te sauvâmes des craintes qui t'oppressaient; et Nous t'imposâmes plusieurs épreuves. Puis tu demeuras des années durant chez les habitants de Madyan. Ensuite tu es venu, ô Moïse, conformément à un décret."},{"n":2389,"s":20,"a":41,"t":"Et je t'ai assigné à Moi-Même."},{"n":2390,"s":20,"a":42,"t":"Pars, toi et ton frère, avec Mes prodiges; et ne négligez pas de M'invoquer."},{"n":2391,"s":20,"a":43,"t":"Allez vers Pharaon: il s'est vraiment rebellé."},{"n":2392,"s":20,"a":44,"t":"Puis, parlez-lui gentiment. Peut-être se rappellera-t-il ou [Me] craindra-t-il?"},{"n":2393,"s":20,"a":45,"t":"Ils dirent: «O notre Seigneur, nous craignons qu'il ne nous maltraite indûment, ou qu'il dépasse les limites»."},{"n":2394,"s":20,"a":46,"t":"Il dit: «Ne craignez rien. Je suis avec vous: J'entends et Je vois."},{"n":2395,"s":20,"a":47,"t":"Allez donc chez lui; puis, dites-lui: «Nous sommes tous deux, les messagers de ton Seigneur. Envoie donc les Enfants d'Israël en notre compagnie et ne les châtie plus. Nous sommes venus à toi avec une preuve de la part de ton Seigneur. Et que la paix soit sur quiconque suit le droit chemin!"},{"n":2396,"s":20,"a":48,"t":"Il nous a été révélé que le châtiment est pour celui qui refuse d'avoir foi et qui tourne le dos»."},{"n":2397,"s":20,"a":49,"t":"Alors [Pharaon] dit: «Qui donc est votre Seigneur, ô Moïse?»"},{"n":2398,"s":20,"a":50,"t":"«Notre Seigneur, dit Moïse, est Celui qui a donné à chaque chose sa propre nature puis l'a dirigée»."},{"n":2399,"s":20,"a":51,"t":"«Qu'en est-il donc des générations anciennes?» dit Pharaon."},{"n":2400,"s":20,"a":52,"t":"Moïse dit: «La connaissance de leur sort est auprès de mon Seigneur, dans un livre. Mon Seigneur [ne commet] ni erreur ni oubli."},{"n":2401,"s":20,"a":53,"t":"C'est Lui qui vous a assigné la terre comme berceau et vous y a tracé des chemins; et qui du ciel a fait descendre de l'eau avec laquelle Nous faisons germer des couples de plantes de toutes sortes.»"},{"n":2402,"s":20,"a":54,"t":"«Mangez et faites paître votre bétail». Voilà bien là des signes pour les doués d'intelligence."},{"n":2403,"s":20,"a":55,"t":"C'est d'elle (la terre) que Nous vous avons créés, et en elle Nous vous retournerons, et d'elle Nous vous ferons sortir une fois encore."},{"n":2404,"s":20,"a":56,"t":"Certes Nous lui avons montré tous Nos prodiges; mais il les a démentis et a refusé (de croire)."},{"n":2405,"s":20,"a":57,"t":"Il dit: «Es-tu venu à nous, ô Moïse, pour nous faire sortir de notre terre par ta magie?"},{"n":2406,"s":20,"a":58,"t":"Nous t'apporterons assurément une magie semblable. Fixe entre nous et toi un rendez-vous auquel ni nous ni toi ne manquerons, dans un lieu convenable»."},{"n":2407,"s":20,"a":59,"t":"Alors Moïse dit: «Votre rendez-vous, c'est le jour de la fête. Et que les gens se rassemblent dans la matinée»."},{"n":2408,"s":20,"a":60,"t":"Pharaon, donc, se retira. Ensuite il rassembla sa ruse puis vint (au rendez-vous)."},{"n":2409,"s":20,"a":61,"t":"Moïse leur dit: «Malheur à vous! Ne forgez pas de mensonge contre Allah: sinon par un châtiment Il vous anéantira. Celui qui forge (un mensonge) est perdu»."},{"n":2410,"s":20,"a":62,"t":"Là-dessus, ils se mirent à disputer entre eux de leur affaire et tinrent secrètes leurs discussions."},{"n":2411,"s":20,"a":63,"t":"Ils dirent: «Voici deux magiciens qui, par leur magie, veulent vous faire abandonner votre terre et emporter votre doctrine idéale."},{"n":2412,"s":20,"a":64,"t":"Rassemblez donc votre ruse puis venez en rangs serrés. Et celui qui aura le dessus aujourd'hui aura réussi»."},{"n":2413,"s":20,"a":65,"t":"Ils dirent: «O Moïse, ou tu jettes, [le premier ton bâton] ou que nous soyons les premiers à jeter?»"},{"n":2414,"s":20,"a":66,"t":"Il dit: «Jetez plutôt». Et voilà que leurs cordes et leurs bâtons lui parurent ramper par l'effet de leur magie."},{"n":2415,"s":20,"a":67,"t":"Moïse ressentit quelque peur en lui-même."},{"n":2416,"s":20,"a":68,"t":"Nous lui dîmes: «N'aie pas peur, c'est toi qui auras le dessus."},{"n":2417,"s":20,"a":69,"t":"Jette ce qu'il y a dans ta main droite; cela dévorera ce qu'ils ont fabriqué. Ce qu'ils ont fabriqué n'est qu'une ruse de magicien; et le magicien ne réussit pas, où qu'il soit»."},{"n":2418,"s":20,"a":70,"t":"Les magiciens se jetèrent prosternés, disant: «Nous avons foi en le Seigneur d'Aaron et de Moïse»."},{"n":2419,"s":20,"a":71,"t":"Alors Pharaon dit: «Avez-vous cru en lui avant que je ne vous y autorise? C'est lui votre chef qui vous a enseigné la magie. Je vous ferai sûrement, couper mains et jambes opposées, et vous ferai crucifier aux troncs des palmiers, et vous saurez, avec certitude, qui de nous est plus fort en châtiment et qui est le plus durable»."},{"n":2420,"s":20,"a":72,"t":"«Par celui qui nous a créés, dirent-ils, nous ne te préférerons jamais à ce qui nous est parvenu comme preuves évidentes. Décrète donc ce que tu as à décréter. Tes décrets ne touchent que cette présente vie."},{"n":2421,"s":20,"a":73,"t":"Nous croyons en notre Seigneur, afin qu'Il nous pardonne nos fautes ainsi que la magie à laquelle tu nous as contraints». Et Allah est meilleur et éternel."},{"n":2422,"s":20,"a":74,"t":"Quiconque vient en criminel à son Seigneur, aura certes l'Enfer où il ne meurt ni ne vit."},{"n":2423,"s":20,"a":75,"t":"Et quiconque vient auprès de Lui en croyant, après avoir fait de bonnes œuvres, voilà donc ceux qui auront les plus hauts rangs,"},{"n":2424,"s":20,"a":76,"t":"les jardins du séjour (éternel), sous lesquels coulent les ruisseaux, où ils demeureront éternellement. Et voilà la récompense de ceux qui se purifient [de la mécréance et des péchés]."},{"n":2425,"s":20,"a":77,"t":"Nous révélâmes à Moïse: «Pars la nuit, à la tête de Mes serviteurs, puis, trace-leur un passage à sec dans la mer: sans craindre une poursuite et sans éprouver aucune peur»."},{"n":2426,"s":20,"a":78,"t":"Pharaon les poursuivit avec ses armées. La mer les submergea bel et bien."},{"n":2427,"s":20,"a":79,"t":"Pharaon égara ainsi son peuple et ne le mît pas sur le droit chemin."},{"n":2428,"s":20,"a":80,"t":"O Enfants d'Israël, Nous vous avons déjà délivrés de votre ennemi, et Nous vous avons donné rendez-vous sur le flanc droit du Mont. Et Nous avons fait descendre sur vous la manne et les cailles."},{"n":2429,"s":20,"a":81,"t":"«Mangez des bonnes choses que Nous vous avons attribuées et ne vous montrez pas ingrats, sinon Ma colère s'abattra sur vous: et celui sur qui Ma colère s'abat, va sûrement vers l'abîme."},{"n":2430,"s":20,"a":82,"t":"Et je suis Grand Pardonneur à celui qui se repent, croit, fait bonne œuvre, puis se met sur le bon chemin»."},{"n":2431,"s":20,"a":83,"t":"«Pourquoi Moïse t'es-tu hâté de quitter ton peuple?»"},{"n":2432,"s":20,"a":84,"t":"Ils sont là sur mes traces, dit Moïse. Et je me suis hâté vers Toi, Seigneur, afin que Tu sois satisfait."},{"n":2433,"s":20,"a":85,"t":"Allah dit: «Nous avons mis ton peuple à l'épreuve après ton départ. Et le Sâmirî les a égarés»."},{"n":2434,"s":20,"a":86,"t":"Moïse retourna donc vers son peuple, courroucé et chagriné; il dit: «O mon peuple, votre Seigneur ne vous a-t-Il pas déjà fait une belle promesse? L'alliance a-t-elle donc été trop longue pour vous? ou avez-vous désiré que la colère de votre Seigneur s'abatte sur vous, pour avoir trahi votre engagement envers moi?»"},{"n":2435,"s":20,"a":87,"t":"Ils dirent: «Ce n'est pas de notre propre gré que nous avons manqué à notre engagement envers toi. Mais nous fûmes chargés de fardeaux d'ornements du peuple (de Pharaon); nous les avons donc jetés (sur le feu) tout comme le Sâmirî les a lancés."},{"n":2436,"s":20,"a":88,"t":"Puis il en a fait sortir pour eux un veau, un corps à mugissement. Et ils ont dit: «C'est votre divinité et la divinité de Moïse; il a donc oublié»!"},{"n":2437,"s":20,"a":89,"t":"Quoi! Ne voyaient-ils pas qu'il [le veau] ne leur rendait aucune parole et qu'il ne possédait aucun moyen de leur nuire ou de leur faire du bien?"},{"n":2438,"s":20,"a":90,"t":"Certes, Aaron leur avait bien dit auparavant: «O mon peuple, vous êtes tombés dans la tentation (à cause du veau). Or, c'est le Tout Miséricordieux qui est vraiment votre Seigneur. Suivez-moi donc et obéissez à mon commandement»."},{"n":2439,"s":20,"a":91,"t":"Ils dirent: «Nous continuerons à y être attachés, jusqu'à ce que Moïse retourne vers nous»."},{"n":2440,"s":20,"a":92,"t":"Alors [Moïse] dit: «Qu'est-ce qui t'a empêché, Aaron, quand tu les as vus s'égarer,"},{"n":2441,"s":20,"a":93,"t":"de me suivre? As-tu donc désobéi à mon commandement?»"},{"n":2442,"s":20,"a":94,"t":"[Aaron] dit: «O fils de ma mère, ne me prends ni par la barbe ni par la tête. Je craignais que tu ne dises: «Tu as divisé les enfants d'Israël et tu n'as pas observé mes ordres»."},{"n":2443,"s":20,"a":95,"t":"Alors [Moïse] dit: «Quel a été ton dessein? O Sâmirî?»"},{"n":2444,"s":20,"a":96,"t":"Il dit: «J'ai vu ce qu'ils n'ont pas vu: j'ai donc pris une poignée de la trace de l'Envoyé; puis, je l'ai lancée. Voilà ce que mon âme m'a suggéré»."},{"n":2445,"s":20,"a":97,"t":"«Va-t-en, dit [Moïse]. Dans la vie, tu auras à dire (à tout le monde): «Ne me touchez pas!» Et il y aura pour toi un rendez-vous que tu ne pourras manquer. Regarde ta divinité que tu as adorée avec assiduité. Nous la brûlerons certes, et ensuite, nous disperserons [sa cendre] dans les flots."},{"n":2446,"s":20,"a":98,"t":"En vérité, votre seul Dieu est Allah en dehors de qui il n'y a point de divinité. De Sa science Il embrasse tout."},{"n":2447,"s":20,"a":99,"t":"C'est ainsi que Nous te racontons les récits de ce qui s'est passé. C'est bien un rappel de Notre part que Nous t'avons apporté."},{"n":2448,"s":20,"a":100,"t":"Quiconque s'en détourne (de ce Coran), portera au jour de la résurrection un fardeau;"},{"n":2449,"s":20,"a":101,"t":"ils resteront éternellement dans cet état, et quel mauvais fardeau pour eux au Jour de la Résurrection,"},{"n":2450,"s":20,"a":102,"t":"Le jour où l'on soufflera dans la Trompe, ce jour-là Nous rassemblerons les criminels tout bleus (de peur)!"},{"n":2451,"s":20,"a":103,"t":"Ils chuchoteront entre eux: «Vous n'êtes restés là que dix [jours]!»"},{"n":2452,"s":20,"a":104,"t":"Nous connaissons parfaitement ce qu'ils diront lorsque l'un d'entre eux dont la conduite est exemplaire dira: «Vous n'êtes restés qu'un jour»."},{"n":2453,"s":20,"a":105,"t":"Et ils t'interrogent au sujet des montagnes. Dis: «Mon Seigneur les dispersera comme la poussière,"},{"n":2454,"s":20,"a":106,"t":"et les laissera comme une plaine dénudée"},{"n":2455,"s":20,"a":107,"t":"dans laquelle tu ne verras ni tortuosité, ni dépression."},{"n":2456,"s":20,"a":108,"t":"Ce jour-là, ils suivront le Convocateur sans tortuosité; et les voix baisseront devant le Tout Miséricordieux. Tu n'entendras alors qu'un chuchotement."},{"n":2457,"s":20,"a":109,"t":"Ce jour-là, l'intercession ne profitera qu'à celui auquel le Tout Miséricordieux aura donné Sa permission et dont Il agréera la parole."},{"n":2458,"s":20,"a":110,"t":"Il connaît ce qui est devant eux et ce qui est derrière eux, alors qu'eux-mêmes ne Le cernent pas de leur science."},{"n":2459,"s":20,"a":111,"t":"Et les visages s'humilieront devant Le Vivant, Celui qui subsiste par Lui-même «al-Qayyûm», et malheureux sera celui qui [se présentera devant Lui] chargé d'une iniquité."},{"n":2460,"s":20,"a":112,"t":"Et quiconque aura fait de bonnes œuvres tout en étant croyant, ne craindra ni injustice ni oppression."},{"n":2461,"s":20,"a":113,"t":"C'est ainsi que nous l'avons fait descendre un Coran en [langue] arabe, et Nous y avons multiplié les menaces, afin qu'ils deviennent pieux ou qu'il les incite à s'exhorter?"},{"n":2462,"s":20,"a":114,"t":"Que soit éxalté Allah, le Vrai Souverain! Ne te hâte pas [de réciter] le Coran avant que ne te soit achevée sa révélation. Et dis: «O mon Seigneur, accroît mes connaissances!»"},{"n":2463,"s":20,"a":115,"t":"En effet, Nous avons auparavant fait une recommandation à Adam; mais il oublia; et Nous n'avons pas trouvé chez lui de résolution ferme."},{"n":2464,"s":20,"a":116,"t":"Et quand Nous dîmes aux Anges: «Prosternez-vous devant Adam», ils se prosternèrent, excepté Iblis qui refusa."},{"n":2465,"s":20,"a":117,"t":"Alors Nous dîmes: «O Adam, celui-là est vraiment un ennemi pour toi et ton épouse. Prenez garde qu'il vous fasse sortir du Paradis, car alors tu seras malheureux."},{"n":2466,"s":20,"a":118,"t":"Car tu n'y auras pas faim ni ne seras nu,"},{"n":2467,"s":20,"a":119,"t":"tu n'y auras pas soif ni ne seras frappé par l'ardeur du soleil»."},{"n":2468,"s":20,"a":120,"t":"Puis le Diable le tenta en disant: «O Adam, t'indiquerai-je l'arbre de l'éternité et un royaume impérissable?»"},{"n":2469,"s":20,"a":121,"t":"Tous deux (Adam et Eve) en mangèrent. Alors leur apparut leur nudité. Ils se mirent à se couvrir avec des feuilles du paradis. Adam désobéit ainsi à son Seigneur et il s'égara."},{"n":2470,"s":20,"a":122,"t":"Son Seigneur l'a ensuite élu, agréé son repentir et l'a guidé."},{"n":2471,"s":20,"a":123,"t":"Il dit: «Descendez d'ici, (Adam et Eve), [Vous serez] tous (avec vos descendants) ennemis les uns des autres. Puis, si jamais un guide vous vient de Ma part, quiconque suit Mon guide ne s'égarera ni ne sera malheureux."},{"n":2472,"s":20,"a":124,"t":"Et quiconque se détourne de Mon Rappel, mènera certes, une vie pleine de gêne, et le Jour de la Résurrection Nous l'amènerons aveugle au rassemblement»."},{"n":2473,"s":20,"a":125,"t":"Il dira: «O mon Seigneur, pourquoi m'as-Tu amené aveugle alors qu'auparavant je voyais?»"},{"n":2474,"s":20,"a":126,"t":"[Allah lui] dira: «De même que Nos Signes (enseignements) t'étaient venus et que tu les as oubliés, ainsi aujourd'hui tu es oublié»."},{"n":2475,"s":20,"a":127,"t":"Ainsi sanctionnons-nous l'outrancier qui ne croit pas aux révélations de son Seigneur. Et certes, le châtiment de l'au-delà est plus sévère et plus durable."},{"n":2476,"s":20,"a":128,"t":"Cela ne leur a-t-il pas servi de direction, que Nous ayons fait périr avant eux tant de générations dans les demeures desquelles ils marchent maintenant? Voilà bien là des leçons pour les doués d'intelligence!"},{"n":2477,"s":20,"a":129,"t":"N'eussent-été un décret préalable de ton Seigneur et aussi un terme déjà fixé, (leur châtiment) aurait été inévitable (et immédiat)."},{"n":2478,"s":20,"a":130,"t":"Supporte patiemment ce qu'ils disent et célèbre Sa louange, avant le lever du soleil, avant son coucher et pendant la nuit; et exalte Sa Gloire aux extrémités du jour. Peut-être auras-tu satisfaction:"},{"n":2479,"s":20,"a":131,"t":"Et ne tends point les yeux vers ce dont Nous avons donné jouissance temporaire à certains groupes d'entre eux, comme décor de la vie présente, afin de les éprouver par cela. Ce qu'Allah fournit (au Paradis) est meilleur et plus durable."},{"n":2480,"s":20,"a":132,"t":"Et commande à ta famille la Salât, et fais-la avec persévérance. Nous ne te demandons point de nourriture: c'est à Nous de te nourrir. La bonne fin est réservée à la piété."},{"n":2481,"s":20,"a":133,"t":"Et ils disent: «Pourquoi ne nous apporte-t-il pas un miracle de son Seigneur? La Preuve (le Coran) de ce que contiennent les Ecritures anciennes ne leur est-elle pas venue?"},{"n":2482,"s":20,"a":134,"t":"Et si Nous les avions fait périr par un châtiment avant lui [Muhammad], ils auraient certainement dit: «O notre Seigneur, pourquoi ne nous as-Tu pas envoyé de Messager? Nous aurions alors suivi Tes enseignements avant d'avoir été humiliés et jetés dans l'ignominie»."},{"n":2483,"s":20,"a":135,"t":"Dis: «Chacun attend. Attendez donc! Vous saurez bientôt qui sont les gens du droit chemin et qui sont les bien-guidés»."},{"n":2484,"s":21,"a":1,"t":"[L'échéance] du règlement de leur compte approche pour les hommes, alors que dans leur insouciance ils s'en détournent."},{"n":2485,"s":21,"a":2,"t":"Aucun rappel [de révélation] récente ne leur vient de leur Seigneur, sans qu'ils ne l'entendent en s'amusant,"},{"n":2486,"s":21,"a":3,"t":"leurs cœurs distraits; et les injustes tiennent des conversations secrètes et disent: «Ce n'est là qu'un être humain semblable à vous? Allez-vous donc vous adonner à la magie alors que vous voyez clair?»"},{"n":2487,"s":21,"a":4,"t":"Il a répondu: «Mon Seigneur sait tout ce qui se dit au ciel et sur la terre; et Il est l'Audient, l'Omniscient»."},{"n":2488,"s":21,"a":5,"t":"Mais ils dirent: «Voilà plutôt un amas de rêves! Ou bien Il l'a inventé. Ou, c'est plutôt un poète. Qu'il nous apporte donc un signe [identique] à celui dont furent chargés les premiers envoyés»."},{"n":2489,"s":21,"a":6,"t":"Pas une seule cité parmi celles que Nous avons fait périr avant eux n'avait cru [à la vue des miracles]. Ceux-ci croiront-ils donc?"},{"n":2490,"s":21,"a":7,"t":"Nous n'avons envoyé avant toi que des hommes à qui Nous faisions des révélations. Demandez donc aux érudits du Livre, si vous ne savez pas."},{"n":2491,"s":21,"a":8,"t":"Et Nous n'en n'avons pas fait des corps qui ne consommaient pas de nourriture. Et ils n'étaient pas éternels."},{"n":2492,"s":21,"a":9,"t":"Puis Nous réalisâmes la promesse (qui leur avait été faite). Nous les sauvâmes avec ceux que Nous voulûmes [sauver]. Et Nous fîmes périr les outranciers."},{"n":2493,"s":21,"a":10,"t":"Nous avons assurément fait descendre vers vous un livre où se trouve votre rappel [ou votre renom]. Ne comprenez-vous donc pas?"},{"n":2494,"s":21,"a":11,"t":"Et que de cités qui ont commis des injustices, Nous avons brisées; et Nous avons créé d'autres peuples après eux."},{"n":2495,"s":21,"a":12,"t":"Quand [ces gens] sentirent Notre rigueur ils s'en enfuirent hâtivement."},{"n":2496,"s":21,"a":13,"t":"Ne galopez point. Retournez plutôt au grand luxe où vous étiez et dans vos demeures, afin que vous soyez interrogés."},{"n":2497,"s":21,"a":14,"t":"Ils dirent: «Malheur à nous! Nous étions vraiment injustes»."},{"n":2498,"s":21,"a":15,"t":"Telle ne cessa d'être leur lamentation jusqu'à ce que Nous les eûmes moissonnés et éteints."},{"n":2499,"s":21,"a":16,"t":"Ce n'est pas par jeu que Nous avons créé le ciel et la terre et ce qui est entre eux."},{"n":2500,"s":21,"a":17,"t":"Si Nous avions voulu prendre une distraction, Nous l'aurions prise de Nous-mêmes, si vraiment Nous avions voulu le faire."},{"n":2501,"s":21,"a":18,"t":"Bien au contraire, Nous lançons contre le faux la vérité qui le subjugue, et le voilà qui disparaît. Et malheur à vous pour ce que vous attribuez [injustement à Allah]."},{"n":2502,"s":21,"a":19,"t":"A Lui seul appartiennent tous ceux qui sont dans les cieux et sur la terre. Ceux qui sont auprès de Lui [les Anges] ne se considèrent point trop grands pour L'adorer et ne s'en lassent pas."},{"n":2503,"s":21,"a":20,"t":"Ils exaltent Sa Gloire nuit et jour et ne s'interrompent point."},{"n":2504,"s":21,"a":21,"t":"Ont-ils pris des divinités qui peuvent ressusciter (les morts) de la terre?"},{"n":2505,"s":21,"a":22,"t":"S'il y avait dans le ciel et la terre des divinités autres qu'Allah, tous deux seraient certes dans le désordre. Gloire, donc à Allah, Seigneur du Trône; Il est au-dessus de ce qu'ils Lui attribuent!"},{"n":2506,"s":21,"a":23,"t":"Il n'est pas interrogé sur ce qu'Il fait, mais ce sont eux qui devront rendre compte [de leurs actes]."},{"n":2507,"s":21,"a":24,"t":"Ont-ils pris des divinités en dehors de Lui? Dis: «Apportez votre preuve». Ceci est la révélation de ceux qui sont avec moi et de ceux qui étaient avant moi. Mais la plupart d'entre eux ne connaissent pas la vérité et s'en écartent."},{"n":2508,"s":21,"a":25,"t":"Et Nous n'avons envoyé avant toi aucun Messager à qui Nous n'ayons révélé: «Point de divinité en dehors de Moi. Adorez-Moi donc»."},{"n":2509,"s":21,"a":26,"t":"Et ils dirent: «Le Tout Miséricordieux s'est donné un enfant». Pureté à Lui! Mais ce sont plutôt des serviteurs honorés."},{"n":2510,"s":21,"a":27,"t":"Ils ne devancent pas Son Commandement et agissent selon Ses ordres."},{"n":2511,"s":21,"a":28,"t":"Il sait ce qui est devant eux et ce qui derrière eux. Et ils n'intercèdent qu'en faveur de ceux qu'Il a agréés [tout en étant] pénétrés de Sa crainte."},{"n":2512,"s":21,"a":29,"t":"Et quiconque d'entre eux dirait: «Je suis une divinité en dehors de Lui». Nous le rétribuerons de l'Enfer. C'est ainsi que Nous rétribuons les injustes."},{"n":2513,"s":21,"a":30,"t":"Ceux qui ont mécru, n'ont-ils pas vu que les cieux et la terre formaient une masse compacte? Ensuite Nous les avons séparés et fait de l'eau toute chose vivante. Ne croiront-ils donc pas?"},{"n":2514,"s":21,"a":31,"t":"Et Nous avons placé des montagnes fermes dans la terre, afin qu'elle ne s'ébranle pas en les [entraînant]. Et Nous y avons placé des défilés servant de chemins afin qu'ils se guident."},{"n":2515,"s":21,"a":32,"t":"Et Nous avons fait du ciel un toit protégé. Et cependant ils se détournent de ses merveilles."},{"n":2516,"s":21,"a":33,"t":"Et c'est Lui qui a créé la nuit et le jour, le soleil et la lune; chacun voguant dans une orbite."},{"n":2517,"s":21,"a":34,"t":"Et Nous n'avons attribué l'immortalité à nul homme avant toi. Est-ce que si tu meurs, toi, ils seront, eux, éternels?"},{"n":2518,"s":21,"a":35,"t":"Toute âme doit goûter la mort. Nous vous éprouverons par le mal et par le bien [à titre] de tentation. Et c'est à Nous que vous serez ramenés."},{"n":2519,"s":21,"a":36,"t":"Quand les mécréants te voient, ils ne te prennent qu'en dérision (disant): «Quoi! Est-ce-là celui qui médit de vos divinités?» Et ils nient [tout] rappel du Tout Miséricordieux."},{"n":2520,"s":21,"a":37,"t":"L'homme a été créé prompt dans sa nature. Je vous montrerai Mes signes [la réalisation de Mes menaces]. Ne me hâtez donc pas."},{"n":2521,"s":21,"a":38,"t":"Et ils disent: «A quand cette promesse si vous êtes véridiques?»"},{"n":2522,"s":21,"a":39,"t":"Si [seulement] les mécréants connaissaient le moment où ils ne pourront empêcher le feu de leurs visages ni de leurs dos, et où ils ne seront point secourus."},{"n":2523,"s":21,"a":40,"t":"Mais non, cela leur viendra subitement et ils seront alors stupéfaits; ils ne pourront pas le repousser et on ne leur donnera pas de répit."},{"n":2524,"s":21,"a":41,"t":"On s'est moqué de messagers venus avant toi. Et ceux qui se sont moqués d'eux, se virent frapper de toutes parts par l'objet même de leurs moqueries."},{"n":2525,"s":21,"a":42,"t":"Dis: «Qui vous protège la nuit et le jour, contre le [châtiment] du Tout Miséricordieux?» Pourtant ils se détournent du rappel de leur Seigneur."},{"n":2526,"s":21,"a":43,"t":"Ont-ils donc des divinités en dehors de Nous, qui peuvent les protéger? Mais celles-ci ne peuvent ni se secourir elles-mêmes, ni se faire assister contre Nous."},{"n":2527,"s":21,"a":44,"t":"Au contraire Nous avons accordé une jouissance [temporaire] à ceux-là comme à leurs ancêtres jusqu'à un âge avancé. Ne voient-ils pas que Nous venons à la terre que Nous réduisons de tous côtés? Seront-ils alors les vainqueurs?"},{"n":2528,"s":21,"a":45,"t":"Dis: «Je vous avertis par ce qui m'est révélé». Les sourds, cependant, n'entendent pas l'appel quand on les avertit."},{"n":2529,"s":21,"a":46,"t":"Si un souffle du châtiment de ton Seigneur les effleurait, ils diraient alors: «Malheur à nous! Nous étions vraiment injustes»."},{"n":2530,"s":21,"a":47,"t":"Au Jour de la Résurrection, Nous placerons les balances exactes. Nulle âme ne sera lésée en rien, fût-ce du poids d'un grain de moutarde que Nous ferons venir. Nous suffisons largement pour dresser les comptes."},{"n":2531,"s":21,"a":48,"t":"Nous avons déjà apporté à Moïse et Aaron le Livre du discernement (la Thora) ainsi qu'une lumière et un rappel pour les gens pieux,"},{"n":2532,"s":21,"a":49,"t":"qui craignent leur Seigneur malgré qu'ils ne Le voient pas, et redoutent l'Heure (la fin du monde)."},{"n":2533,"s":21,"a":50,"t":"Et ceci [le Coran] est un rappel béni que Nous avons fait descendre. Allez-vous donc le renier?"},{"n":2534,"s":21,"a":51,"t":"En effet, Nous avons mis auparavant Abraham sur le droit chemin. Et Nous en avions bonne connaissance."},{"n":2535,"s":21,"a":52,"t":"Quand il dit à son père et à son peuple: «Que sont ces statues auxquelles vous vous attachez?»"},{"n":2536,"s":21,"a":53,"t":"ils dirent: «Nous avons trouvé nos ancêtres les adorant»."},{"n":2537,"s":21,"a":54,"t":"Il dit: «Certainement, vous avez été, vous et vos ancêtres, dans un égarement évident»."},{"n":2538,"s":21,"a":55,"t":"Ils dirent: «Viens-tu à nous avec la vérité ou plaisantes-tu?»"},{"n":2539,"s":21,"a":56,"t":"Il dit: «Mais votre Seigneur est plutôt le Seigneur des cieux et de la terre, et c'est Lui qui les a créés. Et je suis un de ceux qui en témoignent."},{"n":2540,"s":21,"a":57,"t":"Et par Allah! Je ruserai certes contre vos idoles une fois que vous serez partis»."},{"n":2541,"s":21,"a":58,"t":"Il les mit en pièces, hormis [la statue] la plus grande. Peut-être qu'ils reviendraient vers elle."},{"n":2542,"s":21,"a":59,"t":"Ils dirent: «Qui a fait cela à nos divinités? Il est certes parmi les injustes»."},{"n":2543,"s":21,"a":60,"t":"(Certains) dirent: «Nous avons entendu un jeune homme médire d'elles; il s'appelle Abraham»."},{"n":2544,"s":21,"a":61,"t":"Ils dirent: «Amenez-le sous les yeux des gens afin qu'ils puissent témoigner."},{"n":2545,"s":21,"a":62,"t":"(Alors) ils dirent: «Est-ce toi qui as fait cela à nos divinités, Abraham?»"},{"n":2546,"s":21,"a":63,"t":"Il dit: «C'est la plus grande d'entre elles que voici, qui l'a fait. Demandez-leur donc, si elles peuvent parler»."},{"n":2547,"s":21,"a":64,"t":"Se ravisant alors, ils se dirent entre eux: «C'est vous qui êtes les vrais injustes»."},{"n":2548,"s":21,"a":65,"t":"Puis ils firent volte-face et dirent: «Tu sais bien que celles-ci ne parlent pas»."},{"n":2549,"s":21,"a":66,"t":"Il dit: «Adorez-vous donc, en dehors d'Allah, ce qui ne saurait en rien vous être utile ni vous nuire non plus."},{"n":2550,"s":21,"a":67,"t":"Fi de vous et de ce que vous adorez en dehors d'Allah! Ne raisonnez-vous pas?»"},{"n":2551,"s":21,"a":68,"t":"Ils dirent: «Brûlez-le. Secourez vos divinités si vous voulez faire quelque chose (pour elles)»."},{"n":2552,"s":21,"a":69,"t":"Nous dîmes: «O feu, sois pour Abraham une fraîcheur salutaire»."},{"n":2553,"s":21,"a":70,"t":"Ils voulaient ruser contre lui, mais ce sont eux que Nous rendîmes les plus grands perdants."},{"n":2554,"s":21,"a":71,"t":"Et Nous le sauvâmes, ainsi que Lot, vers une terre que Nous avions bénie pour tout l'univers."},{"n":2555,"s":21,"a":72,"t":"Et Nous lui donnâmes Isaac et, de surcroît Jacob, desquels Nous fîmes des gens de bien."},{"n":2556,"s":21,"a":73,"t":"Nous les fîmes des dirigeants qui guidaient par Notre ordre. Et Nous leur révélâmes de faire le bien, d'accomplir la prière et d'acquitter la Zakât. Et ils étaient Nos adorateurs."},{"n":2557,"s":21,"a":74,"t":"Et Lot! Nous lui avons apporté la capacité de juger et le savoir, et Nous l'avons sauvé de la cité où se commettaient les vices; ces gens étaient vraiment des gens du mal, des pervers."},{"n":2558,"s":21,"a":75,"t":"et Nous l'avons fait entrer en Notre miséricorde. Il était vraiment du nombre des gens de bien."},{"n":2559,"s":21,"a":76,"t":"Et Noé, quand auparavant il fit son appel. Nous l'exauçâmes et Nous le sauvâmes, ainsi que sa famille, de la grande angoisse,"},{"n":2560,"s":21,"a":77,"t":"et Nous le secourûmes contre le peuple qui traitait Nos prodiges de mensonges. Ils furent vraiment des gens du Mal. Nous les noyâmes donc tous."},{"n":2561,"s":21,"a":78,"t":"Et David, et Salomon, quand ils eurent à juger au sujet d'un champ cultivé où des moutons appartenant à une peuplade étaient allés paître, la nuit. Et Nous étions témoin de leur jugement."},{"n":2562,"s":21,"a":79,"t":"Nous la fîmes comprendre à Salomon. Et à chacun Nous donnâmes la faculté de juger et le savoir. Et Nous asservîmes les montagnes à exalter Notre Gloire en compagnie de David, ainsi que les oiseaux. Et c'est Nous qui sommes le Faiseur."},{"n":2563,"s":21,"a":80,"t":"Nous lui (David) apprîmes la fabrication des cottes de mailles afin qu'elles vous protègent contre vos violences mutuelles (la guerre). En êtes-vous donc reconnaissants?"},{"n":2564,"s":21,"a":81,"t":"Et (Nous avons soumis) à Salomon le vent impétueux qui, par son ordre, se dirigea vers la terre que Nous avions bénie. Et Nous sommes à même de tout savoir,"},{"n":2565,"s":21,"a":82,"t":"et parmi les diables il en était qui plongeaient pour lui et faisaient d'autres travaux encore, et Nous les surveillions Nous-mêmes."},{"n":2566,"s":21,"a":83,"t":"Et Job, quand il implora son Seigneur: «Le mal m'a touché. Mais Toi, tu es le plus miséricordieux des miséricordieux»!"},{"n":2567,"s":21,"a":84,"t":"Nous l'exauçâmes, enlevâmes le mal qu'il avait, lui rendîmes les siens et autant qu'eux avec eux, par miséricorde de Notre part et en tant que rappel aux adorateurs."},{"n":2568,"s":21,"a":85,"t":"Et Ismaël, Idris, et Dûl-Kifl! qui étaient tous endurants;"},{"n":2569,"s":21,"a":86,"t":"que Nous fîmes entrer en Notre miséricorde car ils étaient vraiment du nombre des gens de bien."},{"n":2570,"s":21,"a":87,"t":"Et Dû'n-Nûn (Jonas) quand il partit, irrité. Il pensa que Nous N'allions pas l'éprouver. Puis il fit, dans les ténèbres, l'appel que voici: «Pas de divinité à part Toi! Pureté à Toi! J'ai été vraiment du nombre des injustes»."},{"n":2571,"s":21,"a":88,"t":"Nous l'exauçâmes et le sauvâmes de son angoisse. Et c'est ainsi que Nous sauvons les croyants."},{"n":2572,"s":21,"a":89,"t":"Et Zacharie, quand il implora son Seigneur: «Ne me laisse pas seul, Seigneur, alors que Tu es le meilleur des héritiers»."},{"n":2573,"s":21,"a":90,"t":"Nous l'exauçâmes, lui donnâmes Yahya et guérîmes son épouse. Ils concouraient au bien et Nous invoquaient par amour et par crainte. Et ils étaient humbles devant Nous."},{"n":2574,"s":21,"a":91,"t":"Et celle [la vierge Marie] qui avait préservé sa chasteté! Nous insufflâmes en elle un souffle (de vie) venant de Nous et fîmes d'elle ainsi que de son fils, un signe [miracle] pour l'univers."},{"n":2575,"s":21,"a":92,"t":"Certes, cette communauté qui est la vôtre est une communauté unique, et Je suis votre Seigneur. Adorez-Moi donc."},{"n":2576,"s":21,"a":93,"t":"Ils se sont divisés en sectes. Mais tous, retourneront à Nous."},{"n":2577,"s":21,"a":94,"t":"Quiconque fait de bonnes œuvres tout en étant croyant, on ne méconnaîtra pas son effort, et Nous le lui inscrivons [à son actif]."},{"n":2578,"s":21,"a":95,"t":"Il est défendu [aux habitants] d'une cité que Nous avons fait périr de revenir [à la vie d'ici-bas]!"},{"n":2579,"s":21,"a":96,"t":"Jusqu'à ce que soient relâchés les Yâjûj et les Mâjûj et qu'ils se précipiteront de chaque hauteur;"},{"n":2580,"s":21,"a":97,"t":"c'est alors que la vraie promesse s'approchera, tandis que les regards de ceux qui ont mécru se figent: «Malheur à nous! Nous y avons été inattentifs. Bien plus, nous étions des injustes»."},{"n":2581,"s":21,"a":98,"t":"«Vous serez, vous et ce que vous adoriez en dehors d'Allah, le combustible de l'Enfer, vous vous y rendrez tous."},{"n":2582,"s":21,"a":99,"t":"Si ceux-là étaient vraiment des divinités, ils n'y entreraient pas; et tous y demeureront éternellement."},{"n":2583,"s":21,"a":100,"t":"Ils y pousseront des gémissements, et n'y entendront rien."},{"n":2584,"s":21,"a":101,"t":"En seront écartés, ceux à qui étaient précédemment promises de belles récompenses de Notre part."},{"n":2585,"s":21,"a":102,"t":"Ils n'entendront pas son sifflement et jouiront éternellement de ce que leurs âmes désirent."},{"n":2586,"s":21,"a":103,"t":"La grande terreur ne les affligera pas, et les Anges les accueilleront: «voici le jour qui vous a été promis»."},{"n":2587,"s":21,"a":104,"t":"Le jour où Nous plierons le ciel comme on plie le rouleau des livres. Tout comme Nous avons commencé la première création, ainsi Nous la répéterons; c'est une promesse qui Nous incombe et Nous l'accomplirons!"},{"n":2588,"s":21,"a":105,"t":"Et Nous avons certes écrit dans le Zabûr, après l'avoir mentionné (dans le Livre céleste), que la terre sera héritée par Mes bons serviteurs»."},{"n":2589,"s":21,"a":106,"t":"Il y a en cela [ces enseignements] une communication à un peuple d'adorateurs!"},{"n":2590,"s":21,"a":107,"t":"Et Nous ne t'avons envoyé qu'en miséricorde pour l'univers."},{"n":2591,"s":21,"a":108,"t":"Dis: «Voilà ce qui m'est révélé: Votre Dieu est un Dieu unique; Etes-vous Soumis?» [décidés à embrasser l'Islam]"},{"n":2592,"s":21,"a":109,"t":"Si ensuite ils se détournent dis alors: «Je vous ai avertis en toute équité; je ne sais si ce qui vous est promis est proche ou lointain."},{"n":2593,"s":21,"a":110,"t":"Il connaît ce que vous dites à haute voix et ce que vous cachez."},{"n":2594,"s":21,"a":111,"t":"Et je ne sais pas; ceci est peut-être une tentation pour vous et une jouissance pour un certain temps»!"},{"n":2595,"s":21,"a":112,"t":"Il dit: «Seigneur, juge en toute justice! Et Notre Seigneur le Tout Miséricordieux, c'est Lui dont le secours est imploré contre vos assertions»."},{"n":2596,"s":22,"a":1,"t":"O hommes! Craignez votre Seigneur. Le séisme [qui précédera] l'Heure est une chose terrible."},{"n":2597,"s":22,"a":2,"t":"Le jour où vous le verrez, toute nourrice oubliera ce qu'elle allaitait, et toute femelle enceinte avortera de ce qu'elle portait. Et tu verras les gens ivres, alors qu'ils ne le sont pas. Mais le châtiment d'Allah est dur."},{"n":2598,"s":22,"a":3,"t":"Et il y a des gens qui discutent au sujet d'Allah sans aucune science, et qui suivent tout diable rebelle."},{"n":2599,"s":22,"a":4,"t":"Il a été prescrit à l'égard de ce dernier qu'il égarera quiconque le prendra pour maître, et qu'il le guidera vers le châtiment de la fournaise."},{"n":2600,"s":22,"a":5,"t":"O hommes! Si vous doutez au sujet de la Résurrection, c'est Nous qui vous avons créés de terre, puis d'une goutte de sperme, puis d'une adhérence puis d'un embryon [normalement] formé aussi bien qu'informe pour vous montrer [Notre Omnipotence] et Nous déposerons dans les matrices ce que Nous voulons jusqu'à un terme fixé. Puis Nous vous en sortirons [à l'état] de bébé, pour qu'ensuite vous atteignez votre maturité. Il en est parmi vous qui meurent [jeunes] tandis que d'autres parviennent au plus vil de l'âge si bien qu'ils ne savent plus rien de ce qu'ils connaissaient auparavant. De même tu vois la terre desséchée: dès que Nous y faisons descendre de l'eau elle remue, se gonfle, et fait pousser toutes sortes de splendides couples de végétaux."},{"n":2601,"s":22,"a":6,"t":"Il en est ainsi parce qu'Allah est la vérité; et c'est Lui qui rend la vie aux morts; et c'est Lui qui est Omnipotent."},{"n":2602,"s":22,"a":7,"t":"Et que l'Heure arrivera; pas de doute à son sujet, et qu'Allah ressuscitera ceux qui sont dans les tombeaux."},{"n":2603,"s":22,"a":8,"t":"Or, il y a des gens qui discutent au sujet d'Allah sans aucune science, ni guide, ni Livre pour les éclairer,"},{"n":2604,"s":22,"a":9,"t":"affichant une attitude orgueilleuse pour égarer les gens du sentier d'Allah. A lui l'ignominie ici-bas; et Nous Lui ferons goûter le Jour de la Résurrection, le châtiment de la fournaise."},{"n":2605,"s":22,"a":10,"t":"Voilà, pour ce que tes deux mains ont préparé (ici-bas)! Cependant, Allah n'est point injuste envers Ses serviteurs."},{"n":2606,"s":22,"a":11,"t":"Il en est parmi les gens qui adorent Allah marginalement. S'il leur arrive un bien, ils s'en tranquillisent, et s'il leur arrive une épreuve, ils détournent leur visage, perdant ainsi (le bien) de l'ici-bas et de l'au-delà. Telle est la perte évidente!"},{"n":2607,"s":22,"a":12,"t":"Ils invoquent en dehors d'Allah, ce qui ne peut ni leur nuire ni leur profiter. Tel est l'égarement profond!"},{"n":2608,"s":22,"a":13,"t":"Ils invoquent ce dont le mal est certainement plus proche que l'utilité. Quel mauvais allié, et quel mauvais compagnon!"},{"n":2609,"s":22,"a":14,"t":"Ceux qui croient et font de bonnes œuvres, Allah les fait entrer aux Jardins sous lesquels coulent les ruisseaux, car Allah fait certes ce qu'Il veut."},{"n":2610,"s":22,"a":15,"t":"Celui qui pense qu'Allah ne le secourra pas dans l'ici-bas et dans l'au-delà qu'il tende une corde jusqu'au ciel, puis qu'il la coupe, et qu'il voie si sa ruse va faire disparaître ce qui l'enrage."},{"n":2611,"s":22,"a":16,"t":"C'est ainsi que Nous le fîmes descendre (Le Coran) en versets clairs et qu'Allah guide qui Il veut."},{"n":2612,"s":22,"a":17,"t":"Certes, ceux qui ont cru, les Juifs, les Sabéens [les adorateurs des étoiles], les Nazaréens, les Mages et ceux qui donnent à Allah des associés, Allah tranchera entre eux le jour du Jugement, car Allah est certes témoin de toute chose."},{"n":2613,"s":22,"a":18,"t":"N'as-tu pas vu que c'est devant Allah que se prosternent tous ceux qui sont dans les cieux et tous ceux qui sont sur la terre, le soleil, la lune, les étoiles, les montagnes, les arbres, les animaux, ainsi que beaucoup de gens? Il y en a aussi beaucoup qui méritent le châtiment. Et quiconque Allah avilit n'a personne pour l'honorer, car Allah fait ce qu'il veut."},{"n":2614,"s":22,"a":19,"t":"Voici deux clans adverses qui disputaient au sujet de leur Seigneur. A ceux qui ne croient pas, on taillera des vêtements de feu, tandis que sur leurs têtes on versera de l'eau bouillante,"},{"n":2615,"s":22,"a":20,"t":"qui fera fondre ce qui est dans leurs ventres de même que leurs peaux."},{"n":2616,"s":22,"a":21,"t":"Et il y aura pour eux des maillets de fer."},{"n":2617,"s":22,"a":22,"t":"Toutes les fois qu'ils voudront en sortir (pour échapper) à la détresse, on les y remettra et (on leur dira): «Goûtez au châtiment de la Fournaise."},{"n":2618,"s":22,"a":23,"t":"Certes Allah introduit ceux qui croient et font de bonnes œuvres aux Jardins sous lesquels coulent les ruisseaux. Là, ils seront parés de bracelets d'or, et aussi de perles; et leurs vêtements y seront de soie."},{"n":2619,"s":22,"a":24,"t":"Ils ont été guidés vers la bonne parole et ils ont été guidés vers le chemin Du Digne des louanges."},{"n":2620,"s":22,"a":25,"t":"Mais ceux qui mécroient et qui obstruent le sentier d'Allah et celui de la Mosquée sacrée, que Nous avons établie pour les gens: aussi bien les résidents que ceux de passage... Quiconque cherche à y commettre un sacrilège injustement, Nous lui ferons goûter un châtiment douloureux,"},{"n":2621,"s":22,"a":26,"t":"Et quand Nous indiquâmes pour Abraham le lieu de la Maison (La Kaaba) [en lui disant]: «Ne M'associe rien; et purifie Ma Maison pour ceux qui tournent autour, pour ceux qui s'y tiennent debout et pour ceux qui s'y inclinent et se prosternent»."},{"n":2622,"s":22,"a":27,"t":"Et fais aux gens une annonce pour le Hajj. Ils viendront vers toi, à pied, et aussi sur toute monture, venant de tout chemin éloigné,"},{"n":2623,"s":22,"a":28,"t":"pour participer aux avantages qui leur ont été accordés et pour invoquer le nom d'Allah aux jours fixés, sur la bête de cheptel qu'Il leur a attribuée, «Mangez-en vous-mêmes et faites-en manger le besogneux misérable."},{"n":2624,"s":22,"a":29,"t":"Puis qu'ils mettent fin à leurs interdits (qu'ils nettoient leurs corps), qu'ils remplissent leurs vœux, et qu'ils fassent les circuits autour de l'Antique Maison»."},{"n":2625,"s":22,"a":30,"t":"Voilà [ce qui doit être observé] et quiconque prend en haute considération les limites sacrées d'Allah cela lui sera meilleur auprès de son Seigneur. Le bétail, sauf ce qu'on vous a cité, vous a été rendu licite. Abstenez-vous de la souillure des idoles et abstenez-vous des paroles mensongères."},{"n":2626,"s":22,"a":31,"t":"(Soyez) exclusivement [acquis à la religion] d'Allah ne Lui associez rien; car quiconque associe à Allah, c'est comme s'il tombait du haut du ciel et que les oiseaux le happaient, ou que le vent le précipitait dans un abîme très profond."},{"n":2627,"s":22,"a":32,"t":"Voilà [ce qui est prescrit]. Et quiconque exalte les injonctions sacrées d'Allah, s'inspire en effet de la piété des cœurs."},{"n":2628,"s":22,"a":33,"t":"[De ces bêtes-là] vous tirez des avantages jusqu'à un terme fixé; puis son lieu d'immolation est auprès de l'Antique Maison."},{"n":2629,"s":22,"a":34,"t":"A chaque communauté, Nous avons assigné un rite sacrificiel, afin qu'ils prononcent le nom d'Allah sur la bête de cheptel qu'Il leur a attribuée. Votre Dieu est certes un Dieu unique. Soumettez-vous donc à Lui. Et fais bonne annonce à ceux qui s'humilient,"},{"n":2630,"s":22,"a":35,"t":"ceux dont les cœurs frémissent quand le nom d'Allah est mentionné, ceux qui endurent ce qui les atteint et ceux qui accomplissent la Salât et dépensent de ce que Nous leur avons attribué."},{"n":2631,"s":22,"a":36,"t":"Nous vous avons désigné les chameaux (et les vaches) bien portants pour certains rites établis par Allah. Il y a en eux pour vous un bien. Prononcez donc sur eux le nom d'Allah, quand ils ont eu la patte attachée, [prêts à être immolés]. Puis, lorsqu'ils gisent sur le flanc, mangez-en, et nourrissez-en le besogneux discret et le mendiant. Ainsi Nous vous les avons assujettis afin que vous soyez reconnaissants."},{"n":2632,"s":22,"a":37,"t":"Ni leurs chairs ni leurs sangs n'atteindront Allah, mais ce qui L'atteint de votre part c'est la piété. Ainsi vous les a-t-Il assujettis afin que vous proclamiez la grandeur d'Allah, pour vous avoir mis sur le droit chemin. Et annonce la bonne nouvelle aux bienfaisants."},{"n":2633,"s":22,"a":38,"t":"Allah prend la défense de ceux qui croient. Allah n'aime aucun traître ingrat."},{"n":2634,"s":22,"a":39,"t":"Autorisation est donnée à ceux qui sont attaqués (de se défendre) - parce que vraiment ils sont lésés; et Allah est certes Capable de les secourir -"},{"n":2635,"s":22,"a":40,"t":"ceux qui ont été expulsés de leurs demeures, - contre toute justice, simplement parce qu'ils disaient: «Allah est notre Seigneur». - Si Allah ne repoussait pas les gens les uns par les autres, les ermitages seraient démolis, ainsi que les églises, les synagogues et les mosquées où le nom d'Allah est beaucoup invoqué. Allah soutient, certes, ceux qui soutiennent (Sa Religion). Allah est assurément Fort et Puissant,"},{"n":2636,"s":22,"a":41,"t":"ceux qui, si Nous leur donnons la puissance sur terre, accomplissent la Salât, acquittent la Zakât, ordonnent le convenable et interdisent le blâmable. Cependant, l'issue finale de toute chose appartient à Allah."},{"n":2637,"s":22,"a":42,"t":"Et s'ils te traitent de menteur, [sache que] le peuple de Noé, les 'Aad, les Tamûd avant eux, ont aussi crié au mensonge (à l'égard de leurs messagers),"},{"n":2638,"s":22,"a":43,"t":"de même que le peuple d'Abraham, le peuple de Lot."},{"n":2639,"s":22,"a":44,"t":"et les gens de Madyan. Et Moïse fut traité de menteur. Puis, J'ai donné un répit aux mécréants; ensuite Je les ai saisis. Et quelle fut Ma réprobation!"},{"n":2640,"s":22,"a":45,"t":"Que de cités, donc, avons-Nous fait périr, parce qu'elles commettaient des tyrannies. Elles sont réduites à des toits écroulés: Que de puits désertés! Que de palais édifiés (et désertés aussi)!"},{"n":2641,"s":22,"a":46,"t":"Que ne voyagent-ils sur la terre afin d'avoir des cœurs pour comprendre, et des oreilles pour entendre? Car ce ne sont pas les yeux qui s'aveuglent, mais, ce sont les cœurs dans les poitrines qui s'aveuglent."},{"n":2642,"s":22,"a":47,"t":"Et ils te demandent de hâter [l'arrivée] du châtiment. Jamais Allah ne manquera à Sa promesse. Cependant, un jour auprès de ton Seigneur, équivaut à mille ans de ce que vous comptez."},{"n":2643,"s":22,"a":48,"t":"A combien de cités n'ai-Je pas donné répit alors qu'elles commettaient des tyrannies? Ensuite, Je les ais saisies. Vers Moi est le devenir."},{"n":2644,"s":22,"a":49,"t":"Dis: «O hommes! Je ne suis pour vous, en vérité, qu'un avertisseur explicite»."},{"n":2645,"s":22,"a":50,"t":"Ceux donc qui croient et font de bonnes œuvres auront pardon et faveurs généreuses,"},{"n":2646,"s":22,"a":51,"t":"tandis que ceux qui s'efforcent à échapper (au châtiment mentionné dans) Nos versets, ceux-là sont les gens de l'Enfer."},{"n":2647,"s":22,"a":52,"t":"Nous n'avons envoyé, avant toi, ni Messager ni prophète qui n'ait récité (ce qui lui a été révélé) sans que le Diable n'ait essayé d'intervenir [pour semer le doute dans le cœur des gens au sujet] de sa récitation. Allah abroge ce que le Diable suggère, et Allah renforce Ses versets. Allah est Omniscient et Sage."},{"n":2648,"s":22,"a":53,"t":"Afin de faire, de ce que jette le Diable, une tentation pour ceux qui ont une maladie au cœur et ceux qui ont le cœur dur... Les injustes sont certes dans un schisme profond."},{"n":2649,"s":22,"a":54,"t":"Et afin que ceux à qui le savoir a été donné sachent que (le Coran) est en effet, la Vérité venant de ton Seigneur, qu'ils y croient alors, et que leurs cœurs s'y soumettent en toute humilité. Allah guide certes vers le droit chemin ceux qui croient."},{"n":2650,"s":22,"a":55,"t":"Et ceux qui mécroient ne cesseront d'être en doute à son sujet, jusqu'à ce que l'Heure les surprenne à l'improviste ou que les atteigne le châtiment d'un jour terrifiant."},{"n":2651,"s":22,"a":56,"t":"La souveraineté ce jour-là appartiendra à Allah qui jugera parmi eux. Ceux qui auront cru et fait de bonnes œuvres seront dans les Jardins du délice,"},{"n":2652,"s":22,"a":57,"t":"et quant aux infidèles qui auront traité Nos révélations de mensonges, ils auront un châtiment avilissant!"},{"n":2653,"s":22,"a":58,"t":"Ceux qui émigrent dans le sentier d'Allah et qui sont tués ou meurent, Allah leur accordera certes une belle récompense, car Allah est le meilleur des donateurs."},{"n":2654,"s":22,"a":59,"t":"Il les fera, certes, entrer en un lieu qu'ils agréeront, et Allah est certes Omniscient et Indulgent."},{"n":2655,"s":22,"a":60,"t":"Ainsi en est-il. Quiconque châtie de la même façon dont il a été châtié, et qu'ensuite il est victime d'un nouvel outrage, Allah l'aidera, car Allah est certainement Absoluteur et Pardonneur."},{"n":2656,"s":22,"a":61,"t":"C'est ainsi qu'Allah fait pénétrer la nuit dans le jour, et fait pénétrer le jour dans la nuit. Allah est, certes, Audient et Clairvoyant."},{"n":2657,"s":22,"a":62,"t":"C'est ainsi qu'Allah est Lui le Vrai, alors que ce qu'ils invoquent en dehors de Lui est le faux; c'est Allah qui est le Sublime, le Grand."},{"n":2658,"s":22,"a":63,"t":"N'as-tu pas vu qu'Allah fait descendre l'eau du ciel, et la terre devient alors verte? Allah est Plein de bonté et Parfaitement Connaisseur."},{"n":2659,"s":22,"a":64,"t":"A Lui appartient ce qui est dans les cieux et sur la terre. Allah est le seul qui se suffit à Lui-Même et qui est Le Digne de louange!"},{"n":2660,"s":22,"a":65,"t":"N'as-tu pas vu qu'Allah vous a soumis tout ce qui est sur la terre ainsi que le vaisseau qui vogue sur la mer par Son ordre? Il retient le ciel de tomber sur la terre, sauf quand Il le permettra. Car Allah est Plein de bonté et de miséricorde envers les hommes."},{"n":2661,"s":22,"a":66,"t":"C'est Lui qui vous donne la vie puis vous donne la mort, puis vous fait revivre. Vraiment l'homme est très ingrat!"},{"n":2662,"s":22,"a":67,"t":"A chaque communauté, Nous avons assigné un culte à suivre. Qu'ils ne disputent donc point avec toi l'ordre reçu! Et appelle à ton Seigneur. Tu es certes sur une voie droite."},{"n":2663,"s":22,"a":68,"t":"Et s'ils discutent avec toi, alors dis: «C'est Allah qui connaît mieux ce que vous faites."},{"n":2664,"s":22,"a":69,"t":"Allah jugera entre vous, au Jour de la Résurrection, ce en quoi vous divergez»."},{"n":2665,"s":22,"a":70,"t":"Ne sais-tu pas qu'Allah sait ce qu'il y a dans le ciel et sur la terre? Tout cela est dans un Livre, et cela est pour Allah bien facile."},{"n":2666,"s":22,"a":71,"t":"Et ils adorent en dehors d'Allah, ce en quoi Il n'a fait descendre aucune preuve et ce dont ils n'ont aucune connaissance. Et il n'y aura pas de protecteur pour les injustes."},{"n":2667,"s":22,"a":72,"t":"Et quand on leur récite Nos versets bien clairs, tu discerneras la réprobation sur les visages de ceux qui ont mécru. Peu s'en faut qu'ils ne se jettent sur ceux qui leur récitent Nos versets. Dis: «Vous informerai-je de quelque chose de plus terrible? - Le Feu: Allah l'a promis à ceux qui ont mécru. Et quel triste devenir!»"},{"n":2668,"s":22,"a":73,"t":"O hommes! Une parabole vous est proposée, écoutez-la: «Ceux que vous invoquez en dehors d'Allah ne sauraient même pas créer une mouche, quand même ils s'uniraient pour cela. Et si la mouche les dépouillait de quelque chose, ils ne sauraient le lui reprendre. Le solliciteur et le sollicité sont [également] faibles!»"},{"n":2669,"s":22,"a":74,"t":"Ils n'ont pas estimé Allah à sa juste valeur; Allah est certes Fort et Puissant."},{"n":2670,"s":22,"a":75,"t":"Allah choisit des messagers parmi les Anges et parmi les hommes. Allah est Audient et Clairvoyant."},{"n":2671,"s":22,"a":76,"t":"Il sait ce qui est devant eux et derrière eux. Et c'est vers Allah que tout retournera."},{"n":2672,"s":22,"a":77,"t":"O vous qui croyez! Inclinez-vous, prosternez-vous, adorez votre Seigneur, et faites le bien. Peut-être réussirez vous!"},{"n":2673,"s":22,"a":78,"t":"Et luttez pour Allah avec tout l'effort qu'Il mérite. C'est Lui qui vous a élus; et Il ne vous a imposé aucune gêne dans la religion, celle de votre père Abraham, lequel vous a déjà nommés «Musulmans» avant (ce Livre) et dans ce (Livre), afin que le Messager soit témoin contre vous, et que vous soyez vous-mêmes témoins contre les gens. Accomplissez donc la Salât, acquittez la Zakât et attachez-vous fortement à Allah. C'est Lui votre Maître. Quel Excellent Maître! Et quel Excellent Soutien!"},{"n":2674,"s":23,"a":1,"t":"Bienheureux sont certes les croyants,"},{"n":2675,"s":23,"a":2,"t":"ceux qui sont humbles dans leur Salât,"},{"n":2676,"s":23,"a":3,"t":"qui se détournent des futilités,"},{"n":2677,"s":23,"a":4,"t":"qui s'acquittent de la Zakât,"},{"n":2678,"s":23,"a":5,"t":"et qui préservent leurs sexes [de tout rapport],"},{"n":2679,"s":23,"a":6,"t":"si ce n'est qu'avec leurs épouses ou les esclaves qu'ils possèdent, car là vraiment, on ne peut les blâmer;"},{"n":2680,"s":23,"a":7,"t":"alors que ceux qui cherchent au-delà de ces limites sont des transgresseurs;"},{"n":2681,"s":23,"a":8,"t":"et qui veillent à la sauvegarde des dépôts confiés à eux et honorent leurs engagements,"},{"n":2682,"s":23,"a":9,"t":"et qui observent strictement leur Salât."},{"n":2683,"s":23,"a":10,"t":"Ce sont eux les héritiers,"},{"n":2684,"s":23,"a":11,"t":"qui hériteront le Paradis pour y demeurer éternellement."},{"n":2685,"s":23,"a":12,"t":"Nous avons certes créé l'homme d'un extrait d'argile."},{"n":2686,"s":23,"a":13,"t":"puis Nous en fîmes une goutte de sperme dans un reposoir solide."},{"n":2687,"s":23,"a":14,"t":"Ensuite, Nous avons fait du sperme une adhérence; et de l'adhérence Nous avons créé un embryon; puis, de cet embryon Nous avons créé des os et Nous avons revêtu les os de chair. Ensuite, Nous l'avons transformé en une tout autre création. Gloire à Allah le Meilleur des créateurs!"},{"n":2688,"s":23,"a":15,"t":"Et puis, après cela vous mourrez."},{"n":2689,"s":23,"a":16,"t":"Et puis au Jour de la Résurrection vous serez ressuscités."},{"n":2690,"s":23,"a":17,"t":"Nous avons créé, au-dessus de vous, sept cieux. Et Nous ne sommes pas inattentifs à la création."},{"n":2691,"s":23,"a":18,"t":"Et Nous avons fait descendre l'eau du ciel avec mesure. Puis Nous l'avons maintenue dans la terre, cependant que Nous sommes bien Capable de la faire disparaître."},{"n":2692,"s":23,"a":19,"t":"Avec elle, Nous avons produit pour vous des jardins de palmiers et de vignes, dans lesquels vous avez des fruits abondants et desquels vous mangez,"},{"n":2693,"s":23,"a":20,"t":"ainsi qu'un arbre (l'olivier) qui pousse au Mont Sinaî, en produisant l'huile servant à oindre et où les mangeurs trempent leur pain."},{"n":2694,"s":23,"a":21,"t":"Vous avez certes dans les bestiaux, un sujet de méditation. Nous vous donnons à boire de ce qu'ils ont dans le ventre, et vous y trouvez également maintes utilités; et vous vous en nourrissez."},{"n":2695,"s":23,"a":22,"t":"Sur eux ainsi que sur des vaisseaux vous êtes transportés."},{"n":2696,"s":23,"a":23,"t":"Nous envoyâmes Noé vers son peuple. Il dit: «O mon peuple, adorez Allah. Vous n'avez pas d'autre divinité en dehors de Lui. Ne [Le] craignez-vous pas?»"},{"n":2697,"s":23,"a":24,"t":"Alors les notables de son peuple qui avaient mécru dirent: «Celui-ci n'est qu'un être humain comme vous voulant se distinguer à votre détriment. Si Allah avait voulu, ce sont des Anges qu'Il aurait fait descendre. Jamais nous n'avons entendu cela chez nos ancêtres les plus reculés."},{"n":2698,"s":23,"a":25,"t":"Ce n'est en vérité qu'un homme atteint de folie, observez-le donc durant quelque temps."},{"n":2699,"s":23,"a":26,"t":"Il dit: «Seigneur! Apporte-moi secours parce qu'ils me traitent de menteur»."},{"n":2700,"s":23,"a":27,"t":"Nous lui révélâmes: «Construis l'arche sous Nos yeux et selon Notre révélation. Et quand Notre commandement viendra et que le four bouillonnera, achemine là-dedans un couple de chaque espèce, ainsi que ta famille, sauf ceux d'entre eux contre qui la parole a déjà été prononcée; et ne t'adresse pas à Moi au sujet des injustes, car ils seront fatalement noyés."},{"n":2701,"s":23,"a":28,"t":"Et lorsque tu seras installé, toi et ceux qui sont avec toi, dans l'arche, dis: «Louange à Allah qui nous a sauvés du peuple des injustes»."},{"n":2702,"s":23,"a":29,"t":"Et dis: «Seigneur, fais-moi débarquer d'un débarquement béni. Tu es Celui qui procure le meilleur débarquement»."},{"n":2703,"s":23,"a":30,"t":"Voilà bien là des signes. Nous sommes certes Celui qui éprouve."},{"n":2704,"s":23,"a":31,"t":"Puis, après eux, Nous avons créé d'autres générations,"},{"n":2705,"s":23,"a":32,"t":"Nous envoyâmes parmi elles un Messager [issu] d'elles pour leur dire: «Adorez Allah. Vous n'avez pas d'autre divinité en dehors de Lui. Ne le craignez-vous pas?»"},{"n":2706,"s":23,"a":33,"t":"Les notables de son peuple qui avaient mécru et traité de mensonge la rencontre de l'au-delà, et auxquels Nous avions accordé le luxe dans la vie présente, dirent: «Celui-ci n'est qu'un être humain comme vous, mangeant de ce que vous mangez, et buvant de ce que vous buvez."},{"n":2707,"s":23,"a":34,"t":"Si vous obéissez à un homme comme vous, vous serez alors perdants."},{"n":2708,"s":23,"a":35,"t":"Vous promet-il, quand vous serez morts, et devenus poussière et ossements, que vous serez sortis [de vos sépulcres]?"},{"n":2709,"s":23,"a":36,"t":"Loin, loin, ce qu'on vous promet!"},{"n":2710,"s":23,"a":37,"t":"Ce n'est là que notre vie présente: nous mourons et nous vivons; et nous ne serons jamais ressuscités."},{"n":2711,"s":23,"a":38,"t":"Ce n'est qu'un homme qui forge un mensonge contre Allah; et nous ne croirons pas en lui»."},{"n":2712,"s":23,"a":39,"t":"Il dit: «Seigneur! Apporte-moi secours parce qu'ils me traitent de menteur»."},{"n":2713,"s":23,"a":40,"t":"[Allah] dit: «Oui, bientôt ils en viendront aux regrets»."},{"n":2714,"s":23,"a":41,"t":"Le cri, donc, les saisit en toute justice; puis Nous les rendîmes semblables à des débris emportés par le torrent. Que disparaissent à jamais les injustes!"},{"n":2715,"s":23,"a":42,"t":"Puis après eux Nous avons créé d'autres générations."},{"n":2716,"s":23,"a":43,"t":"Nulle communauté ne peut avancer ni reculer son terme."},{"n":2717,"s":23,"a":44,"t":"Ensuite, Nous envoyâmes successivement Nos messagers. Chaque fois qu'un messager se présentait à sa communauté, ils le traitaient de menteur. Et Nous les fîmes succéder les unes aux autres [dans la destruction], et Nous en fîmes des thèmes de récits légendaires. Que disparaissent à jamais les gens qui ne croient pas!"},{"n":2718,"s":23,"a":45,"t":"Ensuite, Nous envoyâmes Moïse et son frère Aaron avec Nos prodiges et une preuve évidente,"},{"n":2719,"s":23,"a":46,"t":"vers Pharaon et ses notables mais ceux-ci s'enflèrent d'orgueil: ils étaient des gens hautains."},{"n":2720,"s":23,"a":47,"t":"Ils dirent: «Croirons-nous en deux hommes comme nous dont les congénères sont nos esclaves»."},{"n":2721,"s":23,"a":48,"t":"Ils les traitèrent [tous deux] de menteurs et ils furent donc parmi les anéantis."},{"n":2722,"s":23,"a":49,"t":"Et Nous avions apporté le Livre à Moïse afin qu'ils se guident."},{"n":2723,"s":23,"a":50,"t":"Et Nous fîmes du fils de Marie, ainsi que de sa mère, un prodige; et Nous donnâmes à tous deux asile sur une colline bien stable et dotée d'une source."},{"n":2724,"s":23,"a":51,"t":"O Messagers! Mangez de ce qui est permis et agréable et faites du bien. Car Je sais parfaitement ce que vous faites."},{"n":2725,"s":23,"a":52,"t":"Cette communauté, la vôtre, est une seule communauté, tandis que Je suis votre Seigneur. Craignez-Moi donc»."},{"n":2726,"s":23,"a":53,"t":"Mais ils se sont divisés en sectes, chaque secte exultant de ce qu'elle détenait."},{"n":2727,"s":23,"a":54,"t":"Laisse-les dans leur égarement pour un certain temps."},{"n":2728,"s":23,"a":55,"t":"Pensent-ils que ce que Nous leur accordons, en biens et en enfants,"},{"n":2729,"s":23,"a":56,"t":"[soit une avance] que Nous Nous empressons de leur faire sur les biens [de la vie future]? Au contraire, ils n'en sont pas conscients."},{"n":2730,"s":23,"a":57,"t":"Ceux qui, de la crainte de leur Seigneur, sont pénétrés,"},{"n":2731,"s":23,"a":58,"t":"qui croient aux versets de leur Seigneur,"},{"n":2732,"s":23,"a":59,"t":"qui n'associent rien à leur Seigneur,"},{"n":2733,"s":23,"a":60,"t":"qui donnent ce qu'ils donnent, tandis que leurs cœurs sont pleins de crainte [à la pensée] qu'ils doivent retourner à leur Seigneur."},{"n":2734,"s":23,"a":61,"t":"Ceux-là se précipitent vers les bonnes actions et sont les premiers à les accomplir."},{"n":2735,"s":23,"a":62,"t":"Nous n'imposons à personne que selon sa capacité. Et auprès de Nous existe un Livre qui dit la vérité, et ils ne seront pas lésés."},{"n":2736,"s":23,"a":63,"t":"Mais leurs cœurs restent dans l'ignorance à l'égard de cela [le Coran]. [En outre] ils ont d'autres actes (vils) qu'ils accomplissent,"},{"n":2737,"s":23,"a":64,"t":"jusqu'à ce que par le châtiment Nous saisissions les plus aisés parmi eux et voilà qu'ils crient au secours."},{"n":2738,"s":23,"a":65,"t":"«Ne criez pas aujourd'hui. Nul ne vous protègera contre Nous."},{"n":2739,"s":23,"a":66,"t":"Mes versets vous étaient récités auparavant; mais vous vous [en] détourniez,"},{"n":2740,"s":23,"a":67,"t":"s'enflant d'orgueil, et vous les dénigriez au cours de vos veillées»."},{"n":2741,"s":23,"a":68,"t":"Ne méditent-ils donc pas sur la parole (le Coran)? Ou est-ce que leur est venu ce qui n'est jamais venu à leurs premiers ancêtres?"},{"n":2742,"s":23,"a":69,"t":"Ou n'ont-ils pas connu leur Messager, au point de le renier?"},{"n":2743,"s":23,"a":70,"t":"Ou diront-ils: «Il est fou?» Au contraire, c'est la vérité qu'il leur a apportée. Et la plupart d'entre eux dédaignent la vérité."},{"n":2744,"s":23,"a":71,"t":"Si la vérité était conforme à leurs passions, les cieux et la terre et ceux qui s'y trouvent seraient, certes, corrompus. Au contraire, Nous leur avons donné leur rappel. Mais ils s'en détournent."},{"n":2745,"s":23,"a":72,"t":"Ou leur demandes-tu une rétribution? Mais la rétribution de ton Seigneur est meilleure. Et c'est Lui, le Meilleur des pourvoyeurs."},{"n":2746,"s":23,"a":73,"t":"Et tu les appelles, certes, vers le droit chemin."},{"n":2747,"s":23,"a":74,"t":"Or, ceux qui ne croient pas à l'au-delà sont bien écartés de ce chemin."},{"n":2748,"s":23,"a":75,"t":"Si Nous leur faisions miséricorde et écartions d'eux le mal, ils persisteraient certainement dans leur transgression, confus et hésitants."},{"n":2749,"s":23,"a":76,"t":"Nous les avons certes saisis du châtiment, mais ils ne se sont pas soumis à leur Seigneur; de même qu'ils ne [Le] supplient point,"},{"n":2750,"s":23,"a":77,"t":"jusqu'au jour où Nous ouvrirons sur eux une porte au dur châtiment, et voilà qu'ils en seront désespérés."},{"n":2751,"s":23,"a":78,"t":"Et c'est Lui qui a créé pour vous l'ouïe, les yeux et les cœurs. Mais vous êtes rarement reconnaissants."},{"n":2752,"s":23,"a":79,"t":"C'est Lui qui vous a répandus sur la terre, et c'est vers Lui que vous serez rassemblés."},{"n":2753,"s":23,"a":80,"t":"Et c'est Lui qui donne la vie et qui donne la mort; et l'alternance de la nuit et du jour dépend de Lui. Ne raisonnerez-vous donc pas?"},{"n":2754,"s":23,"a":81,"t":"Ils ont plutôt tenu les mêmes propos que les anciens."},{"n":2755,"s":23,"a":82,"t":"Ils ont dit: «lorsque nous serons morts et que nous serons poussière et ossements, serons-nous vraiment ressuscités?"},{"n":2756,"s":23,"a":83,"t":"On nous a promis cela, ainsi qu'à nos ancêtres auparavant; ce ne sont que de vieilles sornettes»."},{"n":2757,"s":23,"a":84,"t":"Dis: «A qui appartient la terre et ceux qui y sont? si vous savez»."},{"n":2758,"s":23,"a":85,"t":"Ils diront: «A Allah». Dis: «Ne vous souvenez-vous donc pas?»"},{"n":2759,"s":23,"a":86,"t":"Dis: «Qui est le Seigneur des sept cieux et le Seigneur du Trône sublime?»"},{"n":2760,"s":23,"a":87,"t":"Ils diront: [ils appartiennent] «A Allah». Dis: «Ne craignez-vous donc pas?»"},{"n":2761,"s":23,"a":88,"t":"Dis: «Qui détient dans sa main la royauté absolue de toute chose, et qui protège et n'a pas besoin d'être protégé? [Dites], si vous le savez!»"},{"n":2762,"s":23,"a":89,"t":"Ils diront: «Allah». Dis: «Comment donc se fait-il que vous soyez ensorcelés?» [au point de ne pas croire en Lui]."},{"n":2763,"s":23,"a":90,"t":"Nous leur avons plutôt apporté la vérité et ils sont assurément des menteurs."},{"n":2764,"s":23,"a":91,"t":"Allah ne S'est point attribué d'enfant et il n'existe point de divinité avec Lui; sinon, chaque divinité s'en irait avec ce qu'elle a créé, et certaines seraient supérieures aux autres. (Gloire et pureté) à Allah! Il est Supérieur à tout ce qu'ils décrivent."},{"n":2765,"s":23,"a":92,"t":"[Il est] Connaisseur de toute chose visible et invisible! Il est bien au-dessus de ce qu'ils [Lui] associent!"},{"n":2766,"s":23,"a":93,"t":"Dis: «Seigneur, si jamais Tu me montres ce qui leur est promis;"},{"n":2767,"s":23,"a":94,"t":"alors, Seigneur, ne me place pas parmi les gens injustes."},{"n":2768,"s":23,"a":95,"t":"Nous sommes Capable, certes, de te montrer ce que Nous leur promettons."},{"n":2769,"s":23,"a":96,"t":"Repousse le mal par ce qui est meilleur. Nous savons très bien ce qu'ils décrivent."},{"n":2770,"s":23,"a":97,"t":"Et dis: «Seigneur, je cherche Ta protection, contre les incitations des diables."},{"n":2771,"s":23,"a":98,"t":"et je cherche Ta protection, Seigneur, contre leur présence auprès de moi»."},{"n":2772,"s":23,"a":99,"t":"...Puis, lorsque la mort vient à l'un deux, il dit: «Mon Seigneur! Fais-moi revenir (sur terre),"},{"n":2773,"s":23,"a":100,"t":"afin que je fasse du bien dans ce que je délaissais». Non, c'est simplement une parole qu'il dit. Derrière eux, cependant, il y a une barrière, jusqu'au jour où ils seront ressuscités»."},{"n":2774,"s":23,"a":101,"t":"Puis quand on soufflera dans la Trompe, il n'y aura plus de parenté entre eux ce jour là, et ils ne se poseront pas de questions."},{"n":2775,"s":23,"a":102,"t":"Ceux dont la balance est lourde seront les bienheureux;"},{"n":2776,"s":23,"a":103,"t":"et ceux dont la balance est légère seront ceux qui ont ruiné leurs propres âmes et ils demeureront éternellement dans l'Enfer."},{"n":2777,"s":23,"a":104,"t":"Le feu brûlera leurs visages et ils auront les lèvres crispées."},{"n":2778,"s":23,"a":105,"t":"«Mes versets ne vous étaient-ils pas récités et vous les traitiez alors de mensonges?»"},{"n":2779,"s":23,"a":106,"t":"Ils dirent: «Seigneur! Notre malheur nous a vaincus, et nous étions des gens égarés."},{"n":2780,"s":23,"a":107,"t":"Seigneur, fais nous-en sortir! Et si nous récidivons, nous serons alors des injustes»."},{"n":2781,"s":23,"a":108,"t":"Il dit: «Soyez-y refoulés (humiliés) et ne Me parlez plus»."},{"n":2782,"s":23,"a":109,"t":"Il y eut un groupe de Mes serviteurs qui dirent: «Seigneur, nous croyons; pardonne-nous donc et fais-nous miséricorde, car Tu es le meilleur des Miséricordieux»"},{"n":2783,"s":23,"a":110,"t":"mais vous les avez pris en raillerie jusqu'à oublier de M'invoquer, et vous vous riiez d'eux."},{"n":2784,"s":23,"a":111,"t":"Vraiment, Je les ai récompensés aujourd'hui pour ce qu'ils ont enduré; et ce sont eux les triomphants."},{"n":2785,"s":23,"a":112,"t":"Il dira: «Combien d'années êtes-vous restés sur terre?»"},{"n":2786,"s":23,"a":113,"t":"Ils diront: «Nous y avons demeuré un jour, ou une partie d'un jour. Interroge donc ceux qui comptent.»"},{"n":2787,"s":23,"a":114,"t":"Il dira: «Vous n'y avez demeuré que peu [de temps], si seulement vous saviez."},{"n":2788,"s":23,"a":115,"t":"Pensiez-vous que Nous vous avions créés sans but, et que vous ne seriez pas ramenés vers Nous?»"},{"n":2789,"s":23,"a":116,"t":"Que soit exalté Allah, le vrai Souverain! Pas de divinité en dehors de Lui, le Seigneur du Trône sublime!"},{"n":2790,"s":23,"a":117,"t":"Et quiconque invoque avec Allah une autre divinité, sans avoir la preuve évidente [de son existence], aura à en rendre compte à son Seigneur. En vérité, les mécréants, ne réussiront pas."},{"n":2791,"s":23,"a":118,"t":"Et dis: «Seigneur, pardonne et fais miséricorde. C'est Toi le Meilleur des miséricordieux»."},{"n":2792,"s":24,"a":1,"t":"Voici une Sourate que Nous avons fait descendre et que Nous avons imposée, et Nous y avons fait descendre des versets explicites afin que vous vous souveniez»."},{"n":2793,"s":24,"a":2,"t":"La fornicatrice et le fornicateur, fouettez-les chacun de cent coups de fouet. Et ne soyez point pris de pitié pour eux dans l'exécution de la loi d'Allah - si vous croyez en Allah et au Jour dernier. Et qu'un groupe de croyants assiste à leur punition."},{"n":2794,"s":24,"a":3,"t":"Le fornicateur n'épousera qu'une fornicatrice ou une associatrice. Et la fornicatrice ne sera épousée que par un fornicateur ou un associateur; et cela a été interdit aux croyants."},{"n":2795,"s":24,"a":4,"t":"Et ceux qui lancent des accusations contre des femmes chastes sans produire par la suite quatre témoins, fouettez-les de quatre-vingts coups de fouet, et n'acceptez plus jamais leur témoignage. Et ceux-là sont les pervers,"},{"n":2796,"s":24,"a":5,"t":"à l'exception de ceux qui, après cela, se repentent et se réforment, car Allah est Pardonneur et Miséricordieux."},{"n":2797,"s":24,"a":6,"t":"Et quant à ceux qui lancent des accusations contre leurs propres épouses, sans avoir d'autres témoins qu'eux-mêmes, le témoignage de l'un d'eux doit être une quadruple attestation par Allah qu'il est du nombre des véridiques,"},{"n":2798,"s":24,"a":7,"t":"et la cinquième [attestation] est «que la malédiction d'Allah tombe sur lui s'il est du nombre des menteurs»."},{"n":2799,"s":24,"a":8,"t":"Et on ne lui infligera pas le châtiment [de la lapidation] si elle atteste quatre fois par Allah qu'il [son mari] est certainement du nombre des menteurs,"},{"n":2800,"s":24,"a":9,"t":"et la cinquième [attestation] est que la colère d'Allah soit sur elle, s'il était du nombre des véridiques."},{"n":2801,"s":24,"a":10,"t":"Et, n'étaient la grâce d'Allah sur vous et Sa miséricorde...! Allah est Grand Accueillant au repentir et Sage!"},{"n":2802,"s":24,"a":11,"t":"Ceux qui sont venus avec la calomnie sont un groupe d'entre vous. Ne pensez pas que c'est un mal pour vous, mais plutôt, c'est un bien pour vous. A chacun d'eux ce qu'il s'est acquis comme péché. Celui d'entre eux qui s'est chargé de la plus grande part aura un énorme châtiment."},{"n":2803,"s":24,"a":12,"t":"Pourquoi, lorsque vous l'avez entendue [cette calomnie], les croyants et les croyantes n'ont-ils pas, en eux-mêmes, conjecturé favorablement, et n'ont-ils pas dit: «C'est une calomnie évidente?»"},{"n":2804,"s":24,"a":13,"t":"Pourquoi n'ont-ils pas produit [à l'appui de leurs accusations] quatre témoins? S'ils ne produisent pas de témoins, alors ce sont eux, auprès d'Allah, les menteurs."},{"n":2805,"s":24,"a":14,"t":"N'eussent-été la grâce d'Allah sur vous et Sa miséricorde ici-bas comme dans l'au-delà, un énorme châtiment vous aurait touchés pour cette (calomnie) dans laquelle vous vous êtes lancés,"},{"n":2806,"s":24,"a":15,"t":"quand vous colportiez la nouvelle avec vos langues et disiez de vos bouches ce dont vous n'aviez aucun savoir; et vous le comptiez comme insignifiant alors qu'auprès d'Allah cela est énorme."},{"n":2807,"s":24,"a":16,"t":"Et pourquoi, lorsque vous l'entendiez, ne disiez-vous pas: «Nous ne devons pas en parler. Gloire à Toi (ô Allah)! C'est une énorme calomnie»?"},{"n":2808,"s":24,"a":17,"t":"Allah vous exhorte à ne plus jamais revenir à une chose pareille si vous êtes croyants."},{"n":2809,"s":24,"a":18,"t":"Allah vous expose clairement les versets et Allah est Omniscient et Sage."},{"n":2810,"s":24,"a":19,"t":"Ceux qui aiment que la turpitude se propage parmi les croyants auront un châtiment douloureux, ici-bas comme dans l'au-delà. Allah sait, et vous, vous ne savez pas."},{"n":2811,"s":24,"a":20,"t":"Et n'eussent été la grâce d'Allah sur vous et Sa miséricorde et (n'eût été) qu'Allah est Compatissant et Miséricordieux..."},{"n":2812,"s":24,"a":21,"t":"O vous qui avez cru! Ne suivez pas les pas du Diable. Quiconque suit les pas du Diable, [sachez que] celui-ci ordonne la turpitude et le blâmable. Et n'eussent été la grâce d'Allah envers vous et Sa miséricorde, nul d'entre vous n'aurait jamais été pur. Mais Allah purifie qui Il veut. Et Allah est Audient et Omniscient."},{"n":2813,"s":24,"a":22,"t":"Et que les détenteurs de richesse et d'aisance parmi vous, ne jurent pas de ne plus faire des dons aux proches, aux pauvres, et à ceux qui émigrent dans le sentier d'Allah. Qu'ils pardonnent et absolvent. N'aimez-vous pas qu'Allah vous pardonne? et Allah est Pardonneur et Miséricordieux!"},{"n":2814,"s":24,"a":23,"t":"Ceux qui lancent des accusations contre des femmes vertueuses, chastes [qui ne pensent même pas à commettre la turpitude] et croyantes sont maudits ici-bas comme dans l'au-delà; et ils auront un énorme châtiment,"},{"n":2815,"s":24,"a":24,"t":"Le jour où leurs langues, leurs mains et leurs pieds témoigneront contre eux de ce qu'ils faisaient."},{"n":2816,"s":24,"a":25,"t":"Ce Jour-là, Allah leur donnera leur pleine et vraie rétribution; et ils sauront que c'est Allah qui est le Vrai de toute évidence."},{"n":2817,"s":24,"a":26,"t":"Les mauvaises [femmes] aux mauvais [hommes], et les mauvais [hommes] aux mauvaises [femmes]. De même, les bonnes [femmes] aux bons [hommes], et les bons [hommes] aux bonnes [femmes]. Ceux-là sont innocents de ce que les autres disent. Ils ont un pardon et une récompense généreuse."},{"n":2818,"s":24,"a":27,"t":"O vous qui croyez! N'entrez pas dans des maisons autres que les vôtres avant de demander la permission [d'une façon délicate] et de saluer leurs habitants. Cela est meilleur pour vous. Peut-être vous souvenez-vous."},{"n":2819,"s":24,"a":28,"t":"Si vous n'y trouvez personne, alors n'y entrez pas avant que permission vous soit donnée. Et si on vous dit: «Retournez», eh bien, retournez. Cela est plus pur pour vous. Et Allah, de ce que vous faites est Omniscient."},{"n":2820,"s":24,"a":29,"t":"Nul grief contre vous à entrer dans des maisons inhabitées où se trouve un bien pour vous. Allah sait ce que vous divulguez et ce que vous cachez."},{"n":2821,"s":24,"a":30,"t":"Dis aux croyants de baisser leurs regards et de garder leur chasteté. C'est plus pur pour eux. Allah est, certes, Parfaitement Connaisseur de ce qu'ils font."},{"n":2822,"s":24,"a":31,"t":"Et dis aux croyantes de baisser leurs regards, de garder leur chasteté, et de ne montrer de leurs atours que ce qui en paraît et qu'elles rabattent leur voile sur leurs poitrines; et qu'elles ne montrent leurs atours qu'à leurs maris, ou à leurs pères, ou aux pères de leurs maris, ou à leurs fils, ou aux fils de leurs maris, ou à leurs frères, ou aux fils de leurs frères, ou aux fils de leurs sœurs, ou aux femmes musulmanes, ou aux esclaves qu'elles possèdent, ou aux domestiques mâles impuissants, ou aux garçons impubères qui ignorent tout des parties cachées des femmes. Et qu'elles ne frappent pas avec leurs pieds de façon que l'on sache ce qu'elles cachent de leurs parures. Et repentez-vous tous devant Allah, ô croyants, afin que vous récoltiez le succès."},{"n":2823,"s":24,"a":32,"t":"Mariez les célibataires d'entre vous et les gens de bien parmi vos esclaves, hommes et femmes. S'ils sont besogneux, Allah les rendra riches par Sa grâce. Car (la grâce d') Allah est immense et Il est Omniscient."},{"n":2824,"s":24,"a":33,"t":"Et que ceux qui n'ont pas de quoi se marier, cherchent à rester chastes jusqu'à ce qu'Allah les enrichisse par Sa grâce. Ceux de vos esclaves qui cherchent un contrat d'affranchissement, concluez ce contrat avec eux si vous reconnaissez du bien en eux; et donnez-leur des biens d'Allah qu'Il vous a accordés. Et dans votre recherche des profits passagers de la vie présente, ne contraignez pas vos femmes esclaves à la prostitution, si elles veulent rester chastes. Si on les y contraint, Allah leur accorde après qu'elles aient été contraintes, Son pardon et Sa miséricorde."},{"n":2825,"s":24,"a":34,"t":"Nous avons effectivement fait descendre vers vous des versets clairs, donnant une parabole de ceux qui ont vécu avant vous, et une exhortation pour les pieux!"},{"n":2826,"s":24,"a":35,"t":"Allah est la Lumière des cieux et de la terre. Sa lumière est semblable à une niche où se trouve une lampe. La lampe est dans un (récipient de) cristal et celui-ci ressemble à un astre de grand éclat; son combustible vient d'un arbre béni: un olivier ni oriental ni occidental dont l'huile semble éclairer sans même que le feu la touche. Lumière sur lumière. Allah guide vers Sa lumière qui Il veut. Allah propose aux hommes des paraboles et Allah est Omniscient."},{"n":2827,"s":24,"a":36,"t":"Dans des maisons [des mosquées] qu'Allah a permis que l'on élève, et où Son Nom est invoqué; Le glorifient en elles matin et après-midi,"},{"n":2828,"s":24,"a":37,"t":"des hommes que ni le négoce, ni le troc ne distraient de l'invocation d'Allah, de l'accomplissement de la Salât et de l'acquittement de la Zakât, et qui redoutent un Jour où les cœurs seront bouleversés ainsi que les regards."},{"n":2829,"s":24,"a":38,"t":"Afin qu'Allah les récompense de la meilleure façon pour ce qu'ils ont fait [de bien]. Et Il leur ajoutera de Sa grâce. Allah attribue à qui Il veut sans compter."},{"n":2830,"s":24,"a":39,"t":"Quant à ceux qui ont mécru, leurs actions sont comme un mirage dans une plaine désertique que l'assoiffé prend pour de l'eau. Puis quand il y arrive, il s'aperçoit que ce n'était rien; mais y trouve Allah qui lui règle son compte en entier, car Allah est prompt à compter."},{"n":2831,"s":24,"a":40,"t":"[Les actions des mécréants] sont encore semblables à des ténèbres sur une mer profonde: des vagues la recouvrent, [vagues] au dessus desquelles s'élèvent [d'autres] vagues, sur lesquelles il y a [d'épais] nuages. Ténèbres [entassées] les unes au-dessus des autres. Quand quelqu'un étend la main, il ne la distingue presque pas. Celui qu'Allah prive de lumière n'a aucune lumière."},{"n":2832,"s":24,"a":41,"t":"N'as-tu pas vu qu'Allah est glorifié par tous ceux qui sont dans les cieux et la terre; ainsi que par les oiseaux déployant leurs ailes? Chacun, certes, a appris sa façon de L'adorer et de Le glorifier. Allah sait parfaitement ce qu'ils font."},{"n":2833,"s":24,"a":42,"t":"C'est à Allah qu'appartient la royauté des cieux et de la terre. Et vers Allah sera le retour final."},{"n":2834,"s":24,"a":43,"t":"N'as-tu pas vu qu'Allah pousse les nuages? Ensuite Il les réunit et Il en fait un amas, et tu vois la pluie sortir de son sein. Et Il fait descendre du ciel, de la grêle [provenant] des nuages [comparables] à des montagnes. Il en frappe qui Il veut et l'écarte de qui Il veut. Peu s'en faut que l'éclat de son éclair ne ravisse la vue."},{"n":2835,"s":24,"a":44,"t":"Allah fait alterner la nuit et le jour. Il y a là un sujet de réflexion pour ceux qui ont des yeux."},{"n":2836,"s":24,"a":45,"t":"Et Allah a créé d'eau tout animal. Il y en a qui marche sur le ventre, d'autres marchent sur deux pattes, et d'autres encore marchent sur quatre. Allah crée ce qu'Il veut et Allah est Omnipotent."},{"n":2837,"s":24,"a":46,"t":"Nous avons certes fait descendre des versets explicites. Et Allah guide qui Il veut vers un droit chemin."},{"n":2838,"s":24,"a":47,"t":"Et ils disent: «Nous croyons en Allah et au messager et nous obéissons». Puis après cela, une partie d'entre eux fait volte-face. Ce ne sont point ceux-là les croyants."},{"n":2839,"s":24,"a":48,"t":"Et quand on les appelle vers Allah et Son messager pour que celui-ci juge parmi eux, voilà que quelques-uns d'entre eux s'éloignent."},{"n":2840,"s":24,"a":49,"t":"Mais s'ils ont le droit en leur faveur, ils viennent à lui, soumis."},{"n":2841,"s":24,"a":50,"t":"Y a-t-il une maladie dans leurs cœurs? ou doutent-ils ? ou craignent-ils qu'Allah les opprime, ainsi que Son messager? Non!... mais ce sont eux les injustes."},{"n":2842,"s":24,"a":51,"t":"La seule parole des croyants, quand on les appelle vers Allah et Son messager, pour que celui-ci juge parmi eux, est: «Nous avons entendu et nous avons obéi». Et voilà ceux qui réussissent."},{"n":2843,"s":24,"a":52,"t":"Et quiconque obéit à Allah et à Son messager, et craint Allah et Le redoute... alors, voilà ceux qui récoltent le succès."},{"n":2844,"s":24,"a":53,"t":"Et ils jurent par Allah en serments solennels que si tu le leur ordonnais, ils sortiraient à coup sûr (au combat). Dis: «Ne jurez donc pas. [Votre] obéissance [verbale] est bien connue. Allah est Parfaitement Connaisseur de ce que vous faites»."},{"n":2845,"s":24,"a":54,"t":"Dis: «Obéissez à Allah et obéissez au messager. S'ils se détournent, ...il [le messager] n'est alors responsable que de ce dont il est chargé; et vous assumez ce dont vous êtes chargés. Et si vous lui obéissez, vous serez bien guidés». Et il n'incombe au messager que de transmettre explicitement (son message)."},{"n":2846,"s":24,"a":55,"t":"Allah a promis à ceux d'entre vous qui ont cru et fait les bonnes œuvres qu'Il leur donnerait la succession sur terre comme Il l'a donnée à ceux qui les ont précédés. Il donnerait force et suprématie à leur religion qu'Il a agréée pour eux. Il leur changerait leur ancienne peur en sécurité. Ils M'adorent et ne M'associent rien et celui qui mécroit par la suite, ce sont ceux-là les pervers."},{"n":2847,"s":24,"a":56,"t":"Accomplissez la Salât, acquittez la Zakât et obéissez au messager, afin que vous ayez la miséricorde."},{"n":2848,"s":24,"a":57,"t":"Ne pense point que ceux qui ne croient pas puissent s'opposer à l'autorité d'Allah sur terre. Le Feu sera leur refuge. Quelle mauvaise destination."},{"n":2849,"s":24,"a":58,"t":"O vous qui avez-cru! Que les esclaves que vous possédez vous demandent permission avant d'entrer, ainsi que ceux des vôtres qui n'ont pas encore atteint la puberté, à trois moments: avant la Salât de l'aube, à midi quand vous enlevez vos vêtements, ainsi qu'après la Salât de la nuit; trois occasions de vous dévêtir. En dehors de ces moments, nul reproche ni à vous ni à eux d'aller et venir, les uns chez les autres. C'est ainsi qu'Allah vous expose clairement Ses versets, et Allah est Omniscient et Sage."},{"n":2850,"s":24,"a":59,"t":"Et quand les enfants parmi vous atteignent la puberté, qu'ils demandent permission avant d'entrer, comme font leurs aînés. C'est ainsi qu'Allah vous expose clairement Ses versets, et Allah est Omniscient et Sage."},{"n":2851,"s":24,"a":60,"t":"Et quant aux femmes atteintes par la ménopause qui n'espèrent plus le mariage, nul reproche à elles d'enlever leurs vêtements de [sortie], sans cependant exhiber leurs atours et si elle cherchent la chasteté c'est mieux pour elles. Allah est Audient et Omniscient."},{"n":2852,"s":24,"a":61,"t":"Il n'y a pas d'empêchement à l'aveugle, au boiteux, au malade, ainsi qu'à vous-mêmes de manger dans vos maisons, ou dans les maisons de vos pères, ou dans celles de vos mères, ou de vos frères, ou de vos sœurs, ou de vos oncles paternels, ou de vos tantes paternelles ou de vos oncles maternels, ou de vos tantes maternelles, ou dans celles dont vous possédez les clefs, ou chez vos amis. Nul empêchement à vous, non plus, de manger ensemble, ou séparément. Quand donc vous entrez dans des maisons, adressez-vous mutuellement des salutations venant d'Allah, bénies et agréables. C'est ainsi qu'Allah vous expose Ses versets, afin que vous compreniez."},{"n":2853,"s":24,"a":62,"t":"Les vrais croyants sont ceux qui croient en Allah et en Son messager, et qui, lorsqu'ils sont en sa compagnie pour une affaire d'intérêt général, ne s'en vont pas avant de lui avoir demandé la permission. Ceux qui te demandent cette permission sont ceux qui croient en Allah et en Son messager. Si donc ils te demandent la permission pour une affaire personnelle, donne-la à qui tu veux d'entre eux; et implore le pardon d'Allah pour eux, car Allah est Pardonneur et Miséricordieux."},{"n":2854,"s":24,"a":63,"t":"Ne considérez pas l'appel du messager comme un appel que vous vous adresseriez les uns aux autres. Allah connaît certes ceux des vôtres qui s'en vont secrètement en s'entrecachant. Que ceux, donc, qui s'opposent à son commandement prennent garde qu'une épreuve ne les atteigne, ou que ne les atteigne un châtiment douloureux."},{"n":2855,"s":24,"a":64,"t":"C'est à Allah, vraiment, qu'appartient tout ce qui est dans les cieux et sur la terre. Il sait parfaitement l'état dans lequel vous êtes, et le Jour où les hommes seront ramenés vers Lui, Il les informera alors de ce qu'ils œuvraient. Allah est Omniscient."},{"n":2856,"s":25,"a":1,"t":"Qu'on exalte la Bénédiction de Celui qui a fait descendre le Livre de Discernement sur Son serviteur, afin qu'il soit un avertisseur à l'univers."},{"n":2857,"s":25,"a":2,"t":"Celui à qui appartient la royauté des cieux et de la terre, qui ne S'est point attribué d'enfant, qui n'a point d'associé en Sa royauté et qui a créé toute chose en lui donnant ses justes proportions."},{"n":2858,"s":25,"a":3,"t":"Mais ils ont adopté en dehors de Lui des divinités qui, étant elles-mêmes créées, ne créent rien, et qui ne possèdent la faculté de faire ni le mal ni le bien pour elles-mêmes, et qui ne sont maîtresses ni de la mort, ni de la vie, ni de la résurrection."},{"n":2859,"s":25,"a":4,"t":"Les mécréants disent: «Tout ceci n'est qu'un mensonge qu'il (Muhammad) a inventé, et où d'autres gens l'ont aidé». Or, ils commettent là une injustice et un mensonge."},{"n":2860,"s":25,"a":5,"t":"Et ils disent: «Ce sont des contes d'anciens qu'il se fait écrire! On les lui dicte matin et soir!»"},{"n":2861,"s":25,"a":6,"t":"Dis: «L'a fait descendre Celui qui connaît les secrets dans les cieux et la terre. Et Il est Pardonneur et Miséricordieux."},{"n":2862,"s":25,"a":7,"t":"Et ils disent: «Qu'est-ce donc que ce Messager qui mange de la nourriture et circule dans les marchés? Que n'a-t-on fait descendre vers lui un Ange qui eût été avertisseur en sa compagnie?"},{"n":2863,"s":25,"a":8,"t":"Ou que ne lui a-t-on lancé un trésor? Ou que n'a-t-il un jardin à lui, dont il pourrait manger (les fruits)?» Les injustes disent: «Vous ne suivez qu'un homme ensorcelé»."},{"n":2864,"s":25,"a":9,"t":"Vois à quoi ils te comparent! Ils se sont égarés. Ils ne pourront trouver aucun chemin."},{"n":2865,"s":25,"a":10,"t":"Béni soit Celui qui, s'Il le veut, t'accordera bien mieux que cela: des Jardins sous lesquels coulent les ruisseaux; et Il t'assignera des châteaux."},{"n":2866,"s":25,"a":11,"t":"Mais ils ont plutôt qualifié l'Heure de mensonge. Nous avons cependant préparé, pour quiconque qualifie l'Heure de mensonge, une Flamme brûlante."},{"n":2867,"s":25,"a":12,"t":"Lorsque de loin elle les voit, ils entendront sa fureur et ses pétillements."},{"n":2868,"s":25,"a":13,"t":"Et quand on les y aura jetés, dans un étroit réduit, les mains liées derrière le cou, ils souhaiteront alors leur destruction complète."},{"n":2869,"s":25,"a":14,"t":"«Aujourd'hui, ne souhaitez pas la destruction une seule fois, mais souhaitez-en plusieurs."},{"n":2870,"s":25,"a":15,"t":"Dis: «Est-ce mieux ceci? ou bien le Paradis éternel qui a été promis aux pieux, comme récompense et destination dernière?"},{"n":2871,"s":25,"a":16,"t":"Ils auront là tout ce qu'ils désireront et une demeure éternelle. C'est une promesse incombant à ton Seigneur."},{"n":2872,"s":25,"a":17,"t":"Et le jour où Il les rassemblera, eux et ceux qu'ils adoraient en dehors d'Allah, Il dira: «Est-ce vous qui avez égaré Mes serviteurs que voici, ou ont-ils eux-mêmes perdu le sentier?»"},{"n":2873,"s":25,"a":18,"t":"Ils diront: «Gloire à Toi! Il ne nous convenait nullement de prendre en dehors de Toi des patrons protecteurs mais Tu les as comblés de jouissance ainsi que leurs ancêtres au point qu'ils en ont oublié le livre du rappel [le Coran]. Et ils ont été des gens perdus»."},{"n":2874,"s":25,"a":19,"t":"«Ils vous ont démentis en ce que vous dites. Il n'y aura pour vous ni échappatoire ni secours (possible). Et quiconque des vôtres est injuste, Nous lui ferons goûter un grand châtiment»."},{"n":2875,"s":25,"a":20,"t":"Et Nous n'avons envoyé avant toi que des messagers qui mangeaient de la nourriture et circulaient dans les marchés. Et Nous avons fait de certains d'entre vous une épreuve pour les autres -endurerez-vous avec constance? - Et ton Seigneur demeure Clairvoyant."},{"n":2876,"s":25,"a":21,"t":"Et ceux qui n'espèrent pas Nous rencontrer disent: «Si seulement on avait fait descendre sur nous des Anges ou si nous pouvions voir notre Seigneur!» En effet, ils se sont enflés d'orgueil en eux-mêmes, et ont dépassé les limites de l'arrogance."},{"n":2877,"s":25,"a":22,"t":"Le jour où ils verront les Anges, ce ne sera pas une bonne nouvelle, ce jour-là, pour les injustes, ils (les Anges) diront: «Barrage totalement défendu»!"},{"n":2878,"s":25,"a":23,"t":"Nous avons considéré l'œuvre qu'ils ont accomplie et Nous l'avons réduite en poussière éparpillée."},{"n":2879,"s":25,"a":24,"t":"Les gens du Paradis seront, ce jour-là, en meilleure demeure et au plus beau lieu de repos."},{"n":2880,"s":25,"a":25,"t":"Et le jour où le ciel sera fendu par les nuages et qu'on fera descendre des Anges,"},{"n":2881,"s":25,"a":26,"t":"ce jour-là, la vraie royauté appartient au Tout Miséricordieux, et ce sera un Jour difficile aux infidèles."},{"n":2882,"s":25,"a":27,"t":"Le jour où l'injuste se mordra les deux mains et dira: «[Hélas pour moi!] Si seulement j'avais suivi chemin avec le Messager!..."},{"n":2883,"s":25,"a":28,"t":"Malheur à moi! Hélas! Si seulement je n'avais pas pris «un tel» pour ami!..."},{"n":2884,"s":25,"a":29,"t":"Il m'a, en effet, égaré loin du rappel [le Coran], après qu'il me soit parvenu». Et le Diable déserte l'homme (après l'avoir tenté)."},{"n":2885,"s":25,"a":30,"t":"Et le Messager dit: «Seigneur, mon peuple a vraiment pris ce Coran pour une chose délaissée!»"},{"n":2886,"s":25,"a":31,"t":"C'est ainsi que Nous fîmes à chaque prophète un ennemi parmi les criminels. Mais ton Seigneur suffit comme guide et comme soutien."},{"n":2887,"s":25,"a":32,"t":"Et ceux qui ne croient pas disent: «Pourquoi n'a-t-on pas fait descendre sur lui le Coran en une seule fois?» Nous l'avons révélé ainsi pour raffermir ton cœur. Et Nous l'avons récité soigneusement."},{"n":2888,"s":25,"a":33,"t":"Ils ne t'apporteront aucune parabole, sans que Nous ne t'apportions la vérité avec la meilleure interprétation."},{"n":2889,"s":25,"a":34,"t":"Ceux qui seront traînés [ensemble] sur leurs visages vers l'Enfer, ceux-là seront dans la pire des situations et les plus égarés hors du chemin droit."},{"n":2890,"s":25,"a":35,"t":"En effet, Nous avons apporté à Moïse le Livre et lui avons assigné son frère Aaron comme assistant."},{"n":2891,"s":25,"a":36,"t":"Puis Nous avons dit: «Allez tous deux vers les gens qui ont traité de mensonge Nos preuves». Nous les avons ensuite détruits complètement."},{"n":2892,"s":25,"a":37,"t":"Et le peuple de Noé, quand ils eurent démenti les messagers, Nous les noyâmes et en fîmes pour les gens un signe d'avertissement. Et Nous avons préparé pour les injustes un châtiment douloureux."},{"n":2893,"s":25,"a":38,"t":"Et les 'Aad, les Thamûd, les gens d'Ar-Rass et de nombreuses générations intermédiaires!"},{"n":2894,"s":25,"a":39,"t":"A tous, cependant, Nous avions fait des paraboles et Nous les avions tous anéantis d'une façon brutale."},{"n":2895,"s":25,"a":40,"t":"Ils sont passés par la cité sur laquelle est tombée une pluie de malheurs. Ne la voient-ils donc pas? Mais ils n'espèrent pas de résurrection!"},{"n":2896,"s":25,"a":41,"t":"Et quand ils te voient, ils ne te prennent qu'en raillerie: «Est-ce là celui qu'Allah a envoyé comme Messager?"},{"n":2897,"s":25,"a":42,"t":"Peu s'en est fallu qu'il ne nous égare de nos divinités, si ce n'était notre attachement patient à elles!». Cependant, ils sauront quand ils verront le châtiment, qui est le plus égaré en son chemin."},{"n":2898,"s":25,"a":43,"t":"Ne vois-tu pas celui qui a fait de sa passion sa divinité? Est-ce à toi d'être un garant pour lui?"},{"n":2899,"s":25,"a":44,"t":"Ou bien penses-tu que la plupart d'entre eux entendent ou comprennent? Ils ne sont en vérité comparables qu'à des bestiaux. Ou plutôt, ils sont plus égarés encore du sentier."},{"n":2900,"s":25,"a":45,"t":"N'as-tu pas vu comment ton Seigneur étend l'ombre? S'Il avait voulu, certes, Il l'aurait faite immobile. Puis Nous lui fîmes du soleil son indice,"},{"n":2901,"s":25,"a":46,"t":"puis Nous la saisissons [pour la ramener] vers Nous avec facilité."},{"n":2902,"s":25,"a":47,"t":"Et c'est Lui qui vous fit de la nuit un vêtement, du sommeil un repos et qui fit du jour un retour à la vie active."},{"n":2903,"s":25,"a":48,"t":"Et c'est Lui qui envoya les vents comme une annonce précédant Sa miséricorde. Nous fîmes descendre du ciel une eau pure et purifiante,"},{"n":2904,"s":25,"a":49,"t":"pour faire revivre par elle une contrée morte, et donner à boire aux multiples bestiaux et hommes que Nous avons créés."},{"n":2905,"s":25,"a":50,"t":"Nous l'avions répartie entre eux afin qu'ils se rappellent (de Nous). Mais la plupart des gens se refusent à tout sauf à être ingrats."},{"n":2906,"s":25,"a":51,"t":"Or, si Nous avions voulu, Nous aurions certes envoyé dans chaque cité un avertisseur."},{"n":2907,"s":25,"a":52,"t":"N'obéis donc pas aux infidèles; et avec ceci (le Coran), lutte contre eux vigoureusement."},{"n":2908,"s":25,"a":53,"t":"Et c'est Lui qui donne libre cours aux deux mers: l'une douce, rafraîchissante, l'autre salée, amère. Et Il assigne entre les deux une zone intermédiaire et un barrage infranchissable."},{"n":2909,"s":25,"a":54,"t":"Et c'est Lui qui de l'eau a créé une espèce humaine qu'Il unit par les liens de la parenté et de l'alliance. Et ton Seigneur demeure Omnipotent."},{"n":2910,"s":25,"a":55,"t":"Mais ils adorent en dehors d'Allah, ce qui ne leur profite point, ni ne leur nuit! Et l'infidèle sera toujours l'allié des ennemis de son Seigneur!"},{"n":2911,"s":25,"a":56,"t":"Or, Nous ne t'avons envoyé que comme annonciateur et avertisseur."},{"n":2912,"s":25,"a":57,"t":"Dis: «Je ne vous en demande aucun salaire (pour moi même). Toutefois, celui qui veut suivre un chemin conduisant vers son Seigneur [est libre de dépenser dans la voie d'Allah]»."},{"n":2913,"s":25,"a":58,"t":"Et place ta confiance en Le Vivant qui ne meurt jamais. Et par Sa louange, glorifie-Le. Il suffit comme Parfait Connaisseur des péchés de Ses serviteurs."},{"n":2914,"s":25,"a":59,"t":"C'est Lui qui, en six jours, a créé les cieux, la terre et tout ce qui existe entre eux, et le Tout Miséricordieux S'est établi «Istawâ» ensuite sur le Trône. Interroge donc qui est bien informé de Lui."},{"n":2915,"s":25,"a":60,"t":"Et quand on leur dit: «Prosternez-vous devant le Tout Miséricordieux», ils disent: «Qu'est-ce donc que le Tout Miséricordieux? Allons-nous nous prosterner devant ce que tu nous commandes?» - Et cela accroît leur répulsion."},{"n":2916,"s":25,"a":61,"t":"Que soit béni Celui qui a placé au ciel des constellations et y a placé un luminaire (le soleil) et aussi une lune éclairante!"},{"n":2917,"s":25,"a":62,"t":"Et c'est Lui qui a assigné une alternance à la nuit et au jour pour quiconque veut y réfléchir ou montrer sa reconnaissance."},{"n":2918,"s":25,"a":63,"t":"Les serviteurs du Tout Miséricordieux sont ceux qui marchent humblement sur terre, qui, lorsque les ignorants s'adressent à eux, disent: «Paix»,"},{"n":2919,"s":25,"a":64,"t":"qui passent les nuits prosternés et debout devant leur Seigneur;"},{"n":2920,"s":25,"a":65,"t":"qui disent: «Seigneur, écarte de nous le châtiment de l'Enfer». - car son châtiment est permanent."},{"n":2921,"s":25,"a":66,"t":"Quels mauvais gîte et lieu de séjour!"},{"n":2922,"s":25,"a":67,"t":"Qui, lorsqu'ils dépensent, ne sont ni prodigues ni avares mais se tiennent au juste milieu."},{"n":2923,"s":25,"a":68,"t":"Qui n'invoquent pas d'autre dieu avec Allah et ne tuent pas la vie qu'Allah a rendue sacrée, sauf à bon droit; qui ne commettent pas de fornication - car quiconque fait cela encourra une punition"},{"n":2924,"s":25,"a":69,"t":"et le châtiment lui sera doublé, au Jour de la Résurrection, et il y demeurera éternellement couvert d'ignominie;"},{"n":2925,"s":25,"a":70,"t":"sauf celui qui se repent, croit et accomplit une bonne œuvre; ceux-là Allah changera leurs mauvaises actions en bonnes, et Allah est Pardonneur et Miséricordieux;"},{"n":2926,"s":25,"a":71,"t":"et quiconque se repent et accomplit une bonne œuvre c'est vers Allah qu'aboutira son retour."},{"n":2927,"s":25,"a":72,"t":"Ceux qui ne donnent pas de faux témoignages; et qui, lorsqu'ils passent auprès d'une frivolité, s'en écartent noblement;"},{"n":2928,"s":25,"a":73,"t":"qui lorsque les versets de leur Seigneur leur sont rappelés, ne deviennent ni sourds ni aveugles;"},{"n":2929,"s":25,"a":74,"t":"et qui disent: «Seigneur, donne-nous, en nos épouses et nos descendants, la joie des yeux, et fais de nous un guide pour les pieux»."},{"n":2930,"s":25,"a":75,"t":"Ceux-là auront pour récompense un lieu élevé [du Paradis] à cause de leur endurance, et ils y seront accueillis avec le salut et la paix,"},{"n":2931,"s":25,"a":76,"t":"pour y demeurer éternellement. Quel beau gîte et lieu de séjour!"},{"n":2932,"s":25,"a":77,"t":"Dis: «Mon Seigneur ne se souciera pas de vous sans votre prière; mais vous avez, démenti (le Prophète). Votre [châtiment] sera inévitable et permanent."},{"n":2933,"s":26,"a":1,"t":"T'â, Sîn, Mim."},{"n":2934,"s":26,"a":2,"t":"Voici les versets du Livre explicite."},{"n":2935,"s":26,"a":3,"t":"Il se peut que tu te consumes de chagrin parce qu'ils ne sont pas croyants!"},{"n":2936,"s":26,"a":4,"t":"Si Nous voulions, Nous ferions descendre du ciel sur eux un prodige devant lequel leurs nuques resteront courbées."},{"n":2937,"s":26,"a":5,"t":"Aucun nouveau rappel ne leur vient du Tout Miséricordieux sans qu'ils ne l'esquivent."},{"n":2938,"s":26,"a":6,"t":"Et ils ont traité de mensonge [tout ce qui leur vient du Seigneur]. Il leur viendra bientôt des nouvelles de ce dont ils se raillent."},{"n":2939,"s":26,"a":7,"t":"N'ont-ils pas observé la terre, combien Nous y avons fait pousser de couples généreux de toutes sortes?"},{"n":2940,"s":26,"a":8,"t":"Voilà bien là une preuve! Et la plupart d'entre eux ne croient pas."},{"n":2941,"s":26,"a":9,"t":"Et ton Seigneur est en vérité Lui le Tout Puissant, le Très Miséricordieux."},{"n":2942,"s":26,"a":10,"t":"Et lorsque ton Seigneur appela Moïse: «Rends-toi auprès du peuple injuste,"},{"n":2943,"s":26,"a":11,"t":"[auprès du] peuple de Pharaon» ne craindront-ils pas (Allah)?"},{"n":2944,"s":26,"a":12,"t":"Il dit: «Seigneur, je crains qu'ils ne me traitent de menteur;"},{"n":2945,"s":26,"a":13,"t":"que ma poitrine ne se serre, et que ma langue ne soit embarrassée: Mande donc Aaron."},{"n":2946,"s":26,"a":14,"t":"Ils ont un crime à me reprocher; je crains donc qu'ils ne me tuent»."},{"n":2947,"s":26,"a":15,"t":"Mais [Allah lui] dit: «Jamais! Allez tous deux avec Nos prodiges, Nous resterons avec vous et Nous écouterons."},{"n":2948,"s":26,"a":16,"t":"Rendez-vous donc tous deux auprès de Pharaon, puis dites: «Nous sommes les messagers du Seigneur de l'univers,"},{"n":2949,"s":26,"a":17,"t":"pour que tu renvoies les Enfants d'Israël avec nous»."},{"n":2950,"s":26,"a":18,"t":"«Ne t'avons-nous pas, dit Pharaon, élevé chez nous tout enfant? Et n'as-tu pas demeuré parmi nous des années de ta vie?"},{"n":2951,"s":26,"a":19,"t":"Puis tu as commis le méfait que tu as fait, en dépit de toute reconnaissance»."},{"n":2952,"s":26,"a":20,"t":"«Je l'ai fait, dit Moïse, alors que j'étais encore du nombre des égarés."},{"n":2953,"s":26,"a":21,"t":"Je me suis donc enfui de vous quand j'ai eu peur de vous: puis, mon Seigneur m'a donné la sagesse et m'a désigné parmi Ses messagers."},{"n":2954,"s":26,"a":22,"t":"Est-ce là un bienfait de ta part [que tu me rappelles] avec reproche, alors que tu as asservi les Enfants d'Israël?»"},{"n":2955,"s":26,"a":23,"t":"«Et qu'est-ce que le Seigneur de l'univers?» dit Pharaon."},{"n":2956,"s":26,"a":24,"t":"«Le Seigneur des cieux et de la terre et de ce qui existe entre eux, dit [Moïse], si seulement vous pouviez en être convaincus!»"},{"n":2957,"s":26,"a":25,"t":"[Pharaon] dit à ceux qui l'entouraient: «N'entendez-vous pas?"},{"n":2958,"s":26,"a":26,"t":"[Moïse] continue: «... Votre Seigneur, et le Seigneur de vos plus anciens ancêtres»."},{"n":2959,"s":26,"a":27,"t":"«Vraiment, dit [Pharaon], votre messager qui vous a été envoyé, est un fou»."},{"n":2960,"s":26,"a":28,"t":"[Moïse] ajouta: «... Le Seigneur du Levant et du Couchant et de ce qui est entre les deux; si seulement vous compreniez!»"},{"n":2961,"s":26,"a":29,"t":"«Si tu adoptes, dit [Pharaon], une autre divinité que moi, je te mettrai parmi les prisonniers»."},{"n":2962,"s":26,"a":30,"t":"«Et même si je t'apportais, dit [Moïse], une chose (une preuve) évidente?"},{"n":2963,"s":26,"a":31,"t":"«Apporte-la, dit [Pharaon], si tu es du nombre des véridiques»."},{"n":2964,"s":26,"a":32,"t":"[Moïse] jeta donc son bâton et le voilà devenu un serpent manifeste."},{"n":2965,"s":26,"a":33,"t":"Et il tira sa main et voilà qu'elle était blanche (étincelante) à ceux qui regardaient."},{"n":2966,"s":26,"a":34,"t":"[Pharaon] dit aux notables autour de lui: «Voilà en vérité un magicien savant."},{"n":2967,"s":26,"a":35,"t":"Il veut par sa magie vous expulser de votre terre. Que commandez-vous?»"},{"n":2968,"s":26,"a":36,"t":"Ils dirent: «Remets-les à plus tard, [lui] et son frère, et envoie des gens dans les villes, pour rassembler,"},{"n":2969,"s":26,"a":37,"t":"et t'amener tout grand magicien savant»."},{"n":2970,"s":26,"a":38,"t":"Les magiciens furent donc réunis en rendez-vous au jour convenu."},{"n":2971,"s":26,"a":39,"t":"Et il fut dit aux gens: «Est-ce que vous allez vous réunir,"},{"n":2972,"s":26,"a":40,"t":"afin que nous suivions les magiciens, si ce sont eux les vainqueurs?»"},{"n":2973,"s":26,"a":41,"t":"Puis, lorsque les magiciens arrivèrent, ils dirent à Pharaon: «Y aura-t-il vraiment une récompense pour nous, si nous sommes les vainqueurs?»"},{"n":2974,"s":26,"a":42,"t":"Il dit: «Oui, bien sûr, vous serez alors parmi mes proches!»"},{"n":2975,"s":26,"a":43,"t":"Moïse leur dit: «Jetez ce que vous avez à jeter»."},{"n":2976,"s":26,"a":44,"t":"Ils jetèrent donc leurs cordes et leurs bâtons et dirent: «Par la puissance de Pharaon!... C'est nous qui serons les vainqueurs»."},{"n":2977,"s":26,"a":45,"t":"Puis Moïse jeta son bâton, et voilà qu'il happait ce qu'ils avaient fabriqué."},{"n":2978,"s":26,"a":46,"t":"Alors les magiciens tombèrent prosternés,"},{"n":2979,"s":26,"a":47,"t":"disant: «Nous croyons au Seigneur de l'univers,"},{"n":2980,"s":26,"a":48,"t":"Le Seigneur de Moïse et d'Aaron»."},{"n":2981,"s":26,"a":49,"t":"[Pharaon] dit: «Avez-vous cru en lui avant que je ne vous le permette? En vérité, c'est lui votre chef, qui vous a enseigné la magie! Eh bien, vous saurez bientôt! Je vous couperai, sûrement, mains et jambes opposées, et vous crucifierai tous»."},{"n":2982,"s":26,"a":50,"t":"Ils disent: «Il n'y a pas de mal! Car c'est vers notre Seigneur que nous retournerons."},{"n":2983,"s":26,"a":51,"t":"Nous convoitons que notre Seigneur nous pardonne nos fautes pour avoir été les premiers à croire»."},{"n":2984,"s":26,"a":52,"t":"Et Nous révélâmes à Moïse [ceci]: «Pars de nuit avec Mes serviteurs, car vous serez poursuivis»."},{"n":2985,"s":26,"a":53,"t":"Puis, Pharaon envoya des rassembleurs [dire] dans les villes:"},{"n":2986,"s":26,"a":54,"t":"«Ce sont, en fait, une bande peu nombreuse,"},{"n":2987,"s":26,"a":55,"t":"mais ils nous irritent,"},{"n":2988,"s":26,"a":56,"t":"tandis que nous sommes tous vigilants»."},{"n":2989,"s":26,"a":57,"t":"Ainsi, Nous les fîmes donc sortir des jardins, des sources,"},{"n":2990,"s":26,"a":58,"t":"des trésors et d'un lieu de séjour agréable."},{"n":2991,"s":26,"a":59,"t":"Il en fut ainsi! Et Nous les donnâmes en héritage aux enfants d'Israël."},{"n":2992,"s":26,"a":60,"t":"Au lever du soleil, ils les poursuivirent."},{"n":2993,"s":26,"a":61,"t":"Puis, quand les deux partis se virent, les compagnons de Moïse dirent: «Nous allons être rejoints»."},{"n":2994,"s":26,"a":62,"t":"Il dit: «Jamais, car j'ai avec moi mon Seigneur qui va me guider»."},{"n":2995,"s":26,"a":63,"t":"Alors Nous révélâmes à Moïse: «Frappe la mer de ton bâton». Elle se fendit alors, et chaque versant fut comme une énorme montagne."},{"n":2996,"s":26,"a":64,"t":"Nous fîmes approcher les autres [Pharaon et son peuple]."},{"n":2997,"s":26,"a":65,"t":"Et Nous sauvâmes Moïse et tous ceux qui étaient avec lui;"},{"n":2998,"s":26,"a":66,"t":"ensuite Nous noyâmes les autres."},{"n":2999,"s":26,"a":67,"t":"Voilà bien là un prodige, mais la plupart d'entre eux ne croient pas."},{"n":3000,"s":26,"a":68,"t":"Et ton Seigneur, c'est en vérité Lui le Tout Puissant, le Très Miséricordieux."},{"n":3001,"s":26,"a":69,"t":"Et récite-leur la nouvelle d'Abraham:"},{"n":3002,"s":26,"a":70,"t":"Quand il dit à son père et à son peuple: «Qu'adorez-vous?»"},{"n":3003,"s":26,"a":71,"t":"Ils dirent: «Nous adorons des idoles et nous leurs restons attachés»."},{"n":3004,"s":26,"a":72,"t":"Il dit: «Vous entendent-elles lorsque vous [les] appelez?"},{"n":3005,"s":26,"a":73,"t":"ou vous profitent-elles? ou vous nuisent-elles?»"},{"n":3006,"s":26,"a":74,"t":"Ils dirent: «Non! mais nous avons trouvé nos ancêtres agissant ainsi»."},{"n":3007,"s":26,"a":75,"t":"Il dit: «Que dites-vous de ce que vous adoriez...?"},{"n":3008,"s":26,"a":76,"t":"Vous et vos vieux ancêtres?"},{"n":3009,"s":26,"a":77,"t":"Ils sont tous pour moi des ennemis sauf le Seigneur de l'univers,"},{"n":3010,"s":26,"a":78,"t":"qui m'a créé, et c'est Lui qui me guide;"},{"n":3011,"s":26,"a":79,"t":"et c'est Lui qui me nourrit et me donne à boire;"},{"n":3012,"s":26,"a":80,"t":"et quand je suis malade, c'est Lui qui me guérit,"},{"n":3013,"s":26,"a":81,"t":"et qui me fera mourir, puis me redonnera la vie,"},{"n":3014,"s":26,"a":82,"t":"et c'est de Lui que je convoite le pardon de mes fautes le Jour de la Rétribution."},{"n":3015,"s":26,"a":83,"t":"Seigneur, accorde-moi sagesse (et savoir) et fais-moi rejoindre les gens de bien;"},{"n":3016,"s":26,"a":84,"t":"fais que j'aie une mention honorable sur les langues de la postérité;"},{"n":3017,"s":26,"a":85,"t":"et fais de moi l'un des héritiers du Jardin des délices."},{"n":3018,"s":26,"a":86,"t":"et pardonne à mon père: car il a été du nombre des égarés;"},{"n":3019,"s":26,"a":87,"t":"et ne me couvre pas d'ignominie, le jour où l'on sera ressuscité,"},{"n":3020,"s":26,"a":88,"t":"le jour où ni les biens, ni les enfants ne seront d'aucune utilité,"},{"n":3021,"s":26,"a":89,"t":"sauf celui qui vient à Allah avec un cœur sain»."},{"n":3022,"s":26,"a":90,"t":"On rapprochera alors le Paradis pour les pieux,"},{"n":3023,"s":26,"a":91,"t":"et l'on exposera aux errants la Fournaise,"},{"n":3024,"s":26,"a":92,"t":"et on leur dira: «Où sont ceux que vous adoriez,"},{"n":3025,"s":26,"a":93,"t":"en dehors d'Allah? vous secourent-ils? ou se secourent-ils eux-mêmes?»"},{"n":3026,"s":26,"a":94,"t":"Ils y seront donc jetés pêle-mêle, et les errants aussi,"},{"n":3027,"s":26,"a":95,"t":"ainsi que toutes les légions de Iblis."},{"n":3028,"s":26,"a":96,"t":"Ils diront, tout en s'y querellant:"},{"n":3029,"s":26,"a":97,"t":"«Par Allah! Nous étions certes dans un égarement évident,"},{"n":3030,"s":26,"a":98,"t":"quand nous faisions de vous les égaux du Seigneur de l'univers."},{"n":3031,"s":26,"a":99,"t":"Ce ne sont que les criminels qui nous ont égarés."},{"n":3032,"s":26,"a":100,"t":"Et nous n'avons pas d'intercesseurs,"},{"n":3033,"s":26,"a":101,"t":"ni d'ami chaleureux."},{"n":3034,"s":26,"a":102,"t":"Si un retour nous était possible, alors nous serions parmi les croyants!»"},{"n":3035,"s":26,"a":103,"t":"Voilà bien là un signe; cependant, la plupart d'entre eux ne croient pas."},{"n":3036,"s":26,"a":104,"t":"Et ton Seigneur, c'est Lui vraiment le Puissant, le Très Miséricordieux."},{"n":3037,"s":26,"a":105,"t":"Le peuple de Noé traita de menteurs les Messagers,"},{"n":3038,"s":26,"a":106,"t":"lorsque Noé, leur frère, (contribule) leur dit: «Ne craindrez-vous pas [Allah]?"},{"n":3039,"s":26,"a":107,"t":"Je suis pour vous un messager digne de confiance."},{"n":3040,"s":26,"a":108,"t":"Craignez Allah donc et obéissez-moi."},{"n":3041,"s":26,"a":109,"t":"Et je ne vous demande pas de salaire pour cela; mon salaire n'incombe qu'au Seigneur de l'univers."},{"n":3042,"s":26,"a":110,"t":"Craignez Allah donc, et obéissez-moi»."},{"n":3043,"s":26,"a":111,"t":"Ils dirent: «Croirons-nous en toi, alors que ce sont les plus vils qui te suivent."},{"n":3044,"s":26,"a":112,"t":"Il dit: «Je ne sais pas ce que ceux-là faisaient."},{"n":3045,"s":26,"a":113,"t":"Leur compte n'incombe qu'à mon Seigneur. Si seulement vous êtes conscients."},{"n":3046,"s":26,"a":114,"t":"Je ne suis pas celui qui repousse les croyants."},{"n":3047,"s":26,"a":115,"t":"Je ne suis qu'un avertisseur explicite»."},{"n":3048,"s":26,"a":116,"t":"Ils dirent: «Si tu ne cesses pas, Noé, tu seras certainement du nombre des lapidés!»"},{"n":3049,"s":26,"a":117,"t":"Il dit: «O mon Seigneur, mon peuple me traite de menteur."},{"n":3050,"s":26,"a":118,"t":"Tranche donc clairement entre eux et moi; et sauve-moi ainsi que ceux des croyants qui sont avec moi»."},{"n":3051,"s":26,"a":119,"t":"Nous le sauvâmes donc, de même que ceux qui étaient avec lui dans l'arche, pleinement chargée."},{"n":3052,"s":26,"a":120,"t":"Et ensuite nous noyâmes le reste (les infidèles)."},{"n":3053,"s":26,"a":121,"t":"Voilà bien là un signe. Cependant, la plupart d'entre eux ne croient pas."},{"n":3054,"s":26,"a":122,"t":"Et Ton Seigneur, c'est lui vraiment le Puissant, le Très Miséricordieux."},{"n":3055,"s":26,"a":123,"t":"Les 'Aad traitèrent de menteurs les Envoyés."},{"n":3056,"s":26,"a":124,"t":"Et quand Hûd, leur frère (contribule), leur dit: «Ne craindrez-vous pas [Allah]?»"},{"n":3057,"s":26,"a":125,"t":"Je suis pour vous un messager digne de confiance,"},{"n":3058,"s":26,"a":126,"t":"Craignez Allah donc et obéissez-moi."},{"n":3059,"s":26,"a":127,"t":"Et je ne vous demande pas de salaire pour cela; mon salaire n'incombe qu'au Seigneur de l'univers."},{"n":3060,"s":26,"a":128,"t":"Bâtissez-vous par frivolité sur chaque colline un monument?"},{"n":3061,"s":26,"a":129,"t":"Et édifiez-vous des châteaux comme si vous deviez demeurer éternellement?"},{"n":3062,"s":26,"a":130,"t":"Et quand vous sévissez contre quelqu'un, vous le faites impitoyablement."},{"n":3063,"s":26,"a":131,"t":"Craignez Allah donc et obéissez-moi."},{"n":3064,"s":26,"a":132,"t":"Craignez Celui qui vous a pourvus de [toutes les bonnes choses] que vous connaissez,"},{"n":3065,"s":26,"a":133,"t":"qui vous a pourvus de bestiaux et d'enfants,"},{"n":3066,"s":26,"a":134,"t":"de jardins et de sources."},{"n":3067,"s":26,"a":135,"t":"Je crains pour vous le châtiment d'un Jour terrible»."},{"n":3068,"s":26,"a":136,"t":"Ils dirent: «Que tu nous exhortes ou pas, cela nous est parfaitement égal!"},{"n":3069,"s":26,"a":137,"t":"Ce ne sont là que des mours des anciens:"},{"n":3070,"s":26,"a":138,"t":"Nous ne serons nullement châtiés»."},{"n":3071,"s":26,"a":139,"t":"Ils le traitèrent donc de menteur. Et nous les fîmes périr. Voilà bien là un signe! Cependant, la plupart d'entre eux ne croient pas."},{"n":3072,"s":26,"a":140,"t":"Et Ton Seigneur, c'est Lui vraiment le Puissant, le Très Miséricordieux."},{"n":3073,"s":26,"a":141,"t":"Les Thamûd traitèrent de menteurs les Messagers."},{"n":3074,"s":26,"a":142,"t":"Quand Sâlih, leur frère (contribule) leur dit: «Ne craindrez-vous pas [Allah]?»"},{"n":3075,"s":26,"a":143,"t":"Je suis pour vous un messager digne de confiance."},{"n":3076,"s":26,"a":144,"t":"Craignez Allah donc et obéissez-moi."},{"n":3077,"s":26,"a":145,"t":"Je ne vous demande pas de salaire pour cela, mon salaire n'incombe qu'au Seigneur de l'univers."},{"n":3078,"s":26,"a":146,"t":"Vous laissera-t-on en sécurité dans votre présente condition?"},{"n":3079,"s":26,"a":147,"t":"Au milieu de jardins, de sources,"},{"n":3080,"s":26,"a":148,"t":"de cultures et de palmiers aux fruits digestes?"},{"n":3081,"s":26,"a":149,"t":"Creusez-vous habilement des maisons dans les montagnes?"},{"n":3082,"s":26,"a":150,"t":"Craignez Allah donc et obéissez-moi."},{"n":3083,"s":26,"a":151,"t":"N'obéissez pas à l'ordre des outranciers,"},{"n":3084,"s":26,"a":152,"t":"qui sèment le désordre sur la terre et n'améliorent rien»."},{"n":3085,"s":26,"a":153,"t":"Ils dirent: «Tu n'es qu'un ensorcelé."},{"n":3086,"s":26,"a":154,"t":"Tu n'es qu'un homme comme nous. Apporte donc un prodige, si tu es du nombre des véridiques»."},{"n":3087,"s":26,"a":155,"t":"Il dit: «Voici une chamelle: à elle de boire un jour convenu, et à vous de boire un jour."},{"n":3088,"s":26,"a":156,"t":"Et ne lui infligez aucun mal, sinon le châtiment d'un jour terrible vous saisira»."},{"n":3089,"s":26,"a":157,"t":"Mais ils la tuèrent. Eh bien, ils eurent à regretter!"},{"n":3090,"s":26,"a":158,"t":"Le châtiment, en effet, les saisit. Voilà bien là un prodige. Cependant, la plupart d'entre eux ne croient pas."},{"n":3091,"s":26,"a":159,"t":"Et ton Seigneur, c'est en vérité Lui le Tout Puissant, le Très Miséricordieux."},{"n":3092,"s":26,"a":160,"t":"Le peuple de Lot traita de menteurs les Messagers,"},{"n":3093,"s":26,"a":161,"t":"quand leur frère Lot leur dit: «Ne craindrez-vous pas [Allah]?"},{"n":3094,"s":26,"a":162,"t":"Je suis pour vous un messager digne de confiance."},{"n":3095,"s":26,"a":163,"t":"Craignez Allah donc et obéissez-moi."},{"n":3096,"s":26,"a":164,"t":"Je ne vous demande pas de salaire pour cela; mon salaire n'incombe qu'au Seigneur de l'univers."},{"n":3097,"s":26,"a":165,"t":"Accomplissez-vous l'acte charnel avec les mâles de ce monde?"},{"n":3098,"s":26,"a":166,"t":"Et délaissez-vous les épouses que votre Seigneur a créées pour vous? Mais vous n'êtes que des gens transgresseurs»."},{"n":3099,"s":26,"a":167,"t":"Ils dirent: «Si tu ne cesses pas, Lot, tu seras certainement du nombre des expulsés»."},{"n":3100,"s":26,"a":168,"t":"Il dit: «Je déteste vraiment ce que vous faites."},{"n":3101,"s":26,"a":169,"t":"Seigneur, sauve-moi ainsi que ma famille de ce qu'ils font»."},{"n":3102,"s":26,"a":170,"t":"Nous le sauvâmes alors, lui et toute sa famille,"},{"n":3103,"s":26,"a":171,"t":"sauf une vieille qui fut parmi les exterminés."},{"n":3104,"s":26,"a":172,"t":"Puis Nous détruisîmes les autres;"},{"n":3105,"s":26,"a":173,"t":"et Nous fîmes pleuvoir sur eux une pluie (de pierres). Et quelle pluie fatale pour ceux qui sont avertis!"},{"n":3106,"s":26,"a":174,"t":"Voilà bien là un prodige. Cependant, la plupart d'entre eux ne croient pas."},{"n":3107,"s":26,"a":175,"t":"Et ton Seigneur, c'est en vérité Lui le Tout Puissant, le Très Miséricordieux."},{"n":3108,"s":26,"a":176,"t":"Les gens d'Al-Ayka traitèrent de menteurs les Messagers."},{"n":3109,"s":26,"a":177,"t":"Lorsque Chuayb leur dit: «Ne craindrez-vous pas [Allah]»."},{"n":3110,"s":26,"a":178,"t":"Je suis pour vous un messager digne de confiance."},{"n":3111,"s":26,"a":179,"t":"Craignez Allah donc et obéissez-moi,"},{"n":3112,"s":26,"a":180,"t":"et je ne vous demande pas de salaire pour cela; mon salaire n'incombe qu'au Seigneur de l'univers."},{"n":3113,"s":26,"a":181,"t":"Donnez la pleine mesure et n'en faites rien perdre [aux gens]."},{"n":3114,"s":26,"a":182,"t":"et pesez avec une balance exacte."},{"n":3115,"s":26,"a":183,"t":"Ne donnez pas aux gens moins que leur dû; et ne commettez pas de désordre et de corruption sur terre."},{"n":3116,"s":26,"a":184,"t":"Et craignez Celui qui vous a créés, vous et les anciennes générations»."},{"n":3117,"s":26,"a":185,"t":"Ils dirent: «Tu es certes du nombre des ensorcelés;"},{"n":3118,"s":26,"a":186,"t":"Tu n'es qu'un homme comme nous; et vraiment nous pensons que tu es du nombre des menteurs."},{"n":3119,"s":26,"a":187,"t":"Fais donc tomber sur nous des morceaux du ciel si tu es du nombre des véridiques!»"},{"n":3120,"s":26,"a":188,"t":"Il dit: «Mon Seigneur sait mieux ce que vous faites»."},{"n":3121,"s":26,"a":189,"t":"Mais ils le traitèrent de menteur. Alors, le châtiment du jour de l'Ombre les saisit. Ce fut le châtiment d'un jour terrible."},{"n":3122,"s":26,"a":190,"t":"Voilà bien là un prodige. Cependant, la plupart d'entre eux ne croient pas."},{"n":3123,"s":26,"a":191,"t":"Et ton Seigneur, c'est en vérité Lui le Tout Puissant, le Très Miséricordieux."},{"n":3124,"s":26,"a":192,"t":"Ce (Coran) ci, c'est le Seigneur de l'univers qui l'a fait descendre,"},{"n":3125,"s":26,"a":193,"t":"et l'Esprit fidèle est descendu avec cela"},{"n":3126,"s":26,"a":194,"t":"sur ton cœur, pour que tu sois du nombre des avertisseurs,"},{"n":3127,"s":26,"a":195,"t":"en une langue arabe très claire."},{"n":3128,"s":26,"a":196,"t":"Et ceci était déjà mentionné dans les Ecrits des anciens (envoyés)."},{"n":3129,"s":26,"a":197,"t":"N'est-ce pas pour eux un signe, que les savants des Enfants d'Israël le sachent?"},{"n":3130,"s":26,"a":198,"t":"Si Nous l'avions fait descendre sur quelqu'un des non-Arabes,"},{"n":3131,"s":26,"a":199,"t":"et que celui-ci le leur eut récité, ils n'y auraient pas cru."},{"n":3132,"s":26,"a":200,"t":"Ainsi l'avons Nous fait pénétrer [le doute] dans les cœurs des criminels;"},{"n":3133,"s":26,"a":201,"t":"mais ils n'y [le Coran] croiront pas avant de voir le châtiment douloureux,"},{"n":3134,"s":26,"a":202,"t":"qui viendra sur eux soudain, sans qu'ils s'en rendent compte;"},{"n":3135,"s":26,"a":203,"t":"alors ils diront: «Est-ce qu'on va nous donner du répit?»"},{"n":3136,"s":26,"a":204,"t":"Est-ce qu'ils cherchent à hâter Notre châtiment?"},{"n":3137,"s":26,"a":205,"t":"Vois-tu si Nous leur permettions de jouir, des années durant,"},{"n":3138,"s":26,"a":206,"t":"et qu'ensuite leur arrive ce dont on les menaçait,"},{"n":3139,"s":26,"a":207,"t":"les jouissances qu'on leur a permises ne leur serviraient à rien."},{"n":3140,"s":26,"a":208,"t":"Et Nous ne faisons pas périr de cité avant qu'elle n'ait eu des avertisseurs,"},{"n":3141,"s":26,"a":209,"t":"[à titre de] rappel, et Nous ne sommes pas injuste."},{"n":3142,"s":26,"a":210,"t":"Et ce ne sont point les diables qui sont descendus avec ceci (le Coran):"},{"n":3143,"s":26,"a":211,"t":"cela ne leur convient pas; et ils n'auraient pu le faire."},{"n":3144,"s":26,"a":212,"t":"Car ils sont écartés de toute écoute (du message divin)."},{"n":3145,"s":26,"a":213,"t":"N'invoque donc pas une autre divinité avec Allah, sinon tu seras du nombre des châtiés."},{"n":3146,"s":26,"a":214,"t":"Et avertis les gens qui te sont les plus proches."},{"n":3147,"s":26,"a":215,"t":"Et abaisse ton aile [sois bienveillant] pour les croyants qui te suivent."},{"n":3148,"s":26,"a":216,"t":"Mais s'ils te désobéissent, dis-leur: «Moi, je désavoue ce que vous faites»."},{"n":3149,"s":26,"a":217,"t":"Et place ta confiance dans le Tout Puissant, le Très Miséricordieux,"},{"n":3150,"s":26,"a":218,"t":"qui te voit quand tu te lèves,"},{"n":3151,"s":26,"a":219,"t":"et (voit) tes gestes parmi ceux qui se prosternent."},{"n":3152,"s":26,"a":220,"t":"C'est Lui vraiment, l'Audient, l'Omniscient."},{"n":3153,"s":26,"a":221,"t":"Vous apprendrai-Je sur qui les diables descendent?"},{"n":3154,"s":26,"a":222,"t":"Ils descendent sur tout calomniateur, pécheur."},{"n":3155,"s":26,"a":223,"t":"Ils tendent l'oreille... Cependant, la plupart d'entre eux sont menteurs."},{"n":3156,"s":26,"a":224,"t":"Et quant aux poètes, ce sont les égarés qui les suivent."},{"n":3157,"s":26,"a":225,"t":"Ne vois-tu pas qu'ils divaguent dans chaque vallée,"},{"n":3158,"s":26,"a":226,"t":"et qu'ils disent ce qu'ils ne font pas?"},{"n":3159,"s":26,"a":227,"t":"à part ceux qui croient et font de bonnes œuvres, qui invoquent souvent le nom d'Allah et se défendent contre les torts qu'on leur fait. Les injustes verront bientôt le revirement qu'ils [éprouveront]!"},{"n":3160,"s":27,"a":1,"t":"T'â, Sîn. Voici les versets du Coran et d'un Livre explicite,"},{"n":3161,"s":27,"a":2,"t":"un guide et une bonne annonce aux croyants,"},{"n":3162,"s":27,"a":3,"t":"qui accomplissent la Salât, acquittent la Zakât et croient avec certitude en l'au-delà."},{"n":3163,"s":27,"a":4,"t":"Quant à ceux qui ne croient pas en l'au-delà, Nous embellissons [à leurs yeux] leurs actions, et alors ils deviennent confus et hésitants."},{"n":3164,"s":27,"a":5,"t":"Ce sont eux qui subiront le pire châtiment, tandis qu'ils seront dans l'au-delà les plus grands perdants."},{"n":3165,"s":27,"a":6,"t":"Certes, c'est toi qui reçois le Coran, de la part d'un Sage, d'un Savant."},{"n":3166,"s":27,"a":7,"t":"(Rappelle) quand Moïse dit à sa famille: «J'ai aperçu un feu; je vais vous en apporter des nouvelles, ou bien je vous apporterai un tison allumé afin que vous vous réchauffiez»."},{"n":3167,"s":27,"a":8,"t":"Lorsqu'il y arriva, on l'appela, - béni soit Celui qui est dans le feu et Celui qui est tout autour, et gloire à Allah, Seigneur de l'univers."},{"n":3168,"s":27,"a":9,"t":"«O Moïse, c'est Moi, Allah le Tout Puissant, le Sage»."},{"n":3169,"s":27,"a":10,"t":"Et: «Jette ton bâton». Quand il le vit remuer comme un serpent, il tourna le dos [pour fuir] sans revenir sur ses pas. «N'aie pas peur, Moïse. Les Messagers n'ont point peur auprès de Moi."},{"n":3170,"s":27,"a":11,"t":"Sauf celui qui a commis une injustice puis a remplacé le mal par le bien... alors Je suis Pardonneur et Miséricordieux»."},{"n":3171,"s":27,"a":12,"t":"Et introduis ta main dans l'ouverture de ta tunique. Elle sortira blanche et sans aucun mal - un des neuf prodiges à Pharaon et à son peuple, car ils sont vraiment des gens pervers» -."},{"n":3172,"s":27,"a":13,"t":"Et lorsque Nos prodiges leur parvinrent, clairs et explicites, ils dirent: «C'est là une magie évidente!»"},{"n":3173,"s":27,"a":14,"t":"Ils les nièrent injustement et orgueilleusement, tandis qu'en eux-mêmes ils y croyaient avec certitude. Regarde donc ce qu'il est advenu des corrupteurs."},{"n":3174,"s":27,"a":15,"t":"Nous avons effectivement donné à David et à Salomon une science; et ils dirent: «Louange à Allah qui nous a favorisés à beaucoup de Ses serviteurs croyants»."},{"n":3175,"s":27,"a":16,"t":"Et Salomon hérita de David et dit: «O hommes! On nous a appris le langage des oiseaux; et on nous a donné part de toutes choses. C'est là vraiment la grâce évidente."},{"n":3176,"s":27,"a":17,"t":"Et furent rassemblées pour Salomon, ses armées de djinns, d'hommes et d'oiseaux, et furent placées en rangs."},{"n":3177,"s":27,"a":18,"t":"Quand ils arrivèrent à la Vallée des Fourmis, une fourmi dit: «O fourmis, entrez dans vos demeures, [de peur] que Salomon et ses armées ne vous écrasent [sous leurs pieds] sans s'en rendre compte»."},{"n":3178,"s":27,"a":19,"t":"Il sourit, amusé par ses propos et dit: «Permets-moi Seigneur, de rendre grâce pour le bienfait dont Tu m'as comblé ainsi que mes père et mère, et que je fasse une bonne œuvre que tu agrées et fais-moi entrer, par Ta miséricorde, parmi Tes serviteurs vertueux»."},{"n":3179,"s":27,"a":20,"t":"Puis il passa en revue les oiseaux et dit: «Pourquoi ne vois-je pas la huppe? est-elle parmi les absents?"},{"n":3180,"s":27,"a":21,"t":"Je la châtierai sévèrement! ou je l'égorgerai! ou bien elle m'apportera un argument explicite»."},{"n":3181,"s":27,"a":22,"t":"Mais elle n'était restée (absente) que peu de temps et dit: «J'ai appris ce que tu n'as point appris; et je te rapporte de Saba' une nouvelle sûre:"},{"n":3182,"s":27,"a":23,"t":"J'ai trouvé qu'une femme est leur reine, que de toute chose elle a été comblée et qu'elle a un trône magnifique."},{"n":3183,"s":27,"a":24,"t":"Je l'ai trouvée, elle et son peuple, se prosternant devant le soleil au lieu d'Allah. Le Diable leur a embelli leurs actions, et les a détournés du droit chemin, et ils ne sont pas bien guidés."},{"n":3184,"s":27,"a":25,"t":"Que ne se prosternent-ils devant Allah qui fait sortir ce qui est caché dans les cieux et la terre, et qui sait ce que vous cachez et aussi ce que vous divulguez?"},{"n":3185,"s":27,"a":26,"t":"Allah! Point de divinité à part Lui, le Seigneur du Trône Immense."},{"n":3186,"s":27,"a":27,"t":"Alors, Salomon dit: «Nous allons voir si tu as dis la vérité ou si tu as menti."},{"n":3187,"s":27,"a":28,"t":"Pars avec ma lettre que voici; puis lance-la à eux; ensuite tiens-toi à l'écart d'eux pour voir ce que sera leur réponse."},{"n":3188,"s":27,"a":29,"t":"La reine dit: «O notables! Une noble lettre m'a été lancée."},{"n":3189,"s":27,"a":30,"t":"Elle vient de Salomon; et c'est: «Au nom d'Allah, le Tout Miséricordieux, le Très Miséricordieux,"},{"n":3190,"s":27,"a":31,"t":"Ne soyez pas hautains avec moi et venez à moi en toute soumission»."},{"n":3191,"s":27,"a":32,"t":"Elle dit: «O notables! Conseillez-moi sur cette affaire: je ne déciderai rien sans que vous ne soyez présents (pour me conseiller)»."},{"n":3192,"s":27,"a":33,"t":"Ils dirent: «Nous sommes détenteurs d'une force et d'une puissance redoutable. Le commandement cependant t'appartient. Regarde donc ce que tu veux ordonner»."},{"n":3193,"s":27,"a":34,"t":"Elle dit: «En vérité, quand les rois entrent dans une cité ils la corrompent, et font de ses honorables citoyens des humiliés. Et c'est ainsi qu'ils agissent."},{"n":3194,"s":27,"a":35,"t":"Moi, je vais leur envoyer un présent, puis je verrai ce que les envoyés ramèneront»."},{"n":3195,"s":27,"a":36,"t":"Puis, lorsque [la délégation] arriva auprès de Salomon, celui-ci dit: «Est-ce avec des biens que vous voulez m'aider? alors que ce qu'Allah m'a procuré est meilleur que ce qu'Il vous a procuré. Mais c'est vous plutôt qui vous réjouissez de votre cadeau."},{"n":3196,"s":27,"a":37,"t":"Retourne vers eux. Nous viendrons avec des armées contre lesquelles ils n'auront aucune résistance, et nous les en expulserons tout humiliés et méprisés."},{"n":3197,"s":27,"a":38,"t":"Il dit: «O notables! Qui de vous m'apportera son trône avant qu'ils ne viennent à moi soumis?»"},{"n":3198,"s":27,"a":39,"t":"Un djinn redoutable dit: «Je te l'apporterai avant que tu ne te lèves de ta place: pour cela, je suis fort et digne de confiance»."},{"n":3199,"s":27,"a":40,"t":"Quelqu'un qui avait une connaissance du Livre dit: «Je te l'apporterai avant que tu n'aies cligné de l'œil». Quand ensuite, Salomon a vu le trône installé auprès de lui, il dit: «Cela est de la grâce de mon Seigneur, pour m'éprouver si je suis reconnaissant ou si je suis ingrat. Quiconque est reconnaissant c'est dans son propre intérêt qu'il le fait, et quiconque est ingrat... alors mon Seigneur Se suffit à Lui-même et Il est Généreux»."},{"n":3200,"s":27,"a":41,"t":"Et il dit [encore]: «Rendez-lui son trône méconnaissable, nous verrons alors si elle sera guidée ou si elle est du nombre de ceux qui ne sont pas guidés»."},{"n":3201,"s":27,"a":42,"t":"Quand elle fut venue on lui dit: «Est-ce que ton trône est ainsi?» Elle dit: «C'est comme s'il l'était». - [Salomon dit]: «Le savoir nous a été donné avant elle; et nous étions déjà soumis»."},{"n":3202,"s":27,"a":43,"t":"Or, ce qu'elle adorait en dehors d'Allah l'empêchait (d'être croyante) car elle faisait partie d'un peuple mécréant."},{"n":3203,"s":27,"a":44,"t":"On lui dit: «Entre dans le palais». Puis, quand elle le vit, elle le prit pour de l'eau profonde et elle se découvrit les jambes. Alors, [Salomon] lui dit: «Ceci est un palais pavé de cristal». - Elle dit: «Seigneur, je me suis fait du tort à moi-même: Je me soumets avec Salomon à Allah, Seigneur de l'univers»."},{"n":3204,"s":27,"a":45,"t":"Nous envoyâmes effectivement vers les Thamûd leur frère Sâlih. [qui leur dit]: «Adorez Allah». Et voilà qu'ils se divisèrent en deux groupes qui se disputèrent."},{"n":3205,"s":27,"a":46,"t":"Il dit: «O mon peuple, pourquoi cherchez-vous à hâter le mal plutôt que le bien? Si seulement vous demandiez pardon à Allah? Peut-être vous serait-il fait miséricorde."},{"n":3206,"s":27,"a":47,"t":"Ils dirent: «Nous voyons en toi et en ceux qui sont avec toi, des porteurs de malheur». Il dit: «Votre sort dépend d'Allah. Mais vous êtes plutôt des gens qu'on soumet à la tentation."},{"n":3207,"s":27,"a":48,"t":"Et il y avait dans la ville un groupe de neuf individus qui semaient le désordre sur terre et ne faisaient rien de bon."},{"n":3208,"s":27,"a":49,"t":"Ils dirent: «Jurons par Allah que nous l'attaquerons de nuit, lui et sa famille. Ensuite nous dirons à celui qui est chargé de le venger: «Nous n'avons pas assisté à l'assassinat de sa famille, et nous sommes sincères»."},{"n":3209,"s":27,"a":50,"t":"Ils ourdirent une ruse et Nous ourdîmes une ruse sans qu'ils s'en rendent compte."},{"n":3210,"s":27,"a":51,"t":"Regarde donc ce qu'a été la conséquence de leur stratagème: Nous les fîmes périr, eux et tout leur peuple."},{"n":3211,"s":27,"a":52,"t":"Voilà donc leurs maisons désertes à cause de leurs méfaits. C'est bien là un avertissement pour des gens qui savent."},{"n":3212,"s":27,"a":53,"t":"Et Nous sauvâmes ceux qui avaient cru et étaient pieux."},{"n":3213,"s":27,"a":54,"t":"[Et rappelle-leur] Lot, quand il dit à son peuple: «Vous livrez-vous à la turpitude [l'homosexualité] alors que vous voyez clair»."},{"n":3214,"s":27,"a":55,"t":"Vous allez aux hommes au lieu de femmes pour assouvir vos désirs? Vous êtes plutôt un peuple ignorant."},{"n":3215,"s":27,"a":56,"t":"Puis son peuple n'eut que cette réponse: «Expulsez de votre cité la famille de Lot! Car ce sont des gens qui affectent la pureté."},{"n":3216,"s":27,"a":57,"t":"Nous le sauvâmes ainsi que sa famille, sauf sa femme pour qui Nous avions déterminé qu'elle serait du nombre des exterminés."},{"n":3217,"s":27,"a":58,"t":"Et Nous fîmes pleuvoir sur eux une pluie (de pierres). Et quelle mauvaise pluie que celle des gens prévenus!"},{"n":3218,"s":27,"a":59,"t":"Dis: «Louange à Allah et paix sur Ses serviteurs qu'Il a élus!» Lequel est meilleur: Allah ou bien ce qu'ils Lui associent?"},{"n":3219,"s":27,"a":60,"t":"N'est-ce pas Lui qui a créé les cieux et la terre et qui vous a fait descendre du ciel une eau avec laquelle Nous avons fait pousser des jardins pleins de beauté. Vous n'étiez nullement capables de faire pousser leurs arbres. Y a-t-il donc une divinité avec Allah? Non, mais ce sont des gens qui Lui donnent des égaux."},{"n":3220,"s":27,"a":61,"t":"N'est-ce pas Lui qui a établi la terre comme lieu de séjour, placé des rivières à travers elle, lui a assigné des montagnes fermes et établi une séparation entre les deux mers, - Y a-t-il donc une divinité avec Allah? Non, mais la plupart d'entre eux ne savent pas."},{"n":3221,"s":27,"a":62,"t":"N'est-ce pas Lui qui répond à l'angoissé quand il L'invoque, et qui enlève le mal, et qui vous fait succéder sur la terre, génération après génération, - Y a-t-il donc une divinité avec Allah? C'est rare que vous vous rappeliez!"},{"n":3222,"s":27,"a":63,"t":"N'est-ce pas Lui qui vous guide dans les ténèbres de la terre et de la mer, et qui envoie les vents, comme une bonne annonce précédent Sa grâce. - Y a-t-il donc une divinité avec Allah? Allah est Très Elevé au-dessus de ce qu'ils [Lui] associent."},{"n":3223,"s":27,"a":64,"t":"N'est-ce pas Lui qui commence la création, puis la refait, et qui vous nourrit du ciel et de la terre. Y a-t-il donc une divinité avec Allah? Dis: «Apportez votre preuve, si vous êtes véridiques!»"},{"n":3224,"s":27,"a":65,"t":"Dis: «Nul de ceux qui sont dans les cieux et sur la terre ne connaît l'Inconnaissable, à part Allah». Et ils ne savent pas quand ils seront ressuscités!"},{"n":3225,"s":27,"a":66,"t":"Mais leurs sciences se sont rejointes au sujet de l'autre monde. Ils doutent plutôt là-dessus. Ou plutôt ils sont aveugles à son sujet."},{"n":3226,"s":27,"a":67,"t":"Et ceux qui ne croient pas disent: «Est-ce que, quand nous serons poussière, nous et nos pères, est-ce que vraiment on nous fera sortir (de nos tombes)?"},{"n":3227,"s":27,"a":68,"t":"Certes, on nous l'a promis à nous et à nos pères, auparavant. Ce ne sont que des contes d'anciens!»"},{"n":3228,"s":27,"a":69,"t":"Dis: «Parcourez la terre et voyez ce qu'il est advenu des criminels»."},{"n":3229,"s":27,"a":70,"t":"Et ne t'afflige pas sur eux et ne sois pas angoissé à cause de leur complot."},{"n":3230,"s":27,"a":71,"t":"Et ils disent: «Pour quand cette promesse si vous êtes véridiques?»"},{"n":3231,"s":27,"a":72,"t":"Dis: «Il se peut qu'une partie de ce que vous cherchez à hâter soit déjà sur vos talons»."},{"n":3232,"s":27,"a":73,"t":"Certes, ton Seigneur est pourvoyeur de grâce aux hommes, mais la plupart d'entre eux ne sont pas reconnaissants."},{"n":3233,"s":27,"a":74,"t":"Certes, ton Seigneur sait ce que cachent leurs poitrines et ce qu'ils divulguent."},{"n":3234,"s":27,"a":75,"t":"Et il n'y a rien de caché, dans le ciel et la terre, qui ne soit dans un Livre explicite."},{"n":3235,"s":27,"a":76,"t":"Ce Coran raconte aux Enfants d'Israël la plupart des sujets sur lesquels ils divergent,"},{"n":3236,"s":27,"a":77,"t":"cependant qu'il est pour les croyants un guide et une miséricorde."},{"n":3237,"s":27,"a":78,"t":"Ton Seigneur décidera certes entre eux par Son jugement; et Il est le Tout Puissant, le Sage."},{"n":3238,"s":27,"a":79,"t":"Place donc ta confiance en Allah, car tu es de toute évidence dans la vérité et le bon droit."},{"n":3239,"s":27,"a":80,"t":"Tu ne peux faire entendre les morts ni faire entendre l'appel aux sourds quand ils s'enfuient en tournant le dos."},{"n":3240,"s":27,"a":81,"t":"Et tu ne peux non plus guider les aveugles hors de leur égarement. Tu ne feras entendre que ceux qui croient en Nos versets et se soumettent."},{"n":3241,"s":27,"a":82,"t":"Et quand la Parole tombera sur eux, Nous leur ferons sortir de terre une bête qui leur parlera; les gens n'étaient nullement convaincus de la vérité de Nos signes [ou versets]."},{"n":3242,"s":27,"a":83,"t":"Et le jour où Nous rassemblerons, de chaque communauté, une foule de ceux qui démentaient Nos révélations, et qu'ils seront placés en rangs."},{"n":3243,"s":27,"a":84,"t":"puis, quand ils seront arrivés, [Allah] dira: «Avez-vous traité de mensonges Mes signes sans les avoir embrassés de votre savoir? Ou que faisiez-vous donc?»"},{"n":3244,"s":27,"a":85,"t":"Et la Parole leur tombera dessus à cause de leurs méfaits. Et ils ne pourront rien dire."},{"n":3245,"s":27,"a":86,"t":"N'ont-ils pas vu qu'en vérité, Nous avons désigné la nuit pour qu'ils y aient du repos, et le jour pour voir? Voilà bien des preuves pour des gens qui croient."},{"n":3246,"s":27,"a":87,"t":"Et le jour où l'on soufflera dans la Trompe, tous ceux qui sont dans les cieux et ceux qui sont dans la terre seront effrayés, - sauf ceux qu'Allah a voulu [préserver]! - Et tous viendront à Lui en s'humiliant."},{"n":3247,"s":27,"a":88,"t":"Et tu verras les montagnes - tu les crois figées - alors qu'elles passent comme des nuages. Telle est l'œuvre d'Allah qui a tout façonné à la perfection. Il est Parfaitement Connaisseur de ce que vous faites!"},{"n":3248,"s":27,"a":89,"t":"Quiconque viendra avec le bien aura bien mieux, et ce jour-là, ils seront à l'abri de tout effroi."},{"n":3249,"s":27,"a":90,"t":"Et quiconque viendra avec le mal... alors ils seront culbutés le visage dans le Feu. N'êtes-vous pas uniquement rétribués selon ce que vous œuvriez?»"},{"n":3250,"s":27,"a":91,"t":"«Il m'a été seulement commandé d'adorer le Seigneur de cette Ville (la Mecque) qu'Il a sanctifiée, - et à Lui toute chose - et il m'a été commandé d'être du nombre des Musulmans,"},{"n":3251,"s":27,"a":92,"t":"et de réciter le Coran». Quiconque se guide, c'est pour lui-même en effet qu'il se guide. Et quiconque s'égare..., alors dis: «Je ne suis que l'un des avertisseurs»."},{"n":3252,"s":27,"a":93,"t":"Dis: «Louange à Allah! Il vous fera voir Ses preuves, et vous les reconnaîtrez». Ton Seigneur n'est pas inattentif à ce que vous faites."},{"n":3253,"s":28,"a":1,"t":"T'â, Sîn, Mîm."},{"n":3254,"s":28,"a":2,"t":"Voici les versets du Livre explicite."},{"n":3255,"s":28,"a":3,"t":"Nous te racontons en toute vérité, de l'histoire de Moïse et de Pharaon, à l'intention des gens qui croient."},{"n":3256,"s":28,"a":4,"t":"Pharaon était hautain sur terre; il répartit en clans ses habitants, afin d'abuser de la faiblesse de l'un d'eux: Il égorgeait leurs fils et laissait vivantes leurs femmes. Il était vraiment parmi les fauteurs de désordre."},{"n":3257,"s":28,"a":5,"t":"Mais Nous voulions favoriser ceux qui avaient été faibles sur terre et en faire des dirigeants et en faire les héritiers,"},{"n":3258,"s":28,"a":6,"t":"et les établir puissamment sur terre, et faire voir à Pharaon, à Hâmân, et à leurs soldats, ce dont ils redoutaient."},{"n":3259,"s":28,"a":7,"t":"Et Nous révélâmes à la mère de Moïse [ceci]: «Allaite-le. Et quand tu craindras pour lui, jette-le dans le flot. Et n'aie pas peur et ne t'attriste pas: Nous te le rendrons et ferons de lui un Messager»."},{"n":3260,"s":28,"a":8,"t":"Les gens de Pharaon le recueillirent, pour qu'il leur soit un ennemi et une source d'affliction! Pharaon, Hâmân et leurs soldats étaient fautifs."},{"n":3261,"s":28,"a":9,"t":"Et la femme de Pharaon dit: «(Cet enfant) réjouira mon œil et le tien! Ne le tuez pas. Il pourrait nous être utile ou le prendrons-nous pour enfant». Et ils ne pressentaient rien."},{"n":3262,"s":28,"a":10,"t":"Et le cœur de la mère de Moïse devint vide. Peu s'en fallut qu'elle ne divulguât tout, si Nous n'avions pas renforcé son cœur pour qu'elle restât du nombre des croyants."},{"n":3263,"s":28,"a":11,"t":"Elle dit à sa sœur: «Suis-le» elle l'aperçut alors de loin sans qu'ils ne s'en rendent compte."},{"n":3264,"s":28,"a":12,"t":"Nous lui avions interdit auparavant (le sein) des nourrices. Elle (la sœur de Moïse) dit donc: «Voulez-vous que je vous indique les gens d'une maison qui s'en chargeront pour vous tout en étant bienveillants à son égard?»..."},{"n":3265,"s":28,"a":13,"t":"Ainsi Nous le rendîmes à sa mère, afin que son œil se réjouisse, qu'elle ne s'affligeât pas et qu'elle sût que la promesse d'Allah est vraie. Mais la plupart d'entre eux ne savent pas."},{"n":3266,"s":28,"a":14,"t":"Et quand il eut atteint sa maturité et sa pleine formation, Nous lui donnâmes la faculté de juger et une science. C'est ainsi que Nous récompensons les bienfaisants."},{"n":3267,"s":28,"a":15,"t":"Il entra dans la ville à un moment d'inattention de ses habitants; il y trouva deux hommes qui se battaient, l'un était de ses partisans et l'autre de ses adversaires. L'homme de son parti l'appela au secours contre son ennemi. Moïse lui donna un coup de poing qui l'acheva. - [Moïse] dit: «Cela est l'œuvre du Diable. C'est vraiment un ennemi, un égareur évident»."},{"n":3268,"s":28,"a":16,"t":"Il dit: «Seigneur, je me suis fait du tort à moi-même; pardonne-moi». Et Il lui pardonna. C'est Lui vraiment le Pardonneur, le Miséricordieux!"},{"n":3269,"s":28,"a":17,"t":"Il dit: «Seigneur, grâce aux bienfaits dont tu m'as comblé, jamais je ne soutiendrai les criminels»."},{"n":3270,"s":28,"a":18,"t":"Le lendemain matin, il se trouva en ville, craintif et regardant autour de lui, quand voilà que celui qui lui avait demandé secours la veille, l'appelait à grands cris. Moïse lui dit: «Tu es certes un provocateur déclaré»."},{"n":3271,"s":28,"a":19,"t":"Quand il voulut porter un coup à leur ennemi commun, il (l'Israélite) dit: «O Moïse, veux-tu me tuer comme tu as tué un homme hier? Tu ne veux être qu'un tyran sur terre; et tu ne veux pas être parmi les bienfaiteurs»."},{"n":3272,"s":28,"a":20,"t":"Et c'est alors qu'un homme vint du bout de la ville en courant et dit: «O Moïse, les notables sont en train de se concerter à ton sujet pour te tuer. Quitte (la ville). C'est le conseil que je te donne»."},{"n":3273,"s":28,"a":21,"t":"Il sortit de là, craintif, regardant autour de lui. Il dit: «Seigneur, sauve-moi de [ce] peuple injuste!»"},{"n":3274,"s":28,"a":22,"t":"Et lorsqu'il se dirigea vers Madyan, il dit: «Je souhaite que mon Seigneur me guide sur la voie droite»."},{"n":3275,"s":28,"a":23,"t":"Et quand il fut arrivé au point d'eau de Madyan, il y trouva un attroupement de gens abreuvant [leurs bêtes] et il trouva aussi deux femmes se tenant à l'écart et retenant [leurs bêtes]. Il dit: «Que voulez-vous?» Elles dirent: «Nous n'abreuverons que quand les bergers seront partis; et notre père est fort âgé»."},{"n":3276,"s":28,"a":24,"t":"Il abreuva [les bêtes] pour elles puis retourna à l'ombre et dit: «Seigneur, j'ai grand besoin du bien que tu feras descendre vers moi»."},{"n":3277,"s":28,"a":25,"t":"Puis l'une des deux femmes vint à lui, d'une démarche timide, et lui dit: «Mon père t'appelle pour te récompenser pour avoir abreuvé pour nous». Et quand il fut venu auprès de lui et qu'il lui eut raconté son histoire, il (le vieillard) dit: «N'aie aucune crainte: tu as échappé aux gens injustes»."},{"n":3278,"s":28,"a":26,"t":"L'une d'elles dit: «O mon père, engage-le [à ton service] moyennant salaire, car le meilleur à engager c'est celui qui est fort et digne de confiance»."},{"n":3279,"s":28,"a":27,"t":"Il dit: «Je voudrais te marier à l'une de mes deux filles que voici, à condition que tu travailles à mon service durant huit ans. Si tu achèves dix [années], ce sera de ton bon gré; je ne veux cependant rien t'imposer d'excessif. Tu me trouveras, si Allah le veut, du nombre des gens de bien»."},{"n":3280,"s":28,"a":28,"t":"«C'est (conclu) entre toi et moi, dit [Moïse]. Quel que soit celui des deux termes que je m'assigne, il n'y aura nulle pression sur moi. Et Allah est Garant de ce que nous disons»."},{"n":3281,"s":28,"a":29,"t":"Puis, lorsque Moïse eut accompli la période convenue et qu'il se mit en route avec sa famille, il vit un feu du côté du Mont. Il dit à sa famille: «Demeurez ici. J'ai vu du feu. Peut-être vous en apporterai-je une nouvelle ou un tison de feu afin que vous vous réchauffiez»."},{"n":3282,"s":28,"a":30,"t":"Puis quand il y arriva, on l'appela, du flanc droit de la vallée, dans la place bénie, à partir de l'arbre: «O Moïse! C'est Moi Allah, le Seigneur de l'univers»."},{"n":3283,"s":28,"a":31,"t":"Et: «Jette ton bâton» Puis quand il le vit remuer comme si c'était un serpent, il tourna le dos sans même se retourner. «O Moïse! Approche et n'aie pas peur: tu es du nombre de ceux qui sont en sécurité."},{"n":3284,"s":28,"a":32,"t":"Introduis ta main dans l'ouverture de ta tunique: elle sortira blanche sans aucun mal. Et serre ton bras contre toi pour ne pas avoir peur. Voilà donc deux preuves de ton Seigneur pour Pharaon et ses notables. Ce sont vraiment des gens pervers»."},{"n":3285,"s":28,"a":33,"t":"«Seigneur, dit [Moïse], j'ai tué un des leurs et je crains qu'ils ne me tuent."},{"n":3286,"s":28,"a":34,"t":"Mais Aaron, mon frère, est plus éloquent que moi. Envoie-le donc avec moi comme auxiliaire, pour déclarer ma véracité: je crains, vraiment, qu'ils ne me traitent de menteur»."},{"n":3287,"s":28,"a":35,"t":"[Allah] dit: «Nous allons, par ton frère, fortifier ton bras, et vous donner des arguments irréfutables; ils ne sauront vous atteindre, grâce à Nos signes [Nos miracles]. Vous deux et ceux qui vous suivront seront les vainqueurs."},{"n":3288,"s":28,"a":36,"t":"Puis, quand Moïse vint à eux avec Nos prodiges évidents, ils dirent: «Ce n'est là que magie inventée. Jamais nous n'avons entendu parler de cela chez nos premiers ancêtres»."},{"n":3289,"s":28,"a":37,"t":"Et Moïse dit: «Mon Seigneur connaît mieux qui est venu de Sa part avec la guidée, et à qui appartiendra la Demeure finale. Vraiment, les injustes ne réussiront pas»."},{"n":3290,"s":28,"a":38,"t":"Et Pharaon dit: «O notables, je ne connais pas de divinité pour vous, autre que moi. Hâmân, allume-moi du feu sur l'argile puis construis-moi une tour peut-être alors monterai-je jusqu'au Dieu de Moïse. Je pense plutôt qu'il est du nombre des menteurs»."},{"n":3291,"s":28,"a":39,"t":"Et il s'enfla d'orgueil sur terre ainsi que ses soldats, sans aucun droit. Et ils pensèrent qu'ils ne seraient pas ramenés vers Nous."},{"n":3292,"s":28,"a":40,"t":"Nous le saisîmes donc, ainsi que ses soldats, et les jetâmes dans le flot. Regarde donc ce qu'il est advenu des injustes!"},{"n":3293,"s":28,"a":41,"t":"Nous fîmes d'eux des dirigeants qui appellent les gens au Feu. Et au Jour de la Résurrection ils ne seront pas secourus."},{"n":3294,"s":28,"a":42,"t":"Nous les fîmes suivre, dans cette vie ici-bas, d'une malédiction. Et au Jour de la Résurrection, ils seront parmi les honnis."},{"n":3295,"s":28,"a":43,"t":"Nous avons en effet, donné le Livre à Moïse, - après avoir fait périr les anciennes générations, - en tant que preuves illuminantes pour les gens, ainsi que guidée et miséricorde afin qu'ils se souviennent."},{"n":3296,"s":28,"a":44,"t":"Tu n'étais pas sur le versant ouest (du Sinaï), quand Nous avons décrété les commandements à Moïse; tu n'étais pas parmi les témoins."},{"n":3297,"s":28,"a":45,"t":"Mais Nous avons fait naître des générations dont l'âge s'est prolongé. Et tu n'étais pas [non plus] résident parmi les gens de Madyan leur récitant Nos versets; mais c'est Nous qui envoyons les Messagers."},{"n":3298,"s":28,"a":46,"t":"Et tu n'étais pas au flanc du Mont Tor quand Nous avons appelé. Mais (tu es venu comme) une miséricorde de ton Seigneur, pour avertir un peuple à qui nul avertisseur avant toi n'est venu, afin qu'ils se souviennent."},{"n":3299,"s":28,"a":47,"t":"Si un malheur les atteignait en rétribution de ce que leurs propres mains avaient préparé, ils diraient: «Seigneur, pourquoi ne nous as-Tu pas envoyé un Messager? Nous aurions alors suivi Tes versets et nous aurions été croyants»."},{"n":3300,"s":28,"a":48,"t":"Mais quand la vérité leur est venue de Notre part, ils ont dit: «Si seulement il avait reçu la même chose que Moïse! «Est-ce qu'ils n'ont pas nié ce qui auparavant fut apporté à Moïse? Ils dirent: «Deux magies se sont mutuellement soutenues!» Et ils dirent: «Nous n'avons foi en aucune»."},{"n":3301,"s":28,"a":49,"t":"Dis-leur: «Apportez donc un Livre venant d'Allah qui soit meilleur guide que ces deux-là, et je le suivrai si vous êtes véridiques»."},{"n":3302,"s":28,"a":50,"t":"Mais s'ils ne te répondent pas, sache alors que c'est seulement leurs passions qu'ils suivent. Et qui est plus égaré que celui qui suit sa passion sans une guidée d'Allah? Allah vraiment, ne guide pas les gens injustes."},{"n":3303,"s":28,"a":51,"t":"Nous leur avons déjà exposé la Parole (le Coran) afin qu'ils se souviennent."},{"n":3304,"s":28,"a":52,"t":"Ceux à qui, avant lui [le Coran], Nous avons apporté le Livre, y croient."},{"n":3305,"s":28,"a":53,"t":"Et quand on le leur récite, ils disent: «Nous y croyons. Ceci est bien la vérité émanant de notre Seigneur. Déjà avant son arrivée, nous étions Soumis»."},{"n":3306,"s":28,"a":54,"t":"Voilà ceux qui recevront deux fois leur récompense pour leur endurance, pour avoir répondu au mal par le bien, et pour avoir dépensé de ce que Nous leur avons attribué;"},{"n":3307,"s":28,"a":55,"t":"et quand ils entendent des futilités, ils s'en détournent et disent: «A nous nos actions, et à vous les vôtres. Paix sur vous. Nous ne recherchons pas les ignorants»."},{"n":3308,"s":28,"a":56,"t":"Tu [Muhammad] ne diriges pas celui que tu aimes: mais c'est Allah qui guide qui Il veut. Il connaît mieux cependant les bien-guidés."},{"n":3309,"s":28,"a":57,"t":"Et ils dirent: «Si nous suivons avec toi la bonne voie, on nous arrachera de notre terre». - Ne les avons-Nous pas établis dans une enceinte sacrée, sûre, vers laquelle des produits de toute sorte sont apportés comme attribution de Notre part? Mais la plupart d'entre eux ne savent pas."},{"n":3310,"s":28,"a":58,"t":"Et combien avons-Nous fait périr de cités qui étaient ingrates (alors que leurs habitants vivaient dans l'abondance), et voilà qu'après eux leurs demeures ne sont que très peu habitées, et c'est Nous qui en fûmes l'héritier."},{"n":3311,"s":28,"a":59,"t":"Ton Seigneur ne fait pas périr des cités avant d'avoir envoyé dans leur métropole un Messager pour leur réciter Nos versets. Et Nous ne faisons périr les cités que lorsque leurs habitants sont injustes."},{"n":3312,"s":28,"a":60,"t":"Tout ce qui vous a été donné est la jouissance éphémère de la vie ici-bas et sa parure, alors que ce qui est auprès d'Allah est meilleur et plus durable... Ne comprenez-vous donc pas?"},{"n":3313,"s":28,"a":61,"t":"Celui à qui Nous avons fait une belle promesse dont il verra l'accomplissement, est-il comparable à celui à qui Nous avons accordé la jouissance de la vie présente et qui sera ensuite le Jour de la Résurrection, de ceux qui comparaîtront (devant Nous)."},{"n":3314,"s":28,"a":62,"t":"Et le jour où Il les appellera, Il dira: «Où sont ceux que vous prétendiez être Mes associés?»"},{"n":3315,"s":28,"a":63,"t":"Ceux contre qui la Parole se réalisera diront: «Voici, Seigneur, ceux que nous avons séduits. Nous les avons séduits comme nous nous sommes dévoyés nous-mêmes. Nous les désavouons devant Toi: ce n'est pas nous qu'ils adoraient»."},{"n":3316,"s":28,"a":64,"t":"Et on [leur] dira: «Appelez vos associés». Ils les appelleront, mais ceux-ci ne leur répondront pas. Quand ils verront le châtiment, ils désireront alors avoir suivi le chemin droit (dans la vie d'ici-bas)."},{"n":3317,"s":28,"a":65,"t":"Et le jour où Il les appellera et qu'Il dira: «Que répondiez-vous aux Messagers?»"},{"n":3318,"s":28,"a":66,"t":"Ce jour-là, leurs arguments deviendront obscurs et ils ne se poseront point de questions."},{"n":3319,"s":28,"a":67,"t":"Mais celui qui se sera repenti, qui aura cru et fait le bien, il se peut qu'il soit parmi ceux qui réussissent."},{"n":3320,"s":28,"a":68,"t":"Ton Seigneur crée ce qu'Il veut et Il choisit; il ne leur a jamais appartenu de choisir. Gloire à Allah! Il transcende ce qu'ils associent à Lui!"},{"n":3321,"s":28,"a":69,"t":"Ton Seigneur sait ce que cachent leurs poitrines et ce qu'ils divulguent."},{"n":3322,"s":28,"a":70,"t":"C'est lui Allah. Pas de divinité à part Lui. A Lui la louange ici-bas comme dans l'au-delà. A Lui appartient le jugement. Et vers Lui vous serez ramenés."},{"n":3323,"s":28,"a":71,"t":"Dis: «Que diriez-vous? Si Allah vous assignait la nuit en permanence jusqu'au Jour de la Résurrection, quelle divinité autre qu'Allah pourrait vous apporter une lumière? N'entendez-vous donc pas?»"},{"n":3324,"s":28,"a":72,"t":"Dis: «Que diriez-vous? Si Allah vous assignait le jour en permanence jusqu'au Jour de la Résurrection, quelle divinité autre qu'Allah pourrait vous apporter une nuit durant laquelle vous reposeriez? N'observez-vous donc pas?»"},{"n":3325,"s":28,"a":73,"t":"C'est de par Sa miséricorde qu'Il vous a assigné la nuit et le jour: pour que vous vous y reposiez et cherchiez de Sa grâce, et afin que vous soyez reconnaissants."},{"n":3326,"s":28,"a":74,"t":"Et le jour où Il les appellera, Il dira: «Où sont ceux que vous prétendiez être Mes associés?»"},{"n":3327,"s":28,"a":75,"t":"Cependant, Nous ferons sortir de chaque communauté un témoin, puis Nous dirons: «Apportez votre preuve décisive». Ils sauront alors que la Vérité est à Allah; et que ce qu'ils avaient inventé les a abandonnés."},{"n":3328,"s":28,"a":76,"t":"En vérité, Coré [Karoûn] était du peuple de Moïse mais il était empli de violence envers eux. Nous lui avions donné des trésors dont les clefs pesaient lourd à toute une bande de gens forts. Son peuple lui dit: «Ne te réjouis point. Car Allah n'aime pas les arrogants."},{"n":3329,"s":28,"a":77,"t":"Et recherche à travers ce qu'Allah t'a donné, la Demeure dernière. Et n'oublie pas ta part en cette vie. Et sois bienfaisant comme Allah a été bienfaisant envers toi. Et ne recherche pas la corruption sur terre. Car Allah n'aime point les corrupteurs»."},{"n":3330,"s":28,"a":78,"t":"Il dit: «C'est par une science que je possède que ceci m'est venu». Ne savait-il pas qu'avant lui Allah avait fait périr des générations supérieures à lui en force et plus riches en biens? Et les criminels ne seront pas interrogés sur leurs péchés»!"},{"n":3331,"s":28,"a":79,"t":"Il sortit à son peuple dans tout son apparat. Ceux qui aimaient la vie présente dirent: «Si seulement nous avions comme ce qui a été donné à Coré. Il a été doté, certes, d'une immense fortune»."},{"n":3332,"s":28,"a":80,"t":"Tandis que ceux auxquels le savoir a été donné dirent: «Malheur à vous! La récompense d'Allah est meilleure pour celui qui croit et fait le bien». Mais elle ne sera reçue que par ceux qui endurent."},{"n":3333,"s":28,"a":81,"t":"Nous fîmes donc que la terre l'engloutît, lui et sa maison. Aucun clan en dehors d'Allah ne fut là pour le secourir, et il ne pût se secourir lui-même."},{"n":3334,"s":28,"a":82,"t":"Et ceux qui, la veille, souhaitaient d'être à sa place, se mirent à dire: «Ah! Il est vrai qu'Allah augmente la part de qui Il veut, parmi Ses serviteurs, ou la restreint. Si Allah ne nous avait pas favorisés, Il nous aurait certainement fait engloutir. Ah! Il est vrai que ceux qui ne croient pas ne réussissent pas»."},{"n":3335,"s":28,"a":83,"t":"Cette Demeure dernière, Nous la réservons à ceux qui ne recherchent, ni à s'élever sur terre, ni à y semer la corruption. Cependant, l'heureuse fin appartient aux pieux."},{"n":3336,"s":28,"a":84,"t":"Quiconque viendra avec le bien, aura meilleur que cela encore; et quiconque viendra avec le mal, (qu'il sache que) ceux qui commettront des méfaits ne seront rétribués que selon ce qu'ils ont commis."},{"n":3337,"s":28,"a":85,"t":"Celui qui t'a prescrit le Coran te ramènera certainement là où tu (souhaites) retourner. Dis: «Mon Seigneur connaît mieux celui qui a apporté la guidée et celui qui est dans un égarement évident."},{"n":3338,"s":28,"a":86,"t":"Tu n'espérais nullement que le Livre te serait révélé. Ceci n'a été que par une miséricorde de ton Seigneur. Ne sois donc jamais un soutien pour les infidèles;"},{"n":3339,"s":28,"a":87,"t":"et que ceux-ci ne te détournent point des versets d'Allah une fois qu'on les a fait descendre vers toi. Appelle les gens vers ton Seigneur et ne sois point du nombre des Associateurs."},{"n":3340,"s":28,"a":88,"t":"Et n'invoque nulle autre divinité avec Allah. Point de divinité à part Lui. Tout doit périr, sauf Son Visage. A Lui appartient le jugement; et vers Lui vous serez ramenés."},{"n":3341,"s":29,"a":1,"t":"Alif, Lâm, Mîm."},{"n":3342,"s":29,"a":2,"t":"Est-ce que les gens pensent qu'on les laissera dire: «Nous croyons!» sans les éprouver?"},{"n":3343,"s":29,"a":3,"t":"Certes, Nous avons éprouvé ceux qui ont vécu avant eux; [Ainsi] Allah connaît ceux qui disent la vérité et ceux qui mentent."},{"n":3344,"s":29,"a":4,"t":"Ou bien ceux qui commettent des méfaits, comptent-ils pouvoir Nous échapper? Comme leur jugement est mauvais!"},{"n":3345,"s":29,"a":5,"t":"Celui qui espère rencontrer Allah, le terme fixé par Allah va certainement venir. Et c'est Lui l'Audient, l'Omniscient."},{"n":3346,"s":29,"a":6,"t":"Et quiconque lutte, ne lutte que pour lui-même, car Allah peut Se passer de tout l'univers."},{"n":3347,"s":29,"a":7,"t":"Et quant à ceux qui croient et font de bonnes œuvres, Nous leur effacerons leurs méfaits, et Nous les rétribuerons de la meilleure récompense pour ce qu'ils auront accompli."},{"n":3348,"s":29,"a":8,"t":"Et Nous avons enjoint à l'homme de bien traiter ses père et mère, et «si ceux-ci te forcent à M'associer, ce dont tu n'as aucun savoir, alors ne leur obéis pas». Vers Moi est votre retour, et alors Je vous informerai de ce que vous faisiez."},{"n":3349,"s":29,"a":9,"t":"Et quant à ceux qui croient et font de bonnes œuvres, Nous les ferons certainement entrer parmi les gens de bien."},{"n":3350,"s":29,"a":10,"t":"Parmi les gens il en est qui disent: «Nous croyons en Allah» puis, si on les fait souffrir pour la cause d'Allah, ils considèrent l'épreuve de la part des hommes comme un châtiment d'Allah. Or, s'il vient du secours de ton Seigneur, ils diront certes: «Nous étions avec vous!» Allah n'est-Il pas le meilleur à savoir ce qu'il y a dans les poitrines de tout le monde?"},{"n":3351,"s":29,"a":11,"t":"Allah connaît parfaitement les croyants et connaît parfaitement les hypocrites."},{"n":3352,"s":29,"a":12,"t":"Et ceux qui ne croient pas disent à ceux qui croient; «Suivez notre sentier, et que nous supportions vos fautes». Mais ils ne supporteront rien de leurs fautes. En vérité ce sont des menteurs."},{"n":3353,"s":29,"a":13,"t":"Et très certainement, ils porteront leurs fardeaux et d'autres fardeaux en plus de leurs propres fardeaux. et ils seront interrogés, le Jour de la Résurrection, sur ce qu'ils inventaient."},{"n":3354,"s":29,"a":14,"t":"Et en effet, Nous avons envoyé Noé vers son peuple. Il demeura parmi eux mille ans moins cinquante années. Puis le déluge les emporta alors qu'ils étaient injustes."},{"n":3355,"s":29,"a":15,"t":"Puis Nous le sauvâmes, lui et les gens de l'arche; et Nous en fîmes un avertissement pour l'univers."},{"n":3356,"s":29,"a":16,"t":"Et Abraham, quand il dit à son peuple; «Adorez Allah et craignez-Le: cela vous est bien meilleur si vous saviez»."},{"n":3357,"s":29,"a":17,"t":"Vous n'adorez que des idoles, en dehors d'Allah, et vous forgez un mensonge. Ceux que vous adorez en dehors d'Allah ne possèdent aucun moyen pour vous procurer nourriture; recherchez votre subsistance auprès d'Allah. Adorez-Le et soyez-Lui reconnaissants. C'est à Lui que vous serez ramenés."},{"n":3358,"s":29,"a":18,"t":"Et si vous criez au mensonge, d'autres nations avant vous, ont aussi traité (leurs prophètes) de menteurs. Au Messager, cependant, n'incombe que la transmission claire."},{"n":3359,"s":29,"a":19,"t":"Ne voient-ils pas comment Allah commence la création puis la refait? Cela est facile pour Allah."},{"n":3360,"s":29,"a":20,"t":"Dis: «Parcourez la terre et voyez comment Il a commencé la création. Puis comment Allah crée la génération ultime. Car Allah est Omnipotent»."},{"n":3361,"s":29,"a":21,"t":"Il châtie qui Il veut et fait miséricorde à qui Il veut; et c'est vers Lui que vous serez ramenés."},{"n":3362,"s":29,"a":22,"t":"Et vous ne pourrez vous opposer à Sa puissance ni sur terre, ni au ciel; et il n'y a pas pour vous, en dehors d'Allah, ni allié ni secoureur."},{"n":3363,"s":29,"a":23,"t":"Et ceux qui ne croient pas aux versets d'Allah et à Sa rencontre, désespèrent de Ma miséricorde. Et ceux-là auront un châtiment douloureux."},{"n":3364,"s":29,"a":24,"t":"Son peuple ne fit d'autre réponse que: «tuez-le ou brûlez-le». Mais Allah le sauva du feu. C'est bien là des signes pour des gens qui croient."},{"n":3365,"s":29,"a":25,"t":"Et [Abraham] dit: «En effet, c'est pour cimenter des liens entre vous-mêmes dans la vie présente, que vous avez adopté des idoles, en dehors d'Allah. Ensuite, le Jour de la Résurrection, les uns rejetteront les autres, et les uns maudiront les autres, tandis que vous aurez le Feu pour refuge, n'aurez pas de protecteurs."},{"n":3366,"s":29,"a":26,"t":"Lot crut en lui. Il dit: «Moi, j'émigre vers mon Seigneur, car c'est Lui le Tout Puissant, le Sage»."},{"n":3367,"s":29,"a":27,"t":"Nous lui donnâmes Isaac et Jacob, et plaçâmes dans sa descendance la prophétie et le Livre. Nous lui accordâmes sa récompense ici-bas, tandis que dans l'au-delà, il sera parmi les gens de bien."},{"n":3368,"s":29,"a":28,"t":"Et Lot, quand il dit à son peuple: «Vraiment, vous commettez la turpitude où nul dans l'univers ne vous a précédés."},{"n":3369,"s":29,"a":29,"t":"Aurez-vous commerce charnel avec des mâles? Pratiquerez-vous le brigandage? Commettrez-vous le blâmable dans votre assemblée?» Mais son peuple ne fit d'autre réponse que: «Fais que le châtiment d'Allah nous vienne, si tu es du nombre des véridiques»."},{"n":3370,"s":29,"a":30,"t":"Il dit: «Seigneur, donne-moi victoire sur ce peuple de corrupteurs!»"},{"n":3371,"s":29,"a":31,"t":"Et quand Nos Anges apportèrent à Abraham la bonne annonce, ils dirent: «Nous allons anéantir les habitants de cette cité car ses habitants sont injustes»."},{"n":3372,"s":29,"a":32,"t":"Il dit: «Mais Lot s'y trouve!» Ils dirent: «Nous savons parfaitement qui y habite: nous le sauverons certainement, lui et sa famille, excepté sa femme qui sera parmi ceux qui périront»."},{"n":3373,"s":29,"a":33,"t":"Et quand Nos Anges vinrent à Lot, il fut affligé pour eux, et se sentit incapable de les protéger. Ils lui dirent: «Ne crains rien et ne t'afflige pas... Nous te sauverons ainsi que ta famille, excepté ta femme qui sera parmi ceux qui périront."},{"n":3374,"s":29,"a":34,"t":"Nous ferons tomber du ciel un châtiment sur les habitants de cette cité, pour leur perversité»."},{"n":3375,"s":29,"a":35,"t":"Et certainement, Nous avons laissé (des ruines de cette cité) un signe (d'avertissement) évident pour des gens qui comprennent."},{"n":3376,"s":29,"a":36,"t":"De même, aux Madyan (Nous envoyâmes) leur frère Chuayb qui leur dit: «O mon peuple, adorez Allah et attendez-vous au Jour dernier, et ne semez pas la corruption sur terre»."},{"n":3377,"s":29,"a":37,"t":"Mais ils le traitèrent de menteur. Le cataclysme les saisit, et au matin, ils gisaient sans vie dans leurs demeures."},{"n":3378,"s":29,"a":38,"t":"De même (Nous anéantîmes) les 'Aad et les Thamûd. - Vous le voyez clairement à travers leurs habitations - Le Diable, cependant, leur avait embelli leurs actions, au point de les repousser loin du Sentier; ils étaient pourtant invités à être clairvoyants."},{"n":3379,"s":29,"a":39,"t":"De même (Nous détruisîmes) Coré, Pharaon et Hâmân. Alors que Moïse leur apporta des preuves, ils s'enorgueillirent sur terre. Et ils n'ont pas pu [Nous] échapper."},{"n":3380,"s":29,"a":40,"t":"Nous saisîmes donc chacun pour son péché: Il y en eut sur qui Nous envoyâmes un ouragan; il y en eut que le Cri saisit; il y en eut que Nous fîmes engloutir par la terre; et il y en eut que Nous noyâmes. Cependant, Allah n'est pas tel à leur faire du tort; mais ils ont fait du tort à eux-mêmes."},{"n":3381,"s":29,"a":41,"t":"Ceux qui ont pris des protecteurs en dehors d'Allah ressemblent à l'araignée qui s'est donnée maison. Or la maison la plus fragile est celle de l'araignée. Si seulement ils savaient!"},{"n":3382,"s":29,"a":42,"t":"Allah connaît toute chose qu'ils invoquent en dehors de Lui. Et c'est Lui le Tout Puissant, le Sage."},{"n":3383,"s":29,"a":43,"t":"Telles sont les paraboles que Nous citons aux gens; cependant, seuls les savants les comprennent."},{"n":3384,"s":29,"a":44,"t":"C'est pour une juste raison qu'Allah a créé les cieux et la terre. Voilà bien là une preuve pour les croyants."},{"n":3385,"s":29,"a":45,"t":"Récite ce qui t'est révélé du Livre et accomplis la Salât. En vérité la Salât préserve de la turpitude et du blâmable. Le rappel d'Allah est certes ce qu'il y a de plus grand. Et Allah sait ce que vous faites."},{"n":3386,"s":29,"a":46,"t":"Et ne discutez que de la meilleure façon avec les gens du Livre, sauf ceux d'entre eux qui sont injustes. Et dites: «Nous croyons en ce qu'on a fait descendre vers nous et descendre vers vous, tandis que notre Dieu et votre Dieu est le même, et c'est à Lui que nous nous soumettons»."},{"n":3387,"s":29,"a":47,"t":"C'est ainsi que Nous t'avons fait descendre le Livre (le Coran). Ceux à qui Nous avons donné le Livre y croient. Et parmi ceux-ci, il en est qui y croient. Seuls les mécréants renient Nos versets."},{"n":3388,"s":29,"a":48,"t":"Et avant cela, tu ne récitais aucun livre et tu n'en écrivais aucun de ta main droite. Sinon, ceux qui nient la vérité auraient eu des doutes."},{"n":3389,"s":29,"a":49,"t":"Il consiste plutôt en des versets évidents, (préservés) dans les poitrines de ceux à qui le savoir a été donné. Et seuls les injustes renient Nos versets."},{"n":3390,"s":29,"a":50,"t":"Et ils dirent: «Pourquoi n'a-t-on pas fait descendre sur lui des prodiges de la part de son Seigneur?» Dis: «Les prodiges sont auprès d'Allah. Moi, je ne suis qu'un avertisseur bien clair»."},{"n":3391,"s":29,"a":51,"t":"Ne leur suffit-il donc point que Nous ayons fait descendre sur toi le Livre et qu'il leur soit récité? Il y a assurément là une miséricorde et un rappel pour des gens qui croient."},{"n":3392,"s":29,"a":52,"t":"Dis: «Allah suffit comme témoin entre moi et vous». Il sait ce qui est dans les cieux et la terre. Et quant à ceux qui croient au faux et ne croient pas en Allah, ceux-là seront les perdants."},{"n":3393,"s":29,"a":53,"t":"Et ils te demandent de hâter [la venue] du châtiment. S'il n'y avait pas eu un terme fixé, le châtiment leur serait certes venu. Et assurément, il leur viendra soudain, sans qu'ils en aient conscience."},{"n":3394,"s":29,"a":54,"t":"Ils te demandent de hâter [la venue] du châtiment, tandis que l'Enfer cerne les mécréants de toutes parts."},{"n":3395,"s":29,"a":55,"t":"Le jour où le châtiment les enveloppera d'en haut et sous leurs pieds. Il [leur] dira: «Goûtez à ce que vous faisiez!»"},{"n":3396,"s":29,"a":56,"t":"O Mes serviteurs qui avaient cru! Ma terre est bien vaste. Adorez-Moi donc!"},{"n":3397,"s":29,"a":57,"t":"Toute âme goûtera la mort. Ensuite c'est vers Nous que vous serez ramenés."},{"n":3398,"s":29,"a":58,"t":"Et quant à ceux qui croient et accomplissent de bonnes œuvres, Nous les installerons certes à l'étage dans le Paradis sous lequel coulent les ruisseaux, pour y demeurer éternellement. Quelle belle récompense que celle de ceux qui font le bien,"},{"n":3399,"s":29,"a":59,"t":"qui endurent, et placent leur confiance en leur Seigneur!"},{"n":3400,"s":29,"a":60,"t":"Que de bêtes ne se chargent point de leur propre nourriture! C'est Allah qui les nourrit ainsi que vous. Et c'est Lui l'Audient, l'Omniscient."},{"n":3401,"s":29,"a":61,"t":"Si tu leur demandes: «Qui a créé les cieux et la terre, et assujetti le soleil et la lune?», ils diront très certainement: «Allah». Comment se fait-il qu'ensuite ils se détournent (du chemin droit)?"},{"n":3402,"s":29,"a":62,"t":"Allah dispense largement ou restreint Ses dons à qui Il veut parmi Ses serviteurs. Certes, Allah est Omniscient."},{"n":3403,"s":29,"a":63,"t":"Si tu leur demandes: «Qui a fait descendre du ciel une eau avec laquelle Il fit revivre la terre après sa mort?», ils diront très certainement: «Allah». Dis: «Louange à Allah!» Mais la plupart d'entre eux ne raisonnent pas."},{"n":3404,"s":29,"a":64,"t":"Cette vie d'ici-bas n'est qu'amusement et jeu. La Demeure de l'au-delà est assurément la vraie vie. S'ils savaient!"},{"n":3405,"s":29,"a":65,"t":"Quand ils montent en bateau, ils invoquent Allah Lui vouant exclusivement leur culte. Une fois qu'Il les a sauvés [des dangers de la mer en les ramenant] sur la terre ferme, voilà qu'ils [Lui] donnent des associés."},{"n":3406,"s":29,"a":66,"t":"Qu'ils nient ce que nous leur avons donné et jouissent des biens de ce monde! Ils sauront bientôt!"},{"n":3407,"s":29,"a":67,"t":"Ne voient-ils pas que vraiment Nous avons fait un sanctuaire sûr [la Mecque], alors que tout autour d'eux on enlève les gens? Croiront-ils donc au faux et nieront-ils les bienfaits d'Allah?"},{"n":3408,"s":29,"a":68,"t":"Et quel pire injuste que celui qui invente un mensonge contre Allah, ou qui dément la Vérité quand elle lui parvient? N'est-ce pas dans l'Enfer une demeure pour les mécréants?"},{"n":3409,"s":29,"a":69,"t":"Et quant à ceux qui luttent pour Notre cause, Nous les guiderons certes sur Nos sentiers. Allah est en vérité avec les bienfaisants."},{"n":3410,"s":30,"a":1,"t":"Alif, Lâm, Mîm."},{"n":3411,"s":30,"a":2,"t":"Les Romains ont été vaincus,"},{"n":3412,"s":30,"a":3,"t":"dans le pays voisin, et après leur défaite ils seront les vainqueurs,"},{"n":3413,"s":30,"a":4,"t":"dans quelques années. A Allah appartient le commandement, au début et à la fin, et ce jour-là les Croyants se réjouiront"},{"n":3414,"s":30,"a":5,"t":"du secours d'Allah. Il secourt qui Il veut et Il est le Tout Puissant, le Tout Miséricordieux."},{"n":3415,"s":30,"a":6,"t":"C'est [là] la promesse d'Allah. Allah ne manque jamais à Sa promesse mais la plupart des gens ne savent pas."},{"n":3416,"s":30,"a":7,"t":"Ils connaissent un aspect de la vie présente, tandis qu'ils sont inattentifs à l'au-delà."},{"n":3417,"s":30,"a":8,"t":"N'ont-ils pas médité en eux-mêmes? Allah n'a créé les cieux et la terre et ce qui est entre eux, qu'à juste raison et pour un terme fixé. Beaucoup de gens cependant ne croient pas en la rencontre de leur Seigneur."},{"n":3418,"s":30,"a":9,"t":"N'ont-ils pas parcouru la terre pour voir ce qu'il est advenu de ceux qui ont vécu avant eux? Ceux-là les surpassaient en puissance et avaient labouré et peuplé la terre bien plus qu'ils ne l'ont fait eux-mêmes. Leurs messagers leur vinrent avec des preuves évidentes. Ce n'est pas Allah qui leur fit du tort; mais ils se firent du tort à eux-mêmes."},{"n":3419,"s":30,"a":10,"t":"Puis, mauvaise fut la fin de ceux qui faisaient le mal, ayant traité de mensonges les versets d'Allah et les ayant raillés."},{"n":3420,"s":30,"a":11,"t":"C'est Allah qui commence la création; ensuite Il la refait; puis, vers Lui vous serez ramenés."},{"n":3421,"s":30,"a":12,"t":"Et le jour où l'Heure arrivera, les criminels seront frappés de désespoir."},{"n":3422,"s":30,"a":13,"t":"Et ils n'auront point d'intercesseurs parmi ceux qu'ils associaient [à Allah] et ils renieront même leurs divinités."},{"n":3423,"s":30,"a":14,"t":"Le jour où l'Heure arrivera, ce jour-là ils se sépareront [les uns des autres]."},{"n":3424,"s":30,"a":15,"t":"Ceux qui auront cru et accompli de bonnes œuvres se réjouiront dans un jardin;"},{"n":3425,"s":30,"a":16,"t":"et quant à ceux qui n'auront pas cru et auront traité de mensonges Nos signes ainsi que la rencontre de l'au-delà, ceux-là seront emmenés au châtiment."},{"n":3426,"s":30,"a":17,"t":"Glorifiez Allah donc, soir et matin!"},{"n":3427,"s":30,"a":18,"t":"A Lui toute louange dans les cieux et la terre, dans l'après-midi et au milieu de la journée."},{"n":3428,"s":30,"a":19,"t":"Du mort, Il fait sortir le vivant, et du vivant, Il fait sortir le mort. Et Il redonne la vie à la terre après sa mort. Et c'est ainsi que l'on vous fera sortir (à la résurrection)."},{"n":3429,"s":30,"a":20,"t":"Parmi Ses signes: Il vous a créés de terre, - puis, vous voilà des hommes qui se dispersent [dans le monde] -."},{"n":3430,"s":30,"a":21,"t":"Et parmi Ses signes Il a créé de vous, pour vous, des épouses pour que vous viviez en tranquillité avec elles et Il a mis entre vous de l'affection et de la bonté. Il y a en cela des preuves pour des gens qui réfléchissent."},{"n":3431,"s":30,"a":22,"t":"Et parmi Ses signes la création des cieux et de la terre et la variété de vos idiomes et de vos couleurs. Il y a en cela des preuves pour les savants."},{"n":3432,"s":30,"a":23,"t":"Et parmi Ses signes votre sommeil la nuit et le jour, et aussi votre quête de Sa grâce. Il y a en cela des preuves pour des gens qui entendent."},{"n":3433,"s":30,"a":24,"t":"Et parmi Ses signes Il vous montre l'éclair avec crainte (de la foudre) et espoir (de la pluie), et fait descendre du ciel une eau avec laquelle Il redonne la vie à la terre après sa mort. Il y a en cela des preuves pour des gens qui raisonnent."},{"n":3434,"s":30,"a":25,"t":"Et parmi Ses signes le ciel et la terre sont maintenus par Son ordre; ensuite lorsqu'Il vous appellera d'un appel, voilà que de la terre vous surgirez."},{"n":3435,"s":30,"a":26,"t":"A Lui tous ceux qui sont dans les cieux et la terre: tous Lui sont entièrement soumis."},{"n":3436,"s":30,"a":27,"t":"Et c'est Lui qui commence la création puis la refait; et cela Lui est plus facile. Il a la transcendance absolue dans les cieux et sur la terre. C'est Lui le Tout Puissant, le Sage."},{"n":3437,"s":30,"a":28,"t":"Il vous a cité une parabole de vous-mêmes: Avez-vous associé vos esclaves à ce que Nous vous avons attribué en sorte que vous soyez tous égaux [en droit de propriété] et que vous les craignez [autant] que vous vous craignez mutuellement? C'est ainsi que Nous exposons Nos versets pour des gens qui raisonnent."},{"n":3438,"s":30,"a":29,"t":"Ceux qui ont été injustes ont plutôt suivi leurs propres passions, sans savoir. Qui donc peut guider celui qu'Allah égare? Et ils n'ont pas pour eux, de protecteur."},{"n":3439,"s":30,"a":30,"t":"Dirige tout ton être vers la religion exclusivement [pour Allah], telle est la nature qu'Allah a originellement donnée aux hommes - pas de changement à la création d'Allah -. Voilà la religion de droiture; mais la plupart des gens ne savent pas."},{"n":3440,"s":30,"a":31,"t":"Revenez repentants vers Lui; craignez-Le, accomplissez la Salât et ne soyez pas parmi les associateurs,"},{"n":3441,"s":30,"a":32,"t":"parmi ceux qui ont divisé leur religion et sont devenus des sectes, chaque parti exultant de ce qu'il détenait."},{"n":3442,"s":30,"a":33,"t":"Et quand un mal touche les gens, ils invoquent leur Seigneur en revenant à Lui repentants. Puis s'Il leur fait goûter de Sa part une miséricorde, voilà qu'une partie d'entre eux donnent à leur Seigneur des associés,"},{"n":3443,"s":30,"a":34,"t":"en sorte qu'ils deviennent ingrats envers ce que Nous leur avons donné. «Et jouissez donc. Vous saurez bientôt»."},{"n":3444,"s":30,"a":35,"t":"Avons-Nous fait descendre sur eux une autorité (un Livre) telle qu'elle parle de ce qu'ils Lui associaient?"},{"n":3445,"s":30,"a":36,"t":"Et quand Nous faisons goûter une miséricorde aux gens, ils en exultent. Mais si un malheur les atteint à cause de ce que leurs propres mains ont préparé, voilà qu'ils désespèrent."},{"n":3446,"s":30,"a":37,"t":"N'ont-ils pas vu qu'Allah dispense Ses dons ou les restreint à qui Il veut? Il y a en cela des preuves pour des gens qui croient."},{"n":3447,"s":30,"a":38,"t":"Donne donc au proche parent son dû, ainsi qu'au pauvre, et au voyageur en détresse. Cela est meilleur pour ceux qui recherchent la face d'Allah (Sa satisfaction); et ce sont eux qui réussissent."},{"n":3448,"s":30,"a":39,"t":"Tout ce que vous donnerez à usure pour augmenter vos biens aux dépens des biens d'autrui ne les accroît pas auprès d'Allah, mais ce que vous donnez comme Zakât, tout en cherchant la Face d'Allah (Sa satisfaction)... Ceux-là verront [leurs récompenses] multipliées."},{"n":3449,"s":30,"a":40,"t":"C'est Allah qui vous a créés et vous a nourris. Ensuite Il vous fera mourir, puis Il vous redonnera vie. Y en a-t-il, parmi vos associés, qui fasse quoi que ce soit de tout cela? Gloire à Lui! Il transcende ce qu'on Lui associe."},{"n":3450,"s":30,"a":41,"t":"La corruption est apparue sur la terre et dans la mer à cause de ce que les gens ont accompli de leurs propres mains; afin qu'[Allah] leur fasse goûter une partie de ce qu'ils ont œuvré; peut-être reviendront-ils (vers Allah)."},{"n":3451,"s":30,"a":42,"t":"Dis: «Parcourez la terre et regardez ce qu'il est advenu de ceux qui ont vécu avant. La plupart d'entre eux étaient des associateurs»."},{"n":3452,"s":30,"a":43,"t":"Dirige tout ton être vers la religion de droiture, avant que ne vienne d'Allah un jour qu'on ne peut repousser. Ce jour-là [les gens] seront divisés:"},{"n":3453,"s":30,"a":44,"t":"Celui qui aura mécru subira [les conséquences] de son infidélité. Et quiconque aura œuvré en bien... C'est pour eux-mêmes qu'ils préparent (leur avenir),"},{"n":3454,"s":30,"a":45,"t":"afin qu'[Allah] récompense par Sa grâce ceux qui croient et accomplissent les bonnes œuvres. En vérité, Il n'aime pas les infidèles."},{"n":3455,"s":30,"a":46,"t":"Parmi Ses signes, Il envoie les vents comme annonciateurs, pour vous faire goûter de Sa miséricorde et pour que le vaisseau vogue, par Son ordre, et que vous recherchiez de Sa grâce. Peut-être seriez-vous reconnaissants!"},{"n":3456,"s":30,"a":47,"t":"Nous avons effectivement envoyé avant toi des Messagers vers leurs peuples et ils leur apportèrent les preuves. Nous Nous vengeâmes de ceux qui commirent les crimes [de la négation]; et c'était Notre devoir de secourir les croyants."},{"n":3457,"s":30,"a":48,"t":"Allah, c'est Lui qui envoie les vents qui soulèvent des nuages; puis Il les étend dans le ciel comme Il veut; et Il les met en morceaux. Tu vois alors la pluie sortir de leurs profondeurs. Puis, lorsqu'Il atteint avec elle qui Il veut parmi Ses serviteurs, les voilà qui se réjouissent,"},{"n":3458,"s":30,"a":49,"t":"même s'ils étaient auparavant, avant qu'on ne l'ait fait descendre sur eux, désespérés."},{"n":3459,"s":30,"a":50,"t":"Regarde donc les effets de la miséricorde d'Allah comment Il redonne la vie à la terre après sa mort. C'est Lui qui fait revivre les morts et Il est Omnipotent."},{"n":3460,"s":30,"a":51,"t":"Et si Nous envoyons un vent et qu'ils voient jaunir [leur végétation], ils demeurent après cela ingrats (oubliant les bienfaits antérieurs)."},{"n":3461,"s":30,"a":52,"t":"En vérité, tu ne fais pas entendre les morts; et tu ne fais pas entendre aux sourds l'appel, s'ils s'en vont en tournant le dos."},{"n":3462,"s":30,"a":53,"t":"Tu n'es pas celui qui guide les aveugles hors de leur égarement. Tu ne fais entendre que ceux qui croient en Nos versets et qui sont alors entièrement soumis [musulmans]."},{"n":3463,"s":30,"a":54,"t":"Allah, c'est Lui qui vous a créés faibles; puis après la faiblesse, Il vous donne la force; puis après la force, Il vous réduit à la faiblesse et à la vieillesse: Il crée ce qu'Il veut et c'est Lui l'Omniscient, l'Omnipotent."},{"n":3464,"s":30,"a":55,"t":"Et le jour où l'Heure arrivera, les criminels jureront qu'ils n'ont demeuré qu'une heure. C'est ainsi qu'ils ont été détournés (de la vérité);"},{"n":3465,"s":30,"a":56,"t":"tandis que ceux à qui le savoir et la foi furent donnés diront: «Vous avez demeuré d'après le Décret d'Allah, jusqu'au Jour de la Résurrection, voici le Jour de la Résurrection, - mais vous ne saviez point»."},{"n":3466,"s":30,"a":57,"t":"ce jour-là donc, les excuses ne seront pas utiles aux injustes et on ne leur demandera pas à chercher à plaire à [Allah]."},{"n":3467,"s":30,"a":58,"t":"Et dans ce Coran, Nous avons certes cité, pour les gens, des exemples de toutes sortes. Et si tu leur apportes un prodige, ceux qui ne croient pas diront: «Certes, vous n'êtes que des imposteurs»."},{"n":3468,"s":30,"a":59,"t":"C'est ainsi qu'Allah scelle les cœurs de ceux qui ne savent pas."},{"n":3469,"s":30,"a":60,"t":"Sois donc patient, car la promesse d'Allah est vérité. Et que ceux qui ne croient pas fermement ne t'ébranlent pas!"},{"n":3470,"s":31,"a":1,"t":"Alif, Lâm, Mîm."},{"n":3471,"s":31,"a":2,"t":"Voici les versets du Livre plein de sagesse,"},{"n":3472,"s":31,"a":3,"t":"c'est un guide et une miséricorde aux bienfaisants,"},{"n":3473,"s":31,"a":4,"t":"qui accomplissent la Salât, acquittent la Zakât et qui croient avec certitude en l'au-delà."},{"n":3474,"s":31,"a":5,"t":"Ceux-là sont sur le chemin droit de leur Seigneur et ce sont eux les bienheureux."},{"n":3475,"s":31,"a":6,"t":"Et, parmi les hommes, il est [quelqu'un] qui, dénué de science, achète de plaisants discours pour égarer hors du chemin d'Allah et pour le prendre en raillerie. Ceux-là subiront un châtiment avilissant."},{"n":3476,"s":31,"a":7,"t":"Et quand on lui récite Nos versets, il tourne le dos avec orgueil, comme s'il ne les avait point entendus, comme s'il y avait un poids dans ses oreilles. Fais-lui donc l'annonce d'un châtiment douloureux."},{"n":3477,"s":31,"a":8,"t":"Ceux qui croient et accomplissent les bonnes œuvres auront les Jardins des délices,"},{"n":3478,"s":31,"a":9,"t":"pour y demeurer éternellement, - c'est en vérité une promesse d'Allah-. C'est Lui le Puissant, le Sage."},{"n":3479,"s":31,"a":10,"t":"Il a créé les cieux sans piliers que vous puissiez voir; et Il a enfoncé des montagnes fermes dans la terre pour l'empêcher de basculer avec vous; et Il y a propagé des animaux de toute espèce. Et du ciel, Nous avons fait descendre une eau, avec laquelle Nous avons fait pousser des plantes productives par couples de toute espèce."},{"n":3480,"s":31,"a":11,"t":"«Voilà la création d'Allah. Montrez-Moi donc ce qu'ont créé, ceux qui sont en dehors de Lui?» Mais les injustes sont dans un égarement évident."},{"n":3481,"s":31,"a":12,"t":"Nous avons effectivement donné à Luqmân la sagesse: «Sois reconnaissant à Allah, car quiconque est reconnaissant, n'est reconnaissant que pour soi-même; quant à celui qui est ingrat... En vérité, Allah se dispense de tout, et Il est digne de louange»."},{"n":3482,"s":31,"a":13,"t":"Et lorsque Luqmân dit à son fils tout en l'exhortant: «O mon fils, ne donne pas d'associé à Allah, car l'association à [Allah] est vraiment une injustice énorme.»"},{"n":3483,"s":31,"a":14,"t":"Nous avons commandé à l'homme [la bienfaisance envers] ses père et mère; sa mère l'a porté [subissant pour lui] peine sur peine: son sevrage a lieu à deux ans. «Sois reconnaissant envers Moi ainsi qu'envers tes parents. Vers Moi est la destination."},{"n":3484,"s":31,"a":15,"t":"Et si tous deux te forcent à M'associer ce dont tu n'as aucune connaissance, alors ne leur obéis pas; mais reste avec eux ici-bas de façon convenable. Et suis le sentier de celui qui se tourne vers Moi. Vers Moi, ensuite, est votre retour, et alors Je vous informerai de ce que vous faisiez»."},{"n":3485,"s":31,"a":16,"t":"«O mon enfant, fût-ce le poids d'un grain de moutarde, au fond d'un rocher, ou dans les cieux ou dans la terre, Allah le fera venir. Allah est infiniment Doux et Parfaitement Connaisseur."},{"n":3486,"s":31,"a":17,"t":"O mon enfant accomplis la Salât, commande le convenable, interdis le blâmable et endure ce qui t'arrive avec patience. Telle est la résolution à prendre dans toute entreprise!"},{"n":3487,"s":31,"a":18,"t":"Et ne détourne pas ton visage des hommes, et ne foule pas la terre avec arrogance: car Allah n'aime pas le présomptueux plein de gloriole."},{"n":3488,"s":31,"a":19,"t":"Sois modeste dans ta démarche, et baisse ta voix, car la plus détestée des voix, c'est bien la voix des ânes»."},{"n":3489,"s":31,"a":20,"t":"Ne voyez-vous pas qu'Allah vous a assujetti ce qui est dans les cieux et sur la terre? Et Il vous a comblés de Ses bienfaits apparents et cachés. Et parmi les gens, il y en a qui disputent à propos d'Allah, sans science, ni guidée, ni Livre éclairant."},{"n":3490,"s":31,"a":21,"t":"Et quand on leur dit: «Suivez ce qu'Allah a fait descendre», ils disent: «Nous suivons plutôt ce sur quoi nous avons trouvé nos ancêtres». Est-ce donc même si le Diable les appelait au châtiment de la fournaise!"},{"n":3491,"s":31,"a":22,"t":"Et quiconque soumet son être à Allah, tout en étant bienfaisant, s'accroche réellement à l'anse la plus ferme. La fin de toute chose appartient à Allah."},{"n":3492,"s":31,"a":23,"t":"Celui qui a mécru, que sa mécréance ne t'afflige pas: vers Nous sera leur retour et Nous les informerons de ce qu'ils faisaient. Allah connaît bien le contenu des poitrines."},{"n":3493,"s":31,"a":24,"t":"Nous leur donnons de la jouissance pour peu de temps; ensuite Nous les forcerons vers un dur châtiment."},{"n":3494,"s":31,"a":25,"t":"Si tu leur demandes: «Qui a créé les cieux et la terre?», ils diront, certes: «Allah!» Dis: «Louange à Allah!». Mais la plupart d'entre eux ne savent pas."},{"n":3495,"s":31,"a":26,"t":"A Allah appartient tout ce qui est dans les cieux et en terre. Allah est Celui qui se suffit à Lui-même, Il est Le Digne de louange!"},{"n":3496,"s":31,"a":27,"t":"Quand bien même tous les arbres de la terre se changeraient en calames [plumes pour écrire], quand bien même l'océan serait un océan d'encre où conflueraient sept autres océans, les paroles d'Allah ne s'épuiseraient pas. Car Allah est Puissant et Sage."},{"n":3497,"s":31,"a":28,"t":"Votre création et votre résurrection [à tous] sont [aussi faciles à Allah] que s'il s'agissait d'une seule âme. Certes Allah est Audient et Clairvoyant."},{"n":3498,"s":31,"a":29,"t":"N'as-tu pas vu qu'Allah fait pénétrer la nuit dans le jour, et qu'il fait pénétrer le jour dans la nuit, et qu'Il a assujetti le soleil et la lune chacun poursuivant sa course jusqu'à un terme fixé? Et Allah est Parfaitement Connaisseur de ce que vous faites."},{"n":3499,"s":31,"a":30,"t":"Il en est ainsi parce qu'Allah est la Vérité, et que tout ce qu'ils invoquent en dehors de Lui est le Faux, et qu'Allah, c'est Lui le Haut, le Grand."},{"n":3500,"s":31,"a":31,"t":"N'as-tu pas vu que c'est par la grâce d'Allah que le vaisseau vogue dans la mer, afin qu'Il vous fasse voir de Ses merveilles? Il y a en cela des preuves pour tout homme patient et reconnaissant."},{"n":3501,"s":31,"a":32,"t":"Quand une vague les recouvre comme des ombres, ils invoquent Allah, vouant leur culte exclusivement à Lui; et lorsqu'Il les sauve, en les ramenant vers la terre ferme, certains d'entre eux deviennent réticents; mais, seul le grand traître et le grand ingrat renient Nos signes."},{"n":3502,"s":31,"a":33,"t":"O hommes! Craignez votre Seigneur et redoutez un jour où le père ne répondra en quoi que ce soit pour son enfant, ni l'enfant pour son père. La promesse d'Allah est vérité. Que la vie présente ne vous trompe donc pas, et que le Trompeur (Satan) ne vous induise pas en erreur sur Allah!"},{"n":3503,"s":31,"a":34,"t":"La connaissance de l'Heure est auprès d'Allah; et c'est Lui qui fait tomber la pluie salvatrice; et Il sait ce qu'il y a dans les matrices. Et personne ne sait ce qu'il acquerra demain, et personne ne sait dans quelle terre il mourra. Certes, Allah est Omniscient et Parfaitement Connaisseur."},{"n":3504,"s":32,"a":1,"t":"Alif, Lâm, Mîm."},{"n":3505,"s":32,"a":2,"t":"La Révélation du Livre, nul doute là-dessus, émane du Seigneur de l'univers."},{"n":3506,"s":32,"a":3,"t":"Diront-ils qu'il (Muhammad) l'a inventé? Ceci est, au contraire, la vérité venant de ton Seigneur pour que tu avertisses un peuple à qui nul avertisseur avant toi n'est venu, afin qu'ils se guident."},{"n":3507,"s":32,"a":4,"t":"Allah qui a créé en six jours les cieux et la terre, et ce qui est entre eux. Ensuite Il S'est établi «Istawâ» sur le Trône. Vous n'avez, en dehors de Lui, ni allié ni intercesseur. Ne vous rappelez-vous donc pas?"},{"n":3508,"s":32,"a":5,"t":"Du ciel à la terre, Il administre l'affaire, laquelle ensuite monte vers Lui en un jour équivalent à mille ans de votre calcul."},{"n":3509,"s":32,"a":6,"t":"C'est Lui le Connaisseur [des mondes] inconnus et visibles, le Puissant, le Miséricordieux,"},{"n":3510,"s":32,"a":7,"t":"qui a bien fait tout ce qu'Il a créé. Et Il a commencé la création de l'homme à partir de l'argile,"},{"n":3511,"s":32,"a":8,"t":"puis Il tira sa descendance d'une goutte d'eau vile [le sperme];"},{"n":3512,"s":32,"a":9,"t":"puis Il lui donna sa forme parfaite et lui insuffla de Son Esprit. Et Il vous a assigné l'ouïe, les yeux et le cœur. Que vous êtes peu reconnaissants!"},{"n":3513,"s":32,"a":10,"t":"Et ils disent: «Quand nous serons perdus dans la terre [sous forme de poussière], redeviendrons-nous une création nouvelle?» En outre, ils ne croient pas en la rencontre avec leur Seigneur."},{"n":3514,"s":32,"a":11,"t":"Dis: «L'Ange de la mort qui est chargé de vous, vous fera mourir. Ensuite, vous serez ramenés vers Votre Seigneur»."},{"n":3515,"s":32,"a":12,"t":"Si tu voyais alors les criminels [comparaître], têtes basses devant leur Seigneur! «Notre Seigneur, Nous avons vu et entendu, renvoie-nous donc afin que nous puissions faire du bien; nous croyons [maintenant] avec certitude»."},{"n":3516,"s":32,"a":13,"t":"«Si Nous voulions, Nous apporterions à chaque âme sa guidée. Mais la parole venant de Moi doit être réalisée: «J'emplirai l'Enfer de djinns et d'hommes réunis»."},{"n":3517,"s":32,"a":14,"t":"«Goûtez donc! Pour avoir oublié la rencontre de votre jour que voici. Nous aussi Nous vous avons oubliés. Goûtez au châtiment éternel pour ce que vous faisiez»."},{"n":3518,"s":32,"a":15,"t":"Seuls croient en Nos versets ceux qui, lorsqu'on les leur rappelle, tombent prosternés et, par des louanges à leur Seigneur, célèbrent Sa gloire et ne s'enflent pas d'orgueil."},{"n":3519,"s":32,"a":16,"t":"Ils s'arrachent de leurs lits pour invoquer leur Seigneur, par crainte et espoir; et ils font largesse de ce que Nous leur attribuons."},{"n":3520,"s":32,"a":17,"t":"Aucun être ne sait ce qu'on a réservé pour eux comme réjouissance pour les yeux, en récompense de ce qu'ils œuvraient!"},{"n":3521,"s":32,"a":18,"t":"Celui qui est croyant est-il comparable au pervers? (Non), ils ne sont point égaux."},{"n":3522,"s":32,"a":19,"t":"Ceux qui croient et accomplissent les bonnes œuvres, auront leur résidence dans les Jardins du Refuge, en récompense de ce qu'ils œuvraient."},{"n":3523,"s":32,"a":20,"t":"Et quant à ceux qui auront été pervers, leur refuge sera le Feu: toutes les fois qu'ils voudront en sortir, ils y seront ramenés, et on leur dira: «Goûtez au châtiment du Feu auquel vous refusiez de croire»."},{"n":3524,"s":32,"a":21,"t":"Nous leur ferons certainement goûter au châtiment ici-bas, avant le grand châtiment afin qu'ils retournent (vers le chemin droit)!"},{"n":3525,"s":32,"a":22,"t":"Qui est plus injuste que celui à qui les versets d'Allah sont rappelés et qui ensuite s'en détourne? Nous nous vengerons certes des criminels."},{"n":3526,"s":32,"a":23,"t":"Nous avons effectivement donné à Moïse le Livre - ne sois donc pas en doute sur ta rencontre avec lui -, et l'avons assigné comme guide aux Enfants d'Israël."},{"n":3527,"s":32,"a":24,"t":"Et Nous avons désigné parmi eux des dirigeants qui guidaient (les gens) par Notre ordre aussi longtemps qu'ils enduraient et croyaient fermement en Nos versets."},{"n":3528,"s":32,"a":25,"t":"Ton Seigneur, c'est Lui qui décidera entre eux, au Jour de la Résurrection, de ce sur quoi ils divergeaient."},{"n":3529,"s":32,"a":26,"t":"N'est-ce pas pour eux une indication le fait qu'avant eux, Nous ayons fait périr tant de générations dans les maisons desquelles ils marchent? Il y a en cela des preuves! N'écouteront-ils donc pas?"},{"n":3530,"s":32,"a":27,"t":"N'ont-ils pas vu que Nous poussons l'eau vers un sol aride, qu'ensuite Nous en faisons sortir une culture que consomment leurs bestiaux et eux-mêmes? Ne voient-ils donc pas,?"},{"n":3531,"s":32,"a":28,"t":"Et ils disent: «A quand cette victoire, si vous êtes véridiques?»"},{"n":3532,"s":32,"a":29,"t":"Dis: «Le jour de la Victoire, il sera inutile aux infidèles de croire! Et aucun délai ne leur sera donné»."},{"n":3533,"s":32,"a":30,"t":"Eloigne-toi d'eux et attends. Eux aussi demeurent dans l'attente."},{"n":3534,"s":33,"a":1,"t":"O Prophète! Crains Allah et n'obéis pas aux infidèles et aux hypocrites, car Allah demeure Omniscient et Sage."},{"n":3535,"s":33,"a":2,"t":"Et suis ce qui t'est révélé émanant de Ton Seigneur. Car Allah est Parfaitement Connaisseur de ce que vous faites."},{"n":3536,"s":33,"a":3,"t":"Et place ta confiance en Allah. Allah te suffit comme protecteur."},{"n":3537,"s":33,"a":4,"t":"Allah n'a pas placé à l'homme deux cœurs dans sa poitrine. Il n'a point assimilé à vos mères vos épouses [à qui vous dites en les répudiant]: «Tu es [aussi illicite] pour moi que le dos de ma mère». Il n'a point fait de vos enfants adoptifs vos propres enfants. Ce sont des propos [qui sortent] de votre bouche. Mais Allah dit la vérité et c'est Lui qui met [l'homme] dans la bonne direction."},{"n":3538,"s":33,"a":5,"t":"Appelez-les du nom de leurs pères: c'est plus équitable devant Allah. Mais si vous ne connaissez pas leurs pères, alors considérez-les comme vos frères en religion ou vos alliés. Nul blâme sur vous pour ce que vous faites par erreur, mais (vous serez blâmés pour) ce que vos cœurs font délibérément. Allah, cependant, est Pardonneur et Miséricordieux."},{"n":3539,"s":33,"a":6,"t":"Le Prophète a plus de droit sur les croyants qu'ils n'en ont sur eux-mêmes; et ses épouses sont leurs mères. Les liens de consanguinité ont [dans les successions] la priorité [sur les liens] unissant les croyants [de Médine] et les émigrés [de la Mecque] selon le livre d'Allah, à moins que vous ne fassiez un testament convenable en faveur de vos frères en religion. Et cela est inscrit dans le Livre."},{"n":3540,"s":33,"a":7,"t":"Lorsque Nous prîmes des prophètes leur engagement, de même que de toi, de Noé, d'Abraham, de Moïse, et de Jésus fils de Marie: et Nous avons pris d'eux un engagement solennel,"},{"n":3541,"s":33,"a":8,"t":"afin [qu'Allah] interroge les véridiques sur leur sincérité. Et Il a préparé aux infidèles un châtiment douloureux."},{"n":3542,"s":33,"a":9,"t":"O vous qui croyez! Rappelez-vous le bienfait d'Allah sur vous, quand des troupes vous sont venues et que Nous avons envoyé contre elles un vent et des troupes que vous n'avez pas vues. Allah demeure Clairvoyant sur ce que vous faites."},{"n":3543,"s":33,"a":10,"t":"Quand ils vous vinrent d'en haut et d'en bas [de toutes parts], et que les regards étaient troublés, et les cœurs remontaient aux gorges, et vous faisiez sur Allah toutes sortes de suppositions..."},{"n":3544,"s":33,"a":11,"t":"Les croyants furent alors éprouvés et secoués d'une dure secousse."},{"n":3545,"s":33,"a":12,"t":"Et quand les hypocrites et ceux qui ont la maladie [le doute] au cœur disaient: «Allah et Son messager ne nous ont promis que tromperie»."},{"n":3546,"s":33,"a":13,"t":"De même, un groupe d'entre eux dit: «Gens de Yathrib! Ne demeurez pas ici. Retournez [chez vous]». Un groupe d'entre eux demande au Prophète la permission de partir en disant: «Nos demeures sont sans protection», alors qu'elles ne l'étaient pas: ils ne voulaient que s'enfuir."},{"n":3547,"s":33,"a":14,"t":"Et si une percée avait été faite sur eux par les flancs de la ville et qu'ensuite on leur avait demandé de renier leur foi, ils auraient accepté certes, et n'auraient guère tardé,"},{"n":3548,"s":33,"a":15,"t":"tandis qu'auparavant ils avaient pris l'engagement envers Allah qu'ils ne tourneraient pas le dos. Et il sera demandé compte de tout engagement vis-à-vis d'Allah."},{"n":3549,"s":33,"a":16,"t":"Dis: «Jamais la fuite ne vous sera utile si c'est la mort (sans combat) ou le meurtre (dans le combat) que vous fuyez; dans ce cas, vous ne jouirez (de la vie) que peu (de temps)»."},{"n":3550,"s":33,"a":17,"t":"Dis: «Quel est celui qui peut vous protéger d'Allah, s'Il vous veut du mal ou s'Il veut vous accorder une miséricorde?» Et ils ne trouveront pour eux-mêmes en dehors d'Allah, ni allié ni secoureur."},{"n":3551,"s":33,"a":18,"t":"Certes, Allah connaît ceux d'entre vous qui suscitent des obstacles, ainsi que ceux qui disent à leurs frères: «Venez à nous», tandis qu'ils ne déploient que peu d'ardeur au combat,"},{"n":3552,"s":33,"a":19,"t":"avares à votre égard. Puis, quand leur vient la peur, tu les vois te regarder avec des yeux révulsés, comme ceux de quelqu'un qui s'est évanoui par peur de la mort. Une fois la peur passée, ils vous lacèrent avec des langues affilées, alors qu'ils sont chiches à faire le bien. Ceux-là n'ont jamais cru. Allah donc, rend vaines leurs actions. Et cela est facile à Allah."},{"n":3553,"s":33,"a":20,"t":"Ils pensent que les coalisés ne sont pas partis. Or si les coalisés revenaient, [ces gens-là] souhaiteraient être des nomades parmi les Bédouins et [se contenteraient] de demander de vos nouvelles. S'ils étaient parmi vous, ils n'auraient combattu que très peu."},{"n":3554,"s":33,"a":21,"t":"En effet, vous avez dans le Messager d'Allah un excellent modèle [à suivre], pour quiconque espère en Allah et au Jour dernier et invoque Allah fréquemment."},{"n":3555,"s":33,"a":22,"t":"Et quand les croyants virent les coalisés, ils dirent: «Voilà ce qu'Allah et Son messager nous avaient promis; et Allah et Son messager disaient la vérité». Et cela ne fit que croître leur foi et leur soumission."},{"n":3556,"s":33,"a":23,"t":"Il est, parmi les croyants, des hommes qui ont été sincères dans leur engagement envers Allah. Certains d'entre eux ont atteint leur fin, et d'autres attendent encore; et ils n'ont varié aucunement (dans leur engagement);"},{"n":3557,"s":33,"a":24,"t":"afin qu'Allah récompense les véridiques pour leur sincérité, et châtie, s'Il veut, les hypocrites, ou accepte leur repentir. Car Allah est Pardonneur et Miséricordieux."},{"n":3558,"s":33,"a":25,"t":"Et Allah a renvoyé, avec leur rage, les infidèles sans qu'ils n'aient obtenu aucun bien, et Allah a épargné aux croyants le combat. Allah est Fort et Puissant."},{"n":3559,"s":33,"a":26,"t":"Et Il a fait descendre de leurs forteresses ceux des gens du Livre qui les avaient soutenus [les coalisés], et Il a jeté l'effroi dans leurs cœurs; un groupe d'entre eux vous tuiez, et un groupe vous faisiez prisonniers."},{"n":3560,"s":33,"a":27,"t":"Et Il vous a fait hériter leur terre, leurs demeures, leurs biens, et aussi une terre que vous n'aviez point foulée. Et Allah est Omnipotent."},{"n":3561,"s":33,"a":28,"t":"O Prophète! Dis à tes épouses: «Si c'est la vie présente que vous désirez et sa parure, alors venez! Je vous donnerai [les moyens] d'en jouir et vous libérerai [par un divorce] sans préjudice."},{"n":3562,"s":33,"a":29,"t":"Mais si c'est Allah que vous voulez et Son messager ainsi que la Demeure dernière, Allah a préparé pour les bienfaisantes parmi vous une énorme récompense."},{"n":3563,"s":33,"a":30,"t":"O femmes du Prophète! Celle d'entre vous qui commettra une turpitude prouvée, le châtiment lui sera doublé par deux fois! Et ceci est facile pour Allah."},{"n":3564,"s":33,"a":31,"t":"Et celle d'entre vous qui est entièrement soumise à Allah et à Son messager et qui fait le bien, Nous lui accorderons deux fois sa récompense, et Nous avons préparé pour elle une généreuse attribution."},{"n":3565,"s":33,"a":32,"t":"O femmes du Prophète! Vous n'êtes comparables à aucune autre femme. Si vous êtes pieuses, ne soyez pas trop complaisantes dans votre langage, afin que celui dont le cœur est malade [l'hypocrite] ne vous convoite pas. Et tenez un langage décent."},{"n":3566,"s":33,"a":33,"t":"Restez dans vos foyers; et ne vous exhibez pas à la manière des femmes d'avant l'Islam (Jâhiliyah). Accomplissez la Salât, acquittez la Zakât et obéissez à Allah et à Son messager. Allah ne veut que vous débarrasser de toute souillure, ô gens de la maison [du prophète], et veut vous purifier pleinement."},{"n":3567,"s":33,"a":34,"t":"Et gardez dans vos mémoires ce qui, dans vos foyers, est récité des versets d'Allah et de la sagesse. Allah est Doux et Parfaitement Connaisseur."},{"n":3568,"s":33,"a":35,"t":"Les Musulmans et Musulmanes, croyants et croyantes, obéissants et obéissantes, loyaux et loyales, endurants et endurantes, craignants et craignantes, donneurs et donneuses d'aumône, jeûnants et jeûnantes, gardiens de leur chasteté et gardiennes, invocateurs souvent d'Allah et invocatrices: Allah a préparé pour eux un pardon et une énorme récompense."},{"n":3569,"s":33,"a":36,"t":"Il n'appartient pas à un croyant ou à une croyante, une fois qu'Allah et Son messager ont décidé d'une chose d'avoir encore le choix dans leur façon d'agir. Et quiconque désobéit à Allah et à Son messager, s'est égaré certes, d'un égarement évident."},{"n":3570,"s":33,"a":37,"t":"Quand tu disais à celui qu'Allah avait comblé de bienfait, tout comme toi-même l'avais comblé: «Garde pour toi ton épouse et crains Allah», et tu cachais en ton âme ce qu'Allah allait rendre public. Tu craignais les gens, et c'est Allah qui est plus digne de ta crainte. Puis quand Zayd eut cessé toute relation avec elle, Nous te la fîmes épouser, afin qu'il n'y ait aucun empêchement pour les croyants d'épouser les femmes de leurs fils adoptifs, quand ceux-ci cessent toute relation avec elles. Le commandement d'Allah doit être exécuté."},{"n":3571,"s":33,"a":38,"t":"Nul grief à faire au Prophète en ce qu'Allah lui a imposé, conformément aux lois établies pour ceux qui vécurent antérieurement. Le commandement d'Allah est un décret inéluctable."},{"n":3572,"s":33,"a":39,"t":"Ceux qui communiquaient les messages d'Allah, Le craignaient et ne redoutaient nul autre qu'Allah. Et Allah suffit pour tenir le compte de tout."},{"n":3573,"s":33,"a":40,"t":"Muhammad n'a jamais été le père de l'un de vos hommes, mais le messager d'Allah et le dernier des prophètes. Allah est Omniscient."},{"n":3574,"s":33,"a":41,"t":"O vous qui croyez! Evoquez Allah d'une façon abondante,"},{"n":3575,"s":33,"a":42,"t":"et glorifiez-Le à la pointe et au déclin du jour."},{"n":3576,"s":33,"a":43,"t":"C'est lui qui prie sur vous, - ainsi que Ses Anges -, afin qu'Il vous fasse sortir des ténèbres à la lumière; et Il est Miséricordieux envers les croyants."},{"n":3577,"s":33,"a":44,"t":"Leur salutation au jour où ils Le rencontreront sera: «Salâm» [paix], et Il leur a préparé une généreuse récompense."},{"n":3578,"s":33,"a":45,"t":"O Prophète! Nous t'avons envoyé [pour être] témoin, annonciateur, avertisseur,"},{"n":3579,"s":33,"a":46,"t":"appelant (les gens) à Allah, par Sa permission; et comme une lampe éclairante."},{"n":3580,"s":33,"a":47,"t":"Et fais aux croyants la bonne annonce qu'ils recevront d'Allah une grande grâce."},{"n":3581,"s":33,"a":48,"t":"Et n'obéis pas aux infidèles et aux hypocrites, ne prête pas attention à leur méchanceté et place ta confiance en Allah et Allah suffit comme protecteur."},{"n":3582,"s":33,"a":49,"t":"O vous qui croyez! Quand vous vous mariez avec des croyantes et qu'ensuite vous divorcez d'avec elles avant de les avoir touchées, vous ne pouvez leur imposer un délai d'attente. Donnez-leur jouissance [d'un bien] et libérez-les [par un divorce] sans préjudice."},{"n":3583,"s":33,"a":50,"t":"O Prophète! Nous t'avons rendu licites tes épouses à qui tu as donné leur mahr (dot), ce que tu as possédé légalement parmi les captives [ou esclaves] qu'Allah t'a destinées, les filles de ton oncle paternel, les filles de tes tantes paternelles, les filles de ton oncle maternel, et les filles de tes tantes maternelles, - celles qui avaient émigré en ta compagnie -, ainsi que toute femme croyante si elle fait don de sa personne au Prophète, pourvu que le Prophète consente à se marier avec elle: c'est là un privilège pour toi, à l'exclusion des autres croyants. Nous savons certes, ce que Nous leur avons imposé au sujet de leurs épouses et des esclaves qu'ils possèdent, afin qu'il n'y eût donc point de blâme contre toi. Allah est Pardonneur et Miséricordieux."},{"n":3584,"s":33,"a":51,"t":"Tu fais attendre qui tu veux d'entre elles, et tu héberges chez toi qui tu veux. Puis il ne t'est fait aucun grief si tu invites chez toi l'une de celles que tu avais écartées. Voilà ce qui est le plus propre à les réjouir, à leur éviter tout chagrin et à leur faire accepter de bon cœur ce que tu leur as donné à toutes. Allah sait, cependant, ce qui est en vos cœurs. Et Allah est Omniscient et Indulgent."},{"n":3585,"s":33,"a":52,"t":"Il ne t'est plus permis désormais de prendre [d'autres] femmes, ni de changer d'épouses, même si leur beauté te plaît; - à l'exception des esclaves que tu possèdes. Et Allah observe toute chose."},{"n":3586,"s":33,"a":53,"t":"O vous qui croyez! N'entrez pas dans les demeures du Prophète, à moins qu'invitation ne vous soit faite à un repas, sans être là à attendre sa cuisson. Mais lorsqu'on vous appelle, alors, entrez. Puis, quand vous aurez mangé, dispersez-vous, sans chercher à vous rendre familiers pour causer. Cela faisait de la peine au Prophète, mais il se gênait de vous (congédier), alors qu'Allah ne se gêne pas de la vérité. Et si vous leur demandez (à ses femmes) quelque objet, demandez-le leur derrière un rideau: c'est plus pur pour vos cœurs et leurs cœurs; vous ne devez pas faire de la peine au Messager d'Allah, ni jamais vous marier avec ses épouses après lui; ce serait, auprès d'Allah, un énorme péché."},{"n":3587,"s":33,"a":54,"t":"Que vous divulguiez une chose ou que vous la cachiez,... Allah demeure Omniscient."},{"n":3588,"s":33,"a":55,"t":"Nul grief sur elles au sujet de leurs pères, leurs fils, leurs frères, les fils de leurs frères, les fils de leurs sœurs, leurs femmes [de suite] et les esclaves qu'elles possèdent. Et craignez Allah. Car Allah est témoin de toute chose."},{"n":3589,"s":33,"a":56,"t":"Certes, Allah et Ses Anges prient sur le Prophète; ô vous qui croyez priez sur lui et adressez [lui] vos salutations."},{"n":3590,"s":33,"a":57,"t":"Ceux qui offensent Allah et Son messager, Allah les maudit ici-bas, comme dans l'au-delà et leur prépare un châtiment avilissant."},{"n":3591,"s":33,"a":58,"t":"Et ceux qui offensent les croyants et les croyantes sans qu'ils l'aient mérité, se chargent d'une calomnie et d'un péché évident."},{"n":3592,"s":33,"a":59,"t":"O Prophète! Dis à tes épouses, à tes filles, et aux femmes des croyants, de ramener sur elles leurs grands voiles: elles en seront plus vite reconnues et éviteront d'être offensées. Allah est Pardonneur et Miséricordieux."},{"n":3593,"s":33,"a":60,"t":"Certes, si les hypocrites, ceux qui ont la maladie au cœur, et les alarmistes [semeurs de troubles] à Médine ne cessent pas, Nous t'inciterons contre eux, et alors, ils n'y resteront que peu de temps en ton voisinage."},{"n":3594,"s":33,"a":61,"t":"Ce sont des maudits. Où qu'on les trouve, ils seront pris et tués impitoyablement:"},{"n":3595,"s":33,"a":62,"t":"Telle était la loi établie par Allah envers ceux qui ont vécu auparavant et tu ne trouveras pas de changement dans la loi d'Allah."},{"n":3596,"s":33,"a":63,"t":"Les gens t'interrogent au sujet de l'Heure. Dis: «Sa connaissance est exclusive à Allah». Qu'en sais-tu? Il se peut que l'Heure soit proche."},{"n":3597,"s":33,"a":64,"t":"Allah a maudit les infidèles et leur a préparé une fournaise,"},{"n":3598,"s":33,"a":65,"t":"pour qu'ils y demeurent éternellement, sans trouver ni allié ni secoureur."},{"n":3599,"s":33,"a":66,"t":"Le jour où leurs visages seront tournés et retournés dans le Feu, ils diront: «Hélas pour nous! Si seulement nous avions obéi à Allah et obéi au Messager!»"},{"n":3600,"s":33,"a":67,"t":"Et ils dirent: «Seigneur, nous avons obéi à nos chefs et à nos grands. C'est donc eux qui nous ont égarés du Sentier."},{"n":3601,"s":33,"a":68,"t":"O notre Seigneur, inflige-leur deux fois le châtiment et maudis les d'une grande malédiction»."},{"n":3602,"s":33,"a":69,"t":"O vous qui croyez! Ne soyez pas comme ceux qui ont offensé Moïse. Allah l'a déclaré innocent de leurs accusations, car il était honorable auprès d'Allah."},{"n":3603,"s":33,"a":70,"t":"O vous qui croyez! Craignez Allah et parlez avec droiture,"},{"n":3604,"s":33,"a":71,"t":"afin qu'Il améliore vos actions et vous pardonne vos péchés. Quiconque obéit à Allah et à Son messager obtient certes une grande réussite."},{"n":3605,"s":33,"a":72,"t":"Nous avions proposé aux cieux, à la terre et aux montagnes la responsabilité (de porter les charges de faire le bien et d'éviter le mal). Ils ont refusé de la porter et en ont eu peur, alors que l'homme s'en est chargé; car il est très injuste [envers lui-même] et très ignorant."},{"n":3606,"s":33,"a":73,"t":"[Il en est ainsi] afin qu'Allah châtie les hypocrites, hommes et femmes, et les associateurs et les associatrices et Allah accueille le repentir des croyants et des croyantes. Allah est Pardonneur et Miséricordieux."},{"n":3607,"s":34,"a":1,"t":"Louange à Allah à qui appartient tout ce qui est dans les cieux et tout ce qui est sur la terre. Et louange à Lui dans l'au-delà. Et c'est Lui le Sage, le Parfaitement Connaisseur."},{"n":3608,"s":34,"a":2,"t":"Il sait ce qui pénètre en terre et ce qui en sort, ce qui descend du ciel et ce qui y remonte. Et c'est Lui le Miséricordieux, le Pardonneur."},{"n":3609,"s":34,"a":3,"t":"Ceux qui ne croient pas disent: «L'Heure ne nous viendra pas». Dis: «Par mon Seigneur! Très certainement, elle vous viendra. [Mon Seigneur] le Connaisseur de l'Inconnaissable. Rien ne Lui échappe fût-il du poids d'un atome dans les cieux, comme sur la terre. Et rien n'existe de plus petit ni de plus grand, qui ne soit inscrit dans un Livre explicite,"},{"n":3610,"s":34,"a":4,"t":"afin qu'Il récompense ceux qui croient et accomplissent les bonnes œuvres. Pour ceux-ci, il y aura un pardon et un don généreux."},{"n":3611,"s":34,"a":5,"t":"Et ceux qui s'efforcent de rendre vains Nos versets, ceux-là auront le châtiment d'un supplice douloureux."},{"n":3612,"s":34,"a":6,"t":"Et ceux à qui le savoir a été donné voient que ce qu'on t'a fait descendre de la part de ton Seigneur est la vérité qui guide au chemin du Tout Puissant, du Digne de Louange."},{"n":3613,"s":34,"a":7,"t":"Et ceux qui ne croient pas dirent: «Voulez-vous que l'on vous montre un homme qui vous prédise que lorsque vous serez complètement désintégrés, vous reparaîtrez, sans nul doute, en une nouvelle création?"},{"n":3614,"s":34,"a":8,"t":"Invente-t-il un mensonge contre Allah? ou bien est-il fou?» [Non], mais ceux qui ne croient pas en l'au-delà sont voués au châtiment et à l'égarement lointain."},{"n":3615,"s":34,"a":9,"t":"Ne voient-ils donc pas ce qu'il y a comme ciel et comme terre devant et derrière eux? Si Nous voulions, Nous ferions que la terre les engloutisse, ou que des morceaux du ciel tombent sur eux. Il y a en cela une preuve pour tout serviteur repentant."},{"n":3616,"s":34,"a":10,"t":"Nous avons certes accordé une grâce à David de Notre part. O montagnes et oiseaux, répétez avec lui (les louanges d'Allah). Et pour lui, Nous avons amolli le fer,"},{"n":3617,"s":34,"a":11,"t":"(en lui disant): «Fabrique des cottes de mailles complètes et mesure bien les mailles». Et faites le bien. Je suis Clairvoyant sur ce que vous faites."},{"n":3618,"s":34,"a":12,"t":"Et à Salomon (Nous avons assujetti) le vent, dont le parcours du matin équivaut à un mois (de marche) et le parcours du soir, un mois aussi. Et pour lui Nous avons fait couler la source de cuivre. Et parmi les djinns il y en a qui travaillaient sous ses ordres, par permission de son Seigneur. Quiconque d'entre eux, cependant, déviait de Notre ordre, Nous lui faisions goûter au châtiment de la fournaise."},{"n":3619,"s":34,"a":13,"t":"Ils exécutaient pour lui ce qu'il voulait: sanctuaires, statues, plateaux comme des bassins, et marmites bien ancrées. - «O famille de David, œuvrez par gratitude», alors qu'il y a eu peu de Mes serviteurs qui sont reconnaissants."},{"n":3620,"s":34,"a":14,"t":"Puis, quand Nous décidâmes sa mort, il n'y eut pour les avertir de sa mort que la «bête de terre», qui rongea sa canne. Puis lorsqu'il s'écroula, il apparut de toute évidence aux djinns que s'ils savaient vraiment l'inconnu, ils ne seraient pas restés dans le supplice humiliant [de la servitude]."},{"n":3621,"s":34,"a":15,"t":"Il y avait assurément, pour la tribu de Saba' un Signe dans leurs habitat: deux jardins, l'un à droite et l'autre à gauche. «Mangez de ce que votre Seigneur vous a attribué, et soyez-Lui reconnaissants: une bonne contrée et un Seigneur Pardonneur»."},{"n":3622,"s":34,"a":16,"t":"Mais ils se détournèrent. Nous déchaînâmes contre eux l'inondation du Barrage, et leur changeâmes leurs deux jardins en deux jardins aux fruits amers, tamaris et quelques jujubiers."},{"n":3623,"s":34,"a":17,"t":"Ainsi les rétribuâmes Nous pour leur mécréance. Saurions-Nous sanctionner un autre que le mécréant?"},{"n":3624,"s":34,"a":18,"t":"Et Nous avions placé entre eux et les cités que Nous avions bénies, d'autres cités proéminentes, et Nous avions évalué les étapes de voyage entre elles. «Voyagez entre elles pendant des nuits et des jours, en sécurité»."},{"n":3625,"s":34,"a":19,"t":"Puis, ils dirent: «Seigneur, allonge les distances entre nos étapes», et ils se firent du tort à eux-mêmes. Nous fîmes d'eux, donc, des sujets de légendes et les désintégrâmes totalement. Il y a en cela des avertissements pour tous grand endurant et grand reconnaissant."},{"n":3626,"s":34,"a":20,"t":"Et Satan a très certainement rendu véridique sa conjecture à leur égard. Ils l'ont suivi donc, sauf un groupe parmi les croyants."},{"n":3627,"s":34,"a":21,"t":"Et pourtant il n'avait sur eux aucun pouvoir si ce n'est que Nous voulions distinguer celui qui croyait en l'au-delà et celui qui doutait. Ton Seigneur, cependant, assure la sauvegarde de toute chose."},{"n":3628,"s":34,"a":22,"t":"Dis: «Invoquez ceux qu'en dehors d'Allah vous prétendez [être des divinités]. Ils ne possèdent même pas le poids d'un atome, ni dans les cieux ni sur la terre. Ils n'ont jamais été associés à leur création et Il n'a personne parmi eux pour Le soutenir»."},{"n":3629,"s":34,"a":23,"t":"L'intercession auprès de Lui ne profite qu'à celui en faveur duquel Il la permet. Quand ensuite la frayeur se sera éloignée de leurs cœurs, ils diront: «Qu'a dit votre Seigneur?» Ils répondront: «La Vérité; C'est Lui le Sublime, le Grand»."},{"n":3630,"s":34,"a":24,"t":"Dis: «Qui vous nourrit du ciel et de la terre?» Dis: «Allah. C'est nous ou bien vous qui sommes sur une bonne voie, ou dans un égarement manifeste»."},{"n":3631,"s":34,"a":25,"t":"Dis: «Vous ne serez pas interrogés sur les crimes que nous avons commis, et nous ne serons pas interrogés sur ce que vous faites»."},{"n":3632,"s":34,"a":26,"t":"Dis: «Notre Seigneur nous réunira, puis Il tranchera entre nous, avec la vérité, car c'est Lui le Grand Juge, l'Omniscient»."},{"n":3633,"s":34,"a":27,"t":"Dis: «Montrez-moi ceux que vous Lui avez donnés comme associés. Eh bien, non! C'est plutôt Lui, Allah, le Puissant, le Sage»."},{"n":3634,"s":34,"a":28,"t":"Et Nous ne t'avons envoyé qu'en tant qu'annonciateur et avertisseur pour toute l'humanité. Mais la plupart des gens ne savent pas."},{"n":3635,"s":34,"a":29,"t":"Et ils disent: «A quand cette promesse, si vous êtes véridiques?»"},{"n":3636,"s":34,"a":30,"t":"Dis: «Le rendez-vous est pour un jour que vous ne saurez retarder d'une heure, ni avancer!»"},{"n":3637,"s":34,"a":31,"t":"Et ceux qui avaient mécru dirent: «Jamais nous ne croirons à ce Coran ni à ce qui l'a précédé». Et si tu pouvais voir quand les injustes seront debout devant leur Seigneur, se renvoyant la parole les uns aux autres! Ceux que l'on considérait comme faibles diront à ceux qui s'enorgueillissaient: «Sans vous, nous aurions certes été croyants»."},{"n":3638,"s":34,"a":32,"t":"Ceux qui s'enorgueillissaient diront à ceux qu'ils considéraient comme faibles: «Est-ce nous qui vous avons repoussés de la bonne direction après qu'elle vous fut venue? Mais vous étiez plutôt des criminels»."},{"n":3639,"s":34,"a":33,"t":"Et ceux que l'on considérait comme faibles diront à ceux qui s'enorgueillissaient: «C'était votre stratagème, plutôt, nuit et jour, de nous commander de ne pas croire en Allah et de Lui donner des égaux». Et ils cacheront leur regret quand ils verront le châtiment. Nous placerons des carcans aux cous de ceux qui ont mécru: les rétribuerait-on autrement que selon ce qu'ils œuvraient?»"},{"n":3640,"s":34,"a":34,"t":"Et Nous n'avons envoyé aucun avertisseur dans une cité sans que ses gens aisés n'aient dit: «Nous ne croyons pas au message avec lequel vous êtes envoyés»."},{"n":3641,"s":34,"a":35,"t":"Et ils dirent: «Nous avons davantage de richesses et d'enfants et nous ne serons pas châtiés»."},{"n":3642,"s":34,"a":36,"t":"Dis: «Mon Seigneur dispense avec largesse ou restreint Ses dons à qui Il veut. Mais la plupart des gens ne savent pas»."},{"n":3643,"s":34,"a":37,"t":"Ni vos biens ni vos enfants ne vous rapprocheront à proximité de Nous. Sauf celui qui croit et œuvre dans le bien. Ceux-là auront une double récompense pour ce qu'ils œuvraient, tandis qu'ils seront en sécurité, aux étages supérieurs (du Paradis)."},{"n":3644,"s":34,"a":38,"t":"Et quant à ceux qui s'efforcent à rendre Nos versets inefficients, ceux-là seront forcés de se présenter au châtiment."},{"n":3645,"s":34,"a":39,"t":"Dis: «Mon Seigneur dispense avec largesse ou restreint Ses dons à qui Il veut parmi ses serviteurs. Et toute dépense que vous faites [dans le bien], Il la remplace, et c'est Lui le Meilleur des donateurs»."},{"n":3646,"s":34,"a":40,"t":"Et un jour Il les rassemblera tous. Puis Il dira aux Anges: «Est-ce vous que ces gens-là adoraient?»"},{"n":3647,"s":34,"a":41,"t":"Ils diront: «Gloire à Toi! Tu es notre Allié en dehors d'eux. Ils adoraient plutôt les djinns, en qui la plupart d'entre eux croyaient."},{"n":3648,"s":34,"a":42,"t":"Ce jour-là donc, vous n'aurez aucun moyen pour profiter ou nuire les uns aux autres, tandis que Nous dirons aux injustes: «Goûtez au châtiment du Feu que vous traitiez de mensonge»."},{"n":3649,"s":34,"a":43,"t":"Et quand Nos versets édifiants leur sont récités, ils disent: Ce n'est là qu'un homme qui veut vous repousser de ce que vos ancêtres adoraient». Et ils disent: «Ceci (Le Coran) n'est qu'un mensonge inventé». Et ceux qui ne croient pas disent de la Vérité quand elle leur vient: «Ce n'est là qu'une magie évidente!»"},{"n":3650,"s":34,"a":44,"t":"[Pourtant] Nous ne leur avons pas donné de livres à étudier. Et Nous ne leur avons envoyé avant toi aucun avertisseur."},{"n":3651,"s":34,"a":45,"t":"Ceux d'avant eux avaient [aussi] démenti (leurs messagers). [Les Mecquois] n'ont pas atteint le dixième de ce que Nous leur avons donné [en force et en richesse]. Ils traitaient Mes Messagers de menteurs. Et quelle réprobation fut la mienne!"},{"n":3652,"s":34,"a":46,"t":"Dis: «Je vous exhorte seulement à une chose: que pour Allah vous vous leviez, par deux ou isolément, et qu'ensuite vous réfléchissiez. Votre compagnon (Muhammad) n'est nullement possédé: il n'est pour vous qu'un avertisseur annonçant un dur châtiment»."},{"n":3653,"s":34,"a":47,"t":"Dis: «Ce que je vous demande comme salaire, c'est pour vous-mêmes. Car mon salaire n'incombe qu'à Allah. Il est Témoin de toute chose»."},{"n":3654,"s":34,"a":48,"t":"Dis: «Certes, mon Seigneur lance la Vérité, [à Ses messagers], Il est le Parfait Connaisseur des inconnaissables»."},{"n":3655,"s":34,"a":49,"t":"Dis: «La vérité [l'Islam] est venue. Et le Faux [la mécréance] ne peut rien commencer ni renouveler»."},{"n":3656,"s":34,"a":50,"t":"Dis: «Si je m'égare, je ne m'égare qu'à mes dépens; tandis que si je me guide, alors c'est grâce à ce que Mon Seigneur me révèle, car Il est Audient et Proche»."},{"n":3657,"s":34,"a":51,"t":"Si tu les voyais quand ils seront saisis de peur, - pas d'échappatoire pour eux -, et ils seront saisis de près!"},{"n":3658,"s":34,"a":52,"t":"Ils diront alors: «Nous croyons en lui». - Mais comment atteindront-ils la foi de si loin?"},{"n":3659,"s":34,"a":53,"t":"alors qu'auparavant ils y avaient effectivement mécru et ils offensent l'inconnu à partir d'un endroit éloigné !"},{"n":3660,"s":34,"a":54,"t":"On les empêchera d'atteindre ce qu'ils désirent, comme cela fut fait auparavant avec leurs semblables, car ils se trouvaient dans un doute profond."},{"n":3661,"s":35,"a":1,"t":"Louange à Allah, Créateur des cieux et de la terre, qui a fait des Anges des messagers dotés de deux, trois ou quatre ailes. Il ajoute à la création ce qu'Il veut, car Allah est Omnipotent."},{"n":3662,"s":35,"a":2,"t":"Ce qu'Allah accorde en miséricorde aux gens, il n'est personne à pouvoir le retenir. Et ce qu'Il retient, il n'est personne à le relâcher après Lui. Et c'est Lui le Puissant, le Sage."},{"n":3663,"s":35,"a":3,"t":"O hommes! Rappelez-vous le bienfait d'Allah sur vous: existe-t-il en dehors d'Allah, un créateur qui du ciel et de la terre vous attribue votre subsistance? Point de divinité à part Lui! Comment pouvez-vous vous détourner [de cette vérité]?"},{"n":3664,"s":35,"a":4,"t":"Et s'ils te traitent de menteur, certes on a traité de menteurs des Messagers avant toi. Vers Allah cependant, tout est ramené."},{"n":3665,"s":35,"a":5,"t":"O hommes! La promesse d'Allah est vérité. Ne laissez pas la vie présente vous tromper, et que le grand trompeur (Satan) ne vous trompe pas à propos d'Allah!"},{"n":3666,"s":35,"a":6,"t":"Le Diable est pour vous un ennemi. Prenez-le donc pour ennemi. Il ne fait qu'appeler ses partisans pour qu'ils soient des gens de la Fournaise."},{"n":3667,"s":35,"a":7,"t":"Ceux qui ont mécru auront un dur châtiment, tandis que ceux qui croient et accomplissent les bonnes œuvres auront un pardon et une grosse récompense."},{"n":3668,"s":35,"a":8,"t":"Eh quoi! Celui à qui on a enjolivé sa mauvaise action au point qu'il la voit belle...? - Mais Allah égare qui Il veut, et guide qui Il veut - Que ton âme ne se répande donc pas en regrets pour eux: Allah est Parfaitement Savant de ce qu'ils fabriquent."},{"n":3669,"s":35,"a":9,"t":"Et c'est Allah qui envoie les vents qui soulèvent un nuage que Nous poussons ensuite vers une contrée morte; puis, Nous redonnons la vie à la terre après sa mort. C'est ainsi que se fera la Résurrection!"},{"n":3670,"s":35,"a":10,"t":"Quiconque veut la puissance (qu'il la cherche auprès d'Allah) car la puissance tout entière est à Allah: vers Lui monte la bonne parole, et Il élève haut la bonne action. Et quand à ceux qui complotent de mauvaises actions, ils auront un dur châtiment. Cependant, leur stratagème est voué à l'échec."},{"n":3671,"s":35,"a":11,"t":"Et Allah vous a créés de terre, puis d'une goutte de sperme, Il vous a ensuite établis en couples. Nulle femelle ne porte ni ne met bas sans qu'Il le sache. Et aucune existence n'est prolongée ou abrégée sans que cela soit consigné dans un livre. Cela est vraiment facile pour Allah."},{"n":3672,"s":35,"a":12,"t":"Les deux mers ne sont pas identiques: [l'eau de] celle-ci est potable, douce et agréable à boire, et celle-là est salée, amère. Cependant de chacune vous mangez une chair fraîche, et vous extrayez un ornement que vous portez. Et tu vois le vaisseau fendre l'eau avec bruit, pour que vous cherchiez certains [des produits] de Sa grâce. Peut-être serez-vous reconnaissants!"},{"n":3673,"s":35,"a":13,"t":"Il fait que la nuit pénètre le jour et que le jour pénètre la nuit. Et Il a soumis le soleil et la lune. Chacun d'eux s'achemine vers un terme fixé. Tel est Allah, votre Seigneur: à Lui appartient la royauté, tandis que ceux que vous invoquez, en dehors de Lui, ne sont même pas maîtres de la pellicule d'un noyau de datte."},{"n":3674,"s":35,"a":14,"t":"Si vous les invoquez, ils n'entendent pas votre invocation; et même s'ils entendaient, ils ne sauraient vous répondre. Et le jour du Jugement ils vont nier votre association. Nul ne peut te donner des nouvelles comme Celui qui est parfaitement informé."},{"n":3675,"s":35,"a":15,"t":"O hommes, vous êtes les indigents ayant besoin d'Allah, et c'est Allah, Lui qui se dispense de tout et Il est Le Digne de louange."},{"n":3676,"s":35,"a":16,"t":"S'Il voulait, Il vous ferait disparaître, et ferait surgir une nouvelle création."},{"n":3677,"s":35,"a":17,"t":"Et cela n'est point difficile pour Allah."},{"n":3678,"s":35,"a":18,"t":"Or, personne ne portera le fardeau d'autrui. Et si une âme surchargée [de péchés] appelle à l'aide, rien de sa charge ne sera supporté par une autre même si c'est un proche parent. Tu n'avertis en fait, que ceux qui craignent leur Seigneur malgré qu'ils ne Le voient pas, et qui accomplissent la Salât. Et quiconque se purifie ne se purifie que pour lui-même, et vers Allah est la destination."},{"n":3679,"s":35,"a":19,"t":"L'aveugle et celui qui voit ne sont pas semblables,"},{"n":3680,"s":35,"a":20,"t":"ni les ténèbres et la lumière,"},{"n":3681,"s":35,"a":21,"t":"ni l'ombre et la chaleur ardente."},{"n":3682,"s":35,"a":22,"t":"De même, ne sont pas semblables les vivants et les morts. Allah fait entendre qui Il veut, alors que toi [Muhammad], tu ne peux faire entendre ceux qui sont dans les tombeaux."},{"n":3683,"s":35,"a":23,"t":"Tu n'es qu'un avertisseur."},{"n":3684,"s":35,"a":24,"t":"Nous t'avons envoyé avec la Vérité en tant qu'annonciateur et avertisseur. Il n'est pas une nation qui n'ait déjà eu un avertisseur."},{"n":3685,"s":35,"a":25,"t":"Et s'ils te traitent de menteur, eh bien, ceux d'avant eux avaient traité (leurs Messagers) de menteurs, cependant que leurs Messagers leur avaient apporté les preuves, les Ecrits et le Livre illuminant."},{"n":3686,"s":35,"a":26,"t":"Puis J'ai saisi ceux qui ont mécru. Et quelle réprobation fut la Mienne!"},{"n":3687,"s":35,"a":27,"t":"N'as-tu pas vu que, du ciel, Allah fait descendre l'eau? Puis Nous en faisons sortir des fruits de couleurs différentes. Et dans les montagnes, il y a des sillons blancs et rouges, de couleurs différentes, et des roches excessivement noires."},{"n":3688,"s":35,"a":28,"t":"Il y a pareillement des couleurs différentes, parmi les hommes, les animaux, et les bestiaux. Parmi Ses serviteurs, seuls les savants craignent Allah. Allah est, certes, Puissant et Pardonneur."},{"n":3689,"s":35,"a":29,"t":"Ceux qui récitent le Livre d'Allah, accomplissent la Salât, et dépensent, en secret et en public de ce que Nous leur avons attribué, espèrent ainsi faire un commerce qui ne périra jamais,"},{"n":3690,"s":35,"a":30,"t":"afin [qu'Allah] les récompense pleinement et leur ajoute de Sa grâce. Il est Pardonneur et Reconnaissant."},{"n":3691,"s":35,"a":31,"t":"Et ce que Nous t'avons révélé du Livre est la Vérité confirmant ce qui l'a précédé. Certes Allah est Parfaitement Connaisseur et Clairvoyant sur Ses serviteurs."},{"n":3692,"s":35,"a":32,"t":"Ensuite, Nous fîmes héritiers du Livre ceux de Nos serviteurs que Nous avons choisis. Il en est parmi eux qui font du tort à eux-mêmes, d'autres qui se tiennent sur une voie moyenne, et d'autres avec la permission d'Allah devancent [tous les autres] par leurs bonnes actions; telle est la grâce infinie"},{"n":3693,"s":35,"a":33,"t":"Les jardins d'Eden où ils entreront, parés de bracelets en or ainsi que de perles; et là, leurs vêtements sont de soie."},{"n":3694,"s":35,"a":34,"t":"Et ils diront: «Louange à Allah qui a écarté de nous l'affliction. Notre Seigneur est certes Pardonneur et Reconnaissant."},{"n":3695,"s":35,"a":35,"t":"C'est Lui qui nous a installés, par Sa grâce, dans la Demeure de la stabilité, où nulle fatigue, nulle lassitude ne nous touchent»."},{"n":3696,"s":35,"a":36,"t":"Et ceux qui ont mécru auront le feu de l'Enfer: on ne les achève pas pour qu'ils meurent; on ne leur allège rien de ses tourments. C'est ainsi que Nous récompensons tout négateur obstiné."},{"n":3697,"s":35,"a":37,"t":"Et là, ils hurleront: «Seigneur, fais-nous sortir; nous ferons le bien, contrairement à ce que nous faisions». «Ne vous avons-Nous pas donné une vie assez longue pour que celui qui réfléchit réfléchisse? L'avertisseur, cependant, vous était venu. Et bien, goûtez (votre punition). Car pour les injustes, il n'y a pas de secoureur»."},{"n":3698,"s":35,"a":38,"t":"Allah connaît l'Inconnaissable dans les cieux et la terre. Il connaît le contenu des poitrines."},{"n":3699,"s":35,"a":39,"t":"C'est Lui qui a fait de vous des successeurs sur terre. Quiconque mécroit, sa mécréance retombera sur lui. Leur mécréance n'ajoute aux mécréants qu'opprobre auprès de leur Seigneur. Leur mécréance n'ajoute que perte aux mécréants."},{"n":3700,"s":35,"a":40,"t":"Dis: «Voyez-vous vos associés que vous invoquez en dehors d'Allah? Montrez-moi ce qu'ils ont créé de la terre. Ont-ils été associés à la création des cieux? Ou leur avons-Nous apporté un Livre qui contienne des preuves [pour ce qu'ils font?]» Non! Mais ce n'est qu'en tromperie que les injustes se font des promesses les uns aux autres."},{"n":3701,"s":35,"a":41,"t":"Allah retient les cieux et la terre pour qu'ils ne s'affaissent pas. Et s'ils s'affaissaient, nul autre après Lui ne pourra les retenir. Il est Indulgent et Pardonneur."},{"n":3702,"s":35,"a":42,"t":"Et ils ont juré solennellement par Allah, que si un avertisseur leur venait, ils seraient certes mieux guidés que n'importe quelle autre communauté. Puis, quand un avertisseur (Muhammad) leur est venu, cela n'a fait qu'accroître leur répulsion,"},{"n":3703,"s":35,"a":43,"t":"par orgueil sur terre et par manœuvre perfide. Cependant, la manœuvre perfide n'enveloppe que ses propres auteurs. Attendent-ils donc un autre sort que celui des Anciens? Or, jamais tu ne trouveras de changement dans la règle d'Allah et jamais tu ne trouveras de déviation dans la règle d'Allah."},{"n":3704,"s":35,"a":44,"t":"N'ont-ils donc jamais parcouru la terre pour voir ce qu'il est advenu de ceux qui vécurent avant eux et qui étaient plus puissants qu'eux? Et rien, dans les cieux ni sur terre ne saurait réduire l'autorité d'Allah. Car Il est certes Omniscient, Omnipotent."},{"n":3705,"s":35,"a":45,"t":"Et si Allah s'en prenait aux gens pour ce qu'ils acquièrent, Il ne laisserait à la surface [de la terre] aucun être vivant. Mais Il leur donne un délai jusqu'à un terme fixé. Puis quand leur terme viendra... (Il se saisira d'eux) car Allah est Très Clairvoyant sur Ses serviteurs."},{"n":3706,"s":36,"a":1,"t":"Yâ Sîn."},{"n":3707,"s":36,"a":2,"t":"Par le Coran plein de sagesse."},{"n":3708,"s":36,"a":3,"t":"Tu (Muhammad) es certes du nombre des messagers,"},{"n":3709,"s":36,"a":4,"t":"sur un chemin droit."},{"n":3710,"s":36,"a":5,"t":"C'est une révélation de la part du Tout Puissant, du Très Miséricordieux,"},{"n":3711,"s":36,"a":6,"t":"pour que tu avertisses un peuple dont les ancêtres n'ont pas été avertis: ils sont donc insouciants."},{"n":3712,"s":36,"a":7,"t":"En effet, la Parole contre la plupart d'entre eux s'est réalisée: ils ne croiront donc pas."},{"n":3713,"s":36,"a":8,"t":"Nous mettrons des carcans à leurs cous, et il y en aura jusqu'aux mentons: et voilà qu'ils iront têtes dressées."},{"n":3714,"s":36,"a":9,"t":"et Nous mettrons une barrière devant eux et une barrière derrière eux; Nous les recouvrirons d'un voile: et voilà qu'ils ne pourront rien voir."},{"n":3715,"s":36,"a":10,"t":"Cela leur est égal que tu les avertisses ou que tu ne les avertisses pas: ils ne croiront jamais."},{"n":3716,"s":36,"a":11,"t":"Tu avertis seulement celui qui suit le Rappel (le Coran), et craint le Tout Miséricordieux, malgré qu'il ne Le voit pas. Annonce-lui un pardon et une récompense généreuse."},{"n":3717,"s":36,"a":12,"t":"C'est Nous qui ressuscitons les morts et écrivons ce qu'ils ont fait [pour l'au-delà] ainsi que leurs traces. Et Nous avons dénombré toute chose dans un registre explicite."},{"n":3718,"s":36,"a":13,"t":"Donne-leur comme exemple les habitants de la cité, quand lui vinrent les envoyés."},{"n":3719,"s":36,"a":14,"t":"Quand Nous leur envoyâmes deux [envoyés] et qu'ils les traitèrent de menteurs. Nous [les] renforçâmes alors par un troisième et ils dirent: «Vraiment, nous sommes envoyés à vous»."},{"n":3720,"s":36,"a":15,"t":"Mais ils [les gens] dirent: «Vous n'êtes que des hommes comme nous. Le Tout Miséricordieux n'a rien fait descendre et vous ne faites que mentir»."},{"n":3721,"s":36,"a":16,"t":"Ils [les messagers] dirent: «Notre Seigneur sait qu'en vérité nous sommes envoyés à vous,"},{"n":3722,"s":36,"a":17,"t":"et il ne nous incombe que de transmettre clairement (notre message)»."},{"n":3723,"s":36,"a":18,"t":"Ils dirent: «Nous voyons en vous un mauvais présage. Si vous ne cessez pas, nous vous lapiderons et un douloureux châtiment de notre part vous touchera»."},{"n":3724,"s":36,"a":19,"t":"Ils dirent: «Votre mauvais présage est avec vous-mêmes. Est-ce que (c'est ainsi que vous agissez) quand on vous [le] rappelle? Mais vous êtes des gens outranciers!»"},{"n":3725,"s":36,"a":20,"t":"Et du bout de la ville, un homme vint en toute hâte et dit: «O mon peuple, suivez les messagers:"},{"n":3726,"s":36,"a":21,"t":"suivez ceux qui ne vous demandent aucun salaire et qui sont sur la bonne voie."},{"n":3727,"s":36,"a":22,"t":"et qu'aurais-je à ne pas adorer Celui qui m'a créé? Et c'est vers Lui que vous serez ramenés."},{"n":3728,"s":36,"a":23,"t":"Prendrais-je en dehors de Lui des divinités? Si le Tout Miséricordieux me veut du mal, leur intercession de me servira à rien et ils ne me sauveront pas."},{"n":3729,"s":36,"a":24,"t":"Je serai alors dans un égarement évident."},{"n":3730,"s":36,"a":25,"t":"[Mais] je crois en votre Seigneur. Ecoutez-moi donc»."},{"n":3731,"s":36,"a":26,"t":"Alors, il [lui] fut dit: «Entre au Paradis». Il dit: «Ah si seulement mon peuple savait!"},{"n":3732,"s":36,"a":27,"t":"...en raison de quoi mon Seigneur m'a pardonné et mis au nombre des honorés»."},{"n":3733,"s":36,"a":28,"t":"Et après lui Nous ne fîmes descendre du ciel aucune armée. Nous ne voulions rien faire descendre sur son peuple."},{"n":3734,"s":36,"a":29,"t":"Ce ne fut qu'un seul Cri et les voilà éteints."},{"n":3735,"s":36,"a":30,"t":"Hélas pour les esclaves [les humains]! Jamais il ne leur vient de messager sans qu'ils ne s'en raillent."},{"n":3736,"s":36,"a":31,"t":"Ne voient-ils pas combien de générations avant eux Nous avons fait périr? Lesquelles ne retourneront jamais parmi eux."},{"n":3737,"s":36,"a":32,"t":"Et tous sans exception comparaîtront devant Nous."},{"n":3738,"s":36,"a":33,"t":"Une preuve pour eux est la terre morte, à laquelle Nous redonnons la vie, et d'où Nous faisons sortir des grains dont ils mangent."},{"n":3739,"s":36,"a":34,"t":"Nous y avons mis des jardins de palmiers et de vignes et y avons fait jaillir des sources,"},{"n":3740,"s":36,"a":35,"t":"afin qu'ils mangent de Ses fruits et de ce que leurs mains ont produit. Ne seront-ils pas reconnaissants?"},{"n":3741,"s":36,"a":36,"t":"Louange à Celui qui a créé tous les couples de ce que la terre fait pousser, d'eux-mêmes, et de ce qu'ils ne savent pas!"},{"n":3742,"s":36,"a":37,"t":"Et une preuve pour eux est la nuit. Nous en écorchons le jour et ils sont alors dans les ténèbres."},{"n":3743,"s":36,"a":38,"t":"et le soleil court vers un gîte qui lui est assigné; telle est la détermination du Tout Puissant, de l'Omniscient."},{"n":3744,"s":36,"a":39,"t":"Et la lune, Nous lui avons déterminé des phases jusqu'à ce qu'elle devienne comme la palme vieillie."},{"n":3745,"s":36,"a":40,"t":"Le soleil ne peut rattraper la lune, ni la nuit devancer le jour; et chacun vogue dans une orbite."},{"n":3746,"s":36,"a":41,"t":"Et un (autre) signe pour eux est que Nous avons transporté leur descendance sur le bateau chargé;"},{"n":3747,"s":36,"a":42,"t":"et Nous leur créâmes des semblables sur lesquels ils montent."},{"n":3748,"s":36,"a":43,"t":"Et si Nous le voulons, Nous les noyons; pour eux alors, pas de secoureur et ils ne seront pas sauvés,"},{"n":3749,"s":36,"a":44,"t":"sauf par une miséricorde de Notre part, et à titre de jouissance pour un temps."},{"n":3750,"s":36,"a":45,"t":"Et quand on leur dit: «Craignez ce qu'il y a devant vous et ce qu'il y a derrière vous afin que vous ayez la miséricorde»!..."},{"n":3751,"s":36,"a":46,"t":"Or, pas une preuve ne leur vient, parmi les preuves de leur Seigneur sans qu'ils ne s'en détournent."},{"n":3752,"s":36,"a":47,"t":"Et quand on leur dit: «Dépensez de ce qu'Allah vous a attribué», ceux qui ont mécru disent à ceux qui ont cru: «Nourrirons-nous quelqu'un qu'Allah aurait nourri s'Il l'avait voulu? Vous n'êtes que dans un égarement évident»."},{"n":3753,"s":36,"a":48,"t":"Et ils disent: «A quand cette promesse si vous êtes véridiques?»"},{"n":3754,"s":36,"a":49,"t":"Ils n'attendent qu'un seul Cri qui les saisira alors qu'ils seront en train de disputer."},{"n":3755,"s":36,"a":50,"t":"Ils ne pourront donc ni faire de testament, ni retourner chez leurs familles."},{"n":3756,"s":36,"a":51,"t":"Et on soufflera dans la Trompe, et voilà que, des tombes, ils se précipiteront vers leur Seigneur,"},{"n":3757,"s":36,"a":52,"t":"en disant: «Malheur à nous! Qui nous a ressuscités de là où nous dormions?» C'est ce que le Tout Miséricordieux avait promis; et les Messagers avaient dit vrai."},{"n":3758,"s":36,"a":53,"t":"Ce ne sera qu'un seul Cri, et voilà qu'ils seront tous amenés devant Nous."},{"n":3759,"s":36,"a":54,"t":"Ce jour-là, aucune âme ne sera lésée en rien. Et vous ne serez rétribués que selon ce que vous faisiez."},{"n":3760,"s":36,"a":55,"t":"Les gens du Paradis seront, ce jour-là, dans une occupation qui les remplit de bonheur;"},{"n":3761,"s":36,"a":56,"t":"eux et leurs épouses sont sous des ombrages, accoudés sur les divans."},{"n":3762,"s":36,"a":57,"t":"Là ils auront des fruits et ils auront ce qu'ils réclameront,"},{"n":3763,"s":36,"a":58,"t":"«Salâm» [paix et salut]! Parole de la part d'un Seigneur Très Miséricordieux."},{"n":3764,"s":36,"a":59,"t":"«O injustes! Tenez-vous à l'écart ce jour-là!"},{"n":3765,"s":36,"a":60,"t":"Ne vous ai-Je pas engagés, enfants d'Adam, à ne pas adorer le Diable? Car il est vraiment pour vous un ennemi déclaré,"},{"n":3766,"s":36,"a":61,"t":"et [ne vous ai-Je pas engagés] à M'adorer? Voilà un chemin bien droit."},{"n":3767,"s":36,"a":62,"t":"Et il a très certainement égaré un grand nombre d'entre vous. Ne raisonniez-vous donc pas?"},{"n":3768,"s":36,"a":63,"t":"Voici l'Enfer qu'on vous promettait."},{"n":3769,"s":36,"a":64,"t":"Brûlez-y aujourd'hui, pour avoir mécru»."},{"n":3770,"s":36,"a":65,"t":"Ce jour-là, Nous scellerons leurs bouches, tandis que leurs mains Nous parleront et que leurs jambes témoigneront de ce qu'ils avaient accompli."},{"n":3771,"s":36,"a":66,"t":"Et si Nous voulions, Nous effacerions leurs yeux et ils courront vers le chemin. Mais comment alors pourront-ils voir?"},{"n":3772,"s":36,"a":67,"t":"Et si Nous voulions, Nous les métamorphoserions sur place; alors ils ne sauront ni avancer ni revenir."},{"n":3773,"s":36,"a":68,"t":"A quiconque Nous accordons une longue vie, Nous faisons baisser sa forme. Ne comprendront-ils donc pas?"},{"n":3774,"s":36,"a":69,"t":"Nous ne lui (à Muhammad) avons pas enseigné la poésie; cela ne lui convient pas non plus. Ceci n'est qu'un rappel et une Lecture [Coran] claire,"},{"n":3775,"s":36,"a":70,"t":"pour qu'il avertisse celui qui est vivant et que la Parole se réalise contre les mécréants."},{"n":3776,"s":36,"a":71,"t":"Ne voient-ils donc pas que, parmi ce que Nos mains ont fait, Nous leur avons créé des bestiaux dont ils sont propriétaires;"},{"n":3777,"s":36,"a":72,"t":"et Nous les leur avons soumis: certains leur servent de monture et d'autres de nourriture;"},{"n":3778,"s":36,"a":73,"t":"et ils en retirent d'autres utilités et des boissons. Ne seront-ils donc pas reconnaissants?"},{"n":3779,"s":36,"a":74,"t":"Et ils adoptèrent des divinités en dehors d'Allah, dans l'espoir d'être secourus..."},{"n":3780,"s":36,"a":75,"t":"Celles-ci ne pourront pas les secourir, elles formeront au contraire une armée dressée contre eux."},{"n":3781,"s":36,"a":76,"t":"Que leurs paroles ne t'affligent donc pas! Nous savons ce qu'ils cachent et ce qu'ils divulguent."},{"n":3782,"s":36,"a":77,"t":"L'homme ne voit-il pas que Nous l'avons créé d'une goutte de sperme? Et le voilà [devenu] un adversaire déclaré!"},{"n":3783,"s":36,"a":78,"t":"Il cite pour Nous un exemple, tandis qu'il oublie sa propre création; il dit: «Qui va redonner la vie à des ossements une fois réduits en poussière?»"},{"n":3784,"s":36,"a":79,"t":"Dis: «Celui qui les a créés une première fois, leur redonnera la vie. Il Se connaît parfaitement à toute création."},{"n":3785,"s":36,"a":80,"t":"c'est Lui qui, de l'arbre vert, a fait pour vous du feu, et voilà que de cela vous allumez."},{"n":3786,"s":36,"a":81,"t":"Celui qui a créé les cieux et la terre ne sera-t-Il pas capable de créer leur pareil? Oh que si! et Il est le grand Créateur, l'Omniscient."},{"n":3787,"s":36,"a":82,"t":"Quand Il veut une chose, Son commandement consiste à dire: «Sois», et c'est."},{"n":3788,"s":36,"a":83,"t":"Louange donc, à Celui qui détient en Sa main la royauté sur toute chose! Et c'est vers Lui que vous serez ramenés."},{"n":3789,"s":37,"a":1,"t":"Par ceux qui sont rangés en rangs."},{"n":3790,"s":37,"a":2,"t":"Par ceux qui poussent (les nuages) avec force."},{"n":3791,"s":37,"a":3,"t":"Par ceux qui récitent, en rappel:"},{"n":3792,"s":37,"a":4,"t":"«Votre Dieu est en vérité unique,"},{"n":3793,"s":37,"a":5,"t":"le Seigneur des cieux et de la terre et de ce qui existe entre eux et Seigneur des Levants»"},{"n":3794,"s":37,"a":6,"t":"Nous avons décoré le ciel le plus proche d'un décor: les étoiles,"},{"n":3795,"s":37,"a":7,"t":"afin de le protéger contre tout diable rebelle."},{"n":3796,"s":37,"a":8,"t":"Ils ne pourront être à l'écoute des dignitaires suprêmes [les Anges]; car ils seront harcelés de tout côté,"},{"n":3797,"s":37,"a":9,"t":"et refoulés. Et ils auront un châtiment perpétuel."},{"n":3798,"s":37,"a":10,"t":"Sauf celui qui saisit au vol quelque [information]; il est alors pourchassé par un météore transperçant."},{"n":3799,"s":37,"a":11,"t":"Demande-leur s'ils sont plus difficiles à créer que ceux que Nous avons créés? Car Nous les avons créés de boue collante!"},{"n":3800,"s":37,"a":12,"t":"Mais tu t'étonnes, et ils se moquent!"},{"n":3801,"s":37,"a":13,"t":"Et quand on le leur rappelle (le Coran), ils ne se rappellent pas;"},{"n":3802,"s":37,"a":14,"t":"et quand ils voient un prodige, ils cherchent à s'en moquer,"},{"n":3803,"s":37,"a":15,"t":"et disent: «Ceci n'est que magie évidente."},{"n":3804,"s":37,"a":16,"t":"Lorsque nous serons morts et que nous deviendrons poussière et ossements, serons-nous ressuscités?"},{"n":3805,"s":37,"a":17,"t":"ainsi que nos premiers ancêtres?»"},{"n":3806,"s":37,"a":18,"t":"Dis: «Oui! et vous vous humilierez»."},{"n":3807,"s":37,"a":19,"t":"Il n'y aura qu'un seul Cri, et voilà qu'ils regarderont,"},{"n":3808,"s":37,"a":20,"t":"et ils diront: «Malheur à nous! c'est le jour de la Rétribution»."},{"n":3809,"s":37,"a":21,"t":"«C'est le jour du Jugement que vous traitiez de mensonge»."},{"n":3810,"s":37,"a":22,"t":"«Rassemblez les injustes et leurs épouses et tout ce qu'ils adoraient,"},{"n":3811,"s":37,"a":23,"t":"en dehors d'Allah. Puis conduisez-les au chemin de la Fournaise."},{"n":3812,"s":37,"a":24,"t":"Et arrêtez-les: car ils doivent être interrogés»."},{"n":3813,"s":37,"a":25,"t":"«Pourquoi ne vous portez-vous pas secours mutuellement?»"},{"n":3814,"s":37,"a":26,"t":"Mais ce jour-là, ils seront complètement soumis,"},{"n":3815,"s":37,"a":27,"t":"et les uns se tourneront vers les autres s'interrogeant mutuellement;"},{"n":3816,"s":37,"a":28,"t":"Ils diront: «C'est vous qui nous forciez (à la mécréance)»."},{"n":3817,"s":37,"a":29,"t":"«C'est vous plutôt (diront les chefs) qui ne vouliez pas croire."},{"n":3818,"s":37,"a":30,"t":"Et nous n'avions aucun pouvoir sur vous. C'est vous plutôt qui étiez des gens transgresseurs."},{"n":3819,"s":37,"a":31,"t":"La parole de notre Seigneur s'est donc réalisée contre nous; certes, nous allons goûter [au châtiment]."},{"n":3820,"s":37,"a":32,"t":"Nous vous avons induits en erreur car, en vérité, nous étions égarés nous-mêmes»."},{"n":3821,"s":37,"a":33,"t":"Ce jour-là donc, ils seront tous associés dans le châtiment."},{"n":3822,"s":37,"a":34,"t":"Ainsi traitons-Nous les criminels."},{"n":3823,"s":37,"a":35,"t":"Quand on leur disait: «Point de divinité à part Allah», ils se gonflaient d'orgueil,"},{"n":3824,"s":37,"a":36,"t":"et disaient: «Allons-nous abandonner nos divinités pour un poète fou?»"},{"n":3825,"s":37,"a":37,"t":"Il est plutôt venu avec la Vérité et il a confirmé les messagers (précédents)."},{"n":3826,"s":37,"a":38,"t":"Vous allez certes, goûter au châtiment douloureux."},{"n":3827,"s":37,"a":39,"t":"Et vous ne serez rétribués que selon ce que vous œuvriez,"},{"n":3828,"s":37,"a":40,"t":"sauf les serviteurs élus d'Allah,"},{"n":3829,"s":37,"a":41,"t":"Ceux-là auront une rétribution bien connue:"},{"n":3830,"s":37,"a":42,"t":"des fruits, et ils seront honorés,"},{"n":3831,"s":37,"a":43,"t":"dans les Jardins du délice,"},{"n":3832,"s":37,"a":44,"t":"sur des lits, face à face."},{"n":3833,"s":37,"a":45,"t":"On fera circuler entre eux une coupe d'eau remplie à une source"},{"n":3834,"s":37,"a":46,"t":"blanche, savoureuse à boire,"},{"n":3835,"s":37,"a":47,"t":"Elle n'offusquera point leur raison et ne les enivrera pas."},{"n":3836,"s":37,"a":48,"t":"Et Ils auront auprès d'eux des belles aux grands yeux, au regard chaste,"},{"n":3837,"s":37,"a":49,"t":"semblables au blanc bien préservé de l'œuf."},{"n":3838,"s":37,"a":50,"t":"Puis les uns se tourneront vers les autres s'interrogeant mutuellement."},{"n":3839,"s":37,"a":51,"t":"L'un d'eux dira: «J'avais un compagnon"},{"n":3840,"s":37,"a":52,"t":"qui disait: «Es-tu vraiment de ceux qui croient?"},{"n":3841,"s":37,"a":53,"t":"Est-ce que quand nous mourrons et serons poussière et ossements, nous aurons à rendre des comptes?»"},{"n":3842,"s":37,"a":54,"t":"Il dira: «Est-ce que vous voudriez regarder d'en haut?»"},{"n":3843,"s":37,"a":55,"t":"Alors il regardera d'en haut et il le verra en plein dans la Fournaise,"},{"n":3844,"s":37,"a":56,"t":"et dira: «Par Allah! Tu as bien failli causer ma perte!"},{"n":3845,"s":37,"a":57,"t":"et sans le bienfait de mon Seigneur, j'aurais certainement été du nombre de ceux qu'on traîne [au supplice]."},{"n":3846,"s":37,"a":58,"t":"N'est-il pas vrai que nous ne mourrons"},{"n":3847,"s":37,"a":59,"t":"que de notre première mort et que nous ne serons pas châtiés?»"},{"n":3848,"s":37,"a":60,"t":"C'est cela, certes, le grand succès."},{"n":3849,"s":37,"a":61,"t":"C'est pour une chose pareille que doivent ouvrer ceux qui ouvrent."},{"n":3850,"s":37,"a":62,"t":"Est-ce que ceci est meilleur comme séjour, ou l'arbre de Zaqqûm?"},{"n":3851,"s":37,"a":63,"t":"Nous l'avons assigné en épreuve aux injustes."},{"n":3852,"s":37,"a":64,"t":"C'est un arbre qui sort du fond de la Fournaise."},{"n":3853,"s":37,"a":65,"t":"Ses fruits sont comme des têtes de diables."},{"n":3854,"s":37,"a":66,"t":"Ils doivent certainement en manger et ils doivent s'en remplir le ventre."},{"n":3855,"s":37,"a":67,"t":"Ensuite ils auront par-dessus une mixture d'eau bouillante."},{"n":3856,"s":37,"a":68,"t":"Puis leur retour sera vers la Fournaise."},{"n":3857,"s":37,"a":69,"t":"C'est qu'ils ont trouvé leurs ancêtres dans l'égarement,"},{"n":3858,"s":37,"a":70,"t":"et les voilà courant sur leurs traces."},{"n":3859,"s":37,"a":71,"t":"En effet, avant eux, la plupart des anciens se sont égarés."},{"n":3860,"s":37,"a":72,"t":"Et Nous avions certes envoyé parmi eux des avertisseurs."},{"n":3861,"s":37,"a":73,"t":"Regarde donc ce qu'il est advenu de ceux qui ont été avertis!"},{"n":3862,"s":37,"a":74,"t":"Exception faite des élus, parmi les serviteurs d'Allah:"},{"n":3863,"s":37,"a":75,"t":"Noé, en effet, fit appel à Nous qui sommes le Meilleur Répondeur (qui exauce les prières)."},{"n":3864,"s":37,"a":76,"t":"Et Nous le sauvâmes, lui et sa famille, de la grande angoisse,"},{"n":3865,"s":37,"a":77,"t":"et Nous fîmes de sa descendance les seuls survivants."},{"n":3866,"s":37,"a":78,"t":"et Nous avons perpétué son souvenir dans la postérité,"},{"n":3867,"s":37,"a":79,"t":"Paix sur Noé dans tout l'univers!"},{"n":3868,"s":37,"a":80,"t":"Ainsi récompensons-Nous les bienfaisants."},{"n":3869,"s":37,"a":81,"t":"Il était, certes, un de Nos serviteurs croyants."},{"n":3870,"s":37,"a":82,"t":"Ensuite Nous noyâmes les autres."},{"n":3871,"s":37,"a":83,"t":"Du nombre de ses coreligionnaires, certes, fut Abraham."},{"n":3872,"s":37,"a":84,"t":"Quand il vint à son Seigneur avec un cœur sain."},{"n":3873,"s":37,"a":85,"t":"Quand il dit à son père et à son peuple: «Qu'est-ce que vous adorez?»"},{"n":3874,"s":37,"a":86,"t":"Cherchez-vous dans votre égarement, des divinités en dehors d'Allah?"},{"n":3875,"s":37,"a":87,"t":"Que pensez-vous du Seigneur de l'univers?»"},{"n":3876,"s":37,"a":88,"t":"Puis, il jeta un regard attentif sur les étoiles,"},{"n":3877,"s":37,"a":89,"t":"et dit: «Je suis malade»."},{"n":3878,"s":37,"a":90,"t":"Ils lui tournèrent le dos et s'en allèrent."},{"n":3879,"s":37,"a":91,"t":"Alors il se glissa vers leurs divinités et dit: «Ne mangez-vous pas?"},{"n":3880,"s":37,"a":92,"t":"Qu'avez-vous à ne pas parler?»"},{"n":3881,"s":37,"a":93,"t":"Puis il se mit furtivement à les frapper de sa main droite."},{"n":3882,"s":37,"a":94,"t":"Alors [les gens] vinrent à lui en courant."},{"n":3883,"s":37,"a":95,"t":"Il [leur] dit: «Adorez-vous ce que vous-mêmes sculptez,"},{"n":3884,"s":37,"a":96,"t":"alors que c'est Allah qui vous a créés, vous et ce que vous fabriquez?»"},{"n":3885,"s":37,"a":97,"t":"Ils dirent: «Qu'on lui construise un four et qu'on le lance dans la fournaise!»"},{"n":3886,"s":37,"a":98,"t":"Ils voulurent lui jouer un mauvais tour; mais ce sont eux que Nous mîmes à bas."},{"n":3887,"s":37,"a":99,"t":"Et il dit: «Moi, je pars vers mon Seigneur et Il me guidera."},{"n":3888,"s":37,"a":100,"t":"Seigneur, fais-moi don d'une [progéniture] d'entre les vertueux»."},{"n":3889,"s":37,"a":101,"t":"Nous lui fîmes donc la bonne annonce d'un garçon (Ismaël) longanime."},{"n":3890,"s":37,"a":102,"t":"Puis quand celui-ci fut en âge de l'accompagner, [Abraham] dit: «O mon fils, je me vois en songe en train de t'immoler. Vois donc ce que tu en penses». (Ismaël) dit: «O mon cher père, fais ce qui t'es commandé: tu me trouveras, s'il plaît à Allah, du nombre des endurants»."},{"n":3891,"s":37,"a":103,"t":"Puis quand tous deux se furent soumis (à l'ordre d'Allah) et qu'il l'eut jeté sur le front,"},{"n":3892,"s":37,"a":104,"t":"voilà que Nous l'appelâmes «Abraham!"},{"n":3893,"s":37,"a":105,"t":"Tu as confirmé la vision. C'est ainsi que Nous récompensons les bienfaisants»."},{"n":3894,"s":37,"a":106,"t":"C'était là certes, l'épreuve manifeste."},{"n":3895,"s":37,"a":107,"t":"Et Nous le rançonnâmes d'une immolation généreuse."},{"n":3896,"s":37,"a":108,"t":"Et Nous perpétuâmes son renom dans la postérité:"},{"n":3897,"s":37,"a":109,"t":"«Paix sur Abraham»."},{"n":3898,"s":37,"a":110,"t":"Ainsi récompensons-Nous les bienfaisants;"},{"n":3899,"s":37,"a":111,"t":"car il était de Nos serviteurs croyants."},{"n":3900,"s":37,"a":112,"t":"Nous lui fîmes la bonne annonce d'Isaac comme prophète d'entre les gens vertueux."},{"n":3901,"s":37,"a":113,"t":"Et Nous le bénîmes ainsi que Isaac. Parmi leurs descendances il y a [l'homme] de bien et celui qui est manifestement injuste envers lui-même."},{"n":3902,"s":37,"a":114,"t":"Et Nous accordâmes certes à Moïse et Aaron des faveurs,"},{"n":3903,"s":37,"a":115,"t":"Et les sauvâmes ainsi que leur peuple, de la grande angoisse,"},{"n":3904,"s":37,"a":116,"t":"et les secourûmes, et ils furent eux les vainqueurs."},{"n":3905,"s":37,"a":117,"t":"Et Nous leur apportâmes le livre explicite"},{"n":3906,"s":37,"a":118,"t":"et les guidâmes vers le droit chemin."},{"n":3907,"s":37,"a":119,"t":"Et Nous perpétuâmes leur renom dans la postérité:"},{"n":3908,"s":37,"a":120,"t":"«Paix sur Moïse et Aaron»"},{"n":3909,"s":37,"a":121,"t":"Ainsi récompensons-Nous les bienfaisants;"},{"n":3910,"s":37,"a":122,"t":"car ils étaient du nombre de Nos serviteurs croyants."},{"n":3911,"s":37,"a":123,"t":"Elie était, certes, du nombre des Messagers."},{"n":3912,"s":37,"a":124,"t":"Quand il dit à son peuple: «Ne craignez-vous pas [Allah]?»"},{"n":3913,"s":37,"a":125,"t":"Invoquerez-vous Ball (une idole) et délaisserez-vous le Meilleur des créateurs,"},{"n":3914,"s":37,"a":126,"t":"Allah, votre Seigneur et le Seigneur de vos plus anciens ancêtres?»"},{"n":3915,"s":37,"a":127,"t":"Ils le traitèrent de menteur. Et bien, ils seront emmenées (au châtiment)."},{"n":3916,"s":37,"a":128,"t":"Exception faite des serviteurs élus d'Allah."},{"n":3917,"s":37,"a":129,"t":"Et Nous perpétuâmes son renom dans la postérité:"},{"n":3918,"s":37,"a":130,"t":"«Paix sur Elie et ses adeptes»."},{"n":3919,"s":37,"a":131,"t":"Ainsi récompensons-Nous les bienfaisants,"},{"n":3920,"s":37,"a":132,"t":"car il était du nombre de Nos serviteurs croyants."},{"n":3921,"s":37,"a":133,"t":"Et Loût était, certes, du nombre des Messagers."},{"n":3922,"s":37,"a":134,"t":"Quand Nous le sauvâmes, lui et sa famille, tout entière,"},{"n":3923,"s":37,"a":135,"t":"sauf une vieille femme qui devait disparaître avec les autres,"},{"n":3924,"s":37,"a":136,"t":"Et Nous détruisîmes les autres"},{"n":3925,"s":37,"a":137,"t":"Et vous passez certainement auprès d'eux le matin"},{"n":3926,"s":37,"a":138,"t":"et la nuit. Ne raisonnez-vous donc pas?"},{"n":3927,"s":37,"a":139,"t":"Jonas était certes, du nombre des Messagers."},{"n":3928,"s":37,"a":140,"t":"Quand il s'enfuit vers le bateau comble,"},{"n":3929,"s":37,"a":141,"t":"Il prit part au tirage au sort qui le désigna pour être jeté [à la mer]."},{"n":3930,"s":37,"a":142,"t":"Le poisson l'avala alors qu'il était blâmable."},{"n":3931,"s":37,"a":143,"t":"S'il n'avait pas été parmi ceux qui glorifient Allah,"},{"n":3932,"s":37,"a":144,"t":"il serait demeuré dans son ventre jusqu'au jour où l'on sera ressuscité."},{"n":3933,"s":37,"a":145,"t":"Nous le jetâmes sur la terre nue, indisposé qu'il était."},{"n":3934,"s":37,"a":146,"t":"Et Nous fîmes pousser au-dessus de lui un plant de courge,"},{"n":3935,"s":37,"a":147,"t":"et l'envoyâmes ensuite (comme prophète) vers cent mille hommes ou plus."},{"n":3936,"s":37,"a":148,"t":"Ils crurent, et nous leur donnâmes jouissance de la vie pour un temps."},{"n":3937,"s":37,"a":149,"t":"Pose-leur donc la question: «Ton Seigneur aurait-Il des filles et eux des fils?"},{"n":3938,"s":37,"a":150,"t":"Ou bien avons-Nous créé des Anges de sexe féminin, et en sont-ils témoins?»."},{"n":3939,"s":37,"a":151,"t":"Certes, ils disent dans leur mensonge:"},{"n":3940,"s":37,"a":152,"t":"«Allah a engendré» mais ce sont certainement des menteurs!"},{"n":3941,"s":37,"a":153,"t":"Aurait-Il choisi des filles de préférence à des fils?"},{"n":3942,"s":37,"a":154,"t":"Qu'avez-vous donc à juger ainsi?"},{"n":3943,"s":37,"a":155,"t":"Ne réfléchissez-vous donc pas?"},{"n":3944,"s":37,"a":156,"t":"Ou avez-vous un argument évident?"},{"n":3945,"s":37,"a":157,"t":"Apportez donc votre Livre si vous êtes véridiques!»"},{"n":3946,"s":37,"a":158,"t":"Et ils ont établi entre Lui et les djinns une parenté, alors que les djinns savent bien qu'ils [les mécréants] vont être emmenés (pour le châtiment)."},{"n":3947,"s":37,"a":159,"t":"Gloire à Allah. Il est au-dessus de ce qu'ils décrivent!"},{"n":3948,"s":37,"a":160,"t":"Exception faite des serviteurs élus d'Allah."},{"n":3949,"s":37,"a":161,"t":"En vérité, vous et tout ce que vous adorez,"},{"n":3950,"s":37,"a":162,"t":"ne pourrez tenter [personne],"},{"n":3951,"s":37,"a":163,"t":"excepté celui qui sera brûlé dans la Fournaise."},{"n":3952,"s":37,"a":164,"t":"Il n'y en a pas un, parmi nous, qui n'ait une place connue;"},{"n":3953,"s":37,"a":165,"t":"nous sommes certes, les rangés en rangs;"},{"n":3954,"s":37,"a":166,"t":"et c'est nous certes, qui célébrons la gloire [d'Allah]."},{"n":3955,"s":37,"a":167,"t":"Même s'ils disaient:"},{"n":3956,"s":37,"a":168,"t":"«Si nous avions eu un Rappel de [nos] ancêtres,"},{"n":3957,"s":37,"a":169,"t":"nous aurions été certes les serviteurs élus d'Allah!"},{"n":3958,"s":37,"a":170,"t":"Ils y ont mécru et ils sauront bientôt."},{"n":3959,"s":37,"a":171,"t":"En effet, Notre Parole a déjà été donnée à Nos serviteurs, les Messagers,"},{"n":3960,"s":37,"a":172,"t":"que ce sont eux qui seront secourus,"},{"n":3961,"s":37,"a":173,"t":"et que Nos soldats auront le dessus."},{"n":3962,"s":37,"a":174,"t":"Eloigne-toi d'eux, jusqu'à un certain temps;"},{"n":3963,"s":37,"a":175,"t":"et observe-les: ils verront bientôt!"},{"n":3964,"s":37,"a":176,"t":"Quoi! est-ce Notre châtiment qu'ils cherchent à hâter?"},{"n":3965,"s":37,"a":177,"t":"Quand il tombera dans leur place, ce sera alors un mauvais matin pour ceux qu'on a avertis!"},{"n":3966,"s":37,"a":178,"t":"Et éloigne-toi d'eux jusqu'à un certain temps;"},{"n":3967,"s":37,"a":179,"t":"et observe; ils verront bientôt!"},{"n":3968,"s":37,"a":180,"t":"Gloire à ton Seigneur, le Seigneur de la puissance. Il est au-dessus de ce qu'ils décrivent!"},{"n":3969,"s":37,"a":181,"t":"Et paix sur les Messagers,"},{"n":3970,"s":37,"a":182,"t":"et louange à Allah, Seigneur de l'univers!"},{"n":3971,"s":38,"a":1,"t":"Sâd. Par le Coran, au renom glorieux (dikr)!"},{"n":3972,"s":38,"a":2,"t":"Ceux qui ont mécru sont plutôt dans l'orgueil et le schisme!"},{"n":3973,"s":38,"a":3,"t":"Que de générations avant eux avons-Nous fait périr, qui ont crié, hélas, quand il n'était plus temps d'échapper?"},{"n":3974,"s":38,"a":4,"t":"Et ils (les Mecquois) s'étonnèrent qu'un avertisseur parmi eux leur soit venu, et les infidèles disent: «C'est un magicien et un grand menteur,"},{"n":3975,"s":38,"a":5,"t":"Réduira-t-il les divinités à un Seul Dieu? Voilà une chose vraiment étonnante»."},{"n":3976,"s":38,"a":6,"t":"Et leurs notables partirent en disant: «Allez-vous en, et restez constants à vos dieux: c'est là vraiment une chose souhaitable."},{"n":3977,"s":38,"a":7,"t":"Nous n'avons pas entendu cela dans la dernière religion (le Christianisme); ce n'est en vérité que pure invention!"},{"n":3978,"s":38,"a":8,"t":"Quoi! C'est sur lui, parmi nous, qu'on aurait fait descendre le Rappel [le Coran]?» Plutôt ils sont dans le doute au sujet de Mon message. Ou plutôt ils n'ont pas encore goûté à Mon châtiment!"},{"n":3979,"s":38,"a":9,"t":"Ou bien détiennent-ils les trésors de la miséricorde de ton Seigneur, le Puissant, le Dispensateur par excellence."},{"n":3980,"s":38,"a":10,"t":"Ou bien ont-ils le royaume des cieux et de la terre et de ce qui existe entre eux? Eh bien, qu'ils y montent par n'importe quel moyen!"},{"n":3981,"s":38,"a":11,"t":"Une armée de coalisés qui, ici-même, sera mise en déroute!"},{"n":3982,"s":38,"a":12,"t":"Avant eux, le peuple de Noé, les Aad et Pharaon l'homme aux pals (ou aux Pyramides),"},{"n":3983,"s":38,"a":13,"t":"et les Tamûd, le peuple de Lot, et les gens d'Al-Aykah, (ont tous démenti leurs Messagers). Voilà les coalisés."},{"n":3984,"s":38,"a":14,"t":"Il n'en est aucun qui n'ait traité les Messagers de menteurs. Et bien, Ma punition s'est avérée contre eux!"},{"n":3985,"s":38,"a":15,"t":"Ceux-ci n'attendant qu'un seul Cri, sans répétition."},{"n":3986,"s":38,"a":16,"t":"Et ils disent: «Seigneur, hâte-nous notre part avant le jour des Comptes»."},{"n":3987,"s":38,"a":17,"t":"Endure ce qu'ils disent; et rappelle-toi David, Notre serviteur, doué de force [dans l'adoration] et plein de repentir [à Allah]."},{"n":3988,"s":38,"a":18,"t":"Nous soumîmes les montagnes à glorifier Allah, soir et matin, en sa compagnie,"},{"n":3989,"s":38,"a":19,"t":"de même que les oiseaux assemblés en masse, tous ne faisant qu'obéir à lui [Allah]."},{"n":3990,"s":38,"a":20,"t":"Et Nous renforçâmes son royaume et lui donnâmes la sagesse et la faculté de bien juger."},{"n":3991,"s":38,"a":21,"t":"Et t'est-elle parvenue la nouvelle des disputeurs quand ils grimpèrent au mur du sanctuaire!"},{"n":3992,"s":38,"a":22,"t":"Quand ils entrèrent auprès de David, il en fut effrayé. Ils dirent: «N'aie pas peur! Nous sommes tous deux en dispute; l'un de nous a fait du tort à l'autre. Juge donc en toute équité entre nous, ne sois pas injuste et guide-nous vers le chemin droit."},{"n":3993,"s":38,"a":23,"t":"Celui-ci est mon frère: il a quatre-vingt-dix-neuf brebis, tandis que je n'ai qu'une brebis. Il m'a dit: «Confie-la-moi» et dans la conversation, il a beaucoup fait pression sur moi»."},{"n":3994,"s":38,"a":24,"t":"Il [David] dit: «Il a été certes injuste envers toi en demandant de joindre ta brebis à ses brebis». Beaucoup de gens transgressent les droits de leurs associés, sauf ceux qui croient et accomplissent les bonnes œuvres - cependant ils sont bien rares -. Et David pensa alors que Nous l'avions mis à l'épreuve. Il demanda donc pardon à son Seigneur et tomba prosterné et se repentit."},{"n":3995,"s":38,"a":25,"t":"Nous lui pardonnâmes. Il aura une place proche de Nous et un beau refuge."},{"n":3996,"s":38,"a":26,"t":"«O David, Nous avons fait de toi un calife sur la terre. Juge donc en toute équité parmi les gens et ne suis pas la passion: sinon elle t'égarera du sentier d'Allah». Car ceux qui s'égarent du sentier d'Allah auront un dur châtiment pour avoir oublié le Jour des Comptes."},{"n":3997,"s":38,"a":27,"t":"Nous n'avons pas créé le ciel et la terre et ce qui existe entre eux en vain. C'est ce que pensent ceux qui ont mécru. Malheur à ceux qui ont mécru pour le feu [qui les attend]!"},{"n":3998,"s":38,"a":28,"t":"Traiterons-Nous ceux qui croient et accomplissent les bonnes œuvres comme ceux qui commettent du désordre sur terre? ou traiterons-Nous les pieux comme les pervers?"},{"n":3999,"s":38,"a":29,"t":"[Voici] un Livre béni que Nous avons fait descendre vers toi, afin qu'ils méditent sur ses versets et que les doués d'intelligence réfléchissent!"},{"n":4000,"s":38,"a":30,"t":"Et à David Nous fîmes don de Salomon, - quel bon serviteur! - Il était plein de repentir."},{"n":4001,"s":38,"a":31,"t":"Quand un après-midi, on lui présenta de magnifiques chevaux de course,"},{"n":4002,"s":38,"a":32,"t":"il dit: «Oui, je me suis complu à aimer les biens (de ce monde) au point [d'oublier] le rappel de mon Seigneur jusqu'à ce que [le soleil] se soit caché derrière son voile."},{"n":4003,"s":38,"a":33,"t":"Ramenez-les moi.» Alors il se mit à leur couper les pattes et les cous."},{"n":4004,"s":38,"a":34,"t":"Et Nous avions certes éprouvé Salomon en plaçant sur son siège un corps. Ensuite, il se repentit."},{"n":4005,"s":38,"a":35,"t":"Il dit: «Seigneur, pardonne-moi et fais-moi don d'un royaume tel que nul après moi n'aura de pareil. C'est Toi le grand Dispensateur»."},{"n":4006,"s":38,"a":36,"t":"Nous lui assujettîmes alors le vent qui, par son ordre, soufflait modérément partout où il voulait."},{"n":4007,"s":38,"a":37,"t":"De même que les diables, bâtisseurs et plongeurs de toutes sortes."},{"n":4008,"s":38,"a":38,"t":"Et d'autres encore, accouplés dans des chaînes."},{"n":4009,"s":38,"a":39,"t":"«Voilà Notre don; distribue-le ou retiens-le sans avoir à en rendre compte»."},{"n":4010,"s":38,"a":40,"t":"Et il a une place rapprochée de Nous et un beau refuge."},{"n":4011,"s":38,"a":41,"t":"Et rappelle-toi Job, Notre serviteur, lorsqu'il appela son Seigneur: «Le Diable m'a infligé détresse et souffrance»."},{"n":4012,"s":38,"a":42,"t":"Frappe [la terre] de ton pied: voici une eau fraîche pour te laver et voici de quoi boire."},{"n":4013,"s":38,"a":43,"t":"Et Nous lui rendîmes sa famille et la fîmes deux fois plus nombreuse, comme une miséricorde de Notre part et comme un rappel pour les gens doués d'intelligence."},{"n":4014,"s":38,"a":44,"t":"«Et prends dans ta main un faisceau de brindilles, puis frappe avec cela. Et ne viole pas ton serment». Oui, Nous l'avons trouvé vraiment endurant. Quel bon serviteur! Sans cesse il se repentait."},{"n":4015,"s":38,"a":45,"t":"Et rappelle-toi Abraham, Isaac et Jacob, Nos serviteurs puissants et clairvoyants."},{"n":4016,"s":38,"a":46,"t":"Nous avons fait d'eux l'objet d'une distinction particulière: le rappel de l'au-delà."},{"n":4017,"s":38,"a":47,"t":"Ils sont auprès de Nous, certes, parmi les meilleurs élus."},{"n":4018,"s":38,"a":48,"t":"Et rappelle-toi Ismaël et Elisée, et Dal Kifl, chacun d'eux parmi les meilleurs."},{"n":4019,"s":38,"a":49,"t":"Cela est un rappel. C'est aux pieux qu'appartient, en vérité, la meilleure retraite,"},{"n":4020,"s":38,"a":50,"t":"Les Jardins d'Eden, aux portes ouvertes pour eux,"},{"n":4021,"s":38,"a":51,"t":"où, accoudés, ils demanderont des fruits abondants et des boissons."},{"n":4022,"s":38,"a":52,"t":"Et auprès d'eux seront les belles au regard chaste, toutes du même âge."},{"n":4023,"s":38,"a":53,"t":"Voilà ce qui vous est promis pour le Jour des Comptes."},{"n":4024,"s":38,"a":54,"t":"Ce sera Notre attribution inépuisable."},{"n":4025,"s":38,"a":55,"t":"Voilà! Alors que les rebelles auront certes la pire retraite,"},{"n":4026,"s":38,"a":56,"t":"L'Enfer où ils brûleront. Et quel affreux lit!"},{"n":4027,"s":38,"a":57,"t":"Voilà! Qu'ils y goûtent: eau bouillante et eau purulente,"},{"n":4028,"s":38,"a":58,"t":"et d'autres punitions du même genre."},{"n":4029,"s":38,"a":59,"t":"Voici un groupe qui entre précipitamment en même temps que vous, nulle bienvenue à eux. Ils vont brûler dans le Feu."},{"n":4030,"s":38,"a":60,"t":"Ils dirent: «Pas de bienvenue pour vous, plutôt. C'est vous qui avez préparé cela pour nous». Quel mauvais lieu de séjour!"},{"n":4031,"s":38,"a":61,"t":"Ils dirent: «Seigneur, celui qui nous a préparé cela, ajoute-lui un double châtiment dans le Feu»."},{"n":4032,"s":38,"a":62,"t":"Et ils dirent: «Pourquoi ne voyons-nous pas des gens que nous comptions parmi les malfaiteurs?"},{"n":4033,"s":38,"a":63,"t":"Est-ce que nous les avons raillés (à tort) ou échappent-ils à nos regards?»"},{"n":4034,"s":38,"a":64,"t":"Telles sont en vérité les querelles des gens du Feu."},{"n":4035,"s":38,"a":65,"t":"Dis: «Je ne suis qu'un avertisseur. Point de divinité à part Allah, l'Unique, le Dominateur Suprême,"},{"n":4036,"s":38,"a":66,"t":"Seigneur des cieux et de la terre et de ce qui existe entre eux, le Puissant, le Grand Pardonneur»."},{"n":4037,"s":38,"a":67,"t":"Dis: «Ceci (le Coran) est une grande nouvelle,"},{"n":4038,"s":38,"a":68,"t":"mais vous vous en détournez."},{"n":4039,"s":38,"a":69,"t":"Je n'avais aucune connaissance de la cohorte sublime au moment où elle disputait."},{"n":4040,"s":38,"a":70,"t":"Il m'est seulement révélé que je suis un avertisseur clair»."},{"n":4041,"s":38,"a":71,"t":"Quand ton Seigneur dit aux Anges: «Je vais créer d'argile un être humain."},{"n":4042,"s":38,"a":72,"t":"Quand Je l'aurai bien formé et lui aurai insufflé de Mon Esprit, jetez-vous devant lui, prosternés»."},{"n":4043,"s":38,"a":73,"t":"Alors tous les Anges se prosternèrent,"},{"n":4044,"s":38,"a":74,"t":"à l'exception d'Iblîs qui s'enfla d'orgueil et fut du nombre des infidèles."},{"n":4045,"s":38,"a":75,"t":"(Allah) lui dit: «O Iblîs, qui t'a empêché de te prosterner devant ce que J'ai créé de Mes mains? T'enfles-tu d'orgueil ou te considères-tu parmi les hauts placés?»"},{"n":4046,"s":38,"a":76,"t":"«Je suis meilleur que lui, dit [Iblîs,] Tu m'as créé de feu et tu l'as créé d'argile»."},{"n":4047,"s":38,"a":77,"t":"(Allah) dit: «Sors d'ici, te voilà banni;"},{"n":4048,"s":38,"a":78,"t":"et sur toi sera ma malédiction jusqu'au jour de la Rétribution»."},{"n":4049,"s":38,"a":79,"t":"«Seigneur, dit [Iblîs], donne-moi donc un délai, jusqu'au jour où ils seront ressuscités»."},{"n":4050,"s":38,"a":80,"t":"(Allah) dit: «Tu es de ceux à qui un délai est accordé,"},{"n":4051,"s":38,"a":81,"t":"jusqu'au jour de l'Instant bien Connu»."},{"n":4052,"s":38,"a":82,"t":"«Par Ta puissance! dit [Satan]. Je les séduirai assurément tous,"},{"n":4053,"s":38,"a":83,"t":"sauf Tes serviteurs élus parmi eux»."},{"n":4054,"s":38,"a":84,"t":"(Allah) dit: «En vérité, et c'est la vérité que je dis,"},{"n":4055,"s":38,"a":85,"t":"J'emplirai certainement l'Enfer de toi et de tous ceux d'entre eux qui te suivront»."},{"n":4056,"s":38,"a":86,"t":"Dis: «Pour cela, je ne vous demande aucun salaire; et je ne suis pas un imposteur."},{"n":4057,"s":38,"a":87,"t":"Ceci [le Coran] n'est qu'un rappel à l'univers."},{"n":4058,"s":38,"a":88,"t":"Et certainement vous en aurez des nouvelles bientôt!»"},{"n":4059,"s":39,"a":1,"t":"La révélation du Livre vient d'Allah, le Puissant, le Sage."},{"n":4060,"s":39,"a":2,"t":"Nous t'avons fait descendre le Livre en toute vérité. Adore donc Allah en Lui vouant un culte exclusif."},{"n":4061,"s":39,"a":3,"t":"C'est à Allah qu'appartient la religion pure. Tandis que ceux qui prennent des protecteurs en dehors de Lui (disent): «Nous ne les adorons que pour qu'ils nous rapprochent davantage d'Allah». En vérité, Allah jugera parmi eux sur ce en quoi ils divergent. Allah ne guide pas celui qui est menteur et grand ingrat."},{"n":4062,"s":39,"a":4,"t":"Si Allah avait voulu S'attribuer un enfant, Il aurait certes choisi ce qu'Il eût voulu parmi ce qu'Il crée. Gloire à Lui! C'est Lui Allah, l'Unique, le Dominateur suprême."},{"n":4063,"s":39,"a":5,"t":"Il a créé les cieux et la terre en toute vérité. Il enroule la nuit sur le jour et enroule le jour sur la nuit, et Il a assujetti le soleil et la lune à poursuivre chacun sa course pour un terme fixé. C'est bien Lui le Puissant, le Grand Pardonneur!"},{"n":4064,"s":39,"a":6,"t":"Il vous a créés d'une personne unique et a tiré d'elle son épouse. Et Il a fait descendre [créé] pour vous huit couples de bestiaux. Il vous crée dans les ventres de vos mères, création après création, dans trois ténèbres. Tel est Allah, votre Seigneur! A Lui appartient toute la Royauté. Point de divinité à part Lui. Comment pouvez-vous vous détourner [de son culte]?"},{"n":4065,"s":39,"a":7,"t":"Si vous ne croyez pas, Allah se passe largement de vous. De Ses serviteurs cependant, Il n'agrée pas la mécréance. Et si vous êtes reconnaissants, Il l'agrée pour vous. Nul pécheur ne portera les péchés d'autrui. Ensuite, vers votre Seigneur sera votre retour: Il vous informera alors de ce que vous faisiez car Il connaît parfaitement le contenu des poitrines."},{"n":4066,"s":39,"a":8,"t":"Et quand un malheur touche l'homme, il appelle son Seigneur en se tournant vers Lui. Puis quand Il lui accorde de Sa part un bienfait, il oublie la raison pour laquelle il faisait appel, et il assigne à Allah des égaux, afin d'égarer (les gens) de son chemin. Dis «Jouis de ta mécréance un court moment. Tu fais partie des gens du Feu»."},{"n":4067,"s":39,"a":9,"t":"Est-ce que celui qui, aux heures de la nuit, reste en dévotion, prosterné et debout, prenant garde à l'au-delà et espérant la miséricorde de son Seigneur... Dis: «Sont-ils égaux, ceux qui savent et ceux qui ne savent pas?» Seuls les doués d'intelligence se rappellent."},{"n":4068,"s":39,"a":10,"t":"Dis: «O Mes serviteurs qui avez cru! Craignez votre Seigneur». Ceux qui ici-bas font le bien, auront une bonne [récompense]. La terre d'Allah est vaste et les endurants auront leur pleine récompense sans compter."},{"n":4069,"s":39,"a":11,"t":"Dis: «Il m'a été ordonné d'adorer Allah en Lui vouant exclusivement le culte,"},{"n":4070,"s":39,"a":12,"t":"et il m'a été ordonné d'être le premier des Musulmans."},{"n":4071,"s":39,"a":13,"t":"Dis: «Je crains, si je désobéis à mon Seigneur, le châtiment d'un jour terrible»."},{"n":4072,"s":39,"a":14,"t":"Dis: «C'est Allah que j'adore, et Lui voue exclusivement mon culte."},{"n":4073,"s":39,"a":15,"t":"Adorez donc, en dehors de Lui, qui vous voudrez!» - Dis: «Les perdants sont ceux qui, au Jour de la Résurrection, auront causé la perte de leurs propres âmes et celles de leurs familles». C'est bien cela la perte évidente."},{"n":4074,"s":39,"a":16,"t":"Au-dessus d'eux ils auront des couches de feu et des couches au-dessous d'eux. Voilà ce dont Allah menace Ses esclaves. «O Mes esclaves, craignez-Moi donc!»"},{"n":4075,"s":39,"a":17,"t":"Et à ceux qui s'écartent des Taghût pour ne pas les adorer, tandis qu'ils reviennent à Allah, à eux la bonne nouvelle! Annonce la bonne nouvelle à Mes serviteurs"},{"n":4076,"s":39,"a":18,"t":"qui prêtent l'oreille à la Parole, puis suivent ce qu'elle contient de meilleur. Ce sont ceux-là qu'Allah a guidés et ce sont eux les doués d'intelligence!"},{"n":4077,"s":39,"a":19,"t":"Et bien quoi! Celui contre qui s'avère le décret du châtiment,... est-ce que tu sauves celui qui est dans le Feu?"},{"n":4078,"s":39,"a":20,"t":"Mais ceux qui auront craint leur Seigneur auront [pour demeure] des étages [au Paradis] au-dessus desquels d'autres étages sont construits et sous lesquels coulent les rivières. Promesse d'Allah! Allah ne manque pas à Sa promesse."},{"n":4079,"s":39,"a":21,"t":"Ne vois-tu pas qu'Allah fait descendre du ciel de l'eau, puis Il l'achemine vers des sources dans la terre; ensuite avec cela, Il fait sortir une culture aux couleurs diverses, laquelle se fane ensuite, de sorte que tu la vois jaunie; ensuite, Il la réduit en miettes. C'est là certainement un rappel aux [gens] doués d'intelligence."},{"n":4080,"s":39,"a":22,"t":"Est-ce que celui dont Allah ouvre la poitrine à l'Islam et qui détient ainsi une lumière venant de Son Seigneur... Malheur donc à ceux dont les cœurs sont endurcis contre le rappel d'Allah. Ceux-là sont dans un égarement évident."},{"n":4081,"s":39,"a":23,"t":"Allah a fait descendre le plus beau des récits, un Livre dont [certains versets] se ressemblent et se répètent. Les peaux de ceux qui redoutent leur Seigneur frissonnent (à l'entendre); puis leurs peaux et leurs cœurs s'apaisent au rappel d'Allah. Voilà le [Livre] guide d'Allah par lequel Il guide qui Il veut. Mais quiconque Allah égare n'a point de guide."},{"n":4082,"s":39,"a":24,"t":"Est-ce que celui qui, au Jour de la Résurrection, se sera protégé le visage contre le pire châtiment... Et l'on dira aux injustes: «Goûtez à ce que vous avez acquis»."},{"n":4083,"s":39,"a":25,"t":"Ceux qui ont vécu avant eux ont démenti (les Messagers), le châtiment leur est venu par où ils ne le pressentaient pas."},{"n":4084,"s":39,"a":26,"t":"Allah leur a fait goûter l'ignominie dans la vie présente. Le châtiment de l'au-delà, cependant, est plus grand, si seulement ils savaient!"},{"n":4085,"s":39,"a":27,"t":"Nous avons, dans ce Coran, cité pour les gens des exemples de toutes sortes afin qu'ils se souviennent."},{"n":4086,"s":39,"a":28,"t":"Un Coran [en langue] arabe, dénué de tortuosité, afin qu'ils soient pieux!"},{"n":4087,"s":39,"a":29,"t":"Allah a cité comme parabole un homme appartenant à des associés se querellant à son sujet et un [autre] homme appartenant à un seul homme: sont-ils égaux en exemple? Louanges à Allah! Mais la plupart d'entre eux ne savent pas."},{"n":4088,"s":39,"a":30,"t":"En vérité tu mourras et ils mourront eux aussi;"},{"n":4089,"s":39,"a":31,"t":"ensuite, au Jour de la Résurrection, vous vous disputerez auprès de votre Seigneur."},{"n":4090,"s":39,"a":32,"t":"Quel pire injuste donc, que celui qui ment contre Allah et qui traite de mensonge la vérité quand elle lui vient? N'est-ce pas dans l'Enfer qu'il y a un refuge pour les mécréants?"},{"n":4091,"s":39,"a":33,"t":"Tandis que celui qui vient avec la vérité et celui qui la confirme, ceux-là sont les pieux."},{"n":4092,"s":39,"a":34,"t":"Ils auront tout ce qu'ils désireront auprès de leur Seigneur; voilà la récompense des bienfaisants,"},{"n":4093,"s":39,"a":35,"t":"afin qu'Allah leur efface les pires de leurs actions et les récompense selon ce qu'ils auront fait de meilleur."},{"n":4094,"s":39,"a":36,"t":"Allah ne suffit-Il pas à Son esclave [comme soutien]? Et ils te font peur avec ce qui est en dehors de Lui. Et quiconque Allah égare n'a point de guide."},{"n":4095,"s":39,"a":37,"t":"Quiconque Allah guide, nul ne peut l'égarer. Allah n'est-Il pas Puissant et Détenteur du pouvoir de châtier?"},{"n":4096,"s":39,"a":38,"t":"Si tu leur demandais: «Qui a créé les cieux et la terre?», Ils diraient assurément: «Allah». Dis: «Voyez-vous ceux que vous invoquez en dehors d'Allah; si Allah me voulait du mal, est-ce que [ces divinités] pourraient dissiper Son mal? Ou s'Il me voulait une miséricorde, pourraient-elles retenir Sa miséricorde?» - Dis: «Allah me suffit: c'est en Lui que placent leur confiance ceux qui cherchent un appui»."},{"n":4097,"s":39,"a":39,"t":"Dis: «O mon peuple, agissez selon votre méthode, moi j'agirai [selon la mienne]. Bientôt vous saurez"},{"n":4098,"s":39,"a":40,"t":"sur qui s'abattra un châtiment qui l'avilira; et sur qui se justifiera un châtiment durable»."},{"n":4099,"s":39,"a":41,"t":"Nous t'avons fait descendre le Livre, pour les hommes, en toute vérité. Quiconque se guide [le fait] pour son propre bien; et quiconque s'égare, s'égare à son détriment. Tu n'es nullement responsable [de leurs propres affaires]."},{"n":4100,"s":39,"a":42,"t":"Allah reçoit les âmes au moment de leur mort ainsi que celles qui ne meurent pas au cours de leur sommeil. Il retient celles à qui Il a décrété la mort, tandis qu'Il renvoie les autres jusqu'à un terme fixé. Il y a certainement là des preuves pour des gens qui réfléchissent."},{"n":4101,"s":39,"a":43,"t":"Ont-ils adopté, en dehors d'Allah, des intercesseurs? Dis: «Quoi! Même s'ils ne détiennent rien et sont dépourvus de raison?"},{"n":4102,"s":39,"a":44,"t":"Dis: «L'intercession toute entière appartient à Allah. A Lui la royauté des cieux et de la terre. Puis c'est vers Lui que vous serez ramenés»."},{"n":4103,"s":39,"a":45,"t":"Et quand Allah est mentionné seul (sans associés), les cœurs de ceux qui ne croient pas en l'au-delà se crispent et quand on mentionne ceux qui sont en dehors de Lui, voilà qu'ils se réjouissent."},{"n":4104,"s":39,"a":46,"t":"Dis: «O Allah, Créateur des cieux et de la terre, Connaisseur de tout ce que le monde ignore comme de ce qu'il perçoit, c'est Toi qui jugeras entre Tes serviteurs ce sur quoi ils divergeaient»."},{"n":4105,"s":39,"a":47,"t":"Si les injustes possédaient tout ce qui se trouve sur la terre, - et autant encore -, ils l'offriraient comme rançon pour échapper au pire châtiment le Jour de la Résurrection; et leur apparaîtra, de la part d'Allah, ce qu'ils n'avaient jamais imaginé;"},{"n":4106,"s":39,"a":48,"t":"et leur apparaîtront les méfaits qu'ils ont commis, et ce dont ils se raillaient les enveloppera."},{"n":4107,"s":39,"a":49,"t":"Quand un malheur touche l'homme, il Nous invoque. Quand ensuite Nous lui accordons une faveur de Notre part, il dit: «Je ne la dois qu'à [ma] science». C'est une épreuve, plutôt; mais la plupart d'entre eux ne savent pas."},{"n":4108,"s":39,"a":50,"t":"Ainsi parlaient ceux qui vécurent avant eux. Mais ce qu'ils ont acquis ne leur a servi à rien;"},{"n":4109,"s":39,"a":51,"t":"Ils furent donc atteints par les mauvaises conséquences de leurs acquis. Ceux de ces gens [les Mecquois] qui auront commis l'injustice seront atteints par les mauvaises conséquences de leurs acquis et ils ne pourront s'opposer à la puissance [d'Allah]."},{"n":4110,"s":39,"a":52,"t":"Ne savent-ils pas qu'Allah attribue Ses dons avec largesse ou les restreint à qui Il veut? Il y a en cela des preuves pour des gens qui croient."},{"n":4111,"s":39,"a":53,"t":"Dis: «O Mes serviteurs qui avez commis des excès à votre propre détriment, ne désespérez pas de la miséricorde d'Allah. Car Allah pardonne tous les péchés. Oui, c'est Lui le Pardonneur, le Très Miséricordieux."},{"n":4112,"s":39,"a":54,"t":"Et revenez repentant à votre Seigneur, et soumettez-vous à Lui, avant que ne vous vienne le châtiment et vous ne recevez alors aucun secours."},{"n":4113,"s":39,"a":55,"t":"Et suivez la meilleure révélation qui vous est descendue de la part de votre Seigneur, avant que le châtiment ne vous vienne soudain, sans que vous ne [le] pressentiez;"},{"n":4114,"s":39,"a":56,"t":"avant qu'une âme ne dise: «Malheur à moi pour mes manquements envers Allah. Car j'ai été certes, parmi les railleurs»"},{"n":4115,"s":39,"a":57,"t":"ou qu'elle ne dise: «Si Allah m'avait guidée, j'aurais été certes, parmi les pieux»"},{"n":4116,"s":39,"a":58,"t":"ou bien qu'elle ne dise en voyant le châtiment: «Ah! S'il y avait pour moi un retour! Je serais alors parmi les bienfaisants»."},{"n":4117,"s":39,"a":59,"t":"«Oh que si! Mes versets te sont venus et tu les as traités de mensonge, tu t'es enflé d'orgueil et tu étais parmi les mécréants»."},{"n":4118,"s":39,"a":60,"t":"Et au Jour de la Résurrection, tu verras les visages de ceux qui mentaient sur Allah, assombris. N'est-ce pas dans l'Enfer qu'il y aura une demeure pour les orgueilleux?"},{"n":4119,"s":39,"a":61,"t":"Et Allah sauvera ceux qui ont été pieux en leur faisant gagner [leur place au Paradis]. Nul mal ne les touchera et ils ne seront point affligés."},{"n":4120,"s":39,"a":62,"t":"Allah est le Créateur de toute chose, et de toute chose Il est Garant."},{"n":4121,"s":39,"a":63,"t":"Il détient les clefs des cieux et de la terre; et ceux qui ne croient pas aux versets d'Allah, ce sont ceux-là les perdants."},{"n":4122,"s":39,"a":64,"t":"Dis: «Me commanderez-vous d'adorer autre qu'Allah, O ignorants?»"},{"n":4123,"s":39,"a":65,"t":"En effet, il t'a été révélé, ainsi qu'à ceux qui t'ont précédé: «Si tu donnes des associés à Allah, ton œuvre sera certes vaine; et tu seras très certainement du nombre des perdants."},{"n":4124,"s":39,"a":66,"t":"Tout au contraire, adore Allah seul et sois du nombre des reconnaissants»."},{"n":4125,"s":39,"a":67,"t":"Ils n'ont pas estimé Allah comme Il devrait l'être alors qu'au Jour de la Résurrection, Il fera de la terre entière une poignée, et les cieux seront pliés dans Sa [main] droite. Gloire à Lui! Il est au-dessus de ce qu'ils Lui associent."},{"n":4126,"s":39,"a":68,"t":"Et on soufflera dans la Trompe, et voilà que ceux qui seront dans les cieux et ceux qui seront sur la terre seront foudroyés, sauf ceux qu'Allah voudra [épargner]. Puis on y soufflera de nouveau, et les voilà debout à regarder."},{"n":4127,"s":39,"a":69,"t":"Et la terre resplendira de la lumière de son Seigneur; le Livre sera déposé et on fera venir les prophètes et les témoins; on décidera parmi eux en toute équité et ils ne seront point lésés;"},{"n":4128,"s":39,"a":70,"t":"et chaque âme sera pleinement rétribuée pour ce qu'elle aura œuvré. Il [Allah] connaît mieux ce qu'ils font."},{"n":4129,"s":39,"a":71,"t":"Et ceux qui avaient mécru seront conduits par groupes à l'Enfer. Puis, quand ils y parviendront, ses portes s'ouvriront et ses gardiens leur diront: «Des messagers [choisis] parmi vous ne vous sont-ils pas venus, vous récitant les versets de votre Seigneur et vous avertissant de la rencontre de votre jour que voici?» Ils diront: si, mais le décret du châtiment s'est avéré juste contre les mécréants."},{"n":4130,"s":39,"a":72,"t":"«Entrez, [leur] dira-t-on, par les portes de l'Enfer, pour y demeurer éternellement». Qu'il est mauvais le lieu de séjour des orgueilleux!"},{"n":4131,"s":39,"a":73,"t":"Et ceux qui avaient craint leur Seigneur seront conduits par groupes au Paradis. Puis, quand ils y parviendront et que ses portes s'ouvriront ses gardiens leur diront: «Salut à vous! vous avez été bons: entrez donc, pour y demeurer éternellement»."},{"n":4132,"s":39,"a":74,"t":"Et ils diront: «Louange à Allah qui nous a tenu Sa promesse et nous a fait hériter la terre! Nous allons nous installer dans le Paradis là où nous voulons». Que la récompense de ceux qui font le bien est excellente!"},{"n":4133,"s":39,"a":75,"t":"Et tu verras les Anges faisant cercle autour du Trône, célébrant les louanges de leur Seigneur et Le glorifiant. Et il sera jugé entre eux en toute équité, et l'on dira: «Louange à Allah, Seigneur de l'univers»."},{"n":4134,"s":40,"a":1,"t":"H'â, Mîm."},{"n":4135,"s":40,"a":2,"t":"La révélation du Livre vient d'Allah, le Puissant, l'Omniscient."},{"n":4136,"s":40,"a":3,"t":"Le Pardonneur des péchés, l'Accueillant au repentir, le Dur en punition, le Détenteur des faveurs. Point de divinité à part Lui et vers Lui est la destination."},{"n":4137,"s":40,"a":4,"t":"Seuls ceux qui ont mécru discutent les versets d'Allah. Que leurs activités dans le pays ne te trompent pas."},{"n":4138,"s":40,"a":5,"t":"Avant eux, le peuple de Noé a traité (Son Messager) de menteur, et les coalisés après eux (ont fait de même), et chaque communauté a conçu le dessein de s'emparer de Son Messager. Et ils ont discuté de faux arguments pour rejeter la vérité. Alors Je les ai saisis. Et quelle punition fut la Mienne!"},{"n":4139,"s":40,"a":6,"t":"Ainsi s'avéra juste la Parole de ton Seigneur contre ceux qui ont mécru: «Ils seront les gens du Feu»."},{"n":4140,"s":40,"a":7,"t":"Ceux (les Anges) qui portent le Trône et ceux qui l'entourent célèbrent les louanges de leur Seigneur, croient en Lui et implorent le pardon pour ceux qui croient: «Seigneur! Tu étends sur toute chose Ta miséricorde et Ta science. Pardonne donc à ceux qui se repentent et suivent Ton chemin et protège-les du châtiment de l'Enfer."},{"n":4141,"s":40,"a":8,"t":"Seigneur! Fais-les entrer aux jardins d'Eden que Tu leur as promis, ainsi qu'aux vertueux parmi leurs ancêtres, leurs épouses et leurs descendants, car c'est Toi le Puissant, le Sage."},{"n":4142,"s":40,"a":9,"t":"Et préserve-les [du châtiment] des mauvaises actions. Quiconque Tu préserves [du châtiment] des mauvaises actions ce jour-là, Tu lui feras miséricorde». Et c'est là l'énorme succès."},{"n":4143,"s":40,"a":10,"t":"A ceux qui n'auront pas cru on proclamera: «l'aversion d'Allah [envers vous] est plus grande que votre aversion envers vous-mêmes, lorsque vous étiez appelés à la foi et que vous persistiez dans la mécréance»."},{"n":4144,"s":40,"a":11,"t":"Ils diront: «Notre Seigneur, Tu nous as fais mourir deux fois et redonné la vie deux fois: nous reconnaissons donc nos péchés. Y a-t-il un moyen d'en sortir?»"},{"n":4145,"s":40,"a":12,"t":"«... Il en est ainsi car lorsqu'Allah était invoqué seul (sans associé), vous ne croyiez pas; et si on Lui donnait des associés, alors vous croyiez. Le jugement appartient à Allah, le Très Haut, le Très Grand»."},{"n":4146,"s":40,"a":13,"t":"C'est Lui qui vous fait voir Ses preuves, et fait descendre du ciel, pour vous, une subsistance. Seul se rappelle celui qui revient [à Allah]."},{"n":4147,"s":40,"a":14,"t":"Invoquez Allah donc, en Lui vouant un culte exclusif quelque répulsion qu'en aient les mécréants."},{"n":4148,"s":40,"a":15,"t":"Il est Celui qui est élevé aux degrés les plus hauts, Possesseur du Trône, Il envoie par son ordre l'Esprit sur celui qu'Il veut parmi Ses serviteurs, afin que celui-ci avertisse du jour de la Rencontre,"},{"n":4149,"s":40,"a":16,"t":"le jour où ils comparaîtront sans que rien en eux ne soit caché à Allah. A qui appartient la royauté, aujourd'hui? A Allah, l'Unique, le Dominateur."},{"n":4150,"s":40,"a":17,"t":"Ce jour-là, chaque âme sera rétribuée selon ce qu'elle aura acquis. Ce jour-là, pas d'injustice, car Allah est prompt dans [Ses] comptes."},{"n":4151,"s":40,"a":18,"t":"Et avertis-les du jour qui approche, quand les cœurs remonteront aux gorges, terrifiés (ou angoissés). Les injustes n'auront ni ami zélé, ni intercesseur écouté."},{"n":4152,"s":40,"a":19,"t":"Il (Allah) connaît la trahison des yeux, tout comme ce que les poitrines cachent."},{"n":4153,"s":40,"a":20,"t":"Et Allah juge en toute équité, tandis que ceux qu'ils invoquent en dehors de Lui ne jugent rien. En vérité c'est Allah qui est l'Audient, le Clairvoyant."},{"n":4154,"s":40,"a":21,"t":"Ne parcourent-ils pas la terre, pour voir ce qu'il est advenu de ceux qui ont vécu avant eux? Ils étaient [pourtant] plus forts qu'eux et ont laissé sur terre bien plus de vestiges. Allah les saisit pour leurs péchés et ils n'eurent point de protecteur contre Allah."},{"n":4155,"s":40,"a":22,"t":"Ce fut ainsi, parce que leurs Messagers leur avaient apporté les preuves, mais ils se montrèrent mécréants. Allah donc les saisit, car Il est fort et redoutable dans Son châtiment."},{"n":4156,"s":40,"a":23,"t":"Nous envoyâmes effectivement Moïse avec Nos signes et une preuve évidente,"},{"n":4157,"s":40,"a":24,"t":"vers Pharaon, Hâmân et Coré. Mais ils dirent: «Magicien! Grand menteur!»"},{"n":4158,"s":40,"a":25,"t":"Puis, quand il leur eut apporté la vérité venant de Nous, ils dirent: «Tuez les fils de ceux qui ont cru avec lui, et laissez vivre leurs femmes». Et les ruses des mécréants ne vont qu'en pure perte."},{"n":4159,"s":40,"a":26,"t":"Et Pharaon dit: «Laissez-moi tuer Moïse. Et qu'il appelle son Seigneur! Je crains qu'il ne change votre religion ou qu'il ne fasse apparaître la corruption sur terre»."},{"n":4160,"s":40,"a":27,"t":"Moïse [lui] dit: «Je cherche auprès de mon Seigneur et le vôtre, protection contre tout orgueilleux qui ne croit pas au jour du Compte»."},{"n":4161,"s":40,"a":28,"t":"Et un homme croyant de la famille de Pharaon, qui dissimulait sa foi dit: «Tuez-vous un homme parce qu'il dit: «Mon Seigneur est Allah?» Alors qu'il est venu à vous avec les preuves évidentes de la part de votre Seigneur. S'il est menteur, son mensonge sera à son détriment; tandis que s'il est véridique, alors une partie de ce dont il vous menace tombera sur vous». Certes, Allah ne guide pas celui qui est outrancier et imposteur!"},{"n":4162,"s":40,"a":29,"t":"«O mon peuple, triomphant sur la terre, vous avez la royauté aujourd'hui. Mais qui nous secourra de la rigueur d'Allah si elle nous vient?» Pharaon dit: «Je ne vous indique que ce que je considère bon. Je ne vous guide qu'au sentier de la droiture»."},{"n":4163,"s":40,"a":30,"t":"Et celui qui était croyant dit: «O mon peuple, je crains pour vous un jour semblable à celui des coalisés."},{"n":4164,"s":40,"a":31,"t":"Un sort semblable à celui du peuple de Noé, des 'Aad et des Thamûd et de ceux [qui vécurent] après eux». Allah ne veut [faire subir] aucune injustice aux serviteurs."},{"n":4165,"s":40,"a":32,"t":"«O mon peuple, je crains pour vous le jour de l'Appel Mutuel,"},{"n":4166,"s":40,"a":33,"t":"Le jour où vous tournerez le dos en déroute, sans qu'il y ait pour vous de protecteur contre Allah». Et quiconque Allah égare, n'a point de guide."},{"n":4167,"s":40,"a":34,"t":"Certes, Joseph vous est venu auparavant avec les preuves évidentes, mais vous n'avez jamais cessé d'avoir des doutes sur ce qu'il vous avait apporté. Mais lorsqu'il mourut, vous dites alors: «Allah n'enverra plus jamais de Messager après lui». Ainsi Allah égare-t-Il celui qui est outrancier et celui qui doute."},{"n":4168,"s":40,"a":35,"t":"Ceux qui discutent les prodiges d'Allah sans qu'aucune preuve ne leur soit venue, [leur action] est grandement haïssable auprès d'Allah et auprès de ceux qui croient. Ainsi Allah scelle-t-Il le cœur de tout orgueilleux tyran."},{"n":4169,"s":40,"a":36,"t":"Et Pharaon dit: «O Hâmân, bâtis-moi une tour: peut-être atteindrai-je les voies,"},{"n":4170,"s":40,"a":37,"t":"les voies des cieux, et apercevrai-je le Dieu de Moïse; mais je pense que celui-ci est menteur». Ainsi la mauvaise action de Pharaon lui parut enjolivée; et il fut détourné du droit chemin; et le stratagème de Pharaon n'est voué qu'à la destruction."},{"n":4171,"s":40,"a":38,"t":"Et celui qui avait cru dit: «O mon peuple, suivez-moi. Je vous guiderai au sentier de la droiture."},{"n":4172,"s":40,"a":39,"t":"O mon peuple, cette vie n'est que jouissance temporaire, alors que l'au-delà est vraiment la demeure de la stabilité."},{"n":4173,"s":40,"a":40,"t":"Quiconque fait une mauvaise action ne sera rétribué que par son pareil; et quiconque, mâle ou femelle, fait une bonne action tout en étant croyant, alors ceux-là entreront au Paradis pour y recevoir leur subsistance sans compter."},{"n":4174,"s":40,"a":41,"t":"O mon peuple, mais qu'ai-je à vous appeler au salut, alors que vous m'appelez au Feu?"},{"n":4175,"s":40,"a":42,"t":"Vous m'invitez à nier Allah et à Lui donner des associés dont je n'ai aucun savoir, alors que je vous appelle au Tout Puissant, au Grand Pardonneur."},{"n":4176,"s":40,"a":43,"t":"Nul doute que ce à quoi vous m'appelez ne peut exaucer une invocation ni ici-bas ni dans l'au-delà. C'est vers Allah qu'est notre retour, et les outranciers sont eux les gens du Feu."},{"n":4177,"s":40,"a":44,"t":"Bientôt vous vous rappellerez ce que je vous dis; et je confie mon sort à Allah. Allah est, certes, Clairvoyant sur les serviteurs."},{"n":4178,"s":40,"a":45,"t":"Allah donc le protégea des méfaits de leurs ruses, alors que le pire châtiment cerna les gens de Pharaon:"},{"n":4179,"s":40,"a":46,"t":"le Feu, auquel ils sont exposés matin et soir. Et le jour où l'Heure arrivera (il sera dit): «Faites entrer les gens de Pharaon au plus dur du châtiment»."},{"n":4180,"s":40,"a":47,"t":"Et quand ils se disputeront dans le Feu, les faibles diront à ceux qui s'enflaient d'orgueil: «Nous vous avions suivis: pourriez-vous nous préserver d'une partie du feu?»"},{"n":4181,"s":40,"a":48,"t":"Et ceux qui s'enflaient d'orgueil diront: «En vérité, nous y voilà tous». Allah a déjà rendu son jugement entre les serviteurs."},{"n":4182,"s":40,"a":49,"t":"Et ceux qui seront dans le Feu diront aux gardiens de l'Enfer: «Priez votre Seigneur de nous alléger un jour de [notre] supplice»."},{"n":4183,"s":40,"a":50,"t":"Ils diront: «vos Messagers, ne vous apportaient-ils pas les preuves évidentes?» Ils diront: «Si»! Ils [les gardiens] diront: «Eh bien, priez» ! Et l'invocation des mécréants n'est qu'aberration."},{"n":4184,"s":40,"a":51,"t":"Nous secourrons, certes, Nos Messagers et ceux qui croient, dans la vie présente tout comme au jour où les témoins [les Anges gardiens] se dresseront (le Jour du Jugement),"},{"n":4185,"s":40,"a":52,"t":"au jour où leur excuse ne sera pas utile aux injustes, tandis qu'il y aura pour eux la malédiction et la pire demeure."},{"n":4186,"s":40,"a":53,"t":"En effet, Nous avons apporté à Moïse la guidée, et fait hériter aux Enfants d'Israël, le Livre,"},{"n":4187,"s":40,"a":54,"t":"une guidée et un rappel aux gens doués d'intelligence."},{"n":4188,"s":40,"a":55,"t":"Endure donc, car la promesse d'Allah est vérité, implore le pardon pour ton péché et célèbre la gloire et la louange de ton Seigneur, soir et matin."},{"n":4189,"s":40,"a":56,"t":"Ceux qui discutent sur les versets d'Allah sans qu'aucune preuve ne leur soit venue, n'ont dans leurs poitrines qu'orgueil. Ils n'atteindront pas leur but. Implore donc la protection d'Allah, car c'est Lui l'Audient, le Clairvoyant."},{"n":4190,"s":40,"a":57,"t":"La création des cieux et de la terre est quelque chose de plus grand que la création des gens. Mais la plupart des gens ne savent pas."},{"n":4191,"s":40,"a":58,"t":"L'aveugle et le voyant ne sont pas égaux, et ceux qui croient et accomplissent les bonnes œuvres ne peuvent être comparés à celui qui fait le mal. C'est rare que vous vous rappeliez!"},{"n":4192,"s":40,"a":59,"t":"En vérité; L'Heure va arriver: pas de doute là-dessus; mais la plupart des gens n'y croient pas."},{"n":4193,"s":40,"a":60,"t":"Et votre Seigneur dit: «Appelez-Moi, Je vous répondrai. Ceux qui, par orgueil, se refusent à M'adorer entreront bientôt dans l'Enfer, humiliés»."},{"n":4194,"s":40,"a":61,"t":"Allah est celui qui vous a assigné la nuit pour que vous vous y reposiez, et le jour pour y voir clair. Allah est le Pourvoyeur de grâce aux hommes, mais la plupart des gens ne sont pas reconnaissants."},{"n":4195,"s":40,"a":62,"t":"Tel est votre Seigneur, Créateur de toute chose. Point de divinité à part Lui. Comment se fait-il que vous vous détourniez (du chemin droit)?"},{"n":4196,"s":40,"a":63,"t":"Ainsi ceux qui nient les prodiges d'Allah se détournent-ils [du chemin droit.]"},{"n":4197,"s":40,"a":64,"t":"C'est Allah qui vous a assigné la terre comme demeure stable et le ciel comme toit et vous a donné votre forme, - et quelle belle forme Il vous a donnée! - et Il vous a nourris de bonnes choses. Tel est Allah, votre Seigneur; gloire à Allah, Seigneur de l'univers!"},{"n":4198,"s":40,"a":65,"t":"C'est Lui le Vivant. Point de divinité à part Lui. Appelez-Le donc, en Lui vouant un culte exclusif. Louange à Allah, Seigneur de l'univers!"},{"n":4199,"s":40,"a":66,"t":"Dis: «Il m'a été interdit, une fois que les preuves me sont venues de mon Seigneur, d'adorer ceux que vous invoquez en dehors d'Allah, et il m'a été ordonné de me soumettre au Seigneur de l'univers»."},{"n":4200,"s":40,"a":67,"t":"C'est Lui qui vous a créés de terre, puis d'une goutte sperme, puis d'une adhérence; puis Il vous fait sortir petit enfant pour qu'ensuite vous atteigniez votre maturité et qu'ensuite vous deveniez vieux, - certains parmi vous meurent plus tôt, - et pour que vous atteigniez un terme fixé, afin que vous raisonniez."},{"n":4201,"s":40,"a":68,"t":"C'est Lui qui donne la vie et donne la mort. Puis quand Il décide une affaire, Il n'a qu'à dire: «Sois», et elle est."},{"n":4202,"s":40,"a":69,"t":"N'as-tu pas vu comment ceux qui discutent sur les versets d'Allah se laissent détourner?"},{"n":4203,"s":40,"a":70,"t":"Ceux qui traitent de mensonge le Livre (le Coran) et ce avec quoi Nous avons envoyé Nos Messagers; ils sauront bientôt,"},{"n":4204,"s":40,"a":71,"t":"quand, des carcans à leurs cous et avec des chaînes ils seront traînés"},{"n":4205,"s":40,"a":72,"t":"dans l'eau bouillante; et qu'ensuite ils brûleront dans le Feu."},{"n":4206,"s":40,"a":73,"t":"Puis on leur dira: «Où sont ceux que vous associez"},{"n":4207,"s":40,"a":74,"t":"à Allah?» «Ils se sont écartés de nous, diront-ils. Ou plutôt, nous n'invoquions rien, auparavant». Ainsi Allah égare-t-Il les mécréants."},{"n":4208,"s":40,"a":75,"t":"Voilà le prix de votre exultation sur terre, sans raison, ainsi que de votre joie immodérée."},{"n":4209,"s":40,"a":76,"t":"Franchissez les portes de l'Enfer pour y demeurer éternellement. Qu'il est mauvais le lieu de séjour des orgueilleux!"},{"n":4210,"s":40,"a":77,"t":"Endure donc. La promesse d'Allah est vraie. Que Nous te montrions une partie de ce dont Nous les menaçons ou que Nous te fassions mourir (avant cela)... c'est vers Nous qu'ils seront ramenés."},{"n":4211,"s":40,"a":78,"t":"Certes, Nous avons envoyé avant toi des Messagers. Il en est dont Nous t'avons raconté l'histoire; et il en est dont Nous ne t'avons pas raconté l'histoire. Et il n'appartient pas à un Messager d'apporter un signe [ou verset] si ce n'est avec la permission d'Allah. Lorsque le commandement d'Allah viendra, tout sera décidé en toute justice; et ceux qui profèrent des mensonges sont alors les perdants."},{"n":4212,"s":40,"a":79,"t":"C'est Allah qui vous a fait les bestiaux pour que vous en montiez et que vous en mangiez,"},{"n":4213,"s":40,"a":80,"t":"et vous y avez des profits et afin que vous atteigniez sur eux une chose nécessaire qui vous tenait à cœur. C'est sur eux et sur les vaisseaux que vous êtes transportés."},{"n":4214,"s":40,"a":81,"t":"Et Il vous montre Ses merveilles. Quelles merveilles d'Allah niez-vous donc?"},{"n":4215,"s":40,"a":82,"t":"Ne parcourent-ils donc pas la terre pour voir ce qu'il est advenu de ceux qui étaient avant eux? Ils étaient [pourtant] plus nombreux qu'eux et bien plus puissants et ils [avaient laissé] sur terre beaucoup plus de vestiges. Mais ce qu'ils ont acquis ne leur a servi à rien."},{"n":4216,"s":40,"a":83,"t":"Lorsque leurs Messagers leur apportaient les preuves évidentes, ils exultaient des connaissances qu'ils avaient. Et ce dont ils se moquaient les enveloppa."},{"n":4217,"s":40,"a":84,"t":"Puis, quand ils virent Notre rigueur ils dirent: «Nous croyons en Allah Seul, et nous renions ce que nous Lui donnions comme associés»."},{"n":4218,"s":40,"a":85,"t":"Mais leur croyance, au moment où ils eurent constaté Notre rigueur, ne leur profita point; Telle est la règle d'Allah envers Ses serviteurs dans le passé. Et c'est là que les mécréants se trouvèrent perdants."},{"n":4219,"s":41,"a":1,"t":"H'â, Mîm."},{"n":4220,"s":41,"a":2,"t":"[C'est] une Révélation descendue de la part du Tout Miséricordieux, du Très Miséricordieux."},{"n":4221,"s":41,"a":3,"t":"Un Livre dont les versets sont détaillés (et clairement exposés), un Coran [lecture] arabe pour des gens qui savent,"},{"n":4222,"s":41,"a":4,"t":"annonciateur [d'une bonne nouvelle] et avertisseur. Mais la plupart d'entre eux se détournent; c'est qu'ils n'entendent pas."},{"n":4223,"s":41,"a":5,"t":"Et ils dirent: «Nos cœurs sont voilés contre ce à quoi tu nous appelles, nos oreilles sont sourdes. Et entre nous et toi, il y a une cloison. Agis donc de ton côté; nous agissons du nôtre.»"},{"n":4224,"s":41,"a":6,"t":"Dis: «Je ne suis qu'un homme comme vous. Il m'a été révélé que votre Dieu est un Dieu unique. Cherchez le droit chemin vers Lui et implorez son pardon». Et malheur aux Associateurs"},{"n":4225,"s":41,"a":7,"t":"qui n'acquittent pas la Zakât et ne croient pas en l'au-delà!"},{"n":4226,"s":41,"a":8,"t":"Ceux qui croient et accomplissent de bonnes œuvres auront une énorme récompense jamais interrompue."},{"n":4227,"s":41,"a":9,"t":"Dis: «Renierez-vous [l'existence] de celui qui a créé la terre en deux jours et Lui donnerez-vous des égaux? Tel est le Seigneur de l'univers,"},{"n":4228,"s":41,"a":10,"t":"c'est Lui qui a fermement fixé des montagnes au-dessus d'elle, l'a bénie et lui assigna ses ressources alimentaires en quatre jours d'égale durée. [Telle est la réponse] à ceux qui t'interrogent."},{"n":4229,"s":41,"a":11,"t":"Il S'est ensuite adressé au ciel qui était alors fumée et lui dit, ainsi qu'à la terre: «Venez tous deux, bon gré, mal gré». Tous deux dirent: «Nous venons obéissants»."},{"n":4230,"s":41,"a":12,"t":"Il décréta d'en faire sept cieux en deux jours et révéla à chaque ciel sa fonction. Et Nous avons décoré le ciel le plus proche de lampes [étoiles] et l'avons protégé. Tel est l'Ordre établi par le Puissant, l'Omniscient."},{"n":4231,"s":41,"a":13,"t":"S'ils s'en détournent, alors dis-leur; «Je vous ai avertis d'une foudre semblable à celle qui frappa les 'Aad et les Tamûd»."},{"n":4232,"s":41,"a":14,"t":"Quand les Messagers leur étaient venus, de devant eux et par derrière, [leur disant]: «N'adorez qu'Allah», ils dirent: «Si notre Seigneur avait voulu, Il aurait certainement fait descendre des Anges. Nous ne croyons donc pas [au message] avec lequel vous avez été envoyés»."},{"n":4233,"s":41,"a":15,"t":"Quant aux 'Aad, ils s'enflèrent d'orgueil sur terre injustement et dirent: «Qui est plus fort que nous?» Quoi! N'ont-ils pas vu qu'en vérité Allah qui les a créés est plus fort qu'eux? Et ils reniaient Nos signes."},{"n":4234,"s":41,"a":16,"t":"Nous déchaînâmes contre eux un vent violent et glacial en des jours néfastes, afin de leur faire goûter le châtiment de l'ignominie dans la vie présente. Le châtiment de l'au-delà cependant est plus ignominieux encore, et ils ne seront pas secourus."},{"n":4235,"s":41,"a":17,"t":"Et quant aux Tamûd, Nous les guidâmes; mais ils ont préféré l'aveuglement à la guidée. C'est alors qu'ils furent saisis par la foudre du supplice le plus humiliant pour ce qu'ils avaient acquis."},{"n":4236,"s":41,"a":18,"t":"Et Nous sauvâmes ceux qui croyaient et craignaient Allah."},{"n":4237,"s":41,"a":19,"t":"Et le jour où les ennemis d'Allah seront rassemblés en masse vers le Feu... Puis on les poussera [dans sa direction]."},{"n":4238,"s":41,"a":20,"t":"Alors, quand ils y seront, leur ouïe, leurs yeux et leurs peaux témoigneront contre eux de ce qu'ils œuvraient."},{"n":4239,"s":41,"a":21,"t":"Ils diront à leurs peaux: «Pourquoi avez-vous témoigné contre nous?» Elles diront: «C'est Allah qui nous a fait parler, Lui qui fait parler toute chose. C'est Lui qui vous a créés une première fois et c'est vers Lui que vous serez retournés»."},{"n":4240,"s":41,"a":22,"t":"Vous ne pouviez vous cacher au point que ni votre ouïe, ni vos yeux et ni vos peaux ne puissent témoigner contre vous. Mais vous pensiez qu'Allah ne savait pas beaucoup de ce que vous faisiez."},{"n":4241,"s":41,"a":23,"t":"Et c'est cette pensée que vous avez eue de votre Seigneur, qui vous a ruinés, de sorte que vous êtes devenus du nombre des perdants."},{"n":4242,"s":41,"a":24,"t":"S'ils endurent, le Feu sera leur lieu de séjour; et s'ils cherchent à s'excuser, ils ne seront pas excusés."},{"n":4243,"s":41,"a":25,"t":"Et Nous leur avons destiné des compagnons inséparables [des démons] qui leur ont enjolivé ce qui était devant et derrière eux. Et le décret s'est avéré juste contre eux, comme contre les autres communautés de djinns et d'hommes qui ont vécu avant eux. Ils sont certes perdants!"},{"n":4244,"s":41,"a":26,"t":"Et ceux qui avaient mécru dirent: «Ne prêtez pas l'oreille à ce Coran, et faites du chahut (pendant sa récitation), afin d'avoir le dessus»."},{"n":4245,"s":41,"a":27,"t":"Nous ferons certes, goûter à ceux qui ne croient pas un dur châtiment, et les rétribuerons certes [d'une punition] pire que ce [que méritent] leurs méfaits."},{"n":4246,"s":41,"a":28,"t":"Ainsi, la rétribution des ennemis d'Allah sera le Feu où ils auront une demeure éternelle, comme punition pour avoir nié Nos versets [le Coran]."},{"n":4247,"s":41,"a":29,"t":"Et les mécréants diront: «Seigneur, fais-nous voir ceux des djinns et des humains qui nous ont égarés, afin que nous les placions tous sous nos pieds, pour qu'ils soient parmi les plus bas»."},{"n":4248,"s":41,"a":30,"t":"Ceux qui disent: «Notre Seigneur est Allah», et qui se tiennent dans le droit chemin, les Anges descendent sur eux. «N'ayez pas peur et ne soyez pas affligés; mais ayez la bonne nouvelle du Paradis qui vous était promis."},{"n":4249,"s":41,"a":31,"t":"Nous sommes vos protecteurs dans la vie présente et dans l'au-delà; et vous y aurez ce que vos âmes désireront et ce que vous réclamerez,"},{"n":4250,"s":41,"a":32,"t":"un lieu d'accueil de la part d'un Très Grand Pardonneur, d'un Très Miséricordieux»."},{"n":4251,"s":41,"a":33,"t":"Et qui profère plus belles paroles que celui qui appelle à Allah, fait bonne œuvre et dit: «Je suis du nombre des Musulmans?»"},{"n":4252,"s":41,"a":34,"t":"La bonne action et la mauvaise ne sont pas pareilles. Repousse (le mal) par ce qui est meilleur; et voilà que celui avec qui tu avais une animosité devient tel un ami chaleureux."},{"n":4253,"s":41,"a":35,"t":"Mais (ce privilège) n'est donné qu'à ceux qui endurent et il n'est donné qu'au possesseur d'une grâce infinie."},{"n":4254,"s":41,"a":36,"t":"Et si jamais le Diable t'incite (à agir autrement), alors cherche refuge auprès d'Allah; c'est Lui, vraiment l'Audient, l'Omniscient."},{"n":4255,"s":41,"a":37,"t":"Parmi Ses merveilles, sont la nuit et le jour, le soleil et la lune: ne vous prosternez ni devant le soleil, ni devant la lune, mais prosternez-vous devant Allah qui les a créés, si c'est Lui que vous adorez."},{"n":4256,"s":41,"a":38,"t":"Mais s'ils s'enflent d'orgueil... ceux qui sont auprès de ton Seigneur [les Anges] Le glorifient, nuit et jour, sans jamais se lasser!"},{"n":4257,"s":41,"a":39,"t":"Et parmi Ses merveilles est que tu vois la terre humiliée (toute nue). Puis aussitôt que Nous faisons descendre l'eau sur elle, elle se soulève et augmente [de volume]. Celui qui lui redonne la vie est certes Celui qui fera revivre les morts, car Il est Omnipotent."},{"n":4258,"s":41,"a":40,"t":"Ceux qui dénaturent le sens de Nos versets (le Coran) ne Nous échappent pas. Celui qui sera jeté au Feu sera-t-il meilleur que celui qui viendra en toute sécurité le Jour de la Résurrection? Faites ce que vous voulez car Il est Clairvoyant sur tout ce que vous faites;"},{"n":4259,"s":41,"a":41,"t":"Ceux qui ne croient pas au Rappel [le Coran] quand il leur parvient... alors que c'est un Livre puissant [inattaquable];"},{"n":4260,"s":41,"a":42,"t":"Le faux ne l'atteint [d'aucune part], ni par devant ni par derrière: c'est une révélation émanant d'un Sage, Digne de louange."},{"n":4261,"s":41,"a":43,"t":"Il ne t'est dit que ce qui a été dit aux Messagers avant toi. Ton Seigneur est certes Détenteur du pardon et Détenteur aussi d'une punition douloureuse."},{"n":4262,"s":41,"a":44,"t":"Si Nous en avions fait un Coran en une langue autre que l'arabe, ils auraient dit: «Pourquoi ses versets n'ont-ils pas été exposés clairement? quoi? Un [Coran] non-arabe et [un Messager] arabe?» Dis: «Pour ceux qui croient, il est une guidée et une guérison». Et quant à ceux qui ne croient pas, il y a une surdité dans leurs oreilles et ils sont frappés d'aveuglement en ce qui le concerne; ceux-là sont appelés d'un endroit lointain."},{"n":4263,"s":41,"a":45,"t":"Nous avons effectivement donné à Moïse le Livre. Puis, il y eut controverse là-dessus. Et si ce n'était une parole préalable de ton Seigneur, on aurait certainement tranché entre eux. Ils sont vraiment, à son sujet, dans un doute troublant."},{"n":4264,"s":41,"a":46,"t":"Quiconque fait une bonne œuvre, c'est pour son bien. Et quiconque fait le mal, il le fait à ses dépens. Ton Seigneur, cependant, n'est point injuste envers les serviteurs."},{"n":4265,"s":41,"a":47,"t":"A Lui revient la connaissance de l'Heure. Aucun fruit ne sort de son enveloppe, aucune femelle ne conçoit ni ne met bas sans qu'Il n'en ait connaissance. Et le jour où Il les appellera: «Où sont Mes associés?», ils diront: «Nous Te déclarons qu'il n'y a point de témoin parmi nous»!"},{"n":4266,"s":41,"a":48,"t":"Et ce qu'auparavant ils invoquaient les délaissera; et ils réaliseront qu'ils n'ont point d'échappatoire."},{"n":4267,"s":41,"a":49,"t":"L'homme ne se lasse pas d'implorer le bien. Si le mal le touche, le voilà désespéré, désemparé."},{"n":4268,"s":41,"a":50,"t":"Et si nous lui faisons goûter une miséricorde de Notre part, après qu'une détresse l'ait touché, il dit certainement: «Cela m'est dû! Et je ne pense pas que l'Heure se lèvera [un jour]. Et si je suis ramené vers mon Seigneur, je trouverai, près de Lui, la plus belle part». Nous informerons ceux qui ont mécru de ce qu'ils ont fait et Nous leur ferons sûrement goûter à un dur châtiment."},{"n":4269,"s":41,"a":51,"t":"Quand Nous comblons de bienfaits l'homme, il s'esquive et s'éloigne. Et quand un malheur le touche, il se livre alors à une longue prière."},{"n":4270,"s":41,"a":52,"t":"Dis: «Voyez-vous? Si ceci (le Coran) émane d'Allah et qu'ensuite vous le reniez; qui se trouvera plus égaré que celui qui s'éloigne dans la dissidence?»"},{"n":4271,"s":41,"a":53,"t":"Nous leur montrerons Nos signes dans l'univers et en eux-mêmes, jusqu'à ce qu'il leur devienne évident que c'est cela (le Coran), la vérité. Ne suffit-il pas que ton Seigneur soit témoin de toute chose?"},{"n":4272,"s":41,"a":54,"t":"Ils sont dans le doute, n'est-ce pas, au sujet de la rencontre de leur Seigneur? C'est Lui certes qui embrasse toute chose (par Sa science et Sa puissance)."},{"n":4273,"s":42,"a":1,"t":"H'â, Mîm."},{"n":4274,"s":42,"a":2,"t":"Aîn, Sîn, Qâf."},{"n":4275,"s":42,"a":3,"t":"C'est ainsi qu'Allah, le Puissant, le Sage, te fait des révélations, comme à ceux qui ont vécu avant toi."},{"n":4276,"s":42,"a":4,"t":"A Lui appartient ce qui est dans les cieux et ce qui est sur la terre. Et Il est le Sublime, le Très Grand,"},{"n":4277,"s":42,"a":5,"t":"Peu s'en faut que les cieux ne se fendent depuis leur faîte quand les anges glorifient leur Seigneur, célèbrent Ses louanges et implorent le pardon pour ceux qui sont sur la terre. Allah est certes le Pardonneur, le Très Miséricordieux."},{"n":4278,"s":42,"a":6,"t":"Et quant à ceux qui prennent des protecteurs en dehors de Lui, Allah veille à ce qu'ils font. Et tu n'es pas pour eux un garant."},{"n":4279,"s":42,"a":7,"t":"Et c'est ainsi que Nous t'avons révélé un Coran arabe, afin que tu avertisses la Mère des cités (la Mecque) et ses alentours et que tu avertisses du Jour du rassemblement, - sur lequel il n'y a pas de doute - Un groupe au Paradis et un groupe dans la fournaise ardente."},{"n":4280,"s":42,"a":8,"t":"Et si Allah avait voulu, Il en aurait fait une seule communauté. Mais Il fait entrer qui Il veut dans Sa miséricorde. Et les injustes n'auront ni maître ni secoureur."},{"n":4281,"s":42,"a":9,"t":"Ont-ils pris des maîtres en dehors de Lui ? C'est Allah qui est le seul Maître et c'est Lui qui redonne la vie aux morts; et c'est Lui qui est Omnipotent."},{"n":4282,"s":42,"a":10,"t":"Sur toutes vos divergences, le jugement appartient à Allah. Tel est Allah mon Seigneur; en Lui je place ma confiance et c'est à Lui que je retourne [repentant]"},{"n":4283,"s":42,"a":11,"t":"...Créateur des cieux et de la terre. Il vous a donné des épouses [issues] de vous-mêmes et des bestiaux par couples; par ce moyen Il vous multiplie. Il n'y a rien qui Lui ressemble; et c'est Lui l'Audient, le Clairvoyant."},{"n":4284,"s":42,"a":12,"t":"Il possède les clefs [des trésors] des cieux et de la terre. Il attribue Ses dons avec largesse, ou les restreint à qui Il veut. Certes, Il est Omniscient."},{"n":4285,"s":42,"a":13,"t":"Il vous a légiféré en matière de religion, ce qu'Il avait enjoint à Noé, ce que Nous t'avons révélé, ainsi que ce que Nous avons enjoint à Abraham, à Moïse et à Jésus: «Etablissez la religion; et n'en faites pas un sujet de divisions». Ce à quoi tu appelles les associateurs leur paraît énorme Allah élit et rapproche de Lui qui Il veut et guide vers Lui celui qui se repent."},{"n":4286,"s":42,"a":14,"t":"Ils ne se sont divisés qu'après avoir reçu la science et ceci par rivalité entre eux. Et si ce n'était une parole préalable de ton Seigneur pour un terme fixé, on aurait certainement tranché entre eux. Ceux à qui le Livre a été donné en héritage après eux sont vraiment à son sujet, dans un doute troublant."},{"n":4287,"s":42,"a":15,"t":"Appelle donc (les gens) à cela; reste droit comme il t'a été commandé; ne suis pas leurs passions; et dis: «Je crois en tout ce qu'Allah a fait descendre comme Livre, et il m'a été commandé d'être équitable entre vous. Allah est notre Seigneur et votre Seigneur. A nous nos œuvres et à vous vos œuvres. Aucun argument [ne peut trancher] entre nous et vous. Allah nous regroupera tous. Et vers Lui est la destination»."},{"n":4288,"s":42,"a":16,"t":"Et ceux qui discutent au sujet d'Allah, après qu'il a été répondu à [Son appel], leur argumentation est auprès d'Allah sans valeur. Une colère tombera sur eux et ils auront un dur châtiment."},{"n":4289,"s":42,"a":17,"t":"C'est Allah qui a fait descendre le Livre en toute vérité, ainsi que la balance. Et qu'en sais-tu? Peut-être que l'Heure est proche?"},{"n":4290,"s":42,"a":18,"t":"Ceux qui n'y croient pas cherchent à la hâter; tandis que ceux qui croient en sont craintifs et savent qu'elle est la pure vérité. Et ceux qui discutent à propos de l'Heure sont dans un égarement lointain."},{"n":4291,"s":42,"a":19,"t":"Allah est doux envers Ses serviteurs. Il attribue [Ses biens] à qui Il veut. Et c'est Lui le Fort, le Puissant."},{"n":4292,"s":42,"a":20,"t":"Quiconque désire labourer [le champ] de la vie future, Nous augmenterons pour lui son labour. Quiconque désire labourer [le champ] de la présente vie, Nous lui en accorderons de [ses jouissances]; mais il n'aura pas de part dans l'au-delà."},{"n":4293,"s":42,"a":21,"t":"Ou bien auraient-ils des associés [à Allah] qui auraient établi pour eux des lois religieuses qu'Allah n'a jamais permises? Or, si l'arrêt décisif n'avait pas été prononcé, il aurait été tranché entre eux. Les injustes auront certes un châtiment douloureux."},{"n":4294,"s":42,"a":22,"t":"Tu verras les injustes épouvantés par ce qu'ils ont fait, et le châtiment s'abattra sur eux (inéluctablement). Et ceux qui croient et accomplissent les bonnes œuvres, seront dans les sites fleuris des jardins, ayant ce qu'ils voudront auprès de leur Seigneur. Telle est la grande grâce!"},{"n":4295,"s":42,"a":23,"t":"Telle est la [bonne nouvelle] qu'Allah annonce à ceux de Ses serviteurs qui croient et accomplissent les bonnes œuvres! Dis: «Je ne vous en demande aucun salaire si ce n'est l'affection eu égard à [nos liens] de parenté». Et quiconque accomplit une bonne action, Nous répondons par [une récompense] plus belle encore. Allah est certes Pardonneur et Reconnaissant."},{"n":4296,"s":42,"a":24,"t":"Ou bien ils disent il a inventé un mensonge contre Allah. Or, si Allah voulait, Il scellerait ton cœur. Par Ses Paroles cependant, Allah efface le faux et confirme le vrai. Il connaît parfaitement le contenu des poitrines."},{"n":4297,"s":42,"a":25,"t":"Et c'est lui qui agrée de Ses serviteurs le repentir, pardonne les méfaits et sait ce que vous faites,"},{"n":4298,"s":42,"a":26,"t":"et exauce [les vœux] de ceux qui croient et accomplissent les bonnes œuvres et leur accroît Sa faveur, tandis que les mécréants ont un dur châtiment."},{"n":4299,"s":42,"a":27,"t":"Si Allah attribuait Ses dons avec largesse à [tous] Ses serviteurs, ils commettraient des abus sur la terre; mais, Il fait descendre avec mesure ce qu'Il veut. Il connaît parfaitement Ses serviteurs et en est Clairvoyant."},{"n":4300,"s":42,"a":28,"t":"Et c'est Lui qui fait descendre la pluie après qu'on en a désespéré, et répand Sa miséricorde. Et c'est Lui le Maître, le Digne de louange."},{"n":4301,"s":42,"a":29,"t":"Parmi Ses preuves est la création des cieux et de la terre et des êtres vivants qu'Il y a disséminés. Il a en outre le pouvoir de les réunir quand Il voudra."},{"n":4302,"s":42,"a":30,"t":"Tout malheur qui vous atteint est dû à ce que vos mains ont acquis. Et Il pardonne beaucoup."},{"n":4303,"s":42,"a":31,"t":"Vous ne pouvez pas échapper à la puissance d'Allah sur la terre; et vous n'avez en dehors d'Allah, ni maître ni défenseur."},{"n":4304,"s":42,"a":32,"t":"Et parmi Ses preuves, sont les vaisseaux à travers la mer, semblables à des montagnes."},{"n":4305,"s":42,"a":33,"t":"S'Il veut, Il calme le vent, et les voilà qui restent immobiles à sa surface. Ce sont certainement là des preuves pour tout [homme] endurant et reconnaissant."},{"n":4306,"s":42,"a":34,"t":"Ou bien, Il les détruit en punition de ce qu'ils ont acquis [comme péchés]. Cependant, Il pardonne beaucoup."},{"n":4307,"s":42,"a":35,"t":"Ceux qui disputent à propos de Nos preuves savent bien qu'ils n'ont pas d'échappatoire."},{"n":4308,"s":42,"a":36,"t":"Tout ce qui vous a été donné [comme bien] n'est que jouissance de la vie présente; mais ce qui est auprès d'Allah est meilleur et plus durable pour ceux qui ont cru et qui placent leur confiance en leur Seigneur,"},{"n":4309,"s":42,"a":37,"t":"qui évitent [de commettre] les péchés les plus graves ainsi que les turpitudes, et qui pardonnent après s'être mis en colère,"},{"n":4310,"s":42,"a":38,"t":"qui répondent à l'appel de leur Seigneur, accomplissent la Salât, se consultent entre eux à propos de leurs affaires, dépensent de ce que Nous leur attribuons,"},{"n":4311,"s":42,"a":39,"t":"et qui, atteints par l'injustice, ripostent."},{"n":4312,"s":42,"a":40,"t":"La sanction d'une mauvaise action est une mauvaise action [une peine] identique. Mais quiconque pardonne et réforme, son salaire incombe à Allah. Il n'aime point les injustes!"},{"n":4313,"s":42,"a":41,"t":"Quant à ceux qui ripostent après avoir été lésés, ...ceux-là pas de voie (recours légal) contre eux;"},{"n":4314,"s":42,"a":42,"t":"il n'y a de voie [de recours] que contre ceux qui lèsent les gens et commettent des abus, contrairement au droit, sur la terre: ceux-là auront un châtiment douloureux."},{"n":4315,"s":42,"a":43,"t":"Et celui qui endure et pardonne, cela en vérité, fait partie des bonnes dispositions et de la résolution dans les affaires."},{"n":4316,"s":42,"a":44,"t":"Et quiconque Allah égare n'a aucun protecteur après Lui. Cependant tu verras les injustes dire, en voyant le châtiment: «Y a-t-il un moyen de retourner [sur terre]?»"},{"n":4317,"s":42,"a":45,"t":"Et tu les verras exposés devant l'Enfer, confondus dans l'avilissement, et regardant d'un œil furtif, tandis que ceux qui ont cru diront: «Les perdants sont certes, ceux qui au Jour de la Résurrection font leur propre perte et celle de leurs familles». Les injustes subiront certes un châtiment permanent."},{"n":4318,"s":42,"a":46,"t":"Ils n'auront pas de protecteur en dehors d'Allah pour les secourir et quiconque Allah égare n'a plus aucune voie."},{"n":4319,"s":42,"a":47,"t":"Répondez à l'appel de votre Seigneur avant que ne vienne un jour dont Allah ne reportera jamais le terme. Ce jour-là, nul refuge pour vous et vous ne pourrez point nier (vos péchés)."},{"n":4320,"s":42,"a":48,"t":"S'ils se détournent, ...Nous ne t'avons pas envoyé pour assurer leur sauvegarde: tu n'es chargé que de transmettre [le message]. Et lorsque Nous faisons goûter à l'homme une miséricorde venant de Nous, il en exulte; mais si un malheur les atteint pour ce que leurs mains ont perpétré..., l'homme est alors très ingrat!"},{"n":4321,"s":42,"a":49,"t":"A Allah appartient la royauté des cieux et de la terre. Il crée ce qu'Il veut. Il fait don de filles à qui Il veut, et don de garçons à qui Il veut,"},{"n":4322,"s":42,"a":50,"t":"ou bien Il donne à la fois garçons et filles; et Il rend stérile qui Il veut. Il est certes Omniscient et Omnipotent."},{"n":4323,"s":42,"a":51,"t":"Il n'a pas été donné à un mortel qu'Allah lui parle autrement que par révélation ou de derrière un voile, ou qu'Il [Lui] envoie un messager (Ange) qui révèle, par Sa permission, ce qu'Il [Allah] veut. Il est Sublime et Sage."},{"n":4324,"s":42,"a":52,"t":"Et c'est ainsi que Nous t'avons révélé un esprit [le Coran] provenant de Notre ordre. Tu n'avais aucune connaissance du Livre ni de la foi; mais Nous en avons fait une lumière par laquelle Nous guidons qui Nous voulons parmi Nos serviteurs. Et en vérité tu guides vers un chemin droit,"},{"n":4325,"s":42,"a":53,"t":"le chemin d'Allah à Qui appartient ce qui est dans les cieux et ce qui est sur la terre. Oui c'est à Allah que s'acheminent toutes les choses."},{"n":4326,"s":43,"a":1,"t":"H'â, Mîm."},{"n":4327,"s":43,"a":2,"t":"Par le Livre explicite!"},{"n":4328,"s":43,"a":3,"t":"Nous en avons fait un Coran arabe afin que vous raisonniez."},{"n":4329,"s":43,"a":4,"t":"Il est auprès de Nous, dans l'Ecriture-Mère (l'original au ciel), sublime et rempli de sagesse."},{"n":4330,"s":43,"a":5,"t":"Quoi! Allons-Nous vous dispenser du Rappel [le Coran] pour la raison que vous êtes des gens outranciers?"},{"n":4331,"s":43,"a":6,"t":"Que de prophètes avons-Nous envoyés aux Anciens!"},{"n":4332,"s":43,"a":7,"t":"et pas un prophète ne leur venait qu'ils ne le tournaient en dérision."},{"n":4333,"s":43,"a":8,"t":"Nous avons fait périr de plus redoutables qu'eux! Et on a déjà cité l'exemple des anciens."},{"n":4334,"s":43,"a":9,"t":"Et si tu leur demandes: «Qui a créé les cieux et la terre?» Ils diront très certainement: «Le Puissant, l'Omniscient les a créés»."},{"n":4335,"s":43,"a":10,"t":"Celui qui vous a donné la terre pour berceau et vous y a tracé des sentiers afin que vous vous guidiez;"},{"n":4336,"s":43,"a":11,"t":"Celui qui a fait descendre l'eau du ciel avec mesure et avec laquelle Nous ranimons une cité morte [aride]. Ainsi vous serez ressuscités;"},{"n":4337,"s":43,"a":12,"t":"Celui qui a créé les couples dans leur totalité et a fait pour vous, des vaisseaux et des bestiaux, des montures,"},{"n":4338,"s":43,"a":13,"t":"afin que vous vous installiez sur leurs dos, et qu'ensuite, après vous y être installés, vous vous rappeliez le bienfait de votre Seigneur et que vous disiez: «Gloire à Celui qui nous a soumis tout cela alors que nous n'étions pas capables de les dominer."},{"n":4339,"s":43,"a":14,"t":"C'est vers notre Seigneur que nous retournerons»."},{"n":4340,"s":43,"a":15,"t":"Et ils Lui firent de Ses serviteurs une partie [de Lui-Même]. L'homme est vraiment un ingrat déclaré!"},{"n":4341,"s":43,"a":16,"t":"Ou bien Se serait-Il attribué des filles parmi ce qu'Il crée et accordé à vous par préférence des fils?"},{"n":4342,"s":43,"a":17,"t":"Or, quand on annonce à l'un d'eux (la naissance) d'une semblable de ce qu'il attribue au Tout Miséricordieux, son visage s'assombrit d'un chagrin profond."},{"n":4343,"s":43,"a":18,"t":"Quoi! Cet être (la fille) élevé au milieu des parures et qui, dans la dispute, est incapable de se défendre par une argumentation claire et convaincante?"},{"n":4344,"s":43,"a":19,"t":"Et ils firent des Anges qui sont les serviteurs du Tout Miséricordieux des [êtres] féminins! Etaient-ils témoins de leur création? Leur témoignage sera alors inscrit; et ils seront interrogés."},{"n":4345,"s":43,"a":20,"t":"Et ils dirent: «Si le Tout Miséricordieux avait voulu, nous ne les aurions pas adorés». Ils n'en ont aucune connaissance; ils ne font que se livrer à des conjectures."},{"n":4346,"s":43,"a":21,"t":"Ou bien, leur avions-Nous donné avant lui [le Coran] un Livre auquel ils seraient fermement attachés?"},{"n":4347,"s":43,"a":22,"t":"Mais plutôt ils dirent: «Nous avons trouvé nos ancêtres sur une religion, et nous nous guidons sur leurs traces»."},{"n":4348,"s":43,"a":23,"t":"Et c'est ainsi que Nous n'avons pas envoyé avant toi d'avertisseur en une cité, sans que ses gens aisés n'aient dit: «Nous avons trouvé nos ancêtres sur une religion et nous suivons leurs traces»."},{"n":4349,"s":43,"a":24,"t":"Il dit: «Même si je viens à vous avec une meilleure direction que celle sur laquelle vous avez trouvé vos ancêtres?» Ils dirent: «Nous ne croyons pas au message avec lequel vous avez été envoyés»."},{"n":4350,"s":43,"a":25,"t":"Nous Nous vengeâmes d'eux. Regarde ce qu'il est advenu de ceux qui criaient au mensonge."},{"n":4351,"s":43,"a":26,"t":"Et lorsqu'Abraham dit à son père et à son peuple: «Je désavoue totalement ce que vous adorez,"},{"n":4352,"s":43,"a":27,"t":"à l'exception de Celui qui m'a créé, car c'est Lui en vérité qui me guidera»."},{"n":4353,"s":43,"a":28,"t":"Et il en fit une parole qui devait se perpétuer parmi sa descendance. Peut-être reviendront-ils?"},{"n":4354,"s":43,"a":29,"t":"Mais à ces gens ainsi qu'à leurs ancêtres J'ai accordé la jouissance jusqu'à ce que leur vinrent la Vérité (le Coran) et un Messager explicite."},{"n":4355,"s":43,"a":30,"t":"Et quand la Vérité leur vint, ils dirent: «C'est de la magie et nous n'y croyons pas»."},{"n":4356,"s":43,"a":31,"t":"Et ils dirent: «Pourquoi n'a-t-on pas fait descendre ce Coran sur un haut personnage de l'une des deux cités?» (la Mecque et Tâ'îf)."},{"n":4357,"s":43,"a":32,"t":"Est-ce eux qui distribuent la miséricorde de ton Seigneur? C'est Nous qui avons réparti entre eux leur subsistance dans la vie présente et qui les avons élevés en grades les uns sur les autres, afin que les uns prennent les autres à leur service. La miséricorde de ton Seigneur vaut mieux, cependant, que ce qu'ils amassent."},{"n":4358,"s":43,"a":33,"t":"Si les hommes ne devaient pas constituer une seule communauté (mécréante), Nous aurions certes pourvu les maisons de ceux qui ne croient pas au Tout Miséricordieux, de toits d'argent avec des escaliers pour y monter;"},{"n":4359,"s":43,"a":34,"t":"(Nous aurions pourvu) leurs maisons de portes et de divans où ils s'accouderaient,"},{"n":4360,"s":43,"a":35,"t":"ainsi que des ornements. Et tout cela ne serait que jouissance temporaire de la vie d'ici-bas, alors que l'au-delà, auprès de ton Seigneur, est pour les pieux."},{"n":4361,"s":43,"a":36,"t":"Et quiconque s'aveugle (et s'écarte) du rappel du Tout Miséricordieux, Nous lui désignons un diable qui devient son compagnon inséparable."},{"n":4362,"s":43,"a":37,"t":"Ils [Les diables] détournent certes [les hommes] du droit chemin, tandis que ceux-ci s'estiment être bien guidés."},{"n":4363,"s":43,"a":38,"t":"Lorsque cet [homme] vient à Nous, il dira [à son démon]: «Hélas! Que n'y a-t-il entre toi et moi la distance entre les deux orients [l'Est et l'Ouest]» - Quel mauvais compagnon [que tu es]!"},{"n":4364,"s":43,"a":39,"t":"Il ne vous profitera point ce jour-là - du moment que vous avez été injustes - que vous soyez associés dans le châtiment."},{"n":4365,"s":43,"a":40,"t":"Est-ce donc toi qui fait entendre les sourds ou qui guide les aveugles et ceux qui sont dans un égarement évident?"},{"n":4366,"s":43,"a":41,"t":"Soit que Nous t'enlevons [te ferons mourir] et alors Nous Nous vengerons d'eux;"},{"n":4367,"s":43,"a":42,"t":"ou bien que Nous te ferons voir ce que Nous leur avons promis [le châtiment]; car Nous avons sur eux un pouvoir certain."},{"n":4368,"s":43,"a":43,"t":"Tiens fermement à ce qui t'a été révélé car tu es sur le droit chemin."},{"n":4369,"s":43,"a":44,"t":"C'est certainement un rappel [le Coran] pour toi et ton peuple. Et vous en serez interrogés."},{"n":4370,"s":43,"a":45,"t":"Et demande à ceux de Nos messagers que Nous avons envoyés avant toi, si Nous avons institué, en dehors du Tout Miséricordieux, des divinités à adorer?"},{"n":4371,"s":43,"a":46,"t":"Nous avons effectivement envoyé Moïse avec Nos miracles, à Pharaon et à ses notables. Il dit: «Je suis le Messager du Seigneur de l'univers»."},{"n":4372,"s":43,"a":47,"t":"Puis, lorsqu'il vint à eux avec Nos miracles, voilà qu'ils en rirent."},{"n":4373,"s":43,"a":48,"t":"Chaque miracle que Nous leur montrions était plus probant que son précédent. Et Nous les saisîmes par le châtiment, peut-être reviendront-ils [vers Nous]."},{"n":4374,"s":43,"a":49,"t":"Et ils dirent: «O magicien! Implore pour nous ton Seigneur au nom de l'engagement qu'Il a pris envers toi. Nous suivrons le droit chemin»."},{"n":4375,"s":43,"a":50,"t":"Puis quand Nous eûmes écarté d'eux le châtiment, voilà qu'ils violèrent leurs engagements."},{"n":4376,"s":43,"a":51,"t":"Et Pharaon fit une proclamation à son peuple et dit: «O mon peuple! Le royaume de Misr [l'Egypte] ne m'appartient-il pas ainsi que ces canaux qui coulent à mes pieds? N'observez-vous donc pas?"},{"n":4377,"s":43,"a":52,"t":"Ne suis-je pas meilleur que ce misérable qui sait à peine s'exprimer?"},{"n":4378,"s":43,"a":53,"t":"Pourquoi ne lui a-t-on pas lancé des bracelets d'or? Pourquoi les Anges ne l'ont-ils pas accompagné?»"},{"n":4379,"s":43,"a":54,"t":"Ainsi chercha-t-il à étourdir son peuple et ainsi lui obéirent-ils car ils étaient des gens pervers."},{"n":4380,"s":43,"a":55,"t":"Puis lorsqu'ils Nous eurent irrité, Nous Nous vengeâmes d'eux et les noyâmes tous."},{"n":4381,"s":43,"a":56,"t":"Nous fîmes d'eux un antécédant et un exemple [une leçon] pour la postérité."},{"n":4382,"s":43,"a":57,"t":"Quand on cite l'exemple du fils de Marie, ton peuple s'en détourne,"},{"n":4383,"s":43,"a":58,"t":"en disant: «Nos dieux sont-ils meilleurs, ou bien lui?» Ce n'est que par polémique qu'ils te le citent comme exemple. Ce sont plutôt des gens chicaniers."},{"n":4384,"s":43,"a":59,"t":"Il (Jésus) n'était qu'un Serviteur que Nous avions comblé de bienfaits et que Nous avions désigné en exemple aux Enfants d'Israël."},{"n":4385,"s":43,"a":60,"t":"Si Nous voulions, Nous ferions de vous des Anges qui vous succéderaient sur la terre."},{"n":4386,"s":43,"a":61,"t":"Il sera un signe au sujet de l'Heure. N'en doutez point. Et suivez-moi: voilà un droit chemin."},{"n":4387,"s":43,"a":62,"t":"Que le Diable ne vous détourne point! Car il est pour vous un ennemi déclaré."},{"n":4388,"s":43,"a":63,"t":"Et quand Jésus apporta les preuves, il dit: «Je suis venu à vous avec la sagesse et pour vous expliquer certains de vos sujets de désaccord. Craignez Allah donc et obéissez-moi."},{"n":4389,"s":43,"a":64,"t":"Allah est en vérité mon Seigneur et votre Seigneur. Adorez-Le donc. Voilà un droit chemin»."},{"n":4390,"s":43,"a":65,"t":"Mais les factions divergèrent entre elles. Malheur donc aux injustes du châtiment d'un jour douloureux!"},{"n":4391,"s":43,"a":66,"t":"Attendent-ils seulement que l'Heure leur vienne à l'improviste, sans qu'ils ne s'en rendent compte?"},{"n":4392,"s":43,"a":67,"t":"Les amis, ce jour-là, seront ennemis les uns des autres; excepté les pieux."},{"n":4393,"s":43,"a":68,"t":"«O Mes serviteurs! Vous ne devez avoir aucune crainte aujourd'hui; vous ne serez point affligés,"},{"n":4394,"s":43,"a":69,"t":"Ceux qui croient en Nos signes et sont musulmans,"},{"n":4395,"s":43,"a":70,"t":"«Entrez au Paradis, vous et vos épouses, vous y serez fêtés»."},{"n":4396,"s":43,"a":71,"t":"On fera circuler parmi eux des plats d'or et des coupes; et il y aura là [pour eux] tout ce que les âmes désirent et ce qui réjouit les yeux;» - et vous y demeurerez éternellement."},{"n":4397,"s":43,"a":72,"t":"Tel est le Paradis qu'on vous fait hériter pour ce que vous faisiez."},{"n":4398,"s":43,"a":73,"t":"Il y aura là pour vous beaucoup de fruits dont vous mangerez»."},{"n":4399,"s":43,"a":74,"t":"Quant aux criminels, ils demeureront éternellement dans le châtiment de l'Enfer,"},{"n":4400,"s":43,"a":75,"t":"qui ne sera jamais interrompu pour eux et où ils seront en désespoir."},{"n":4401,"s":43,"a":76,"t":"Nous ne leur avons fait aucun tort, mais c'étaient eux les injustes."},{"n":4402,"s":43,"a":77,"t":"et ils crieront: «O Mâlik! Que ton Seigneur nous achève!» Il dira: «En vérité, vous êtes pour y demeurer [éternellement]»!"},{"n":4403,"s":43,"a":78,"t":"«Certes, Nous vous avions apporté la Vérité; mais la plupart d'entre vous détestaient la Vérité»."},{"n":4404,"s":43,"a":79,"t":"Ont-ils pris quelque décision [entre eux]? Car c'est Nous qui décidons!"},{"n":4405,"s":43,"a":80,"t":"Ou bien escomptent-ils que Nous n'entendons pas leur secret ni leurs délibérations? Mais si! Nos Anges prennent note auprès d'eux."},{"n":4406,"s":43,"a":81,"t":"Dis: «Si le Tout Miséricordieux avait un enfant, alors je serais le premier à l'adorer»."},{"n":4407,"s":43,"a":82,"t":"Gloire au Seigneur des cieux et de la terre, Seigneur du Trône; Il transcende ce qu'ils décrivent."},{"n":4408,"s":43,"a":83,"t":"Laisse-les donc s'enfoncer dans leur fausseté et s'amuser jusqu'à ce qu'ils rencontrent le jour qui leur est promis."},{"n":4409,"s":43,"a":84,"t":"C'est Lui qui est Dieu dans le ciel et Dieu sur terre; et c'est Lui le Sage, l'Omniscient!"},{"n":4410,"s":43,"a":85,"t":"Et béni soit Celui à qui appartient la souveraineté des cieux et de la terre et de ce qui est entre eux. Il détient la science de l'Heure. Et c'est vers Lui que vous serez ramenés."},{"n":4411,"s":43,"a":86,"t":"Et ceux qu'ils invoquent en dehors de Lui n'ont aucun pouvoir d'intercession, à l'exception de ceux qui auront témoigné de la vérité en pleine connaissance de cause."},{"n":4412,"s":43,"a":87,"t":"Et si tu leur demandes qui les a créés, ils diront très certainement: «Allah». Comment se fait-il donc qu'ils se détournent?"},{"n":4413,"s":43,"a":88,"t":"Et sa parole (la parole du Prophète à Allah): «Seigneur, ce sont là des gens qui ne croient pas»."},{"n":4414,"s":43,"a":89,"t":"Et bien, éloigne-toi d'eux (pardonne-leur); et dis: «Salut!» Car ils sauront bientôt."},{"n":4415,"s":44,"a":1,"t":"H'â, Mîm."},{"n":4416,"s":44,"a":2,"t":"Par le Livre (le Coran) explicite."},{"n":4417,"s":44,"a":3,"t":"Nous l'avons fait descendre en une nuit bénie, Nous sommes en vérité Celui qui avertit,"},{"n":4418,"s":44,"a":4,"t":"durant laquelle est décidé tout ordre sage,"},{"n":4419,"s":44,"a":5,"t":"c'est là un commandement venant de Nous. C'est Nous qui envoyons [les Messagers],"},{"n":4420,"s":44,"a":6,"t":"à titre de miséricorde de la part de ton Seigneur, car c'est Lui l'Audient, l'Omniscient,"},{"n":4421,"s":44,"a":7,"t":"Seigneur des cieux et de la terre et de ce qui est entre eux, si seulement vous pouviez en avoir la conviction."},{"n":4422,"s":44,"a":8,"t":"Point de divinité à part Lui. Il donne la vie et donne la mort, et Il est votre Seigneur et le Seigneur de vos premiers ancêtres."},{"n":4423,"s":44,"a":9,"t":"Mais ces gens-là, dans le doute, s'amusent."},{"n":4424,"s":44,"a":10,"t":"Eh bien, attends le jour où le ciel apportera une fumée visible"},{"n":4425,"s":44,"a":11,"t":"qui couvrira les gens. Ce sera un châtiment douloureux."},{"n":4426,"s":44,"a":12,"t":"«Seigneur, éloigne de nous le châtiment. Car, [à présent] nous croyons»."},{"n":4427,"s":44,"a":13,"t":"D'où leur vient cette prise de conscience alors qu'un Messager explicite leur est déjà venu,"},{"n":4428,"s":44,"a":14,"t":"Puis ils s'en détournèrent en disant: «C'est un homme instruit [par d'autres], un possédé»."},{"n":4429,"s":44,"a":15,"t":"Nous dissiperons le châtiment pour peu de temps; car vous récidiverez."},{"n":4430,"s":44,"a":16,"t":"Le jour où Nous userons de la plus grande violence et Nous Nous vengerons."},{"n":4431,"s":44,"a":17,"t":"Et avant eux Nous avons déjà éprouvé le peuple de Pharaon, quand un noble Messager leur était venu,"},{"n":4432,"s":44,"a":18,"t":"[leur disant]: «Livrez-moi les serviteurs d'Allah! Je suis pour vous un Messager digne de confiance."},{"n":4433,"s":44,"a":19,"t":"Ne vous montrez pas hautains vis-à-vis d'Allah, car je vous apporte une preuve évidente."},{"n":4434,"s":44,"a":20,"t":"Et je cherche protection auprès de mon Seigneur et votre Seigneur, pour que vous ne me lapidiez pas."},{"n":4435,"s":44,"a":21,"t":"Si vous ne voulez pas croire en moi, éloignez-vous de moi»."},{"n":4436,"s":44,"a":22,"t":"Il invoqua alors son Seigneur: «Ce sont des gens criminels»."},{"n":4437,"s":44,"a":23,"t":"«Voyage de nuit avec Mes serviteurs; vous serez poursuivis."},{"n":4438,"s":44,"a":24,"t":"Laisse la mer calme; [telle que tu l'as franchie] ce sont, des armées [vouées] à la noyade»."},{"n":4439,"s":44,"a":25,"t":"Que de jardins et de sources ils laissèrent [derrière eux]"},{"n":4440,"s":44,"a":26,"t":"que de champs et de superbes résidences,"},{"n":4441,"s":44,"a":27,"t":"que de délices au sein desquels ils se réjouissaient."},{"n":4442,"s":44,"a":28,"t":"Il en fut ainsi et Nous fîmes qu'un autre peuple en hérita."},{"n":4443,"s":44,"a":29,"t":"Ni le ciel ni la terre ne les pleurèrent et ils n'eurent aucun délai."},{"n":4444,"s":44,"a":30,"t":"Et certes, Nous sauvâmes les Enfants d'Israël du châtiment avilissant"},{"n":4445,"s":44,"a":31,"t":"de Pharaon qui était hautain et outrancier."},{"n":4446,"s":44,"a":32,"t":"A bon escient Nous les choisîmes parmi tous les peuples de l'univers,"},{"n":4447,"s":44,"a":33,"t":"et leur apportâmes des miracles de quoi les mettre manifestement à l'épreuve."},{"n":4448,"s":44,"a":34,"t":"Ceux-là (les Mecquois) disent:"},{"n":4449,"s":44,"a":35,"t":"«Il n'y a pour nous qu'une mort, la première. Et nous ne serons pas ressuscités."},{"n":4450,"s":44,"a":36,"t":"Faites donc revenir nos ancêtres, si vous êtes véridiques»."},{"n":4451,"s":44,"a":37,"t":"Sont-ils les meilleurs ou le peuple de Tubba' et ceux qui les ont précédés? Nous les avons fait périr parce que vraiment ils étaient criminels."},{"n":4452,"s":44,"a":38,"t":"Ce n'est pas par divertissement que Nous avons créé les cieux et la terre et ce qui est entre eux."},{"n":4453,"s":44,"a":39,"t":"Nous ne les avons créés qu'en toute vérité. Mais la plupart d'entre eux ne savent pas."},{"n":4454,"s":44,"a":40,"t":"En vérité, le Jour de la Décision sera leur rendez-vous à tous,"},{"n":4455,"s":44,"a":41,"t":"le jour où un allié ne sera d'aucune utilité à un [autre] allié; et ils ne seront point secourus non plus,"},{"n":4456,"s":44,"a":42,"t":"sauf celui à qui Allah fera miséricorde. Car c'est Lui, le Puissant, le Très Miséricordieux."},{"n":4457,"s":44,"a":43,"t":"Certes l'arbre de Zakkûm"},{"n":4458,"s":44,"a":44,"t":"sera la nourriture du grand pécheur."},{"n":4459,"s":44,"a":45,"t":"Comme du métal en fusion; il bouillonnera dans les ventres"},{"n":4460,"s":44,"a":46,"t":"comme le bouillonnement de l'eau surchauffée."},{"n":4461,"s":44,"a":47,"t":"Qu'on le saisisse et qu'on l'emporte en plein dans la fournaise;"},{"n":4462,"s":44,"a":48,"t":"qu'on verse ensuite sur sa tête de l'eau bouillante comme châtiment."},{"n":4463,"s":44,"a":49,"t":"Goûte! Toi [qui prétendait être] le puissant, le noble."},{"n":4464,"s":44,"a":50,"t":"Voilà ce dont vous doutiez."},{"n":4465,"s":44,"a":51,"t":"Les pieux seront dans une demeure sûre,"},{"n":4466,"s":44,"a":52,"t":"parmi des jardins et des sources,"},{"n":4467,"s":44,"a":53,"t":"Ils porteront des vêtements de satin et de brocart et seront placés face à face."},{"n":4468,"s":44,"a":54,"t":"C'est ainsi! Et Nous leur donnerons pour épouses des houris aux grands yeux."},{"n":4469,"s":44,"a":55,"t":"Ils y demanderont en toute quiétude toutes sortes de fruits."},{"n":4470,"s":44,"a":56,"t":"Ils n'y goûteront pas à la mort sauf leur mort première. Et [Allah] les protègera du châtiment de la Fournaise,"},{"n":4471,"s":44,"a":57,"t":"c'est là une grâce de ton Seigneur. Et c'est là l'énorme succès."},{"n":4472,"s":44,"a":58,"t":"Nous ne l'avons facilité dans ta langue, qu'afin qu'ils se rappellent!"},{"n":4473,"s":44,"a":59,"t":"Attends donc. Eux aussi attendent."},{"n":4474,"s":45,"a":1,"t":"H'â, Mîm."},{"n":4475,"s":45,"a":2,"t":"La révélation du Livre émane d'Allah, le Puissant, le Sage."},{"n":4476,"s":45,"a":3,"t":"Il y a certes dans les cieux et la terre des preuves pour les croyants."},{"n":4477,"s":45,"a":4,"t":"Et dans votre propre création, et dans ce qu'Il dissémine comme animaux, il y a des signes pour des gens qui croient avec certitude."},{"n":4478,"s":45,"a":5,"t":"De même dans l'alternance de la nuit et du jour, et dans ce qu'Allah fait descendre du ciel comme subsistance [pluie] par laquelle Il redonne la vie à la terre une fois morte, et dans la distribution des vents, il y a des signes pour des gens qui raisonnent."},{"n":4479,"s":45,"a":6,"t":"Voilà les versets d'Allah que Nous te récitons en toute vérité. Alors dans quelle parole croiront-ils après [la parole] d'Allah et après Ses signes?"},{"n":4480,"s":45,"a":7,"t":"Malheur à tout grand imposteur pécheur!"},{"n":4481,"s":45,"a":8,"t":"Il entend les versets d'Allah qu'on lui récite puis persiste dans son orgueil, comme s'il ne les avait jamais entendus. Annonce-lui donc un châtiment douloureux."},{"n":4482,"s":45,"a":9,"t":"S'il a connaissance de quelques-uns de Nos versets, il les tourne en dérision. Ceux-là auront un châtiment avilissant:"},{"n":4483,"s":45,"a":10,"t":"l'Enfer est à leurs trousses. Ce qu'ils auront acquis ne leur servira à rien, ni ce qu'ils auront pris comme protecteurs, en dehors d'Allah. Ils auront un énorme châtiment."},{"n":4484,"s":45,"a":11,"t":"Ceci [le Coran] est un guide. Et ceux qui récusent les versets de leur Seigneur auront le supplice d'un châtiment douloureux."},{"n":4485,"s":45,"a":12,"t":"Allah c'est Lui qui vous a assujetti la mer, afin que les vaisseaux y voguent, par Son ordre, et que vous alliez en quête de sa grâce afin que vous soyez reconnaissants."},{"n":4486,"s":45,"a":13,"t":"Et Il vous a assujetti tout ce qui est dans les cieux et sur la terre, le tout venant de Lui. Il y a là des signes pour des gens qui réfléchissent."},{"n":4487,"s":45,"a":14,"t":"Dis à ceux qui ont cru de pardonner à ceux qui n'espèrent pas les jours d'Allah afin qu'Il rétribue [chaque] peuple pour les acquis qu'ils faisaient."},{"n":4488,"s":45,"a":15,"t":"Quiconque fait le bien, le fait pour lui-même; et quiconque agit mal, agit contre lui-même. Puis vous serez ramenés vers votre Seigneur,"},{"n":4489,"s":45,"a":16,"t":"Nous avons effectivement apporté aux Enfants d'Israël le Livre, la sagesse, la prophétie, et leur avons attribué de bonnes choses, et les préférâmes aux autres humains [leurs contemporains];"},{"n":4490,"s":45,"a":17,"t":"Et Nous leur avons apporté des preuves évidentes de l'Ordre. Ils ne divergèrent qu'après que la science leur fut venue par agressivité entre eux. Ton Seigneur décidera parmi eux, au Jour de la Résurrection, sur ce en quoi ils divergeaient."},{"n":4491,"s":45,"a":18,"t":"Puis Nous t'avons mis sur la voie de l'Ordre [une religion claire et parfaite]. Suis-la donc et ne suis pas les passions de ceux qui ne savent pas."},{"n":4492,"s":45,"a":19,"t":"Ils ne te seront d'aucune utilité vis-à-vis d'Allah. Les injustes sont vraiment alliés les uns des autres; tandis qu'Allah est le Protecteur des pieux."},{"n":4493,"s":45,"a":20,"t":"Ceci [le Coran] constitue pour les hommes une source de clarté, un guide et une miséricorde pour des gens qui croient avec certitude."},{"n":4494,"s":45,"a":21,"t":"Ceux qui commettent des mauvaises actions comptent-ils que Nous allons les traiter comme ceux qui croient et accomplissent les bonnes œuvres, dans leur vie et dans leur mort? Comme ils jugent mal!"},{"n":4495,"s":45,"a":22,"t":"Et Allah a créé les cieux et la terre en toute vérité et afin que chaque âme soit rétribuée selon ce qu'elle a acquis. Ils ne seront cependant pas lésés."},{"n":4496,"s":45,"a":23,"t":"Vois-tu celui qui prend sa passion pour sa propre divinité? Et Allah l'égare sciemment et scelle son ouïe et son cœur et étend un voile sur sa vue. Qui donc peut le guider après Allah? Ne vous rappelez-vous donc pas?"},{"n":4497,"s":45,"a":24,"t":"Et ils dirent: «Il n'y a pour nous que la vie d'ici-bas: nous mourons et nous vivons et seul le temps nous fait périr». Ils n'ont de cela aucune connaissance: ils ne font qu'émettre des conjectures."},{"n":4498,"s":45,"a":25,"t":"Et quand on leur récite Nos versets bien clairs, leur seul argument est de dire: «Faites revenir nos ancêtres si vous êtes véridiques»."},{"n":4499,"s":45,"a":26,"t":"Dis: «Allah vous donne la vie puis Il vous donne la mort. Ensuite Il vous réunira le Jour de la Résurrection, il n'y a pas de doute à ce sujet, mais la plupart des gens ne savent pas."},{"n":4500,"s":45,"a":27,"t":"A Allah appartient le royaume des cieux et de la terre. Et le jour où l'Heure arrivera, ce jour-là, les imposteurs seront perdus."},{"n":4501,"s":45,"a":28,"t":"Et tu verras chaque communauté agenouillée. Chaque communauté sera appelée vers son livre. On vous rétribuera aujourd'hui selon ce que vous œuvriez."},{"n":4502,"s":45,"a":29,"t":"Voilà Notre Livre. Il parle de vous en toute vérité car Nous enregistrions [tout] ce que vous faisiez»."},{"n":4503,"s":45,"a":30,"t":"Ceux qui ont cru et fait de bonnes œuvres, leur Seigneur les fera entrer dans Sa miséricorde. Voilà le succès évident."},{"n":4504,"s":45,"a":31,"t":"Et quant à ceux qui ont mécru [il sera dit]: «Mes versets ne vous étaient-ils pas récités? Mais vous vous enfliez d'orgueil et vous étiez des gens criminels»."},{"n":4505,"s":45,"a":32,"t":"Et quand on disait: «La promesse d'Allah est vérité; et l'Heure n'est pas l'objet d'un doute», vous disiez: «Nous ne savons pas ce que c'est que l'Heure; et nous ne faisions à son sujet que de simples conjectures et nous ne sommes pas convaincus [qu'elle arrivera]."},{"n":4506,"s":45,"a":33,"t":"Et leur apparaîtra [la laideur] de leurs mauvaises actions. Et ce dont ils se moquaient les cernera."},{"n":4507,"s":45,"a":34,"t":"Et on leur dira: «Aujourd'hui Nous vous oublions comme vous avez oublié la rencontre de votre jour que voici. Votre refuge est le Feu; et vous n'aurez point de secoureurs."},{"n":4508,"s":45,"a":35,"t":"Cela parce que vous preniez en raillerie les versets d'Allah et que la vie d'ici-bas vous trompait». Ce jour-là on ne les en fera pas sortir et on ne les excusera pas non plus."},{"n":4509,"s":45,"a":36,"t":"Louange à Allah, Seigneur des cieux et Seigneur de la terre: Seigneur de l'univers."},{"n":4510,"s":45,"a":37,"t":"Et à Lui la grandeur dans les cieux et la terre. Et c'est Lui le Puissant, le Sage."},{"n":4511,"s":46,"a":1,"t":"H'â, Mîm."},{"n":4512,"s":46,"a":2,"t":"La révélation du Livre émane d'Allah, le Puissant, le Sage."},{"n":4513,"s":46,"a":3,"t":"Nous n'avons créé les cieux et la terre et ce qui est entre eux qu'en toute vérité et [pour] un terme fixé. Ceux qui ont mécru se détournent de ce dont ils ont été avertis."},{"n":4514,"s":46,"a":4,"t":"Dis: «Que pensez-vous de ceux que vous invoquez en dehors d'Allah? Montrez-moi donc ce qu'ils ont créé de la terre! Ou ont-ils dans les cieux une participation avec Dieu? Apportez-moi un Livre antérieur à celui-ci (le Coran) ou même un vestige d'une science, si vous êtes véridiques»."},{"n":4515,"s":46,"a":5,"t":"Et qui est plus égaré que celui qui invoque en dehors d'Allah, et que la vie ne saura lui répondre jusqu'au Jour de la Résurrection? Et elles [leurs divinités] sont indifférentes à leur invocation."},{"n":4516,"s":46,"a":6,"t":"Et quand les gens seront rassemblés [pour le Jugement] elles seront leurs ennemies et nieront leur adoration [pour elles]."},{"n":4517,"s":46,"a":7,"t":"Et quand on leur récite Nos versets bien clairs, ceux qui ont mécru disent à propos de la vérité, une fois venue à eux: «C'est de la magie manifeste»."},{"n":4518,"s":46,"a":8,"t":"Ou bien ils disent: «Il l'a inventé!» Dis: «Si je l'ai inventé alors vous ne pourrez rien pour moi contre [la punition] d'Allah. Il sait parfaitement ce que vous propagez (en calomnies contre le Coran): Allah est suffisant comme témoin entre moi et vous. Et c'est Lui le Pardonneur, le Très Miséricordieux»."},{"n":4519,"s":46,"a":9,"t":"Dis: «Je ne suis pas une innovation parmi les messagers; et je ne sais pas ce que l'on fera de moi, ni de vous. Je ne fais que suivre ce qui m'est révélé; et je ne suis qu'un avertisseur clair»."},{"n":4520,"s":46,"a":10,"t":"Dis: «Que direz-vous si [cette révélation s'avère] venir d'Allah et que vous n'y croyez pas qu'un témoin parmi les fils d'Israël en atteste la conformité [au Pentateuque] et y croit pendant que vous, vous le repoussez avec orgueil... En vérité Allah ne guide pas les gens injustes!»"},{"n":4521,"s":46,"a":11,"t":"Et ceux qui ont mécru dirent à ceux qui ont cru: «Si ceci était un bien, ils (les pauvres) ne nous y auraient pas devancés». Et comme ils ne se seront pas laissés guider par lui ils diront: «Ce n'est qu'un vieux mensonge!»"},{"n":4522,"s":46,"a":12,"t":"Et avant lui, il y avait le Livre de Moïse, comme guide et comme miséricorde. Et ceci est [un Livre] confirmateur, en langue arabe, pour avertir ceux qui font du tort et pour faire la bonne annonce aux bienfaisants"},{"n":4523,"s":46,"a":13,"t":"Ceux qui disent: «Notre Seigneur est Allah» et qui ensuite se tiennent sur le droit chemin. Ils ne doivent avoir aucune crainte et ne seront point affligés."},{"n":4524,"s":46,"a":14,"t":"Ceux-là sont les gens du Paradis où ils demeureront éternellement, en récompense de ce qu'ils faisaient."},{"n":4525,"s":46,"a":15,"t":"Et Nous avons enjoint à l'homme de la bonté envers ses père et mère: sa mère l'a péniblement porté et en a péniblement accouché; et sa gestation et sevrage durent trente mois; puis quand il atteint ses pleines forces et atteint quarante ans, il dit: «O Seigneur! Inspire-moi pour que je rende grâce au bienfait dont Tu m'as comblé ainsi qu'à mes père et mère, et pour que je fasse une bonne œuvre que Tu agrées. Et fais que ma postérité soit de moralité saine. Je me repens à Toi et je suis du nombre des Soumis»."},{"n":4526,"s":46,"a":16,"t":"Ce sont ceux-là dont Nous acceptons le meilleur de ce qu'ils œuvrent et passons sur leurs méfaits, (ils seront) parmi les gens du Paradis, selon la promesse véridique qui leur était faite."},{"n":4527,"s":46,"a":17,"t":"Quant à celui qui dit à ses père et mère: «Fi de vous deux! Me promettez-vous qu'on me fera sortir de terre alors que des générations avant moi ont passé?» Et les deux, implorant le secours d'Allah, [lui dirent]: «Malheur à toi! Crois. Car la promesse d'Allah est véridique». Mais il (répond): «Ce ne sont que des contes d'Anciens»."},{"n":4528,"s":46,"a":18,"t":"Ce sont ceux-là qui ont mérité la sentence [prescrite] en même temps que des communautés déjà passées avant eux parmi les djinns et les hommes. Ils étaient réellement perdants."},{"n":4529,"s":46,"a":19,"t":"Et il y a des rangs [de mérite] pour chacun, selon ce qu'ils ont fait afin qu'Allah leur attribue la pleine récompense de leurs œuvres; et ils ne seront point lésés."},{"n":4530,"s":46,"a":20,"t":"Et le jour où ceux qui ont mécru seront présentés au Feu (il leur sera dit): «Vous avez dissipé vos [biens] excellents et vous en avez joui pleinement durant votre vie sur terre: on vous rétribue donc aujourd'hui du châtiment avilissant, pour l'orgueil dont vous vous enfliez injustement sur terre, et pour votre perversité."},{"n":4531,"s":46,"a":21,"t":"Et rappelle-toi le frère des 'Aad (Hûd) quand il avertit son peuple à Al-Ahqâf - alors qu'avant et après lui, des avertisseurs sont passés - [en disant]: «N'adorez qu'Allah. Je crains pour vous le châtiment d'un jour terrible»."},{"n":4532,"s":46,"a":22,"t":"Ils dirent: «Es-tu venu à nous pour nous détourner de nos divinités? Eh bien, apporte-nous ce que tu nous promets si tu es du nombre des véridiques»."},{"n":4533,"s":46,"a":23,"t":"Il dit: «La science n'est qu'auprès d'Allah. Je vous transmets cependant le message avec lequel j'ai été envoyé. Mais je vois que vous êtes des gens ignorants»."},{"n":4534,"s":46,"a":24,"t":"Puis, voyant un nuage se dirigeant vers leurs vallées ils dirent; «Voici un nuage qui nous apporte de la pluie». Au contraire! c'est cela même que vous cherchiez à hâter: C'est un vent qui contient un châtiment douloureux,"},{"n":4535,"s":46,"a":25,"t":"détruisant tout, par le commandement de son Seigneur. Puis le lendemain on ne voyait plus que leurs demeures. Ainsi rétribuons-Nous les gens criminels."},{"n":4536,"s":46,"a":26,"t":"En effet, Nous les avions consolidés dans des positions que Nous ne vous avons pas données. Et Nous leur avions assigné une ouïe, des yeux et des cœurs, mais ni leur ouïe, ni leurs yeux, ni leurs cœurs ne leur ont profité en quoi que ce soit, parce qu'ils niaient les signes d'Allah. Et ce dont ils se moquaient les cerna."},{"n":4537,"s":46,"a":27,"t":"Nous avons assurément fait périr les cités autour de vous; et Nous avons diversifié les signes afin qu'ils reviennent (de leur mécréance)."},{"n":4538,"s":46,"a":28,"t":"Pourquoi donc ne les secourent pas, ceux qu'ils avaient pris, en dehors d'Allah, comme divinités pour [soi-disant] les rapprocher de Lui? Ceux-ci, au contraire, les abandonnèrent; telle est leur imposture et voilà ce qu'ils inventaient comme mensonges."},{"n":4539,"s":46,"a":29,"t":"(Rappelle-toi) lorsque Nous dirigeâmes vers toi une troupe de djinns pour qu'ils écoutent le Coran. Quand ils assistèrent [à sa lecture] ils dirent: «Ecoutez attentivement»... Puis, quand ce fut terminé, ils retournèrent à leur peuple en avertisseurs"},{"n":4540,"s":46,"a":30,"t":"Ils dirent: «O notre peuple! Nous venons d'entendre un Livre qui a été descendu après Moïse, confirmant ce qui l'a précédé. Il guide vers la vérité et vers un chemin droit."},{"n":4541,"s":46,"a":31,"t":"O notre peuple! Répondez au prédicateur d'Allah et croyez en lui. Il [Allah] vous pardonnera une partie de vos péchés et vous protègera contre un châtiment douloureux."},{"n":4542,"s":46,"a":32,"t":"Et quiconque ne répond pas au prédicateur d'Allah ne saura échapper au pouvoir [d'Allah] sur terre. Et il n'aura pas de protecteurs en dehors de Lui. Ceux-là sont dans un égarement évident."},{"n":4543,"s":46,"a":33,"t":"Ne voient-ils pas qu'Allah qui a créé les cieux et la terre, et qui n'a pas été fatigué par leur création, est capable en vérité de redonner la vie aux morts? Mais si. Il est certes Omnipotent."},{"n":4544,"s":46,"a":34,"t":"Et le jour où seront présentés au Feu ceux qui ont mécru (on leur dira): «Ceci n'est-il pas la vérité?» Ils diront: «Mais si, par notre Seigneur». Il dira: «Eh bien, goûtez le châtiment pour votre mécréance»."},{"n":4545,"s":46,"a":35,"t":"Endure (Muhammad) donc, comme ont enduré les messagers doués de fermeté; et ne te montre pas trop pressé de les voir subir [leur châtiment]. Le jour où ils verront ce qui leur est promis, il leur semblera qu'ils n'étaient restés [sur terre] qu'une heure d'un jour. Voilà une communication. Qui sera donc anéanti sinon les gens pervers?"},{"n":4546,"s":47,"a":1,"t":"Ceux qui ont mécru et obstrué le chemin d'Allah, Il a rendu leurs œuvres vaines."},{"n":4547,"s":47,"a":2,"t":"Et ceux qui ont cru et accompli de bonnes œuvres et ont cru en ce qui a été descendu sur Muhammad - et c'est la vérité venant de leur Seigneur - Il leur efface leurs méfaits et améliore leur condition."},{"n":4548,"s":47,"a":3,"t":"Il en est ainsi parce que ceux qui ont mécru ont suivi le Faux et que ceux qui ont cru ont suivi la Vérité émanant de leur Seigneur. C'est ainsi qu'Allah propose leurs exemples aux gens."},{"n":4549,"s":47,"a":4,"t":"Lorsque vous rencontrez (au combat) ceux qui ont mécru frappez-en les cous. Puis, quand vous les avez dominés, enchaînez-les solidement. Ensuite, c'est soit la libération gratuite, soit la rançon, jusqu'à ce que la guerre dépose ses fardeaux. Il en est ainsi, car si Allah voulait, Il se vengerait Lui-même contre eux, mais c'est pour vous éprouver les uns par les autres. Et ceux qui seront tués dans le chemin d'Allah, Il ne rendra jamais vaines leurs actions."},{"n":4550,"s":47,"a":5,"t":"Il les guidera et améliorera leur condition."},{"n":4551,"s":47,"a":6,"t":"et les fera entrer au Paradis qu'Il leur aura fait connaître."},{"n":4552,"s":47,"a":7,"t":"O vous qui croyez! si vous faites triompher (la cause d') Allah, Il vous fera triompher et raffermira vos pas."},{"n":4553,"s":47,"a":8,"t":"Et quant à ceux qui ont mécru, il y aura un malheur pour eux, et Il rendra leurs œuvres vaines."},{"n":4554,"s":47,"a":9,"t":"C'est parce qu'ils ont de la répulsion pour ce qu'Allah a fait descendre. Il a rendu donc vaines leurs œuvres."},{"n":4555,"s":47,"a":10,"t":"N'ont-il pas parcouru la terre pour voir ce qu'il est advenu de leurs prédécesseurs? Allah les a détruits. Pareilles fins sont réservées aux mécréants."},{"n":4556,"s":47,"a":11,"t":"C'est qu'Allah est vraiment le Protecteur de ceux qui ont cru; tandis que les mécréants n'ont pas de protecteur."},{"n":4557,"s":47,"a":12,"t":"Ceux qui croient et accomplissent de bonnes œuvres Allah les fera entrer dans des Jardins sous lesquels coulent les ruisseaux. Et ceux qui mécroient jouissent et mangent comme mangent les bestiaux; et le Feu sera leur lieu de séjour."},{"n":4558,"s":47,"a":13,"t":"Et que de cités, bien plus fortes que ta cité qui t'a expulsé, avons-Nous fait périr, et ils n'eurent point de secoureur."},{"n":4559,"s":47,"a":14,"t":"Est-ce que celui qui se base sur une preuve claire venant de son Seigneur est comparable à ceux dont on a embelli les mauvaises actions et qui ont suivi leurs propres passions."},{"n":4560,"s":47,"a":15,"t":"Voici la description du Paradis qui a été promis aux pieux: il y aura là des ruisseaux d'une eau jamais malodorante, et des ruisseaux d'un lait au goût inaltérable, et des ruisseaux d'un vin délicieux à boire, ainsi que des ruisseaux d'un miel purifié. Et il y a là, pour eux, des fruits de toutes sortes, ainsi qu'un pardon de la part de leur Seigneur. [Ceux-là] seront-ils pareils à ceux qui s'éternisent dans le Feu et qui sont abreuvés d'une eau bouillante qui leur déchire les entrailles?"},{"n":4561,"s":47,"a":16,"t":"Et il en est parmi eux qui t'écoutent. Une fois sortis de chez toi ils disent à ceux qui ont reçu la science: «Qu'a-t-il dit tout à l'heure?» Ce sont ceux-là dont Allah a scellé les cœurs et qui suivent leurs propres passions."},{"n":4562,"s":47,"a":17,"t":"Quant à ceux qui se mirent sur la bonne voie, Il les guida encore plus et leur inspira leur piété."},{"n":4563,"s":47,"a":18,"t":"Qu'est-ce qu'ils attendent sinon que l'Heure leur vienne à l'improviste? Or ses signes avant-coureurs sont certes déjà venus. Et comment pourront-ils se rappeler quand elle leur viendra (à l'improviste)?"},{"n":4564,"s":47,"a":19,"t":"Sache donc qu'en vérité il n'y a point de divinité à part Allah et implore le pardon pour ton péché, ainsi que pour les croyants et les croyantes. Allah connaît vos activités (sur terre) et votre lieu de repos (dans l'au-delà)."},{"n":4565,"s":47,"a":20,"t":"Ceux qui ont cru disent: «Ah! Si une Sourate descendait!» Puis, quand on fait descendre une Sourate explicite et qu'on y mentionne le combat, tu vois ceux qui ont une maladie au cœur te regarder du regard de celui qui s'évanouit devant la mort. Seraient bien préférables pour eux."},{"n":4566,"s":47,"a":21,"t":"une obéissance et une parole convenable. Puis, quand l'affaire est décidée, il serait mieux pour eux certes, de se montrer sincères vis-à-vis d'Allah."},{"n":4567,"s":47,"a":22,"t":"Si vous vous détournez, ne risquez-vous pas de semer la corruption sur terre et de rompre vos liens de parenté?"},{"n":4568,"s":47,"a":23,"t":"Ce sont ceux-là qu'Allah a maudits, a rendus sourds et a rendu leurs yeux aveugles."},{"n":4569,"s":47,"a":24,"t":"Ne méditent-ils pas sur le Coran? Ou y a-t-il des cadenas sur leurs cœurs?"},{"n":4570,"s":47,"a":25,"t":"Ceux qui sont revenus sur leurs pas après que le droit chemin leur a été clairement exposé, le Diable les a séduits et trompés."},{"n":4571,"s":47,"a":26,"t":"C'est parce qu'ils ont dit à ceux qui ont de la répulsion pour la révélation d'Allah: «Nous allons vous obéir dans certaines choses». Allah cependant connaît ce qu'ils cachent."},{"n":4572,"s":47,"a":27,"t":"Qu'adviendra-t-il d'eux quand les Anges les achèveront, frappant leurs faces et leurs dos?"},{"n":4573,"s":47,"a":28,"t":"Cela parce qu'ils ont suivi ce qui courrouce Allah, et qu'ils ont de la répulsion pour [ce qui attire] Son agrément. Il a donc rendu vaines leurs œuvres."},{"n":4574,"s":47,"a":29,"t":"Ou bien est-ce que ceux qui ont une maladie au cœur escomptent qu'Allah ne saura jamais faire apparaître leur haine?"},{"n":4575,"s":47,"a":30,"t":"Or, si Nous voulions Nous te les montrerions. Tu les reconnaîtrais certes à leurs traits; et tu les reconnaîtrais très certainement au ton de leur parler. Et Allah connaît bien vos actions."},{"n":4576,"s":47,"a":31,"t":"Nous vous éprouverons certes afin de distinguer ceux d'entre vous qui luttent [pour la cause d'Allah] et qui endurent, et afin d'éprouver [faire apparaître] vos nouvelles."},{"n":4577,"s":47,"a":32,"t":"Ceux qui ont mécru et obstrué le chemin d'Allah et se sont mis dans le clan opposé au Messager après que le droit chemin leur fut clairement exposé, ne sauront nuire à Allah en quoi que ce soit. Il rendra vaines leurs œuvres."},{"n":4578,"s":47,"a":33,"t":"O vous qui avez cru ! Obéissez à Allah, obéissez au Messager, et ne rendez pas vaines vos œuvres."},{"n":4579,"s":47,"a":34,"t":"Ceux qui ont mécru et obstrué le chemin d'Allah puis sont morts tout en étant mécréants, Allah ne leur pardonnera jamais."},{"n":4580,"s":47,"a":35,"t":"Ne faiblissez donc pas et n'appelez pas à la paix alors que vous êtes les plus hauts, qu'Allah est avec vous, et qu'Il ne vous frustrera jamais [du mérite] de vos œuvres."},{"n":4581,"s":47,"a":36,"t":"La vie présente n'est que jeu et amusement; alors que si vous croyez et craignez, [Allah], Il vous accordera vos récompenses et ne vous demandera pas vos biens."},{"n":4582,"s":47,"a":37,"t":"S'Il vous les demandait importunément, vous deviendriez avares et Il ferait apparaître vos haines."},{"n":4583,"s":47,"a":38,"t":"Vous voilà appelés à faire des dépenses dans le chemin d'Allah. Certains parmi vous se montrent avares. Quiconque cependant est avare, l'est à son détriment. Allah est le Suffisant à Soi-même alors que vous êtes les besogneux. Et si vous vous détournez, Il vous remplacera par un peuple autre que vous, et ils ne seront pas comme vous."},{"n":4584,"s":48,"a":1,"t":"En vérité Nous t'avons accordé une victoire éclatante,"},{"n":4585,"s":48,"a":2,"t":"afin qu'Allah te pardonne tes péchés, passés et futurs, qu'Il parachève sur toi Son bienfait et te guide sur une voie droite;"},{"n":4586,"s":48,"a":3,"t":"et qu'Allah te donne un puissant secours."},{"n":4587,"s":48,"a":4,"t":"C'est Lui qui a fait descendre la quiétude dans les cœurs des croyants afin qu'ils ajoutent une foi à leur foi. A Allah appartiennent les armées des cieux et de la terre; et Allah est Omniscient et Sage"},{"n":4588,"s":48,"a":5,"t":"afin qu'Il fasse entrer les croyants et les croyantes dans des Jardins sous lesquels coulent les ruisseaux où ils demeureront éternellement et afin de leur effacer leurs méfaits. Cela est auprès d'Allah un énorme succès."},{"n":4589,"s":48,"a":6,"t":"Et afin qu'Il châtie les hypocrites, hommes et femmes, et les associateurs et les associatrices, qui pensent du mal d'Allah. Qu'un mauvais sort tombe sur eux. Allah est courroucé contre eux, les a maudits, et leur a préparé l'Enfer. Quelle mauvaise destination!"},{"n":4590,"s":48,"a":7,"t":"A Allah appartiennent les armées des cieux et de la terre; et Allah est Puissant et Sage."},{"n":4591,"s":48,"a":8,"t":"Nous t'avons envoyé en tant que témoin, annonciateur de la bonne nouvelle et avertisseur,"},{"n":4592,"s":48,"a":9,"t":"pour que vous croyiez en Allah et en Son messager, que vous l'honoriez, reconnaissiez Sa dignité, et Le glorifiez matin et soir."},{"n":4593,"s":48,"a":10,"t":"Ceux qui te prêtent serment d'allégeance ne font que prêter serment à Allah: la main d'Allah est au-dessus de leurs mains. Quiconque viole le serment ne le viole qu'à son propre détriment; et quiconque remplit son engagement envers Allah, Il lui apportera bientôt une énorme récompense."},{"n":4594,"s":48,"a":11,"t":"Ceux des Bédouins qui ont été laissés en arrière te diront: «Nos biens et nos familles nous ont retenus: implore donc pour nous le pardon». Ils disent avec leurs langues ce qui n'est pas dans leurs cœurs. Dis: «Qui donc peut quelque chose pour vous auprès d'Allah s'Il veut vous faire du mal ou s'Il veut vous faire du bien? Mais Allah est Parfaitement Connaisseur de ce que vous œuvrez."},{"n":4595,"s":48,"a":12,"t":"Vous pensiez plutôt que le Messager et les croyants ne retourneraient jamais plus à leur famille. Et cela vous a été embelli dans vos cœurs; et vous avez eu de mauvaises pensées. Et vous fûtes des gens perdus»."},{"n":4596,"s":48,"a":13,"t":"Et quiconque ne croit pas en Allah et en Son messager... alors, pour les mécréants, Nous avons préparé une fournaise ardente."},{"n":4597,"s":48,"a":14,"t":"A Allah appartient la souveraineté des cieux et de la terre. Il pardonne à qui Il veut et châtie qui Il veut. Allah demeure cependant, Pardonneur et Miséricordieux."},{"n":4598,"s":48,"a":15,"t":"Ceux qui restèrent en arrière diront, quand vous vous dirigez vers le butin pour vous en emparer; «Laissez-nous vous suivre». Ils voudraient changer la parole d'Allah. Dis: «Jamais vous ne nous suivrez: ainsi Allah a déjà annoncé». Mais ils diront: «Vous êtes plutôt envieux à notre égard». Mais ils ne comprenaient en réalité que peu."},{"n":4599,"s":48,"a":16,"t":"Dis à ceux des Bédouins qui restèrent en arrière: «vous serez bientôt appelés contre des gens d'une force redoutable. Vous les combattrez à moins qu'ils n'embrassent l'Islam, si vous obéissez, Allah vous donnera une belle récompense, et si vous vous détournez comme vous vous êtes détournés auparavant, Il vous châtiera d'un châtiment douloureux»."},{"n":4600,"s":48,"a":17,"t":"Nul grief n'est à faire à l'aveugle, ni au boiteux ni au malade. Et quiconque obéit à Allah et à Son messager, Il le fera entrer dans des Jardins sous lesquels coulent les ruisseaux. Quiconque cependant se détourne, Il le châtiera d'un douloureux châtiment."},{"n":4601,"s":48,"a":18,"t":"Allah a très certainement agréé les croyants quand ils t'ont prêté le serment d'allégeance sous l'arbre. Il a su ce qu'il y avait dans leurs cœurs, et a fait descendre sur eux la quiétude, et Il les a récompensés par une victoire proche."},{"n":4602,"s":48,"a":19,"t":"ainsi qu'un abondant butin qu'ils ramasseront. Allah est Puissant et Sage."},{"n":4603,"s":48,"a":20,"t":"Allah vous a promis un abondant butin que vous prendrez et Il a hâté pour vous Celle-ci et repoussé de vous les mains des gens, afin que tout cela soit un signe pour les croyants et qu'Il vous guide dans un droit chemin;"},{"n":4604,"s":48,"a":21,"t":"Il vous promet un autre butin que vous ne seriez jamais capables de remporter et qu'Allah a embrassé en Sa puissance, car Allah est Omnipotent."},{"n":4605,"s":48,"a":22,"t":"Et si ceux qui ont mécru vous combattent, ils se détourneront, certes; puis ils ne trouveront ni allié ni secoureur."},{"n":4606,"s":48,"a":23,"t":"Telle est la règle d'Allah appliquée aux générations passées. Et tu ne trouveras jamais de changement à la règle d'Allah."},{"n":4607,"s":48,"a":24,"t":"C'est Lui qui, dans la vallée de la Mecque, a écarté leurs mains de vous, de même qu'Il a écarté vos mains d'eux, après vous avoir fait triompher sur eux. Et Allah voit parfaitement ce que vous œuvrez."},{"n":4608,"s":48,"a":25,"t":"Ce sont eux qui ont mécru et qui vous ont obstrué le chemin de la Mosquée Sacrée [et ont empêché] que les offrandes entravées parvinssent à leur lieu d'immolation. S'il n'y avait pas eu des hommes croyants et des femmes croyantes (parmi les Mecquois) que vous ne connaissiez pas et que vous auriez pu piétiner sans le savoir, vous rendant ainsi coupables d'une action répréhensible... [Tout cela s'est fait] pour qu'Allah fasse entrer qui Il veut dans Sa miséricorde. Et s'ils [les croyants] s'étaient signalés, Nous aurions certes châtié d'un châtiment douloureux ceux qui avaient mécru parmi [les Mecquois]."},{"n":4609,"s":48,"a":26,"t":"Quand ceux qui ont mécru eurent mis dans leurs cœurs la fureur, [la] fureur de l'ignorance... Puis Allah fit descendre Sa quiétude sur Son Messager ainsi que sur les croyants, et les obligea à une parole de piété, dont ils étaient les plus dignes et les plus proches. Allah est Omniscient."},{"n":4610,"s":48,"a":27,"t":"Allah a été véridique en la vision par laquelle Il annonça à Son messager en toute vérité: vous entrerez dans la Mosquée Sacrée si Allah veut, en toute sécurité, ayant rasé vos têtes ou coupé vos cheveux, sans aucune crainte. Il savait donc ce que vous ne saviez pas. Il a placé en deçà de cela (la trêve de Houdaybiya) une victoire proche."},{"n":4611,"s":48,"a":28,"t":"C'est Lui qui a envoyé Son messager avec la guidée et la religion de vérité [l'Islam] pour la faire triompher sur toute autre religion. Allah suffit comme témoin."},{"n":4612,"s":48,"a":29,"t":"Muhammad est le Messager d'Allah. Et ceux qui sont avec lui sont durs envers les mécréants, miséricordieux entre eux. Tu les vois inclinés, prosternés, recherchant d'Allah grâce et agrément. Leurs visages sont marqués par la trace laissée par la prosternation. Telle est leur image dans la Thora. Et l'image que l'on donne d'eux dans l'Evangile est celle d'une semence qui sort sa pousse, puis se raffermit, s'épaissit, et ensuite se dresse sur sa tige, à l'émerveillement des semeurs. [Allah] par eux [les croyants] remplit de dépit les mécréants. Allah promet à ceux d'entre eux qui croient et font de bonnes œuvres, un pardon et une énorme récompense."},{"n":4613,"s":49,"a":1,"t":"O vous qui avez cru! Ne devancez pas Allah et Son messager. Et craignez Allah. Allah est Audient et Omniscient."},{"n":4614,"s":49,"a":2,"t":"O vous qui avez cru! N'élevez pas vos voix au-dessus de la voix du Prophète, et ne haussez pas le ton en lui parlant, comme vous le haussez les uns avec les autres, sinon vos œuvres deviendraient vaines sans que vous vous en rendiez compte."},{"n":4615,"s":49,"a":3,"t":"Ceux qui auprès du Messager d'Allah baissent leurs voix sont ceux dont Allah a éprouvé les cœurs pour la piété. Ils auront un pardon et une énorme récompense."},{"n":4616,"s":49,"a":4,"t":"Ceux qui t'appellent à haute voix de derrière les appartements, la plupart d'entre eux ne raisonnent pas."},{"n":4617,"s":49,"a":5,"t":"Et s'ils patientaient jusqu'à ce que tu sortes à eux ce serait certes mieux pour eux. Allah cependant, est Pardonneur et Miséricordieux."},{"n":4618,"s":49,"a":6,"t":"O vous qui avez cru! Si un pervers vous apporte une nouvelle, voyez bien clair [de crainte] que par inadvertance vous ne portiez atteinte à des gens et que vous ne regrettiez par la suite ce que vous avez fait."},{"n":4619,"s":49,"a":7,"t":"Et sachez que le Messager d'Allah est parmi vous. S'il vous obéissait dans maintes affaires, vous seriez en difficultés. Mais Allah vous a fait aimer la foi et l'a embellie dans vos cœurs et vous a fait détester la mécréance, la perversité et la désobéissance. Ceux-là sont les bien dirigés,"},{"n":4620,"s":49,"a":8,"t":"c'est là en effet une grâce d'Allah et un bienfait. Allah est Omniscient et Sage."},{"n":4621,"s":49,"a":9,"t":"Et si deux groupes de croyants se combattent, faites la conciliation entre eux. Si l'un d'eux se rebelle contre l'autre, combattez le groupe qui se rebelle, jusqu'à ce qu'il se conforme à l'ordre d'Allah. Puis, s'il s'y conforme, réconciliez-les avec justice et soyez équitables car Allah aime les équitables."},{"n":4622,"s":49,"a":10,"t":"Les croyants ne sont que des frères. Etablissez la concorde entre vos frères, et craignez Allah, afin qu'on vous fasse miséricorde."},{"n":4623,"s":49,"a":11,"t":"O vous qui avez cru! Qu'un groupe ne se raille pas d'un autre groupe: ceux-ci sont peut-être meilleurs qu'eux. Et que des femmes ne se raillent pas d'autres femmes: celles-ci sont peut-être meilleures qu'elles. Ne vous dénigrez pas et ne vous lancez pas mutuellement des sobriquets (injurieux). Quel vilain mot que «perversion» lorsqu'on a déjà la foi. Et quiconque ne se repent pas... Ceux-là sont les injustes."},{"n":4624,"s":49,"a":12,"t":"O vous qui avez cru! Evitez de trop conjecturer [sur autrui] car une partie des conjectures est péché. Et n'espionnez pas; et ne médisez pas les uns des autres. L'un de vous aimerait-il manger la chair de son frère mort? (Non!) vous en aurez horreur. Et craignez Allah. Car Allah est Grand Accueillant au repentir, Très Miséricordieux."},{"n":4625,"s":49,"a":13,"t":"O hommes! Nous vous avons créés d'un mâle et d'une femelle, et Nous avons fait de vous des nations et des tribus, pour que vous vous entre-connaissiez. Le plus noble d'entre vous, auprès d'Allah, est le plus pieux. Allah est certes Omniscient et Grand Connaisseur."},{"n":4626,"s":49,"a":14,"t":"Les Bédouins ont dit: «Nous avons la foi». Dis: «Vous n'avez pas encore la foi. Dites plutôt: Nous nous sommes simplement soumis, car la foi n'a pas encore pénétré dans vos cœurs. Et si vous obéissez à Allah et à Son messager, Il ne vous fera rien perdre de vos œuvres». Allah est Pardonneur et Miséricordieux."},{"n":4627,"s":49,"a":15,"t":"Les vrais croyants sont seulement ceux qui croient en Allah et en Son messager, qui par la suite ne doutent point et qui luttent avec leurs biens et leurs personnes dans le chemin d'Allah. Ceux-là sont les véridiques."},{"n":4628,"s":49,"a":16,"t":"Dis: «Est-ce vous qui apprendrez à Allah votre religion, alors qu'Allah sait tout ce qui est dans les cieux et sur la terre?» Et Allah est Omniscient."},{"n":4629,"s":49,"a":17,"t":"Ils te rappellent leur conversion à l'Islam comme si c'était une faveur de leur part. Dis: «Ne me rappelez pas votre conversion à l'Islam comme une faveur. C'est tout au contraire une faveur dont Allah vous a comblés en vous dirigeant vers la foi, si toutefois vous êtes véridiques»."},{"n":4630,"s":49,"a":18,"t":"Allah connaît l'Inconnaissable des cieux et de la terre et Allah est Clairvoyant sur ce que vous faites."},{"n":4631,"s":50,"a":1,"t":"Qâf. Par le Coran glorieux!"},{"n":4632,"s":50,"a":2,"t":"Mais ils s'étonnent que l'un des leurs leur vint comme avertisseur; et les mécréants dirent: «Ceci est une chose étonnante."},{"n":4633,"s":50,"a":3,"t":"Quoi! Quand nous serons morts et réduits en poussière...? Ce serait revenir de loin!»"},{"n":4634,"s":50,"a":4,"t":"Certes, Nous savons ce que la terre rongera d'eux [de leurs corps]; et Nous avons un Livre où tout est conservé."},{"n":4635,"s":50,"a":5,"t":"Plutôt, ils traitent de mensonge la vérité qui leur est venue: les voilà donc dans une situation confuse."},{"n":4636,"s":50,"a":6,"t":"N'ont-ils donc pas observé le ciel au-dessus d'eux, comment Nous l'avons bâti et embelli; et comment il est sans fissures?"},{"n":4637,"s":50,"a":7,"t":"Et la terre, Nous l'avons étendue et Nous y avons enfoncé fermement des montagnes et y avons fait pousser toutes sortes de magnifiques couples de [végétaux],"},{"n":4638,"s":50,"a":8,"t":"à titre d'appel à la clairvoyance et un rappel pour tout serviteur repentant."},{"n":4639,"s":50,"a":9,"t":"Et Nous avons fait descendre du ciel une eau bénie, avec laquelle Nous avons fait pousser des jardins et le grain qu'on moissonne,"},{"n":4640,"s":50,"a":10,"t":"ainsi que les hauts palmiers aux régimes superposés,"},{"n":4641,"s":50,"a":11,"t":"comme subsistance pour les serviteurs. Et par elle (l'eau) Nous avons redonné la vie à une contrée morte. Ainsi se fera la résurrection."},{"n":4642,"s":50,"a":12,"t":"Avant eux, le peuple de Noé, les gens d'Ar-Rass et les Thamûd crièrent au mensonge,"},{"n":4643,"s":50,"a":13,"t":"de même que les 'Aad et Pharaon et les frères de Lot,"},{"n":4644,"s":50,"a":14,"t":"et les gens d'Al-Aykah et le peuple de Tubba'. Tous traitèrent les Messagers de menteurs. C'est ainsi que Ma menace se justifia."},{"n":4645,"s":50,"a":15,"t":"Quoi? Avons-Nous été fatigué par la première création? Mais ils sont dans la confusion [au sujet] d'une création nouvelle."},{"n":4646,"s":50,"a":16,"t":"Nous avons effectivement créé l'homme et Nous savons ce que son âme lui suggère et Nous sommes plus près de lui que sa veine jugulaire"},{"n":4647,"s":50,"a":17,"t":"quand les deux recueillants, assis à droite et à gauche, recueillent."},{"n":4648,"s":50,"a":18,"t":"Il ne prononce pas une parole sans avoir auprès de lui un observateur prêt à l'inscrire."},{"n":4649,"s":50,"a":19,"t":"L'agonie de la mort fait apparaître la vérité: «Voilà ce dont tu t'écartais»."},{"n":4650,"s":50,"a":20,"t":"Et l'on soufflera dans la Trompe: Voilà le jour de la Menace."},{"n":4651,"s":50,"a":21,"t":"Alors chaque âme viendra accompagnée d'un conducteur et d'un témoin."},{"n":4652,"s":50,"a":22,"t":"«Tu restais indifférent à cela. Et bien, Nous ôtons ton voile; ta vue est perçante aujourd'hui."},{"n":4653,"s":50,"a":23,"t":"Et son compagnon dira: «Voilà ce qui est avec moi, tout prêt»."},{"n":4654,"s":50,"a":24,"t":"«Vous deux, jetez dans l'Enfer tout mécréant endurci et rebelle,"},{"n":4655,"s":50,"a":25,"t":"acharné à empêcher le bien, transgresseur, douteur,"},{"n":4656,"s":50,"a":26,"t":"celui qui plaçait à côté d'Allah une autre divinité. Jetez-le donc dans le dur châtiment»."},{"n":4657,"s":50,"a":27,"t":"Son camarade (le Diable) dira: «Seigneur, ce n'est pas moi qui l'ai fait transgresser; mais il était déjà dans un profond égarement»."},{"n":4658,"s":50,"a":28,"t":"Alors [Allah] dira:«Ne vous disputez pas devant moi! Alors que Je vous ai déjà fait part de la menace."},{"n":4659,"s":50,"a":29,"t":"Chez Moi, la parole ne change pas; et Je n'opprime nullement les serviteurs»."},{"n":4660,"s":50,"a":30,"t":"Le jour où Nous dirons à l'Enfer; «Es-tu rempli?» Il dira: «Y en a-t-il encore?»"},{"n":4661,"s":50,"a":31,"t":"Le Paradis sera rapproché à proximité des pieux."},{"n":4662,"s":50,"a":32,"t":"«Voilà ce qui vous a été promis, [ainsi qu'] à tout homme plein de repentir et respectueux [des prescriptions divines]"},{"n":4663,"s":50,"a":33,"t":"qui redoute le Tout Miséricordieux bien qu'il ne Le voit pas, et qui vient [vers Lui] avec un cœur porté à l'obéissance."},{"n":4664,"s":50,"a":34,"t":"Entrez-y en toute sécurité,». Voilà le jour de l'éternité!"},{"n":4665,"s":50,"a":35,"t":"Il y aura là pour eux tout ce qu'ils voudront. Et auprès de Nous il y a davantage encore."},{"n":4666,"s":50,"a":36,"t":"combien avons-Nous fait périr, avant eux, de générations bien plus fortes qu'eux. Ils avaient parcouru les contrées, cherchant [vainement] où fuir."},{"n":4667,"s":50,"a":37,"t":"Il y a bien là un rappel pour quiconque a un cœur, prête l'oreille tout en étant témoin."},{"n":4668,"s":50,"a":38,"t":"En effet Nous avons créé les cieux et la terre et ce qui existe entre eux en six jours, sans éprouver la moindre lassitude."},{"n":4669,"s":50,"a":39,"t":"Endure donc ce qu'ils disent; et célèbre la louange de ton Seigneur avant le lever du soleil et avant [son] coucher;"},{"n":4670,"s":50,"a":40,"t":"et célèbre Sa gloire, une partie de la nuit et à la suite des prosternations [prières]."},{"n":4671,"s":50,"a":41,"t":"Et sois à l'écoute, le jour où le Crieur criera d'un endroit proche,"},{"n":4672,"s":50,"a":42,"t":"le jour où ils entendront en toute vérité le Cri. Voilà le Jour de la Résurrection."},{"n":4673,"s":50,"a":43,"t":"C'est Nous qui donnons la vie et donnons la mort, et vers Nous sera la destination,"},{"n":4674,"s":50,"a":44,"t":"le jour où la terre se fendra, les [rejetant] précipitamment. Ce sera un rassemblement facile pour Nous."},{"n":4675,"s":50,"a":45,"t":"Nous savons mieux ce qu'ils disent. Tu n'as pas pour mission d'exercer sur eux une contrainte. Rappelle donc, par le Coran celui qui craint Ma menace."},{"n":4676,"s":51,"a":1,"t":"Par les vents qui éparpillent!"},{"n":4677,"s":51,"a":2,"t":"Par les porteurs de fardeaux!"},{"n":4678,"s":51,"a":3,"t":"Par les glisseurs agiles!"},{"n":4679,"s":51,"a":4,"t":"Par les distributeurs selon un commandement!"},{"n":4680,"s":51,"a":5,"t":"Ce qui vous est promis est certainement vrai."},{"n":4681,"s":51,"a":6,"t":"Et la Rétribution arrivera inévitablement."},{"n":4682,"s":51,"a":7,"t":"Par le ciel aux voies parfaitement tracées!"},{"n":4683,"s":51,"a":8,"t":"vous divergez sur ce que vous dites."},{"n":4684,"s":51,"a":9,"t":"Est détourné de lui quiconque a été détourné de la foi."},{"n":4685,"s":51,"a":10,"t":"Maudits soient les menteurs,"},{"n":4686,"s":51,"a":11,"t":"qui sont plongés dans l'insouciance."},{"n":4687,"s":51,"a":12,"t":"Ils demandent: «A quand le jour de la Rétribution?»"},{"n":4688,"s":51,"a":13,"t":"Le jour où ils seront éprouvés au Feu:"},{"n":4689,"s":51,"a":14,"t":"«Goûtez à votre épreuve [punition]; voici ce que vous cherchiez à hâter»."},{"n":4690,"s":51,"a":15,"t":"Les pieux seront dans des Jardins et [parmi] des sources,"},{"n":4691,"s":51,"a":16,"t":"recevant ce que leur Seigneur leur aura donné. Car ils ont été auparavant des bienfaisants:"},{"n":4692,"s":51,"a":17,"t":"ils dormaient peu, la nuit,"},{"n":4693,"s":51,"a":18,"t":"et aux dernières heures de la nuit ils imploraient le pardon [d'Allah];"},{"n":4694,"s":51,"a":19,"t":"et dans leurs biens, il y avait un droit au mendiant et au déshérité."},{"n":4695,"s":51,"a":20,"t":"Il y a sur terre des preuves pour ceux qui croient avec certitude;"},{"n":4696,"s":51,"a":21,"t":"ainsi qu'en vous-mêmes. N'observez-vous donc pas?"},{"n":4697,"s":51,"a":22,"t":"Et il y a dans le ciel votre subsistance et ce qui vous a été promis."},{"n":4698,"s":51,"a":23,"t":"Par le Seigneur du ciel et de la terre! Ceci est tout aussi vrai que le fait que vous parliez."},{"n":4699,"s":51,"a":24,"t":"T'est-il parvenu le récit des visiteurs honorables d'Abraham?"},{"n":4700,"s":51,"a":25,"t":"Quand ils entrèrent chez lui et dirent: «Paix!», il [leur] dit: «Paix, visiteurs inconnus»."},{"n":4701,"s":51,"a":26,"t":"Puis il alla discrètement à sa famille et apporta un veau gras."},{"n":4702,"s":51,"a":27,"t":"Ensuite il l'approcha d'eux... «Ne mangez-vous pas?» dit-il."},{"n":4703,"s":51,"a":28,"t":"Il ressentit alors de la peur vis-à-vis d'eux. Ils dirent: «N'aie pas peur». Et ils lui annoncèrent [la naissance] d'un garçon plein de savoir."},{"n":4704,"s":51,"a":29,"t":"Alors sa femme s'avança en criant, se frappa le visage et dit: «Une vieille femme stérile...»"},{"n":4705,"s":51,"a":30,"t":"Ils dirent: «Ainsi a dit ton Seigneur. C'est Lui vraiment le Sage, l'Omniscient»."},{"n":4706,"s":51,"a":31,"t":"Alors [Abraham] dit: «Quelle est donc votre mission, ô envoyés?»"},{"n":4707,"s":51,"a":32,"t":"Ils dirent: «Nous avons été envoyés vers des gens criminels,"},{"n":4708,"s":51,"a":33,"t":"pour lancer sur eux des pierres de glaise,"},{"n":4709,"s":51,"a":34,"t":"marquées auprès de ton Seigneur à l'intention des outranciers»."},{"n":4710,"s":51,"a":35,"t":"Nous en fîmes sortir alors ce qu'il y avait comme croyants,"},{"n":4711,"s":51,"a":36,"t":"mais Nous n'y trouvâmes qu'une seule maison de gens soumis."},{"n":4712,"s":51,"a":37,"t":"Et Nous y laissâmes un signe pour ceux qui redoutent le douloureux châtiment;"},{"n":4713,"s":51,"a":38,"t":"[Il y a même un signe] en Moïse quand Nous l'envoyâmes, avec une preuve évidente, vers Pharaon."},{"n":4714,"s":51,"a":39,"t":"Mais [celui-ci] se détourna confiant en sa puissance, et dit: «C'est un magicien ou un possédé!»"},{"n":4715,"s":51,"a":40,"t":"Nous le saisîmes ainsi que ses troupes, puis les jetâmes dans les flots, pour son comportement blâmable."},{"n":4716,"s":51,"a":41,"t":"De même pour les 'Aad, quand Nous envoyâmes contre eux le vent dévastateur"},{"n":4717,"s":51,"a":42,"t":"n'épargnant rien sur son passage sans le réduire en poussière."},{"n":4718,"s":51,"a":43,"t":"De même pour les Thamûd, quand il leur fut dit: «Jouissez jusqu'à un certain temps!»"},{"n":4719,"s":51,"a":44,"t":"Ils défièrent le commandement de leur Seigneur. La foudre les saisit alors qu'ils regardaient."},{"n":4720,"s":51,"a":45,"t":"Ils ne purent ni se mettre debout ni être secourus."},{"n":4721,"s":51,"a":46,"t":"De même, pour le peuple de Noé auparavant. Ils étaient des gens pervers."},{"n":4722,"s":51,"a":47,"t":"Le ciel, Nous l'avons construit par Notre puissance: et Nous l'étendons [constamment] dans l'immensité."},{"n":4723,"s":51,"a":48,"t":"Et la terre, Nous l'avons étendue. Et de quelle excellente façon Nous l'avons nivelée!"},{"n":4724,"s":51,"a":49,"t":"Et de toute chose Nous avons créé [deux éléments] de couple. Peut-être vous rappellerez-vous?"},{"n":4725,"s":51,"a":50,"t":"«Fuyez donc vers Allah. Moi, je suis pour vous de Sa part, un avertisseur explicite."},{"n":4726,"s":51,"a":51,"t":"Ne placez pas avec Allah une autre divinité. Je suis pour vous de Sa part, un avertisseur explicite»."},{"n":4727,"s":51,"a":52,"t":"Ainsi, aucun Messager n'est venu à leurs prédécesseurs sans qu'ils n'aient dit: «C'est un magicien ou un possédé!»"},{"n":4728,"s":51,"a":53,"t":"Est-ce qu'ils se sont transmis cette injonction? Ils sont plutôt des gens transgresseurs."},{"n":4729,"s":51,"a":54,"t":"Détourne-toi d'eux, tu ne seras pas blâmé [à leur sujet]."},{"n":4730,"s":51,"a":55,"t":"Et rappelle; car le rappel profite aux croyants."},{"n":4731,"s":51,"a":56,"t":"Je n'ai créé les djinns et les hommes que pour qu'ils M'adorent."},{"n":4732,"s":51,"a":57,"t":"Je ne cherche pas d'eux une subsistance; et Je ne veux pas qu'ils me nourrissent."},{"n":4733,"s":51,"a":58,"t":"En vérité, c'est Allah qui est le Grand Pourvoyeur, Le Détenteur de la force, l'Inébranlable."},{"n":4734,"s":51,"a":59,"t":"Ceux qui ont été injustes auront une part [de tourments] pareille à celle de leurs compagnons. Qu'ils ne soient pas trop pressés."},{"n":4735,"s":51,"a":60,"t":"Malheur donc à ceux qui ont mécru à cause du jour dont ils sont menacés!"},{"n":4736,"s":52,"a":1,"t":"Par At-Tûr!"},{"n":4737,"s":52,"a":2,"t":"Et par un Livre écrit"},{"n":4738,"s":52,"a":3,"t":"sur un parchemin déployé!"},{"n":4739,"s":52,"a":4,"t":"Et par la Maison peuplée!"},{"n":4740,"s":52,"a":5,"t":"Et par la Voûte élevée!"},{"n":4741,"s":52,"a":6,"t":"Et par la Mer portée à ébullition! (au Jour dernier)"},{"n":4742,"s":52,"a":7,"t":"Le châtiment de ton Seigneur aura lieu inévitablement."},{"n":4743,"s":52,"a":8,"t":"Nul ne pourra le repousser."},{"n":4744,"s":52,"a":9,"t":"Le jour où le ciel sera agité d'un tourbillonnement,"},{"n":4745,"s":52,"a":10,"t":"et les montagnes se mettront en marche."},{"n":4746,"s":52,"a":11,"t":"Ce jour-là, malheur à ceux qui traitent (les signes d'Allah) de mensonges,"},{"n":4747,"s":52,"a":12,"t":"ceux qui s'ébattent dans des discours frivoles"},{"n":4748,"s":52,"a":13,"t":"le jour où ils seront brutalement poussés au feu de l'Enfer:"},{"n":4749,"s":52,"a":14,"t":"Voilà le feu que vous traitiez de mensonge."},{"n":4750,"s":52,"a":15,"t":"Est-ce que cela est de la magie? Ou bien ne voyez-vous pas clair?"},{"n":4751,"s":52,"a":16,"t":"Brûlez dedans! Supportez ou ne supportez pas, ce sera égal pour vous: vous n'êtes rétribués que selon ce que vous faisiez."},{"n":4752,"s":52,"a":17,"t":"Les pieux seront dans des Jardins et dans des délices,"},{"n":4753,"s":52,"a":18,"t":"se réjouissant de ce que leur Seigneur leur aura donné, et leur Seigneur les aura protégés du châtiment de la Fournaise."},{"n":4754,"s":52,"a":19,"t":"«En récompense de ce que vous faisiez, mangez et buvez en toute sérénité,"},{"n":4755,"s":52,"a":20,"t":"accoudés sur des lits bien rangés», et Nous leur ferons épouser des houris aux grands yeux noirs,"},{"n":4756,"s":52,"a":21,"t":"Ceux qui auront cru et que leurs descendants auront suivis dans la foi, Nous ferons que leurs descendants les rejoignent. Et Nous ne diminuerons en rien le mérite de leurs œuvres, chacun étant tenu responsable de ce qu'il aura acquis."},{"n":4757,"s":52,"a":22,"t":"Nous les pourvoirons abondamment des fruits et des viandes qu'ils désireront."},{"n":4758,"s":52,"a":23,"t":"Là, ils se passeront les uns les autres une coupe qui ne provoquera ni vanité ni incrimination."},{"n":4759,"s":52,"a":24,"t":"Et parmi eux circuleront des garçons à leur service, pareils à des perles bien conservées."},{"n":4760,"s":52,"a":25,"t":"Et ils se tourneront les uns vers les autres s'interrogeant;"},{"n":4761,"s":52,"a":26,"t":"Ils diront: «Nous vivions au milieu des nôtres dans la crainte [d'Allah];"},{"n":4762,"s":52,"a":27,"t":"Puis Allah nous a favorisés et protégés du châtiment du Samûm."},{"n":4763,"s":52,"a":28,"t":"Antérieurement, nous L'invoquions. C'est Lui certes, le Charitable, le Très Miséricordieux»."},{"n":4764,"s":52,"a":29,"t":"Rappelle donc et par la grâce de ton Seigneur tu n'es ni un devin ni un possédé."},{"n":4765,"s":52,"a":30,"t":"Ou bien ils disent: «C'est un poète! Attendons pour lui le coup de la mort»."},{"n":4766,"s":52,"a":31,"t":"Dis: «Attendez! Je suis avec vous parmi ceux qui attendent»."},{"n":4767,"s":52,"a":32,"t":"Est-ce leur raison qui leur commande cela? Ou sont-ils des gens outranciers?"},{"n":4768,"s":52,"a":33,"t":"Ou bien ils disent: «Il l'a inventé lui-même?» Non... mais ils ne croient pas."},{"n":4769,"s":52,"a":34,"t":"Eh bien, qu'ils produisent un récit pareil à lui (le Coran), s'ils sont véridiques."},{"n":4770,"s":52,"a":35,"t":"Ont-ils été créé à partir de rien ou sont-ils eux les créateurs?"},{"n":4771,"s":52,"a":36,"t":"Ou ont-ils créé les cieux et la terre? Mais ils n'ont plutôt aucune conviction."},{"n":4772,"s":52,"a":37,"t":"Possèdent-ils les trésors de ton Seigneur? Ou sont-ils eux les maîtres souverains?"},{"n":4773,"s":52,"a":38,"t":"Ont-ils une échelle d'où ils écoutent? Que celui des leurs qui reste à l'écoute apporte une preuve évidente!"},{"n":4774,"s":52,"a":39,"t":"[Allah] aurait-Il les filles, tandis que vous, les fils?"},{"n":4775,"s":52,"a":40,"t":"Ou leur demandes-tu un salaire, de sorte qu'ils soient grevés d'une lourde dette?"},{"n":4776,"s":52,"a":41,"t":"Ou bien détiennent-ils l'Inconnaissable pour le mentionner par écrit?"},{"n":4777,"s":52,"a":42,"t":"Ou cherchent-ils un stratagème? Mais ce sont ceux qui ont mécru qui sont victimes de leur propre stratagème."},{"n":4778,"s":52,"a":43,"t":"Ou ont-ils une autre divinité à part Allah? Qu'Allah soit glorifié et purifié de tout ce qu'ils associent!"},{"n":4779,"s":52,"a":44,"t":"Et s'ils voient tomber des fragments du ciel, ils disent: «Ce sont des nuages superposés»."},{"n":4780,"s":52,"a":45,"t":"Laisse-les donc, jusqu'à ce qu'ils rencontrent leur jour où ils seront foudroyés,"},{"n":4781,"s":52,"a":46,"t":"le jour où leur ruse ne leur servira à rien, où ils ne seront pas secourus."},{"n":4782,"s":52,"a":47,"t":"Les injustes auront un châtiment préalable. Mais la plupart d'entre eux ne savent pas."},{"n":4783,"s":52,"a":48,"t":"Et supporte patiemment la décision de ton Seigneur. Car en vérité, tu es sous Nos yeux. Et célèbre la gloire de ton Seigneur quand tu te lèves;"},{"n":4784,"s":52,"a":49,"t":"Glorifie-Le une partie de la nuit et au déclin des étoiles."},{"n":4785,"s":53,"a":1,"t":"Par l'étoile à son déclin!"},{"n":4786,"s":53,"a":2,"t":"Votre compagnon ne s'est pas égaré et n'a pas été induit en erreur"},{"n":4787,"s":53,"a":3,"t":"et il ne prononce rien sous l'effet de la passion;"},{"n":4788,"s":53,"a":4,"t":"ce n'est rien d'autre qu'une révélation inspirée."},{"n":4789,"s":53,"a":5,"t":"Que lui a enseigné [l'Ange Gabriel] à la force prodigieuse,"},{"n":4790,"s":53,"a":6,"t":"doué de sagacité; c'est alors qu'il se montra sous sa forme réelle [angélique],"},{"n":4791,"s":53,"a":7,"t":"alors qu'il se trouvait à l'horizon supérieur."},{"n":4792,"s":53,"a":8,"t":"Puis il se rapprocha et descendit encore plus bas,"},{"n":4793,"s":53,"a":9,"t":"et fut à deux portées d'arc, ou plus près encore."},{"n":4794,"s":53,"a":10,"t":"Il révéla à Son serviteur ce qu'Il révéla."},{"n":4795,"s":53,"a":11,"t":"Le cœur n'a pas menti en ce qu'il a vu."},{"n":4796,"s":53,"a":12,"t":"Lui contestez-vous donc ce qu'il voit?"},{"n":4797,"s":53,"a":13,"t":"Il l'a pourtant vu, lors d'une autre descente,"},{"n":4798,"s":53,"a":14,"t":"près de la Sidrat-ul-Muntahâ,"},{"n":4799,"s":53,"a":15,"t":"près d'elle se trouve le jardin de Ma'w?:"},{"n":4800,"s":53,"a":16,"t":"au moment où le lotus était couvert de ce qui le couvrait."},{"n":4801,"s":53,"a":17,"t":"la vue n'a nullement dévié ni outrepassé la mesure."},{"n":4802,"s":53,"a":18,"t":"Il a bien vu certaines des grandes merveilles de son Seigneur."},{"n":4803,"s":53,"a":19,"t":"Que vous en semble [des divinités], Lât et Uuzzâ"},{"n":4804,"s":53,"a":20,"t":"ainsi que Manât, cette troisième autre?"},{"n":4805,"s":53,"a":21,"t":"Sera-ce à vous le garçon et à Lui la fille?"},{"n":4806,"s":53,"a":22,"t":"Que voilà donc un partage injuste!"},{"n":4807,"s":53,"a":23,"t":"Ce ne sont que des noms que vous avez inventés, vous et vos ancêtres. Allah n'a fait descendre aucune preuve à leur sujet. Ils ne suivent que la conjecture et les passions de [leurs] âmes, alors que la guidée leur est venue de leur Seigneur."},{"n":4808,"s":53,"a":24,"t":"Ou bien l'homme aura-t-il tout ce qu'il désire?"},{"n":4809,"s":53,"a":25,"t":"A Allah appartiennent la vie future et la vie d'ici-bas."},{"n":4810,"s":53,"a":26,"t":"Et que d'Anges dans les cieux dont l'intercession ne sert à rien, sinon qu'après qu'Allah l'aura permis, en faveur de qui Il veut et qu'Il agrée."},{"n":4811,"s":53,"a":27,"t":"Ceux qui ne croient pas en l'au-delà donnent aux Anges des noms de femmes,"},{"n":4812,"s":53,"a":28,"t":"alors qu'ils n'en ont aucune science: ils ne suivent que la conjecture, alors que la conjecture ne sert à rien contre la vérité."},{"n":4813,"s":53,"a":29,"t":"Ecarte-toi donc, de celui qui tourne le dos à Notre rappel et qui ne désire que la vie présente."},{"n":4814,"s":53,"a":30,"t":"Voilà toute la portée de leur savoir. Certes ton Seigneur connaît parfaitement celui qui s'égare de Son chemin et Il connaît parfaitement qui est bien guidé."},{"n":4815,"s":53,"a":31,"t":"A Allah appartient ce qui est dans les cieux et sur la terre afin qu'Il rétribue ceux qui font le mal selon ce qu'ils œuvrent, et récompense ceux qui font le bien par la meilleure [récompense],"},{"n":4816,"s":53,"a":32,"t":"ceux qui évitent les plus grands péchés ainsi que les turpitudes et [qui ne commettent] que des fautes légères. Certes, le pardon de Ton Seigneur est immense. C'est Lui qui vous connaît le mieux quand Il vous a produits de terre, et aussi quand vous étiez des embryons dans les ventres de vos mères. Ne vantez pas vous-mêmes votre pureté; c'est Lui qui connaît mieux ceux qui [Le] craignent."},{"n":4817,"s":53,"a":33,"t":"Vois-tu celui qui s'est détourné,"},{"n":4818,"s":53,"a":34,"t":"donné peu et a [finalement] cessé de donner?"},{"n":4819,"s":53,"a":35,"t":"Détient-il la science de l'Inconnaissable en sorte qu'il voit?"},{"n":4820,"s":53,"a":36,"t":"Ne lui a-t-on pas annoncé ce qu'il y avait dans les feuilles de Moïse"},{"n":4821,"s":53,"a":37,"t":"et celles d'Abraham qui a tenu parfaitement [sa promesse de transmettre]"},{"n":4822,"s":53,"a":38,"t":"qu'aucune [âme] ne portera le fardeau (le péché) d'autrui,"},{"n":4823,"s":53,"a":39,"t":"et qu'en vérité, l'homme n'obtient que [le fruit] de ses efforts;"},{"n":4824,"s":53,"a":40,"t":"et que son effort, en vérité, lui sera présenté (le jour du Jugement)."},{"n":4825,"s":53,"a":41,"t":"Ensuite il en sera récompensé pleinement,"},{"n":4826,"s":53,"a":42,"t":"et que tout aboutit, en vérité, vers ton Seigneur,"},{"n":4827,"s":53,"a":43,"t":"et que c'est Lui qui a fait rire et qui a fait pleurer,"},{"n":4828,"s":53,"a":44,"t":"et que c'est Lui qui a fait mourir et qui a ramené à la vie,"},{"n":4829,"s":53,"a":45,"t":"et que c'est Lui qui a crée les deux éléments de couple, le mâle et la femelle,"},{"n":4830,"s":53,"a":46,"t":"d'une goutte de sperme quand elle est éjaculée"},{"n":4831,"s":53,"a":47,"t":"et que la seconde création Lui incombe,"},{"n":4832,"s":53,"a":48,"t":"et c'est Lui qui a enrichi et qui a fait acquérir."},{"n":4833,"s":53,"a":49,"t":"Et c'est Lui qui est le Seigneur de Sirius,"},{"n":4834,"s":53,"a":50,"t":"et c'est Lui qui a fait périr les anciens 'Aad,"},{"n":4835,"s":53,"a":51,"t":"ainsi que les Thamûd, et Il fit que rien n'en subsistât,"},{"n":4836,"s":53,"a":52,"t":"ainsi que le peuple de Noé antérieurement, car ils étaient encore plus injustes et plus violents,"},{"n":4837,"s":53,"a":53,"t":"de même qu'Il anéantit les villes renversées."},{"n":4838,"s":53,"a":54,"t":"Et les recouvrit de ce dont Il les recouvrit."},{"n":4839,"s":53,"a":55,"t":"Lequel donc des bienfaits de ton Seigneur mets-tu en doute?"},{"n":4840,"s":53,"a":56,"t":"Voici un avertisseur analogue aux avertisseurs anciens:"},{"n":4841,"s":53,"a":57,"t":"l'Imminente (L'heure du Jugement) s'approche."},{"n":4842,"s":53,"a":58,"t":"Rien d'autre en dehors d'Allah ne peut la dévoiler."},{"n":4843,"s":53,"a":59,"t":"Quoi! vous étonnez-vous de ce discours (le Coran)?"},{"n":4844,"s":53,"a":60,"t":"Et vous [en] riez et n'[en] pleurez point?"},{"n":4845,"s":53,"a":61,"t":"absorbés [que vous êtes] par votre distraction."},{"n":4846,"s":53,"a":62,"t":"Prosternez-vous donc à Allah et adorez-Le."},{"n":4847,"s":54,"a":1,"t":"L'Heure approche et la Lune s'est fendue."},{"n":4848,"s":54,"a":2,"t":"Et s'ils voient un prodige, ils s'en détournent et disent: «Une magie persistante»."},{"n":4849,"s":54,"a":3,"t":"Et ils [le] traitent de mensonge et suivent leurs propres impulsions, or chaque chose arrivera à son terme [et son but]."},{"n":4850,"s":54,"a":4,"t":"Ils ont pourtant reçu comme nouvelles de quoi les empêcher (du mal);"},{"n":4851,"s":54,"a":5,"t":"[Cela est] une sagesse parfaite. Mais les avertissements ne [leur] servent à rien."},{"n":4852,"s":54,"a":6,"t":"Détourne-toi d'eux. Le jour où l'appeleur appellera vers une chose affreuse,"},{"n":4853,"s":54,"a":7,"t":"les regards baissés, ils sortiront des tombes comme des sauterelles éparpillées,"},{"n":4854,"s":54,"a":8,"t":"courant, le cou tendu, vers l'appeleur. Les mécréants diront: «Voilà un jour difficile»."},{"n":4855,"s":54,"a":9,"t":"Avant eux, le peuple de Noé avait crié au mensonge. Ils traitèrent Notre serviteur de menteur et dirent: «C'est un possédé!» et il fut repoussé."},{"n":4856,"s":54,"a":10,"t":"Il invoqua donc son Seigneur: «Moi, je suis vaincu. Fais triompher (Ta cause)»."},{"n":4857,"s":54,"a":11,"t":"Nous ouvrîmes alors les portes du ciel à une eau torrentielle,"},{"n":4858,"s":54,"a":12,"t":"et fîmes jaillir la terre en sources. Les eaux se rencontrèrent d'après un ordre qui était déjà décrété dans une chose [faite]."},{"n":4859,"s":54,"a":13,"t":"Et Nous le portâmes sur un objet [fait] de planches et de clous [l'arche],"},{"n":4860,"s":54,"a":14,"t":"voguant sous Nos yeux: récompense pour celui qu'on avait renié [Noé]."},{"n":4861,"s":54,"a":15,"t":"Et Nous la laissâmes, comme un signe [d'avertissement]. Y a-t-il quelqu'un pour réfléchir?"},{"n":4862,"s":54,"a":16,"t":"Comment furent Mon châtiment et Mes avertissements?"},{"n":4863,"s":54,"a":17,"t":"En effet, Nous avons rendu le Coran facile pour la méditation. Y a-t-il quelqu'un pour réfléchir?"},{"n":4864,"s":54,"a":18,"t":"Les 'Aad ont traité de menteur (leur Messager). Comment furent Mon châtiment et Mes avertissements?"},{"n":4865,"s":54,"a":19,"t":"Nous avons envoyé contre eux un vent violent et glacial, en un jour néfaste et interminable;"},{"n":4866,"s":54,"a":20,"t":"il arrachait les gens comme des souches de palmiers déracinés."},{"n":4867,"s":54,"a":21,"t":"Comment furent Mon châtiment et Mes avertissements?"},{"n":4868,"s":54,"a":22,"t":"En effet, Nous avons rendu le Coran facile pour la méditation. Y a-t-il quelqu'un pour réfléchir?"},{"n":4869,"s":54,"a":23,"t":"Les Thamûd ont traité de mensonges les avertissements."},{"n":4870,"s":54,"a":24,"t":"Ils dirent: «Allons-nous suivre un seul homme (Sâlih) d'entre nous-mêmes? Nous serions alors dans l'égarement et la folie."},{"n":4871,"s":54,"a":25,"t":"Est-ce que le message a été envoyé à Lui à l'exception de nous tous? C'est plutôt un grand menteur, plein de prétention et d'orgueil»."},{"n":4872,"s":54,"a":26,"t":"Demain, ils sauront qui est le grand menteur plein de prétention et d'orgueil."},{"n":4873,"s":54,"a":27,"t":"Nous leur enverrons la chamelle, comme épreuve. Surveille-les donc et sois patient."},{"n":4874,"s":54,"a":28,"t":"Et informe-les que l'eau sera en partage entre eux [et la chamelle]; chacun boira à son tour."},{"n":4875,"s":54,"a":29,"t":"Puis ils appelèrent leur camarade qui prit [son épée] et [la] tua."},{"n":4876,"s":54,"a":30,"t":"Comment furent donc Mon châtiment et Mes avertissements?"},{"n":4877,"s":54,"a":31,"t":"Nous lachâmes sur eux un seul Cri, et voilà qu'ils furent réduits à l'état de paille d'étable."},{"n":4878,"s":54,"a":32,"t":"Et vraiment, Nous avons rendu le Coran facile pour la méditation. Y a-t-il quelqu'un pour réfléchir?"},{"n":4879,"s":54,"a":33,"t":"Le peuple de Lot traita de mensonges les avertissements."},{"n":4880,"s":54,"a":34,"t":"Nous lachâmes sur eux un ouragan, excepté la famille de Lot que Nous sauvâmes avant l'aube,"},{"n":4881,"s":54,"a":35,"t":"à titre de bienfait de Notre part: ainsi récompensons-Nous celui qui est reconnaissant."},{"n":4882,"s":54,"a":36,"t":"Il les avait pourtant avertis de Nos représailles. Mais ils mirent les avertissements en doute."},{"n":4883,"s":54,"a":37,"t":"En effet, ils voulaient séduire ses hôtes. Nous aveuglâmes leurs yeux «Goûtez donc Mon châtiment et Mes avertissements»."},{"n":4884,"s":54,"a":38,"t":"En effet, au petit matin, un châtiment persistant les surprit."},{"n":4885,"s":54,"a":39,"t":"Goûtez donc Mon châtiment et Mes avertissements."},{"n":4886,"s":54,"a":40,"t":"Et vraiment, Nous avons rendu le Coran facile pour la méditation. Y a-t-il quelqu'un pour réfléchir?"},{"n":4887,"s":54,"a":41,"t":"Les avertissements vinrent certes, aux gens de Pharaon."},{"n":4888,"s":54,"a":42,"t":"Ils traitèrent de mensonges tous Nos prodiges. Nous les saisîmes donc, de la saisie d'un Puissant Omnipotent."},{"n":4889,"s":54,"a":43,"t":"Vos mécréants sont-ils meilleurs que ceux-là? Ou bien y a-t-il dans les Ecritures une immunité pour vous?"},{"n":4890,"s":54,"a":44,"t":"Ou bien ils disent: «Nous formons un groupe [fort] et nous vaincrons»."},{"n":4891,"s":54,"a":45,"t":"Leur rassemblement sera bientôt mis en déroute, et ils fuiront."},{"n":4892,"s":54,"a":46,"t":"L'Heure, plutôt, sera leur rendez-vous, et l'Heure sera plus terrible et plus amère."},{"n":4893,"s":54,"a":47,"t":"Les criminels sont certes, dans l'égarement et la folie."},{"n":4894,"s":54,"a":48,"t":"Le jour où on les traînera dans le Feu sur leurs visages, (on leur dira): «Goûtez au contact de Saqar [la chaleur brûlante de l'Enfer]»."},{"n":4895,"s":54,"a":49,"t":"Nous avons créé toute chose avec mesure,"},{"n":4896,"s":54,"a":50,"t":"et Notre ordre est une seule [parole]; [il est prompt] comme un clin d'œil."},{"n":4897,"s":54,"a":51,"t":"En effet, nous avons fait périr des peuples semblables à vous. Y a-t-il quelqu'un pour s'en souvenir?"},{"n":4898,"s":54,"a":52,"t":"Et tout ce qu'ils ont fait est mentionné dans les registres,"},{"n":4899,"s":54,"a":53,"t":"et tout fait, petit et grand, est consigné."},{"n":4900,"s":54,"a":54,"t":"Les pieux seront dans des Jardins et parmi des ruisseaux,"},{"n":4901,"s":54,"a":55,"t":"dans un séjour de vérité, auprès d'un Souverain Omnipotent."},{"n":4902,"s":55,"a":1,"t":"Le Tout Miséricordieux."},{"n":4903,"s":55,"a":2,"t":"Il a enseigné le Coran."},{"n":4904,"s":55,"a":3,"t":"Il a créé l'homme."},{"n":4905,"s":55,"a":4,"t":"Il lui a appris à s'exprimer clairement."},{"n":4906,"s":55,"a":5,"t":"Le soleil et la lune [évoluent] selon un calcul [minutieux]."},{"n":4907,"s":55,"a":6,"t":"Et l'herbe et les arbres se prosternent."},{"n":4908,"s":55,"a":7,"t":"Et quant au ciel, Il l'a élevé bien haut. Et Il a établi la balance,"},{"n":4909,"s":55,"a":8,"t":"afin que vous ne transgressiez pas dans la pesée:"},{"n":4910,"s":55,"a":9,"t":"Donnez [toujours] le poids exact et ne faussez pas la pesée."},{"n":4911,"s":55,"a":10,"t":"Quant à la terre, Il l'a étendue pour les êtres vivants:"},{"n":4912,"s":55,"a":11,"t":"il s'y trouve des fruits, et aussi les palmiers aux fruits recouverts d'enveloppes,"},{"n":4913,"s":55,"a":12,"t":"tout comme les grains dans leurs balles, et les plantes aromatiques."},{"n":4914,"s":55,"a":13,"t":"Lequel donc des bienfaits de votre Seigneur nierez-vous?"},{"n":4915,"s":55,"a":14,"t":"Il a crée l'homme d'argile sonnante comme la poterie;"},{"n":4916,"s":55,"a":15,"t":"et Il a créé les djinns de la flamme d'un feu sans fumée."},{"n":4917,"s":55,"a":16,"t":"Lequel donc des bienfaits de votre Seigneur nierez-vous?"},{"n":4918,"s":55,"a":17,"t":"Seigneur des deux Levants et Seigneur des deux Couchants!"},{"n":4919,"s":55,"a":18,"t":"Lequel donc des bienfaits de votre Seigneur nierez-vous?"},{"n":4920,"s":55,"a":19,"t":"Il a donné libre cours aux deux mers pour se rencontrer;"},{"n":4921,"s":55,"a":20,"t":"il y a entre elles une barrière qu'elles ne dépassent pas."},{"n":4922,"s":55,"a":21,"t":"Lequel donc des bienfaits de votre Seigneur nierez-vous?"},{"n":4923,"s":55,"a":22,"t":"De ces deux [mers] sortent la perle et le corail."},{"n":4924,"s":55,"a":23,"t":"Lequel donc des bienfaits de votre Seigneur nierez-vous?"},{"n":4925,"s":55,"a":24,"t":"A Lui appartiennent les vaisseaux élevés sur la mer comme des montagnes."},{"n":4926,"s":55,"a":25,"t":"Lequel donc des bienfaits de votre Seigneur nierez-vous?"},{"n":4927,"s":55,"a":26,"t":"Tout ce qui est sur elle [la terre] doit disparaître,"},{"n":4928,"s":55,"a":27,"t":"[Seule] subsistera La Face [Wajh] de ton Seigneur, plein de majesté et de noblesse."},{"n":4929,"s":55,"a":28,"t":"Lequel donc des bienfaits de votre Seigneur nierez-vous?"},{"n":4930,"s":55,"a":29,"t":"Ceux qui sont dans les cieux et la terre L'implorent. Chaque jour, Il accomplit une œuvre nouvelle."},{"n":4931,"s":55,"a":30,"t":"Lequel donc des bienfaits de votre Seigneur nierez-vous?"},{"n":4932,"s":55,"a":31,"t":"Nous allons bientôt entreprendre votre jugement, ô vous les deux charges [hommes et djinns]."},{"n":4933,"s":55,"a":32,"t":"Lequel donc des bienfaits de votre Seigneur nierez-vous?"},{"n":4934,"s":55,"a":33,"t":"O peuple de djinns et d'hommes! Si vous pouvez sortir du domaine des cieux et de la terre, alors faites-le. Mais vous ne pourrez en sortir qu'à l'aide d'un pouvoir [illimité]."},{"n":4935,"s":55,"a":34,"t":"Lequel donc des bienfaits de votre Seigneur nierez-vous?"},{"n":4936,"s":55,"a":35,"t":"Il sera lancé contre vous un jet de feu et de fumée [ou de cuivre fondu], et vous ne serez pas secourus."},{"n":4937,"s":55,"a":36,"t":"Lequel donc des bienfaits de votre Seigneur nierez-vous?"},{"n":4938,"s":55,"a":37,"t":"Puis quand le ciel se fendra et deviendra alors écarlate comme le cuir rouge."},{"n":4939,"s":55,"a":38,"t":"Lequel des bienfaits de votre Seigneur nierez-vous?"},{"n":4940,"s":55,"a":39,"t":"Alors, ni aux hommes ni aux djinns, on ne posera des questions à propos de leurs péchés."},{"n":4941,"s":55,"a":40,"t":"Lequel donc des bienfaits de votre Seigneur nierez-vous?"},{"n":4942,"s":55,"a":41,"t":"On reconnaîtra les criminels à leurs traits. Ils seront donc saisis par les toupets et les pieds."},{"n":4943,"s":55,"a":42,"t":"Lequel donc des bienfaits de votre Seigneur nierez-vous?"},{"n":4944,"s":55,"a":43,"t":"Voilà l'Enfer que les criminels traitaient de mensonge."},{"n":4945,"s":55,"a":44,"t":"Ils feront le va-et-vient entre lui (l'Enfer) et une eau bouillante extrêmement chaude."},{"n":4946,"s":55,"a":45,"t":"Lequel donc des bienfaits de votre Seigneur nierez-vous?"},{"n":4947,"s":55,"a":46,"t":"Et pour celui qui aura craint de comparaître devant son Seigneur, il y aura deux jardins;"},{"n":4948,"s":55,"a":47,"t":"Lequel donc des bienfaits de votre Seigneur nierez-vous?"},{"n":4949,"s":55,"a":48,"t":"Aux branches touffues."},{"n":4950,"s":55,"a":49,"t":"Lequel donc des bienfaits de votre Seigneur nierez-vous?"},{"n":4951,"s":55,"a":50,"t":"Ils y trouveront deux sources courantes."},{"n":4952,"s":55,"a":51,"t":"Lequel donc des bienfaits de votre Seigneur nierez-vous?"},{"n":4953,"s":55,"a":52,"t":"Ils contiennent deux espèces de chaque fruit."},{"n":4954,"s":55,"a":53,"t":"Lequel donc des bienfaits de votre Seigneur nierez-vous?"},{"n":4955,"s":55,"a":54,"t":"Ils seront accoudés sur des tapis doublés de brocart, et les fruits des deux jardins seront à leur portée (pour être cueillis)."},{"n":4956,"s":55,"a":55,"t":"Lequel donc des bienfaits de votre Seigneur nierez-vous?"},{"n":4957,"s":55,"a":56,"t":"Ils y trouveront [les houris] aux regards chastes, qu'avant eux aucun homme ou djinn n'aura déflorées."},{"n":4958,"s":55,"a":57,"t":"Lequel donc des bienfaits de votre Seigneur nierez-vous?"},{"n":4959,"s":55,"a":58,"t":"Elles seront [aussi belles] que le rubis et le corail."},{"n":4960,"s":55,"a":59,"t":"Lequel donc des bienfaits de votre Seigneur nierez-vous?"},{"n":4961,"s":55,"a":60,"t":"Y a-t-il d'autre récompense pour le bien, que le bien?"},{"n":4962,"s":55,"a":61,"t":"Lequel donc des bienfaits de votre Seigneur nierez-vous?"},{"n":4963,"s":55,"a":62,"t":"En deçà de ces deux jardins il y aura deux autres jardins."},{"n":4964,"s":55,"a":63,"t":"Lequel donc des bienfaits de votre Seigneur nierez-vous?"},{"n":4965,"s":55,"a":64,"t":"Ils sont d'un vert sombre."},{"n":4966,"s":55,"a":65,"t":"Lequel donc des bienfaits de votre Seigneur nierez-vous?"},{"n":4967,"s":55,"a":66,"t":"Dans lesquelles il y aura deux sources jaillissantes."},{"n":4968,"s":55,"a":67,"t":"Lequel donc des bienfaits de votre Seigneur nierez-vous?"},{"n":4969,"s":55,"a":68,"t":"Ils contiennent des fruits, des palmiers, et des grenadiers."},{"n":4970,"s":55,"a":69,"t":"Lequel donc des bienfaits de votre Seigneur nierez-vous?"},{"n":4971,"s":55,"a":70,"t":"Là, il y aura des vertueuses et des belles."},{"n":4972,"s":55,"a":71,"t":"Lequel donc des bienfaits de votre Seigneur nierez-vous?"},{"n":4973,"s":55,"a":72,"t":"Des houris cloîtrées dans les tentes,"},{"n":4974,"s":55,"a":73,"t":"Lequel donc des bienfaits de votre Seigneur nierez-vous?"},{"n":4975,"s":55,"a":74,"t":"qu'avant eux aucun homme ou djinn n'a déflorées."},{"n":4976,"s":55,"a":75,"t":"Lequel donc des bienfaits de votre Seigneur nierez-vous?"},{"n":4977,"s":55,"a":76,"t":"Ils seront accoudés sur des coussins verts et des tapis épais et jolis."},{"n":4978,"s":55,"a":77,"t":"Lequel donc des bienfaits de votre Seigneur nierez-vous?"},{"n":4979,"s":55,"a":78,"t":"Béni soit le Nom de ton Seigneur, Plein de Majesté et de Munificence!"},{"n":4980,"s":56,"a":1,"t":"Quand l'événement (le Jugement) arrivera,"},{"n":4981,"s":56,"a":2,"t":"nul ne traitera sa venue de mensonge."},{"n":4982,"s":56,"a":3,"t":"Il abaissera (les uns), il élèvera (les autres)."},{"n":4983,"s":56,"a":4,"t":"Quand la terre sera secouée violemment,"},{"n":4984,"s":56,"a":5,"t":"et les montagnes seront réduites en miettes,"},{"n":4985,"s":56,"a":6,"t":"et qu'elles deviendront poussière éparpillée"},{"n":4986,"s":56,"a":7,"t":"alors vous serez trois catégories:"},{"n":4987,"s":56,"a":8,"t":"les gens de la droite - que sont les gens de la droite?"},{"n":4988,"s":56,"a":9,"t":"Et les gens de la gauche - que sont les gens de la gauche?"},{"n":4989,"s":56,"a":10,"t":"Les premiers (à suivre les ordres d'Allah sur la terre) ce sont eux qui seront les premiers (dans l'au-delà)"},{"n":4990,"s":56,"a":11,"t":"Ce sont ceux-là les plus rapprochés d'Allah"},{"n":4991,"s":56,"a":12,"t":"dans les Jardins des délices,"},{"n":4992,"s":56,"a":13,"t":"une multitude d'élus parmi les premières [générations],"},{"n":4993,"s":56,"a":14,"t":"et un petit nombre parmi les dernières [générations],"},{"n":4994,"s":56,"a":15,"t":"sur des lits ornés [d'or et de pierreries],"},{"n":4995,"s":56,"a":16,"t":"s'y accoudant et se faisant face."},{"n":4996,"s":56,"a":17,"t":"Parmi eux circuleront des garçons éternellement jeunes,"},{"n":4997,"s":56,"a":18,"t":"avec des coupes, des aiguières et un verre [rempli] d'une liqueur de source"},{"n":4998,"s":56,"a":19,"t":"qui ne leur provoquera ni maux de tête ni étourdissement;"},{"n":4999,"s":56,"a":20,"t":"et des fruits de leur choix,"},{"n":5000,"s":56,"a":21,"t":"et toute chair d'oiseau qu'ils désireront."},{"n":5001,"s":56,"a":22,"t":"Et ils auront des houris aux yeux, grands et beaux,"},{"n":5002,"s":56,"a":23,"t":"pareilles à des perles en coquille"},{"n":5003,"s":56,"a":24,"t":"en récompense pour ce qu'ils faisaient."},{"n":5004,"s":56,"a":25,"t":"Ils n'y entendront ni futilité ni blasphème;"},{"n":5005,"s":56,"a":26,"t":"mais seulement les propos: «Salâm! Salâm!»... [Paix! Paix!]"},{"n":5006,"s":56,"a":27,"t":"Et les gens de la droite; que sont les gens de la droite?"},{"n":5007,"s":56,"a":28,"t":"[Ils seront parmi] des jujubiers sans épines,"},{"n":5008,"s":56,"a":29,"t":"et parmi des bananiers aux régimes bien fournis,"},{"n":5009,"s":56,"a":30,"t":"dans une ombre étendue"},{"n":5010,"s":56,"a":31,"t":"[près] d'une eau coulant continuellement,"},{"n":5011,"s":56,"a":32,"t":"et des fruits abondants"},{"n":5012,"s":56,"a":33,"t":"ni interrompus ni défendus,"},{"n":5013,"s":56,"a":34,"t":"sur des lits surélevés,"},{"n":5014,"s":56,"a":35,"t":"C'est Nous qui les avons créées à la perfection,"},{"n":5015,"s":56,"a":36,"t":"et Nous les avons faites vierges,"},{"n":5016,"s":56,"a":37,"t":"gracieuses, toutes de même âge,"},{"n":5017,"s":56,"a":38,"t":"pour les gens de la droite,"},{"n":5018,"s":56,"a":39,"t":"une multitude d'élus parmi les premières [générations],"},{"n":5019,"s":56,"a":40,"t":"et une multitude d'élus parmi les dernières [générations]."},{"n":5020,"s":56,"a":41,"t":"Et les gens de la gauche; que sont les gens de la gauche?"},{"n":5021,"s":56,"a":42,"t":"ils seront au milieu d'un souffle brûlant et d'une eau bouillante,"},{"n":5022,"s":56,"a":43,"t":"à l'ombre d'une fumée noire"},{"n":5023,"s":56,"a":44,"t":"ni fraîche, ni douce."},{"n":5024,"s":56,"a":45,"t":"Ils vivaient auparavant dans le luxe."},{"n":5025,"s":56,"a":46,"t":"Ils persistaient dans le grand péché [le polythéisme]"},{"n":5026,"s":56,"a":47,"t":"et disaient: «Quand nous mourrons et serons poussière et ossements, serons-nous ressuscités?"},{"n":5027,"s":56,"a":48,"t":"ainsi que nos anciens ancêtres?..»"},{"n":5028,"s":56,"a":49,"t":"Dis: «En vérité les premiers et les derniers"},{"n":5029,"s":56,"a":50,"t":"seront réunis pour le rendez-vous d'un jour connu»."},{"n":5030,"s":56,"a":51,"t":"Et puis, vous, les égarés, qui traitiez (la Résurrection) de mensonge,"},{"n":5031,"s":56,"a":52,"t":"vous mangerez certainement d'un arbre de Zaqqûm."},{"n":5032,"s":56,"a":53,"t":"vous vous en remplirez le ventre,"},{"n":5033,"s":56,"a":54,"t":"puis vous boirez par-dessus cela de l'eau bouillante,"},{"n":5034,"s":56,"a":55,"t":"vous en boirez comme boivent les chameaux assoiffés."},{"n":5035,"s":56,"a":56,"t":"Voilà le repas d'accueil qui leur sera servi, au jour de la Rétribution."},{"n":5036,"s":56,"a":57,"t":"C'est Nous qui vous avons créés. Pourquoi ne croiriez-vous donc pas [à la résurrection]?"},{"n":5037,"s":56,"a":58,"t":"Voyez-vous donc ce que vous éjaculez:"},{"n":5038,"s":56,"a":59,"t":"est-ce vous qui le créez ou [en] sommes Nous le Créateur?"},{"n":5039,"s":56,"a":60,"t":"Nous avons prédéterminé la mort parmi vous. Nous ne serons point empêchés"},{"n":5040,"s":56,"a":61,"t":"de vous remplacer par vos semblables, et vous faire renaître dans [un état] que vous ne savez pas."},{"n":5041,"s":56,"a":62,"t":"Vous avez connu la première création. Ne vous rappelez-vous donc pas?"},{"n":5042,"s":56,"a":63,"t":"Voyez-vous donc ce que vous labourez?"},{"n":5043,"s":56,"a":64,"t":"Est-ce vous qui le cultivez? ou [en] sommes Nous le cultivateur?"},{"n":5044,"s":56,"a":65,"t":"Si Nous voulions, Nous le réduirions en débris. Et vous ne cesseriez pas de vous étonner et [de crier]:"},{"n":5045,"s":56,"a":66,"t":"«Nous voilà endettés!"},{"n":5046,"s":56,"a":67,"t":"ou plutôt, exposés aux privations»."},{"n":5047,"s":56,"a":68,"t":"Voyez-vous donc l'eau que vous buvez?"},{"n":5048,"s":56,"a":69,"t":"Est-ce vous qui l'avez fait descendre du nuage? ou [en] sommes Nous le descendeur?"},{"n":5049,"s":56,"a":70,"t":"Si Nous voulions, Nous la rendrions salée. Pourquoi n'êtes-vous donc pas reconnaissants?"},{"n":5050,"s":56,"a":71,"t":"Voyez-vous donc le feu que vous obtenez par frottement?"},{"n":5051,"s":56,"a":72,"t":"Est-ce vous qui avez créé son arbre ou [en] sommes Nous le Créateur?"},{"n":5052,"s":56,"a":73,"t":"Nous en avons fait un rappel (de l'Enfer), et un élément utile pour ceux qui en ont besoin."},{"n":5053,"s":56,"a":74,"t":"Glorifie donc le nom de ton Seigneur, le Très Grand!"},{"n":5054,"s":56,"a":75,"t":"Non!.. Je jure par les positions des étoiles (dans le firmament)."},{"n":5055,"s":56,"a":76,"t":"Et c'est vraiment un serment solennel, si vous saviez."},{"n":5056,"s":56,"a":77,"t":"Et c'est certainement un Coran noble,"},{"n":5057,"s":56,"a":78,"t":"dans un Livre bien gardé"},{"n":5058,"s":56,"a":79,"t":"que seuls les purifiés touchent;"},{"n":5059,"s":56,"a":80,"t":"C'est une révélation de la part du Seigneur de l'Univers."},{"n":5060,"s":56,"a":81,"t":"Est-ce ce discours-là que vous traitez de mensonge?"},{"n":5061,"s":56,"a":82,"t":"Et est-ce pour vous [une façon d'être reconnaissant] à votre subsistance que de traiter (le Coran) de mensonge?"},{"n":5062,"s":56,"a":83,"t":"Lorsque le souffle de la vie remonte à la gorge (d'un moribond),"},{"n":5063,"s":56,"a":84,"t":"et qu'à ce moment là vous regardez,"},{"n":5064,"s":56,"a":85,"t":"et que Nous sommes plus proche de lui que vous [qui l'entourez] mais vous ne [le] voyez point."},{"n":5065,"s":56,"a":86,"t":"Pourquoi donc, si vous croyez que vous n'avez pas de compte à rendre,"},{"n":5066,"s":56,"a":87,"t":"ne la faites-vous pas revenir [cette âme], si vous êtes véridiques?"},{"n":5067,"s":56,"a":88,"t":"Si celui-ci est du nombre des rapprochés (d'Allah),"},{"n":5068,"s":56,"a":89,"t":"alors (il aura) du repos, de la grâce et un Jardin de délices."},{"n":5069,"s":56,"a":90,"t":"Et s'il est du nombre des gens de la droite,"},{"n":5070,"s":56,"a":91,"t":"il sera [accueilli par ces mots]: «Paix à toi» de la part des gens de la droite."},{"n":5071,"s":56,"a":92,"t":"Et s'il est de ceux qui avaient traité de mensonge (la résurrection) et s'étaient égarés,"},{"n":5072,"s":56,"a":93,"t":"alors, il sera installé dans une eau bouillante,"},{"n":5073,"s":56,"a":94,"t":"et il brûlera dans la Fournaise."},{"n":5074,"s":56,"a":95,"t":"C'est cela la pleine certitude."},{"n":5075,"s":56,"a":96,"t":"Glorifie donc le nom de ton Seigneur, le Très Grand!"},{"n":5076,"s":57,"a":1,"t":"Tout ce qui est dans les cieux et la terre glorifie Allah. Et c'est Lui le Puissant, le Sage."},{"n":5077,"s":57,"a":2,"t":"A Lui appartient la souveraineté des cieux et de la terre. Il fait vivre et il fait mourir, et Il est Omnipotent."},{"n":5078,"s":57,"a":3,"t":"C'est Lui le Premier et le Dernier, l'Apparent et le Caché et Il est Omniscient."},{"n":5079,"s":57,"a":4,"t":"C'est Lui qui a créé les cieux et la terre en six jours puis Il S'est établi sur le Trône; Il sait ce qui pénètre dans la terre et ce qui en sort, et ce qui descend du ciel et ce qui y monte, et Il est avec vous où que vous soyez. Et Allah observe parfaitement ce que vous faites."},{"n":5080,"s":57,"a":5,"t":"A Lui appartient la souveraineté des cieux et de la terre. Et à Allah tout est ramené."},{"n":5081,"s":57,"a":6,"t":"Il fait pénétrer la nuit dans le jour et fait pénétrer le jour dans la nuit, et Il sait parfaitement le contenu des poitrines."},{"n":5082,"s":57,"a":7,"t":"Croyez en Allah et en Son Messager, et dépensez de ce dont Il vous a donné la lieutenance. Ceux d'entre vous qui croient et dépensent [pour la cause d'Allah] auront une grande récompense."},{"n":5083,"s":57,"a":8,"t":"Et qu'avez-vous à ne pas croire en Allah, alors que le Messager vous appelle à croire en votre Seigneur? Et [Allah] a déjà pris [acte] de votre engagement si vous êtes [sincères] dans votre foi."},{"n":5084,"s":57,"a":9,"t":"C'est Lui qui fait descendre sur Son serviteur des versets clairs, afin qu'il vous fasse sortir des ténèbres à la lumière; et assurément Allah est Compatissant envers vous, et Très Miséricordieux."},{"n":5085,"s":57,"a":10,"t":"Et qu'avez-vous à ne pas dépenser dans le chemin d'Allah, alors que c'est à Allah que revient l'héritage des cieux et de la terre? On ne peut comparer cependant celui d'entre vous qui a donné ses biens et combattu avant la conquête... ces derniers sont plus hauts en hiérarchie que ceux qui ont dépensé et ont combattu après. Or, à chacun, Allah a promis la plus belle récompense, et Allah est Grand Connaisseur de ce que vous faites."},{"n":5086,"s":57,"a":11,"t":"Quiconque fait à Allah un prêt sincère, Allah le lui multiplie, et il aura une généreuse récompense."},{"n":5087,"s":57,"a":12,"t":"Le jour où tu verras les croyants et les croyantes, leur lumière courant devant eux et à leur droite; (on leur dira): «Voici une bonne nouvelle pour vous, aujourd'hui: des Jardins sous lesquels coulent les ruisseaux pour y demeurer éternellement». Tel est l'énorme succès."},{"n":5088,"s":57,"a":13,"t":"Le jour où les hypocrites, hommes et femmes, diront à ceux qui croient: «Attendez que nous empruntions [un peu] de votre lumière». Il sera dit: «Revenez en arrière, et cherchez de la lumière». C'est alors qu'on éleva entre eux une muraille ayant une porte dont l'intérieur contient la miséricorde, et dont la face apparente a devant elle le châtiment [l'Enfer]."},{"n":5089,"s":57,"a":14,"t":"«N'étions-nous pas avec vous?» leur crieront-ils. «Oui, répondront [les autres] mais vous vous êtes laissés tenter, vous avez comploté (contre les croyants) et vous avez douté et de vains espoirs vous ont trompés, jusqu'à ce que vînt l'ordre d'Allah. Et le séducteur [le diable] vous a trompés au sujet d'Allah."},{"n":5090,"s":57,"a":15,"t":"Aujourd'hui donc, on n'acceptera de rançon ni de vous ni de ceux qui ont mécru. Votre asile est le Feu: c'est lui qui est votre compagnon inséparable. Et quelle mauvaise destination!"},{"n":5091,"s":57,"a":16,"t":"Le moment n'est-il pas venu pour ceux qui ont cru, que leurs cœurs s'humilient à l'évocation d'Allah et devant ce qui est descendu de la vérité [le Coran]? Et de ne point être pareils à ceux qui ont reçu le Livre avant eux. Ceux-ci trouvèrent le temps assez long et leurs cœurs s'endurcirent, et beaucoup d'entre eux sont pervers."},{"n":5092,"s":57,"a":17,"t":"Sachez qu'Allah redonne la vie à la terre une fois morte. Certes, Nous vous avons exposé les preuves clairement afin que vous raisonniez."},{"n":5093,"s":57,"a":18,"t":"Ceux et celles qui font la charité et qui ont fait à Allah un prêt sincère, cela leur sera multiplié et ils auront une généreuse récompense."},{"n":5094,"s":57,"a":19,"t":"Ceux qui ont cru en Allah et en Ses messagers ceux-là sont les grands véridiques et les témoins auprès d'Allah. Ils auront leur récompense et leur lumière, tandis que ceux qui ont mécru et traité de mensonges Nos signes, ceux-là seront les gens de la Fournaise."},{"n":5095,"s":57,"a":20,"t":"Sachez que la vie présente n'est que jeu, amusement, vaine parure, une course à l'orgueil entre vous et une rivalité dans l'acquisition des richesses et des enfants. Elle est en cela pareille à une pluie: la végétation qui en vient émerveille les cultivateurs, puis elle se fane et tu la vois donc jaunie; ensuite elle devient des débris. Et dans l'au-delà, il y a un dur châtiment, et aussi pardon et agrément d'Allah. Et la vie présente n'est que jouissance trompeuse."},{"n":5096,"s":57,"a":21,"t":"Hâtez-vous vers un pardon de votre Seigneur ainsi qu'un Paradis aussi large que le ciel et la terre, préparé pour ceux qui ont cru en Allah et en Ses Messagers. Telle est la grâce d'Allah qu'Il donne à qui Il veut. Et Allah est le Détenteur de l'énorme grâce."},{"n":5097,"s":57,"a":22,"t":"Nul malheur n'atteint la terre ni vos personnes, qui ne soit enregistré dans un Livre avant que Nous ne l'ayons créé; et cela est certes facile à Allah,"},{"n":5098,"s":57,"a":23,"t":"afin que vous ne vous tourmentiez pas au sujet de ce qui vous a échappé, ni n'exultiez pour ce qu'Il vous a donné. Et Allah n'aime point tout présomptueux plein de gloriole."},{"n":5099,"s":57,"a":24,"t":"Ceux qui sont avares et ordonnent aux gens l'avarice. Et quiconque se détourne... Allah Se suffit alors à Lui-même et Il est Digne de louange."},{"n":5100,"s":57,"a":25,"t":"Nous avons effectivement envoyé Nos Messagers avec des preuves évidentes, et fait descendre avec eux le Livre et la balance, afin que les gens établissent la justice. Et Nous avons fait descendre le fer, dans lequel il y a une force redoutable, aussi bien que des utilités pour les gens, et pour qu'Allah reconnaisse qui, dans l'Invisible, défendra Sa cause et celle de Ses Messagers. Certes, Allah est Fort et Puissant."},{"n":5101,"s":57,"a":26,"t":"Nous avons effectivement envoyé Noé et Abraham et accordé à leur descendance la prophétie et le Livre. Certains d'entre eux furent bien-guidés, tandis que beaucoup d'entre eux furent pervers."},{"n":5102,"s":57,"a":27,"t":"Ensuite, sur leurs traces, Nous avons fait suivre Nos [autres] messagers, et Nous les avons fait suivre de Jésus fils de Marie et lui avons apporté l'Evangile, et mis dans les cœurs de ceux qui le suivirent douceur et mansuétude. Le monachisme qu'ils inventèrent, Nous ne le leur avons nullement prescrit. [Ils devaient] seulement rechercher l'agrément d'Allah. Mais ils ne l'observèrent pas (ce monachisme) comme il se devait. Nous avons donné leur récompense à ceux d'entre eux qui crurent. Mais beaucoup d'entre eux furent des pervers."},{"n":5103,"s":57,"a":28,"t":"O Vous qui avez cru! Craignez Allah et croyez en Son messager pour qu'Il vous accorde deux parts de Sa miséricorde, et qu'Il vous assigne une lumière à l'aide de laquelle vous marcherez, et qu'Il vous pardonne, car Allah est Pardonneur et Très Miséricordieux."},{"n":5104,"s":57,"a":29,"t":"Cela afin que les gens du Livre sachent qu'ils ne peuvent en rien disposer de la grâce d'Allah et que la grâce est dans la main d'Allah. Il la donne à qui Il veut, et Allah est le Détenteur de la grâce immense."},{"n":5105,"s":58,"a":1,"t":"Allah a bien entendu la parole de celle qui discutait avec toi à propos de son époux et se plaignait à Allah. Et Allah entendait votre conversation, car Allah est Audient et Clairvoyant."},{"n":5106,"s":58,"a":2,"t":"Ceux d'entre vous qui répudient leurs femmes, en déclarant qu'elles sont pour eux comme le dos de leurs mères. alors qu'elles ne sont nullement leurs mères, car ils n'ont pour mères que celles qui les ont enfantés. Ils prononcent certes une parole blâmable et mensongère. Allah cependant est Indulgent et Pardonneur."},{"n":5107,"s":58,"a":3,"t":"Ceux qui comparent leurs femmes au dos de leurs mères puis reviennent sur ce qu'ils ont dit, doivent affranchir un esclave avant d'avoir aucun contact [conjugal] avec leur femme. C'est ce dont on vous exhorte. Et Allah est Parfaitement Connaisseur de ce que vous faites"},{"n":5108,"s":58,"a":4,"t":"Mais celui qui n'en trouve pas les moyens doit jeûner alors deux mois consécutifs avant d'avoir aucun contact [conjugal] avec sa femme. Mais s'il ne peut le faire non plus, alors qu'il nourrisse soixante pauvres. Cela, pour que vous croyiez en Allah et en Son messager. Voilà les limites imposées par Allah. Et les mécréants auront un châtiment douloureux."},{"n":5109,"s":58,"a":5,"t":"Ceux qui s'opposent à Allah et à Son messager seront culbutés comme furent culbutés leurs devanciers. Nous avons déjà fait descendre des preuves explicites, et les mécréants auront un châtiment avilissant,"},{"n":5110,"s":58,"a":6,"t":"le jour où Allah les ressuscitera tous, puis les informera de ce qu'ils ont fait Allah l'a dénombré et ils l'auront oublié. Allah est témoin de toute chose."},{"n":5111,"s":58,"a":7,"t":"Ne vois-tu pas qu'Allah sait ce qui est dans les cieux et sur la terre? Pas de conversation secrète entre trois sans qu'Il ne soit leur quatrième, ni entre cinq sans qu'Il n'y ne soit leur sixième, ni moins ni plus que cela sans qu'Il ne soit avec eux, là où ils se trouvent. Ensuite, Il les informera au Jour de la Résurrection, de ce qu'ils faisaient, car Allah est Omniscient."},{"n":5112,"s":58,"a":8,"t":"Ne vois-tu pas ceux à qui les conversations secrètes ont été interdites? Puis, ils retournent à ce qui leur a été interdit, et se concertent pour pécher, transgresser et désobéir au Messager. Et quand ils viennent à toi, ils te saluent d'une façon dont Allah ne t'a pas salué, et disent en eux-mêmes: «Pourquoi Allah ne nous châtie pas pour ce que nous disons?» L'Enfer leur suffira, où ils brûleront. Et quelle mauvaise destination!"},{"n":5113,"s":58,"a":9,"t":"O vous qui avez cru! Quand vous tenez des conversations secrètes, ne vous concertez pas pour pécher, transgresser et désobéir au Messager, mais concertez-vous dans la bonté et la piété. Et craignez Allah vers qui vous serez rassemblés."},{"n":5114,"s":58,"a":10,"t":"La conversation secrète n'est que [l'œuvre] du Diable pour attrister ceux qui ont cru. Mais il ne peut leur nuire en rien sans la permission d'Allah. Et c'est en Allah que les croyants doivent placer leur confiance."},{"n":5115,"s":58,"a":11,"t":"O vous qui avez cru! Quand on vous dit: «Faites place [aux autres] dans les assemblées», alors faites place. Allah vous ménagera une place (au Paradis). Et quand on vous dit de vous lever, levez-vous. Allah élèvera en degrés ceux d'entre vous qui auront cru et ceux qui auront reçu le savoir. Allah est Parfaitement Connaisseur de ce que vous faites."},{"n":5116,"s":58,"a":12,"t":"O vous qui avez cru! Quand vous avez un entretien confidentiel avec le Messager, faites précéder d'une aumône votre entretien: cela est meilleur pour vous et plus pur. Mais si vous n'en trouvez pas les moyens alors Allah est Pardonneur et très Miséricordieux!"},{"n":5117,"s":58,"a":13,"t":"Appréhendez-vous de faire précéder d'aumônes votre entretien? Mais, si vous ne l'avez pas fait et qu'Allah a accueilli votre repentir, alors accomplissez la Salât, acquittez la Zakât, et obéissez à Allah et à Son messager. Allah est Parfaitement Connaisseur de ce que vous faites."},{"n":5118,"s":58,"a":14,"t":"N'as-tu pas vu ceux qui ont pris pour alliés des gens contre qui Allah S'est courroucé? Ils ne sont ni des vôtres, ni des leurs; et ils jurent mensongèrement, alors qu'ils savent."},{"n":5119,"s":58,"a":15,"t":"Allah leur a préparé un dur châtiment. Ce qu'ils faisaient alors était très mauvais."},{"n":5120,"s":58,"a":16,"t":"Prenant leurs serments comme boucliers, ils obstruent le chemin d'Allah. Ils auront donc un châtiment avilissant."},{"n":5121,"s":58,"a":17,"t":"Ni leurs biens, ni leurs enfants ne leur seront d'aucune utilité contre la [punition] d'Allah. Ce sont les gens du Feu où ils demeureront éternellement."},{"n":5122,"s":58,"a":18,"t":"Le jour où Allah les ressuscitera tous, ils Lui jureront alors comme ils vous jurent à vous-mêmes, pensant s'appuyer sur quelque chose de solide. Mais ce sont eux les menteurs."},{"n":5123,"s":58,"a":19,"t":"Le Diable les a dominés et leur a fait oublier le rappel d'Allah. Ceux-là sont le parti du Diable et c'est le parti du Diable qui sont assurément les perdants."},{"n":5124,"s":58,"a":20,"t":"Ceux qui s'opposent à Allah et à Son messager seront parmi les plus humiliés."},{"n":5125,"s":58,"a":21,"t":"Allah a prescrit: «Assurément, Je triompherai, Moi ainsi que Mes Messagers». En vérité Allah est Fort et Puissant."},{"n":5126,"s":58,"a":22,"t":"Tu n'en trouveras pas, parmi les gens qui croient en Allah et au Jour dernier, qui prennent pour amis ceux qui s'opposent à Allah et à Son Messager, fussent-ils leurs pères, leurs fils, leurs frères ou les gens de leur tribu. Il a prescrit la foi dans leurs cœurs et Il les a aidés de Son secours. Il les fera entrer dans des Jardins sous lesquels coulent les ruisseaux, où ils demeureront éternellement. Allah les agrée et ils L'agréent. Ceux-là sont le parti d'Allah. Le parti d'Allah est celui de ceux qui réussissent."},{"n":5127,"s":59,"a":1,"t":"Ce qui est dans les cieux et ce qui est sur la terre glorifient Allah, et Il est le Puissant, le Sage."},{"n":5128,"s":59,"a":2,"t":"C'est Lui qui a expulsé de leurs maisons, ceux parmi les gens du Livre qui ne croyaient pas, lors du premier exode. Vous ne pensiez pas qu'ils partiraient, et ils pensaient qu'en vérité leurs forteresses les défendraient contre Allah. Mais Allah est venu à eux par où ils ne s'attendaient point, et a lancé la terreur dans leurs cœurs. Ils démolissaient leurs maisons de leurs propres mains, autant que des mains des croyants. Tirez-en une leçon, ô vous qui êtes doués de clairvoyance."},{"n":5129,"s":59,"a":3,"t":"Et si Allah n'avait pas prescrit contre eux l'expatriation, Il les aurait certainement châtiés ici-bas; et dans l'au-delà ils auront le châtiment du feu."},{"n":5130,"s":59,"a":4,"t":"Il en est ainsi parce qu'ils se sont dressés contre Allah et Son messager. Et quiconque se dresse contre Allah... alors, vraiment Allah est dur en punition."},{"n":5131,"s":59,"a":5,"t":"Tout palmier que vous avez coupé ou que vous avez laissé debout sur ses racines, c'est avec la permission d'Allah et afin qu'Il couvre ainsi d'ignominie les pervers."},{"n":5132,"s":59,"a":6,"t":"Le butin provenant de leurs biens et qu'Allah a accordé sans combat à Son Messager, vous n'y aviez engagé ni chevaux, ni chameaux; mais Allah, donne à Ses messagers la domination sur qui Il veut et Allah est Omnipotent."},{"n":5133,"s":59,"a":7,"t":"Le butin provenant [des biens] des habitants des cités, qu'Allah a accordé sans combat à Son Messager, appartient à Allah, au Messager, aux proches parents, aux orphelins, aux pauvres et au voyageur en détresse, afin que cela ne circule pas parmi les seuls riches d'entre vous. Prenez ce que le Messager vous donne; et ce qu'il vous interdit, abstenez-vous en; et craignez Allah car Allah est dur en punition."},{"n":5134,"s":59,"a":8,"t":"[Il appartient aussi] aux émigrés besogneux qui ont été expulsés de leurs demeures et de leurs biens, tandis qu'ils recherchaient une grâce et un agrément d'Allah, et qu'ils portaient secours à (la cause d') Allah et à Son Messager. Ceux-là sont les véridiques."},{"n":5135,"s":59,"a":9,"t":"Il [appartient également] à ceux qui, avant eux, se sont installés dans le pays et dans la foi, qui aiment ceux qui émigrent vers eux, et ne ressentent dans leurs cœurs aucune envie pour ce que [ces immigrés] ont reçu, et qui [les] préfèrent à eux-mêmes, même s'il y a pénurie chez eux. Quiconque se prémunit contre sa propre avarice, ceux-là sont ceux qui réussissent."},{"n":5136,"s":59,"a":10,"t":"Et [il appartient également] à ceux qui sont venus après eux en disant: «Seigneur, pardonne-nous, ainsi qu'à nos frères qui nous ont précédés dans la foi; et ne mets dans nos cœurs aucune rancœur pour ceux qui ont cru. Seigneur, Tu es Compatissant et Très Miséricordieux»."},{"n":5137,"s":59,"a":11,"t":"N'as-tu pas vu les hypocrites disant à leurs confrères qui ont mécru parmi les gens du Livre: «Si vous êtes chassés, nous partirons certes avec vous et nous n'obéirons jamais à personne contre vous; et si vous êtes attaqués, nous vous secourrons certes». Et Allah atteste qu'en vérité ils sont des menteurs."},{"n":5138,"s":59,"a":12,"t":"S'ils sont chassés, ils ne partiront pas avec eux; et s'ils sont attaqués, ils ne les secourront pas; et même s'ils allaient à leur secours, ils tourneraient sûrement le dos; puis ils ne seront point secourus."},{"n":5139,"s":59,"a":13,"t":"Vous jetez dans leurs cœurs plus de terreur qu'Allah. C'est qu'ils sont des gens qui ne comprennent pas."},{"n":5140,"s":59,"a":14,"t":"Tous ne vous combattront que retranchés dans des cités fortifiées ou de derrière des murailles. Leurs dissensions internes sont extrêmes. Tu les croirait unis, alors que leurs cœurs sont divisés. C'est qu'ils sont des gens qui ne raisonnent pas."},{"n":5141,"s":59,"a":15,"t":"Ils sont semblables à ceux qui, peu de temps avant eux, ont goûté la conséquence de leur comportement et ils auront un châtiment douloureux;"},{"n":5142,"s":59,"a":16,"t":"ils sont semblables au Diable quand il dit à l'homme: «Sois incrédule». Puis quand il a mécru, il dit: «Je te désavoue car je redoute Allah, le Seigneur de l'Univers»."},{"n":5143,"s":59,"a":17,"t":"Ils eurent pour destinée d'être tous deux dans le Feu pour y demeurer éternellement. Telle est la rétribution des injustes."},{"n":5144,"s":59,"a":18,"t":"O vous qui avez cru! Craignez Allah. Que chaque âme voit bien ce qu'elle a avancé pour demain. Et craignez Allah, car Allah est Parfaitement Connaisseur de ce que vous faites."},{"n":5145,"s":59,"a":19,"t":"Et ne soyez pas comme ceux qui ont oublié Allah; [Allah] leur a fait alors oublier leurs propres personnes; ceux-là sont les pervers."},{"n":5146,"s":59,"a":20,"t":"Ne seront pas égaux les gens du Feu et les gens du Paradis. Les gens du Paradis sont eux les gagnants."},{"n":5147,"s":59,"a":21,"t":"Si Nous avions fait descendre ce Coran sur une montagne, tu l'aurais vu s'humilier et se fendre par crainte d'Allah. Et ces paraboles Nous les citons aux gens afin qu'ils réfléchissent."},{"n":5148,"s":59,"a":22,"t":"C'est Lui Allah. Nulle divinité autre que Lui, le Connaisseur de l'Invisible tout comme du visible. C'est Lui, le Tout Miséricordieux, le Très Miséricordieux."},{"n":5149,"s":59,"a":23,"t":"C'est Lui, Allah. Nulle divinité autre que Lui; Le Souverain, Le Pur, L'Apaisant, Le Rassurant, Le Prédominant, Le Tout Puissant, Le Contraignant, L'Orgueilleux. Gloire à Allah! Il transcende ce qu'ils Lui associent."},{"n":5150,"s":59,"a":24,"t":"C'est Lui Allah, le Créateur, Celui qui donne un commencement à toute chose, le Formateur. A Lui les plus beaux noms. Tout ce qui est dans les cieux et la terre Le glorifie. Et c'est Lui le Puissant, le Sage."},{"n":5151,"s":60,"a":1,"t":"O vous qui avez cru! Ne prenez pas pour alliés Mon ennemi et le vôtre, leur offrant l'amitié, alors qu'ils ont nié ce qui vous est parvenu de la vérité. Ils expulsent le Messager et vous-mêmes parce que vous croyez en Allah, votre Seigneur. Si vous êtes sortis pour lutter dans Mon chemin et pour rechercher Mon agrément, leur témoignerez-vous secrètement de l'amitié, alors que Je connais parfaitement ce que vous cachez et ce que vous divulguez? Et quiconque d'entre vous le fait s'égare de la droiture du sentier."},{"n":5152,"s":60,"a":2,"t":"S'ils vous dominent, ils seront des ennemis pour vous et étendront en mal leurs mains et leurs langues vers vous; et ils aimeraient que vous deveniez mécréants."},{"n":5153,"s":60,"a":3,"t":"Ni vos proches parents ni vos enfants ne vous seront d'aucune utilité le Jour de la Résurrection, Il [Allah] décidera entre vous, et Allah est Clairvoyant sur ce que vous faites."},{"n":5154,"s":60,"a":4,"t":"Certes, vous avez eu un bel exemple [à suivre] en Abraham et en ceux qui étaient avec lui, quand ils dirent à leur peuple: «Nous vous désavouons, vous et ce que vous adorez en dehors d'Allah. Nous vous renions. Entre vous et nous, l'inimitié et la haine sont à jamais déclarées jusqu'à ce que vous croyiez en Allah, seul». Exception faite de la parole d'Abraham [adressée] à son père: «J'implorerai certes, le pardon [d'Allah] en ta faveur bien que je ne puisse rien pour toi auprès d'Allah». «Seigneur, c'est en Toi que nous mettons notre confiance et à Toi nous revenons [repentants]. Et vers Toi est le Devenir."},{"n":5155,"s":60,"a":5,"t":"Seigneur, ne fais pas de nous [un sujet] de tentation pour ceux qui ont mécru; et pardonne-nous, Seigneur, car c'est Toi le Puissant, le Sage»."},{"n":5156,"s":60,"a":6,"t":"Vous avez certes eu en eux un bel exemple [à suivre], pour celui qui espère en Allah et en le Jour dernier; mais quiconque se détourne... alors Allah Se suffit à Lui-même et est Digne de louange."},{"n":5157,"s":60,"a":7,"t":"Il se peut qu'Allah établisse de l'amitié entre vous et ceux d'entre eux dont vous avez été les ennemis. Et Allah est Omnipotent et Allah est Pardonneur et Très Miséricordieux."},{"n":5158,"s":60,"a":8,"t":"Allah ne vous défend pas d'être bienfaisants et équitables envers ceux qui ne vous ont pas combattus pour la religion et ne vous ont pas chassés de vos demeures. Car Allah aime les équitables."},{"n":5159,"s":60,"a":9,"t":"Allah vous défend seulement de prendre pour alliés ceux qui vous ont combattus pour la religion, chassés de vos demeures et ont aidé à votre expulsion. Et ceux qui les prennent pour alliés sont les injustes."},{"n":5160,"s":60,"a":10,"t":"O vous qui avez cru! Quand les croyantes viennent à vous en émigrées, éprouvez-les; Allah connaît mieux leur foi; si vous constatez qu'elles sont croyantes, ne les renvoyez pas aux mécréants. Elles ne sont pas licites [en tant qu'épouses] pour eux, et eux non plus ne sont pas licites [en tant qu'époux] pour elles. Et rendez-leur ce qu'ils ont dépensé (comme mahr). Il ne vous sera fait aucun grief en vous mariant avec elles quand vous leur aurez donné leur mahr. Et ne gardez pas de liens conjugaux avec les mécréantes. Réclamez ce que vous avez dépensé et que (les mécréants) aussi réclament ce qu'ils ont dépensé. Tel est le jugement d'Allah par lequel Il juge entre vous, et Allah est Omniscient et Sage."},{"n":5161,"s":60,"a":11,"t":"Et si quelqu'une de vos épouses s'échappe vers les mécréants, et que vous fassiez des représailles, restituez à ceux dont les épouses sont parties autant que ce qu'ils avaient dépensé. Craignez Allah en qui vous croyez."},{"n":5162,"s":60,"a":12,"t":"O Prophète! Quand les croyantes viennent te prêter serment d'allégeance, [et en jurent] qu'elles n'associeront rien à Allah, qu'elles ne voleront pas, qu'elles ne se livreront pas à l'adultère, qu'elles ne tueront pas leurs propres enfants, qu'elles ne commettront aucune infamie ni avec leurs mains ni avec leurs pieds et qu'elles ne désobéiront pas en ce qui est convenable, alors reçois leur serment d'allégeance, et implore d'Allah le pardon pour elles. Allah est certes, Pardonneur et Très Miséricordieux."},{"n":5163,"s":60,"a":13,"t":"O vous qui avez cru! Ne prenez pas pour alliés des gens contre lesquels Allah est courroucé et qui désespèrent de l'au-delà, tout comme les mécréants désespèrent des gens des tombeaux."},{"n":5164,"s":61,"a":1,"t":"Ce qui est dans les cieux et ce qui est sur la terre glorifient Allah, et Il est le Puissant, le Sage."},{"n":5165,"s":61,"a":2,"t":"O vous qui avez cru! Pourquoi dites-vous ce que vous ne faites pas?"},{"n":5166,"s":61,"a":3,"t":"C'est une grande abomination auprès d'Allah que de dire ce que vous ne faites pas."},{"n":5167,"s":61,"a":4,"t":"Allah aime ceux qui combattent dans Son chemin en rang serré pareils à un édifice renforcé."},{"n":5168,"s":61,"a":5,"t":"Et quand Moïse dit à son peuple: «O mon peuple! Pourquoi me maltraitez-vous alors que vous savez que je suis vraiment le Messager d'Allah [envoyé] à vous?» Puis quand ils dévièrent, Allah fit dévier leurs cœurs, car Allah ne guide pas les gens pervers."},{"n":5169,"s":61,"a":6,"t":"Et quand Jésus fils de Marie dit: «O Enfants d'Israël, je suis vraiment le Messager d'Allah [envoyé] à vous, confirmateur de ce qui, dans la Thora, est antérieur à moi, et annonciateur d'un Messager à venir après moi, dont le nom sera «Ahmad». Puis quand celui-ci vint à eux avec des preuves évidentes, ils dirent: «C'est là une magie manifeste»."},{"n":5170,"s":61,"a":7,"t":"Et qui est plus injuste que celui qui invente un mensonge contre Allah, alors qu'il est appelé à l'Islam? Et Allah ne guide pas les gens injustes."},{"n":5171,"s":61,"a":8,"t":"Ils veulent éteindre de leurs bouches la lumière d'Allah, alors qu'Allah parachèvera Sa lumière en dépit de l'aversion des mécréants."},{"n":5172,"s":61,"a":9,"t":"C'est Lui qui a envoyé Son messager avec la guidée et la Religion de Vérité, pour la placer au-dessus de toute autre religion, en dépit de l'aversion des associateurs."},{"n":5173,"s":61,"a":10,"t":"O vous qui avez cru! vous indiquerai-je un commerce qui vous sauvera d'un châtiment douloureux?"},{"n":5174,"s":61,"a":11,"t":"Vous croyez en Allah et en Son messager et vous combattez avec vos biens et vos personnes dans le chemin d'Allah, et cela vous est bien meilleur, si vous saviez!"},{"n":5175,"s":61,"a":12,"t":"Il vous pardonnera vos péchés et vous fera entrer dans des Jardins sous lesquels coulent les ruisseaux, et dans des demeures agréables dans les jardins d'Eden. Voilà l'énorme succès"},{"n":5176,"s":61,"a":13,"t":"et Il vous accordera d'autres choses encore que vous aimez bien: un secours [venant] d'Allah et une victoire prochaine. Et annonce la bonne nouvelle aux croyants."},{"n":5177,"s":61,"a":14,"t":"O vous qui avez cru! Soyez les alliés d'Allah, à l'instar de ce que Jésus fils de Marie a dit aux apôtres: «Qui sont mes alliés (pour la cause) d'Allah?» - Les apôtres dirent: «Nous sommes les alliés d'Allah». Un groupe des Enfants d'Israël crut, tandis qu'un groupe nia. Nous aidâmes donc ceux qui crurent contre leur ennemi, et ils triomphèrent."},{"n":5178,"s":62,"a":1,"t":"Ce qui est dans les cieux et ce qui est sur la terre glorifient Allah, le Souverain, le Pur, le Puissant, le Sage."},{"n":5179,"s":62,"a":2,"t":"C'est Lui qui a envoyé à des gens sans Livre (les Arabes) un Messager des leurs qui leur récite Ses versets, les purifie et leur enseigne le Livre et la Sagesse, bien qu'ils étaient auparavant dans un égarement évident,"},{"n":5180,"s":62,"a":3,"t":"ainsi qu'à d'autres parmi ceux qui ne les ont pas encore rejoints. C'est Lui le Puissant, le Sage."},{"n":5181,"s":62,"a":4,"t":"Telle est la grâce d'Allah qu'Il donne à qui Il veut. Et Allah est le Détenteur de l'énorme grâce."},{"n":5182,"s":62,"a":5,"t":"Ceux qui ont été chargés de la Thora mais qui ne l'ont pas appliquée sont pareils à l'âne qui porte des livres. Quel mauvais exemple que celui de ceux qui traitent de mensonges les versets d'Allah et Allah ne guide pas les gens injustes."},{"n":5183,"s":62,"a":6,"t":"Dis: «O vous qui pratiquez le judaïsme! Si vous prétendez être les bien-aimés d'Allah à l'exclusion des autres, souhaitez, donc la mort, si vous êtes véridiques»."},{"n":5184,"s":62,"a":7,"t":"Or, ils ne la souhaiteront jamais, à cause de ce que leurs mains ont préparé. Allah cependant connaît bien les injustes."},{"n":5185,"s":62,"a":8,"t":"Dis: «La mort que vous fuyez va certes vous rencontrer. Ensuite vous serez ramenés à Celui qui connaît parfaitement le monde Invisible et le monde visible et qui vous informera alors de ce que vous faisiez»."},{"n":5186,"s":62,"a":9,"t":"O vous qui avez cru! Quand on appelle à la Salât du jour du Vendredi, accourez à l'invocation d'Allah et laissez tout négoce. Cela est bien meilleur pour vous, si vous saviez!"},{"n":5187,"s":62,"a":10,"t":"Puis quand la Salât est achevée, dispersez-vous sur terre et recherchez [quelque effet] de la grâce d'Allah, et invoquez beaucoup Allah afin que vous réussissiez."},{"n":5188,"s":62,"a":11,"t":"Quand ils entrevoient quelque commerce ou quelque divertissement, ils s'y dispersent et te laissent debout. Dis: «Ce qui est auprès d'Allah est bien meilleur que le divertissement et le commerce, et Allah est le Meilleur des pourvoyeurs»."},{"n":5189,"s":63,"a":1,"t":"Quand les hypocrites viennent à toi, ils disent: «Nous attestons que tu es certes le Messager d'Allah» Allah sait que tu es vraiment Son messager; et Allah atteste que les hypocrites sont assurément des menteurs."},{"n":5190,"s":63,"a":2,"t":"Ils prennent leurs serments pour bouclier et obstruent le chemin d'Allah. Quelles mauvaises choses que ce qu'ils faisaient!"},{"n":5191,"s":63,"a":3,"t":"C'est parce qu'en vérité ils ont cru, puis rejeté la foi. Leurs cœurs donc, ont été scellés, de sorte qu'ils ne comprennent rien."},{"n":5192,"s":63,"a":4,"t":"Et quand tu les vois, leurs corps t'émerveillent; et s'ils parlent tu écoutes leur parole. Ils sont comme des bûches appuyées (contre des murs) et ils pensent que chaque cri est dirigé contre eux. L'ennemi c'est eux. Prends y garde. Qu'Allah les extermine! Comme les voilà détournés (du droit chemin)."},{"n":5193,"s":63,"a":5,"t":"Et quand on leur dit: «Venez que le Messager d'Allah implore le pardon pour vous», ils détournent leurs têtes, et tu les vois se détourner tandis qu'ils s'enflent d'orgueil."},{"n":5194,"s":63,"a":6,"t":"C'est égal, pour eux, que tu implores le pardon pour eux ou que tu ne le fasses pas: Allah ne leur pardonnera jamais, car Allah ne guide pas les gens pervers."},{"n":5195,"s":63,"a":7,"t":"Ce sont eux qui disent: «Ne dépensez point pour ceux qui sont auprès du Messager d'Allah, afin qu'ils se dispersent». Et c'est à Allah qu'appartiennent les trésors des cieux et de la terre, mais les hypocrites ne comprennent pas."},{"n":5196,"s":63,"a":8,"t":"Ils disent: «Si nous retournons à Médine, le plus puissant en fera assurément sortir le plus humble». Or c'est à Allah qu'est la puissance ainsi qu'à Son messager et aux croyants. Mais les hypocrites ne le savent pas."},{"n":5197,"s":63,"a":9,"t":"O vous qui avez cru! Que ni vos biens ni vos enfants ne vous distraient du rappel d'Allah. Et quiconque fait cela... alors ceux-là seront les perdants."},{"n":5198,"s":63,"a":10,"t":"Et dépensez de ce que Nous vous avons octroyé avant que la mort ne vienne à l'un de vous et qu'il dise alors: «Seigneur! si seulement Tu m'accordais un court délai: je ferais l'aumône et serais parmi les gens de bien»."},{"n":5199,"s":63,"a":11,"t":"Allah cependant n'accorde jamais de délai à une âme dont le terme est arrivé. Et Allah est Parfaitement Connaisseur de ce que vous faites."},{"n":5200,"s":64,"a":1,"t":"Ce qui est dans les cieux et ce qui est sur la terre glorifient Allah. A Lui la royauté et à Lui les louanges. Et Il est Omnipotent."},{"n":5201,"s":64,"a":2,"t":"C'est Lui qui vous a créés. Parmi vous [il y a] mécréant et croyant. Allah observe parfaitement ce que vous faites."},{"n":5202,"s":64,"a":3,"t":"Il a créé les cieux et la terre en toute vérité et vous a donné votre forme et quelle belle forme Il vous a donnée! Et vers Lui est le devenir."},{"n":5203,"s":64,"a":4,"t":"Il sait ce qui est dans les cieux et la terre, et Il sait ce que vous cachez ainsi que ce que vous divulguez. Et Allah connaît bien le contenu des poitrines."},{"n":5204,"s":64,"a":5,"t":"Ne vous est-elle pas parvenue, la nouvelle de ceux qui auparavant ont mécru et qui ont goûté la conséquence néfaste de leur acte; ils auront en outre un châtiment douloureux."},{"n":5205,"s":64,"a":6,"t":"Il en est ainsi parce que leurs messagers leur venaient avec des preuves évidentes, et qu'ils ont dit: «Sont-ce des hommes qui nous guideront?» Ils mécrurent alors et se détournèrent et Allah Se passa [d'eux] et Allah Se suffit à Lui-même et Il est Digne de louange."},{"n":5206,"s":64,"a":7,"t":"Ceux qui ont mécru prétendent qu'ils ne seront point ressuscités. Dis: «Mais si! Par mon Seigneur! Vous serez très certainement ressuscités; puis vous serez certes informés de ce que vous faisiez. Et cela est facile pour Allah»."},{"n":5207,"s":64,"a":8,"t":"Croyez en Allah donc et en Son messager, ainsi qu'en la Lumière [le Coran] que Nous avons fait descendre. Et Allah est Parfaitement Connaisseur de ce que vous faites."},{"n":5208,"s":64,"a":9,"t":"Le jour où Il vous réunira pour le jour du Rassemblement, ce sera le jour de la grande perte. Et celui qui croit en Allah et accomplit les bonnes œuvres, Il lui effacera ses mauvaises actions et le fera entrer dans des Jardins sous lesquels coulent les ruisseaux où ils demeureront éternellement. Voilà l'énorme succès!"},{"n":5209,"s":64,"a":10,"t":"Et ceux qui ont mécru et traité de mensonges Nos versets, ceux-là sont les gens du Feu où ils demeureront éternellement. Et quelle mauvaise destination!"},{"n":5210,"s":64,"a":11,"t":"Nul malheur n'atteint [l'homme] que par la permission d'Allah. Et quiconque croit en Allah, [Allah] guide son cœur. Allah est Omniscient."},{"n":5211,"s":64,"a":12,"t":"Obéissez à Allah et obéissez au Messager et si vous vous détournez... il n'incombe à Notre messager que de transmettre en clair (son message)."},{"n":5212,"s":64,"a":13,"t":"Allah nulle autre divinité que Lui! Et c'est à Allah que les croyants [doivent] s'en remettre."},{"n":5213,"s":64,"a":14,"t":"O vous qui avez cru, vous avez de vos épouses et de vos enfants un ennemi [une tentation]. Prenez-y garde donc. Mais si vous [les] excusez, passez sur [leurs] fautes et [leur] pardonnez, sachez qu'Allah est Pardonneur, Très Miséricordieux."},{"n":5214,"s":64,"a":15,"t":"Vos biens et vos enfants ne sont qu'une tentation, alors qu'auprès d'Allah est une énorme récompense."},{"n":5215,"s":64,"a":16,"t":"Craignez Allah, donc autant que vous pouvez, écoutez, obéissez et faites largesses. Ce sera un bien pour vous. Et quiconque a été protégé contre sa propre avidité... ceux-là sont ceux qui réussissent."},{"n":5216,"s":64,"a":17,"t":"Si vous faites à Allah un prêt sincère, Il le multipliera pour vous et vous pardonnera. Allah cependant est très Reconnaissant et Indulgent."},{"n":5217,"s":64,"a":18,"t":"Il est le Connaisseur du monde Invisible et visible, et Il est le Puissant, le Sage."},{"n":5218,"s":65,"a":1,"t":"O Prophète! Quand vous répudiez les femmes, répudiez-les conformément à leur période d'attente prescrite; et comptez la période; et craignez Allah votre Seigneur. Ne les faites pas sortir de leurs maisons, et qu'elles n'en sortent pas, à moins qu'elles n'aient commis une turpitude prouvée. Telles sont les lois d'Allah. Quiconque cependant transgresse les lois d'Allah, se fait du tort à lui-même. Tu ne sais pas si d'ici là Allah ne suscitera pas quelque chose de nouveau!"},{"n":5219,"s":65,"a":2,"t":"Puis quand elles atteignent le terme prescrit, retenez-les de façon convenable, ou séparez-vous d'elles de façon convenable; et prenez deux hommes intègres parmi vous comme témoins. Et acquittez-vous du témoignage envers Allah. Voilà ce à quoi est exhorté celui qui croit en Allah et au Jour dernier. Et quiconque craint Allah, Il Lui donnera une issue favorable,"},{"n":5220,"s":65,"a":3,"t":"et lui accordera Ses dons par [des moyens] sur lesquels il ne comptait pas. Et quiconque place sa confiance en Allah, Il [Allah] lui suffit. Allah atteint ce qu'Il Se propose, et Allah a assigné une mesure à chaque chose."},{"n":5221,"s":65,"a":4,"t":"Si vous avez des doutes à propos (de la période d'attente) de vos femmes qui n'espèrent plus avoir de règles, leur délai est de trois mois. De même pour celles qui n'ont pas encore de règles. Et quant à celles qui sont enceintes, leur période d'attente se terminera à leur accouchement. Quiconque craint Allah cependant, Il lui facilite les choses."},{"n":5222,"s":65,"a":5,"t":"Tel est le commandement d'Allah qu'Il a fait descendre vers vous. Quiconque craint Allah cependant, Il lui efface ses fautes et lui accorde une grosse récompense."},{"n":5223,"s":65,"a":6,"t":"Et faites que ces femmes habitent où vous habitez, et suivant vos moyens. Et ne cherchez pas à leur nuire en les contraignant à vivre à l'étroit. Et si elles sont enceintes, pourvoyez à leurs besoins jusqu'à ce qu'elles aient accouché. Puis, si elles allaitent [l'enfant né] de vous, donnez-leur leurs salaires. Et concertez vous [à ce sujet] de façon convenable. Et si vous rencontrez des difficultés réciproques, alors, une autre allaitera pour lui."},{"n":5224,"s":65,"a":7,"t":"Que celui qui est aisé dépense de sa fortune; et que celui dont les biens sont restreints dépense selon ce qu'Allah lui a accordé. Allah n'impose à personne que selon ce qu'Il lui a donné, et Allah fera succéder l'aisance à la gêne."},{"n":5225,"s":65,"a":8,"t":"Que de cités ont refusé avec insolence le commandement de leur Seigneur et de Ses messagers! Nous leur en demandâmes compte avec sévérité, et les châtiâmes d'un châtiment inouï."},{"n":5226,"s":65,"a":9,"t":"Elles goûtèrent donc la conséquence de leur comportement. Et le résultat final de leurs actions fut [leur] perdition."},{"n":5227,"s":65,"a":10,"t":"Allah a préparé pour eux un dur châtiment. Craignez Allah donc, ô vous qui êtes doués d'intelligence, vous qui avez la foi. Certes, Allah a fait descendre vers vous un rappel,"},{"n":5228,"s":65,"a":11,"t":"un Messager qui vous récite les versets d'Allah comme preuves claires, afin de faire sortir ceux qui croient et accomplissent les bonnes œuvres des ténèbres à la lumière. Et quiconque croit en Allah et fait le bien, Il le fait entrer aux Jardins sous lesquels coulent les ruisseaux, pour y demeurer éternellement. Allah lui a fait une belle attribution."},{"n":5229,"s":65,"a":12,"t":"Allah qui a créé sept cieux et autant de terres. Entre eux [Son] commandement descend, afin que vous sachiez qu'Allah est en vérité Omnipotent et qu'Allah a embrassé toute chose de [Son] savoir."},{"n":5230,"s":66,"a":1,"t":"O Prophète! Pourquoi, en recherchant l'agrément de tes femmes, t'interdis-tu ce qu'Allah t'a rendu licite? Et Allah est Pardonneur, Très Miséricordieux."},{"n":5231,"s":66,"a":2,"t":"Allah vous a prescrit certes, de vous libérer de vos serments. Allah est votre Maître; et c'est Lui l'Omniscient, le Sage."},{"n":5232,"s":66,"a":3,"t":"Lorsque le Prophète confia un secret à l'une de ses épouses et qu'elle l'eut divulgué et qu'Allah l'en eut informé, celui-ci en fit connaître une partie et passa sur une partie. Puis, quand il l'en eut informée elle dit: «Qui t'en a donné nouvelle?» Il dit: «C'est l'Omniscient, le Parfaitement Connaisseur qui m'en a avisé»."},{"n":5233,"s":66,"a":4,"t":"Si vous vous repentez à Allah c'est que vos cœurs ont fléchi. Mais si vous vous soutenez l'une l'autre contre le Prophète, alors ses alliés seront Allah, Gabriel et les vertueux d'entre les croyants, et les Anges sont par surcroît [son] soutien."},{"n":5234,"s":66,"a":5,"t":"S'Il vous répudie, il se peut que son Seigneur lui donne en échange des épouses meilleures que vous, musulmanes, croyantes, obéissantes, repentantes, adoratrices, jeûneuses, déjà mariées ou vierges."},{"n":5235,"s":66,"a":6,"t":"O vous qui avez cru! Préservez vos personnes et vos familles, d'un Feu dont le combustible sera les gens et les pierres, surveillé par des Anges rudes, durs, ne désobéissant jamais à Allah en ce qu'Il leur commande, et faisant strictement ce qu'on leur ordonne."},{"n":5236,"s":66,"a":7,"t":"O vous qui avez mécru! Ne vous excusez pas aujourd'hui. Vous ne serez rétribués que selon ce que vous œuvriez."},{"n":5237,"s":66,"a":8,"t":"O vous qui avez cru! Repentez-vous à Allah d'un repentir sincère. Il se peut que votre Seigneur vous efface vos fautes et qu'Il vous fasse entrer dans des Jardins sous lesquels coulent les ruisseaux, le jour où Allah épargnera l'ignominie au Prophète et à ceux qui croient avec lui. Leur lumière courra devant eux et à leur droite; ils diront: «Seigneur, parfais-nous notre lumière et pardonne-nous. Car Tu es Omnipotent»."},{"n":5238,"s":66,"a":9,"t":"O Prophète! Mène la lutte contre les mécréants et les hypocrites et sois rude à leur égard. Leur refuge sera l'Enfer, et quelle mauvaise destination!"},{"n":5239,"s":66,"a":10,"t":"Allah a cité en parabole pour ceux qui ont mécru la femme de Noé et la femme de Lot. Elles étaient sous l'autorité de deux vertueux de Nos serviteurs. Toutes deux les trahirent et ils ne furent d'aucune aide pour [ces deux femmes] vis-à-vis d'Allah. Et il [leur] fut dit: «Entrez au Feu toutes les deux, avec ceux qui y entrent»,"},{"n":5240,"s":66,"a":11,"t":"et Allah a cité en parabole pour ceux qui croient, la femme de Pharaon, quand elle dit «Seigneur, construis-moi auprès de Toi une maison dans le Paradis, et sauve-moi de Pharaon et de son œuvre; et sauve-moi des gens injustes»."},{"n":5241,"s":66,"a":12,"t":"De même, Marie, la fille d''Imran qui avait préservé sa virginité; Nous y insufflâmes alors de Notre Esprit. Elle avait déclaré véridiques les paroles de son Seigneur ainsi que Ses Livres: elle fut parmi les dévoués."},{"n":5242,"s":67,"a":1,"t":"Béni soit celui dans la main de qui est la royauté, et Il est Omnipotent."},{"n":5243,"s":67,"a":2,"t":"Celui qui a créé la mort et la vie afin de vous éprouver (et de savoir) qui de vous est le meilleur en œuvre, et c'est Lui le Puissant, le Pardonneur."},{"n":5244,"s":67,"a":3,"t":"Celui qui a créé sept cieux superposés sans que tu voies de disproportion en la création du Tout Miséricordieux. Ramène [sur elle] le regard. Y vois-tu une brèche quelconque?"},{"n":5245,"s":67,"a":4,"t":"Puis, retourne ton regard à deux fois: le regard te reviendra humilié et frustré."},{"n":5246,"s":67,"a":5,"t":"Nous avons effectivement embelli le ciel le plus proche avec des lampes [des étoiles] dont Nous avons fait des projectiles pour lapider les diables et Nous leur avons préparé le châtiment de la Fournaise."},{"n":5247,"s":67,"a":6,"t":"Ceux qui ont mécru à leur Seigneur auront le châtiment de l'Enfer. Et quelle mauvaise destination!"},{"n":5248,"s":67,"a":7,"t":"Quand ils y seront jetés, ils lui entendront un gémissement, tandis qu'il bouillonne."},{"n":5249,"s":67,"a":8,"t":"Peu s'en faut que, de rage, il n'éclate. Toutes les fois qu'un groupe y est jeté, ses gardiens leur demandent: «Quoi! ne vous est-il pas venu d'avertisseur?»"},{"n":5250,"s":67,"a":9,"t":"Ils dirent: «Mais si! un avertisseur nous était venu certes, mais nous avons crié au mensonge et avons dit: Allah n'a rien fait descendre: vous n'êtes que dans un grand égarement»."},{"n":5251,"s":67,"a":10,"t":"Et ils dirent: «Si nous avions écouté ou raisonné, nous ne serions pas parmi les gens de la Fournaise»."},{"n":5252,"s":67,"a":11,"t":"Ils ont reconnu leur péché. Que les gens de la Fournaise soient anéantis à jamais."},{"n":5253,"s":67,"a":12,"t":"Ceux qui redoutent leur Seigneur bien qu'ils ne L'aient jamais vu auront un pardon et une grande récompense."},{"n":5254,"s":67,"a":13,"t":"Que vous cachiez votre parole ou la divulguiez Il connaît bien le contenu des poitrines."},{"n":5255,"s":67,"a":14,"t":"Ne connaît-Il pas ce qu'Il a créé alors que c'est Lui le Compatissant, le Parfaitement Connaisseur."},{"n":5256,"s":67,"a":15,"t":"C'est Lui qui vous a soumis la terre: parcourez donc ses grandes étendues. Mangez de ce qu'Il vous fournit. Vers Lui est la Résurrection."},{"n":5257,"s":67,"a":16,"t":"Etes-vous à l'abri que Celui qui est au ciel vous enfouisse en la terre? Et voici qu'elle tremble!"},{"n":5258,"s":67,"a":17,"t":"Ou êtes-vous à l'abri que Celui qui est au ciel envoie contre vous un ouragan de pierres? Vous saurez ainsi quel fut Mon avertissement."},{"n":5259,"s":67,"a":18,"t":"En effet, ceux d'avant eux avaient crié au mensonge. Quelle fut alors Ma réprobation!"},{"n":5260,"s":67,"a":19,"t":"N'ont-ils pas vu les oiseaux au-dessus d'eux, déployant et repliant leurs ailes tour à tour? Seul le Tout Miséricordieux les soutient. Car Il est sur toute chose, Clairvoyant."},{"n":5261,"s":67,"a":20,"t":"Quel est celui qui constituerait pour vous une armée [capable] de vous secourir, en dehors du Tout Miséricordieux? En vérité les mécréants sont dans l'illusion complète."},{"n":5262,"s":67,"a":21,"t":"Ou quel est celui qui vous donnera votre subsistance s'Il s'arrête de fournir Son attribution? Mais ils persistent dans leur insolence et dans leur répulsion."},{"n":5263,"s":67,"a":22,"t":"Qui est donc mieux guidé? Celui qui marche face contre terre ou celui qui marche redressé sur un chemin droit."},{"n":5264,"s":67,"a":23,"t":"Dis: «C'est Lui qui vous a créés et vous a donné l'ouïe, les yeux et les cœurs». Mais vous êtes rarement reconnaissants!"},{"n":5265,"s":67,"a":24,"t":"Dis: «C'est Lui qui vous a répandus sur la terre, et c'est vers Lui que vous serez rassemblés»."},{"n":5266,"s":67,"a":25,"t":"Et ils disent: «A quand cette promesse si vous êtes véridiques?»"},{"n":5267,"s":67,"a":26,"t":"Dis: «Allah seul [en] a la connaissance. Et moi je ne suis qu'un avertisseur clair»."},{"n":5268,"s":67,"a":27,"t":"Puis, quand ils verront (le châtiment) de près, les visages de ceux qui ont mécru seront affligés. Et il leur sera dit: «Voilà ce que vous réclamiez»."},{"n":5269,"s":67,"a":28,"t":"Dis: «Que vous en semble? Qu'Allah me fasse périr ainsi que ceux qui sont avec moi ou qu'Il nous fasse miséricorde, qui protégera alors les mécréants d'un châtiment douloureux?»"},{"n":5270,"s":67,"a":29,"t":"Dis: «C'est Lui, le Tout Miséricordieux. Nous croyons en Lui et c'est en Lui que nous plaçons notre confiance. Vous saurez bientôt qui est dans un égarement évident»."},{"n":5271,"s":67,"a":30,"t":"Dis: «Que vous en semble? Si votre eau était absorbée au plus profond de la terre, qui donc vous apporterait de l'eau de source?»"},{"n":5272,"s":68,"a":1,"t":"Nûn. Par la plume et ce qu'ils écrivent!"},{"n":5273,"s":68,"a":2,"t":"Tu (Muhammad) n'es pas, par la grâce de ton Seigneur, un possédé."},{"n":5274,"s":68,"a":3,"t":"Et il y aura pour toi certes, une récompense jamais interrompue."},{"n":5275,"s":68,"a":4,"t":"Et tu es certes, d'une moralité éminente."},{"n":5276,"s":68,"a":5,"t":"Tu verras et ils verront"},{"n":5277,"s":68,"a":6,"t":"qui d'entre vous a perdu la raison."},{"n":5278,"s":68,"a":7,"t":"C'est ton Seigneur qui connaît mieux ceux qui s'égarent de Son chemin, et Il connaît mieux ceux qui suivent la bonne voie."},{"n":5279,"s":68,"a":8,"t":"N'obéis pas à ceux qui crient au mensonge,"},{"n":5280,"s":68,"a":9,"t":"Ils aimeraient bien que tu transiges avec eux afin qu'ils transigent avec toi."},{"n":5281,"s":68,"a":10,"t":"Et n'obéis à aucun grand jureur, méprisable,"},{"n":5282,"s":68,"a":11,"t":"grand diffamateur, grand colporteur de médisance,"},{"n":5283,"s":68,"a":12,"t":"grand empêcheur du bien, transgresseur, grand pécheur,"},{"n":5284,"s":68,"a":13,"t":"au cœur dur, et en plus de cela bâtard."},{"n":5285,"s":68,"a":14,"t":"Même s'il est doté de richesses et (de nombreux) enfants."},{"n":5286,"s":68,"a":15,"t":"Quand Nos versets lui sont récités, il dit: «Des contes d'anciens»."},{"n":5287,"s":68,"a":16,"t":"Nous le marquerons sur le museau [nez]."},{"n":5288,"s":68,"a":17,"t":"Nous les avons éprouvés comme Nous avons éprouvé les propriétaires du verger qui avaient juré d'en faire la récolte au matin,"},{"n":5289,"s":68,"a":18,"t":"sans dire: «Si Allah le veut»."},{"n":5290,"s":68,"a":19,"t":"Une calamité de la part de ton Seigneur tomba dessus pendant qu'ils dormaient,"},{"n":5291,"s":68,"a":20,"t":"et le matin, ce fut comme si tout avait été rasé."},{"n":5292,"s":68,"a":21,"t":"Le [lendemain] matin, ils s'appelèrent les uns les autres:"},{"n":5293,"s":68,"a":22,"t":"«Partez tôt à votre champ si vous voulez le récolter»."},{"n":5294,"s":68,"a":23,"t":"Ils allèrent donc, tout en parlant entre eux à voix basse:"},{"n":5295,"s":68,"a":24,"t":"«Ne laissez aucun pauvre y entrer aujourd'hui»."},{"n":5296,"s":68,"a":25,"t":"Ils partirent de bonne heure décidés à user d'avarice [envers les pauvres], convaincus que cela était en leur pouvoir."},{"n":5297,"s":68,"a":26,"t":"Puis, quand ils le virent [le jardin], ils dirent: «vraiment, nous avons perdu notre chemin."},{"n":5298,"s":68,"a":27,"t":"Ou plutôt nous sommes frustrés»."},{"n":5299,"s":68,"a":28,"t":"Le plus juste d'entre eux dit: «Ne vous avais-je pas dit: Si seulement vous avez rendu gloire à Allah!»"},{"n":5300,"s":68,"a":29,"t":"Ils dirent: «Gloire à notre Seigneur! Oui, nous avons été des injustes»."},{"n":5301,"s":68,"a":30,"t":"Puis ils s'adressèrent les uns aux autres, se faisant des reproches."},{"n":5302,"s":68,"a":31,"t":"Ils dirent: «Malheur à nous! Nous avons été des rebelles."},{"n":5303,"s":68,"a":32,"t":"Nous souhaitons que notre Seigneur nous le remplace par quelque chose de meilleur. Nous désirons nous rapprocher de notre Seigneur»."},{"n":5304,"s":68,"a":33,"t":"Tel fut le châtiment; et le châtiment de l'au-delà est plus grand encore, si seulement ils savaient!"},{"n":5305,"s":68,"a":34,"t":"Les pieux auront auprès de leur Seigneur les Jardins du délice."},{"n":5306,"s":68,"a":35,"t":"Traiterons-Nous les soumis [à Allah] à la manière des criminels?"},{"n":5307,"s":68,"a":36,"t":"Qu'avez-vous? Comment jugez-vous?"},{"n":5308,"s":68,"a":37,"t":"Ou bien avez-vous un Livre dans lequel vous apprenez"},{"n":5309,"s":68,"a":38,"t":"qu'en vérité vous obtiendrez tout ce que vous désirez?"},{"n":5310,"s":68,"a":39,"t":"Ou bien est-ce que vous avez obtenu de Nous des serments valables jusqu'au Jour de la Résurrection, Nous engageant à vous donner ce que vous décidez?"},{"n":5311,"s":68,"a":40,"t":"Demande-leur qui d'entre eux en est garant?"},{"n":5312,"s":68,"a":41,"t":"Ou encore, est-ce qu'ils ont des associés? Eh bien, qu'ils fassent venir leurs associés s'ils sont véridiques!"},{"n":5313,"s":68,"a":42,"t":"Le jour où ils affronteront les horreurs [du Jugement] et où ils seront appelés à la Prosternation mais ils ne le pourront pas."},{"n":5314,"s":68,"a":43,"t":"Leurs regards seront abaissés, et l'avilissement les couvrira. Or, ils étaient appelés à la Prosternation au temps où ils étaient sains et saufs!..."},{"n":5315,"s":68,"a":44,"t":"Laisse-Moi donc avec quiconque traite de mensonge ce discours; Nous allons les mener graduellement par où ils ne savent pas!"},{"n":5316,"s":68,"a":45,"t":"Et Je leur accorde un délai, car Mon stratagème est sûr!"},{"n":5317,"s":68,"a":46,"t":"Ou bien est-ce que tu leur demandes un salaire, les accablant ainsi d'une lourde dette?"},{"n":5318,"s":68,"a":47,"t":"Ou savent-ils l'Inconnaissable et c'est de là qu'ils écrivent [leurs mensonges]?"},{"n":5319,"s":68,"a":48,"t":"Endure avec patience la sentence de ton Seigneur, et ne sois pas comme l'homme au Poisson [Jonas] qui appela (Allah) dans sa grande angoisse."},{"n":5320,"s":68,"a":49,"t":"Si un bienfait de son Seigneur ne l'avait pas atteint, il aurait été rejeté honni sur une terre déserte,"},{"n":5321,"s":68,"a":50,"t":"Puis son Seigneur l'élut et le désigna au nombre des gens de bien."},{"n":5322,"s":68,"a":51,"t":"Peu s'en faut que ceux qui mécroient ne te transpercent par leurs regards, quand ils entendent le Coran, ils disent: «Il est certes fou!»"},{"n":5323,"s":68,"a":52,"t":"Et ce n'est qu'un Rappel, adressé aux mondes!"},{"n":5324,"s":69,"a":1,"t":"L'inévitable [l'Heure qui montre la vérité]"},{"n":5325,"s":69,"a":2,"t":"Qu'est-ce que l'inévitable?"},{"n":5326,"s":69,"a":3,"t":"Et qui te dira ce que c'est que l'inévitable?"},{"n":5327,"s":69,"a":4,"t":"Les Thamûd et les 'Aad avaient traité de mensonge le cataclysme."},{"n":5328,"s":69,"a":5,"t":"Quant aux Thamûd, ils furent détruits par le [bruit] excessivement fort."},{"n":5329,"s":69,"a":6,"t":"Et quant aux 'Aad, ils furent détruits par un vent mugissant et furieux"},{"n":5330,"s":69,"a":7,"t":"qu'[Allah] déchaîna contre eux pendant sept nuits et huit jours consécutifs; tu voyais alors les gens renversés par terre comme des souches de palmiers évidées."},{"n":5331,"s":69,"a":8,"t":"En vois-tu le moindre vestige?"},{"n":5332,"s":69,"a":9,"t":"Pharaon et ceux qui vécurent avant lui ainsi que les Villes renversées, commirent des fautes."},{"n":5333,"s":69,"a":10,"t":"Ils désobéirent au Messager de leur Seigneur. Celui-ci donc, les saisit d'une façon irrésistible."},{"n":5334,"s":69,"a":11,"t":"C'est Nous qui, quand l'eau déborda, vous avons chargés sur l'Arche"},{"n":5335,"s":69,"a":12,"t":"afin d'en faire pour vous un rappel que toute oreille fidèle conserve."},{"n":5336,"s":69,"a":13,"t":"Puis, quand d'un seul souffle, on soufflera dans la Trompe,"},{"n":5337,"s":69,"a":14,"t":"et que la terre et les montagnes seront soulevées puis tassées d'un seul coup;"},{"n":5338,"s":69,"a":15,"t":"ce jour-là alors, l'Evénement se produira,"},{"n":5339,"s":69,"a":16,"t":"et le ciel se fendra et sera fragile, ce jour-là."},{"n":5340,"s":69,"a":17,"t":"Et sur ses côtés [se tiendront] les Anges, tandis que huit, ce jour-là, porteront au-dessus d'eux le Trône de ton Seigneur."},{"n":5341,"s":69,"a":18,"t":"Ce jour-là vous serez exposés; et rien de vous ne sera caché."},{"n":5342,"s":69,"a":19,"t":"Quant à celui à qui on aura remis le Livre en sa main droite, il dira: «Tenez! lisez mon livre."},{"n":5343,"s":69,"a":20,"t":"J'étais sûr d'y trouver mon compte»."},{"n":5344,"s":69,"a":21,"t":"Il jouira d'une vie agréable:"},{"n":5345,"s":69,"a":22,"t":"dans un Jardin haut placé"},{"n":5346,"s":69,"a":23,"t":"dont les fruits sont à portée de la main."},{"n":5347,"s":69,"a":24,"t":"«Mangez et buvez agréablement pour ce que vous avez avancé dans les jours passés»."},{"n":5348,"s":69,"a":25,"t":"Quant à celui à qui on aura remis le Livre en sa main gauche, il dira: «Hélas pour moi! J'aurai souhaité qu'on ne m'ait pas remis mon livre,"},{"n":5349,"s":69,"a":26,"t":"et ne pas avoir connu mon compte..."},{"n":5350,"s":69,"a":27,"t":"Hélas, comme j'aurai souhaité que [ma première mort] fût la définitive."},{"n":5351,"s":69,"a":28,"t":"Ma fortune ne m'a servi à rien."},{"n":5352,"s":69,"a":29,"t":"Mon autorité est anéantie et m'a quitté!»"},{"n":5353,"s":69,"a":30,"t":"«Saisissez-le! Puis, mettez-lui un carcan;"},{"n":5354,"s":69,"a":31,"t":"ensuite, brûlez-le dans la Fournaise;"},{"n":5355,"s":69,"a":32,"t":"puis, liez-le avec une chaîne de soixante-dix coudées,"},{"n":5356,"s":69,"a":33,"t":"car il ne croyait pas en Allah, le Très Grand."},{"n":5357,"s":69,"a":34,"t":"et n'incitait pas à nourrir le pauvre."},{"n":5358,"s":69,"a":35,"t":"Il n'a pour lui ici, aujourd'hui, point d'ami chaleureux [pour le protéger],"},{"n":5359,"s":69,"a":36,"t":"ni d'autre nourriture que du pus,"},{"n":5360,"s":69,"a":37,"t":"que seuls les fautifs mangeront»."},{"n":5361,"s":69,"a":38,"t":"Mais non... Je jure par ce que vous voyez,"},{"n":5362,"s":69,"a":39,"t":"ainsi que par ce que vous ne voyez pas,"},{"n":5363,"s":69,"a":40,"t":"que ceci [le Coran] est la parole d'un noble Messager,"},{"n":5364,"s":69,"a":41,"t":"et que ce n'est pas la parole d'un poète; mais vous ne croyez que très peu,"},{"n":5365,"s":69,"a":42,"t":"ni la parole d'un devin, mais vous vous rappelez bien peu."},{"n":5366,"s":69,"a":43,"t":"C'est une révélation du Seigneur de l'Univers."},{"n":5367,"s":69,"a":44,"t":"Et s'il avait forgé quelques paroles qu'ils Nous avait attribuées,"},{"n":5368,"s":69,"a":45,"t":"Nous l'aurions saisi de la main droite,"},{"n":5369,"s":69,"a":46,"t":"ensuite, Nous lui aurions tranché l'aorte."},{"n":5370,"s":69,"a":47,"t":"Et nul d'entre vous n'aurait pu lui servir de rempart."},{"n":5371,"s":69,"a":48,"t":"C'est en vérité un rappel pour les pieux."},{"n":5372,"s":69,"a":49,"t":"Et Nous savons qu'il y a parmi vous qui le traitent de menteur;"},{"n":5373,"s":69,"a":50,"t":"mais en vérité, ce sera un sujet de regret pour les mécréants,"},{"n":5374,"s":69,"a":51,"t":"c'est là la véritable certitude."},{"n":5375,"s":69,"a":52,"t":"Glorifie donc le nom de ton Seigneur, le Très Grand!"},{"n":5376,"s":70,"a":1,"t":"Un demandeur a réclamé un châtiment inéluctable,"},{"n":5377,"s":70,"a":2,"t":"pour les mécréants, que nul ne pourrait repousser,"},{"n":5378,"s":70,"a":3,"t":"et qui vient d'Allah, le Maître des voies d'ascension."},{"n":5379,"s":70,"a":4,"t":"Les Anges ainsi que l'Esprit montent vers Lui en un jour dont la durée est de cinquante mille ans."},{"n":5380,"s":70,"a":5,"t":"Supporte donc, d'une belle patience."},{"n":5381,"s":70,"a":6,"t":"Ils le (le châtiment) voient bien loin,"},{"n":5382,"s":70,"a":7,"t":"alors que Nous le voyons bien proche,"},{"n":5383,"s":70,"a":8,"t":"le jour où le ciel sera comme du métal en fusion"},{"n":5384,"s":70,"a":9,"t":"et les montagnes comme de la laine,"},{"n":5385,"s":70,"a":10,"t":"où nul ami dévoué ne s'enquerra d'un ami,"},{"n":5386,"s":70,"a":11,"t":"bien qu'ils se voient l'un l'autre. Le criminel aimerait pouvoir se racheter du châtiment de ce jour, en livrant ses enfants,"},{"n":5387,"s":70,"a":12,"t":"sa compagne, son frère,"},{"n":5388,"s":70,"a":13,"t":"même son clan qui lui donnait asile,"},{"n":5389,"s":70,"a":14,"t":"et tout ce qui est sur la terre, tout, qui pourrait le sauver."},{"n":5390,"s":70,"a":15,"t":"Mais rien [ne le sauvera]. [L'Enfer] est un brasier"},{"n":5391,"s":70,"a":16,"t":"arrachant brutalement la peau du crâne."},{"n":5392,"s":70,"a":17,"t":"Il appellera celui qui tournait le dos et s'en allait,"},{"n":5393,"s":70,"a":18,"t":"amassait et thésaurisait."},{"n":5394,"s":70,"a":19,"t":"Oui, l'homme a été créé instable [très inquiet];"},{"n":5395,"s":70,"a":20,"t":"quand le malheur le touche, il est abattu;"},{"n":5396,"s":70,"a":21,"t":"et quand le bonheur le touche, il est grand refuseur."},{"n":5397,"s":70,"a":22,"t":"Sauf ceux qui pratiquent la Salât"},{"n":5398,"s":70,"a":23,"t":"qui sont assidus à leurs Salâts,"},{"n":5399,"s":70,"a":24,"t":"et sur les biens desquels il y a un droit bien déterminé [la Zakât]"},{"n":5400,"s":70,"a":25,"t":"pour le mendiant et le déshérité;"},{"n":5401,"s":70,"a":26,"t":"et qui déclarent véridique le Jour de la Rétribution,"},{"n":5402,"s":70,"a":27,"t":"et ceux qui craignent le châtiment de leur Seigneur"},{"n":5403,"s":70,"a":28,"t":"car vraiment, il n'y a nulle assurance contre le châtiment de leur Seigneur;"},{"n":5404,"s":70,"a":29,"t":"et qui se maintiennent dans la chasteté"},{"n":5405,"s":70,"a":30,"t":"et n'ont de rapports qu'avec leurs épouses ou les esclaves qu'ils possèdent car dans ce cas, ils ne sont pas blâmables,"},{"n":5406,"s":70,"a":31,"t":"mais ceux qui cherchent [leur plaisir] en dehors de cela, sont des transgresseurs;"},{"n":5407,"s":70,"a":32,"t":"et qui gardent les dépôts confiés à eux, et respectent leurs engagements scrupuleusement;"},{"n":5408,"s":70,"a":33,"t":"et qui témoignent de la stricte vérité,"},{"n":5409,"s":70,"a":34,"t":"et qui sont réguliers dans leur Salât."},{"n":5410,"s":70,"a":35,"t":"Ceux-là seront honorés dans des Jardins."},{"n":5411,"s":70,"a":36,"t":"Qu'ont donc, ceux qui ont mécru, à courir vers toi, le cou tendu,"},{"n":5412,"s":70,"a":37,"t":"de droite et de gauche, [venant] par bandes?"},{"n":5413,"s":70,"a":38,"t":"Chacun d'eux convoite-t-il qu'on le laisse entrer au Jardin des délices?"},{"n":5414,"s":70,"a":39,"t":"Mais non! Nous les avons créés de ce qu'ils savent."},{"n":5415,"s":70,"a":40,"t":"Eh Non!... Je jure par le Seigneur des Levants et des Couchants que Nous sommes Capable"},{"n":5416,"s":70,"a":41,"t":"de les remplacer par de meilleurs qu'eux, et nul ne peut nous en empêcher."},{"n":5417,"s":70,"a":42,"t":"Laisse-les donc s'enfoncer (dans leur mécréance) et se divertir jusqu'à ce qu'ils rencontrent leur jour dont on les menaçait,"},{"n":5418,"s":70,"a":43,"t":"le jour où ils sortiront des tombes, rapides comme s'ils couraient vers des pierres dressées;"},{"n":5419,"s":70,"a":44,"t":"leurs yeux seront abaissés, l'avilissement les couvrira. C'est cela le jour dont on les menaçait!"},{"n":5420,"s":71,"a":1,"t":"Nous avons envoyé Noé vers son peuple: «Avertis ton peuple, avant que leur vienne un châtiment douloureux»."},{"n":5421,"s":71,"a":2,"t":"Il [leur] dit: «O mon peuple, je suis vraiment pour vous, un avertisseur clair,"},{"n":5422,"s":71,"a":3,"t":"Adorez Allah, craignez-Le et obéissez-moi,"},{"n":5423,"s":71,"a":4,"t":"pour qu'Il vous pardonne vos péchés et qu'Il vous donne un délai jusqu'à un terme fixé. Mais quand vient le terme fixé par Allah, il ne saurait être différé si vous saviez!»"},{"n":5424,"s":71,"a":5,"t":"Il dit: «Seigneur! J'ai appelé mon peuple, nuit et jour."},{"n":5425,"s":71,"a":6,"t":"Mais mon appel n'a fait qu'accroître leur fuite."},{"n":5426,"s":71,"a":7,"t":"Et chaque fois que je les ai appelés pour que Tu leur pardonnes, ils ont mis leurs doigts dans leurs oreilles. se sont enveloppés de leurs vêtements, se sont entêtés et se sont montrés extrêmement orgueilleux."},{"n":5427,"s":71,"a":8,"t":"Ensuite, je les ai appelés ouvertement."},{"n":5428,"s":71,"a":9,"t":"Puis, je leur ai fait des proclamations publiques, et des confidences en secret."},{"n":5429,"s":71,"a":10,"t":"J'ai donc dit: «Implorez le pardon de votre Seigneur, car Il est grand Pardonneur,"},{"n":5430,"s":71,"a":11,"t":"pour qu'Il vous envoie du ciel, des pluies abondantes,"},{"n":5431,"s":71,"a":12,"t":"et qu'Il vous accorde beaucoup de biens et d'enfants, et vous donne des jardins et vous donne des rivières."},{"n":5432,"s":71,"a":13,"t":"Qu'avez-vous à ne pas vénérer Allah comme il se doit,"},{"n":5433,"s":71,"a":14,"t":"alors qu'Il vous a créés par phases successives?"},{"n":5434,"s":71,"a":15,"t":"N'avez-vous pas vu comment Allah a créé sept cieux superposés"},{"n":5435,"s":71,"a":16,"t":"et y a fait de la lune une lumière et du soleil une lampe?"},{"n":5436,"s":71,"a":17,"t":"Et c'est Allah qui, de la terre, vous a fait croître comme des plantes,"},{"n":5437,"s":71,"a":18,"t":"puis Il vous y fera retourner et vous en fera sortir véritablement."},{"n":5438,"s":71,"a":19,"t":"Et c'est Allah qui vous a fait de la terre un tapis,"},{"n":5439,"s":71,"a":20,"t":"pour que vous vous acheminiez par ses voies spacieuses»."},{"n":5440,"s":71,"a":21,"t":"Noé dit: «Seigneur, ils m'ont désobéi et ils ont suivi celui dont les biens et les enfants n'ont fait qu'accroître la perte."},{"n":5441,"s":71,"a":22,"t":"Ils ont ourdi un immense stratagème,"},{"n":5442,"s":71,"a":23,"t":"et ils ont dit: «N'abandonnez jamais vos divinités et n'abandonnez jamais Wadd, Suwâ, Yaghhû, Ya'ûq et Nasr'."},{"n":5443,"s":71,"a":24,"t":"Elles [les idoles] ont déjà égaré plusieurs. Ne fais (Seigneur) croître les injustes qu'en égarement."},{"n":5444,"s":71,"a":25,"t":"A cause de leurs fautes, ils ont été noyés, puis on les a fait entrer au Feu, et ils n'ont pas trouvé en dehors d'Allah, de secoureurs»."},{"n":5445,"s":71,"a":26,"t":"Et Noé dit: «Seigneur, ne laisse sur la terre aucun infidèle."},{"n":5446,"s":71,"a":27,"t":"Si Tu les laisses [en vie], ils égareront Tes serviteurs et n'engendreront que des pécheurs infidèles."},{"n":5447,"s":71,"a":28,"t":"Seigneur! Pardonne-moi, et à mes père et mère et à celui qui entre dans ma demeure croyant, ainsi qu'aux croyants et croyantes; et ne fais croître les injustes qu'en perdition»."},{"n":5448,"s":72,"a":1,"t":"Dis: «Il m'a été révélé qu'un groupe de djinns prêtèrent l'oreille, puis dirent: «Nous avons certes entendu une Lecture [le Coran] merveilleuse,"},{"n":5449,"s":72,"a":2,"t":"qui guide vers la droiture. Nous y avons cru, et nous n'associerons jamais personne à notre Seigneur."},{"n":5450,"s":72,"a":3,"t":"En vérité notre Seigneur - que Sa grandeur soit exaltée - ne S'est donné ni compagne, ni enfant!"},{"n":5451,"s":72,"a":4,"t":"Notre insensé [Iblis] disait des extravagances contre Allah."},{"n":5452,"s":72,"a":5,"t":"Et nous pensions que ni les humains ni les djinns ne sauraient jamais proférer de mensonge contre Allah."},{"n":5453,"s":72,"a":6,"t":"Or, il y avait parmi les humains, des mâles qui cherchaient protection auprès des mâles parmi les djinns mais cela ne fit qu'accroître leur détresse."},{"n":5454,"s":72,"a":7,"t":"Et ils avaient pensé comme vous avez pensé qu'Allah ne ressusciterait jamais personne."},{"n":5455,"s":72,"a":8,"t":"Nous avions frôlé le ciel et nous l'avions trouvé plein d'une forte garde et de bolides."},{"n":5456,"s":72,"a":9,"t":"Nous y prenions place pour écouter. Mais quiconque prête l'oreille maintenant, trouve contre lui un bolide aux aguets."},{"n":5457,"s":72,"a":10,"t":"Nous ne savons pas si on veut du mal aux habitants de la terre ou si leur Seigneur veut les mettre sur le droit chemin."},{"n":5458,"s":72,"a":11,"t":"Il y a parmi nous des vertueux et [d'autres] qui le sont moins: nous étions divisés en différentes sectes."},{"n":5459,"s":72,"a":12,"t":"Nous pensions bien que nous ne saurions jamais réduire Allah à l'impuissance sur la terre et que nous ne saurions jamais le réduire à l'impuissance en nous enfuyant."},{"n":5460,"s":72,"a":13,"t":"Et lorsque nous avons entendu le guide [le Coran], nous y avons cru, et quiconque croit en son Seigneur ne craint alors ni diminution de récompense ni oppression."},{"n":5461,"s":72,"a":14,"t":"Il y a parmi nous les Musulmans, et il y en a les injustes [qui ont dévié]. Et ceux qui se sont convertis à l'Islam sont ceux qui ont cherché la droiture."},{"n":5462,"s":72,"a":15,"t":"Et quant aux injustes, ils formeront le combustible de l'Enfer."},{"n":5463,"s":72,"a":16,"t":"Et s'ils se maintenaient dans la bonne direction, Nous les aurions abreuvés, certes d'une eau abondante,"},{"n":5464,"s":72,"a":17,"t":"afin de les y éprouver. Et quiconque se détourne du rappel de son Seigneur, Il l'achemine vers un châtiment sans cesse croissant."},{"n":5465,"s":72,"a":18,"t":"Les mosquées sont consacrées à Allah: n'invoquez donc personne avec Allah."},{"n":5466,"s":72,"a":19,"t":"Et quand le serviteur d'Allah s'est mis debout pour L'invoquer, ils faillirent se ruer en masse sur lui."},{"n":5467,"s":72,"a":20,"t":"Dis: «Je n'invoque que mon Seigneur et ne Lui associe personne»."},{"n":5468,"s":72,"a":21,"t":"Dis: «Je ne possède aucun moyen pour vous faire du mal, ni pour vous mettre sur le chemin droit»."},{"n":5469,"s":72,"a":22,"t":"Dis: «Vraiment, personne ne saura me protéger contre Allah; et jamais je ne trouverai de refuge en dehors de Lui."},{"n":5470,"s":72,"a":23,"t":"[Je ne puis que transmettre] une communication et des messages [émanant] d'Allah. Et quiconque désobéit à Allah et à Son Messager aura le feu de l'Enfer pour y demeurer éternellement."},{"n":5471,"s":72,"a":24,"t":"Puis, quand ils verront ce dont on les menaçait, ils sauront lesquels ont les secours les plus faibles et [lesquels] sont les moins nombreux."},{"n":5472,"s":72,"a":25,"t":"Dis: «Je ne sais pas si ce dont vous êtes menacés est proche, ou bien, si mon Seigneur va lui assigner un délai."},{"n":5473,"s":72,"a":26,"t":"[C'est Lui] qui connaît le mystère. Il ne dévoile Son mystère à personne,"},{"n":5474,"s":72,"a":27,"t":"sauf à celui qu'Il agrée comme Messager et qu'Il fait précéder et suivre de gardiens vigilants,"},{"n":5475,"s":72,"a":28,"t":"afin qu'Il sache s'ils ont bien transmis les messages de leur Seigneur. Il cerne (de Son savoir) ce qui est avec eux, et dénombre exactement toute chose."},{"n":5476,"s":73,"a":1,"t":"O toi, l'enveloppé [dans tes vêtements]!"},{"n":5477,"s":73,"a":2,"t":"Lève-toi [pour prier], toute la nuit, excepté une petite partie;"},{"n":5478,"s":73,"a":3,"t":"Sa moitié, ou un peu moins;"},{"n":5479,"s":73,"a":4,"t":"ou un peu plus. Et récite le Coran, lentement et clairement."},{"n":5480,"s":73,"a":5,"t":"Nous allons te révéler des paroles lourdes (très importantes)."},{"n":5481,"s":73,"a":6,"t":"La prière pendant la nuit est plus efficace et plus propice pour la récitation."},{"n":5482,"s":73,"a":7,"t":"Tu as, dans la journée, à vaquer à de longues occupations."},{"n":5483,"s":73,"a":8,"t":"Et rappelle-toi le nom de ton Seigneur et consacre-toi totalement à Lui,"},{"n":5484,"s":73,"a":9,"t":"le Seigneur du Levant et du Couchant. Il n'y a point de divinité à part Lui. Prends-Le donc comme Protecteur."},{"n":5485,"s":73,"a":10,"t":"Et endure ce qu'ils disent; et écarte-toi d'eux d'une façon convenable."},{"n":5486,"s":73,"a":11,"t":"Et laisse-moi avec ceux qui crient au mensonge et qui vivent dans l'aisance; et accorde-leur un court répit:"},{"n":5487,"s":73,"a":12,"t":"Nous avons [pour eux] lourdes chaînes et Enfer,"},{"n":5488,"s":73,"a":13,"t":"et nourriture à faire suffoquer, et châtiment douloureux."},{"n":5489,"s":73,"a":14,"t":"Le jour où la terre et les montagnes trembleront, tandis que les montagnes deviendront comme une dune de sable dispersée."},{"n":5490,"s":73,"a":15,"t":"Nous vous avons envoyé un Messager pour être témoin contre vous, de même que Nous avions envoyé un Messager à Pharaon."},{"n":5491,"s":73,"a":16,"t":"Pharaon désobéit alors au Messager. Nous le saisîmes donc rudement."},{"n":5492,"s":73,"a":17,"t":"Comment vous préserverez-vous, si vous mécroyez, d'un jour qui rendra les enfants comme des vieillards aux cheveux blancs?"},{"n":5493,"s":73,"a":18,"t":"[et] durant lequel le ciel se fendra. Sa promesse s'accomplira sans doute."},{"n":5494,"s":73,"a":19,"t":"Ceci est un rappel. Que celui qui veut prenne une voie [menant] à son Seigneur."},{"n":5495,"s":73,"a":20,"t":"Ton Seigneur sait, certes, que tu (Muhammad) te tiens debout moins de deux tiers de la nuit, ou sa moitié, ou son tiers. De même qu'une partie de ceux qui sont avec toi. Allah détermine la nuit et le jour. Il sait que vous ne saurez jamais passer toute la nuit en prière. Il a usé envers vous avec indulgence. Récitez donc ce qui [vous] est possible du Coran. Il sait qu'il y aura parmi vous des malades, et d'autres qui voyageront sur la terre, en quête de la grâce d'Allah, et d'autres encore qui combattront dans le chemin d'Allah. Récite-en donc ce qui [vous] sera possible. Accomplissez la Salât, acquittez la Zakât, et faites à Allah un prêt sincère. Tout bien que vous vous préparez, vous le retrouverez auprès d'Allah, meilleur et plus grand en fait de récompense. Et implorez le pardon d'Allah. Car Allah est Pardonneur et Très Miséricordieux."},{"n":5496,"s":74,"a":1,"t":"O, toi (Muhammad)! Le revêtu d'un manteau!"},{"n":5497,"s":74,"a":2,"t":"Lève-toi et avertis."},{"n":5498,"s":74,"a":3,"t":"Et de ton Seigneur, célèbre la grandeur."},{"n":5499,"s":74,"a":4,"t":"Et tes vêtements, purifie-les."},{"n":5500,"s":74,"a":5,"t":"Et de tout péché, écarte-toi."},{"n":5501,"s":74,"a":6,"t":"Et ne donne pas dans le but de recevoir davantage."},{"n":5502,"s":74,"a":7,"t":"Et pour ton Seigneur, endure."},{"n":5503,"s":74,"a":8,"t":"Quand on sonnera du Clairon,"},{"n":5504,"s":74,"a":9,"t":"alors, ce jour-là sera un jour difficile,"},{"n":5505,"s":74,"a":10,"t":"pas facile pour les mécréants."},{"n":5506,"s":74,"a":11,"t":"Laisse-Moi avec celui que J'ai créé seul,"},{"n":5507,"s":74,"a":12,"t":"et à qui J'ai donné des biens étendus,"},{"n":5508,"s":74,"a":13,"t":"et des enfants qui lui tiennent toujours compagnie,"},{"n":5509,"s":74,"a":14,"t":"pour qui aussi J'ai aplani toutes difficultés"},{"n":5510,"s":74,"a":15,"t":"Cependant, il convoite [de Moi] que Je lui donne davantage."},{"n":5511,"s":74,"a":16,"t":"Pas du tout! Car il reniait nos versets (le Coran) avec entêtement."},{"n":5512,"s":74,"a":17,"t":"Je vais le contraindre à gravir une pente."},{"n":5513,"s":74,"a":18,"t":"Il a réfléchi. Et il a décidé."},{"n":5514,"s":74,"a":19,"t":"Qu'il périsse! Comme il a décidé!"},{"n":5515,"s":74,"a":20,"t":"Encore une fois, qu'il périsse; comme il a décidé!"},{"n":5516,"s":74,"a":21,"t":"Ensuite, il a regardé."},{"n":5517,"s":74,"a":22,"t":"Et il s'est renfrogné et a durci son visage."},{"n":5518,"s":74,"a":23,"t":"Ensuite il a tourné le dos et s'est enflé d'orgueil"},{"n":5519,"s":74,"a":24,"t":"Puis il a dit: «Ceci (le Coran) n'est que magie apprise"},{"n":5520,"s":74,"a":25,"t":"ce n'est là que la parole d'un humain»."},{"n":5521,"s":74,"a":26,"t":"Je vais le brûler dans le Feu intense (Saqar)."},{"n":5522,"s":74,"a":27,"t":"Et qui te dira ce qu'est Saqar?"},{"n":5523,"s":74,"a":28,"t":"Il ne laisse rien et n'épargne rien;"},{"n":5524,"s":74,"a":29,"t":"Il brûle la peau et la noircit."},{"n":5525,"s":74,"a":30,"t":"Ils sont dix neuf à y veiller."},{"n":5526,"s":74,"a":31,"t":"Nous n'avons assigné comme gardiens du Feu que des Anges. Cependant, Nous n'en avons fixé le nombre que pour éprouver les mécréants, et aussi afin que ceux à qui le Livre a été apporté soient convaincus, et que croisse la foi de ceux qui croient, et que ceux à qui le Livre a été apporté et les croyants n'aient point de doute; et pour que ceux qui ont au cœur quelque maladie ainsi que les mécréants disent: «Qu'a donc voulu Allah par cette parabole?» C'est ainsi qu'Allah égare qui Il veut et guide qui Il veut. Nul ne connaît les armées de ton Seigneur, à part Lui. Et ce n'est là qu'un rappel pour les humains."},{"n":5527,"s":74,"a":32,"t":"Non!... Par la lune!"},{"n":5528,"s":74,"a":33,"t":"Et par la nuit quand elle se retire!"},{"n":5529,"s":74,"a":34,"t":"Et par l'aurore quand elle se découvre!"},{"n":5530,"s":74,"a":35,"t":"[Saqar] est l'un des plus grands [malheurs]"},{"n":5531,"s":74,"a":36,"t":"un avertissement, pour les humains."},{"n":5532,"s":74,"a":37,"t":"Pour qui d'entre vous, veut avancer ou reculer."},{"n":5533,"s":74,"a":38,"t":"Toute âme est l'otage de ce qu'elle a acquis."},{"n":5534,"s":74,"a":39,"t":"Sauf les gens de la droite (les élus):"},{"n":5535,"s":74,"a":40,"t":"dans des Jardins, ils s'interrogeront"},{"n":5536,"s":74,"a":41,"t":"au sujet des criminels:"},{"n":5537,"s":74,"a":42,"t":"«Qu'est-ce qui vous a acheminés à Saqar?»"},{"n":5538,"s":74,"a":43,"t":"Ils diront: «Nous n'étions pas de ceux qui faisaient la Salât,"},{"n":5539,"s":74,"a":44,"t":"et nous ne nourrissions pas le pauvre,"},{"n":5540,"s":74,"a":45,"t":"et nous nous associions à ceux qui tenaient des conversations futiles,"},{"n":5541,"s":74,"a":46,"t":"et nous traitions de mensonge le jour de la Rétribution,"},{"n":5542,"s":74,"a":47,"t":"jusqu'à ce que nous vînt la vérité évidente [la mort]»."},{"n":5543,"s":74,"a":48,"t":"Ne leur profitera point donc, l'intercession des intercesseurs."},{"n":5544,"s":74,"a":49,"t":"Qu'ont-ils à se détourner du Rappel?"},{"n":5545,"s":74,"a":50,"t":"Ils sont comme des onagres épouvantés,"},{"n":5546,"s":74,"a":51,"t":"s'enfuyant devant un lion."},{"n":5547,"s":74,"a":52,"t":"Chacun d'eux voudrait plutôt qu'on lui apporte des feuilles tout étalées."},{"n":5548,"s":74,"a":53,"t":"Ah! Non! C'est plutôt qu'ils ne craignent pas l'au-delà."},{"n":5549,"s":74,"a":54,"t":"Ah! Non! Ceci est vraiment un Rappel."},{"n":5550,"s":74,"a":55,"t":"Quiconque veut, qu'il se le rappelle."},{"n":5551,"s":74,"a":56,"t":"Mais ils ne se rappelleront que si Allah veut. C'est Lui qui est Le plus digne d'être craint; et c'est Lui qui détient le pardon."},{"n":5552,"s":75,"a":1,"t":"Non!... Je jure par le Jour de la Résurrection!"},{"n":5553,"s":75,"a":2,"t":"Mais non!, Je jure par l'âme qui ne cesse de se blâmer."},{"n":5554,"s":75,"a":3,"t":"L'homme, pense-t-il que Nous ne réunirons jamais ses os?"},{"n":5555,"s":75,"a":4,"t":"Mais si! Nous sommes Capable de remettre à leur place les extrémités de ses doigts."},{"n":5556,"s":75,"a":5,"t":"L'homme voudrait plutôt continuer à vivre en libertin."},{"n":5557,"s":75,"a":6,"t":"Il interroge: «A quand, le Jour de la Résurrection?»"},{"n":5558,"s":75,"a":7,"t":"Lorsque la vue sera éblouie,"},{"n":5559,"s":75,"a":8,"t":"et que la lune s'éclipsera,"},{"n":5560,"s":75,"a":9,"t":"et que le soleil et la lune seront réunis,"},{"n":5561,"s":75,"a":10,"t":"l'homme, ce jour-là, dira: «Où fuir?»"},{"n":5562,"s":75,"a":11,"t":"Non! Point de refuge!"},{"n":5563,"s":75,"a":12,"t":"Vers ton Seigneur sera, ce jour-là, le retour."},{"n":5564,"s":75,"a":13,"t":"L'homme sera informé ce jour-là de ce qu'il aura avancé et de ce qu'il aura remis à plus tard."},{"n":5565,"s":75,"a":14,"t":"Mais l'homme sera un témoin perspicace contre lui-même,"},{"n":5566,"s":75,"a":15,"t":"quand même il présenterait ses excuses."},{"n":5567,"s":75,"a":16,"t":"Ne remue pas ta langue pour hâter sa récitation:"},{"n":5568,"s":75,"a":17,"t":"Son rassemblement (dans ton cœur et sa fixation dans ta mémoire) Nous incombent, ainsi que la façon de le réciter."},{"n":5569,"s":75,"a":18,"t":"Quand donc Nous le récitons, suis sa récitation."},{"n":5570,"s":75,"a":19,"t":"A Nous, ensuite incombera son explication."},{"n":5571,"s":75,"a":20,"t":"Mais vous aimez plutôt [la vie] éphémère,"},{"n":5572,"s":75,"a":21,"t":"et vous délaissez l'au-delà."},{"n":5573,"s":75,"a":22,"t":"Ce jour-là, il y aura des visages resplendissants"},{"n":5574,"s":75,"a":23,"t":"qui regarderont leur Seigneur;"},{"n":5575,"s":75,"a":24,"t":"et il y aura ce jour-là, des visages assombris,"},{"n":5576,"s":75,"a":25,"t":"qui s'attendent à subir une catastrophe."},{"n":5577,"s":75,"a":26,"t":"Mais non! Quand [l'âme] en arrive aux clavicules"},{"n":5578,"s":75,"a":27,"t":"et qu'on dit: «Qui est exorciseur?»"},{"n":5579,"s":75,"a":28,"t":"et qu'il [l'agonisant] est convaincu que c'est la séparation (la mort),"},{"n":5580,"s":75,"a":29,"t":"et que la jambe s'enlace à la jambe,"},{"n":5581,"s":75,"a":30,"t":"c'est vers ton Seigneur, ce jour-là que tu seras conduit."},{"n":5582,"s":75,"a":31,"t":"Mais il n'a ni cru, ni fait la Salât;"},{"n":5583,"s":75,"a":32,"t":"par contre, il a démenti et tourné le dos,"},{"n":5584,"s":75,"a":33,"t":"puis il s'en est allé vers sa famille, marchant avec orgueil."},{"n":5585,"s":75,"a":34,"t":"«Malheur à toi, malheur!»"},{"n":5586,"s":75,"a":35,"t":"Et encore malheur à toi, malheur!"},{"n":5587,"s":75,"a":36,"t":"L'homme pense-t-il qu'on le laissera sans obligation à observer?"},{"n":5588,"s":75,"a":37,"t":"N'était-il pas une goutte de sperme éjaculé?"},{"n":5589,"s":75,"a":38,"t":"Et ensuite une adhérence Puis [Allah] l'a créée et formée harmonieusement;"},{"n":5590,"s":75,"a":39,"t":"puis en a fait alors les deux éléments de couple: le mâle et la femelle?"},{"n":5591,"s":75,"a":40,"t":"Celui-là [Allah] n'est-Il pas capable de faire revivre les morts?"},{"n":5592,"s":76,"a":1,"t":"S'est-il écoulé pour l'homme un laps de temps durant lequel il n'était même pas une chose mentionnable?"},{"n":5593,"s":76,"a":2,"t":"En effet, Nous avons créé l'homme d'une goutte de sperme mélangé [aux composantes diverses] pour le mettre à l'épreuve. [C'est pourquoi] Nous l'avons fait entendant et voyant."},{"n":5594,"s":76,"a":3,"t":"Nous l'avons guidé dans le chemin, - qu'il soit reconnaissant ou ingrat -"},{"n":5595,"s":76,"a":4,"t":"Nous avons préparé pour les infidèles des chaînes, des carcans et une fournaise ardente."},{"n":5596,"s":76,"a":5,"t":"Les vertueux boiront d'une coupe dont le mélange sera de camphre,"},{"n":5597,"s":76,"a":6,"t":"d'une source de laquelle boiront les serviteurs d'Allah et ils la feront jaillir en abondance."},{"n":5598,"s":76,"a":7,"t":"Ils accomplissent leurs vœux et ils redoutent un jour dont le mal s'étendra partout."},{"n":5599,"s":76,"a":8,"t":"et offrent la nourriture, malgré son amour, au pauvre, à l'orphelin et au prisonnier,"},{"n":5600,"s":76,"a":9,"t":"(disant): «C'est pour le visage d'Allah que nous vous nourrissons: nous ne voulons de vous ni récompense ni gratitude."},{"n":5601,"s":76,"a":10,"t":"Nous redoutons, de notre Seigneur, un jour terrible et catastrophique»."},{"n":5602,"s":76,"a":11,"t":"Allah les protègera donc du mal de ce jour-là, et leur fera rencontrer la splendeur et la joie,"},{"n":5603,"s":76,"a":12,"t":"et les rétribuera pour ce qu'ils auront enduré, en leur donnant le Paradis et des [vêtements] de soie,"},{"n":5604,"s":76,"a":13,"t":"ils y seront accoudés sur des divans, n'y voyant ni soleil ni froid glacial."},{"n":5605,"s":76,"a":14,"t":"Ses ombrages les couvriront de près, et ses fruits inclinés bien bas [à portée de leurs mains]."},{"n":5606,"s":76,"a":15,"t":"Et l'on fera circuler parmi eux des récipients d'argent et des coupes cristallines,"},{"n":5607,"s":76,"a":16,"t":"en cristal d'argent, dont le contenu a été savamment dosé."},{"n":5608,"s":76,"a":17,"t":"Et là, ils seront abreuvés d'une coupe dont le mélange sera de gingembre,"},{"n":5609,"s":76,"a":18,"t":"puisé là-dedans à une source qui s'appelle Salsabîl."},{"n":5610,"s":76,"a":19,"t":"Et parmi eux, circuleront des garçons éternellement jeunes. Quand tu les verras, tu les prendras pour des perles éparpillées."},{"n":5611,"s":76,"a":20,"t":"Et quand tu regarderas là-bas, tu verras un délice et un vaste royaume."},{"n":5612,"s":76,"a":21,"t":"Ils porteront des vêtements verts de satin et de brocart. Et ils seront parés de bracelets d'argent. Et leur Seigneur les abreuvera d'une boisson très pure."},{"n":5613,"s":76,"a":22,"t":"Cela sera pour vous une récompense, et votre effort sera reconnu."},{"n":5614,"s":76,"a":23,"t":"En vérité c'est Nous qui avons fait descendre sur toi le Coran graduellement."},{"n":5615,"s":76,"a":24,"t":"Endure donc ce que ton Seigneur a décrété, et n'obéis ni au pécheur, parmi eux, ni au grand mécréant."},{"n":5616,"s":76,"a":25,"t":"Et invoque le nom de ton Seigneur, matin et après-midi;"},{"n":5617,"s":76,"a":26,"t":"et prosterne-toi devant Lui une partie de la nuit; et glorifie-Le de longues [heures] pendant la nuit."},{"n":5618,"s":76,"a":27,"t":"Ces gens-là aiment [la vie] éphémère (la vie sur terre) et laissent derrière eux un jour bien lourd [le Jour du Jugement]."},{"n":5619,"s":76,"a":28,"t":"C'est Nous qui les avons créés et avons fortifié leur constitution. Quand Nous voulons, cependant, Nous les remplaçons [facilement] par leurs semblables."},{"n":5620,"s":76,"a":29,"t":"Ceci est un rappel. Que celui qui veut prenne donc le chemin vers son Seigneur!"},{"n":5621,"s":76,"a":30,"t":"Cependant, vous ne saurez vouloir, à moins qu'Allah veuille. Et Allah est Omniscient et Sage."},{"n":5622,"s":76,"a":31,"t":"Il fait entrer qui Il veut dans Sa miséricorde. Et quant aux injustes, Il leur a préparé un châtiment douloureux."},{"n":5623,"s":77,"a":1,"t":"Par ceux qu'on envoie en rafales,"},{"n":5624,"s":77,"a":2,"t":"et qui soufflent en tempête!"},{"n":5625,"s":77,"a":3,"t":"Et qui dispersent largement [dans toutes les directions]."},{"n":5626,"s":77,"a":4,"t":"Par ceux qui séparent nettement (le bien et le mal),"},{"n":5627,"s":77,"a":5,"t":"et lancent un rappel"},{"n":5628,"s":77,"a":6,"t":"en guise d'excuse ou d'avertissement!"},{"n":5629,"s":77,"a":7,"t":"Ce qui vous est promis est inéluctable."},{"n":5630,"s":77,"a":8,"t":"Quand donc les étoiles seront effacées,"},{"n":5631,"s":77,"a":9,"t":"et que le ciel sera fendu,"},{"n":5632,"s":77,"a":10,"t":"et que les montagnes seront pulvérisées,"},{"n":5633,"s":77,"a":11,"t":"et que le moment (pour la réunion) des Messagers a été fixé!..."},{"n":5634,"s":77,"a":12,"t":"A quel jour tout cela a-t-il été renvoyé?"},{"n":5635,"s":77,"a":13,"t":"Au Jour de la Décision. [le Jugement]!"},{"n":5636,"s":77,"a":14,"t":"Et qui te dira ce qu'est le Jour de la Décision?"},{"n":5637,"s":77,"a":15,"t":"Malheur, ce jour-là, à ceux qui criaient au mensonge."},{"n":5638,"s":77,"a":16,"t":"N'avons-nous pas fait périr les premières [générations]?"},{"n":5639,"s":77,"a":17,"t":"Puis ne les avons-Nous pas fait suivre par les derniers?"},{"n":5640,"s":77,"a":18,"t":"C'est ainsi que Nous agissons avec les criminels."},{"n":5641,"s":77,"a":19,"t":"Malheur, ce jour-là, à ceux qui criaient au mensonge."},{"n":5642,"s":77,"a":20,"t":"Ne vous avons-Nous pas créés d'une eau vile"},{"n":5643,"s":77,"a":21,"t":"que Nous avons placée dans un reposoir sûr,"},{"n":5644,"s":77,"a":22,"t":"pour une durée connue?"},{"n":5645,"s":77,"a":23,"t":"Nous l'avons décrété ainsi et Nous décrétons [tout] de façon parfaite."},{"n":5646,"s":77,"a":24,"t":"Malheur, ce jour-là, à ceux qui criaient au mensonge."},{"n":5647,"s":77,"a":25,"t":"N'avons-Nous pas fait de la terre un endroit les contenant tous,"},{"n":5648,"s":77,"a":26,"t":"les vivants ainsi que les morts?"},{"n":5649,"s":77,"a":27,"t":"Et n'y avons-Nous pas placé fermement de hautes montagnes? Et ne vous avons-Nous pas abreuvés d'eau douce?"},{"n":5650,"s":77,"a":28,"t":"Malheur, ce jour-là, à ceux qui criaient au mensonge."},{"n":5651,"s":77,"a":29,"t":"Allez vers ce que vous traitiez alors de mensonge!"},{"n":5652,"s":77,"a":30,"t":"Allez vers une ombre [fumée de l'Enfer] à trois branches;"},{"n":5653,"s":77,"a":31,"t":"qui n'est ni ombreuse ni capable de protéger contre la flamme;"},{"n":5654,"s":77,"a":32,"t":"car [le feu] jette des étincelles volumineuses comme des châteaux,"},{"n":5655,"s":77,"a":33,"t":"et qu'on prendrait pour des chameaux jaunes."},{"n":5656,"s":77,"a":34,"t":"Malheur, ce jour-là, à ceux qui criaient au mensonge."},{"n":5657,"s":77,"a":35,"t":"Ce sera le jour où ils ne [peuvent] pas parler,"},{"n":5658,"s":77,"a":36,"t":"et point ne leur sera donné permission de s'excuser."},{"n":5659,"s":77,"a":37,"t":"Malheur, ce jour-là, à ceux qui criaient au mensonge."},{"n":5660,"s":77,"a":38,"t":"C'est le Jour de la Décision [Jugement], où nous vous réunirons ainsi que les anciens."},{"n":5661,"s":77,"a":39,"t":"Si vous disposez d'une ruse, rusez donc contre Moi."},{"n":5662,"s":77,"a":40,"t":"Malheur, ce jour-là, à ceux qui criaient au mensonge."},{"n":5663,"s":77,"a":41,"t":"Les pieux seront parmi des ombrages et des sources"},{"n":5664,"s":77,"a":42,"t":"De même que des fruits selon leurs désirs."},{"n":5665,"s":77,"a":43,"t":"«Mangez et buvez agréablement, pour ce que vous faisiez»."},{"n":5666,"s":77,"a":44,"t":"C'est ainsi que Nous récompensons les bienfaisants."},{"n":5667,"s":77,"a":45,"t":"Malheur, ce jour-là, à ceux qui criaient au mensonge."},{"n":5668,"s":77,"a":46,"t":"«Mangez et jouissez un peu (ici-bas); vous êtes certes des criminels»."},{"n":5669,"s":77,"a":47,"t":"Malheur, ce jour-là, à ceux qui criaient au mensonge."},{"n":5670,"s":77,"a":48,"t":"Et quand on leur dit: «Inclinez-vous, ils ne s'inclinent pas."},{"n":5671,"s":77,"a":49,"t":"Malheur, ce jour-là, à ceux qui criaient au mensonge."},{"n":5672,"s":77,"a":50,"t":"Après cela, en quelle parole croiront-ils donc?"},{"n":5673,"s":78,"a":1,"t":"Sur quoi s'interrogent-ils mutuellement?"},{"n":5674,"s":78,"a":2,"t":"Sur la grande nouvelle,"},{"n":5675,"s":78,"a":3,"t":"à propos de laquelle ils divergent."},{"n":5676,"s":78,"a":4,"t":"Eh bien non! Ils sauront bientôt."},{"n":5677,"s":78,"a":5,"t":"Encore une fois, non! Ils sauront bientôt."},{"n":5678,"s":78,"a":6,"t":"N'avons-Nous pas fait de la terre une couche?"},{"n":5679,"s":78,"a":7,"t":"et (placé) les montagnes comme des piquets?"},{"n":5680,"s":78,"a":8,"t":"Nous vous avons créés en couples,"},{"n":5681,"s":78,"a":9,"t":"et désigné votre sommeil pour votre repos,"},{"n":5682,"s":78,"a":10,"t":"et fait de la nuit un vêtement,"},{"n":5683,"s":78,"a":11,"t":"et assigné le jour pour les affaires de la vie,"},{"n":5684,"s":78,"a":12,"t":"et construit au-dessus de vous sept (cieux) renforcés,"},{"n":5685,"s":78,"a":13,"t":"et [y] avons placé une lampe (le soleil) très ardente,"},{"n":5686,"s":78,"a":14,"t":"et fait descendre des nuées une eau abondante"},{"n":5687,"s":78,"a":15,"t":"pour faire pousser par elle grains et plantes"},{"n":5688,"s":78,"a":16,"t":"et jardins luxuriants."},{"n":5689,"s":78,"a":17,"t":"Le Jour de la Décision [du Jugement] a son terme fixé."},{"n":5690,"s":78,"a":18,"t":"Le jour où l'on soufflera dans la Trompe, vous viendrez par troupes,"},{"n":5691,"s":78,"a":19,"t":"et le ciel sera ouvert et [présentera] des portes,"},{"n":5692,"s":78,"a":20,"t":"et les montagnes seront mises en marche et deviendront un mirage."},{"n":5693,"s":78,"a":21,"t":"L'Enfer demeure aux aguets,"},{"n":5694,"s":78,"a":22,"t":"refuge pour les transgresseurs."},{"n":5695,"s":78,"a":23,"t":"Ils y demeureront pendant des siècles successifs."},{"n":5696,"s":78,"a":24,"t":"Ils n'y goûteront ni fraîcheur ni breuvage,"},{"n":5697,"s":78,"a":25,"t":"Hormis une eau bouillante et un pus"},{"n":5698,"s":78,"a":26,"t":"comme rétribution équitable."},{"n":5699,"s":78,"a":27,"t":"Car ils ne s'attendaient pas à rendre compte,"},{"n":5700,"s":78,"a":28,"t":"et traitaient de mensonges, continuellement, Nos versets,"},{"n":5701,"s":78,"a":29,"t":"alors que Nous avons dénombré toutes choses en écrit."},{"n":5702,"s":78,"a":30,"t":"Goûtez-donc. Nous n'augmenterons pour vous que le châtiment!"},{"n":5703,"s":78,"a":31,"t":"Pour les pieux ce sera une réussite:"},{"n":5704,"s":78,"a":32,"t":"jardins et vignes,"},{"n":5705,"s":78,"a":33,"t":"et des (belles) aux seins arrondis, d'une égale jeunesse,"},{"n":5706,"s":78,"a":34,"t":"et coupes débordantes."},{"n":5707,"s":78,"a":35,"t":"Ils n'y entendront ni futilités ni mensonges."},{"n":5708,"s":78,"a":36,"t":"A titre de récompense de ton Seigneur et à titre de don abondant"},{"n":5709,"s":78,"a":37,"t":"du Seigneur des cieux et de la terre et de ce qui existe entre eux, le Tout Miséricordieux; ils n'osent nullement Lui adresser la parole."},{"n":5710,"s":78,"a":38,"t":"Le jour où l'Esprit et les Anges se dresseront en rangs, nul ne saura parler, sauf celui à qui le Tout Miséricordieux aura accordé la permission, et qui dira la vérité."},{"n":5711,"s":78,"a":39,"t":"Ce jour-là est inéluctable. Que celui qui veut prenne donc refuge auprès de son Seigneur."},{"n":5712,"s":78,"a":40,"t":"Nous vous avons avertis d'un châtiment bien proche, le jour où l'homme verra ce que ses deux mains ont préparé; et l'infidèle dira: «Hélas pour moi! Comme j'aurais aimé n'être que poussière»."},{"n":5713,"s":79,"a":1,"t":"Par ceux qui arrachent violemment!"},{"n":5714,"s":79,"a":2,"t":"Et par ceux qui recueillent avec douceur!"},{"n":5715,"s":79,"a":3,"t":"Et par ceux qui voguent librement,"},{"n":5716,"s":79,"a":4,"t":"puis s'élancent à toute vitesse,"},{"n":5717,"s":79,"a":5,"t":"et règlent les affaires!"},{"n":5718,"s":79,"a":6,"t":"Le jour où [la terre] tremblera [au premier son du clairon]"},{"n":5719,"s":79,"a":7,"t":"immédiatement suivi du deuxième."},{"n":5720,"s":79,"a":8,"t":"Ce jour-là, il y aura des cœurs qui seront agités d'effroi,"},{"n":5721,"s":79,"a":9,"t":"et leurs regards se baisseront."},{"n":5722,"s":79,"a":10,"t":"Ils disent: «Quoi! Serons-nous ramenés à notre vie première,"},{"n":5723,"s":79,"a":11,"t":"quand nous serons ossements pourris?»"},{"n":5724,"s":79,"a":12,"t":"Ils disent: «ce sera alors un retour ruineux!»"},{"n":5725,"s":79,"a":13,"t":"Il n'y aura qu'une sommation,"},{"n":5726,"s":79,"a":14,"t":"et voilà qu'ils seront sur la terre (ressuscités)."},{"n":5727,"s":79,"a":15,"t":"Le récit de Moïse t'est-il parvenu?"},{"n":5728,"s":79,"a":16,"t":"Quand son Seigneur l'appela, dans Towâ, la vallée sanctifiée:"},{"n":5729,"s":79,"a":17,"t":"«Va vers Pharaon. Vraiment, il s'est rebellé!»"},{"n":5730,"s":79,"a":18,"t":"Puis dis-lui: «Voudrais-tu te purifier?"},{"n":5731,"s":79,"a":19,"t":"et que je te guide vers ton Seigneur afin que tu Le craignes?»"},{"n":5732,"s":79,"a":20,"t":"Il lui fit voir le très grand miracle."},{"n":5733,"s":79,"a":21,"t":"Mais il le qualifia de mensonge et désobéit;"},{"n":5734,"s":79,"a":22,"t":"Ensuite, il tourna le dos, s'en alla précipitamment,"},{"n":5735,"s":79,"a":23,"t":"rassembla [les gens] et leur fit une proclamation,"},{"n":5736,"s":79,"a":24,"t":"et dit: «C'est moi votre Seigneur, le très haut»."},{"n":5737,"s":79,"a":25,"t":"Alors Allah le saisit de la punition exemplaire de l'au-delà et de celle d'ici-bas."},{"n":5738,"s":79,"a":26,"t":"Il y a certes là un sujet de réflexion pour celui qui craint."},{"n":5739,"s":79,"a":27,"t":"Etes-vous plus durs à créer? ou le ciel, qu'Il a pourtant construit?"},{"n":5740,"s":79,"a":28,"t":"Il a élevé bien haut sa voûte, puis l'a parfaitement ordonné;"},{"n":5741,"s":79,"a":29,"t":"Il a assombri sa nuit et fait luire son jour."},{"n":5742,"s":79,"a":30,"t":"Et quant à la terre, après cela, Il l'a étendue:"},{"n":5743,"s":79,"a":31,"t":"Il a fait sortir d'elle son eau et son pâturage,"},{"n":5744,"s":79,"a":32,"t":"et quant aux montagnes, Il les a ancrées,"},{"n":5745,"s":79,"a":33,"t":"pour votre jouissance, vous et vos bestiaux."},{"n":5746,"s":79,"a":34,"t":"Puis quand viendra le grand cataclysme,"},{"n":5747,"s":79,"a":35,"t":"le jour où l'homme se rappellera à quoi il s'est efforcé,"},{"n":5748,"s":79,"a":36,"t":"l'Enfer sera pleinement visible à celui qui regardera..."},{"n":5749,"s":79,"a":37,"t":"Quant à celui qui aura dépassé les limites"},{"n":5750,"s":79,"a":38,"t":"et aura préféré la vie présente,"},{"n":5751,"s":79,"a":39,"t":"alors, l'Enfer sera son refuge..."},{"n":5752,"s":79,"a":40,"t":"Et pour celui qui aura redouté de comparaître devant son Seigneur, et préservé son âme de la passion,"},{"n":5753,"s":79,"a":41,"t":"le Paradis sera alors son refuge."},{"n":5754,"s":79,"a":42,"t":"Ils t'interrogent au sujet de l'Heure: «Quand va-t-elle jeter l'ancre?»"},{"n":5755,"s":79,"a":43,"t":"Quelle [science] en as-tu pour le leur dire?"},{"n":5756,"s":79,"a":44,"t":"Son terme n'est connu que de ton Seigneur."},{"n":5757,"s":79,"a":45,"t":"Tu n'es que l'avertisseur de celui qui la redoute."},{"n":5758,"s":79,"a":46,"t":"Le jour où ils la verront, il leur semblera n'avoir demeuré qu'un soir ou un matin."},{"n":5759,"s":80,"a":1,"t":"Il s'est renfrogné et il s'est détourné"},{"n":5760,"s":80,"a":2,"t":"parce que l'aveugle est venu à lui."},{"n":5761,"s":80,"a":3,"t":"Qui te dit: peut-être [cherche]-t-il à se purifier?"},{"n":5762,"s":80,"a":4,"t":"ou à se rappeler en sorte que le rappel lui profite?"},{"n":5763,"s":80,"a":5,"t":"Quant à celui qui se complaît dans sa suffisance (pour sa richesse)"},{"n":5764,"s":80,"a":6,"t":"tu vas avec empressement à sa rencontre."},{"n":5765,"s":80,"a":7,"t":"Or, que t'importe qu'il ne se purifie pas»."},{"n":5766,"s":80,"a":8,"t":"Et quant à celui qui vient à toi avec empressement"},{"n":5767,"s":80,"a":9,"t":"tout en ayant la crainte,"},{"n":5768,"s":80,"a":10,"t":"tu ne t'en soucies pas."},{"n":5769,"s":80,"a":11,"t":"N'agis plus ainsi! Vraiment ceci est un rappel -"},{"n":5770,"s":80,"a":12,"t":"quiconque veut, donc, s'en rappelle -"},{"n":5771,"s":80,"a":13,"t":"consigné dans des feuilles honorées,"},{"n":5772,"s":80,"a":14,"t":"élevées, purifiées,"},{"n":5773,"s":80,"a":15,"t":"entre les mains d'ambassadeurs"},{"n":5774,"s":80,"a":16,"t":"nobles, obéissants."},{"n":5775,"s":80,"a":17,"t":"Que périsse l'homme! Qu'il est ingrat!"},{"n":5776,"s":80,"a":18,"t":"De quoi [Allah] l'a-t-Il créé?"},{"n":5777,"s":80,"a":19,"t":"D'une goutte de sperme, Il le crée et détermine (son destin):"},{"n":5778,"s":80,"a":20,"t":"puis Il lui facilite le chemin;"},{"n":5779,"s":80,"a":21,"t":"puis Il lui donne la mort et le met au tombeau;"},{"n":5780,"s":80,"a":22,"t":"puis Il le ressuscitera quand Il voudra."},{"n":5781,"s":80,"a":23,"t":"Eh bien non! [L'homme] n'accomplit pas ce qu'Il lui commande."},{"n":5782,"s":80,"a":24,"t":"Que l'homme considère donc sa nourriture:"},{"n":5783,"s":80,"a":25,"t":"C'est Nous qui versons l'eau abondante,"},{"n":5784,"s":80,"a":26,"t":"puis Nous fendons la terre par fissures"},{"n":5785,"s":80,"a":27,"t":"et y faisons pousser grains,"},{"n":5786,"s":80,"a":28,"t":"vignobles et légumes,"},{"n":5787,"s":80,"a":29,"t":"oliviers et palmiers,"},{"n":5788,"s":80,"a":30,"t":"jardins touffus,"},{"n":5789,"s":80,"a":31,"t":"fruits et herbages,"},{"n":5790,"s":80,"a":32,"t":"pour votre jouissance vous et vos bestiaux."},{"n":5791,"s":80,"a":33,"t":"Puis quand viendra le Fracas,"},{"n":5792,"s":80,"a":34,"t":"le jour où l'homme s'enfuira de son frère,"},{"n":5793,"s":80,"a":35,"t":"de sa mère, de son père,"},{"n":5794,"s":80,"a":36,"t":"de sa compagne et de ses enfants,"},{"n":5795,"s":80,"a":37,"t":"car chacun d'eux, ce jour-là, aura son propre cas pour l'occuper."},{"n":5796,"s":80,"a":38,"t":"Ce jour-là, il y aura des visages rayonnants,"},{"n":5797,"s":80,"a":39,"t":"riants et réjouis."},{"n":5798,"s":80,"a":40,"t":"De même qu'il y aura, ce jour-là, des visages couverts de poussière,"},{"n":5799,"s":80,"a":41,"t":"recouverts de ténèbres."},{"n":5800,"s":80,"a":42,"t":"Voilà les infidèles, les libertins."},{"n":5801,"s":81,"a":1,"t":"Quand le soleil sera obscurci,"},{"n":5802,"s":81,"a":2,"t":"et que les étoiles deviendront ternes,"},{"n":5803,"s":81,"a":3,"t":"et les montagnes mises en marche,"},{"n":5804,"s":81,"a":4,"t":"et les chamelles à terme, négligées,"},{"n":5805,"s":81,"a":5,"t":"et les bêtes farouches, rassemblées,"},{"n":5806,"s":81,"a":6,"t":"et les mers allumées,"},{"n":5807,"s":81,"a":7,"t":"et les âmes accouplées"},{"n":5808,"s":81,"a":8,"t":"et qu'on demandera à la fillette enterrée vivante"},{"n":5809,"s":81,"a":9,"t":"pour quel péché elle a été tuée."},{"n":5810,"s":81,"a":10,"t":"Et quand les feuilles seront déployées,"},{"n":5811,"s":81,"a":11,"t":"et le ciel écorché"},{"n":5812,"s":81,"a":12,"t":"et la fournaise attisée,"},{"n":5813,"s":81,"a":13,"t":"et le Paradis rapproché,"},{"n":5814,"s":81,"a":14,"t":"chaque âme saura ce qu'elle a présenté."},{"n":5815,"s":81,"a":15,"t":"Non!... Je jure par les planètes qui gravitent"},{"n":5816,"s":81,"a":16,"t":"qui courent et disparaissent"},{"n":5817,"s":81,"a":17,"t":"par la nuit quand elle survient!"},{"n":5818,"s":81,"a":18,"t":"et par l'aube quand elle exhale son souffle!"},{"n":5819,"s":81,"a":19,"t":"Ceci [le Coran] est la parole d'un noble Messager,"},{"n":5820,"s":81,"a":20,"t":"doué d'une grande force, et ayant un rang élevé auprès du Maître du Trône,"},{"n":5821,"s":81,"a":21,"t":"obéi, là-haut, et digne de confiance."},{"n":5822,"s":81,"a":22,"t":"Votre compagnon (Muhammad) n'est nullement fou;"},{"n":5823,"s":81,"a":23,"t":"il l'a effectivement vu (Gabriel), au clair horizon"},{"n":5824,"s":81,"a":24,"t":"et il ne garde pas avarement pour lui-même ce qui lui a été révélé."},{"n":5825,"s":81,"a":25,"t":"Et ceci [le Coran] n'est point la parole d'un diable banni."},{"n":5826,"s":81,"a":26,"t":"Où allez-vous donc?"},{"n":5827,"s":81,"a":27,"t":"Ceci n'est qu'un rappel pour l'univers,"},{"n":5828,"s":81,"a":28,"t":"pour celui d'entre vous qui veut suivre le chemin droit."},{"n":5829,"s":81,"a":29,"t":"Mais vous ne pouvez vouloir, que si Allah veut, [Lui], le Seigneur de l'Univers ;"},{"n":5830,"s":82,"a":1,"t":"Quand le ciel se rompra,"},{"n":5831,"s":82,"a":2,"t":"et que les étoiles se disperseront,"},{"n":5832,"s":82,"a":3,"t":"et que les mers confondront leurs eaux,"},{"n":5833,"s":82,"a":4,"t":"et que les tombeaux seront bouleversés,"},{"n":5834,"s":82,"a":5,"t":"toute âme saura alors ce qu'elle a accompli et ce qu'elle a remis de faire à plus tard."},{"n":5835,"s":82,"a":6,"t":"O homme! Qu'est-ce qui t'a trompé au sujet de ton Seigneur, le Noble,"},{"n":5836,"s":82,"a":7,"t":"qui t'a créé, puis modelé et constitué harmonieusement?"},{"n":5837,"s":82,"a":8,"t":"Il t'a façonné dans la forme qu'Il a voulue."},{"n":5838,"s":82,"a":9,"t":"Non...! [malgré tout] vous traitez la Rétribution de mensonge;"},{"n":5839,"s":82,"a":10,"t":"alors que veillent sur vous des gardiens,"},{"n":5840,"s":82,"a":11,"t":"de nobles scribes,"},{"n":5841,"s":82,"a":12,"t":"qui savent ce que vous faites."},{"n":5842,"s":82,"a":13,"t":"Les bons seront, certes, dans un [jardin] de délice,"},{"n":5843,"s":82,"a":14,"t":"et les libertins seront, certes, dans une fournaise"},{"n":5844,"s":82,"a":15,"t":"où ils brûleront, le jour de la Rétribution"},{"n":5845,"s":82,"a":16,"t":"incapables de s'en échapper."},{"n":5846,"s":82,"a":17,"t":"Et qui te dira ce qu'est le jour de la Rétribution?"},{"n":5847,"s":82,"a":18,"t":"Encore une fois, qui te dira ce qu'est le jour de la Rétribution?"},{"n":5848,"s":82,"a":19,"t":"Le jour où aucune âme ne pourra rien en faveur d'une autre âme. Et ce jour-là, le commandement sera à Allah."},{"n":5849,"s":83,"a":1,"t":"Malheur aux fraudeurs"},{"n":5850,"s":83,"a":2,"t":"qui, lorsqu'ils font mesurer pour eux-mêmes exigent la pleine mesure,"},{"n":5851,"s":83,"a":3,"t":"et qui lorsqu'eux-mêmes mesurent ou pèsent pour les autres, [leur] causent perte."},{"n":5852,"s":83,"a":4,"t":"Ceux-là ne pensent-ils pas qu'ils seront ressuscités,"},{"n":5853,"s":83,"a":5,"t":"en un jour terrible,"},{"n":5854,"s":83,"a":6,"t":"le jour où les gens se tiendront debout devant le Seigneur de l'Univers?"},{"n":5855,"s":83,"a":7,"t":"Non...! Mais en vérité le livre des libertins sera dans le Sijjîn -"},{"n":5856,"s":83,"a":8,"t":"et qui te dira ce qu'est le Sijjîn? -"},{"n":5857,"s":83,"a":9,"t":"Un livre déjà cacheté (achevé)."},{"n":5858,"s":83,"a":10,"t":"Malheur, ce jour-là, aux négateurs,"},{"n":5859,"s":83,"a":11,"t":"qui démentent le jour de la Rétribution."},{"n":5860,"s":83,"a":12,"t":"Or, ne le dément que tout transgresseur, pécheur:"},{"n":5861,"s":83,"a":13,"t":"qui, lorsque Nos versets lui sont récités, dit: «[Ce sont] des contes d'anciens!»"},{"n":5862,"s":83,"a":14,"t":"Pas du tout, mais ce qu'ils ont accompli couvre leurs cœurs."},{"n":5863,"s":83,"a":15,"t":"Qu'ils prennent garde! En vérité ce jour-là un voile les empêchera de voir leur Seigneur,"},{"n":5864,"s":83,"a":16,"t":"ensuite, ils brûleront certes, dans la Fournaise;"},{"n":5865,"s":83,"a":17,"t":"on [leur] dira alors: «Voilà ce que vous traitiez de mensonge!»"},{"n":5866,"s":83,"a":18,"t":"Qu'ils prennent garde! Le livre des bons sera dans l'Illiyûn -"},{"n":5867,"s":83,"a":19,"t":"et qui te dira ce qu'est l'Illiyûn? -"},{"n":5868,"s":83,"a":20,"t":"un livre cacheté!"},{"n":5869,"s":83,"a":21,"t":"Les rapprochés [d'Allah: les Anges] en témoignent."},{"n":5870,"s":83,"a":22,"t":"Les bons seront dans [un Jardin] de délice,"},{"n":5871,"s":83,"a":23,"t":"sur les divans, ils regardent."},{"n":5872,"s":83,"a":24,"t":"Tu reconnaîtras sur leurs visages, l'éclat de la félicité."},{"n":5873,"s":83,"a":25,"t":"On leur sert à boire un nectar pur, cacheté,"},{"n":5874,"s":83,"a":26,"t":"laissant un arrière-goût de musc. Que ceux qui la convoitent entrent en compétition [pour l'acquérir]"},{"n":5875,"s":83,"a":27,"t":"Il est mélangé à la boisson de Tasnîm,"},{"n":5876,"s":83,"a":28,"t":"source dont les rapprochés boivent."},{"n":5877,"s":83,"a":29,"t":"Les criminels riaient de ceux qui croyaient,"},{"n":5878,"s":83,"a":30,"t":"et, passant près d'eux, ils se faisaient des œillades,"},{"n":5879,"s":83,"a":31,"t":"et, retournant dans leurs familles, ils retournaient en plaisantant,"},{"n":5880,"s":83,"a":32,"t":"et les voyant, ils disaient: «Ce sont vraiment ceux-là les égarés»."},{"n":5881,"s":83,"a":33,"t":"Or, ils n'ont pas été envoyés pour être leurs gardiens."},{"n":5882,"s":83,"a":34,"t":"Aujourd'hui, donc, ce sont ceux qui ont cru qui rient des infidèles"},{"n":5883,"s":83,"a":35,"t":"sur les divans, ils regardent."},{"n":5884,"s":83,"a":36,"t":"Est-ce que les infidèles ont eu la récompense de ce qu'ils faisaient?"},{"n":5885,"s":84,"a":1,"t":"Quand le ciel se déchirera"},{"n":5886,"s":84,"a":2,"t":"et obéira à son Seigneur - et fera ce qu'il doit faire -"},{"n":5887,"s":84,"a":3,"t":"et que la terre sera nivelée,"},{"n":5888,"s":84,"a":4,"t":"et qu'elle rejettera ce qui est en son sein (les morts) et se videra,"},{"n":5889,"s":84,"a":5,"t":"et qu'elle obéira à son Seigneur - et fera ce qu'elle doit faire -"},{"n":5890,"s":84,"a":6,"t":"O homme! Toi qui t'efforces vers ton Seigneur sans relâche, tu Le rencontreras alors."},{"n":5891,"s":84,"a":7,"t":"Celui qui recevra son livre en sa main droite,"},{"n":5892,"s":84,"a":8,"t":"sera soumis à un jugement facile,"},{"n":5893,"s":84,"a":9,"t":"et retournera réjoui auprès de sa famille"},{"n":5894,"s":84,"a":10,"t":"Quant à celui qui recevra son livre derrière son dos,"},{"n":5895,"s":84,"a":11,"t":"il invoquera la destruction sur lui-même,"},{"n":5896,"s":84,"a":12,"t":"et il brûlera dans un feu ardent."},{"n":5897,"s":84,"a":13,"t":"Car il était tout joyeux parmi les siens,"},{"n":5898,"s":84,"a":14,"t":"et il pensait que jamais il ne ressusciterait"},{"n":5899,"s":84,"a":15,"t":"Mais si! Certes, son Seigneur l'observait parfaitement."},{"n":5900,"s":84,"a":16,"t":"Non!... Je jure par le crépuscule,"},{"n":5901,"s":84,"a":17,"t":"et par la nuit et ce qu'elle enveloppe,"},{"n":5902,"s":84,"a":18,"t":"et par la lune quand elle devient pleine lune!"},{"n":5903,"s":84,"a":19,"t":"Vous passerez, certes, par des états successifs!"},{"n":5904,"s":84,"a":20,"t":"Qu'ont-ils à ne pas croire?"},{"n":5905,"s":84,"a":21,"t":"et à ne pas se prosterner quand le Coran leur est lu?"},{"n":5906,"s":84,"a":22,"t":"Mais ceux qui ne croient pas, le traitent plutôt de mensonge."},{"n":5907,"s":84,"a":23,"t":"Or, Allah sait bien ce qu'ils dissimulent."},{"n":5908,"s":84,"a":24,"t":"Annonce-leur donc un châtiment douloureux."},{"n":5909,"s":84,"a":25,"t":"Sauf ceux qui croient et accomplissent les bonnes œuvres: à eux une récompense jamais interrompue."},{"n":5910,"s":85,"a":1,"t":"Par le ciel aux constellations!"},{"n":5911,"s":85,"a":2,"t":"et par le jour promis!"},{"n":5912,"s":85,"a":3,"t":"et par le témoin et ce dont on témoigne!"},{"n":5913,"s":85,"a":4,"t":"Périssent les gens de l'Uhdûd,"},{"n":5914,"s":85,"a":5,"t":"par le feu plein de combustible,"},{"n":5915,"s":85,"a":6,"t":"cependant qu'ils étaient assis tout autour,"},{"n":5916,"s":85,"a":7,"t":"ils étaient ainsi témoins de ce qu'ils faisaient des croyants,"},{"n":5917,"s":85,"a":8,"t":"à qui ils ne leur reprochaient que d'avoir cru en Allah, le Puissant, le Digne de louange,"},{"n":5918,"s":85,"a":9,"t":"Auquel appartient la royauté des cieux et de la terre. Allah est témoin de toute chose."},{"n":5919,"s":85,"a":10,"t":"Ceux qui font subir des épreuves aux croyants et aux croyantes, puis ne se repentent pas, auront le châtiment de l'Enfer et le supplice du feu."},{"n":5920,"s":85,"a":11,"t":"Ceux qui croient et accomplissent les bonnes œuvres auront des Jardins sous lesquels coulent les ruisseaux. Cela est le grand succès."},{"n":5921,"s":85,"a":12,"t":"La riposte de ton Seigneur est redoutable."},{"n":5922,"s":85,"a":13,"t":"C'est Lui, certes, qui commence (la création) et la refait."},{"n":5923,"s":85,"a":14,"t":"Et c'est Lui le Pardonneur, le Tout-Affectueux,"},{"n":5924,"s":85,"a":15,"t":"Le Maître du Trône, le Tout-Glorieux,"},{"n":5925,"s":85,"a":16,"t":"Il réalise parfaitement tout ce qu'Il veut."},{"n":5926,"s":85,"a":17,"t":"T'est-il parvenu le récit des armées,"},{"n":5927,"s":85,"a":18,"t":"de Pharaon, et de Thamûd?"},{"n":5928,"s":85,"a":19,"t":"Mais ceux qui ne croient pas persistent à démentir,"},{"n":5929,"s":85,"a":20,"t":"alors qu'Allah, derrière eux, les cerne de toutes parts."},{"n":5930,"s":85,"a":21,"t":"Mais c'est plutôt un Coran glorifié"},{"n":5931,"s":85,"a":22,"t":"préservé sur une Tablette (auprès d'Allah)."},{"n":5932,"s":86,"a":1,"t":"Par le ciel et par l'astre nocturne"},{"n":5933,"s":86,"a":2,"t":"Et qui te dira ce qu'est l'astre nocturne?"},{"n":5934,"s":86,"a":3,"t":"C'est l'étoile vivement brillante."},{"n":5935,"s":86,"a":4,"t":"Il n'est pas d'âme qui n'ait sur elle un gardien."},{"n":5936,"s":86,"a":5,"t":"Que l'homme considère donc de quoi il a été créé."},{"n":5937,"s":86,"a":6,"t":"Il a été créé d'une giclée d'eau"},{"n":5938,"s":86,"a":7,"t":"sortie d'entre les lombes et les côtes."},{"n":5939,"s":86,"a":8,"t":"Allah est certes capable de le ressusciter."},{"n":5940,"s":86,"a":9,"t":"Le jour où les cœurs dévoileront leurs secrets,"},{"n":5941,"s":86,"a":10,"t":"Il n'aura alors ni force ni secoureur."},{"n":5942,"s":86,"a":11,"t":"Par le ciel qui fait revenir la pluie!"},{"n":5943,"s":86,"a":12,"t":"et par la terre qui se fend!"},{"n":5944,"s":86,"a":13,"t":"Ceci [le Coran] est certes, une parole décisive [qui tranche entre le vrai et le faux],"},{"n":5945,"s":86,"a":14,"t":"et non point une plaisanterie frivole!"},{"n":5946,"s":86,"a":15,"t":"Ils se servent d'une ruse,"},{"n":5947,"s":86,"a":16,"t":"et Moi aussi Je me sers de Mon plan."},{"n":5948,"s":86,"a":17,"t":"Accorde (ô Prophète) donc un délai aux infidèles: accorde-leur un court délai."},{"n":5949,"s":87,"a":1,"t":"Glorifie le nom de ton Seigneur, le Très Haut,"},{"n":5950,"s":87,"a":2,"t":"Celui Qui a créé et agencé harmonieusement,"},{"n":5951,"s":87,"a":3,"t":"qui a décrété et guidé,"},{"n":5952,"s":87,"a":4,"t":"et qui a fait pousser le pâturage,"},{"n":5953,"s":87,"a":5,"t":"et en a fait ensuite un foin sombre."},{"n":5954,"s":87,"a":6,"t":"Nous te ferons réciter (le Coran), de sorte que tu n'oublieras"},{"n":5955,"s":87,"a":7,"t":"que ce qu'Allah veut. Car, Il connaît ce qui paraît au grand jour ainsi que ce qui est caché."},{"n":5956,"s":87,"a":8,"t":"Nous te mettrons sur la voie la plus facile."},{"n":5957,"s":87,"a":9,"t":"Rappelle, donc, où le Rappel doit être utile."},{"n":5958,"s":87,"a":10,"t":"Quiconque craint (Allah) s'[en] rappellera,"},{"n":5959,"s":87,"a":11,"t":"et s'en écartera le grand malheureux,"},{"n":5960,"s":87,"a":12,"t":"qui brûlera dans le plus grand Feu,"},{"n":5961,"s":87,"a":13,"t":"où il ne mourra ni ne vivra."},{"n":5962,"s":87,"a":14,"t":"Réussit, certes, celui qui se purifie,"},{"n":5963,"s":87,"a":15,"t":"et se rappelle le nom de son Seigneur, puis célèbre la Salât."},{"n":5964,"s":87,"a":16,"t":"Mais, vous préférez plutôt la vie présente,"},{"n":5965,"s":87,"a":17,"t":"alors que l'au-delà est meilleur et plus durable."},{"n":5966,"s":87,"a":18,"t":"Ceci se trouve, certes, dans les Feuilles anciennes,"},{"n":5967,"s":87,"a":19,"t":"les Feuilles d'Abraham et de Moïse."},{"n":5968,"s":88,"a":1,"t":"T'est-il parvenu le récit de l'enveloppante?"},{"n":5969,"s":88,"a":2,"t":"Ce jour-là, il y aura des visages humiliés,"},{"n":5970,"s":88,"a":3,"t":"préoccupés, harassés."},{"n":5971,"s":88,"a":4,"t":"Ils brûleront dans un Feu ardent,"},{"n":5972,"s":88,"a":5,"t":"et seront abreuvés d'une source bouillante."},{"n":5973,"s":88,"a":6,"t":"Il n'y aura pour eux d'autre nourriture que des plantes épineuses [darî'],"},{"n":5974,"s":88,"a":7,"t":"qui n'engraisse, ni n'apaise la faim."},{"n":5975,"s":88,"a":8,"t":"Ce jour-là, il y aura des visages épanouis,"},{"n":5976,"s":88,"a":9,"t":"contents de leurs efforts,"},{"n":5977,"s":88,"a":10,"t":"dans un haut Jardin,"},{"n":5978,"s":88,"a":11,"t":"où ils n'entendent aucune futilité."},{"n":5979,"s":88,"a":12,"t":"Là, il y aura une source coulante."},{"n":5980,"s":88,"a":13,"t":"Là, des divans élevés"},{"n":5981,"s":88,"a":14,"t":"et des coupes posées"},{"n":5982,"s":88,"a":15,"t":"et des coussins rangés"},{"n":5983,"s":88,"a":16,"t":"et des tapis étalés."},{"n":5984,"s":88,"a":17,"t":"Ne considèrent-ils donc pas les chameaux, comment ils ont été créés,"},{"n":5985,"s":88,"a":18,"t":"et le ciel comment il est élevé,"},{"n":5986,"s":88,"a":19,"t":"et les montagnes comment elles sont dressées"},{"n":5987,"s":88,"a":20,"t":"et la terre comment elle est nivelée?"},{"n":5988,"s":88,"a":21,"t":"Eh bien, rappelle! Tu n'es qu'un rappeleur,"},{"n":5989,"s":88,"a":22,"t":"et tu n'es pas un dominateur sur eux."},{"n":5990,"s":88,"a":23,"t":"Sauf celui qui tourne le dos et ne croit pas,"},{"n":5991,"s":88,"a":24,"t":"alors Allah le châtiera du plus grand châtiment."},{"n":5992,"s":88,"a":25,"t":"Vers Nous est leur retour."},{"n":5993,"s":88,"a":26,"t":"Ensuite, c'est à Nous de leur demander compte."},{"n":5994,"s":89,"a":1,"t":"Par l'Aube!"},{"n":5995,"s":89,"a":2,"t":"Et par les dix nuits!"},{"n":5996,"s":89,"a":3,"t":"Par le pair et l'impair!"},{"n":5997,"s":89,"a":4,"t":"Et par la nuit quand elle s'écoule!"},{"n":5998,"s":89,"a":5,"t":"N'est-ce pas là un serment, pour un doué d'intelligence?"},{"n":5999,"s":89,"a":6,"t":"N'as-tu pas vu comment ton Seigneur a agi avec les 'Aad"},{"n":6000,"s":89,"a":7,"t":"[avec] Iram, [la cité] à la colonne remarquable,"},{"n":6001,"s":89,"a":8,"t":"dont jamais pareille ne fut construite parmi les villes?"},{"n":6002,"s":89,"a":9,"t":"et avec les Thamûd qui taillaient le rocher dans la vallée?"},{"n":6003,"s":89,"a":10,"t":"ainsi qu'avec Pharaon, l'homme aux épieux?"},{"n":6004,"s":89,"a":11,"t":"Tous, étaient des gens qui transgressaient dans [leurs] pays,"},{"n":6005,"s":89,"a":12,"t":"et y avaient commis beaucoup de désordre."},{"n":6006,"s":89,"a":13,"t":"Donc, ton Seigneur déversa sur eux un fouet du châtiment."},{"n":6007,"s":89,"a":14,"t":"Car ton Seigneur demeure aux aguets."},{"n":6008,"s":89,"a":15,"t":"Quant à l'homme, lorsque son Seigneur l'éprouve en l'honorant et en le comblant de bienfaits, il dit: «Mon Seigneur m'a honoré»."},{"n":6009,"s":89,"a":16,"t":"Mais par contre, quand Il l'éprouve en lui restreignant sa subsistance, il dit: «Mon Seigneur m'a avili»."},{"n":6010,"s":89,"a":17,"t":"Mais non! C'est vous plutôt, qui n'êtes pas généreux envers les orphelins;"},{"n":6011,"s":89,"a":18,"t":"qui ne vous incitez pas mutuellement à nourrir le pauvre,"},{"n":6012,"s":89,"a":19,"t":"qui dévorez l'héritage avec une avidité vorace,"},{"n":6013,"s":89,"a":20,"t":"et aimez les richesses d'un amour sans bornes."},{"n":6014,"s":89,"a":21,"t":"Prenez garde! Quand la terre sera complètement pulvérisée,"},{"n":6015,"s":89,"a":22,"t":"et que ton Seigneur viendra ainsi que les Anges, rang par rang,"},{"n":6016,"s":89,"a":23,"t":"et que ce jour-là, on amènera l'Enfer; ce jour-là, l'homme se rappellera. Mais à quoi lui servira de se souvenir?"},{"n":6017,"s":89,"a":24,"t":"Il dira: «Hélas! Que n'ai-je fait du bien pour ma vie future!"},{"n":6018,"s":89,"a":25,"t":"Ce jour-là donc, nul ne saura châtier comme Lui châtie,"},{"n":6019,"s":89,"a":26,"t":"et nul ne saura garrotter comme Lui garrotte."},{"n":6020,"s":89,"a":27,"t":"«O toi, âme apaisée,"},{"n":6021,"s":89,"a":28,"t":"retourne vers ton Seigneur, satisfaite et agréée;"},{"n":6022,"s":89,"a":29,"t":"entre donc parmi Mes serviteurs,"},{"n":6023,"s":89,"a":30,"t":"et entre dans Mon Paradis»."},{"n":6024,"s":90,"a":1,"t":"Non!... Je jure par cette Cité!"},{"n":6025,"s":90,"a":2,"t":"et toi, tu es un résident dans cette cité -"},{"n":6026,"s":90,"a":3,"t":"Et par le père et ce qu'il engendre!"},{"n":6027,"s":90,"a":4,"t":"Nous avons, certes, créé l'homme pour une vie de lutte."},{"n":6028,"s":90,"a":5,"t":"Pense-t-il que personne ne pourra rien contre lui?"},{"n":6029,"s":90,"a":6,"t":"Il dit: «J'ai gaspillé beaucoup de biens»."},{"n":6030,"s":90,"a":7,"t":"Pense-t-il que nul ne l'a vu?"},{"n":6031,"s":90,"a":8,"t":"Ne lui avons Nous pas assigné deux yeux,"},{"n":6032,"s":90,"a":9,"t":"et une langue et deux lèvres?"},{"n":6033,"s":90,"a":10,"t":"Ne l'avons-Nous pas guidé aux deux voies."},{"n":6034,"s":90,"a":11,"t":"Or, il ne s'engage pas dans la voie difficile!"},{"n":6035,"s":90,"a":12,"t":"Et qui te dira ce qu'est la voie difficile?"},{"n":6036,"s":90,"a":13,"t":"C'est délier un joug [affranchir un esclave],"},{"n":6037,"s":90,"a":14,"t":"ou nourrir, en un jour de famine,"},{"n":6038,"s":90,"a":15,"t":"un orphelin proche parent"},{"n":6039,"s":90,"a":16,"t":"ou un pauvre dans le dénuement."},{"n":6040,"s":90,"a":17,"t":"Et c'est être, en outre, de ceux qui croient et s'enjoignent mutuellement l'endurance, et s'enjoignent mutuellement la miséricorde."},{"n":6041,"s":90,"a":18,"t":"Ceux-là sont les gens de la droite;"},{"n":6042,"s":90,"a":19,"t":"alors que ceux qui ne croient pas en Nos versets sont les gens de la gauche."},{"n":6043,"s":90,"a":20,"t":"Le Feu se refermera sur eux."},{"n":6044,"s":91,"a":1,"t":"Par le soleil et par sa clarté!"},{"n":6045,"s":91,"a":2,"t":"Et par la lune quand elle le suit!"},{"n":6046,"s":91,"a":3,"t":"Et par le jour quand il l'éclaire!"},{"n":6047,"s":91,"a":4,"t":"Et par la nuit quand elle l'enveloppe!"},{"n":6048,"s":91,"a":5,"t":"Et par le ciel et Celui qui l'a construit!"},{"n":6049,"s":91,"a":6,"t":"Et par la terre et Celui qui l'a étendue!"},{"n":6050,"s":91,"a":7,"t":"Et par l'âme et Celui qui l'a harmonieusement façonnée;"},{"n":6051,"s":91,"a":8,"t":"et lui a alors inspiré son immoralité, de même que sa piété!"},{"n":6052,"s":91,"a":9,"t":"A réussi, certes, celui qui la purifie."},{"n":6053,"s":91,"a":10,"t":"Et est perdu, certes, celui qui la corrompt."},{"n":6054,"s":91,"a":11,"t":"Les Thamûd, par leur transgression, ont crié au mensonge,"},{"n":6055,"s":91,"a":12,"t":"lorsque le plus misérable d'entre eux se leva (pour tuer la chamelle)"},{"n":6056,"s":91,"a":13,"t":"Le Messager d'Allah leur avait dit: «La chamelle d'Allah! Laissez-la boire."},{"n":6057,"s":91,"a":14,"t":"Mais, ils le traitèrent de menteur, et la tuèrent. Leur Seigneur les détruisit donc, pour leur péché et étendit Son châtiment sur tous."},{"n":6058,"s":91,"a":15,"t":"Et Allah n'a aucune crainte des conséquences."},{"n":6059,"s":92,"a":1,"t":"Par la nuit quand elle enveloppe tout!"},{"n":6060,"s":92,"a":2,"t":"Par le jour quand il éclaire!"},{"n":6061,"s":92,"a":3,"t":"Et par ce qu'Il a créé, mâle et femelle!"},{"n":6062,"s":92,"a":4,"t":"Vos efforts sont divergents."},{"n":6063,"s":92,"a":5,"t":"Celui qui donne et craint (Allah)"},{"n":6064,"s":92,"a":6,"t":"et déclare véridique la plus belle récompense"},{"n":6065,"s":92,"a":7,"t":"Nous lui faciliterons la voie au plus grand bonheur."},{"n":6066,"s":92,"a":8,"t":"Et quant à celui qui est avare, se dispense (de l'adoration d'Allah),"},{"n":6067,"s":92,"a":9,"t":"et traite de mensonge la plus belle récompense,"},{"n":6068,"s":92,"a":10,"t":"Nous lui faciliterons la voie à la plus grande difficulté,"},{"n":6069,"s":92,"a":11,"t":"et à rien ne lui serviront ses richesses quand il sera jeté (au Feu)."},{"n":6070,"s":92,"a":12,"t":"C'est à Nous, certes, de guider;"},{"n":6071,"s":92,"a":13,"t":"à Nous appartient, certes, la vie dernière et la vie présente."},{"n":6072,"s":92,"a":14,"t":"Je vous ai donc avertis d'un Feu qui flambe"},{"n":6073,"s":92,"a":15,"t":"où ne brûlera que le damné,"},{"n":6074,"s":92,"a":16,"t":"qui dément et tourne le dos;"},{"n":6075,"s":92,"a":17,"t":"alors qu'en sera écarté le pieux,"},{"n":6076,"s":92,"a":18,"t":"qui donne ses biens pour se purifier"},{"n":6077,"s":92,"a":19,"t":"et auprès de qui personne ne profite d'un bienfait intéressé,"},{"n":6078,"s":92,"a":20,"t":"mais seulement pour la recherche de La Face de son Seigneur le Très Haut."},{"n":6079,"s":92,"a":21,"t":"Et certes, il sera bientôt satisfait!"},{"n":6080,"s":93,"a":1,"t":"Par le Jour Montant!"},{"n":6081,"s":93,"a":2,"t":"Et par la nuit quand elle couvre tout!"},{"n":6082,"s":93,"a":3,"t":"Ton Seigneur ne t'a ni abandonné, ni détesté."},{"n":6083,"s":93,"a":4,"t":"La vie dernière t'est, certes, meilleure que la vie présente."},{"n":6084,"s":93,"a":5,"t":"Ton Seigneur t'accordera certes [Ses faveurs], et alors tu seras satisfait."},{"n":6085,"s":93,"a":6,"t":"Ne t'a-t-Il pas trouvé orphelin? Alors Il t'a accueilli!"},{"n":6086,"s":93,"a":7,"t":"Ne t'a-t-Il pas trouvé égaré? Alors Il t'a guidé."},{"n":6087,"s":93,"a":8,"t":"Ne t'a-t-Il pas trouvé pauvre? Alors Il t'a enrichi."},{"n":6088,"s":93,"a":9,"t":"Quant à l'orphelin, donc, ne le maltraite pas."},{"n":6089,"s":93,"a":10,"t":"Quant au demandeur, ne le repousse pas."},{"n":6090,"s":93,"a":11,"t":"Et quant au bienfait de ton Seigneur, proclame-le."},{"n":6091,"s":94,"a":1,"t":"N'avons-Nous pas ouvert pour toi ta poitrine?"},{"n":6092,"s":94,"a":2,"t":"Et ne t'avons-Nous pas déchargé du fardeau"},{"n":6093,"s":94,"a":3,"t":"qui accablait ton dos?"},{"n":6094,"s":94,"a":4,"t":"Et exalté pour toi ta renommée?"},{"n":6095,"s":94,"a":5,"t":"A côté de la difficulté est, certes, une facilité!"},{"n":6096,"s":94,"a":6,"t":"A côté de la difficulté est, certes, une facilité!"},{"n":6097,"s":94,"a":7,"t":"Quand tu te libères, donc, lève-toi,"},{"n":6098,"s":94,"a":8,"t":"et à ton Seigneur aspire."},{"n":6099,"s":95,"a":1,"t":"Par le figuier et l'olivier!"},{"n":6100,"s":95,"a":2,"t":"Et par le Mont Sînîn!"},{"n":6101,"s":95,"a":3,"t":"Et par cette Cité sûre!"},{"n":6102,"s":95,"a":4,"t":"Nous avons certes créé l'homme dans la forme la plus parfaite."},{"n":6103,"s":95,"a":5,"t":"Ensuite, Nous l'avons ramené au niveau le plus bas,"},{"n":6104,"s":95,"a":6,"t":"sauf ceux qui croient et accomplissent les bonnes œuvres: ceux-là auront une récompense jamais interrompue."},{"n":6105,"s":95,"a":7,"t":"Après cela, qu'est-ce qui te fait traiter la rétribution de mensonge?"},{"n":6106,"s":95,"a":8,"t":"Allah n'est-Il pas le plus sage des Juges?"},{"n":6107,"s":96,"a":1,"t":"Lis, au nom de ton Seigneur qui a créé,"},{"n":6108,"s":96,"a":2,"t":"qui a créé l'homme d'une adhérence."},{"n":6109,"s":96,"a":3,"t":"Lis! Ton Seigneur est le Très Noble,"},{"n":6110,"s":96,"a":4,"t":"qui a enseigné par la plume [le calame],"},{"n":6111,"s":96,"a":5,"t":"a enseigné à l'homme ce qu'il ne savait pas."},{"n":6112,"s":96,"a":6,"t":"Prenez-garde! Vraiment l'homme devient rebelle,"},{"n":6113,"s":96,"a":7,"t":"dès qu'il estime qu'il peut se suffire à lui-même (à cause de sa richesse)."},{"n":6114,"s":96,"a":8,"t":"Mais, c'est vers ton Seigneur qu'est le retour."},{"n":6115,"s":96,"a":9,"t":"As-tu vu celui qui interdit"},{"n":6116,"s":96,"a":10,"t":"à un serviteur d'Allah [Muhammad] de célébrer la Salât?"},{"n":6117,"s":96,"a":11,"t":"Vois-tu s'il est sur la bonne voie,"},{"n":6118,"s":96,"a":12,"t":"ou s'il ordonne la piété?"},{"n":6119,"s":96,"a":13,"t":"Vois-tu s'il dément et tourne le dos?"},{"n":6120,"s":96,"a":14,"t":"Ne sait-il pas que vraiment Allah voit?"},{"n":6121,"s":96,"a":15,"t":"Mais non! S'il ne cesse pas, Nous le saisirons certes, par le toupet,"},{"n":6122,"s":96,"a":16,"t":"le toupet d'un menteur, d'un pécheur."},{"n":6123,"s":96,"a":17,"t":"Qu'il appelle donc son assemblée."},{"n":6124,"s":96,"a":18,"t":"Nous appellerons les gardiens [de l'Enfer]."},{"n":6125,"s":96,"a":19,"t":"Non! Ne lui obéis pas; mais prosterne-toi et rapproche-toi."},{"n":6126,"s":97,"a":1,"t":"Nous l'avons certes, fait descendre (le Coran) pendant la nuit d'Al-Qadr."},{"n":6127,"s":97,"a":2,"t":"Et qui te dira ce qu'est la nuit d'Al-Qadr?"},{"n":6128,"s":97,"a":3,"t":"La nuit d'Al-Qadr est meilleure que mille mois."},{"n":6129,"s":97,"a":4,"t":"Durant celle-ci descendent les Anges ainsi que l'Esprit, par permission de leur Seigneur pour tout ordre."},{"n":6130,"s":97,"a":5,"t":"Elle est paix et salut jusqu'à l'apparition de l'aube."},{"n":6131,"s":98,"a":1,"t":"Les infidèles parmi les gens du Livre, ainsi que les Associateurs, ne cesseront pas de mécroire jusqu'à ce que leur vienne la Preuve évidente:"},{"n":6132,"s":98,"a":2,"t":"un Messager, de la part d'Allah, qui leur récite des feuilles purifiées,"},{"n":6133,"s":98,"a":3,"t":"dans lesquelles se trouvent des prescriptions d'une rectitude parfaite."},{"n":6134,"s":98,"a":4,"t":"Et ceux à qui le Livre a été donné ne se sont divisés qu'après que la preuve leur fut venue."},{"n":6135,"s":98,"a":5,"t":"Il ne leur a été commandé, cependant, que d'adorer Allah, Lui vouant un culte exclusif, d'accomplir la Salât et d'acquitter la Zakât. Et voilà la religion de droiture."},{"n":6136,"s":98,"a":6,"t":"Les infidèles parmi les gens du Livre, ainsi que les Associateurs iront au feu de l'Enfer, pour y demeurer éternellement. De toute la création, ce sont eux les pires."},{"n":6137,"s":98,"a":7,"t":"Quant à ceux qui croient et accomplissent les bonnes œuvres, ce sont les meilleurs de toute la création."},{"n":6138,"s":98,"a":8,"t":"Leur récompense auprès d'Allah sera les Jardins de séjour, sous lesquels coulent les ruisseaux, pour y demeurer éternellement. Allah les agrée et ils L'agréent. Telle sera [la récompense] de celui qui craint son Seigneur."},{"n":6139,"s":99,"a":1,"t":"Quand la terre tremblera d'un violent tremblement,"},{"n":6140,"s":99,"a":2,"t":"et que la terre fera sortir ses fardeaux,"},{"n":6141,"s":99,"a":3,"t":"et que l'homme dira: «Qu'a-t-elle?»"},{"n":6142,"s":99,"a":4,"t":"ce jour-là, elle contera son histoire,"},{"n":6143,"s":99,"a":5,"t":"selon ce que ton Seigneur lui aura révélé [ordonné]."},{"n":6144,"s":99,"a":6,"t":"Ce jour-là, les gens sortiront séparément pour que leur soient montrées leurs œuvres."},{"n":6145,"s":99,"a":7,"t":"Quiconque fait un bien fût-ce du poids d'un atome, le verra,"},{"n":6146,"s":99,"a":8,"t":"et quiconque fait un mal fût-ce du poids d'un atome, le verra."},{"n":6147,"s":100,"a":1,"t":"Par les coursiers qui halètent,"},{"n":6148,"s":100,"a":2,"t":"qui font jaillir des étincelles,"},{"n":6149,"s":100,"a":3,"t":"qui attaquent au matin,"},{"n":6150,"s":100,"a":4,"t":"et font ainsi voler la poussière,"},{"n":6151,"s":100,"a":5,"t":"et pénètrent au centre de la troupe ennemie."},{"n":6152,"s":100,"a":6,"t":"L'homme est, certes, ingrat envers son Seigneur;"},{"n":6153,"s":100,"a":7,"t":"et pourtant, il est certes, témoin de cela;"},{"n":6154,"s":100,"a":8,"t":"et pour l'amour des richesses il est certes ardent."},{"n":6155,"s":100,"a":9,"t":"Ne sait-il donc pas que lorsque ce qui est dans les tombes sera bouleversé,"},{"n":6156,"s":100,"a":10,"t":"et que sera dévoilé ce qui est dans les poitrines,"},{"n":6157,"s":100,"a":11,"t":"ce jour-là, certes, leur Seigneur sera Parfaitement Connaisseur d'eux?"},{"n":6158,"s":101,"a":1,"t":"Le fracas!"},{"n":6159,"s":101,"a":2,"t":"Qu'est-ce que le fracas?"},{"n":6160,"s":101,"a":3,"t":"Et qui te dira ce qu'est le fracas?"},{"n":6161,"s":101,"a":4,"t":"C'est le jour où les gens seront comme des papillons éparpillés,"},{"n":6162,"s":101,"a":5,"t":"et les montagnes comme de la laine cardée;"},{"n":6163,"s":101,"a":6,"t":"quant à celui dont la balance sera lourde"},{"n":6164,"s":101,"a":7,"t":"il sera dans une vie agréable;"},{"n":6165,"s":101,"a":8,"t":"et quant à celui dont la balance sera légère,"},{"n":6166,"s":101,"a":9,"t":"sa mère [destination] est un abîme très profond."},{"n":6167,"s":101,"a":10,"t":"Et qui te dira ce que c'est?"},{"n":6168,"s":101,"a":11,"t":"C'est un Feu ardent."},{"n":6169,"s":102,"a":1,"t":"La course aux richesses vous distrait,"},{"n":6170,"s":102,"a":2,"t":"jusqu'à ce que vous visitiez les tombes."},{"n":6171,"s":102,"a":3,"t":"Mais non! Vous saurez bientôt!"},{"n":6172,"s":102,"a":4,"t":"(Encore une fois)! Vous saurez bientôt!"},{"n":6173,"s":102,"a":5,"t":"Sûrement! Si vous saviez de science certaine."},{"n":6174,"s":102,"a":6,"t":"Vous verrez, certes, la Fournaise."},{"n":6175,"s":102,"a":7,"t":"Puis, vous la verrez certes, avec l'œil de la certitude."},{"n":6176,"s":102,"a":8,"t":"Puis, assurément, vous serez interrogés, ce jour-là, sur les délices."},{"n":6177,"s":103,"a":1,"t":"Par le Temps!"},{"n":6178,"s":103,"a":2,"t":"L'homme est certes, en perdition,"},{"n":6179,"s":103,"a":3,"t":"sauf ceux qui croient et accomplissent les bonnes œuvres, s'enjoignent mutuellement la vérité et s'enjoignent mutuellement l'endurance."},{"n":6180,"s":104,"a":1,"t":"Malheur à tout calomniateur diffamateur,"},{"n":6181,"s":104,"a":2,"t":"qui amasse une fortune et la compte,"},{"n":6182,"s":104,"a":3,"t":"pensant que sa fortune l'immortalisera."},{"n":6183,"s":104,"a":4,"t":"Mais non! Il sera certes, jeté dans la Hutamah."},{"n":6184,"s":104,"a":5,"t":"Et qui te dira ce qu'est la Hutamah?"},{"n":6185,"s":104,"a":6,"t":"Le Feu attisé d'Allah"},{"n":6186,"s":104,"a":7,"t":"qui monte jusqu'aux cœurs."},{"n":6187,"s":104,"a":8,"t":"Il se refermera sur eux,"},{"n":6188,"s":104,"a":9,"t":"en colonnes (de flammes) étendues."},{"n":6189,"s":105,"a":1,"t":"N'as-tu pas vu comment ton Seigneur a agi envers les gens de l'Eléphant?"},{"n":6190,"s":105,"a":2,"t":"N'a-t-Il pas rendu leur ruse complètement vaine?"},{"n":6191,"s":105,"a":3,"t":"et envoyé sur eux des oiseaux par volées"},{"n":6192,"s":105,"a":4,"t":"qui leur lançaient des pierres d'argile?"},{"n":6193,"s":105,"a":5,"t":"Et Il les a rendus semblables à une paille mâchée."},{"n":6194,"s":106,"a":1,"t":"A cause du pacte des Coraïch,"},{"n":6195,"s":106,"a":2,"t":"De leur pacte [concernant] les voyages d'hiver et d'été."},{"n":6196,"s":106,"a":3,"t":"Qu'ils adorent donc le Seigneur de cette Maison [la Ka'ba],"},{"n":6197,"s":106,"a":4,"t":"qui les a nourris contre la faim et rassurés de la crainte!"},{"n":6198,"s":107,"a":1,"t":"Vois-tu celui qui traite de mensonge la Rétribution?"},{"n":6199,"s":107,"a":2,"t":"C'est bien lui qui repousse l'orphelin,"},{"n":6200,"s":107,"a":3,"t":"et qui n'encourage point à nourrir le pauvre."},{"n":6201,"s":107,"a":4,"t":"Malheur donc, à ceux qui prient"},{"n":6202,"s":107,"a":5,"t":"tout en négligeant (et retardant) leur Salât,"},{"n":6203,"s":107,"a":6,"t":"qui sont pleins d'ostentation,"},{"n":6204,"s":107,"a":7,"t":"et refusent l'ustensile (à celui qui en a besoin)."},{"n":6205,"s":108,"a":1,"t":"Nous t'avons certes, accordé l'Abondance."},{"n":6206,"s":108,"a":2,"t":"Accomplis la Salât pour ton Seigneur et sacrifie."},{"n":6207,"s":108,"a":3,"t":"Celui qui te hait sera certes, sans postérité."},{"n":6208,"s":109,"a":1,"t":"Dis: «O vous les infidèles!"},{"n":6209,"s":109,"a":2,"t":"Je n'adore pas ce que vous adorez."},{"n":6210,"s":109,"a":3,"t":"Et vous n'êtes pas adorateurs de ce que j'adore."},{"n":6211,"s":109,"a":4,"t":"Je ne suis pas adorateur de ce que vous adorez."},{"n":6212,"s":109,"a":5,"t":"Et vous n'êtes pas adorateurs de ce que j'adore."},{"n":6213,"s":109,"a":6,"t":"A vous votre religion, et à moi ma religion»."},{"n":6214,"s":110,"a":1,"t":"Lorsque vient le secours d'Allah ainsi que la victoire,"},{"n":6215,"s":110,"a":2,"t":"et que tu vois les gens entrer en foule dans la religion d'Allah,"},{"n":6216,"s":110,"a":3,"t":"alors, par la louange, célèbre la gloire de ton Seigneur et implore Son pardon. Car c'est Lui le grand Accueillant au repentir."},{"n":6217,"s":111,"a":1,"t":"Que périssent les deux mains d'Abû-Lahab et que lui-même périsse."},{"n":6218,"s":111,"a":2,"t":"Sa fortune ne lui sert à rien, ni ce qu'il a acquis."},{"n":6219,"s":111,"a":3,"t":"Il sera brûlé dans un Feu plein de flammes,"},{"n":6220,"s":111,"a":4,"t":"de même sa femme, la porteuse de bois,"},{"n":6221,"s":111,"a":5,"t":"à son cou, une corde de fibres."},{"n":6222,"s":112,"a":1,"t":"Dis: «Il est Allah, Unique."},{"n":6223,"s":112,"a":2,"t":"Allah, Le Seul à être imploré pour ce que nous désirons."},{"n":6224,"s":112,"a":3,"t":"Il n'a jamais engendré, n'a pas été engendré non plus."},{"n":6225,"s":112,"a":4,"t":"Et nul n'est égal à Lui»."},{"n":6226,"s":113,"a":1,"t":"Dis: «Je cherche protection auprès du Seigneur de l'aube naissante,"},{"n":6227,"s":113,"a":2,"t":"contre le mal des êtres qu'Il a créés,"},{"n":6228,"s":113,"a":3,"t":"contre le mal de l'obscurité quand elle s'approfondit,"},{"n":6229,"s":113,"a":4,"t":"contre le mal de celles qui soufflent [les sorcières] sur les nœuds,"},{"n":6230,"s":113,"a":5,"t":"et contre le mal de l'envieux quand il envie»."},{"n":6231,"s":114,"a":1,"t":"Dis: «Je cherche protection auprès du Seigneur des hommes."},{"n":6232,"s":114,"a":2,"t":"Le Souverain des hommes,"},{"n":6233,"s":114,"a":3,"t":"Dieu des hommes,"},{"n":6234,"s":114,"a":4,"t":"contre le mal du mauvais conseiller, furtif,"},{"n":6235,"s":114,"a":5,"t":"qui souffle le mal dans les poitrines des hommes,"},{"n":6236,"s":114,"a":6,"t":"qu'il (le conseiller) soit un djinn, ou un être humain»."}]};